[11208] = { ["id"] = 11208, ["name"] = "Delivery for Drazzit", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 11208 }, ["series"] = { 27348 }, ["description"] = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket? If you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve .", ["objectivesText"] = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket. Progress: Yes?", ["rewardXP"] = 260, ["rewardItems"] = { 33163 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 23797, ["x"] = 0.535, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 23572, ["x"] = 0.422, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard" },
[14127] = { ["id"] = 14127, ["name"] = "Return of the Highborne?", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 14127 }, ["series"] = { 14128 }, ["description"] = "The wax seal on these orders has been freshly broken. You can't read the carefully-penned night elven script, but a small hand-drawn map indicates the nearby ruins. Underneath the map, written in a different language entirely, are a series of runes penned in a metallic, shimmering ink. Ag'tor will no doubt want to see this important piece of intelligence.", ["objectivesText"] = "Deliver the Scout's Orders to Ag'tor Bloodfist at the rear gate to Orgrimmar. Progress: You found something on one of the bodies, you say? Give it here!", ["rewardGold"] = 280900, ["rewardXP"] = 555, ["rewardItems"] = { 47039, 47040 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 8576, ["x"] = 0.268, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 47039 } },
[14428] = { ["id"] = 14428, ["name"] = "Amberwind's Journal", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 14428 }, ["series"] = { 14429, 14430 }, ["description"] = "If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her. With a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.", ["objectivesText"] = "Slay Lorekeeper Amberwind at the Darnassian Base Camp and retrieve her journal. Progress: <Andorel's distorted face appears within the scrying stone.> <name>, have you made contact? What can you tell me?", ["rewardXP"] = 740, ["rewardItems"] = { 49356 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 36596, ["x"] = 0.425, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard" },
[14429] = { ["id"] = 14429, ["name"] = "Arcane De-Construction", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["storyline"] = { 14429 }, ["series"] = { 14428, 14430 }, ["description"] = "Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, <name>. So intelligent! So powerful! So very vulnerable to external tampering... Let's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.", ["objectivesText"] = "Slay Apprentice Investigators and Apprentice Illuminators to collect 10 Attuned Runestones . Progress: <Andorel's image is blurry and indistinct. He squints at you and taps against the glass of the scrying stone.> <name>, is that you? The resolution on this stone is terrible. What kind of hardware are they using?", ["rewardXP"] = 740, ["rewardItems"] = { 49359 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard" },
[25218] = { ["id"] = 25218, ["name"] = "Undersea Inflation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["series"] = { 25216, 25217, 25359, 25456 }, ["description"] = "Fine! Fine. You argued me into it. You can help. I'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench. I brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too. I bet the crabs snatched it up... pinchy, greedy little things.", ["objectivesText"] = "Fill one of Sambino's Air Balloons and find his Lost Air Valve. Progress: If only air weren't so darn floaty! Or if only those water breathing spells came with stylish helmets! Either would do nicely.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 54608, 54611, 54614, 55171, 55186, 62281 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 39882, ["x"] = 0.642, ["y"] = 0.347 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 39882, ["x"] = 0.642, ["y"] = 0.347 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.347 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 205, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 54, ["flags"] = 0 } } },
[25234] = { ["id"] = 25234, ["name"] = "In the Rear With the Gear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25234 }, ["description"] = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better. Kill the slave drivers along the road to our south and nearby slaves should make a break for it. Search the packs they leave behind for anything valuable, and destroy anything you can't carry.", ["objectivesText"] = "Collect 36 Twilight Supplies left behind from freed Twilight Slaves. Progress: Have you created some havoc down there, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 52568, 57383, 57384, 57385 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39427, ["x"] = 0.316, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39427, ["x"] = 0.316, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
