[25390] = { ["id"] = 25390, ["name"] = "A Girl's Best Friend", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["description"] = "Let's just get it out in the open. I'm no stranger to love, <name>. Over the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion. I've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go. At least I used to... When I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", ["objectivesText"] = "Adarrah wants you to recover 6 Adarrah's Keepsakes . Progress: Well, <race>? Were you able to recover my valuables?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 47500, 53053, 53074, 54345, 54639, 55186, 59792, 59793, 59794 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39883, ["x"] = 0.57, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 201, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 26, ["flags"] = 0 } } },
[25408] = { ["id"] = 25408, ["name"] = "Seeds of Their Demise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25404, 25411, 25412, 25428, 25443 }, ["description"] = "We will decimate the Twilight's Hammer by corrupting and subverting them. Seeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower. My little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", ["objectivesText"] = "Collect 8 Bileberries . Progress: Has the local flora been giving you a hard time? <Blackhorn grins disturbingly.>", ["rewardXP"] = 4115, ["rewardItems"] = { 53102, 57323, 57324, 57325 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.413, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 43, ["flags"] = 0 } } },
[25428] = { ["id"] = 25428, ["name"] = "Black Heart of Flame", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25404, 25408, 25411, 25412, 25443 }, ["description"] = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him. The ritual is simple: take this charred branch , tap it on the ground three times, and utter his name aloud. You must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", ["objectivesText"] = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar . Progress: Tell me! Have you fought Thol'embaar yet? I am living vicariously through you, <race>. Do not disappoint!", ["rewardXP"] = 4115, ["rewardItems"] = { 53454, 53464, 57320, 57321, 57322, 60223, 60975, 65661, 65662, 67145 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39933, ["x"] = 0.413, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.413, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 47, ["flags"] = 0 } } },
[25472] = { ["id"] = 25472, ["name"] = "The Flameseer's Staff", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25323, 25464 }, ["description"] = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces. It was an ancient bone staff that granted its wielder power over the elements of fire. Its fragments litter the area around us. Find them and bring them to Malfurion. Perhaps the artifact's power will still be of use.", ["objectivesText"] = "Obtain 8 Bone Staff Fragments. Progress: Yes, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 54461 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39869, ["x"] = 0.476, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39857, ["x"] = 0.476, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[25491] = { ["id"] = 25491, ["name"] = "Durable Seeds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25491 }, ["series"] = { 25382, 25462, 25490, 25940 }, ["description"] = "This land has been scourged by fire, but it may yet renew itself. Some seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", ["objectivesText"] = "Gather 10 Hyjal Seedlings from piles of Scorched Soil. Progress: I suspect life still struggles beneath the ash. What were you able to find?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 54574, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.5015 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[25493] = { ["id"] = 25493, ["name"] = "Fresh Bait", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25507, 25510 }, ["description"] = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake. Freeing Tortolla from his bonds will not be easy. But we will take it one step at a time. Head into the Flamewake and collect for me heaps of core hound entrails . I will explain why later. And beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", ["objectivesText"] = "Collect 4 heaps of Core Hound Entrails . Progress: Have you collected the innards? Core hounds are not native to this part of the world, they accompanied Twilight's Hammer from the nether regions of the earth. Do not trouble yourself over their elimination.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 54609, 57351, 57352, 57353, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.5015 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 51, ["flags"] = 0 } } },
[25494] = { ["id"] = 25494, ["name"] = "A Champion's Collar", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25294 }, ["description"] = "This little guy is a true menace now, isn't he? We're going to have to give him a nice spiked collar if he's going to be a fighting pup. The basilisk matriarch has made her lair off of the road to Winterspring. Bring me her spiked hide and we'll fashion a collar for our little killer here.", ["objectivesText"] = "Obtain the Spiked Basilisk Hide from the Spinescale Matriarch. Progress: Did you get it?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 54610 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39406, ["x"] = 0.683333, ["y"] = 0.447333 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39406, ["x"] = 0.683333, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.447333 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 97, ["flags"] = 0 } } },
[25507] = { ["id"] = 25507, ["name"] = "Hell's Shells", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25493, 25510 }, ["description"] = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer. Nemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient. Go into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", ["objectivesText"] = "Use the Heap of Core Hound Innards near Nemesis to distract him. Collect a Nemesis Shell Fragment . Progress: Nemesis is a molten ball of fury protected by a stony shell of pure hatred. His time will come.", ["rewardGold"] = 295000, ["rewardXP"] = 4115, ["rewardItems"] = { 54744, 54745, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 39858, ["x"] = 0.233, ["y"] = 0.5015 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.233, ["y"] = 0.5015 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 52, ["flags"] = 0 } } },
[25599] = { ["id"] = 25599, ["name"] = "Cindermaul, the Portal Master", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25600 }, ["description"] = "Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed. Find for me the Tome of Openings , used by the elementals to open gates between the planes. Cindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...", ["objectivesText"] = "Slay Cindermaul and locate the Tome of Openings . Progress: The tome! Have you found it?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 55136 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 40834, ["x"] = 0.262, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 40834, ["x"] = 0.262, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 35, ["flags"] = 0 } } },
[25602] = { ["id"] = 25602, ["name"] = "Can't Start a Fire Without a Spark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["description"] = "Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going. There's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own. Would you mind hauling it back for us? For Mack?", ["objectivesText"] = "Get the Keg of Gunpowder from Budd's Dig. Progress: Did you get the explosives from the camp, <class>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55143, 55186 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 39884, ["x"] = 0.572, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 39884, ["x"] = 0.572, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 201, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 27, ["flags"] = 0 } } },
[25656] = { ["id"] = 25656, ["name"] = "Scrambling for Eggs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25655, 25731 }, ["description"] = "There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal. These animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.", ["objectivesText"] = "Gather 8 Hyjal Eggs . Progress: <Thisalee is cleaning her nails with a dagger. She looks up at you expectantly.>", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 55189, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 59, ["flags"] = 0 } } },
[25664] = { ["id"] = 25664, ["name"] = "A Prayer and a Wing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25663, 25665, 25985, 27874 }, ["description"] = "A winged visage? Could it be...? <name>, there's no time to waste. You may have been speaking to Aviana herself, trying to return to us. I'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief. Go to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.", ["objectivesText"] = "Use the Enormous Bird Call at one of Blaithe's Nests perched atop the Rim of the World. Kill Blaithe and gather one of his Ancient Feathers . Progress: Don't trouble yourself over Blaithe's condition. Grief robbed that creature of a soul epochs ago. He was but a shell of his former self, a beast of pure rage.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 44338, 44339, 44340, 44341, 55210, 55211, 57339, 57340, 57341, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41005, ["x"] = 0.444, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 61, ["flags"] = 0 } } },
[25732] = { ["id"] = 25732, ["name"] = "A Bone to Pick", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4815, ["mapID"] = 201, ["storyline"] = { 14482, 24432, 25164, 25216, 25217, 25218, 25221, 25222, 25281, 25334, 25357, 25371, 25389, 25390, 25405, 25439, 25440, 25456, 25459, 25471, 25477, 25535, 25537, 25538, 25539, 25540, 25545, 25546, 25547, 25558, 25564, 25579, 25580, 25581, 25582, 25583, 25587, 25593, 25594, 25595, 25598, 25602, 25619, 25620, 25626, 25629, 25637, 25638, 25651, 25657, 25658, 25659, 25670, 25732, 25743, 25747, 25748, 25749, 25751, 25752, 25753, 25754, 25755, 25760, 25794, 25812, 25824, 25858, 25859, 25860, 25862, 25863, 25884, 25885, 25887, 25888, 25890, 25892, 25893, 25894, 25895, 25896, 25897, 25898, 25900, 25907, 25908, 25909, 25911, 25916, 25917, 25918, 25919, 25920, 25921, 25922, 25924, 25929, 25936, 25941, 25942, 25943, 25944, 25946, 25947, 25948, 25949, 25951, 25952, 25953, 25954, 25955, 25956, 25957, 25958, 25959, 25960, 25962, 25963, 25964, 25965, 25966, 25967, 25968, 25969, 25970, 25971, 25972, 25973, 25989, 25990, 25991, 25992, 25993, 25994, 25995, 25996, 26000, 26005, 26006, 26007, 26008, 26040, 26135, 26191, 26219, 26221, 27699, 27708 }, ["series"] = { 25651, 25657, 25670, 25743, 27699 }, ["description"] = "We did it! Gnaws is down, and I have our shiney! That's good news. Darn shiney is cursed treasure - makes everyone who touches it a skeleton. That's bad news. These cursed pirates say the Gilblin King has the secret to remove the hex. That's good news. I can't step foot outside the reef or I'll be cursed forever. That's bad news.", ["objectivesText"] = "Budd wants you to collect the Pewter Pounder from King Gurboggle at Gurboggle's Ledge. Progress: So, <race>... You gunna remove this curse, or what?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55186, 55805 }, ["starts"] = { { ["mapID"] = 201, ["npcID"] = 46458, ["x"] = 0.584, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 201, ["npcID"] = 46458, ["x"] = 0.584, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 201, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 201 }, ["zone"] = { 4815 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 201, ["questLines"] = { { ["id"] = 539, ["name"] = "Vashj'ir, Kelp'thar Forest & Shimmering Expanse", ["orderIndex"] = 34, ["flags"] = 0 } } },
[25758] = { ["id"] = 25758, ["name"] = "A Gap in Their Armor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25761 }, ["description"] = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose. Those Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating! Run out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", ["objectivesText"] = "Gather 8 Twilight Armor Plates . Progress: Did you get a hold of some plates? Did you have to kill anyone to get them? I hope so.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 55809, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 63, ["flags"] = 0 } } },
[25761] = { ["id"] = 25761, ["name"] = "Disassembly", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25758 }, ["description"] = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath. Take my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor. Once they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", ["objectivesText"] = "Use Thisalee's Shiv to awaken and kill 3 Twilight Juggernauts . The shiv can be used multiple times to tear down a Juggernaut's armor. Progress: Oh good. You're still alive.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 55883, 57312, 57313, 57314, 57315, 65661, 65662, 211279 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 64, ["flags"] = 0 } } },
[25776] = { ["id"] = 25776, ["name"] = "Sethria's Demise", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25795, 25807 }, ["description"] = "While you've been raiding Sethria 's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself. Everyone agreed to my plan... provided YOU spearhead the attack. Take this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", ["objectivesText"] = "Slay the dragon Sethria . Once she reveals her true form, you will need to use the signal rocket to call in reinforcements! Progress: If a minor dragon like Sethria can cause us so many problems, I hate to see what else Twilight's Hammer has in store...", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 56003 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41006, ["x"] = 0.375, ["y"] = 0.581 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.581 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 68, ["flags"] = 0 } } },
[25904] = { ["id"] = 25904, ["name"] = "The Hammer and the Key", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 25223, 25224, 25233, 25255, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25276, 25277, 25278, 25291, 25294, 25296, 25297, 25298, 25299, 25300, 25301, 25303, 25308, 25309, 25310, 25311, 25312, 25314, 25315, 25317, 25320, 25321, 25323, 25324, 25325, 25328, 25330, 25332, 25353, 25355, 25372, 25382, 25385, 25392, 25404, 25408, 25411, 25412, 25424, 25428, 25430, 25443, 25462, 25464, 25472, 25490, 25493, 25494, 25496, 25499, 25507, 25509, 25510, 25514, 25519, 25520, 25523, 25525, 25531, 25544, 25548, 25549, 25550, 25551, 25552, 25553, 25554, 25555, 25560, 25575, 25576, 25577, 25578, 25584, 25597, 25599, 25600, 25601, 25608, 25611, 25612, 25644, 25653, 25655, 25656, 25663, 25664, 25731, 25740, 25746, 25758, 25761, 25763, 25764, 25776, 25795, 25807, 25810, 25830, 25832, 25842, 25904, 25906, 25915, 25923, 25928, 29066 }, ["series"] = { 25843, 25906, 25910 }, ["description"] = "My Nemesis. Still lives. The servants of fire still come. We must pursue. Into their den. The ogres know the way. Slay the Field Captains. Recover the Glyph of Opening . This is the way.", ["objectivesText"] = "Kill a Twilight Field Captain and recover the Glyph of Opening . Progress: The glyph. Show it to me.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 56177, 65661, 65662 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 41504, ["x"] = 0.419, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 41504, ["x"] = 0.419, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.419, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 542, ["name"] = "Mount Hyjal", ["orderIndex"] = 80, ["flags"] = 0 } } },
[26096] = { ["id"] = 26096, ["name"] = "Scalding Shrooms", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["description"] = "We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it. Down below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.", ["objectivesText"] = "Collect 5 Scalding Shrooms . Progress: I heard that you had an unpleasant encounter with putting one of the demons on your head. I can assure you that they are now all quite dead.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 56571, 56810, 57102 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41639, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41639, ["x"] = 0.503, ["y"] = 0.5805 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 204, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 29, ["flags"] = 0 } } },
[26111] = { ["id"] = 26111, ["name"] = "... It Will Come", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26072, 26130, 26140 }, ["description"] = "I now imbue you with the energies of the corrupting faceless. Swim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader. Call forth to Ick'thys the Unfathomable... it will come!", ["objectivesText"] = "Obtain the Brain of the Unfathomable . Progress: Do you have it, <name>? With the Unfathomable's brain, we still may yet be able to communicate with L'ghorek, the dying ancient one in front of us.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 56822, 59617, 59618, 59619, 68833 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 204, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 30, ["flags"] = 0 } } },
[26140] = { ["id"] = 26140, ["name"] = "Communing with the Ancient", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26072, 26111, 26130 }, ["description"] = "Place the dead merciless one upon your head to pose as one of their slaves. Enter L'ghorek . Commune with the ancient.", ["objectivesText"] = "Deliver the Brain of the Unfathomable to L'ghorek in the Cerebrillum inside of L'ghorek in Vashj'ir. Progress: I SENSE... SOMETHING. COME CLOSER....", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 53048, 56822 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 41600, ["x"] = 0.503, ["y"] = 0.5805 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.5805 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 204, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 34, ["flags"] = 0 } } },
[26141] = { ["id"] = 26141, ["name"] = "Runestones of Binding", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5145, ["mapID"] = 204, ["storyline"] = { 25950, 25974, 25975, 25976, 25977, 25980, 25981, 25982, 25987, 25988, 26014, 26015, 26017, 26018, 26019, 26021, 26072, 26080, 26086, 26087, 26088, 26089, 26090, 26091, 26092, 26096, 26103, 26106, 26111, 26122, 26126, 26130, 26132, 26133, 26140, 26141, 26142, 26143, 26144, 26149, 26154, 26193, 26194 }, ["series"] = { 26142, 26143, 26154 }, ["description"] = "ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION. WE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.", ["objectivesText"] = "Collect 7 Runestones of Binding . Progress: DO... YOU HAVE... ALL THAT IS... REQUIRED?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 56571, 57096, 57102 }, ["starts"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["ends"] = { { ["mapID"] = 204, ["npcID"] = 42197, ["x"] = 0.385, ["y"] = 0.449 } }, ["coords"] = { ["mapID"] = 204, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.449 }, ["mapCandidates"] = { ["npc"] = { 204 }, ["zone"] = { 5145 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 204, ["questLines"] = { { ["id"] = 541, ["name"] = "Vashj'ir, Abyssal Depths", ["orderIndex"] = 35, ["flags"] = 0 } } },
[26259] = { ["id"] = 26259, ["name"] = "Blood of the Earthwarder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["description"] = "When Deathwing escaped to Deepholm , his corruption was extreme, but perhaps not yet absolute. The cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power. What if a trace of the Earthwarder's essence remains? After all, Neltharion was the aspect of earth before he was the aspect of death. Gather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", ["objectivesText"] = "Gather 5 samples of Blood of Neltharion from Living Blood at Deathwing's Fall. Progress: You return, <name>. Did you obtain the blood?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 41611, 55699, 59062, 61490, 61491, 61492 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43397, ["x"] = 0.495333, ["y"] = 0.523333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.523333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 44, ["flags"] = 0 } } },
[26296] = { ["id"] = 26296, ["name"] = "Evidence Collection", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["mapID"] = 52, ["storyline"] = { 26296 }, ["description"] = "The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert .", ["objectivesText"] = "Collect 6 Red Bandanas . Progress: Red bandanas ?!", ["rewardXP"] = 740, ["rewardItems"] = { 58117, 58118, 58921, 58922, 58923, 131505 }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 42425, ["x"] = 0.42, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 40 } }, ["questType"] = "standard", ["startItems"] = { 58117 } },
[26354] = { ["id"] = 26354, ["name"] = "Captain Sanders' Hidden Treasure", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["storyline"] = { 26354 }, ["series"] = { 26353, 26355, 26356 }, ["description"] = "The clue to the treasure reads: Good work, matey! Now ye need to head due east. East up the bluffs, east to the road. Look for the ol' chimney ruins near the side of the road. There you'll find an old barrel with your next clue.", ["objectivesText"] = "Find the old barrel near the ruined chimney and search it for your next clue. Progress: This looks like the right barrel.", ["rewardGold"] = 280900, ["rewardXP"] = 370, ["rewardItems"] = { 1358, 2842, 3342, 3343 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[26355] = { ["id"] = 26355, ["name"] = "Captain Sanders' Hidden Treasure", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["storyline"] = { 26355 }, ["series"] = { 26353, 26354, 26356 }, ["description"] = "Searching through the barrel you discover another piece of parchment. This one reads: Now from this here barrel, face ye North. Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs. If ye poke around that jug , ye just might find what you're lookin' for.", ["objectivesText"] = "Search the empty jug next to the windmill for the next clue. Progress: There's a clue sticking out of the empty jug .", ["rewardGold"] = 280900, ["rewardXP"] = 370, ["rewardItems"] = { 1361, 2842, 3342, 3343 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[26410] = { ["id"] = 26410, ["name"] = "Explosive Bonding Compound", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26411, 26413, 26484, 27135, 27931 }, ["description"] = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count! We know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment? My heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", ["objectivesText"] = "Collect 5 Quartzite Resin . Progress: It won't take much resin. Those rock flayers are pretty dangerous though.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 58501 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 1, ["flags"] = 0 } } },
[26427] = { ["id"] = 26427, ["name"] = "Without a Captain or Crew", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26249 }, ["description"] = "Not sure who you're with, but you don't look like one of... them. I'm not sure what happened. I slept through supper and woke up to a ship full of dead people and murderers. Not sure if you want to kill me or not, but I'll spare you the trouble. <Moody points to a wound in his stomach. His insides are not where they should be.> I can keep steering the ship for a while longer. You don't die from a gut wound immediately. Just bring me some rope and some rum... no, whiskey.", ["objectivesText"] = "Bring First Mate Moody a Bottle of Whiskey and a Spool of Rope . Progress: You have what I asked for?", ["rewardGold"] = 232300, ["rewardXP"] = 3085, ["rewardItems"] = { 58798, 58806, 61484, 61495, 61500 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43082, ["x"] = 0.62815, ["y"] = 0.45905 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43082, ["x"] = 0.62815, ["y"] = 0.45905 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.62815, ["y"] = 0.45905 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 38, ["flags"] = 0 } } },
[26437] = { ["id"] = 26437, ["name"] = "Making Things Crystal Clear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26312, 26313, 26314, 26315, 26326, 26328, 26375, 26376, 26377, 26426, 26436, 26437, 26438, 26439, 26440, 26441, 26507, 26575, 26576, 26577, 26578, 26579, 26580, 26581, 26582, 26583, 26584, 26585, 26656, 26657, 26658, 26659, 26750, 26752, 26827, 26828, 26829, 26831, 26832, 26833, 26869, 26871, 26875, 26971 }, ["description"] = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us. I do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself. Bring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", ["objectivesText"] = "Collect 8 Chalky Crystal Formations . Progress: Have you done this favor that I asked of you? Did you bring the crystals?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 58845 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 544, ["name"] = "Deepholm, The Stone Throne", ["orderIndex"] = 13, ["flags"] = 0 } } },
[26502] = { ["id"] = 26502, ["name"] = "Thunder Stones", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26500, 26564 }, ["description"] = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening. Go into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults. When you have enough, take them to Clay Mudaxle . Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", ["objectivesText"] = "Collect 12 Thunder Stones . Progress: <The older Earthen has cracks where the others do not, clearly ancient.> What are you supposed to be? Some kind of fleshy mistake? Cursed is what you are! <Clay spits dust.> Make yourself useful or get off of my front!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 58886 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43160, ["x"] = 0.282, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43169, ["x"] = 0.246, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 15, ["flags"] = 0 } } },
[26507] = { ["id"] = 26507, ["name"] = "Petrified Delicacies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26312, 26313, 26314, 26315, 26326, 26328, 26375, 26376, 26377, 26426, 26436, 26437, 26438, 26439, 26440, 26441, 26507, 26575, 26576, 26577, 26578, 26579, 26580, 26581, 26582, 26583, 26584, 26585, 26656, 26657, 26658, 26659, 26750, 26752, 26827, 26828, 26829, 26831, 26832, 26833, 26869, 26871, 26875, 26971 }, ["description"] = "Petrified bats. Elementals of that size are picky. You're not likely to find anything better easily. To the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory. I must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", ["objectivesText"] = "Gather 12 Petrified Stone Bats for Pebble . Progress: < Pebble starts to look up at you, eyes glowing faintly, growing rounder and larger every moment.>", ["rewardXP"] = 4115, ["rewardItems"] = { 58959 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 544, ["name"] = "Deepholm, The Stone Throne", ["orderIndex"] = 18, ["flags"] = 0 } } },
[26625] = { ["id"] = 26625, ["name"] = "Troggzor the Earthinator", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26499, 26501, 26537, 27932, 27933, 27934, 27935, 27936 }, ["description"] = "You have to put an end to this now! Go back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", ["objectivesText"] = "Obtain the Earthinator's Cudgel . Progress: Is he dead? Do you have the cudgel?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 59144, 61457, 61458, 61459 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43168, ["x"] = 0.245, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43168, ["x"] = 0.245, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 19, ["flags"] = 0 } } },
[26766] = { ["id"] = 26766, ["name"] = "Big Game, Big Bait", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26768, 26771, 26857, 26876 }, ["description"] = "We're only going to get one shot at capturing Abyssion, <name>. Let's make it count. We'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf. To lure the stone matriarch, we're going to need to gather sufficient bait. Take this knife and carve 5 sides of basilisk meat. That ought to be enough even for her appetite.", ["objectivesText"] = "Use Mylra's Knife to obtain 5 Sides of Basilisk Meat from dead Jadecrest Basilisks. Progress: Did you obtain the meat?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 0, 60297, 60382 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.821 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 52, ["flags"] = 0 } } },
[27135] = { ["id"] = 27135, ["name"] = "Something that Burns", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26410, 26411, 26413, 26484, 27931 }, ["description"] = "Alright, we need something that's going to make the compound go, \"Boom\"! I'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental! Here, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", ["objectivesText"] = "Obtain the Burning Heart . Progress: You have the heart yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60834, 60837 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42574, ["x"] = 0.465, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 2, ["flags"] = 0 } } },
