[27928] = { ["id"] = 27928, ["name"] = "A Favor for the Furrier", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27926, 27941, 28132, 29809 }, ["description"] = "The commander can be most generous to those who demonstrate their loyalty, and I know of something that you can do to curry favor with him. Before building up his... ehh... workforce, he dealt in the furs of animals. He is quite skilled in the art of leatherworking. The furrier can do wonders with even the most tattered pelts. The dried oasis to the east is said to be home to a rare breed of coyote. Their furs would make a very thoughtful gift.", ["objectivesText"] = "Collect 5 Desert Coyote Pelts . Progress: Were you successful in your hunt?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62776, 65865, 65866, 65867 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["