[27938] = { ["id"] = 27938, ["name"] = "The Middle Fragment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26791, 26792, 26835, 26836, 27937 }, ["description"] = "I present you with the key to Stonehearth. With it you may unlock the vault to my home and recover the middle fragment of the World Pillar . Keep the fragment safe, <name>. Make certain to get it to the Temple of Earth in the middle of Deepholm as quickly as possible! Know that you are always welcome here.", ["objectivesText"] = "Recover the Middle Fragment of the World Pillar . Progress: You've returned. Did you recover the middle fragment?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 60575, 61395, 61396, 61397 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44204, ["x"] = 0.279, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42573, ["x"] = 0.495333, ["y"] = 0.533333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.279, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 31, ["flags"] = 0 } } },
[27941] = { ["id"] = 27941, ["name"] = "Fashionism", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27926, 27928, 28132, 29809 }, ["description"] = "We have a strict policy among our ranks, one that we take most seriously. Our troops are to dress in official uniform at all times. This helps with organization, friendly fire incidents are reduced, and it keeps the troops looking wonderful! We call it, Fashionism. We've been running low on uniforms lately. I must ask that you recover them from the troopers that have fallen in the line of duty. You should find plenty of the poor fellows east of here, at the Ruins of Ammon.", ["objectivesText"] = "Belloc Brightblade wants you to collect 10 Trooper Uniforms . Progress: Were you able to recover the uniforms we need?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62789, 65858, 65859, 65860 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47670, ["x"] = 0.244, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.244, [