[27942] = { ["id"] = 27942, ["name"] = "Idolatry", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27939, 27943, 27950 }, ["description"] = "Zhere is somezhink I need handled, <race>. My most trusted advisor has run afoul of an ancient curse. A hex zhat has transformed zhe man into a turkey, of all zhings! I haff studied for days to discover a remedy for his condition, and finally I am ready to conduct zhe ritual. I vill reqvire several idols from zhe nearby ruins. You are to brink zhem to me at vonce! Dismissed!", ["objectivesText"] = "Commander Schnottz wants you to collect 8 Well-preserved Idols . Progress: Haff you brought me zhe idols, <race>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 25568, 25569, 25570, 62792 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.811 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2P