[27943] = { ["id"] = 27943, ["name"] = "Angered Spirits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27939, 27942, 27950 }, ["description"] = "Doctor Venkman vas vone of my greatest researchers, until he had to be put out of my misery. He did leave me vizh vone of his greatest accomplishments, zhough. Against zhe properly attuned supernatural adversary, zhis veapon vill siphon zhe target's essence. It is of key importance in zhe ritual I vill be attemptink. Vhere do you come in, you ask? Simple. You have zhe priviledge of collecting zhe material. Zhe veapon is calibrated to vork on zhe Furious Specters in zhe temple to zhe east.", ["objectivesText"] = "Commander Schnottz wants you to use the L.P.A.C. to collect 5 Furious Spectral Essences . Progress: Vell, little man? Vere you successful?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 7734, 10507, 18588, 62793, 62794, 77589, 86570, 124382, 137663 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47159, ["x"] = 0.488, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.811 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 69, ["flags"] = 0 } } },
[28105] = { ["id"] = 28105, ["name"] = "Kavem the Callous", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "Kavem was cruel enough before the Neferset signed up with Deathwing. His pleasure in deriving pain now borders on the insane. It is he who now holds the keys to our shackles. He dwells in the building next to us, to my right. Find him and take the key from him. Do not hesitate or show him mercy. He will slit your throat and think nothing of it.", ["objectivesText"] = "Obtain the Neferset Key from Kavem the Callous. Progress: You're back. Do you have the key?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62817, 65819, 65820, 65821 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 46872, ["x"] = 0.596, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 46872, ["x"] = 0.596, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 4, ["flags"] = 0 } } },
[28350] = { ["id"] = 28350, ["name"] = "Master Trapper", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["series"] = { 27990, 28187, 28193, 28195, 28267, 28269, 28273, 28274 }, ["description"] = "One thing about me that you might not know, <name>... I come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner. As any master trapper will tell you, the most important ingredient in an effective trap is the bait. So let's start there. Fill this bucket with the meat scraps from almost any wild creature in Uldum .", ["objectivesText"] = "Sullah wants you to collect 5 Meat Scraps from the wildlife in Uldum . Progress: Have you got enough to fill my bucket, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 63541 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48431, ["x"] = 0.466667, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48431, ["x"] = 0.466667, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.466667, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 82, ["flags"] = 0 } } },
[28483] = { ["id"] = 28483, ["name"] = "Bleeding the Enemy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "I will not lie to you, <name>. We face a tremendous challenge ahead of us. As you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat. It will be a boon to our armies to know that you've dealt a crushing blow to the enemy.", ["objectivesText"] = "Obtain 10 Neferset Insignia . Progress: It is good to see you once more, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 64352 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48564, ["x"] = 0.52, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48564, ["x"] = 0.52, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 44, ["flags"] = 0 } } },
[28498] = { ["id"] = 28498, ["name"] = "The Secret of Nahom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27003, 27141, 27176, 27179, 27196, 27431, 27511, 27517, 27519, 27520, 27541, 27549, 27595, 27602, 27623, 27624, 27627, 27628, 27629, 27630, 27631, 27632, 27669, 27706, 27707, 27738, 27748, 27755, 27760, 27761, 27777, 27778, 27779, 27836, 27837, 27838, 27900, 27901, 27903, 27905, 27922, 27923, 27924, 27926, 27928, 27939, 27941, 27942, 27943, 27950, 27969, 27990, 28002, 28105, 28112, 28134, 28135, 28187, 28193, 28194, 28195, 28198, 28210, 28267, 28269, 28271, 28272, 28273, 28274, 28276, 28277, 28291, 28350, 28351, 28352, 28363, 28367, 28376, 28402, 28403, 28404, 28480, 28482, 28483, 28486, 28497, 28498, 28499, 28500, 28501, 28520, 28533, 28561, 28602, 28611, 28612, 28613, 28621, 28622, 28623, 28633 }, ["description"] = "There is an old story about Nahom. It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple. Most believe the tale to be just a legend, but that power... would certainly be useful to us now. The vile Neferset have ransacked Atulhet's tomb. They've taken any artifacts of power and shattered the tablets that encode his memories. Go to the Tombs of the Precursors to the east and retrieve any fragments that you find.", ["objectivesText"] = "Obtain 8 Atulhet's Record Fragments . Progress: Did you find them, <name>? Were they salvageable?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 64642 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48761, ["x"] = 0.672, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48761, ["x"] = 0.672, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 545, ["name"] = "Uldum", ["orderIndex"] = 32, ["flags"] = 0 } } },
[34958] = { ["id"] = 34958, ["name"] = "The Shadow of the Worldbreaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["description"] = "Looks like we'll soon have another obstacle in our way: that ridiculously large tank that they have pointed at the Dark Portal. The Iron Worldbreaker, I think they call it. If I had some documentation on how it might work, then I might be able to figure out how to shut it down. Maybe some o' those machinists and laborers have some documentation on how it works?", ["objectivesText"] = "Obtain the Worldbreaker Schematics from Blackrock Orcs in the Blackrock Quarry. Progress: Any luck?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 4, ["flags"] = 0 } } },
[34987] = { ["id"] = 34987, ["name"] = "The Gunpowder Plot", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7025, ["mapID"] = 577, ["storyline"] = { 34437, 34439, 34442, 34925, 34958, 34987, 35005, 35019 }, ["series"] = { 34440, 35253, 35297, 35983 }, ["description"] = "Ey, <pal/lady>! We got an issue, here. Me ol' pal Thaelin's rigged together this here plunger out of spare Blackrock parts - engineerin' whiz that he is - but we're gonna need some gunpowder if we really want ta' do any damage.", ["objectivesText"] = "Find a Blackrock Powder Keg and return it to Hansel Heavyhands . Progress: Don't go doin' anything inappropriate with that gunpowder, now.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 112243, 112323, 112337, 117978, 160347, 160350, 160353, 160356, 160359, 160362, 160365, 160368 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7025 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1265, ["db2PoiUiMapID"] = 577, ["questLines"] = { { ["id"] = 64, ["name"] = "The Blackrock", ["orderIndex"] = 3, ["flags"] = 0 } } },
