[36920] = { ["id"] = 36920, ["name"] = "From Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "A few of our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive, took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?", ["objectivesText"] = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128862, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90255, ["x"] = 0.412, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 9, ["flags"] = 0 } } },
[37256] = { ["id"] = 37256, ["name"] = "They Came From the Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37690, 37733 }, ["description"] = "You're looking for Prince Farondis? <The ghostly elf narrows her eyes warily.> I can take you to Farondis... but first things first. These naga attacked suddenly. They take orders from one called Zarrin, in the low hills to the west. Help me take Zarrin's head, and you'll have my ear.", ["objectivesText"] = "Obtain the Head of Fathom-Commander Zarrin , and slay 8 of his naga troops. Progress: <The nightwatcher looks at you expectantly.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120079, 121427, 121428, 121429, 121430, 132903, 132904, 132905, 132906, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89023, ["x"] = 0.5135, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89023, ["x"] = 0.5135, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5135, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37257] = { ["id"] = 37257, ["name"] = "Our Very Bones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["description"] = "You seek the Tidestone of Golganneth? Yes, I know where it lies. It is in a place to which I prefer not to return. You may be of use to me. In the midst of this naga attack, those horrid fish-men flopped their way onto my lands and raided our graveyards. They steal the bones of our ancestors, and indeed, the very bones of my people. Help me bring some solace to my people. Then I shall tell you more about the Tidestone.", ["objectivesText"] = "Obtain 55 Pilfered Night Elf Bones . Progress: My people may not care much for me, but that will not stop me from caring for them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120080, 121431, 121432, 121433, 121434, 132937, 132938, 132939, 132941, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88115, ["x"] = 0.47, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88115, ["x"] = 0.47, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 3, ["flags"] = 0 } } },
[37447] = { ["id"] = 37447, ["name"] = "The Blood of Demons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "The time has come to make contact with the Master's soul. It is somewhere in the endless expanse of the Twisting Nether. Luckily, so is Mardum. Such a thing is not unheard of, but it will be exceedingly difficult, even here. In addition to what the matron mother had us gather, we need a great deal of demon blood. Like, a lot of it!", ["objectivesText"] = "Collect 100 Fel Blood from any demon on the Broken Isles. Progress: Once we have enough demon blood, you can begin the ritual.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 124125, 127830, 128832, 137677, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37448] = { ["id"] = 37448, ["name"] = "A Simple Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 37494, 37666, 43508 }, ["description"] = "Like many dreadlords, Detheroc cannot help but gloat. He was careless and I overheard many of his plans while I was held captive. With your leave, I would like to underscore the gravity of the situation in Stormwind. The fate of Azeroth hangs in the balance. But for all of that, I have a simple plan: get 'em.", ["objectivesText"] = "Hear Mathias Shaw's plan and then cast your vote. Progress: We need to listen to Shaw's plan and then come to a consensus on the way forward.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[37449] = { ["id"] = 37449, ["name"] = "Dark Revelations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 37450, 37656 }, ["description"] = "I'm not going to let Cordana Felsong get away with this. There is no way in hell I am going to let that warden witch turn my people. As for Nightglaive... I will NOT suffer a traitor to live! Are you with me, <name>?", ["objectivesText"] = "Kill Nightglaive the Traitor . Progress: The traitor must be killed. It is the only way.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 132984, 132985, 132987, 132988, 132989, 132990, 132991, 132993, 132995, 132996, 132998, 132999, 133000, 133001, 133002, 133004, 141384, 237812, 246937 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 }, { ["mapID"] = 630, ["npcID"] = 101927, ["x"] = 0.435, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 13, ["flags"] = 0 } } },
[37450] = { ["id"] = 37450, ["name"] = "Saving Stellagosa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 37449, 37656 }, ["description"] = "During the fighting, of all things, I saw a blue drake swoop in and attack the demons. I couldn't believe my eyes. I'd heard that the Blue Dragonflight had gone extinct. The Legion managed to bring the drake down, but not until after she'd killed a score of them. She was magnificent. Last I saw, they were dragging her in the direction of the southern camp. We should see if she's still alive. A dragon could prove a powerful ally.", ["objectivesText"] = "Obtain Lykill's Key and free Stellagosa . Progress: If there's a remnant of the Blue Dragonflight nearby, we should do whatever we can to ally ourselves with them.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 120359, 132961, 132962, 132963, 132964, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 11, ["flags"] = 0 } } },
[37466] = { ["id"] = 37466, ["name"] = "The Broken Academy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37466 }, ["objectivesText"] = "Defend against the Hatecoil Bound Citizen rescued", ["rewardGold"] = 391440, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend against the Hatecoil", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Bound Citizen rescued", ["amount"] = 25, ["type"] = 0, ["objectID"] = 91449, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630 },
[37467] = { ["id"] = 37467, ["name"] = "The Walk of Shame", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37468, 37486, 37497, 37518, 37736, 42370 }, ["description"] = "The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however. <Farondis' eyes narrow in newfound determination.> We will need to skirt around the edge of town. Follow me.", ["objectivesText"] = "Escort Prince Farondis around the edge of Nar'thalas.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88867, ["x"] = 0.518, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88890, ["x"] = 0.542, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 6, ["flags"] = 0 } } },
[37468] = { ["id"] = 37468, ["name"] = "Into the Academy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37486, 37497, 37518, 37736, 42370 }, ["description"] = "The sunken structure on the other side of this bridge was once called Nar'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor. The Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.", ["objectivesText"] = "Enter the halls of the Nar'thalas Academy.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88890, ["x"] = 0.542, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 7, ["flags"] = 0 } } },
[37469] = { ["id"] = 37469, ["name"] = "The Tidestone: Shattered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37729, 37730 }, ["description"] = "I suppose you can go in, then. The shattered pieces of the Tidestone of Golganneth are contained within the academy's eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia. Oh, young <name>? Please do not touch anything.", ["objectivesText"] = "Collect the 5 Tidestone Shards . Progress: <The last remaining piece of the Tidestone lies before you.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120401, 120960, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 15, ["flags"] = 0 } } },
[37470] = { ["id"] = 37470, ["name"] = "The Head of the Snake", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 38286, 42213 }, ["description"] = "Those naga have the Tidestone shards, <name>. They will soon be dragging them into their watery holes, away from our reach. It would be wise to take out their leaders before that happens.", ["objectivesText"] = "Defeat Athissa . Progress: I... I can't believe it...", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 133019, 133020, 133022, 133023, 133024, 133025, 133026, 133028, 133035, 133052, 133053, 133055, 133056, 133057, 133058, 133059, 133061, 237812, 246864, 246937 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89009, ["x"] = 0.578, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91403, ["x"] = 0.616, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 17, ["flags"] = 0 } } },
[37486] = { ["id"] = 37486, ["name"] = "Nar'thalas Still Suffers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37468, 37497, 37518, 37736, 42370 }, ["description"] = "They have not forgiven me. I cannot blame them. Past crimes aside, I am still their prince. Even in death, I will do what I can to protect my people. <name>. Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar'thalas. After all these years, you - |5<race> <class>, of all things - may be the instrument of my redemption.", ["objectivesText"] = "Defeat Athissa . Progress: I will make it up to them. WE will make it up to them.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121487, 132911, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88867, ["x"] = 0.518, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88867, ["x"] = 0.518, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37492] = { ["id"] = 37492, ["name"] = "A Rather Long Walk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37492 }, ["description"] = "I'm concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned. With these naga attacking, I fear he may be in danger! If you dare venture out into the fray, do look out for our court elder.", ["objectivesText"] = "Find Elder Aldryth. Progress: Have you seen him?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88798, ["x"] = 0.47, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88798, ["x"] = 0.47, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5753, ["name"] = "A Rather Long Walk", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37494] = { ["id"] = 37494, ["name"] = "Under Cover of Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 84, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 37448, 37666, 43508 }, ["description"] = "We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight. The rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7. Are you ready to do this, <name>?", ["objectivesText"] = "Speak with Taoshi when you're ready for Fleet Admiral Tethys to arrange your transport to Stormwind City.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 111049, ["x"] = 0.377, ["y"] = 0.613 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.377, ["y"] = 0.613 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 7, ["flags"] = 0 } } },
[37495] = { ["id"] = 37495, ["name"] = "Plunder the Cove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["objectivesText"] = "Plunder Oceanus Cove Normal mobs Elite mobs Treasure Chest Weapon Rack 01 Weapon Rack 02", ["rewardGold"] = 287760, ["rewardXP"] = 1415, ["rewardItems"] = { 249787 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2Objectives"] = { { ["text"] = "Plunder Oceanus Cove", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Normal mobs", ["amount"] = 40, ["type"] = 0, ["objectID"] = 90109, ["orderIndex"] = 1 }, { ["text"] = "Elite mobs", ["amount"] = 5, ["type"] = 0, ["objectID"] = 89097, ["orderIndex"] = 2 }, { ["text"] = "Treasure Chest", ["amount"] = 25, ["type"] = 0, ["objectID"] = 112018, ["orderIndex"] = 3 }, { ["text"] = "Weapon Rack 01", ["amount"] = 20, ["type"] = 2, ["objectID"] = 241909, ["orderIndex"] = 4 }, { ["text"] = "Weapon Rack 02", ["amount"] = 20, ["type"] = 2, ["objectID"] = 245862, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 9, ["flags"] = 1 } } },
[37496] = { ["id"] = 37496, ["name"] = "Infiltrating Shipwreck Arena", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37507, 38407 }, ["description"] = "The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement. I suppose it will be easy for you to infiltrate the place. It's breaking out that will be the difficult part.", ["objectivesText"] = "Infiltrate Shipwreck Arena and find Okuna Longtusk .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88798, ["x"] = 0.47, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37497] = { ["id"] = 37497, ["name"] = "Trailing the Tidestone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37468, 37486, 37518, 37736, 42370 }, ["description"] = "Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time. It is decided, then. I shall join you. We will have to head east, through Nar'thalas. Shall we depart?", ["objectivesText"] = "Escort Prince Farondis to the Ruins of Nar'thalas.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88115, ["x"] = 0.47, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88867, ["x"] = 0.518, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 4, ["flags"] = 0 } } },
[37507] = { ["id"] = 37507, ["name"] = "Boss Whalebelly's in Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37496, 38407 }, ["description"] = "Great, let's get started! If we're going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won't just let you run around anywhere you want in here. First thing you need to do is present yourself to Boss Whalebelly . The giants may run this place, but as far as posing as one of us, Whalebelly's in charge. He's speaking with his goons just to the south.", ["objectivesText"] = "Speak with Boss Whalebelly . Progress: Go on. Go talk to him.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 2, ["flags"] = 0 } } },
[37510] = { ["id"] = 37510, ["name"] = "Sternfathom's Champion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37528, 37536, 37538, 37542 }, ["description"] = "Since you defeated Ooker Dooker, there's a pit fighter spot open on Sternfathom 's team. You should go establish yourself as his champion. That way, the giants won't think twice about why a stranger is suddenly coming and going as <he/she> pleases. Meanwhile, I'll start to sow some chaos so that we can strike at Prince Oceanus.", ["objectivesText"] = "Report to Sternfathom as his new pitfighter.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88923, ["x"] = 0.48, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37528] = { ["id"] = 37528, ["name"] = "Let Sleeping Giants Lie", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37510, 37536, 37538, 37542 }, ["description"] = "We're going to need a diversion to get close to Prince Oceanus. Are you thinking what I'm thinking? See Sleepy Dhow over there? He's guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves. All you have to do is get past that giant without waking him.", ["objectivesText"] = "Collect the Giants' Stash of Weapons . Progress: As soon as I can, I'll arm the gladiators in Oceanus Cove.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120181, 131811, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 4, ["flags"] = 0 } } },
[37536] = { ["id"] = 37536, ["name"] = "Morale Booster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37510, 37528, 37538, 37542 }, ["description"] = "Things may look good from where you're standing, but, we're losing. However, do not fret, my little <race> friend. You can help. Listen closely. Ooka Dooker , Ooker's sister, is back over yonder in the champions' cave making her world famous Fighter Chow. It'll do the trick and boost our team's morale. All you have to do is to convince her to hand it over.", ["objectivesText"] = "Get the Fighter Chow from Ooka Dooker", ["rewardXP"] = 175, ["rewardItems"] = { 122699, 133577, 133828, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88923, ["x"] = 0.48, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89048, ["x"] = 0.48, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 6, ["flags"] = 0 } } },
[37538] = { ["id"] = 37538, ["name"] = "Round 1, Fight!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37510, 37528, 37536, 37542 }, ["description"] = "All of my gladiators are out of commission! It's down to you, <name>. Bilgerudder's going to pit his three champions against you.", ["objectivesText"] = "Have Sternfathom throw you into the arena, defeat Boss Whalebelly , and then find Okuna Longtusk inside Oceanus Cove.", ["rewardGold"] = 606600, ["rewardXP"] = 1770, ["rewardItems"] = { 121436, 121437, 121438, 121439, 132899, 132900, 132901, 132902, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89048, ["x"] = 0.48, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 7, ["flags"] = 0 } } },
[37542] = { ["id"] = 37542, ["name"] = "No Time for Tryouts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37510, 37528, 37536, 37538 }, ["description"] = "We don't have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants. That kind-hearted giant over there that's losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you'd make yourself a spot on his team. Looks like Ooker Dooker 's taking a rest between bouts. Now's the time to deliver a good ol' monkey beatdown.", ["objectivesText"] = "Deliver a beatdown to Ooker Dooker . Progress: By giving that hozen a good beating, you'll be making a spot for yourself in the arena. You don't have to kill him, though.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 121490, 121492, 121494, 132954, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88873, ["x"] = 0.5, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 3, ["flags"] = 0 } } },
[37565] = { ["id"] = 37565, ["name"] = "The Right Weapon for the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37566 }, ["description"] = "<You and Okuna were going to arm the captives in here. The idea was to free them and cause as much chaos as possible. It's the only sure way to be able to get close to the prince. You still have the weapons. You're just going to have to be careful sneaking around the giants.>", ["objectivesText"] = "Arm 25 Shipwrecked Captives .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 118330, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89051, ["x"] = 0.534667, ["y"] = 0.634667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 8, ["flags"] = 0 } } },
[37566] = { ["id"] = 37566, ["name"] = "The Prince is Going Down", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37565 }, ["description"] = "<name>! I knew you'd come. Quick, let me out of here and we'll take this giant down.", ["objectivesText"] = "Free Okuna Longtusk and kill Prince Oceanus .", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 121440, 121441, 121442, 121443, 132936, 141386, 237812, 246812, 246937 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89051, ["x"] = 0.534667, ["y"] = 0.634667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 109334, ["x"] = 0.52, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 10, ["flags"] = 0 } } },
[37653] = { ["id"] = 37653, ["name"] = "Demon Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 37660 }, ["description"] = "I need to extract information about the Burning Legion from these foul creatures. But living, the demons are almost impossible to break. However, like you, I wield a powerful artifact -- the Scythe of Souls. Take one of my soul gems . If you place it next to a demon's corpse, it will rip the 'soul' out. Then, we will see if the scythe can get them to talk.", ["objectivesText"] = "Trap 8 demon souls on the Faronaar Front. Progress: We need those demon souls, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 122100, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 4, ["flags"] = 0 } } },
[37654] = { ["id"] = 37654, ["name"] = "Maritime Law", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37654, 37657, 37659, 40794, 42220, 42244, 42268 }, ["series"] = { 37659, 38857 }, ["description"] = "Good <sir/madame>, a moment of your time. My fellow salvors and I could not help but notice yon ship that ran aground in the storm last night. A pity about its crew. < Mr. Shackles makes empathetic gestures.> Still, the law's the law. The maritime code is quite clear on the matter. If you find yourself out that way, would you mind terribly checking in on my acquisitions scout, Looper? I would have expected him back for tea some time ago.", ["objectivesText"] = "Find Looper Allen near the ship that's run aground on the east side of Mak'rana.", ["rewardXP"] = 175, ["rewardItems"] = { 141403, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91419, ["x"] = 0.565, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 106881, ["x"] = 0.642, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37656] = { ["id"] = 37656, ["name"] = "Fel Machinations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 37449, 37450 }, ["description"] = "My force wiped out the demons' forward base here. But, an imp mother and her brood took the rest of my demon hunters hostage, including Cyana Nightglaive. We need to free the Illidari and destroy the Burning Legion.", ["objectivesText"] = "Free 6 Demon Hunters from Soul Harvesters. Progress: If we're to defeat the Legion, we need to know exactly what they're up to.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 10, ["flags"] = 0 } } },
[37657] = { ["id"] = 37657, ["name"] = "Making the World Safe for Profit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37654, 37657, 37659, 40794, 42220, 42244, 42268 }, ["description"] = "Might I ask a small favor, my friend? These creatures in the tide pools to the east are starting to frighten me. Our efforts to trade with them have been rebuffed at every turn with aggression. This is not good; neither for running a business, nor for profit. Sadly, I must admit the time for talk has come to an end. Might you be willing to serve as my representative in dealing with the denizens of Mak'rura and their \"queen\"? I can assure you that your efforts will be rewarded commensurately.", ["objectivesText"] = "Kill 12 gilblin and/or makrura at Mak'rana and slay their leader, Queen Kraklaa. Progress: How goes the cleanup?", ["rewardGold"] = 606600, ["rewardXP"] = 1415, ["rewardItems"] = { 64399, 129170, 133549, 138848, 138850, 138851, 138852, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91419, ["x"] = 0.565, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91419, ["x"] = 0.565, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37658] = { ["id"] = 37658, ["name"] = "Reignite the Wards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "The demons are weakening my defenses. They must be far more powerful than what we've faced before. Will you help me to reignite the wards to keep the Legion from overrunning our position here?", ["objectivesText"] = "Reignite the 3 demon wards . Progress: All of the wards need to be reignited if we're to hold the front.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141620, 141621, 141622, 141623, 141625, 141626, 141627, 141628, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37659] = { ["id"] = 37659, ["name"] = "The Captain's Foot Locker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37654, 37657, 37659, 40794, 42220, 42244, 42268 }, ["series"] = { 37654, 38857 }, ["description"] = "I don't care what you do, mate. But, if you get caught, you didn't see me. I wasn't here.", ["objectivesText"] = "Locate the Captain's Chest below decks on the Queen's Reprisal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141403, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106881, ["x"] = 0.642, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[37660] = { ["id"] = 37660, ["name"] = "The Scythe of Souls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 37653 }, ["description"] = "Let's head to the other side of the stand. We will release the demon souls one by one and get the answers that we seek concerning Lord Illidan. The Scythe of Souls will ensure that we do.", ["objectivesText"] = "Work with Allari the Souleater to compel information from the demon souls . Progress: We need to compel the demons, <name>.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 129172, 132947, 132948, 132949, 132951 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 6, ["flags"] = 0 } } },
[37666] = { ["id"] = 37666, ["name"] = "Picking a Fight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 37448, 37494, 43508 }, ["description"] = "They're coming, <name>! I will get to work unlocking these fel-magic chains from the cage. You keep the Legion at bay.", ["objectivesText"] = "Kill demons until Vaultwarden Umbral appears and kill him. Then, set Mathias Shaw free.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110793, ["x"] = 0.27, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37678] = { ["id"] = 37678, ["name"] = "Hit the Books", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["description"] = "<The librarian speaks in shushed tones.> One problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage. If you encounter any of these exasperating essays, please put them down. Quietly.", ["objectivesText"] = "Destroy 3 Ancient Tomes . Progress: <The librarian sighs quietly.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 138840, 138841, 138842, 138843, 138844, 138845, 138846, 138847, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 9, ["flags"] = 0 } } },
[37689] = { ["id"] = 37689, ["name"] = "The Imposter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["description"] = "Detheroc has SI:7's finest snipers on all of the rooftops. We can't mount up and we can't fly. There are grapple points above so that we can move up the cliff. We've also setup hay bales to hide in along the likely routes to SI:7. We just need to stealth in and kill Detheroc. Once we get up there, we'll separate to increase the chances of at least one of us making it through the city. Good luck, <name>.", ["objectivesText"] = "Grapple up the Lion's Rest cliffs, sneak through Stormwind City to the SI:7 courtyard, and then kill Detheroc.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 142057, 142058, 142061, 142063, 142064, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 111049, ["x"] = 0.377, ["y"] = 0.613 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.377, ["y"] = 0.613 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 8, ["flags"] = 0 } } },
[37690] = { ["id"] = 37690, ["name"] = "Those Who Remember", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37256, 37733 }, ["description"] = "The ghostly elves, to the south, once had the Pillar of Creation known as the Tidestone of Golganneth. Their great city of Nar'thalas was destroyed an eon ago. The city's ruler, Prince Farondis, fell with the city. You small ones die so easily. If anyone knows where the fragments rest, it will be the ghost of the prince. Seek out his people.", ["objectivesText"] = "Locate Nightwatcher Idri in the Drowned Gardens.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89975, ["x"] = 0.478, ["y"] = 0.266 }, { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89023, ["x"] = 0.5135, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37727] = { ["id"] = 37727, ["name"] = "The Magister of Mixology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37727, 37728 }, ["description"] = "As you must know, I'm a connoisseur of drinks... specifically, arcane-infused spirits. Cocktail mixing is alchemy, and as everyone knows, alchemy is magic. My latest drink must be more exotic than anything I've conjured before. I already have most of what I need. But there are a couple of items left on the list. Notice the herons down in the lagoon? As with many of the creatures on Azsuna , the magic coursing through the island permeates them. Their eggs will do nicely.", ["objectivesText"] = "Collect 6 Arcane-Infused Eggs . Progress: Are we speaking again because you have my eggs?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 120939, 133814, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89341, ["x"] = 0.47, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89341, ["x"] = 0.47, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5760, ["name"] = "Crumbled Palace Cocktails", ["orderIndex"] = 0, ["flags"] = 0 } } },
[37728] = { ["id"] = 37728, ["name"] = "Presentation is Everything", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37727, 37728 }, ["description"] = "The eggs will provide the 'oomph' to my drink's character. But there's another element, and this must not be underestimated! Presentation. Now, you could go with your standard olive skewered on a toothpick. Maybe a carrot stalk stuck slapdash out of a glass. But then, you wouldn't be me. No, my friend. What MY drink needs to sell it visually comes from a one-of-a-kind creature. I'm only going to serve it once and so my drink deserves something unique. The eyes of Gangamesh are what I need.", ["objectivesText"] = "Collect the Six Eyes of Gangamesh . Progress: Yes? You have the eyes?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 120940, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89341, ["x"] = 0.47, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89341, ["x"] = 0.47, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5760, ["name"] = "Crumbled Palace Cocktails", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37730] = { ["id"] = 37730, ["name"] = "The Headmistress' Keys", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37469, 37729 }, ["description"] = "I have a suspicion you are avoiding your studies - but I can see you're anxious to see the Headmistress. Very well! Headmistress Azuremoon can be found up ahead, though I doubt she will enjoy being interrupted.", ["objectivesText"] = "Obtain the Tidestone Vault Key from Elya Azuremoon, the Academy Headmistress. Progress: Were you able to meet with the headmistress?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 120169, 121484, 132907, 132908, 132909, 132910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 14, ["flags"] = 0 } } },
[37733] = { ["id"] = 37733, ["name"] = "Prince Farondis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37256, 37690 }, ["description"] = "I'm glad to see that my doubts in you were unfounded. You seek Prince Farondis? Follow me. I will show you to the prince's hall.", ["objectivesText"] = "Meet up with Nightwatcher Idri at the Crumbled Palace.", ["rewardGold"] = 5865, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89023, ["x"] = 0.5135, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89023, ["x"] = 0.5135, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5135, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 2, ["flags"] = 0 } } },
[37736] = { ["id"] = 37736, ["name"] = "Dressing With Class", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37468, 37486, 37497, 37518, 42370 }, ["description"] = "Now stop right there. Look at you! You look like you just walked in off of the street. Where are your robes and hat? And don't tell me you've entered the academy without your wand and spellbook. Freshmen. Put yourself together, and maybe then I will consider letting you enter the academy.", ["objectivesText"] = "Obtain a Nar'thalas Academy Hat , Robes, Wand, and Spellbook. Progress: Still trying to get into the academy, I see.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120946, 120947, 120948, 120949, 138873, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 8, ["flags"] = 0 } } },
