[37853] = { ["id"] = 37853, ["name"] = "The Death of the Eldest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 38443 }, ["description"] = "I will do what I can to stabilize him, but I will need your help. The small amount of energy he has left is coming from the mana pool he rests in. Follow the whelplings' lead. Dropping ley crystals into the pool gives him a bit of energy - buying him a few more breaths. They seem to be getting the crystals from inside that cave to the north.", ["objectivesText"] = "Slay Leyworms to obtain 6 Crackling Leyworm Cores , then drop them into Senegos's pool. Progress: Call me a fool. I'd always just thought that grandfather would be with us forever.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121412, 122095, 132216, 132217, 132233, 140310, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93354, ["x"] = 0.48, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89794, ["x"] = 0.48, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 1, ["flags"] = 0 } } },
[37855] = { ["id"] = 37855, ["name"] = "The Last of the Last", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["description"] = "We need help. Since the fall of Deathwing, we dragons have lost nearly all of our power. To make matters worse, we can no longer bear eggs. My whelplings are the last of the last. I need you, champion. Help defend my whelplands, and I swear to you, the blues will be at your side when you need them.", ["objectivesText"] = "Investigate the Azurewing Whelplands.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 13444, 13446, 20557, 33271, 38237, 38238, 38239, 38240, 38241, 38242, 39109, 39112, 39117, 39119, 39120, 44013, 44014, 44015, 52586, 52602, 52632, 56689, 56690, 56691, 57829, 59650, 59651, 59652, 63754, 63755, 63756, 83746, 83747, 83748, 83749, 83750, 83751, 83752, 83753, 83754, 83755, 98137, 98138, 98139, 98140, 98141, 98142, 98143, 98144, 98145, 106135, 106149, 106157, 107302, 131293, 131327, 132523, 140244, 140602, 140603, 140604, 140605, 140606, 140607, 140608, 140609, 141943, 142054, 153737, 153744, 153787, 153789, 153808, 153810, 153822, 153825, 153842, 153847, 153855, 153904, 153911, 153938, 153941, 153954, 153956, 154003, 154006, 154016, 154041, 154048, 154735, 154737, 155564, 156976, 158585, 158587, 158628, 158630, 170155, 182253, 182262, 182271, 182280, 194338, 194381, 194382, 194383, 194528, 194530, 197134, 210957, 211279, 217109, 217110, 217111, 232694, 237812, 245438, 246863, 247858, 247915, 254878, 259000 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89975, ["x"] = 0.478, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 4, ["flags"] = 0 } } },
[37856] = { ["id"] = 37856, ["name"] = "The Withered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["description"] = "The withered are the worst kind of pest. They capture our whelplings, knock them unconscious, and then drink whatever mana they can from the helpless babes. Normally our drakes and keepers would fend them off. Today, it looks like we may need your help.", ["objectivesText"] = "Slay 12 withered in the Azurewing Whelplands. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90916, ["x"] = 0.486, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90916, ["x"] = 0.486, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 5, ["flags"] = 0 } } },
[37858] = { ["id"] = 37858, ["name"] = "Stellagosa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37957 }, ["description"] = "Something is wrong, <name>. I sent Stellagosa to assist you, but I can no longer sense her. Please, go out there and find out what's happened to my granddaughter.", ["objectivesText"] = "Find Stellagosa .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 132961, 132962, 132963, 132964, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90065, ["x"] = 0.465, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 8, ["flags"] = 0 } } },
[37859] = { ["id"] = 37859, ["name"] = "The Consumed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["description"] = "<The whelpling is alive, but unconscious. One of the withered must have already drained it of mana.> <You've already learned that exposed ley crystals contain a small amount of magical energy. Perhaps you can use one to revive some of the whelps.>", ["objectivesText"] = "Find a Dim Ley Crystal , then revive 10 Mana-Drained Whelplings . Progress: Clever <race>. Yes, a ley crystal should bring them back to their senses.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 59539, 59540, 59541, 122188, 131227, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90423, ["x"] = 0.494, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 7, ["flags"] = 0 } } },
[37860] = { ["id"] = 37860, ["name"] = "You Scratch My Back...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37959 }, ["description"] = "Much better. I knew I could count on you, my friend. Allow me to return the favor. I know how you can destroy the large mana collector pylons. We shall save your dragon yet! The pylons only work against ground targets, yet they're defenseless from above. Send your whelplings at them, my friend. The whelplings can fly where we cannot. Trust me.", ["objectivesText"] = "Release the whelplings on each of the Mana Collector Pylons in Zarkhenar.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90383, ["x"] = 0.515, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107995, ["x"] = 0.5608, ["y"] = 0.1616 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 12, ["flags"] = 0 } } },
[37861] = { ["id"] = 37861, ["name"] = "The Nightborne Prince", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37857, 37862, 37960, 38014, 38015 }, ["description"] = "<Senegos is focused.> I sense it now. In the ruined building, to the east. One of these cretins must have tapped deep into the ley line. I suspect he will be heavily defended, <name>. Once again, the well-being of my brood is in your hands.", ["objectivesText"] = "Slay Ael'Yith .", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 121444, 121445, 121446, 121447, 132926, 132927, 132928, 132929, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107995, ["x"] = 0.5608, ["y"] = 0.1616 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 13, ["flags"] = 0 } } },
[37862] = { ["id"] = 37862, ["name"] = "Still Alive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37857, 37861, 37960, 38014, 38015 }, ["description"] = "Wait, what was it that I heard? Was it... \"feast on the dragons\"? We must check on grandfather, right away! Let me know when you're ready to depart.", ["objectivesText"] = "Speak with Stellagosa to take a ride back to Azurewing Repose.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107995, ["x"] = 0.5608, ["y"] = 0.1616 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90738, ["x"] = 0.499, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.5608, ["y"] = 0.1616 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 14, ["flags"] = 0 } } },
[37957] = { ["id"] = 37957, ["name"] = "Runas the Shamed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37858 }, ["description"] = "I fell so quickly, <name>. I am not as strong as I once was. We truly do need your help. One of these disgusting creatures ran off with several of the whelplings. I heard him called by name: Runas. I will survive. Home is not far. You still have strength, though. Slay this Runas before he does any more damage to our brood.", ["objectivesText"] = "Slay Runas the Shamed . Progress: Ah, Stella. Always so quick to act. She is still young.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132969, 132970, 132971, 132972, 132973, 132974, 132975, 138874, 138893, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90065, ["x"] = 0.465, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 6, ["flags"] = 0 } } },
[37959] = { ["id"] = 37959, ["name"] = "The Hunger Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37860 }, ["description"] = "<Runas looks antsy.> I can help you, and I very much want to help you, but I'm a bit distracted. Look at all that raw, unfiltered, mouthwatering mana... <Runas slaps his own face.> No! NO! You must stay in control! I simply need to clear my head. Yes, that's it. A few of my depraved brethren carry small mana jewels around with them in case they need a quick burst of energy. Find a few for me? Then I will show you how to get your ley line back.", ["objectivesText"] = "Obtain 4 Charged Mana Jewels . Progress: Do you have them? Please tell me you have them, my friend.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 122153, 138875, 138876, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90383, ["x"] = 0.515, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90383, ["x"] = 0.515, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 10, ["flags"] = 0 } } },
[37960] = { ["id"] = 37960, ["name"] = "Leyline Abuse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37857, 37861, 37862, 38014, 38015 }, ["description"] = "These monsters are pulling mana directly out of the ground. This explains why not even my mana pools can dull my pain. I worry about my brood. Without the power of the ley lines, we are nothing. At this rate, I may not even be able to help you with your Tidestone. Look for their mana siphons, and punish the cowardly nightfallen elves that are using them.", ["objectivesText"] = "Slay Iskhaneth and Tyndrissen . Progress: With each one of these cretins you slay, I grow stronger.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 }, { ["mapID"] = 630, ["npcID"] = 90569, ["x"] = 0.534, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89978, ["x"] = 0.506, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 11, ["flags"] = 0 } } },
