[37991] = { ["id"] = 37991, ["name"] = "Agapanthus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 42271 }, ["description"] = "<This whelpling is trying to get your attention. She locks eyes with you, then quickly flicks her head toward the northeast.>", ["objectivesText"] = "Investigate and assist the visitors in Azurewing Repose.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89795, ["x"] = 0.48, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90543, ["x"] = 0.488, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38014] = { ["id"] = 38014, ["name"] = "Feasting on the Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37857, 37861, 37862, 37960, 38015 }, ["description"] = "You killed their leader, so they came here? Understandable. These creatures crave only one thing - magic - and they can sniff it out from leagues away. Without a leader, they will soon wither and die. Our only recourse in the meantime is to put as many as possible down before they take these dragons with them!", ["objectivesText"] = "Slay 15 withered in Azurewing Repose. Progress: Yes, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 121416, 121417, 121418, 121435, 132914, 132915, 132916, 132917, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102988, ["x"] = 0.496, ["y"] = 0.268 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102988, ["x"] = 0.496, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 15, ["flags"] = 0 } } },
[38015] = { ["id"] = 38015, ["name"] = "On the Brink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37857, 37861, 37862, 37960, 38014 }, ["description"] = "This many withered threaten to wipe our brood out completely! Quickly, <name>! Crack off a ley crystal and heal any wounded drakes you can find out on the battlefield. I will do what I can to keep these whelplings safe and healthy.", ["objectivesText"] = "Use the Radiant Ley Crystal or your healing spells and abilities to resuscitate wounded dragons. Progress: Hurry, <name>!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129178, 138146 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90738, ["x"] = 0.499, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90738, ["x"] = 0.499, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 16, ["flags"] = 0 } } },
[38035] = { ["id"] = 38035, ["name"] = "A Royal Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 84, ["storyline"] = { 38035, 38206, 39800, 44700 }, ["series"] = { 38052, 38206, 39735, 39800, 44700 }, ["description"] = "Well met, $p. I have come on behalf of King Anduin Wrynn. My crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor. <Rogers hands you a sealed envelope.>", ["objectivesText"] = "Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor. Progress: Can we count on you?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128687, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.185538, ["y"] = 0.462154 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 131, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 131, ["name"] = "Greymane's Gambit", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38036] = { ["id"] = 38036, ["name"] = "Supplies From the Skies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["description"] = "Are you feeling alright? Say 'ah.' < Mishka attempts to depress your tongue with a damp twig.> Sorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it's all scattered to the winds now. Anything you can salvage from the wreck will save lives!", ["objectivesText"] = "Gather 5 Skyfire First Aid Kits . Progress: Did you find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 123876, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90783, ["x"] = 0.336, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 90783, ["x"] = 0.336, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38052] = { ["id"] = 38052, ["name"] = "Boarded!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38035, 38206, 39735, 39800, 44700 }, ["description"] = "Glad to see you survived the crash. Unfortunately, so did most of the enemy's boarding party. Just the thought of those monsters setting foot on my ship makes me sick. Wipe them out, $p. For my crew... For King Wrynn... For the Alliance!", ["objectivesText"] = "Slay 8 Forsaken Bat-Riders or Forsaken Deathstalkers . Progress: There will be no peace with those monsters running free.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90749, ["x"] = 0.337, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 90749, ["x"] = 0.337, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.337, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38053] = { ["id"] = 38053, ["name"] = "Assault and Battery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38057, 38058, 38059, 38060, 38558 }, ["description"] = "We need to report our position to the Alliance navy ASAP! I am building a new transponder to send a distress signal, but I need a battery from the Skyfire's communications console. You'll find the console at the top of the ship - I just hope those undead haven't put their creepy, bony fingers on it yet!", ["objectivesText"] = "Recover the Transponder Battery from Dread-Rider Malwick. Progress: I cannot build a new transponder without that battery!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 122295, 134554, 134555, 134556, 134557, 134558, 134559, 134560, 134561, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38057] = { ["id"] = 38057, ["name"] = "The Lost Legion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38053, 38058, 38059, 38060, 38558 }, ["description"] = "The heroic men and women of the 7th Legion stayed at the front of the ship to fight off storm drakes while the crew evacuated. None of them have returned. Please find them, $p!", ["objectivesText"] = "Locate the missing 7th Legion Dragoons.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90783, ["x"] = 0.336, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38058] = { ["id"] = 38058, ["name"] = "Lightning Rod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38053, 38057, 38059, 38060, 38558 }, ["description"] = "<Overspark's tiny hands move like lightning, affixing coils and tubes to the device before cramming it into a parachute pack.> Put this on. Just up the hill you'll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder. You'll have to incite them, of course, but the device should draw most of the power. The probability of you being electrocuted is well within acceptable parameters!", ["objectivesText"] = "Charge the Transponder by absorbing Storm Drake lightning attacks.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38059] = { ["id"] = 38059, ["name"] = "Pins and Needles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38053, 38057, 38058, 38060, 38558 }, ["description"] = "Hngghh! Nope, can't stand yet. It's all pins and needles. Small fries like this are usually no problem for the 7th, but we weren't prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn't move a muscle until you came along. My comrades were carried deeper into the cave. Get 'em out before they become whelp chow!", ["objectivesText"] = "Release 6 7th Legion Dragoons from static fields.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38060] = { ["id"] = 38060, ["name"] = "Signal Boost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38053, 38057, 38058, 38059, 38558 }, ["description"] = "The Skyfire's starboard propeller came to rest on the cliffs overlooking our camp - we're gonna use it like a big antenna and push our distress signal so far that even Mekkatorque's alarm clock could pick it up! Unfortunately, it might attract some unwanted attention. We're braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!", ["objectivesText"] = "Use the Skyfire Propeller to broadcast a distress signal, then hold out until help arrives.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129233, 129234, 129235, 129236, 129310, 129311, 129312, 129313, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 }, { ["mapID"] = 634, ["npcID"] = 92556, ["x"] = 0.324667, ["y"] = 0.491333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 90749, ["x"] = 0.337, ["y"] = 0.485 }, { ["mapID"] = 634, ["npcID"] = 92557, ["x"] = 0.322571, ["y"] = 0.489714 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38142] = { ["id"] = 38142, ["name"] = "Archdruid of the Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "Near the southern edge of our forest you will find Sleeper's Barrow. There, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream. Find disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.", ["objectivesText"] = "Locate Steelclaw Vale.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91651, ["x"] = 0.518, ["y"] = 0.64 }, { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 73426, ["x"] = 0.49, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38143] = { ["id"] = 38143, ["name"] = "Awakening the Archdruid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "Now, we must focus our efforts on waking Archdruid Steelclaw. She and our druid brethren slumber in the barrow dens to the south. With the furbolgs quelled, we can pass safely to the entrance. Go and awaken the Archdruid. I pray to Elune that we are not too late.", ["objectivesText"] = "Awaken the Archdruid of the Claw.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 73426, ["x"] = 0.49, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 643, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38144] = { ["id"] = 38144, ["name"] = "The Demons Below", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "Something, someone, intended us to never awaken. I sense their presence is still here in the barrow. <Koda takes a moment to stand.> My body is weak from deep slumber. If you would aid us, clear our barrow of any enemies.", ["objectivesText"] = "Kill 8 Darkfiend Intruders. Progress: This was no accident. Someone intended us to sleep forever.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38145] = { ["id"] = 38145, ["name"] = "Out of the Dream", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "Malfurion Stormrage... A name I have not heard in centuries. He was teacher to many of us. If he seeks my audience, I cannot refuse. I will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking. A mysterious force of great power is at work against us. I am still too weak from my hibernation. Please, stranger, go and free them from their dreams.", ["objectivesText"] = "Awaken 8 Druids of the Claw . Progress: The Druids of the Claw must awaken. We are needed.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 21100, 21746, 54917, 54918, 54919, 54920, 87399, 109585, 120978, 121574, 121575, 121576, 121585, 121586, 121587, 121588, 121593, 124124, 131412, 131422, 151493, 152103, 173363, 175647, 175660, 175661, 175662, 191983, 191984, 191987, 191989, 191991, 191993, 191994, 191995, 191997, 191998, 191999, 192000, 192001, 192003, 192005, 192006, 192007, 192009, 192010, 192011, 192012, 192013, 197926, 197931, 197932, 197935, 197937, 197938, 197939, 197942, 197948, 198539, 198542, 198611, 200073, 201921, 201922, 201923, 201924, 204076, 206960, 208047, 208066, 208067, 208153, 208396, 208846, 209833, 210009, 210180, 210254, 210421, 210864, 210872, 210916, 210917, 210952, 210954, 210992, 211279, 211376, 211394, 215364, 217111, 224297, 237812, 245259, 257317, 257318, 257319, 257320, 257321, 257322, 257323, 257324, 257325, 257327, 269986 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38146] = { ["id"] = 38146, ["name"] = "The Chieftain's Beads", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "The ceremonial beads, decorated with shells and feathers, are worn by the clan's chieftain. Perhaps Elder Sookh would be interested in seeing these.", ["objectivesText"] = "Speak to Elder Sookh at Smolderhide Thicket.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128340, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93890, ["x"] = 0.484, ["y"] = 0.845 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.845 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 4, ["flags"] = 1 } } },
[38147] = { ["id"] = 38147, ["name"] = "Entangled Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "I sense powerful magic emanating from deep within the barrow. Whatever is down there weaves a powerful spell, entangling us within our dreams. I am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you. Go and eliminate the source of this magic.", ["objectivesText"] = "Kill Morphael . Progress: Someone entangled us within a sinister spell.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121574, 121575, 121576, 121585, 121586, 121587, 121588, 121593, 237812, 245702, 246937 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38148] = { ["id"] = 38148, ["name"] = "Return to the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["series"] = { 38322, 38323, 38377, 40573 }, ["description"] = "Now that my clan is assembled, we shall return to the Grove of Cenarius. Speak to Malfurion when you arrive. We will find out the cause of Cenarius' illness.", ["objectivesText"] = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 1, ["flags"] = 1 } } },
[38203] = { ["id"] = 38203, ["name"] = "Challiane Vineyards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38203 }, ["description"] = "Please, outsider, help me. My recipe for Nightrose wine was to be the toast of Queen Azshara herself. But before I could make it, the vile vintners took it from me and locked me away. Please, recover my recipe so that I might bring it to Lady Challiane and earn the queen's favor.", ["objectivesText"] = "Collect the 3 parts of the Nightrose recipe. Progress: Have you found the pieces of the recipe?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121489, 121491, 121493, 122393, 122394, 122395, 132965, 132966, 132967, 132968, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91061, ["x"] = 0.408, ["y"] = 0.092 }, { ["mapID"] = 630, ["npcID"] = 91065, ["x"] = 0.467231, ["y"] = 0.118923 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91061, ["x"] = 0.408, ["y"] = 0.092 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.092 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5758, ["name"] = "Challiane Vineyards", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38206] = { ["id"] = 38206, ["name"] = "Making the Rounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 38035, 38206, 39800, 44700 }, ["series"] = { 38035, 38052, 39735, 39800, 44700 }, ["description"] = "You must be wondering what all of this is about. Please, walk with me. I have some final preparations to make before we set sail, and I know that your presence will inspire the crew.", ["objectivesText"] = "Follow Sky Admiral Rogers and prepare the Skyfire to set sail. Progress: As soon as preparations are complete, we set out for Stormheim .", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 96663, ["x"] = 0.185333, ["y"] = 0.506667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.185538, ["y"] = 0.462154 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 131, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 131, ["name"] = "Greymane's Gambit", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38210] = { ["id"] = 38210, ["name"] = "The Ancient Trials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["description"] = "<As the raven stares into your eyes, an odd voice fills your mind.> I know who you are, champion, and I know what you seek. Come to me, if you think yourself truly worthy.", ["objectivesText"] = "Find Havi near Aggramar's Vault.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 139302, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97306, ["x"] = 0.338, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38225] = { ["id"] = 38225, ["name"] = "Death to the Witchmother", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38225, 38235, 38381, 44106 }, ["series"] = { 38219 }, ["description"] = "The numberless years of my life have been dedicated to learning and perfecting the arts of healing and restoration. Nothing in this world pains me more than taking a life, traveler. It is with a heavy heart that I must commission the death of Magula , the leader of the harpies that threaten this grove. May her death save the lives of more noble beings.", ["objectivesText"] = "Slay Magula . Progress: Has the terrible deed been accomplished, traveler?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 121646, 130021, 237812, 246937 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 187, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 187, ["name"] = "Archdruid of Lore", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38232] = { ["id"] = 38232, ["name"] = "Minion! Kill Them!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38232, 38237, 38460, 42238 }, ["description"] = "Per your contract you will help me gather supplies for a perfectly harmless ritual. I need feathers, and horns. Lots of horns. See those shadowrunners, prowlers and heron over there in the Olivian Veil? They should have lots of both. Oh! And I need olives. Lots of olives. One for each finger. Minion! Let's ride!", ["objectivesText"] = "Fulfill your part of the deal with Daglop . Progress: This land is ripe for the taking. Especially the olives. They are really ripe. And I love ripe olives.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 122445, 122446, 122447, 138878, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91166, ["x"] = 0.622, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5762, ["name"] = "Minion's Minion", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38235] = { ["id"] = 38235, ["name"] = "Solid as a Rock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38225, 38235, 38381, 44106 }, ["description"] = "Cenarius requires me? I shall depart as soon as I am able, but I mustn't leave while my druids are in danger. A vile harpy coven has emerged and seeks to claim my grove as their own. These vermin inflict a petrifying disease which, given time, will destroy the infected. While I wish for all of my followers to be cured, it is crucial that my elder disciples survive to protect the grove in my absence. If you would assist us, find my disciples and rouse them from this terrible state.", ["objectivesText"] = "Rescue Marnor Lorleaf , Erwind Mistfen and Del'thanar Sagewood . Progress: Have you roused my disciples, traveler?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 187, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 187, ["name"] = "Archdruid of Lore", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38237] = { ["id"] = 38237, ["name"] = "This IS In My Contract.", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38232, 38237, 38460, 42238 }, ["description"] = "To perform my ritual I need to use a special cave I have prepared at Gloombound Barrow. Meet me there and I will \"give\" you your reward. Hee hee.", ["objectivesText"] = "Help Daglop complete his ritual.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138878, 141863, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91166, ["x"] = 0.622, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5762, ["name"] = "Minion's Minion", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38246] = { ["id"] = 38246, ["name"] = "Totemic Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["series"] = { 38922 }, ["description"] = "I heard the others talking earlier. I may know the cause of their fear. They say the Chieftain has a mysterious totem. It gives him power, and fearful visions. If you destroy the totem, the madness will end.", ["objectivesText"] = "Destroy the Nightmare Totem.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 121598, 121599, 121600, 121601, 129987, 129995, 130003, 130014, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93581, ["x"] = 0.469333, ["y"] = 0.845333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93890, ["x"] = 0.484, ["y"] = 0.845 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.469333, ["y"] = 0.845333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38286] = { ["id"] = 38286, ["name"] = "Eye of Azshara: Wrath of Azshara", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37470, 42213 }, ["description"] = "<name>, Warlord Parjesh ran into the magical vortex just ahead. He has returned to an island off the shore to the southeast where Queen Azshara is staging more of her forces. The queen is beyond angry because we opposed her. Even now, she is summoning up a monstrosity known as her Wrath to exact revenge for our defiance and drown the Broken Isles. You must defeat the Wrath of Azshara before the queen lets it loose to destroy us all!", ["objectivesText"] = "Enter the Eye of Azshara , then defeat Warlord Parjesh and the Wrath of Azshara . The Eye of Azshara is a dungeon so be certain to gather some friends to undertake this perilous journey.", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 137206, 141385, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91403, ["x"] = 0.616, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1456, ["db2PoiUiMapID"] = 713, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 18, ["flags"] = 1 } } },
[38305] = { ["id"] = 38305, ["name"] = "Cenarius, Keeper of the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38305 }, ["description"] = "Greetings, hero. Welcome to Val'sharah . It has been an age since I have set foot in these precious woods. Too long... Our work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.", ["objectivesText"] = "Speak to Malfurion Stormrage at Lorlathil in Val'Sharah .", ["rewardGold"] = 27620, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38307] = { ["id"] = 38307, ["name"] = "The Warchief Beckons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 39864, 44701 }, ["description"] = "Greetings, $p. I am here on behalf of Lady Sylvanas Windrunner . I should hope you recognize the name. <Nathanos thrusts a sealed envelope into your hand.> Read it and follow me. You can read, can't you?", ["objectivesText"] = "Read the Royal Summons and follow Nathanos Blightcaller through the portal to Durotar. Progress: If only she weren't so specific about bringing you to her unharmed...", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128692, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.088 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38312] = { ["id"] = 38312, ["name"] = "A Grapple a Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic. The only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don't have a launcher, I managed to wrangle a spare from one of these vrykul. I'll scout ahead and see if I can find a good spot to get in.", ["objectivesText"] = "Pick up a Stormforged Grapple Launcher and meet Lorna Crowley outside the wall of Hrydshal.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91222, ["x"] = 0.374, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91481, ["x"] = 0.424, ["y"] = 0.647333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38318] = { ["id"] = 38318, ["name"] = "No Wings Required", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Now that you've got the launcher, we should be able to infiltrate the city. It looks like there's a good spot to grapple onto on the wall just past us. There's a vantage point on top of this ridge. Once we're in, I'll try to slip past the guards and get a look at the mountain path. I'd appreciate if you could make some distractions for me. If all goes well, I'll meet up with you in the upper city. Good luck!", ["objectivesText"] = "Go to the top of the ridge and use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91481, ["x"] = 0.424, ["y"] = 0.647333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91519, ["x"] = 0.438, ["y"] = 0.682 }, { ["mapID"] = 634, ["npcID"] = 91553, ["x"] = 0.462, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.647333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38322] = { ["id"] = 38322, ["name"] = "Return to the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["series"] = { 38148, 38323, 38377, 40573 }, ["description"] = "Now that my grove is safe, I can turn my attention to the threat you speak of. To hear of Cenarius' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.", ["objectivesText"] = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 2, ["flags"] = 1 } } },
[38323] = { ["id"] = 38323, ["name"] = "Return to the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["series"] = { 38148, 38322, 38377, 40573 }, ["description"] = "Forgive me, <race>. Archdruid Moonclaw's fall is a terrible blow... Malfurion must be informed of what has transpired here. Inform him of Thaon's fate and of the return of Xavius. Make haste, friend. I fear this may be the greatest threat Val'sharah has ever faced.", ["objectivesText"] = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 100573, ["x"] = 0.622, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 0, ["flags"] = 1 } } },
[38324] = { ["id"] = 38324, ["name"] = "Accessories of the Cursed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "Wait! Before ye go rushin' off, we might want to be gettin more than just seaweed. Ye see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it'll add to the disguise. So what ye waitin for?", ["objectivesText"] = "Collect 8 Cursed Bones in Helheim . Progress: Make sure ye've got enough bones before we move on.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121563, 122611, 129331, 129332, 129333, 129334, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38331] = { ["id"] = 38331, ["name"] = "Havi's Test", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 39590, 39591, 39595 }, ["description"] = "I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task. Know that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe. Many trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn't carry the ingredients up the hill. You look like you have a good arm. Will you help an old man finish his stew?", ["objectivesText"] = "Toss ingredients from the Basket of Root Vegetables, Barrel of Crabs, and Hearty Vrykul Grains into Havi 's Stewpot. Progress: Smells good, doesn't it?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128511, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38332] = { ["id"] = 38332, ["name"] = "The Ranger Lord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38332, 38360, 38361, 38362, 38459 }, ["series"] = { 38360, 38362 }, ["description"] = "Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before. He took a group of rangers north to look for Sylvanas - nobody has seen her since the battle. He asked me to send you his way if you ever woke up.", ["objectivesText"] = "Report to Nathanos Blightcaller .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91473, ["x"] = 0.36, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 127, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 127, ["name"] = "The Forsaken Fleet", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38337] = { ["id"] = 38337, ["name"] = "Built to Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38337 }, ["description"] = "The vrykul around here seem to use scales from these drakes to fashion their armor. If you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", ["objectivesText"] = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal. Progress: Oh, what do you have there?", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 121519, 121520, 121521, 121522, 122609, 129320, 129321, 129322, 129323 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91222, ["x"] = 0.374, ["y"] = 0.638 }, { ["mapID"] = 634, ["npcID"] = 91481, ["x"] = 0.424, ["y"] = 0.647333 }, { ["mapID"] = 634, ["npcID"] = 91519, ["x"] = 0.438, ["y"] = 0.682 }, { ["mapID"] = 634, ["npcID"] = 91553, ["x"] = 0.462, ["y"] = 0.704 }, { ["mapID"] = 634, ["npcID"] = 91771, ["x"] = 0.372, ["y"] = 0.636 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.374, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 122610 } },
[38339] = { ["id"] = 38339, ["name"] = "A Little Kelp From My Foes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "I'm not sure what yer doin' here, but ye have my thanks. If ye want to get any further, though, ye'll need to get past that foul dog, Guarm. I've tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm's mean, ye see, but not too smart. What do ye say? Think ye can take on a few kvaldir?", ["objectivesText"] = "Collect 20 pieces of seaweed from Kvaldir Mistcallers and Soulflayers in Helheim . Progress: Do ye have enough for a proper disguise?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 122619, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38342] = { ["id"] = 38342, ["name"] = "Another Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Well, the bridge option is out. You still got that grapple launcher handy? It looks like we can get across from the top of that tower over there. First thing's first, though, we'll need to deal with the big ugly sitting out front. You take point.", ["objectivesText"] = "Defeat Gunnlaug Scaleheart in Hrydshal, then climb to the top of the tower. Progress: Well, we made it this far...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91553, ["x"] = 0.462, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38347] = { ["id"] = 38347, ["name"] = "Stealth by Seaweed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "There! The disguise be complete! Don't mind the smell, there. It's probably better that we smell like the kvaldir, as well. Though I have a feeling I'll be needin a priest to get this stench out once we're gone.", ["objectivesText"] = "Use the Kvaldir Disguise to sneak by Guarm . Progress: Gods, what is that stench?! This disguise had better work!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 122124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38357] = { ["id"] = 38357, ["name"] = "Side Effects May Include Mild Undeath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38357, 38358 }, ["description"] = "Exposure to this particular \"byproduct\" is quite nasty. Rapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life. As you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well... Anyway, good luck!", ["objectivesText"] = "Slay 10 Volatile Bears or Volatile Sailors . Progress: Come now, surely you don't intend to leave them in this state? Have you no compassion? How about money - you like money, don't you?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91590, ["x"] = 0.36, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91590, ["x"] = 0.36, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5928, ["name"] = "Experiments of the Royal Apothecary Society", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38358] = { ["id"] = 38358, ["name"] = "Pump it Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38357, 38358 }, ["description"] = "The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... \"byproducts\" onboard. Regrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast. The R.A.S. must remedy this situation before we press further inland. Please take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.", ["objectivesText"] = "Fill the Containment Unit with Volatile Waste. Progress: There's still room in that containment unit .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 34077, 122702, 123919, 124124, 134554, 134555, 134556, 134557, 134558, 134559, 134560, 134561, 137721, 153741, 153742, 153796, 153797, 153802, 153803, 153817, 153818, 153862, 153863, 153908, 153909, 153927, 153928, 153948, 153949, 153995, 153996, 154011, 154012, 154114, 154115, 154745, 154746, 181501, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181652, 181653, 181654, 181656, 181657, 181659, 181675, 181676, 181677, 181681, 181689, 184305, 184772, 184773, 184774, 184775, 184776, 194533, 194534, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91590, ["x"] = 0.36, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91590, ["x"] = 0.36, ["y"] = 0.274 }, { ["mapID"] = 634, ["npcID"] = 91693, ["x"] = 0.375, ["y"] = 0.217 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5928, ["name"] = "Experiments of the Royal Apothecary Society", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38360] = { ["id"] = 38360, ["name"] = "The Windrunner's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38332, 38360, 38361, 38362, 38459 }, ["series"] = { 38332, 38362 }, ["description"] = "Finding Sylvanas is our only priority! We will cover more ground if we split up. I will lead a team into the hills above the enemy's camp while you search the wreckage itself for any signs of the crew. Once we've cleared the high ground, I will meet you at the far end of the beach.", ["objectivesText"] = "Search the wreckage of the Windrunner and the nearby coastline for signs of Sylvanas.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.391, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 127, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 127, ["name"] = "The Forsaken Fleet", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38361] = { ["id"] = 38361, ["name"] = "Wrath of the Blightcaller", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38332, 38360, 38361, 38362, 38459 }, ["description"] = "The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion! Like my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, <class>, and know that I am doing the same. When next we meet, I expect to see blood upon your hands.", ["objectivesText"] = "Slay 15 7th Legion Paratroopers or Skyfire Gryphon-Riders. Progress: I have no use for soft buffoons! Begone if you haven't the stomach for vengeance!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.391, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 127, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 127, ["name"] = "The Forsaken Fleet", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38362] = { ["id"] = 38362, ["name"] = "A Grim Trophy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38332, 38360, 38361, 38362, 38459 }, ["series"] = { 38332, 38360 }, ["description"] = "It would seem Sylvanas does not wish to be followed - by us or anyone else. Her will is her own, it is not my place to question. Only to obey. In the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him. I will have his head when this is over.", ["objectivesText"] = "Take the Head of Thane Wildsky . Progress: Do you have his head?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121498, 121499, 121500, 121501, 122746, 129302, 129303, 129304, 129305, 237812, 246937 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91158, ["x"] = 0.391, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.391, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 127, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 127, ["name"] = "The Forsaken Fleet", ["orderIndex"] = 3, ["flags"] = 0 } } },
