[38376] = { ["id"] = 38376, ["name"] = "The Search for the Highlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["series"] = { 38566, 38576, 38933, 39756, 42811, 42812 }, ["description"] = "Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment. Give the word and we'll set off. We're ready when you are.", ["objectivesText"] = "Recover Tirion Fordring and the Ashbringer from the Broken Shore. Progress: <Maxwell's eyes seem to struggle to meet your own.>", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38377] = { ["id"] = 38377, ["name"] = "The Emerald Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["series"] = { 38148, 38322, 38323, 40573 }, ["description"] = "<name>, you have returned. Good. I have counseled with the other archdruids and concluded that Cenarius' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear. We need help. There is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.", ["objectivesText"] = "Speak to Malfurion when ready.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 71086, 132279, 132280, 132281, 132282, 132283, 132284, 132285, 132286, 132287, 132288, 132289, 132290, 132294, 132295, 132296, 132297, 132298, 132299, 132302, 132303, 141387, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100387, ["x"] = 0.525, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38381] = { ["id"] = 38381, ["name"] = "Archdruid of Lore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38225, 38235, 38381, 44106 }, ["description"] = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore. Seek him out and tell him that he is desperately needed here.", ["objectivesText"] = "Seek out Elothir in Thas'talah.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91651, ["x"] = 0.518, ["y"] = 0.64 }, { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 187, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 187, ["name"] = "Archdruid of Lore", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38382] = { ["id"] = 38382, ["name"] = "Archdruid of the Vale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 39383, 39384 }, ["description"] = "Deep within our forest lies Moonclaw Vale. There you will find a reclusive group of feral druids charged with the protection of Val'sharah from any that would seek to disrupt the balance of nature. These druids are led by Thaon Moonclaw , the most fierce of the Archdruids. Seek him out. Let him know that Cenarius is in need of his aid.", ["objectivesText"] = "Speak with Thaon Moonclaw .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91651, ["x"] = 0.518, ["y"] = 0.64 }, { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95395, ["x"] = 0.61, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38384] = { ["id"] = 38384, ["name"] = "Nature's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38384, 40122 }, ["description"] = "What vile power is this?! A curse with the strength to paralyze a demigod? Unimaginable! Quickly, <name>, you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor. I will remain here and lend Cenarius what aid I can. Return to Lorlathil and speak with Aranelle . She will know the archdruids' whereabouts. And please, friend, make haste...", ["objectivesText"] = "Speak to Aranelle in Lorlathil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 35929, 35930, 35931, 35937, 141618, 141619, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 184, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 184, ["name"] = "Nature's Call", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38405] = { ["id"] = 38405, ["name"] = "To Weather the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I've been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They've got some specialized gear for it, so while we're here we should take some. I'd recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones , which seem to keep the lightning at bay. You should probably grab one of those, too.", ["objectivesText"] = "Collect Climbing Treads , an Oiled Cloak , and an Enchanted Lodestone from Hrydshal. Progress: Did you find everything?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121567, 122685, 122686, 124038, 129317, 129318, 129319, 198610, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91481, ["x"] = 0.424, ["y"] = 0.647333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91519, ["x"] = 0.438, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.647333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38407] = { ["id"] = 38407, ["name"] = "Bottled Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37495, 37496, 37507, 37510, 37528, 37536, 37538, 37542, 37565, 37566, 38407 }, ["series"] = { 37496, 37507 }, ["description"] = "<You've found a message in a bottle on the corpse. It's a request for aid from someone named Okuna Longtusk. Okuna claims that he and his fellow shipmates are being held prisoner by sea giants. Maybe if you show the note to the ghost of Lady Irisse at the Crumbled Palace, she can point you in the right direction?>", ["objectivesText"] = "Take Okuna's Message to Lady Irisse . Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 175, ["rewardItems"] = { 122699, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 88798, ["x"] = 0.47, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5754, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5754, ["name"] = "Against the Giants", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 122699 } },
[38410] = { ["id"] = 38410, ["name"] = "Impalement Insurance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I've got bad news. Those harpoon launchers up on the walls might cause us some problems. They can't get at us down here, but once you start climbing that path, they're likely going to try to skewer you. If you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!", ["objectivesText"] = "Grapple on top of the walls in Hrydshal and dismantle 7 Tideskorn Harpoon Launchers .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 122701, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91519, ["x"] = 0.438, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91553, ["x"] = 0.462, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38412] = { ["id"] = 38412, ["name"] = "Above the Winter Moonlight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "You should have a good vantage from this tower to grapple over to the mountain path. I can't help you once you're across, but you should be able to take it all the way up to the top. I hope you're able to find what you need from the dragons up there. Who knows what the God-King has done to them.", ["objectivesText"] = "Grapple across from the tower and climb to the top of the mountain path.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38413] = { ["id"] = 38413, ["name"] = "Wings of Liberty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured. Even now they work to corrupt my brothers and sisters to turn them to their side. Please, outsider, free them from this fate!", ["objectivesText"] = "Free Aleifir, Hrafsir, Erilar and Hridmogir in Thorim's Peak. Progress: What news do you bring of my brothers and sisters?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121515, 121516, 121517, 121518, 129324, 129325, 129326, 129327, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 }, { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38414] = { ["id"] = 38414, ["name"] = "Heart of a Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, <class>. With the aid of fel powers such as I've never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King's will. Find her and free her from the demon's grasp - only then might the Thorignir regain our power and grant you aid.", ["objectivesText"] = "Find and rescue the mother of the Thorignir brood. Progress: Have you found our brood-mother?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 }, { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38443] = { ["id"] = 38443, ["name"] = "Journey to the Repose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37853 }, ["description"] = "For now, the Illidari can hold the line against the Legion. We will return later to help them drive the Legion from the upper reaches of Faronaar. You and I must concentrate on the Pillars of Creation if the Tomb of Sargeras is to be resealed. Your saving of Stellagosa is fortuitous. Surely if anyone knows where a Pillar of Creation is, it will be her grandfather, Senegos. The Azurewing Repose is to the northeast. I will meet you there, <name>.", ["objectivesText"] = "Speak with Archmage Khadgar at the Azurewing Repose.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93326, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93354, ["x"] = 0.48, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38455] = { ["id"] = 38455, ["name"] = "Frenzied Furbolgs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["description"] = "I would help you seek audience with the Archdruid, but we have a difficult situation on our hands. The nearby furbolgs have gone into a frenzied rage. For days, it has been all we can do to protect our grove from their aggression. They have cut off our access to the barrow dens, where the Archdruid and our clan sleep in the Emerald Dream. In order to awaken them, we must first get past the furbolg.", ["objectivesText"] = "Kill 8 Smolderhide furbolgs.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 73426, ["x"] = 0.49, ["y"] = 0.822 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 73426, ["x"] = 0.49, ["y"] = 0.822 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.822 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38459] = { ["id"] = 38459, ["name"] = "The Ancient Trials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38332, 38360, 38361, 38362, 38459 }, ["description"] = "<As the raven stares into your eyes, an odd voice fills your mind.> I know who you are, champion, and I know what you seek. Come to me, if you think yourself truly worthy.", ["objectivesText"] = "Find Havi near Aggramar's Vault.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97305, ["x"] = 0.368, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 127, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 127, ["name"] = "The Forsaken Fleet", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38460] = { ["id"] = 38460, ["name"] = "Let's Make A Deal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38232, 38237, 38460, 42238 }, ["description"] = "Hey there! You seem like a gullib- er... um... \"intelligent\" type. I propose a deal. I need a minion to be my muscle to help me acquire a few special... \"ingredients\" for a ritual. In exchange, I'll give you my former master to do with whatever you demon-slaying types do with demons. If you are interested, just sign here. In blood, please.", ["objectivesText"] = "Sign Daglop 's contract. Progress: Yeah! Yeah! You read the contract? I made it myself. Really good binding clauses in there.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 138878, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91166, ["x"] = 0.622, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91166, ["x"] = 0.622, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5762, ["name"] = "Minion's Minion", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38473] = { ["id"] = 38473, ["name"] = "Will of the Thorignir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "In the summit of storms the dragons await. Born of the gods, they will test your will. They roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit. A friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", ["objectivesText"] = "Meet with Lorna Crowley outside of Hrydshal to begin the trial of the Thorignir.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91222, ["x"] = 0.374, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38499] = { ["id"] = 38499, ["name"] = "Strange New Ores", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 39681 }, ["description"] = "You smell that, smith? Ahhhh... that there's the smell of opportunity. Dalaran's taken us to some strange new shores, filled with mysterious metals. I'm tethered to my shop here, but you... you've got the freedom to explore and mine at will. Bring me something interesting, and we'll see what we can make with it.", ["objectivesText"] = "Obtain 10 Leystone Ore . Progress: Come up with anything interesting?", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680, 139493, 140225 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38500] = { ["id"] = 38500, ["name"] = "Leysmithing Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "Well, now that we have the flux we can put it to work and see how it goes. Why don't you take a crack at it this time and make some gauntlets for me. I'll observe your work... from a distance.", ["objectivesText"] = "Follow Alard Schmied 's recipes in your Blacksmithing recipe list to build some Handcrafted Leystone Gauntlets. Progress: Did it work? I haven't heard an explosion yet.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124005, 124007, 124008, 124009, 124010, 124049, 124051, 124103, 124436, 124462, 128777, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38502] = { ["id"] = 38502, ["name"] = "The Methods of the Nightfallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38505, 38506, 38507, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "I have a theory, <name>. Have you encountered the nightfallen elves of Azsuna? They descend from the Highborne, and the accomplishments of Highborne smiths are legendary. These fallen elves do a bit of arcane tinkering, crafting sentries to patrol their camps. Bring me a memory core from one of their constructs. Who knows what manner of smithlore might lie within!", ["objectivesText"] = "Obtain an Ancient Sentry Construct Memory Core . Progress: Hopefully we can extract something useful.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 123976, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38506] = { ["id"] = 38506, ["name"] = "Chicken Scratch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38507, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "I think I have just the thing to extract the information from this core for you. <Timofey loads the core into the hopper of a clearly goblin-made machine, then covers his ears.> You may wish to avert your eyes, blacksmith.", ["objectivesText"] = "Bring the Ancient Highborne Data Printout to Professor Pallin in Dalaran. Progress: Highborne! Ancient Highborne! What an amazing find!", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 123978, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38507] = { ["id"] = 38507, ["name"] = "Secrets of Leysmithing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "I could spend hours poring over the details of this fascinating manuscript! ...is what I would say if this weren't the simplest of tasks for someone of my skill level. It's about something called \"Leysmithing\". Here. <The gnome scribbles down a translation on the back of the scroll.> There it is, word-for-word. Bring me something interesting next time.", ["objectivesText"] = "Bring the Leysmithing Guide to Alard Schmied in Dalaran. Progress: Did you find the engineering shop?", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 123979, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38513] = { ["id"] = 38513, ["name"] = "The Highmountain Smiths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38514, 38515, 38563, 39699 }, ["description"] = "I think we've gone as far as we can go with what I know, <name>. The tauren of Highmountain must have some smiths among their ranks. See if you can find out how to further progress our leysmithing abilities from them.", ["objectivesText"] = "Speak with Barm Stonebreaker in Highmountain.", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123933, 123934, 123935, 123957, 124103, 124436, 124461, 124462, 137680 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38514] = { ["id"] = 38514, ["name"] = "You Are Not Worthy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38515, 38563, 39699 }, ["description"] = "You wish me to teach you how to strengthen your crafts? We do not simply share the secrets of our trade with outsiders who ask for them. We do, however, respect craftsmanship and discipline. Let's see your hammerwork. Our greenhorn trainees use those small anvils over there. Craft your best pair of gauntlets so I may judge your work.", ["objectivesText"] = "Use your blacksmithing skill to craft a pair of Leystone Gauntlets for Barm. Progress: I'm waiting, outsider.", ["rewardGold"] = 140450, ["rewardXP"] = 1415, ["rewardItems"] = { 44987, 45192, 73237, 73238, 73239, 73242, 98134, 123893, 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680, 180847, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181708, 181842, 182126, 182338, 182460, 182480, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 184147, 184150, 184587, 184777, 191784, 205983, 205985, 210421, 210872, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38515] = { ["id"] = 38515, ["name"] = "Nature Provides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38563, 39699 }, ["description"] = "This is interesting, it says that leystone reacts violently with anything it views as a contaminant. Our foreign-mined flux was enough to cause the small explosion. Local ingredients, however, have learned to coexist with leystone. Up in Highmountain, an herb called foxflower grows that can be turned into a suitable flux. Go and gather some foxflower that we can turn into a usable flux.", ["objectivesText"] = "Obtain 10 Foxflower . If you are not an herbalist, you can purchase Foxflower on the Auction House, or you can obtain it from another player. Progress: How goes the search for foxflower ?", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680, 140222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38518] = { ["id"] = 38518, ["name"] = "From One Master to Another", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "Now young one, go back to your master in Dalaran and continue to practice your swing. We'll always be here if you wish to come back and learn more.", ["objectivesText"] = "Go back to Alard in Dalaran and share what you've learned from the Tauren.", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 14, ["flags"] = 0 } } },
[38523] = { ["id"] = 38523, ["name"] = "Leystone Hoofplates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "Here, bring these hoofplates to Mei Francis, down at the mounts and pets store, to get your mount properly shod. I'll share the pattern when you return.", ["objectivesText"] = "Approach Mei Francis in Dalaran while mounted to have your Leystone Hoofplates fitted.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 16, ["flags"] = 0 } } },
[38524] = { ["id"] = 38524, ["name"] = "Felsmith Nal'ryssa", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "Word has been circulating in smithing circles about a pair of Illidari blacksmiths that have been doing exciting work out on the demon-infested front lines of Suramar. I'd follow up myself, but anything described as \"demon-infested\" is a little too exotic for my tastes. I just make the armor. I prefer not to wear it. You, though... you could follow up on this tip. Be on the lookout for Nal'ryssa. From what I hear, she's a hell of a smith.", ["objectivesText"] = "Report to Felsmith Nal'ryssa in Suramar.", ["rewardXP"] = 770, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 22, ["flags"] = 0 } } },
[38525] = { ["id"] = 38525, ["name"] = "Part of the Team", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "You're a blacksmith? <The elf looks down at your hammer.> Still working in leystone, are you? I might be able to help you out. Alliances out here are hard-won. You've got a pretty face, but that's no guarantee that you aren't working for the demons. I can't afford to trust you yet. Don't come back until you're caked in demon's blood. Then we'll talk smithing.", ["objectivesText"] = "Slay 40 demons within Felsoul Hold.", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680, 141022 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 23, ["flags"] = 0 } } },
[38526] = { ["id"] = 38526, ["name"] = "Smith Under Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "You lack recipes for boots? What, were you trained by a tauren or something? Hurry up, then. We probably have a few minutes before the demons attack again. Here's a pattern - show me your work.", ["objectivesText"] = "Follow Felsmith Nal'ryssa 's instructions to craft Leystone Boots. Progress: Watch your step out here on the front lines. This isn't your peaceful floating city's blacksmithing shop.", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124425, 124426, 124427, 124428, 124429, 124433, 124436, 124462, 137680 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 24, ["flags"] = 0 } } },
[38527] = { ["id"] = 38527, ["name"] = "Nal'ryssa's Technique", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "Listen, <class>. We need smiths like you to carry on the traditions of the Illidari, should we fail in our crusade against the Legion. You are ready to learn. Bring me materials. Lots of them. When you return, we will have much to discuss.", ["objectivesText"] = "Obtain 60 Leystone Ore and 60 Felslate . Progress: Are you ready to learn?", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 25, ["flags"] = 0 } } },
[38530] = { ["id"] = 38530, ["name"] = "The Firmament Stone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "When working with felslate and demonsteel, one must use special equipment. Specifically, an anvil hard enough to withstand the energy given off when felslate is hammered. Urael and I no longer possess such an anvil. But your friends, the Highmountain tauren, do. Gain access to the Firmament Stone, their sacred anvil, and we can start working with demonsteel again.", ["objectivesText"] = "Speak with Barm Stonebreaker in Highmountain.", ["rewardXP"] = 770, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124024, 124103, 124436, 124462, 137680, 156833 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 650, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 27, ["flags"] = 0 } } },
[38531] = { ["id"] = 38531, ["name"] = "Leystone Mastery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38532, 38533, 38559, 38833 }, ["description"] = "Smiths that seek access to the Firmament Stone must first prove complete mastery over leystone. Craft an entire set of Leystone Armor, then submit it to me for inspection. Thala can provide you with an armor stand.", ["objectivesText"] = "Speak with Thala Steeltotem to purchase a Leystone Armor Stand, then hang all eight pieces of Leystone Armor on it. Progress: Remember, <name>: I do not tolerate sloppy work.", ["rewardXP"] = 6140, ["rewardItems"] = { 123891, 123892, 123893, 123894, 123895, 123896, 123897, 123898, 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124023, 124024, 124103, 124436, 124462, 136696, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 28, ["flags"] = 0 } } },
[38533] = { ["id"] = 38533, ["name"] = "Tribal Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38531, 38532, 38559, 38833 }, ["description"] = "First, however, you'll need proper patterns for demonsteel armor. While access to the stone is earned through hard work and perseverance, access to our recipes is limited to the trusted members of our tribe. Perhaps you should seek another smith if you wish to discuss demonsteel patterns.", ["objectivesText"] = "Report back to Felsmith Nal'ryssa in Suramar.", ["rewardXP"] = 6140, ["rewardItems"] = { 123910, 123911, 123912, 123913, 123914, 123915, 123916, 123917, 123918, 123919, 123920, 123924, 123928, 123929, 123934, 123935, 123944, 123945, 123952, 123957, 124103, 124113, 124115, 124124, 124125, 124436, 124437, 124438, 124439, 124440, 124444, 124461, 124462, 130179, 136696, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92243, ["x"] = 0.545, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650, 680 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 32, ["flags"] = 0 } } },
[38558] = { ["id"] = 38558, ["name"] = "See Ya Later, Oscillator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 }, ["series"] = { 38053, 38057, 38058, 38059, 38060 }, ["description"] = "Those jawless mooks are actually trying to salvage parts from our ship! They can't possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations. In any case, I need a crystal oscillator for our new transponder. It's the shiniest part of the whole system, they're bound to have it set aside somewhere!", ["objectivesText"] = "Collect the Crystal Oscillator . Progress: Did you find the oscillator?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 123887, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 90866, ["x"] = 0.336, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 128, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 128, ["name"] = "Wreck of the Skyfire", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38559] = { ["id"] = 38559, ["name"] = "Worthy of the Stone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38531, 38532, 38533, 38833 }, ["description"] = "You have nothing more to prove to me, <name>. Your training is complete. Only a very small herd of smiths have earned the right to the Firmament Stone. You should speak with Muirn Ironhorn , who maintains vigil over our sacred stone. He will tell you what to do next.", ["objectivesText"] = "Speak with Muirn Ironhorn .", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 136696, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92243, ["x"] = 0.545, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 30, ["flags"] = 0 } } },
[38563] = { ["id"] = 38563, ["name"] = "Flower-Pickers and Potion-Quaffers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 39699 }, ["description"] = "Now that we know the foxflower flux is safe to use, we can start stocking it. That being said, I don't particularly feel like picking flowers. Do you feel like picking flowers? Didn't think so. Go talk to the alchemists and herbalists across the way. I'm sure we can set up some sort of work order arrangement.", ["objectivesText"] = "Speak with Linzy Blackbolt and Kuhuine Tenderstride to secure a work order for Foxflower Flux. Progress: Have you spoken with the alchemists and herbalists yet?", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38566] = { ["id"] = 38566, ["name"] = "A United Force", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38576, 38933, 39756, 42811, 42812 }, ["description"] = "The paladins of Azeroth must stand united behind a single leader. With Tirion's passing, you are the one most worthy to wear the mantle of Highlord. If you agree to accept this duty, inscribe your name into the Libram of Ancient Kings and I will address the masses on your behalf. The Order of the Silver Hand is reborn, with you as its champion!", ["objectivesText"] = "Establish the Order of the Silver Hand using the Libram of Ancient Kings. Progress: Yes, Highlord?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38576] = { ["id"] = 38576, ["name"] = "We Meet at Light's Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38933, 39756, 42811, 42812 }, ["description"] = "With you on our side, I know the Legion will fall! But before we march on the Broken Isles, we must put Highlord Tirion to rest. There is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel. Paladins the world over are on their way to the ceremony. I know Tirion would want you there most of all.", ["objectivesText"] = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38582] = { ["id"] = 38582, ["name"] = "To Old Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "I sense a powerful dark presence here, <name>, but it is not of Xavius. This feels too familiar. I sense a druid's touch here, a druid twisted by the shadow of the Nightmare. We must deal with this threat if we are to find Xavius. I will take to the skies and lend you my aid. Find this corrupted druid and cut down his tainted and twisted plants.", ["objectivesText"] = "Kill 50 Corrupted Creatures in Moonrest.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121594, 121595, 121596, 121597, 129986, 129994, 130002, 130013, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92420, ["x"] = 0.605333, ["y"] = 0.614667 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92710, ["x"] = 0.65, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.605333, ["y"] = 0.614667 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38595] = { ["id"] = 38595, ["name"] = "Malfurion's Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "The loss of Cenarius to the nightmare is a devastating blow to us all. Though Malfurion's rage is justified, his hatred of Xavius has burned for centuries and I fear that his blind rage will be used as a weapon against him. May Elune guide us in our search for him, lest we have yet another friend to mourn today.", ["objectivesText"] = "Speak with Ysera to search for Malfurion.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92742, ["x"] = 0.524667, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92420, ["x"] = 0.605333, ["y"] = 0.614667 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38611] = { ["id"] = 38611, ["name"] = "Will of the Thorignir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "In the summit of storms the dragons await. Born of the gods, they will test your will. They roost above Hrydshal, where their children serve the Drekirjar. But they are no allies to man or vrykul, and so you must earn their blessing as they see fit. A friend of yours awaits in Hrydshal, no doubt searching for the answers you now possess. Go to her, and together, you will test your might against the storm!", ["objectivesText"] = "Meet with Dread-Rider Cullen outside of Hrydshal to begin the trial of the Thorignir.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92561, ["x"] = 0.448, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38612] = { ["id"] = 38612, ["name"] = "A Grapple a Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "So some old magic vrykul is helping us out? I guess that's good, but this trial of yours might be tricky. You see, the only way up that mountain, is through those big walls. You know, the ones with the mean-looking drakes on them. I scouted a bit, but couldn't get too far without those drakes trying to make lunch out of poor Duchess. The vrykul have them trained, which can't be good. I say we sneak in. I managed to snag a few grapple launchers earlier. Grab one and meet me outside the city walls.", ["objectivesText"] = "Pick up a Stormforged Grapple Launcher and meet Dread-Rider Cullen outside the wall of Hrydshal.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138111, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92561, ["x"] = 0.448, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92566, ["x"] = 0.460667, ["y"] = 0.677333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38613] = { ["id"] = 38613, ["name"] = "No Wings Required", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "That thing looks like it's got the range to get us over the wall. There's a good spot to hook onto right past us - you should be able to spot it from here. Once you're inside, do me a favor and see if you can distract the guards so I can slip through. I'll see what else I can find out about these vrykul.", ["objectivesText"] = "Use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92566, ["x"] = 0.460667, ["y"] = 0.677333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92567, ["x"] = 0.436, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.677333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38614] = { ["id"] = 38614, ["name"] = "To Weather the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "When I was scouting this place out, I noticed the vrykul here are no strangers to the treacherous mountain path we're trying to get to. They've got some specialized equipment they're using, and if I were you I'd try to get my hands on some. You'll want to find some climbing treads to keep your grip and an oiled cloak to keep you dry. They've also got these stones they carry to keep the lightning at bay, so you'll want to pick one of those up as well.", ["objectivesText"] = "Collect Climbing Treads , an Oiled Cloak , and an Enchanted Lodestone from Hrydshal. Progress: Were you able to get all the gear you needed?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121567, 122685, 122686, 124038, 129317, 129318, 129319, 198610, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92566, ["x"] = 0.460667, ["y"] = 0.677333 }, { ["mapID"] = 634, ["npcID"] = 92567, ["x"] = 0.436, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92567, ["x"] = 0.436, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.677333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38615] = { ["id"] = 38615, ["name"] = "Impalement Insurance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "It looks like the elements aren't the only thing you'll need to worry about going up that path. Those harpoon launchers on the wall look pretty nasty, and unless we take them out first, they're likely to make short work of anyone trying to scale that path. They're up on top of the walls, so you'll need to use that grapple launcher to get to them. Just try not to end up drake food!", ["objectivesText"] = "Grapple on top of the walls and dismantle 7 Tideskorn Harpoon Launchers atop in Hrydshal.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 122701, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92567, ["x"] = 0.436, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92573, ["x"] = 0.47, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38616] = { ["id"] = 38616, ["name"] = "Built to Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38616 }, ["description"] = "The vrykul around here seem to use scales from these drakes to fashion their armor. If you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", ["objectivesText"] = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal. Progress: What have we here?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121519, 121520, 121521, 121522, 122609, 129320, 129321, 129322, 129323 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92561, ["x"] = 0.448, ["y"] = 0.592 }, { ["mapID"] = 634, ["npcID"] = 92566, ["x"] = 0.460667, ["y"] = 0.677333 }, { ["mapID"] = 634, ["npcID"] = 92567, ["x"] = 0.436, ["y"] = 0.678 }, { ["mapID"] = 634, ["npcID"] = 92568, ["x"] = 0.448, ["y"] = 0.592 }, { ["mapID"] = 634, ["npcID"] = 92573, ["x"] = 0.47, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 124037 } },
[38617] = { ["id"] = 38617, ["name"] = "Another Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Wait, do you still have that grapple launcher? I think you can still get to the path if you can launch from the top of that tower. The gap doesn't seem too bad there. Of course, we'll have to take out the big guy out front first. He looks tough, but I think we have a chance if we can flank him.", ["objectivesText"] = "Defeat the Drekirjar Champion in Hrydshal, then climb to the top of the tower. Progress: This should be a piece of cake!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92573, ["x"] = 0.47, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38618] = { ["id"] = 38618, ["name"] = "Above the Winter Moonlight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38413, 38414, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top. According to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", ["objectivesText"] = "Grapple across from the tower and climb to the top of the mountain path.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92568, ["x"] = 0.448, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38624] = { ["id"] = 38624, ["name"] = "Cry Thunder!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. The dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Be they Felskorn or not, their malice has caused suffering to my brood. Their toll must be paid in blood. Speak to Vethir when you are ready.", ["objectivesText"] = "Fly with Vethir and kill 150 of the God-King's allies in Hrydshal.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 71076, 237812, 246937 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97074, ["x"] = 0.48, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38641] = { ["id"] = 38641, ["name"] = "The Temple of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "Cenarius is in danger. If his condition is not reversed soon, he will be lost to the Nightmare that threatens the Emerald Dream. To spare him that fate, we must have the Tears of Elune - the same relic you were sent here to retrieve. Elune's temple is not far. Go there. Find Lyanis. Show her my seal and instruct her to release the tears into your custody. Hurry, <name>. Time is short.", ["objectivesText"] = "Speak with Lyanis Moonfall at the Temple of Elune. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127273, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98584, ["x"] = 0.525, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92680, ["x"] = 0.515, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38643] = { ["id"] = 38643, ["name"] = "A Village in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "The corpse of Darcy Heathrow lies before you pierced by several arrows and knife wounds. In one hand she clutches a note, written with a feeble hand, that reads: \"The dead march on Bradensbrook. Help us, please!\"", ["objectivesText"] = "Speak to Mayor Heathrow at Bradensbrook.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92688, ["x"] = 0.548, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92619, ["x"] = 0.424, ["y"] = 0.59 }, { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38644] = { ["id"] = 38644, ["name"] = "The Farmsteads", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Forgive us, stranger. Mayor Heathrow has been under a lot of stress recently. I can't blame him: his own daughter, Penelope, has been missing for two days. In fact, we could use information on several farmsteads to the south: Mayor Heathrow 's house, Granny Marl's farm, and the Radcliffes' dock. Can you go check on the situation out there? Help us, and perhaps the mayor's heart will soften.", ["objectivesText"] = "Check on the Heathrow house, Granny Marl's farm, and the Radcliffes' fishing dock. Progress: How does it look out there?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121581, 121582, 121583, 121584, 129991, 129999, 130007, 130018, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92683, ["x"] = 0.422, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92619, ["x"] = 0.424, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38645] = { ["id"] = 38645, ["name"] = "Children of the Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "I am no enemy to these people, but there is no convincing them of that. Their village has come under attack by some very old friends of mine. Friends who are no longer... living. There's no telling who or what controls them, but in life these noble soldiers would never engage in such acts. That's a mystery for another time. For now, help me earn the trust of these villagers. Strike down the Black Rook enemies who are terrorizing their citizens.", ["objectivesText"] = "Kill 12 Risen Assassins , Black Rook Falcons , or Risen Hounds . Progress: The attackers are night elves, yes, but they are not the same night elves I once knew.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92620, ["x"] = 0.424, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92620, ["x"] = 0.424, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38646] = { ["id"] = 38646, ["name"] = "A Sight For Sore Eyes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Do you see those ravenous birds flying above my farm? Vicious creatures are spreading their filth an' eatin' my crops. I'd get rid of them with my trusty gun, but my eyesight's gone downhill. Take this flare gun and mark them for me. Once I get my sights on them, I'll make 'em scatter.", ["objectivesText"] = "Use Granny's Flare Gun to mark 6 Black Rook Falcons. Progress: Heh? Is that you again?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127030, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92618, ["x"] = 0.388, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92618, ["x"] = 0.388, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38647] = { ["id"] = 38647, ["name"] = "For the Corn!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "I've got a full summer's corn harvest just sittin' out in the field. I need some muscle to bring it in before the night elf raiders can destroy it. Get out there and bring me those crops, and I'll reward you handsomely. The folks back in town need this food, and I sure as heck ain't eating rats for another winter.", ["objectivesText"] = "Collect 5 Barrels of Corn . Progress: The corn isn't gonna gather itself.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 59765, 59766, 59767, 127005, 165871, 237812, 265995 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92618, ["x"] = 0.388, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92618, ["x"] = 0.388, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38649] = { ["id"] = 38649, ["name"] = "Silence in the City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38695, 45260, 45271 }, ["description"] = "There is a troubling silence from Suramar City this day. Oculeth just informed me that the teleporter to the Waning Crescent has gone dark. He is not able to reach Vanthir, nor am I. While I am hesitant to believe something dire has happened, I do feel this warrants investigation. Speak with Oculeth and see if he can transport you to the Waning Crescent. We need to find out what happened.", ["objectivesText"] = "Speak to Chief Telemancer Oculeth .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38655] = { ["id"] = 38655, ["name"] = "Root Cause", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "The massive roots of Shaladrassil are spreading a horrible corruption throughout the forest. If we are to save Val'sharah , we will need to find a way to stop the encroachment of the world tree. If you bring me enough corrupted root samples , I may be able to discover their secrets.", ["objectivesText"] = "Collect 30 Corrupted Root Samples . Progress: Have you collected the root samples?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 35921, 35922, 35923, 35924, 128680, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92697, ["x"] = 0.522, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92697, ["x"] = 0.522, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38656] = { ["id"] = 38656, ["name"] = "Mark of the Demon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "The demonic rune glows in your hand, emanating dark power. A single word, inscribed in demon tongue, glows coldly... ...GRAVAX...", ["objectivesText"] = "Return the Demonic Emblem to Isoraen Nightstar at the Temple of Elune.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124131 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92697, ["x"] = 0.522, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 7, ["flags"] = 1 } }, ["startItems"] = { 124131 } },
[38660] = { ["id"] = 38660, ["name"] = "Cleansing the Corruption", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38660 }, ["description"] = "All along the battlefield, the satyrs have erected dark totems that spread the corruption of the Emerald Nightmare upon the land. As long as the Nightmare totems remain, we will not be able to hold back the corruption! If you truly wish to aid us in the fight, destroy the totems that you encounter upon the battlefield. Our survival depends on it!", ["objectivesText"] = "Destroy 6 Nightmare Totems on the Battlefield.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38662] = { ["id"] = 38662, ["name"] = "Tears for Fears", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "The Tears of Elune are a sacred artifact, protected by my order for thousands of years. I tell you this so that you may understand the gravity of your request. That said, Ysera is noble and wise and I trust in her guidance. You will find the tears in a vault at the eastern edge of the temple grounds. Proceed with caution though, as that area has been overrun by demons.", ["objectivesText"] = "Retrieve the Tears of Elune. Progress: Do you have the Tears of Elune?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121641, 121647, 121649, 121651, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92680, ["x"] = 0.515, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92680, ["x"] = 0.515, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38663] = { ["id"] = 38663, ["name"] = "The Die is Cast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "Thanks to your efforts the temple is safe, for now. But the Tears of Elune are stolen and Shaladrassil, the world tree that once protected this land, is now an instrument in the hands of our enemy. The Emerald Dream itself is being overrun by Nightmare. The hearts of our people falter, their faith tested like never before. Return to Ysera with my report, <name>, such as it is. I shall plead with Elune with what time I have left here. May we somehow yet prevail.", ["objectivesText"] = "Speak with Ysera at the Grove of Cenarius.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812, 245700 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92680, ["x"] = 0.515, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98584, ["x"] = 0.525, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38671] = { ["id"] = 38671, ["name"] = "Lost in Retreat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38671, 41707 }, ["description"] = "Is this the end? Our beloved Malfurion. I saw him in the Dreamer's clutches, but Ysera was... changed. Twisted. Shaladrassil, our mighty world tree, is corrupted beyond recognition. We were forced to flee our home without our belongings. Some were heirlooms, sacred to us. Return them to me if you can, <class>, I beg you.", ["objectivesText"] = "Retrieve 5 Shadowfen Heirlooms in Shadowfen. Progress: Have you retrieved them?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 136272, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94863, ["x"] = 0.694, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 94863, ["x"] = 0.694, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5764, ["name"] = "Shadowfen Sorrows", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38672] = { ["id"] = 38672, ["name"] = "Breaking Out", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 38668, 38669 }, ["description"] = "We cannot fight our way out of the Vault alone. Two of your allies, Kayn Sunfury and Altruis the Sufferer , are imprisoned within this room. Free them with haste. Their strength will be of great use to us.", ["objectivesText"] = "Free both Altruis the Sufferer and Kayn Sunfury . Progress: <The lever seems to control the door.>", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 31312, 31313, 31314, 31315, 37959, 38001, 38044, 38105, 38230, 38231, 38232, 65683, 65703, 65721, 112591, 112592, 112593, 112594, 131699, 132243, 142054, 175733, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 177657, 211279, 237812, 251221, 251222, 251228, 251234, 251235, 252258 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 17, ["flags"] = 0 } } },
[38675] = { ["id"] = 38675, ["name"] = "Heart of the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole. <Tyrande's expression hardens into a scowl as she peers at you.> Elune herself cannot protect Xavius if he is not.", ["objectivesText"] = "Track Malfurion's path through the Nightmare.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38684] = { ["id"] = 38684, ["name"] = "Reading the Leaves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "<name>, my friend. You must succeed where I have failed. You must find our dear Malfurion. As the Nightmare consumes my thoughts, I hear the voices of these twisted trees. I must cling to sanity long enough to aid you. Venture into Ash'theran and bring me Corrupted Petals from the fallen denizens there. With them, I might find your Archdruid while my mind is still my own.", ["objectivesText"] = "Collect 5 Corrupted Petals . Progress: Ahh... the fear! The panic! I haven't the strength to fight much longer...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 136391, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38687] = { ["id"] = 38687, ["name"] = "Close Enough to Touch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "He is near, <name>, I can feel it. We must scour this place in search of my husband. I fear if we do not find him soon it will be too late. You have been courageous throughout our search. I know you will not fail me now, <name>. Thank you, and please hurry.", ["objectivesText"] = "Search for Malfurion within Shala'nir.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104799, ["x"] = 0.578, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.427333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38689] = { ["id"] = 38689, ["name"] = "Fel Infusion", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "So many years of imprisonment has left us weak. The Vault is overrun with demons. Kill them and gather their souls to regain your strength.", ["objectivesText"] = "Infuse yourself with 100 energy from fallen demons.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 132243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 18, ["flags"] = 0 } } },
[38690] = { ["id"] = 38690, ["name"] = "Rise of the Illidari", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "Look down there. We are vastly outnumbered. We will need more allies on our side if we are to escape from here intact. Free the other Illidari imprisoned within the cells of this chamber. We will need everyone to escape this place alive.", ["objectivesText"] = "Free 8 Illidari Prisoners . Progress: Have you freed those you found in the cells?", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 132243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 19, ["flags"] = 0 } } },
[38691] = { ["id"] = 38691, ["name"] = "Jarod's Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["series"] = { 38718 }, ["description"] = "Since Maiev chased after Gul'dan at the Vault of the Wardens, her sisters among the Wardens have been searching far and wide for her whereabouts. With so few Wardens remaining, I volunteered to join the search. I hope I will find sign of her within Black Rook Hold. The fortress will be well guarded, and I will need help to break through. Help me find her, and I will reward you handsomely.", ["objectivesText"] = "Speak to Jarod Shadowsong at Ravencrest Mausoleum. Progress: Did you have any trouble getting here?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 141388, 237812, 246937 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92620, ["x"] = 0.424, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92842, ["x"] = 0.429333, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38692] = { ["id"] = 38692, ["name"] = "Answering Aggression", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38694, 38720 }, ["description"] = "I weep for the Nightborne this day. < Silgryn gestures out the door.> Elisande demonstrates the ultimate disdain for her people. So many lives... wasted! All to relay a message: This is what happens to those who defy her. <name>, my friend, we must answer her. We must show her that she cannot slay her people without retribution. Fight back, <name>.", ["objectivesText"] = "Kill 12 of Elisande's Forces in the Waning Crescent, Starcaller Retreat, and Siren's Vigil.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115018, ["x"] = 0.501333, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38694] = { ["id"] = 38694, ["name"] = "Regroup", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38692, 38720 }, ["description"] = "These people may be able to hold out here, but I know for certain that we cannot. Every moment we spend here places them in danger of Elisande's forces retaliating against us. We need to move. We need to find a place to regroup and recover. Follow me. I think I know how we can get out of here.", ["objectivesText"] = "Escape Siren's Vigil.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 90330, 90332, 90333, 90334, 90335, 90337, 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115018, ["x"] = 0.501333, ["y"] = 0.86 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.501333, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38695] = { ["id"] = 38695, ["name"] = "Crackdown", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38649, 45260, 45271 }, ["description"] = "Thalyssra is right to be concerned! The network has not responded to my attempts to re-establish connection with the Waning Crescent. I do not know what happened, but given the circumstances I believe it prudent to investigate in person. <name>, would you do the honors? I will send you as close to the Waning Crescent as I can.", ["objectivesText"] = "Investigate the events of the Waning Crescent. Progress: Elisande... how could you?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38710] = { ["id"] = 38710, ["name"] = "An Urgent Gathering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 40408 }, ["description"] = "A critical decision must be made, <name>. The Legion devastated our forces at the Broken Shore. The mightiest army this world has ever known was reduced to cinders in moments. We must gather those with the conviction to save our home. Travard of Tyr's Guard and Orik Trueheart have each made plans to do just that, but we must not let them walk alone. I ask that you seek them out and guide them to Krasus' Landing so that we may make this decision together.", ["objectivesText"] = "Gather Travard and Orik Trueheart , then meet Lord Maxwell Tyrosus at Krasus' Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 173537, 237812 }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38714] = { ["id"] = 38714, ["name"] = "Maiev's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "The fortress grounds are just up ahead. There is a large area to search, but if we split up, I believe we can cover a lot of ground. Search the prison cages, the forge, and the guard tower for any signs of Maiev. I will check the upper ramparts and meet you on the other side of the keep.", ["objectivesText"] = "Search the forge, the saber pens, and the guard tower. Progress: We will give this area a thorough search.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121602, 121603, 121604, 121605, 124412, 129983, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94977, ["x"] = 0.408, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92842, ["x"] = 0.429333, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38715] = { ["id"] = 38715, ["name"] = "The Rook's Guard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "Black Rook Hold is not the same place I knew. Its walls have crumbled, a ghostly echo of its former glory. If Lord Ravencrest has returned, then surely he will have his former officers at his side. Kester Farseeker , captain of the guard. Trelan Shieldbreaker , peerless master of maces. Starlys Strongbow , who could split arrows while blindfolded. If we stand any chance of entering the tower itself, they must be eliminated.", ["objectivesText"] = "Kill Kester Farseeker , Trelan Shieldbreaker , and Starlys Strongbow . Progress: Warriors and fighters came from across kaldorei lands to pledge loyalty to Master Ravencrest. We would have followed him to the ends of the earth.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94977, ["x"] = 0.408, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92842, ["x"] = 0.429333, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38716] = { ["id"] = 38716, ["name"] = "Black Rook Hold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38716 }, ["description"] = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest. The band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.", ["objectivesText"] = "Take the Warden's Signet to Jarod Shadowsong.", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["rewardItems"] = { 141176, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Black Rook forces thwarted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Destroy Weapons", ["amount"] = 34, ["type"] = 0, ["objectID"] = 93067, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[38717] = { ["id"] = 38717, ["name"] = "Black Rook Prison", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "I did not come this far to lose her in the final moments. Maiev must be in the cells beneath Black Rook Hold. I scouted above, and the entrance to the prison is guarded by a fearsome jailor. I will sneak past and take out the guards inside. Defeat Araxxas, take the keys, and then meet me within.", ["objectivesText"] = "Kill Araxxas and collect the Prison Keys . Progress: Do you have the keys?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127863, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92842, ["x"] = 0.429333, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118183, ["x"] = 0.39, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 642, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38718] = { ["id"] = 38718, ["name"] = "Kur'talos Ravencrest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["series"] = { 38691 }, ["description"] = "Lord Ravencrest was a fearless leader, a seasoned commander, a man of integrity and honor, a teacher, and a protector of his people. Malfurion, Illidan, Tyrande, and I... we were still young when he helped shape our destinies. The sigil of his house was legendary. Observe, for a moment, the sigil over his former resting place and I shall tell you more of his legacy.", ["objectivesText"] = "Examine Ravencrest's Sigil.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92842, ["x"] = 0.429333, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 94977, ["x"] = 0.408, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38719] = { ["id"] = 38719, ["name"] = "Illidari Freedom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "<The Illidari demon hunter is bleeding from several ghastly wounds. It appears he was left here to die.> Within the prison are three of my... <cough>... comrades. We were taken by surprise while scouting the area. I am not long for this world, but please, save them.", ["objectivesText"] = "Free Sirius Ebonwing , Cassiel Nightthorn , and Asha Ravensong .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95028, ["x"] = 0.39, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38720] = { ["id"] = 38720, ["name"] = "No Reason to Stay", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38692, 38694 }, ["description"] = "Elisande's purge of the Waning Crescent came so swiftly that few could react. Many of my people are dead or taken. Some may have endured this atrocity. We need to make sure they are not left behind. I need you to search the houses nearby for any survivors. See that they flee before they are discovered. Reassure them that there is no reason to stay. Not here, not while Elisande's insanity reigns.", ["objectivesText"] = "Evacuate survivors in the Waning Crescent and Siren's Vigil. Progress: Did you find anyone?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 33925, 142555, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115018, ["x"] = 0.501333, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38721] = { ["id"] = 38721, ["name"] = "Lieutenant of the Tower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "All of your instincts were correct. Gul'dan raised Lord Ravencrest, and his ghostly army, from beyond the grave. Now, they serve the Legion, protecting secrets within the tower. Although Ravencrest commands from above, Lieutenant Desdel Stareye operates the prisons. He tormented me these past few moons, but I did not yield. <Maiev runs a finger along her curved blade.> His life must be ended.", ["objectivesText"] = "Kill Desdel Stareye.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132334, 132335, 132336, 132337, 132338, 132339, 132340, 132341, 132342, 132344, 132345, 132346, 132347, 132348, 132349, 132350, 132351, 132352, 132353, 132355, 141389, 237812, 246812, 246937 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93149, ["x"] = 0.388, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38723] = { ["id"] = 38723, ["name"] = "Stop Gul'dan!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 39682, 40253 }, ["description"] = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens. Gul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse. Even in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", ["objectivesText"] = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 20, ["flags"] = 0 } } },
[38724] = { ["id"] = 38724, ["name"] = "Brotherly Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 642, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "Maiev will be somewhere in the prison. I found her discarded armor on my way here. Let's split up to search the cells more quickly. We must find her.", ["objectivesText"] = "Find Maiev Shadowsong in Black Rook Prison. Provided item:", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 139353, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 642, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38725] = { ["id"] = 38725, ["name"] = "Into the Foul Creche", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 40051, 40222 }, ["description"] = "One of the demons that I interrogated revealed a particularly juicy bit of information. Apparently, there's an imp mother in the volcano that scribes Legion secrets. Kor'vas has gone out to find that demon and bring those secrets back for us.", ["objectivesText"] = "Meet up with Kor'vas Bloodthorn at the Foul Creche.", ["rewardXP"] = 145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 0, ["flags"] = 1 } } },
[38727] = { ["id"] = 38727, ["name"] = "Stop the Bombardment", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "Jace's wards are not going to hold out much longer. We need someone to go out there and make sure those Legion devastators are destroyed. <Kayn pointedly looks at you with his spectrally-enhanced vision.>", ["objectivesText"] = "Destroy the Legion Devastators .", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128947, 128948, 129195 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38729] = { ["id"] = 38729, ["name"] = "Return to the Black Temple", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["description"] = "Quickly, <name>, use the Sargerite Keystone. We must get back to the Black Temple before it is too late!", ["objectivesText"] = "Use the Sargerite Keystone to activate the Fel Portal and return to the Black Temple.", ["rewardGold"] = 12300, ["rewardXP"] = 1145, ["rewardItems"] = { 128944, 128945, 128946, 128947, 128948, 128949, 128958, 129181, 129192, 129195, 132243, 133580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 23, ["flags"] = 0 } } },
[38743] = { ["id"] = 38743, ["name"] = "The Fate of Val'sharah", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "Malfurion, my love.... My heart breaks for him, but I cannot follow where he goes. I have sworn myself to Elune, my goddess, to defend her temples and lands with all that I am. I cannot stand by while my order is in danger. May she keep you in her graces, Malfurion. <Tyrande turns away, eyes glistening with tears.>", ["objectivesText"] = "Defend the Temple of Elune.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 141383, 237812, 246937 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104799, ["x"] = 0.578, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104921, ["x"] = 0.536, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38748] = { ["id"] = 38748, ["name"] = "Ruins of Shala'nir", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38748 }, ["objectivesText"] = "The Ruined Village Common Kill Interact", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "The Ruined Village", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Common Kill", ["amount"] = 20, ["type"] = 0, ["objectID"] = 93074, ["orderIndex"] = 1 }, { ["text"] = "Interact", ["amount"] = 17, ["type"] = 0, ["objectID"] = 93169, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[38753] = { ["id"] = 38753, ["name"] = "The Demon's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38148, 38322, 38323, 38377, 38582, 38595, 38641, 38655, 38656, 38662, 38663, 38753 }, ["description"] = "Malfurion is nearby. I can sense him. Search the summit of Andu'talah while I continue to scour the forest. Be swift, <name>. Time is of the essence!", ["objectivesText"] = "Find Malfurion Stormrage.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141390, 237812, 246937 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92710, ["x"] = 0.65, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102938, ["x"] = 0.674, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 188, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 188, ["name"] = "Into the Nightmare", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38765] = { ["id"] = 38765, ["name"] = "Enter the Illidari: Shivarra", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38766, 38813, 38819, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "Our Shivarra demonesses are waiting at the Black Temple. It's a gamble bringing them here... they used to be part of the Burning Legion after all. But, they are some of the most powerful in Lord Illidan's arsenal. <Jace looks at you for a long moment.> I have a feeling that the ultimate sacrifice is going to have to be made in order to summon them in.", ["objectivesText"] = "Feed a powerful soul into the Legion Gateway Activator and then use it to summon in your Shivarra forces.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 27940, 128951, 133316 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38766] = { ["id"] = 38766, ["name"] = "Before We're Overrun", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38813, 38819, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "The doomguard commander and his queen must be dealt with. His eredar are summoning in a huge number of reinforcements. We need to put an end to him before the Legion overruns our new foothold up in the volcano! As an added benefit, you can steal his demonic power.", ["objectivesText"] = "Slay Doom Commander Beliash and take his power for your own.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38778] = { ["id"] = 38778, ["name"] = "Turn the Keys", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "My roots wither... my branches die... The Bonespeakers, they seek to silence the Runewood. The runestones are the key... Turn the stones... release my bonds...", ["objectivesText"] = "Activate the Runestones within the Runewood. Progress: My shackles remain...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38808] = { ["id"] = 38808, ["name"] = "Bjornharta", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "The afterlife leaves the dead hungry for the delicacies of their former lives. For the vrykul kings, none such offering is prized more than Bjornharta - a celebratory feast of an engorged bear heart . The bears of the Runewood eat well, and have long been prized for their tender meat. Hunt them and find a suitable heart of offer to the ancient rulers. They will not be able to resist such an offering.", ["objectivesText"] = "Collect 4 Engorged Bear Hearts from Voracious Bears in the Runewood. Progress: How went the hunt, outsider?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124503, 129335, 129336, 129337, 129338, 129353, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38810] = { ["id"] = 38810, ["name"] = "The Dreaming Fungus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "So an outsider would seek to be judged by the ancient rulers of the vrykul? Curious, this. Know that they will not take to your presence kindly, stranger. If you are so hasty to meet judgment, you can call them forth with a ritual of wakening. To complete this ritual, you will require an aromatic to burn and an offering to present. A plant grows in the Runewood that will make a suitable incense. Gather it, and I will instruct you further.", ["objectivesText"] = "Collect 8 Soulcaps in the Runewood. Progress: What do you bring?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124504, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38811] = { ["id"] = 38811, ["name"] = "Judgment Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "You have proven resourceful thus far, stranger. As promised, I will instruct you on the ritual of wakening. First, you must place the offering directly atop the grave of the ruler you wish to awaken. Burn the incense so that its aroma wafts over the grave. If your offering is adequate, the ruler will rise, and you may ask your judgment. Take care, outsider. The dead vrykul kings will not enjoy being awakened from their slumber.", ["objectivesText"] = "Receive judgment from the ancient vrykul rulers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93446, ["x"] = 0.681, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38813] = { ["id"] = 38813, ["name"] = "Orders for Your Captains", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38819, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "All that is left is to deliver your orders to our Illidari captains. The mightiest of the Legion's forces have arrayed themselves within the volcano. But, they will not remain on the defensive for long. We must strike first and we must strike hard. Once we destroy them, we can fly up to the command ship, defeat Brood Queen Tyranna, and take the keystone for our own. Lord Illidan will be pleased.", ["objectivesText"] = "Brief your Illidari captains on where to attack the Burning Legion within the volcano. Progress: Are we ready to commence the assault?", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38815] = { ["id"] = 38815, ["name"] = "Waking the Shieldmaiden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "With the rituals disrupted and her bones returned, we may be able to wrest Ashildir from the grasp of these Bonespeakers. Deeper within Haustvald, the mystics possess a special altar that can reunite the body and spirit of a fallen warrior. With this, we may be able to return Ashildir 's spirit into her bones, and out of the grasp of these foul mystics. Go outsider, I will rally her guard.", ["objectivesText"] = "Use the Rune of Reformation to return Ashildir 's spirit to her bones.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93234, ["x"] = 0.714, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 12, ["flags"] = 0 } } },
[38816] = { ["id"] = 38816, ["name"] = "Breaking the Bonespeakers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "The crimes of these ritualists must not go unpunished, but we cannot be their executioners. The rune magic they practice grants them untold power over the dead. You, however, are not dead, and I can sense great power from you. Take the fight to these heretics, and show Ashildir that you are truly worthy of her judgment!", ["objectivesText"] = "Defeat 15 Bonespeaker vrykul or their allies in Haustvald.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93446, ["x"] = 0.681, ["y"] = 0.485 }, { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.681, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38817] = { ["id"] = 38817, ["name"] = "Regal Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "So you seek the judgment of the queen of the Valkyra? This must be your fault! The Bonespeakers of Haustvald have committed an atrocity and stolen Ashildir's bones . They must have done this to keep an outsider from completing the trials. You must not let this stand! Enter Haustvald and retrieve her remains. I hope, for your sake, that Ashildir is in a forgiving mood.", ["objectivesText"] = "Collect 8 Ashildir's Bones in Haustvald. Progress: Were you able to recover her remains?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124512, 129229, 129230, 129231, 129232, 132756, 132757, 132758, 132759, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93446, ["x"] = 0.681, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.681, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38819] = { ["id"] = 38819, ["name"] = "Their Numbers Are Legion", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "Yes, those devastators must be silenced, but there's also a great deal more to be done. Despite the odds, we're counting on you. The Brood Queen's primary leaders are in control of the volcano. They must be killed. We must smash the Legion and do anything else necessary to achieve absolute victory.", ["objectivesText"] = "Wage war upon the Brood Queen's Court and the Burning Legion within the greater Inferno Peak area.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128950, 133311 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38823] = { ["id"] = 38823, ["name"] = "The Runes that Bind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "The stone tablet here describes a ritual where a powerful spirit can be broken into weaker pieces by binding them to special runestones. It looks like the Bonespeakers may be using this very ritual to weaken the spirit of Ashildir. It may be impossible to summon her with her spirit so weakened. The rituals must be stopped.", ["objectivesText"] = "Destroy the Ritual Stones to stop the rituals binding Ashildir's spirit in Haustvald.", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38833] = { ["id"] = 38833, ["name"] = "The Art of Demonsteel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38531, 38532, 38533, 38559 }, ["description"] = "The Firmament Stone is one of the few anvils beneath the sky that can tolerate the hammer strikes necessary to craft demonsteel. Here, I will show you. Two parts leystone, one part felslate. No heat, no tempering, just pure strength and finesse. Try it. I will coach you.", ["objectivesText"] = "Work with Muirn Ironhorn to craft a Demonsteel Bar.", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124461, 124462, 136696, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92243, ["x"] = 0.545, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92243, ["x"] = 0.545, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 31, ["flags"] = 0 } } },
[38834] = { ["id"] = 38834, ["name"] = "Into the Fray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely. Come, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", ["objectivesText"] = "Speak with the lead demon hunter at Illidari Stand.", ["rewardGold"] = 309800, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93337, ["x"] = 0.45, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38842] = { ["id"] = 38842, ["name"] = "Faerie Fracas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38842 }, ["objectivesText"] = "Faerie Fracas Kill Sprites Release Trapped Faerie Dragons Kill Boss Sprites Destroy Mushrooms", ["rewardGold"] = 683200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Faerie Fracas", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Sprites", ["amount"] = 34, ["type"] = 0, ["objectID"] = 93389, ["orderIndex"] = 1 }, { ["text"] = "Release Trapped Faerie Dragons", ["amount"] = 25, ["type"] = 0, ["objectID"] = 99008, ["orderIndex"] = 2 }, { ["text"] = "Kill Boss Sprites", ["amount"] = 20, ["type"] = 0, ["objectID"] = 93444, ["orderIndex"] = 3 }, { ["text"] = "Destroy Mushrooms", ["amount"] = 100, ["type"] = 0, ["objectID"] = 94572, ["orderIndex"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[38857] = { ["id"] = 38857, ["name"] = "A Favor for Mr. Shackle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38857 }, ["series"] = { 37654, 37659 }, ["description"] = "Throm'ka, <class>. My name is Seska. I represent a... trading company. As you can see, I've fallen victim to these giants and their naga allies. Three of my associates were also captured while surveying this cove. I'm certain that my employer, Mr. Shackle , would be most grateful if you could procure their release.", ["objectivesText"] = "Free Cleave Thunderhill , Gentle Rosh , and Grace the Green . Progress: You say your name is <name>? Welcome to our humble den. Seska is very grateful for her freedom. You haven't perchance seen the rest of my people?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133029, 133030, 133031, 133032, 133033, 133034, 133035, 133036, 133037, 133039, 141403, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 88863, ["x"] = 0.502, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91419, ["x"] = 0.565, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5757, ["name"] = "A Favor for Mr. Shackle", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38862] = { ["id"] = 38862, ["name"] = "Thieving Thistleleaf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38862, 40220, 40221 }, ["description"] = "Why the Thistleleaf are collecting the Lunarwing eggs is anyone's guess, but you can be sure it's not to give them a loving home. Saylanna Riverbreeze will know what to do with these.", ["objectivesText"] = "Collect 5 Stolen Lunarwing Eggs in the Lunarwing Shallows. Progress: Gather as many eggs as you can and bring them back to me. I will keep them safe.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 123980, 129966, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5912, ["name"] = "Lunarwing Shallows", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 129966 } },
[38872] = { ["id"] = 38872, ["name"] = "The Dark Lady's Bidding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38872 }, ["series"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["description"] = "Uh, are these guys friendlies? I guess it's a good sign they haven't tried to eat Duchess... yet. Anyway, I have orders. Nathanos caught up with the dark rangers, who were sent forward aboard the Oblivion on a secret mission from Lady Sylvanas herself! Unfortunately the Alliance caught wind of our plan, and now Greymane is attacking the outpost! We could really use you over there, <name>. Duchess can take you there, just give me the word.", ["objectivesText"] = "Meet with Nathanos Blightcaller in Dreadwake's Landing.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93624, ["x"] = 0.6, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[38873] = { ["id"] = 38873, ["name"] = "Clear the Deck!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38878, 38882, 39153, 39154, 39155, 39385 }, ["description"] = "Our mission in Skold-Ashil will have to wait, <class> - for now, we have more pressing matters to attend to. I had just recently arrived with reinforcements for our assault when Greymane's ship sailed in and began barraging our walls. We deployed our siege weapons, but their ground forces quickly overwhelmed us. If you can get to those catapults and take out the dogs manning the cannons, it may give us the window we need to push the attack!", ["objectivesText"] = "Fire 4 Forsaken Catapults in Greymane's Offensive.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38878] = { ["id"] = 38878, ["name"] = "Shielded Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38882, 39153, 39154, 39155, 39385 }, ["description"] = "Our goal lies within that vault, <class>. I don't have time to explain in detail - just know that it is vital to the Forsaken that we succeed. The shieldmaidens have proven tenacious in their defense, but I believe there may be another way in. A chosen few of their order are allowed entrance, and I need you to find out how. In the town I have seen intricately engraved shields which I believe are passed down from these champions. The scenes they depict may be the key to passing into the vault.", ["objectivesText"] = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94227, ["x"] = 0.568, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95611, ["x"] = 0.608, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38882] = { ["id"] = 38882, ["name"] = "A New Life for Undeath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 39153, 39154, 39155, 39385 }, ["description"] = "It seems that you are full of surprises, <name>. With the blessing of the Valkyra queen, you have opened a path that will shape the destiny of Azeroth. I invite you to bear witness, for today a new day dawns on the Forsaken!", ["objectivesText"] = "Follow Sylvanas into the Vault of Eyir .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121568, 121570, 121572, 129342, 129343, 129344, 129345, 139693, 141392, 237812, 245411, 246937 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94228, ["x"] = 0.630667, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95755, ["x"] = 0.55, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38904] = { ["id"] = 38904, ["name"] = "Return to the Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611 }, ["series"] = { 39654, 41052, 42814, 42815 }, ["description"] = "Fear not, <name>. I'm angry, but I don't chase my own death. We will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry! Take my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.", ["objectivesText"] = "Take Saurfang's spare mount to the Broken Shore and fight alongside him to restore your honor.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38907] = { ["id"] = 38907, ["name"] = "Keepers of the Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38911, 39316, 39491, 39496, 39733 }, ["description"] = "The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion. However, we have been betrayed from within and must now ask for your aid. A great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar. We need your help in recovering it.", ["objectivesText"] = "Meet Mayla Highmountain at Thunder Totem in Highmountain . Progress: We must be swift. I was overlong in finding you.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 140192, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97666, ["x"] = 0.513333, ["y"] = 0.656 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.513333, ["y"] = 0.656 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38909] = { ["id"] = 38909, ["name"] = "Get to High Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region. Please, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area. We will rally the survivors here and follow as quickly as we can.", ["objectivesText"] = "Bring Jale Rivermane to Thunder Totem. Progress: Have you had any luck with the Rivermane?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812, 246937 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38910] = { ["id"] = 38910, ["name"] = "Rocs vs Eagles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38913, 39318, 39321 }, ["description"] = "High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley. There is no way to break this curse once it has taken hold. We will take to the skies and do battle with the rocs, but we need your help on the ground. Head north through Darkfeather Valley and release any eagles that you find. Every eagle you save is one less roc we must kill later.", ["objectivesText"] = "Save 7 Captive Great Eagles .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38911] = { ["id"] = 38911, ["name"] = "The Rivermane Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 39316, 39491, 39496, 39733 }, ["description"] = "What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar. Even now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. We need a hero. Please, go to Earthmother's Bounty and lend what aid you can.", ["objectivesText"] = "Meet Jale Rivermane at Earthmother's Bounty.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38912] = { ["id"] = 38912, ["name"] = "The Bloodtotem Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe-- Oakin Ironbull --whom you rescued at Riverbend. Use that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, <name>.", ["objectivesText"] = "Meet Oakin Ironbull at Cliff's Edge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 109076, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38913] = { ["id"] = 38913, ["name"] = "The Skyhorn Tribe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 39318, 39321 }, ["description"] = "The Skyhorn people are some of the greatest pathfinders and hunters this world has ever known. They are a proud people, but should be willing to listen to reason. If the roads feel unsafe, you may ask any flight master in Highmountain to fly you there. Please, $p, go to their leader Lasan and remind him that only together, we are Highmountain .", ["objectivesText"] = "Meet Lasan Skyhorn at Skyhorn.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38915] = { ["id"] = 38915, ["name"] = "Battle of Snowblind Mesa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground. What is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle. Meet us at Snowblind Mesa and let us take the fight to Dargrul together.", ["objectivesText"] = "Journey to Snowblind Mesa.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38916] = { ["id"] = 38916, ["name"] = "Secrets of Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth. I have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain. She needs only our help to realize it herself. Will you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.", ["objectivesText"] = "Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94571, ["x"] = 0.448, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38922] = { ["id"] = 38922, ["name"] = "Littlefur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38142, 38143, 38144, 38145, 38146, 38147, 38246, 38455, 38922 }, ["series"] = { 38246 }, ["description"] = "Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath. My nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee. He is trapped in the village, and I fear the worst. Great <class>, please save him. I am too old and too weak to do it myself.", ["objectivesText"] = "Speak to Littlefur at Smolderhide Thicket.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93890, ["x"] = 0.484, ["y"] = 0.845 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93581, ["x"] = 0.469333, ["y"] = 0.845333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.845 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 186, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 186, ["name"] = "Archdruid of the Claw", ["orderIndex"] = 2, ["flags"] = 1 } } },
[38933] = { ["id"] = 38933, ["name"] = "Logistical Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 39756, 42811, 42812 }, ["description"] = "I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles. Lord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.", ["objectivesText"] = "Speak to Lord Grayson Shadowbreaker .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38944] = { ["id"] = 38944, ["name"] = "Sew It Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below. Threads imbued with magic? Something demonically-tinged? Ugh, I hope it's not FURS again. You're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!", ["objectivesText"] = "Obtain 10 Shal'dorei Silk . You can find Shal'dorei Silk on humanoids within the Broken Isles, obtain some from a fellow adventurer, or you may visit the Auction House and buy some. Progress: I wouldn't mind working with some cashmere...", ["rewardXP"] = 1415, ["rewardItems"] = { 124437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 0, ["flags"] = 0 } } },
[38945] = { ["id"] = 38945, ["name"] = "This Should Be Simple... Right?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38946 }, ["description"] = "I have plenty of silk patterns that we can put this cloth to work on. Help me to prepare the materials, <name>. We're going to put this cloth to good use and make you a new robe.", ["objectivesText"] = "Craft a Handcrafted Silkweave Robe on Tanithria 's Finishing Bench. You can find the pattern in your tailoring pattern list. You can find the materials for the pattern in her shop. Progress: We're back in business again. How exciting!", ["rewardXP"] = 1415, ["rewardItems"] = { 126992, 126993, 127286, 127287, 127289, 127291, 127293, 127294 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38946] = { ["id"] = 38946, ["name"] = "Consult the Locals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38945 }, ["description"] = "Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material. Head on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.", ["objectivesText"] = "Find a tailor in Azsuna.", ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38947] = { ["id"] = 38947, ["name"] = "Runic Catgut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38948, 38949, 38950 }, ["description"] = "Let me guess... thread troubles? Mm-hm. I suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept. Shal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land. I'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.", ["objectivesText"] = "Obtain 3 pieces of Runic Catgut . Progress: They are quite remarkable creatures, really. I used to keep one as a pet and mount... but that was a lifetime ago.", ["rewardXP"] = 1415, ["rewardItems"] = { 127037, 127039 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38948] = { ["id"] = 38948, ["name"] = "Hard Times", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38949, 38950 }, ["description"] = "When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me. Unfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns. The naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.", ["objectivesText"] = "Obtain a Stained Silken Robe and a set of Hatecoil Wristwraps . Progress: What've you got in your hands, there?", ["rewardXP"] = 1415, ["rewardItems"] = { 127038, 127039 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38949] = { ["id"] = 38949, ["name"] = "So You Think You Can Sew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38948, 38950 }, ["description"] = "Very good, I think we're ready to begin. < Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.> Let's prepare our materials and make the robe and bracers that you so rightfully deserve!", ["objectivesText"] = "Craft a Rune-Threaded Silkweave Robe and a set of Rune-Threaded Silkweave Bracers at Lyndras ' Finishing Table. You can find the patterns in your tailoring pattern list. Progress: You're pretty lucky to have found me.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126987, 126994, 127343, 127344, 127345 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38950] = { ["id"] = 38950, ["name"] = "The Wayward Tailor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38947, 38948, 38949 }, ["description"] = "Might I ask a favor, <name>? As I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop. I have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me. < Lyndras looks at you with hopeful apprehension.>", ["objectivesText"] = "Speak to Lalla Brightweave in Dalaran, and ask her to summon Lyndras . Progress: Did you find a tailor yet?", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 6, ["flags"] = 0 } } },
[38954] = { ["id"] = 38954, ["name"] = "Where's Lyndras?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38955 }, ["description"] = "That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face. Perhaps we should track him down.", ["objectivesText"] = "Find Lyndras .", ["rewardGold"] = 20220, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38956] = { ["id"] = 38956, ["name"] = "Where's Lyndras Again?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Oh dear. He had just promised you that he wouldn't wander off, and then he did it again! I'm starting to think that this Lyndras character might be a bit too impetuous for my tastes. Please, go find him, before he gets into any more trouble.", ["objectivesText"] = "Find Lyndras in Dalaran.", ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 12, ["flags"] = 0 } } },
[38957] = { ["id"] = 38957, ["name"] = "Taking Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own. I've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive. If I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.", ["objectivesText"] = "Obtain 6 Runed Breeches . Progress: I'm looking forward to this.", ["rewardXP"] = 1415, ["rewardItems"] = { 126991, 127044 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 13, ["flags"] = 0 } } },
[38958] = { ["id"] = 38958, ["name"] = "The Right Color", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "Your assistance, <name>, if you have a moment. I've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right. The color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?", ["objectivesText"] = "Obtain 10 Helsquid Ink . Progress: I'm quite close to completing these slippers.", ["rewardXP"] = 1415, ["rewardItems"] = { 116271, 126988, 127046 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 14, ["flags"] = 0 } } },
[38962] = { ["id"] = 38962, ["name"] = "The Path to Suramar City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth. Unfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight. You must find a way to move safely within the confines of their city if we're to continue our research.", ["objectivesText"] = "Assist the nightfallen of Suramar until you discover a way to move safely amongst the elves of Suramar City.", ["rewardXP"] = 6140, ["rewardItems"] = { 2996, 2997, 4339, 41510, 53643, 114821, 127004, 127022, 127027, 136269, 140326, 140327, 140328, 140329, 147768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 25, ["flags"] = 0 } } },
[38964] = { ["id"] = 38964, ["name"] = "Where's Lyndras Now?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. I heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras. Could you please go over there and make sure?", ["objectivesText"] = "Go the alchemy shop across the street.", ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 19, ["flags"] = 0 } } },
[38967] = { ["id"] = 38967, ["name"] = "The Nightborne Connection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors. Good luck, <name>, and try not to get caught.", ["objectivesText"] = "Speak with Leyweaver Tytallo in Suramar.", ["rewardXP"] = 6140, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 26, ["flags"] = 0 } } },
[38968] = { ["id"] = 38968, ["name"] = "Proof of Loyalty", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38970, 39602, 39605, 39667 }, ["description"] = "<Tytallo listens as you recount what happened with Lyndras.> I see. You sound almost... sympathetic to the wretch. The nightfallen are liars and thieves. ALL of them. Lyndras included. I will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity? If you want to get on my good side, do not return until you are covered in the blood of the withered .", ["objectivesText"] = "Slay 25 withered within Suramar. Progress: If you wish to earn my tutelage, you must first prove that you are on our side.", ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 27, ["flags"] = 0 } } },
[38970] = { ["id"] = 38970, ["name"] = "The Queen's Grace Loom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 39602, 39605, 39667 }, ["description"] = "Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made. You are prepared, <name>, to learn about working with Imbued Silkweave. Use the teleportation crystal behind me, and speak with Azayna, the leader of our order.", ["objectivesText"] = "Use the Teleportation Crystal in the Leyweavers' Hall, then speak with Leyweaver Azayna. Progress: Return once you've spoken with Azayna.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127022, 127023, 127025, 127027, 127277, 127278, 127279, 127280 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 29, ["flags"] = 0 } } },
[38975] = { ["id"] = 38975, ["name"] = "Inspire Me!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe. I'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.", ["objectivesText"] = "Craft a Brown Linen Robe, a White Woolen Dress, a Simple Black Dress, a Frostwoven Robe, and a Spiritmend Robe while standing near Leyweaver Mithrogane . If you do not know a pattern, you can learn it from tailoring trainers in major cities. Progress: I never turn down the opportunity to learn a new robe pattern.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 2320, 2321, 2324, 2325, 2589, 2592, 2996, 2997, 4338, 4339, 6238, 6787, 8343, 10053, 33470, 38426, 41510, 41515, 53010, 53643, 54486 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93976, ["x"] = 0.402, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93976, ["x"] = 0.402, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 32, ["flags"] = 0 } } },
[38990] = { ["id"] = 38990, ["name"] = "The Call of Icecrown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 38990 }, ["description"] = "<A powerful presence again touches your thoughts.> I have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, <name>, will be the hand of our vengeance! Use the Death Gate to return to Acherus and I shall reveal your role in this.", ["objectivesText"] = "Use your Death Gate ability to travel to Icecrown and obtain the Blades of the Fallen Prince . Progress: It is time to begin, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 118006, 124124, 127009, 127991, 128292, 128293, 128318, 128402, 128403, 128848, 132510, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 168, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 168, ["name"] = "The Blades of the Fallen Prince", ["orderIndex"] = 0, ["flags"] = 0 } } },
