[39025] = { ["id"] = 39025, ["name"] = "Grasp of the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer. He keeps thinking of the hammer as a weapon instead of a tool of creation. Even so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic. You might have power enough to break these fists. Can you help?", ["objectivesText"] = "Rescue Jale Rivermane , Warbrave Oro , and Oakin Ironbull . Progress: How are the captives? Did you find them alive?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39026] = { ["id"] = 39026, ["name"] = "The Drogbar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left. Please champion, prove to my people that you are the hero I foresaw. Slay enough of these Stoneraiders that it breaks their resolve.", ["objectivesText"] = "Slay 8 Drogbar in Riverbend. Progress: The drogbar were supposed to be our allies against the Burning Legion.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 87399, 130904, 131736, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.687 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39027] = { ["id"] = 39027, ["name"] = "Dargrul and the Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "We are about to follow a drogbar into a cave, something we warn our children never to do. Even so, several of our warbraves have already followed Dargrul inside. Come, join us in battle and let us reclaim the Hammer of Khaz'goroth.", ["objectivesText"] = "Confront Dargrul the Underking. Progress: This is a hard day.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121722, 130287, 130288, 130289, 130290, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4155, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39029] = { ["id"] = 39029, ["name"] = "Defend The Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39029 }, ["objectivesText"] = "Defend The Temple", ["rewardGold"] = 650600, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend The Temple", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39043] = { ["id"] = 39043, ["name"] = "Bitestone Enclave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "This is an old drogbar enclave that we used to trade with. Now it is a base of operations for their raids. I need more time to gather what is left of our warbraves. Go, enter the enclave, and slay any you find in there. Buy us the time we need to gather our strength.", ["objectivesText"] = "Slay drogbar in the Bitestone Enclave. Progress: Highmountain stands!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 138783, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97553, ["x"] = 0.4155, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4155, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39047] = { ["id"] = 39047, ["name"] = "Call of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, Altruis requests that you meet him at Krasus' Landing at once. <Kor'vas leans in close, her voice an urgent whisper.> You must hurry. The Legion has eyes everywhere.", ["objectivesText"] = "Speak to Altruis the Sufferer at Krasus' Landing.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39049] = { ["id"] = 39049, ["name"] = "Eye On the Prize", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39050, 40379 }, ["description"] = "This demon has proved less than useful. I have been using the Scythe of Souls on it, but so far, it has resisted my inquiries. We will see how long that lasts. I have a different idea... There is a fresh inquisitor demon ahead. They are horrific fel casters who see through their floating eyes and specialize in dark pacts. If you steal its power, Jace Darkweaver could use some of it in his ritual to spy on the Legion. Better yet, you will gain its power by ripping it from its smoking corpse.", ["objectivesText"] = "Kill Inquisitor Baleful and take his power. Progress: <name>. I would salute, but I am in the middle of a ritual.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 71083, 128944, 128945, 128946, 128947, 128948, 128949, 128958, 129192, 129195, 132243, 133580, 190456, 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39050] = { ["id"] = 39050, ["name"] = "Meeting With the Queen", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39049, 40379 }, ["description"] = "We can use some of that essence to complete my ritual. You'll be able to spy upon the Legion leaders and see what they're planning. Use the nether crucible and complete the ritual.", ["objectivesText"] = "Complete the ritual to spy upon the Legion leaders. Progress: If we don't know what they're planning, we're at a disadvantage fighting them.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39051] = { ["id"] = 39051, ["name"] = "By Any Means", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7777, ["mapID"] = 723, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "We need to figure out what rock Varedis is hiding under - the only way we're going to do that is by getting inside this prison. Do what you must.", ["objectivesText"] = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis. Progress: A truly impressive display.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 53265, 53267, 53292, 62178, 62179, 62180, 127830, 128832, 131398, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7777 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1494, ["db2PoiUiMapID"] = 723, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39059] = { ["id"] = 39059, ["name"] = "To Catch a Banshee", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "The strange-talking vrykul said I might be able to meet you here. I have orders from Greymane. It seems he may have a lead on Sylvanas' location. He's set up a camp near the base of the mountain. We've run into some troubles, though. It looks like the Horde may have homed in on our position. We could use your help. You can take my gryphon. Just speak to me when you're ready to leave.", ["objectivesText"] = "Meet with Genn Greymane in Greywatch.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94346, ["x"] = 0.6, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 0, ["flags"] = 1 } } },
[39060] = { ["id"] = 39060, ["name"] = "Combustible Contagion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39061, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "It is true that we may have a lead on Sylvanas. Though I want nothing more than to get my hands on the Banshee Queen, the situation here at Greywatch requires immediate attention. Yesterday, a regiment of guards returned with word of Forsaken forces in the woods. Several of them bore signs of a blight, similar to the one we endured in Gilneas. It would appear these Forsaken seek to unleash this blight upon Greywatch. Seek out their caches and destroy them, before the blight overtakes us!", ["objectivesText"] = "Burn the Forsaken Blight Caches near Greywatch. Progress: Have the caches been taken care of?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127295, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39061] = { ["id"] = 39061, ["name"] = "Whispers from the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39062, 39063, 39092, 39122, 39472 }, ["description"] = "We still have little knowledge of the Horde's activities in the region, but I'm hoping you can help change that. Lately the woods have been crawling with Sylvanas' agents. The few we have taken out carried orders from her Dark Rangers, who are no doubt in command of her forces here. While you're on the hunt, keep an eye out for any scouting orders. They may help us pinpoint Sylvanas' objective in the area.", ["objectivesText"] = "Collect the Forsaken Scouting Orders from Dread-Rider Stalkers and Dread-Rider Plaguebringers near Greywatch. Progress: What have you found?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 127285, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39062] = { ["id"] = 39062, ["name"] = "To Skold-Ashil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39063, 39092, 39122, 39472 }, ["description"] = "We have her now! According to these reports, Sylvanas' forces are after something in Skold-Ashil - a vrykul town not far from here. We must make our way there and track her down. I had previously dispatched Commander Lorna Crowley and a detachment of Gilneas Brigade to scout the position. Meet up with her there and find out what Sylvanas is after. Meanwhile, I will muster the fleet to assault their outpost. We will have justice if I have to reduce their camp to rubble!", ["objectivesText"] = "Meet with Commander Lorna Crowley in Crowley's Overlook.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 14370, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93779, ["x"] = 0.635, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39063] = { ["id"] = 39063, ["name"] = "Shielded Secrets", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39092, 39122, 39472 }, ["description"] = "It's obvious at this point that the Horde wants something in Skold-Ashil. Unfortunately we still don't know what they're after. We think the secret lies with the shieldmaidens here, so we need to find out more about them. Some early scouting revealed that they have a method of carving their shields to tell their stories. Go into the city and find as many of these shields as you can. With luck, we will find what Sylvanas seeks.", ["objectivesText"] = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93779, ["x"] = 0.635, ["y"] = 0.618 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95921, ["x"] = 0.605, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39092] = { ["id"] = 39092, ["name"] = "Becoming the Ascendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39063, 39122, 39472 }, ["description"] = "Our course is now clear. We must enter the vault and prevent Sylvanas from obtaining the power to create more Val'kyr. The entrance is barred, which is likely what has kept her out so far, but you may have already uncovered the key to this barrier. You must become the next ascendant. Complete the rites as depicted on the shields and take down the barrier to the vault. I will send word to Greymane of our findings - he will wish to confront Sylvanas himself.", ["objectivesText"] = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95921, ["x"] = 0.605, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95804, ["x"] = 0.622, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39117] = { ["id"] = 39117, ["name"] = "Shriek No More", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Papa loved this village. He'd never hear of leaving, even in these dread times. Before he died, he told me what attacked him: a monstrous falcon we call Rotbeak. You're fighting these undead, aren't you? Will you avenge my father? If so, you can find the beast northwest of here, patrolling our western route to the sea.", ["objectivesText"] = "Find Rotbeak along the Bradensbrook, and collect the beast's head. Progress: Papa always said the only way he'd leave here would be feet-first. I wish he'd been wrong.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 127411, 129168, 130009, 133812, 237812, 245615 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94117, ["x"] = 0.37, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 94117, ["x"] = 0.37, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39122] = { ["id"] = 39122, ["name"] = "Ending the New Beginning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39472 }, ["description"] = "The Banshee Queen is here! I'd recognize those tainted arrows anywhere. This is the moment we have been fighting for. Sylvanas will answer for her crimes against Varian Wrynn and the Alliance! To arms!", ["objectivesText"] = "Confront Sylvanas in the Vault of Eyir.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95804, ["x"] = 0.622, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 95932, ["x"] = 0.714, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39123] = { ["id"] = 39123, ["name"] = "Lion Stalkin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "The hills are crawlin' with lions that stalk their prey from afar. These big cats will pounce at anything that catches their eye, including |5<race>. While most would fall to such a formidable predator, anyone in my huntin' party would be able to best those beasts. Prove you've got what it takes by taking down a few of those stalkers.", ["objectivesText"] = "Hunt Pinerock Stalkers and Prowlers in Pinerock Basin.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39124] = { ["id"] = 39124, ["name"] = "Moose Shootin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "Highmountain is home to wildlife that can't be hunted anywhere else in the world. Tell me, <name>, have you ever laid eyes on a moose before? The roaming Elderhorn may look like gentle giants, but only a fool would underestimate their strength. They should prove to be a good challenge, even for someone as experienced as you.", ["objectivesText"] = "Hunt Pinerock Elderhorn in Pinerock Basin. Progress: Ya can't be huntin' Elderhorn if you're lingerin' around camp.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39149] = { ["id"] = 39149, ["name"] = "A Village in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38643, 38644, 38645, 38646, 38647, 38691, 39117, 39149 }, ["description"] = "Another outsider? Some bloke named Jarod just went off to our village down the road claiming he might be able to help us with our problem. If you're here to help as well, then you best speak to the Mayor. Just know this is a bad time, and he's got an itchy trigger finger.", ["objectivesText"] = "Speak to Mayor Heathrow at Bradensbrook.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94594, ["x"] = 0.512, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92619, ["x"] = 0.424, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 191, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 191, ["name"] = "Bradensbrook", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39153] = { ["id"] = 39153, ["name"] = "Dreadwake's Dilemma", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39154, 39155, 39385 }, ["description"] = "The situation has taken a dire turn, <name>. We were unprepared for Greymane's sudden assault, with only a token force left behind at Dreadwake's Landing, and we are paying the toll. The beach is now swarming with worgen infiltrators, and if the cannons breach our defenses, they will likely swarm in on us. We're spread too thin here to take the fight to them, but you could change that. Wipe them out.", ["objectivesText"] = "Kill 10 Greywatch Saboteurs or Infiltrators in Greymane's Offensive.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39154] = { ["id"] = 39154, ["name"] = "To Skold-Ashil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39155, 39385 }, ["description"] = "Thanks to your initiative, <class>, the situation at Dreadwake's Landing is under control. We have no time to rest on our laurels, however - Sylvanas's mission must still be carried out. The dark rangers are heading up operations in Skold-Ashil from the tower overlooking the river junction. Seek them out there, and see if you can aid in completing this task.", ["objectivesText"] = "Meet with the dark rangers in Ranger's Foothold, outside of Skold-Ashil.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 14370, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94227, ["x"] = 0.568, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39155] = { ["id"] = 39155, ["name"] = "Becoming the Ascendant", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39154, 39385 }, ["description"] = "It would seem that the engravings depict a rite of ascension, which allows the shieldmaidens to enter the vault. I believe we can use this to our advantage. You must become the next ascendant. Go to the temple and perform the rites. Should you need to wade through the corpses of the shieldmaidens to do so, then so be it. Find me when you have completed this task, and we will take the vault for the Horde!", ["objectivesText"] = "Seek the blessings at the four shrines in the temple at Skold-Ashil, then commune with the statue.", ["rewardGold"] = 262100, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 95611, ["x"] = 0.608, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94228, ["x"] = 0.630667, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39178] = { ["id"] = 39178, ["name"] = "Moose on the Loose", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "There's been chatter around the hunters' lodge about a crazed moose that is terrorizing the basin. I've never laid eyes on the beast myself, but they say its antlers are illuminated with magic. Where other lesser hunters have tried and failed, you will prevail, and collect me a one-of-a-kind trophy!", ["objectivesText"] = "Collect the antlers of the cursed ancient spirit, Morashu. Progress: I'm looking forward to hanging the antlers of an ancient spirit within the walls of the hunters' lodge!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 127767, 141647, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94101, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94101, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39179] = { ["id"] = 39179, ["name"] = "Bloodstone Bandit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39389, 40218, 41759, 41767 }, ["description"] = "Something of personal value has been taken from me, and my work here cannot continue until I get it back. To most it would appear to be an ordinary stone, but it is so much more than a simple rock - it lives and breathes! The nearby naga have been snatching anything with any sort of magical significance, my stone included. Fortunately, they do not know how to access its power. Return my stone to me, and I will consider your request for help.", ["objectivesText"] = "Recover Kira's Bloodstone from Narashi Spitescale. Progress: Have you recovered my Bloodstone yet?", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 127710, 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39191] = { ["id"] = 39191, ["name"] = "Legacy of the Icebreaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 39191 }, ["description"] = "The greatest warrior should wield the greatest weapons. Long ago a great king, Magnar Icebreaker, wielded weapons crafted from a scale of the mightiest dragon in the land. He should be here, but he is not. Instead he languishes in his tomb. His son, Hruthnir, is here. He will lead you to the tomb. If Magnar can be saved, do so. Either way, return with his weapons.", ["objectivesText"] = "Deal with Magnar Icebreaker. Progress: You have done well. You will bring many victories to these Halls.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 217, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 217, ["name"] = "Legacy of the Icebreaker", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39214] = { ["id"] = 39214, ["name"] = "The Eye of Odyn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "It is time to begin the war in Azeroth. We have prepared a tool for you to direct your warriors and your own operations from here. It is called the Eye of Odyn. If you will follow me, I will take you to it, and someone that will help you use it.", ["objectivesText"] = "Go to the Eye of Odyn.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39247] = { ["id"] = 39247, ["name"] = "The Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "This hunt is yours to lead, <name> - a select few Illidari will join you to make sure Varedis meets his end. The rest of us must stay behind; a small team will have the best chance of making it to his hold undetected. We will meet you at Krasus' Landing to see you off when you are ready.", ["objectivesText"] = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39261] = { ["id"] = 39261, ["name"] = "Call of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, Kayn requests that you meet him at Krasus' Landing at once. <Kor'vas leans in close, her voice an urgent whisper.> You must hurry. The Legion has eyes everywhere.", ["objectivesText"] = "Speak to Kayn Sunfury at Krasus' Landing.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 140192, 227669, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39262] = { ["id"] = 39262, ["name"] = "Give Me Sight Beyond Sight", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39495, 39515, 39516, 39663 }, ["description"] = "Jace Darkweaver swears that for a split second he sensed a demonic presence up and behind us. He took some of our forces up to the cave just to the southeast to investigate. They found nothing in the cave, but he is certain that something is amiss. Would you lend him your guidance, and more importantly, your spectral sight?", ["objectivesText"] = "Speak with Jace Darkweaver and then use your Spectral Sight ability to scan the cave for hidden demons. Progress: <name>, we need you to scan the cave with your spectral sight. We must know if there are Legion forces magically hidden within.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 6802, 128944, 128945, 128946, 128947, 128948, 128949, 128958, 129192, 129195, 132243, 133580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39272] = { ["id"] = 39272, ["name"] = "Poisoned Crops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["description"] = "After driving us from the farmland and infesting our crops with insects, the drogbar placed wicked totems that further poison our harvest. I can only hope that if you destroy them, we'll be able to heal the land using Jale's water magic. Thank you for coming to help us, <name>. We are but simple farmers and fishermen, and have little prowess in combat.", ["objectivesText"] = "Destroy the drogbar Poison Idols . Progress: The crops must be rid of this poison!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95191, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39277] = { ["id"] = 39277, ["name"] = "Spray and Prey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39487, 39488, 39489, 39498, 39661, 42104 }, ["description"] = "The Bug Sprayer you recovered from Ormgul the Pestilent seems like it could give us an advantage against the drogbar and their insects. Spray the Drogbar with their own alchemy and watch their insects turn against them.", ["objectivesText"] = "Use the Bug Sprayer on drogbar in Whitewater Wash. Progress: For this group of drogbar to turn against us after so many years of peace...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 127988, 130291, 130292, 130293, 130294, 133820, 141634, 141635, 141636, 141637, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95956, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95956, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39279] = { ["id"] = 39279, ["name"] = "Assault on Mardum", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 39279 }, ["objectivesText"] = "Assault the Legion in the lowlands Minus-Mobs Normal Mobs Mo'arg Brute Legion Communicator #1 Legion Comm #1 - TH Controller Legion Communicator #2 Legion Comm #2 - TH Controller Legion Communicator #3 Legion Comm #3 - TH Controller Fel Spreader Destroyed First Fel Spreader Destroyed Legion Portal First Legion Portal Destroyed", ["rewardGold"] = 404400, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Assault the Legion in the lowlands", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Minus-Mobs", ["amount"] = 100, ["type"] = 0, ["objectID"] = 94651, ["orderIndex"] = 1 }, { ["text"] = "Normal Mobs", ["amount"] = 40, ["type"] = 0, ["objectID"] = 95226, ["orderIndex"] = 2 }, { ["text"] = "Mo'arg Brute", ["amount"] = 25, ["type"] = 0, ["objectID"] = 96400, ["orderIndex"] = 3 }, { ["text"] = "Legion Communicator #1", ["amount"] = 7, ["type"] = 2, ["objectID"] = 244439, ["orderIndex"] = 4 }, { ["text"] = "Legion Comm #1 - TH Controller", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102223, ["orderIndex"] = 5 }, { ["text"] = "Legion Communicator #2", ["amount"] = 7, ["type"] = 2, ["objectID"] = 244440, ["orderIndex"] = 6 }, { ["text"] = "Legion Comm #2 - TH Controller", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102224, ["orderIndex"] = 7 }, { ["text"] = "Legion Communicator #3", ["amount"] = 7, ["type"] = 2, ["objectID"] = 244441, ["orderIndex"] = 8 }, { ["text"] = "Legion Comm #3 - TH Controller", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102225, ["orderIndex"] = 9 }, { ["text"] = "Fel Spreader Destroyed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 97142,