[39316] = { ["id"] = 39316, ["name"] = "Trapped Tauren", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39491, 39496, 39733 }, ["description"] = "The drogbar just rounded up those of us that they could and led them to a cave near here. If you act quickly, I think they can still be saved. I know not what purpose they have for capturing our people. I shudder to think of it... in the deep places, the darkness rules.", ["objectivesText"] = "Free the captured Rivermane tauren. Progress: They slew many of my brothers and sisters, but at least some managed to escape. Others, however, we captured.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39318] = { ["id"] = 39318, ["name"] = "Nursing the Wounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 38913, 39321 }, ["description"] = "I know why Mayla sent you. But as you have seen, the drogbar are not the only threat to Highmountain . I will not send forces to support until we deal with the minions of High Crawliac. If you want to help, find my shaman. He was supposed to be dispersing these fires that are ravaging my village. He was last seen heading for his spirit lodge to the south just before these Cinderwitches descended on us.", ["objectivesText"] = "Find Windmaster Julan and help extinguish the fires on Skyhorn. Progress: These harpies are all over the place!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93841, ["x"] = 0.525, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39321] = { ["id"] = 39321, ["name"] = "The Three", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 38910, 38913, 39318 }, ["description"] = "When High Crawliac seized control of the harpies she placed 3 powerful and deadly witches in charge of the covens under her command. These witches must die. Feel up for the challenge? Head into the Haglands behind me and find these three evil creatures. We will cover you from the air and give your prey no sky to retreat. Look for us higher up the mountain, should you survive.", ["objectivesText"] = "Slay Ragi the Hexxer , Agara Deathsong , and Ugla the Hag . Progress: Many Skyhorn have fallen to the witchcraft of these hags.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 52913, 52959, 121664, 121665, 121666, 121667, 130303, 130304, 130305, 130306, 131832, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39322] = { ["id"] = 39322, ["name"] = "The Witchqueen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 39387 }, ["description"] = "The time has come to assault High Crawliac , the Witchqueen. You should know that one does not become queen of the harpies through kindness. This creature has killed, betrayed, and tormented countless tauren, harpies, kobolds, and anything else she had to in order to secure her position as queen. Come, friend, let us finish this.", ["objectivesText"] = "Slay High Crawliac , the Witchqueen. Progress: Without a queen, it will take the harpies many years before they can organize in such numbers again.", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 133092, 133093, 133094, 133095, 133096, 133097, 133098, 133099, 133100, 133102, 133103, 133104, 133105, 133106, 133107, 133108, 133109, 133110, 133111, 133113, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39325] = { ["id"] = 39325, ["name"] = "Get Your Mix On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39326 }, ["description"] = "Let's see... potion stains on your tabard, crushed herbs on your boots... I know a fellow alchemist when I see one! We will do good work together, the two of us. I trust you're not averse to learning new tricks. Be sure to use my state-of-the-art alchemy table. I built her myself!", ["objectivesText"] = "Deucus Valdera in Dalaran wants you to craft some new potions. Merchant Patricia Egan in the alchemy shop can help you learn how. Progress: I hope you're making good use of my alchemy table. It's my pride and joy!", ["rewardGold"] = 20220, ["rewardXP"] = 1415, ["rewardItems"] = { 3371, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127898, 127899, 127900, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127917, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39326] = { ["id"] = 39326, ["name"] = "Missing Shipments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39325 }, ["description"] = "Now that we've gotten to know each other, perhaps you can lend me a hand. My weekly supply shipment was lost when my longtime courier--you know, old whatsername--was shot out of the sky over the shores of Azsuna. Surely a hardy sort like you could retrieve my lost goods.", ["objectivesText"] = "Alchemist Deucus Valdera in Dalaran wants you to locate supplies lost near the water in Azsuna. Progress: I say, I do hope you were able to locate my lost supplies. How are we to build trust between us if you won't do everything I ask?", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128355, 128356, 128357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39327] = { ["id"] = 39327, ["name"] = "There's a Scribe for That", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39328, 39329, 39330, 39390, 39566 }, ["description"] = "Fine! I admit, even my considerable intellect can't translate the strange tome you discovered. No doubt the water smears made it illegible. Say, one of those dimwitted scribes down the block owes me a favor. This sort of busywork is just his cup of tea.", ["objectivesText"] = "Bring the Runewritten Tome to Professor Pallin in Dalaran. Progress: I don't have time to translate tomes! That's what lesser professions are for.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128290, 128291, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39328] = { ["id"] = 39328, ["name"] = "Ancient Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39329, 39330, 39390, 39566 }, ["description"] = "The tome contains a wealth of ancient vrykul recipes! Why, I could be the first alchemist in untold ages to craft one! How fortunate for you, friend <name>, that you are here to bear witness to my greatness! Awful kind of that Svena person to die and leave her book for us, eh? Silly vrykul...", ["objectivesText"] = "Observe Deucus Valdera as he attempts one of the vrykul recipes.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39330] = { ["id"] = 39330, ["name"] = "Ley Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39390, 39566 }, ["description"] = "The leyflame burner you brought me is useless! This is why I never trust an engineer... The burner needs to be charged in areas that resonate with ley energy before it can be used to craft our newfound alchemy recipes. Lucky for us, Azsuna is rich with such power.", ["objectivesText"] = "Travel to key locations in Azsuna and use the Depleted Leyflame Burner to collect ley energy.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39333] = { ["id"] = 39333, ["name"] = "An Imprecise Burette", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39342 }, ["description"] = "Here are your burettes. Should you ever be in the need of anything else, don't hesitate to ask. < Ms. Xiulan holds up the hair and continues to chuckle to herself.>", ["objectivesText"] = "Bring the Uncalibrated Malloric Burettes to Deucus in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128676 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 23, ["flags"] = 0 } }, ["startItems"] = { 127872 } },
[39334] = { ["id"] = 39334, ["name"] = "Thanks for Flasking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39430 }, ["description"] = "Here is your flask, good as new. A fair trade for those potions. Be a little more careful with your breakables next time!", ["objectivesText"] = "Take the repaired Dual-Chambered Mixing Flask to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128516 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39337] = { ["id"] = 39337, ["name"] = "Forlorn Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39338, 39431, 44112 }, ["description"] = "Next on the list of things to replace are my filters. Now I'm sure you've concluded that an alchemist of my caliber uses only the finest of tools when mixing my potions. The elves at the Temple of Elune in Val'sharah use Shaldorei silk to craft their robes. Perhaps they'd be willing to part with some for my filters.", ["objectivesText"] = "Speak with a Temple Priestess at the Temple of Elune to see if you can acquire some Shaldorei Silk. Progress: A pile of tattered shaldorei silk lay on the chest.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 14, ["flags"] = 0 } } },
[39338] = { ["id"] = 39338, ["name"] = "Return the Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39337, 39431, 44112 }, ["description"] = "What was torn has now been mended. I hope you put this Shaldorei silk to good use. Now, run along.", ["objectivesText"] = "Return the Mended Shaldorei Silk to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128518 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 16, ["flags"] = 0 } } },
[39340] = { ["id"] = 39340, ["name"] = "Lining the Crucible", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39339, 39341 }, ["description"] = "The first step in making this crucible useful is to restore the lining of its interior. That's going to require supplies you'll either gather yourself or obtain through trade with fellow adventurers. Felwort and yseralline seeds are familiar to herbalists. Felhide is obtained through skinning. Blood of Sargeras can be found all over the Broken Isles.", ["objectivesText"] = "Gather 1 Blood of Sargeras , 1 Felhide , 2 Felwort , and 100 Yseralline Seeds . Progress: Restoring the lining of the crucible is no simple task, <name>.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 18, ["flags"] = 0 } } },
[39341] = { ["id"] = 39341, ["name"] = "Vault of the Wardens: Demon's Bile", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39339, 39340 }, ["description"] = "The key to a crucible like this is that it must be bathed in the foulest of fel energy. I hate to say it, but the most efficient method of accomplishing such a feat is to subject it to the bile of a demon. Yes, I said the bile of a demon. Ready to get to work? In the Vault of the Wardens, such a demon exists. An imp mother by the name of Grimoira . The door to her room is sealed by an invisible lock. I'd suggest bringing some Skaggldrynk with you. Use it when you get to her door.", ["objectivesText"] = "Craft a Skaggldrynk , then go to the Vault of the Wardens and bathe the crucible in the bile of Grimoira .", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127877, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128679, 136723 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 19, ["flags"] = 0 } } },
[39342] = { ["id"] = 39342, ["name"] = "The Price of the Black Market", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39333 }, ["description"] = "I may have what you're looking for, burettes you say? Not a very common item. For that, I require a moderate favor. Nothing too big, just a few things really. A silver hair from a high-ranking archmage... the blood of a titan, and, oh... some wine and cheese. What?! I have appetites that need satiating.", ["objectivesText"] = "Collect a Silver Hair of Khadgar , a Blood of Sargeras , 5 Kaldorei Ginger Wine and 5 Moist Azsunian Feta . Progress: Don't take too long now. Who knows who else may be in the market for your precious burettes.", ["rewardXP"] = 6140, ["rewardItems"] = { 116268, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128764, 128833, 136723 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 22, ["flags"] = 0 } } },
[39343] = { ["id"] = 39343, ["name"] = "Vault of the Wardens: Bendy Glass Tubes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "You find tubing formed from a bendable sort of glass. It appears as though Grimoira was using it to suck out the insides of her victims. Its magical properties, however, would seem ideal for use on an advanced alchemy table.", ["objectivesText"] = "Bring the Bendy Glass Tubes to Deucus Valdera in Dalaran. Provided item:", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127877, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 20, ["flags"] = 0 } }, ["startItems"] = { 127877 } },
[39344] = { ["id"] = 39344, ["name"] = "Going Underground", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "We're so close to replacing all my equipment, <name>. In order to make flasks again, we need to be able to precisely measure each ingredient. For that, we need to replace my burette assembly. Unfortunately, burettes aren't easy to come by. We may be able to procure some though through other means by... <Deucus looks around and beckons you closer.> Going underground, so to say. As in, the Black Market. Go see Ms. Xiulan . Mum's the word.", ["objectivesText"] = "See Ms. Xiulan about acquiring some new burettes for Deucus.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 21, ["flags"] = 0 } }, ["startItems"] = { 127878 } },
[39345] = { ["id"] = 39345, ["name"] = "Calibration Experts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 42081 }, ["series"] = { 39346, 39645 }, ["description"] = "It will take the cooperation of several highly skilled sorts to calibrate these burettes for a variety of substances. Chemist Emmara is an old friend from the Undercity who has helped me with similar endeavors. Thunder Bluff smells like a barn to me, but Jana Winterhoof is an alchemist with exacting standards. And while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair.", ["objectivesText"] = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128676 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 25, ["flags"] = 0 } } },
[39347] = { ["id"] = 39347, ["name"] = "Channeling Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "While it's no secret my time is more valuable than... well, anyone's, I fear I must step in and help to replace my decoction conduit. You will also play a crucial part in this, <name>, as my liaison with the blacksmiths. The thought of getting soot on my robes curls my toes. Here's a list of what we'll need done. Meanwhile I'll be out gathering the rest of what's needed.", ["objectivesText"] = "Talk to Alard Schmied about the list of things you need done. Provided item:", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 27, ["flags"] = 0 } } },
[39348] = { ["id"] = 39348, ["name"] = "Halls of Valor: The Prime Ingredient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39349, 39350, 39351 }, ["description"] = "This first ingredient can only be obtained by visiting the next realm. Fortunately for us, there's a gate in Stormheim that can take you there. In the Halls of Valor, there is a sand that's used for polishing their architecture. Eternity Sand , it's called. I'll need an ample amount of it as the base for the new glass. This ingredient won't be easy to work with either. I'll need something to keep me going, you know, keep my stamina up.", ["objectivesText"] = "Retrieve the Eternity Sand from Heroic: Halls of Valor, craft a Flask of Ten Thousand Scars and return both items to Alard in Dalaran. Progress: What a sight the Halls of Valor must be. You'll have to tell me about them sometime after your return.", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124101, 124102, 124103, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136784 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 28, ["flags"] = 0 } } },
[39349] = { ["id"] = 39349, ["name"] = "Black Rook Hold: Heavy, But Helpful", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39350, 39351 }, ["description"] = "The next ingredient on the list will supposedly add strength to the mix, according to Deucus. I've heard of it before, but haven't really used it. It's called Sabelite Sulfate , and it's said the elves of Black Rook Hold use it in their blacksmithing. Something like that won't just be lying around. You may have to delve deep into the hold to find it. And due to its weight, I may need a concoction of yours to compensate, something to give me a bit more strength.", ["objectivesText"] = "Retrieve some Sabelite Sulfate from Heroic: Black Rook Hold, craft a Flask of the Countless Armies and return both items to Alard in Dalaran. Progress: I hope Deucus was right about these ingredients. This'll be the first time I'm making something like this.", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124101, 124102, 124103, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 29, ["flags"] = 0 } } },
[39351] = { ["id"] = 39351, ["name"] = "The Emerald Nightmare: Rage Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39349, 39350 }, ["description"] = "Now that we have all the ingredients assembled, we need one last thing. The fire of my forges burn hot, but not hot enough to work these ingredients into glass. For that, we need more heat. The heat of a dragon, to be exact. I'm aware of one that has emerged from the Emerald Dream in a corrupted state. Corrupted or not, a dragon's heart burns with enough heat to melt the strongest of materials. Bring me its heart and you'll have your conduit.", ["objectivesText"] = "Travel to the Emerald Nightmare and acquire Nythendra's Heart . Bring it to Alard in Dalaran. Progress: I'm getting the mixture ready now. As soon as you return with the heart, I'll begin the construction.", ["rewardXP"] = 6140, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136820 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 31, ["flags"] = 0 } } },
[39372] = { ["id"] = 39372, ["name"] = "Witch of the Wood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You saved me at Riverbend not long ago. It is the reason I vouched for you as emissary to this tribe, and the only reason you're alive here now. I consider my debt to you paid. You must prove yourself to the Bloodtotem chieftain before he will speak with you. Within the forest is the Witch of the Wood , a harpy mother who recently descended into this territory. If you are able to defeat her and show her carcass to the Bloodtotem, they might allow you an audience with Torok.", ["objectivesText"] = "Defeat the Witch of the Wood .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39373] = { ["id"] = 39373, ["name"] = "Hags of a Feather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The drogbar you freed me from were unusually aggressive. The tribe in the nearby caves seems to be apart from the rest of them, but that didn't stop the Bloodtotem from going on the offensive just in case, capturing some of their number. That move left the woods exposed to the harpies, however. Your help dealing with these witches would not go unnoticed by Torok. Bring back their feathers as proof of death.", ["objectivesText"] = "Collect 50 Hag Feathers from Witchwood Hags in the Witchwood. Progress: Your size belies your strength, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128380, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39374] = { ["id"] = 39374, ["name"] = "An Audience with Torok", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I should warn you that Torok is easily displeased and is hateful of outsiders. Be on your guard. We will seek an audience with him at his tent at the Cliff's Edge. As the Rivermane Emissary here, I am afforded some protection against aggression, but they have made no such promises about you.", ["objectivesText"] = "Speak with Torok Bloodtotem. Progress: I just hope the Bloodtotem don't cut us down for demanding their chieftain's time.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39381] = { ["id"] = 39381, ["name"] = "Rock Troll in a Hard Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "We should leave this place while we have a chance. The Bloodtotem are amassing at their village to the north, and I believe they intend to kill my people. Let me know when you are ready to go, and I can take us to a safe place quickly.", ["objectivesText"] = "Speak with Navarrogg to meet him at a safe location.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39383] = { ["id"] = 39383, ["name"] = "Dishonored", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38382, 39384 }, ["description"] = "Xandris the Dishonored was among the first to betray his brethren and accept the curse of Xavius. During the great war, it was he who led the slaughter of many of my dearest friends. The last time I met him on the battlefield he fled. Help me to finally dispense justice on this foul being.", ["objectivesText"] = "Slay Xandris the Dishonored .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95395, ["x"] = 0.61, ["y"] = 0.732 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95396, ["x"] = 0.628, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.732 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39384] = { ["id"] = 39384, ["name"] = "The Corruptor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38382, 39383 }, ["description"] = "Xandris has been slain, but there are others that must be dealt with if my grove is to be saved. During the great war, Kagraxxis took great pleasure in corrupting the lands he once called home. Were it not for the foolish mercy of my fellow druids, I would have slain him myself. Find the demon and bring justice upon him. I must entrust this task to you alone, for I sense an even darker presence here... one that requires my personal attention.", ["objectivesText"] = "Slay Kagraxxis the Corruptor . Progress: Kagraxxis must be slain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 12844, 57374, 57375, 57376, 57377, 57378, 57379, 206576, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95396, ["x"] = 0.628, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91650, ["x"] = 0.65, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39385] = { ["id"] = 39385, ["name"] = "A Gift for Greymane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38873, 38878, 38882, 39153, 39154, 39155, 39385 }, ["series"] = { 38872, 38873, 38878, 38882, 39153, 39154, 39155 }, ["description"] = "It looks like the Gilnean infiltrators brought some heavy ordnance to the fight. It's likely they intend to use them on the walls of Dreadwake's Landing. If these could be rigged to Greymane's ship, it could make for a decisive end to his assault on the outpost.", ["objectivesText"] = "Plant 3 Gilnean Heavy Explosives onto the hull of Greymane's ship and detonate them at a safe distance. Progress: <insert>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128287, 129225, 129226, 129227, 129228, 132762, 132763, 132764, 132765, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93603, ["x"] = 0.55, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 137, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 137, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39386] = { ["id"] = 39386, ["name"] = "Procuring a Prototype", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39656, 39670 }, ["description"] = "If Addie's going to be a more permanent member of the huntin' party, then she'll need some specialty gear for someone her size. My munitions expert should have some ideas about what kind of weapon would best suit a gnome. Stop by his camp and let him know that I'll be needin' a prototype soon.", ["objectivesText"] = "Find Razik Gazbolt at Icepine Point.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39387] = { ["id"] = 39387, ["name"] = "The Skies of Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["series"] = { 39322 }, ["description"] = "When you are ready, join me at the base of Thunder Totem. I would be honored to have you at my side as my tribe once again swears its allegiance to the young Mayla. Together, we are Highmountain !", ["objectivesText"] = "Speak with Lasan Skyhorn at the base of Thunder Totem. Progress: Have you had any luck with Lasan?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 141394, 237812, 246937, 257401 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39389] = { ["id"] = 39389, ["name"] = "It Hungers for Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 40218, 41759, 41767 }, ["description"] = "Bloodstones contain a great deal of power that can only be awakened once they are fed. Yet this stone does not feast on fish and cakes. It hungers for blood; the more powerful, the better. There's an infestation of demons just east of here. I need you to nourish my stone with their blood, so that I may unlock its power.", ["objectivesText"] = "Let the Bloodstone feed on the blood of demons. Progress: Has the Bloodstone been sated yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39390] = { ["id"] = 39390, ["name"] = "A Mysterious Text", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39330, 39566 }, ["description"] = "You found a water-logged tome near the bones of a massive creature. Written in an unfamiliar language, the book is adorned with runes and alchemical symbols. Perhaps another alchemist would be able to tell you more.", ["objectivesText"] = "Bring the Runewritten Tome to Deucus Valdera in Dalaran. Progress: You found something down in Azsuna, <name>? Do share. It's so rare for something interesting to walk through the door of my quiet little shop.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128224, 128290, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39391] = { ["id"] = 39391, ["name"] = "Pet Rocks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I raise creatures born of the earth to help defend myself and my people. When I was captured, I ordered them to stay behind at our home, but they are often disobedient and likely tried to follow me. If they did, I fear the Bloodtotem may have captured them, or worse. In my current state, I can't muster the strength to find them. If you find them, it would be much appreciated.", ["objectivesText"] = "Find Navarrogg 's pets. Progress: These beasts are not terribly bright, but they are loyal in their way.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39392] = { ["id"] = 39392, ["name"] = "Bear Huntin'", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "They say a single hair from the back of a bristlefur bear is sharp enough to cut a dwarf's beard. But if the fur doesn't kill ya, the maul will. Some lesser hunters have been a meal for those bears. Show me you're more than a snack and bring me back a few of those bristlefur pelts .", ["objectivesText"] = "Collect 4 Bristlefur Pelts within the Fields of An'she. Progress: Procuring a few Bristlefur Pelts should help sell me on your huntin' skills.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128286, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39393] = { ["id"] = 39393, ["name"] = "Moonclaw Vale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39393 }, ["objectivesText"] = "Defend Moonclaw Vale Free Moonclaw druids Interact Small Normal Large", ["rewardGold"] = 619600, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend Moonclaw Vale", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Free Moonclaw druids", ["amount"] = 20, ["type"] = 0, ["objectID"] = 95747, ["orderIndex"] = 1 }, { ["text"] = "Interact", ["amount"] = 20, ["type"] = 0, ["objectID"] = 97799, ["orderIndex"] = 2 }, { ["text"] = "Small", ["amount"] = 100, ["type"] = 0, ["objectID"] = 98089, ["orderIndex"] = 3 }, { ["text"] = "Normal", ["amount"] = 34, ["type"] = 0, ["objectID"] = 98087, ["orderIndex"] = 4 }, { ["text"] = "Large", ["amount"] = 20, ["type"] = 0, ["objectID"] = 98088, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641 },
[39405] = { ["id"] = 39405, ["name"] = "Stories of Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39405 }, ["description"] = "The writings carried by the priestess appear to be the first part of an epic poem describing the history of Ashildir, the ancient queen of the Valkyra. If Ashildir has a connection to the shieldmaidens here, you may be able to use that to your advantage. The answer to her involvement likely lies within the remaining text.", ["objectivesText"] = "Collect 8 verses of Ashilvara from Priestesses of Eyir in Skold-Ashil. Progress: This appears to be the last verse.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 126946 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94228, ["x"] = 0.630667, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.630667, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 128324 } },
[39417] = { ["id"] = 39417, ["name"] = "Rating Razik", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39417 }, ["series"] = { 39859, 40170, 40216, 40217 }, ["description"] = "Hemet is expecting an update on how my munitions research and development is going. I'm sure you'll be happy to tell my boss that my latest creation worked flawlessly! You can find him at his camp near the hunters' lodge.", ["objectivesText"] = "Find Hemet Nesingwary at his Highmountain retreat.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[39425] = { ["id"] = 39425, ["name"] = "Stonedark Crystal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Without my crystalline focus, my powers are weak. Those who captured me took it, and I know not where it is now. I'm sure one of the Feltotem has it. If you find it, please return it to me.", ["objectivesText"] = "Find Navarrogg 's Stonedark Focus . Progress: I have power over the earth without my crystal, but my power is much greater with it than without.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128343, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39426] = { ["id"] = 39426, ["name"] = "Blood Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You have proven a much greater ally than the Bloodtotem ever were. With my focus crystal, my wounds are healed. I fear Frag was too far gone to revive. Torok and his Bloodtotem will suffer for what they have done to us. Let's pay them a visit before they can mount an attack against the cave of my people.", ["objectivesText"] = "Defeat Torok Bloodtotem at Torok's Bluff. Progress: Drogbar are not violent by nature, despite our size. But the Bloodtotem crossed us, and they pay the debt in blood.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 133114, 133115, 133116, 133117, 133118, 133119, 133120, 133121, 133122, 133124, 237812, 246937, 257722 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39427] = { ["id"] = 39427, ["name"] = "The Eagle Spirit's Blessing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "The spear is linked to a spirit called Ohn'ahra. It has been tradition for us to speak with her and receive her blessing before going after the spear. She may also impart some knowledge. If you would accompany me to Spiritwatch Point, I will summon the Eagle Spirit and ask for its blessing in the coming fight.", ["objectivesText"] = "Receive the Eagle Spirit's blessing at Spiritwatch Point in Highmountain. Progress: We've done it!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 110821, ["x"] = 0.599, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39429] = { ["id"] = 39429, ["name"] = "Assaulting the Haglands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38910, 38913, 39318, 39321, 39322, 39387, 39429 }, ["description"] = "Proceed on foot into the Haglands and slay any harpies you find. Quell their numbers! We will provide air support and force your prey to the ground where you can deal with them. Show these witches the fury of your... well... your \"you.\"", ["objectivesText"] = "Slay 8 Crawliac Harpies and 6 Skywhisker Loyalists in the Haglands. Progress: It has been many years since we have had to enter the Haglands in force.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95410, ["x"] = 0.4905, ["y"] = 0.3715 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4905, ["y"] = 0.3715 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 93, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 93, ["name"] = "Skyhorn Tribe", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39431] = { ["id"] = 39431, ["name"] = "Mending the Filter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39337, 39338, 44112 }, ["description"] = "Bringing back the cloth in such a manner would not be beneficial to Deucus. Perhaps there's a tailor here in Val'sharah who'd be willing to mend it for you. The priestess who helped you earlier may know of such a person.", ["objectivesText"] = "Try to find the whereabouts of a tailor in Val'sharah who can help you mend the silk.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128517 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 15, ["flags"] = 0 } } },
[39437] = { ["id"] = 39437, ["name"] = "Deep in the Cavern", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["description"] = "We're getting tired of those murlocs. They skitter around the cavern like they own it. They stole some of our most precious relics and got their fishy fins all over them. Kill a few of them so they know they don't run things around here.", ["objectivesText"] = "Slay 8 murlocs in Stonedark Cavern. Progress: Slippery little critters, aren't they?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39438] = { ["id"] = 39438, ["name"] = "Guhruhlruhlruh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["description"] = "The murlocs are usually pretty scared of us, but some bigger one led them into our cavern and they're getting too brave. Kill their leader. I think its name is something like \" Guhruhlruhlruh .\"", ["objectivesText"] = "Defeat Guhruhlruhlruh . Progress: Can you pronounce murloc names? I never can.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 130295, 130296, 130297, 130298, 130313, 130314, 130315, 130316, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39439] = { ["id"] = 39439, ["name"] = "Stonedark Relics", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["series"] = { 39440 }, ["description"] = "The murlocs managed to steal some of our sacred relics and carry them down into the lower cavern. While we warm up, do you think you could go find them?", ["objectivesText"] = "Recover the Chain of Resistance, Wheel of Fortitude , and Rod of Bearing . Progress: We have possessed these relics for generations until the murlocs put their fishy flippers on them.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128697, 128703, 128704, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39440] = { ["id"] = 39440, ["name"] = "You Lift, Brul?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 39437, 39438, 39439, 39440 }, ["series"] = { 39439 }, ["description"] = "Do you even lift? If you can carry these weights to the statue of Liftbrul and back, maybe we can talk.", ["objectivesText"] = "Carry the weights to the statue of Liftbrul and return to Damrul the Stronk . Progress: Those arms fallin' off?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659, ["questLines"] = { { ["id"] = 5917, ["name"] = "Stonedark Cavern: Trials of Liftbrul", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39455] = { ["id"] = 39455, ["name"] = "Cave of the Blood Trial", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "All Bloodtotem and distinguished guests must go through a trial of blood in the cavern beneath this outpost. I hope it's a good sign that they wish you to participate in this rite of passage. You will need to show proof of your deeds, defeat a Warmonger in single combat, then perform sacrifice at an altar deep in the cavern.", ["objectivesText"] = "Place the Witch of the Wood's carcass on the altar and defeat a Warmonger in single combat. Progress: Are you afraid of the dark?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95256, ["x"] = 0.3895, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.3895, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 653, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39456] = { ["id"] = 39456, ["name"] = "Unexpected Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 750, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "You have gained my trust. Not all drogbar are as violent as the savages led by Dargrul the Underking, nor are all tauren as bloodthirsty as the Bloodtotem. You may tell Mayla Highmountain that she has our support. The cavern we call home is yours to explore freely as well, <name>.", ["objectivesText"] = "Speak with Mayla Highmountain at Thunder Totem. Progress: Has Torok agreed to join us?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140336, 141395, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 13, ["flags"] = 0 } } },
[39472] = { ["id"] = 39472, ["name"] = "Cut Out the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122, 39472 }, ["series"] = { 39059, 39060, 39061, 39062, 39063, 39092, 39122 }, ["description"] = "This map points out the strategic locations of the Forsaken forces around Greywatch. A marker to the east indicates an apothecary camp where Dread-Riders are being supplied from. If you were to take out the apothecary in charge of creating this plague, it could stem the invasion and prevent the Dread-Riders from spreading the plague any further.", ["objectivesText"] = "Kill Apothecary Curseheart in the Dread-Rider Incursion.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129250, 129251, 129252, 129253, 129254, 129255, 129256, 129257, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 94318, ["x"] = 0.715, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 136, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 136, ["name"] = "The Secret of the Shieldmaidens", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39487] = { ["id"] = 39487, ["name"] = "Crystal Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39488, 39489, 39498, 39661, 42104 }, ["description"] = "A drogbar stonecaster known as Gelmogg entered our sacred water caverns and aims to draw its power into himself. We must destroy him before he gets too powerful. He is in the upper caverns.", ["objectivesText"] = "Slay Gelmogg . Progress: The drogbar used to control only earthen magic, but it seems they've found a way to draw power from other sources.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 133070, 133071, 133073, 133074, 133075, 133076, 133077, 133079, 133081, 133082, 133084, 133085, 133086, 133087, 133088, 133090, 237812, 246812, 246937, 264477 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39488] = { ["id"] = 39488, ["name"] = "Balance of Elements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39487, 39489, 39498, 39661, 42104 }, ["description"] = "The drogbar place their foul crystals in our cave to absorb the magic within, and then they collect them when they are saturated with power. We must recover the crystals so the magic might dissipate and be suffused back into the waters, or else the drogbar will find ways to corrupt the magic to their own purposes.", ["objectivesText"] = "Recover 10 Empowered Crystals . Progress: I believe the drogbar are learning stronger magic now that they have possession of the Hammer of Khaz'goroth.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128393, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39489] = { ["id"] = 39489, ["name"] = "Invading Spelunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39487, 39488, 39498, 39661, 42104 }, ["description"] = "The drogbar and their earthen furies have overrun the cavern. They're perverting the magic within and destroying the elementals that have forever dwelled in this place. Let's work together to remove them from this sacred cave.", ["objectivesText"] = "Slay 7 Drogbar Manathirsters or Violent Crageaters . Progress: We must cleanse the cavern of the drogbar.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.384, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39491] = { ["id"] = 39491, ["name"] = "Ormgul the Pestilent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39316, 39496, 39733 }, ["description"] = "We've lived at peace with the drogbar for years--our tribe even more than the others. But we were betrayed in our last trade with them at Riverbend. They usually supply us with potent alchemy to prevent insects from infesting our fields. This time, led by Ormgul, they have attacked the crops that sustain us all. Ormgul the Pestilent is the one who brought the infection to our farmland. Destroy him, and bring me whatever he uses to attract the bugs to our land.", ["objectivesText"] = "Slay Ormgul the Pestilent and acquire his Bug Sprayer . Progress: The Rivermane are a peaceful tribe. We provide the others with food and healing in exchange for protection and equipment. When pressed, however, I am willing to put my magic to more violent use.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121656, 121657, 121658, 121659, 121727, 121729, 121731, 128397, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39495] = { ["id"] = 39495, ["name"] = "Hidden No More", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39515, 39516, 39663 }, ["description"] = "Now that you've uncovered the demons, I can sense them, too. Specifically, I sense a very powerful fel lord deeper in the cave. You need to grab his power while you still can. If you can deal with their leader, we will take care of the rest of his forces in that cave.", ["objectivesText"] = "Kill Fel Lord Caza and take his fel power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 128946, 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39496] = { ["id"] = 39496, ["name"] = "The Flow of the River", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 38907, 38911, 39316, 39491, 39733 }, ["description"] = "We can leave Farmer Maya in charge of the farmland now that the greatest threat has been reduced. But we aren't out of hot water just yet, <name>. The fisheries are just as important as our fields, and they are in even greater danger than the farm if what Angler Creel says is true.", ["objectivesText"] = "Meet with Angler Creel in Whitewater Wash.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812, 245409 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93833, ["x"] = 0.436, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39498] = { ["id"] = 39498, ["name"] = "High Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 39277, 39487, 39488, 39489, 39661, 42104 }, ["description"] = "Riverbend! Is that what the Underking said? That is my home and the place where we store our winter supplies. We must make it there at all speed and warn them. Meet me there.", ["objectivesText"] = "Speak with Jale Rivermane at Riverbend.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 59776, 59777, 59778, 141396, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97662, ["x"] = 0.484, ["y"] = 0.804 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39515] = { ["id"] = 39515, ["name"] = "Vengeance Will Be Mine!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39516, 39663 }, ["description"] = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be. Quickly, <name>, teach us what you have learned.", ["objectivesText"] = "Teach the Vengeance specialization to your assembled demon hunters. Progress: We await your instruction, <name>.", ["rewardGold"] = 169800, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39516] = { ["id"] = 39516, ["name"] = "Cry Havoc and Let Slip the Illidari!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39515, 39663 }, ["description"] = "This is why the Legion fears us. We have the ability to turn their secrets against them and in so doing become stronger than they ever can be.", ["objectivesText"] = "Teach the Havoc specialization to your assembled demon hunters. Progress: We await your instruction, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39575] = { ["id"] = 39575, ["name"] = "The Path of Huln", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Armies are vital to the success of a war. But so are symbols. For our people, few things make for a better symbol than the blessings of our most eldest ancestors. Mayla must walk the Path of Huln. The path is dangerous, and she may only bring two people with her: a spiritwalker to guide her and a champion to protect her. Will you be the champion?", ["objectivesText"] = "Follow Spiritwalker Ebonhorn on the Path of Huln.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94571, ["x"] = 0.448, ["y"] = 0.655 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39577] = { ["id"] = 39577, ["name"] = "An Ancient Secret", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Before Mayla may be pronounced High Chieftain, there is one more vision she must see. I wish to show you as well. It is an ancient secret, handed down along the Highmountain bloodline. I ask for your discretion in keeping it that way.", ["objectivesText"] = "Assist Spiritwalker Ebonhorn in Neltharion's Vault.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39578] = { ["id"] = 39578, ["name"] = "Titanic Showdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The tale of Huln did not end with him acquiring the Hammer of Khaz'goroth. No. For that part, we must venture deeper into this cavern. A final brazier awaits us ahead. Come, let us see what happened next.", ["objectivesText"] = "Find and aid the spirit of Huln Highmountain .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121660, 121661, 121662, 121663, 130312, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39579] = { ["id"] = 39579, ["name"] = "The Backdoor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "This will take Mayla some time to adjust to. That being said, we should return to Thunder Totem. Just south of here is a tunnel that should take us through the old drogbar slave enclave and then to an opening beyond. We keep a small Skyhorn outpost there to watch and ensure nothing enters or leaves this vault without us knowing about it. They should be able to fly us back.", ["objectivesText"] = "Escape the Vault.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 133129, 133136, 133137, 133138, 133139, 133141, 133142, 133143, 133144, 133146, 237812, 245456, 246937 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 108305, ["x"] = 0.474, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39580] = { ["id"] = 39580, ["name"] = "The High Chieftain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "I understand what Ebonhorn has been trying to tell me for a while now. Our people do not need a hammer, we need a leader. One willing to stand against any threat, even if they are terrified to do so. And between you and me, I am definitely terrified, but resolved. Let us return to Thunder Totem and prepare ourselves for war.", ["objectivesText"] = "Speak with Mayla Highmountain at Thunder Totem.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 141397, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 108305, ["x"] = 0.474, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 652, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39588] = { ["id"] = 39588, ["name"] = "They Will Pay With Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "The tauren go too far. I did not escape their outpost for fear that they would attack the cave and slaughter my people. It looks like they planned to do it all along. Slay some of the Feltotem. Thin the herd.", ["objectivesText"] = "Slay 10 Feltotem Tauren. Progress: These tauren have always been bloodthirsty. The Highmountain chieftain has barely been able to stop them killing all of us.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95421, ["x"] = 0.452, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39590] = { ["id"] = 39590, ["name"] = "Ahead of the Game", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38331, 39591, 39595 }, ["description"] = "The watcher Yotnar keeps the vault, and he is a fickle one. Challengers come from far and wide seeking the trials, but the watcher chooses not to see. If you wish to catch his eye, show him you are worth being seen. Some of these challengers await in camps throughout the Valley of the Sword. Bring their heads to Yotnar, so that he may see them, and you.", ["objectivesText"] = "Collect the heads of the Gutspill, Rumblehoof, and Felskorn champions in Valley of the Sword. Progress: An ironic gift you bring me, challenger.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128508, 128509, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.461 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39591] = { ["id"] = 39591, ["name"] = "A Trial of Valor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38331, 39590, 39595 }, ["description"] = "To seek the Aegis of Aggramar, a champion must complete three great trials before riding into glorious battle through the Gates of Valor. Here you will find the knowledge of the trials you must seek out, as well as the first challenge you must face. Above us, adorning the central plateau, you will find the archive for the Trial of Valor. Seek it out, and learn where your path leads.", ["objectivesText"] = "Power up the archive device and view the holographic record for the Trial of Valor in the Terrace of the Watchers.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 142533, 142534, 143506, 143510, 143514, 143518, 237812, 246936, 249400, 251821, 254267, 254579 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39592] = { ["id"] = 39592, ["name"] = "A Trial of Will", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Upon the highest point of the plateau above, you will find the archive device for the Trial of Will. Seek it out to learn what awaits you in Thorim's Peak. Be on your guard, outsider. The one called Skovald has left behind many of his army, and they will no doubt be unfriendly.", ["objectivesText"] = "Power up the archive device and view the holographic record for the Trial of Will in the Terrace of the Watchers.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39593] = { ["id"] = 39593, ["name"] = "The Shattered Watcher", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "When your adversary - the one called Skovald- completed his first trial, he used his ill-begotten powers to sunder my physical body. I cannot allow a contender to pass through the vault while I remain unwhole. His forces have no doubt scattered my pieces through the plateau which they currently desecrate. Bring them back to me, so that I may properly guide your trial.", ["objectivesText"] = "Collect the pieces of Yotnar's body from the Terrace of the Watchers. Progress: Have you managed to find them all?", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 121560, 128493, 128495, 128496, 128497, 129316, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39594] = { ["id"] = 39594, ["name"] = "A Trial of Might", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I owe you my gratitude for helping make me whole again, outsider. It is clear that you are worthy to take on the trials. Go now into the vault. There you will find the archive for the first trial you must undertake. I will meet you inside.", ["objectivesText"] = "Activate the archive device to learn about the Trial of Might.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96258, ["x"] = 0.464, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39595] = { ["id"] = 39595, ["name"] = "Blood and Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39595 }, ["series"] = { 38331, 39590, 39591 }, ["description"] = "The challengers gathered in the Valley of the Sword have brought with them offerings to the watchers of the vault. It might be a good idea to take some of these offerings with you to help in appeasing Yotnar .", ["objectivesText"] = "Collect 7 Challenger's Tributes from Valley of the Sword. Progress: What is this you bring? You honor me, outsider.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128511, 128512, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96257, ["x"] = 0.466, ["y"] = 0.445 }, { ["mapID"] = 634, ["npcID"] = 96258, ["x"] = 0.464, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 128512 } },
[39597] = { ["id"] = 39597, ["name"] = "The Blessing of the Watchers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38331, 39590, 39591, 39592, 39593, 39594, 39597 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "As is your due for passing the Trial of Might, I will grant you the blessing of the watchers . Furthermore, to aid you in your trials to come, I will bestow upon your artifact the power of the vault's keeper. May it serve you well in your time of need. Speak to me when you are ready to receive this gift.", ["objectivesText"] = "Speak to Yotnar to receive the blessing of the watchers .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 132775, 132776, 132777, 132778, 132779, 132780, 132781, 132782, 132783, 132785, 132786, 132787, 132788, 132789, 132790, 132791, 132792, 132793, 132794, 132796, 141398, 237812, 246937 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96258, ["x"] = 0.464, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96254, ["x"] = 0.424, ["y"] = 0.461 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 129, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 129, ["name"] = "The Trial of Might", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39602] = { ["id"] = 39602, ["name"] = "Where's Lyndras: Sewer Sleuthing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39605, 39667 }, ["description"] = "Linzy said that Lyndras escaped down into the sewers of Dalaran. Surely there must be a clue down there as to his whereabouts. Hopefully he hasn't caused any more commotion amongst the citizens of Dalaran.", ["objectivesText"] = "Search the sewers for clues as to where Lyndras has gone.", ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 20, ["flags"] = 0 } } },
[39605] = { ["id"] = 39605, ["name"] = "Where's Lyndras: Downward Spiral", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39667 }, ["description"] = "Flitz mentioned a manhole near Violet Hold, perhaps that would be the best place to pick up Lyndras' trail.", ["objectivesText"] = "Continue following Lyndras' trail.", ["rewardXP"] = 6140, ["rewardItems"] = { 139460 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 21, ["flags"] = 0 } } },
[39614] = { ["id"] = 39614, ["name"] = "Fish Out of Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["description"] = "The drogbar are on a rampage! They're smashing everything they can find and are throwing fish to the shore. Worst of all, it is the wrong time to harvest fish. They must be returned to the waters so they can breed.", ["objectivesText"] = "Return 8 Whitewater Carp to the river. Progress: We used to supply the drogbar with most of their food between our fish and crops. What will the fools eat now?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 237812, 245457 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95186, ["x"] = 0.412, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39645] = { ["id"] = 39645, ["name"] = "Calibration Experts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39345, 39346 }, ["description"] = "It will take the cooperation of several highly skilled sorts to calibrate these burettes. Myshalla Streambreeze in Feralas has demonstrated admirable attention to detail. I loathe Ironforge, but a resident named Krimple Proxmeasure is known for his precision. And while I'd never travel to Booty Bay without a lock on my wallet, Tryks Pourtrue has proven reliable and fair... mostly.", ["objectivesText"] = "Take the Uncalibrated Malloric Burettes to skilled alchemists for calibration.", ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127878, 127915, 128209, 128676 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 24, ["flags"] = 0 } } },
[39652] = { ["id"] = 39652, ["name"] = "Where Dragons Rule", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Thanks to your help, Thrymjaris was able to escape the clutches of that vile demon. She bid me wait for you, so that I could take you to her once you had finished dispatching your foes. She has gathered our brood at the top of Thorim's Peak to prepare for a counterattack. Would you join us?", ["objectivesText"] = "Speak to Vethir to fly to the top of Thorim's Peak.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132799, 132800, 132802, 132803, 132804, 132805, 132806, 132808, 132810, 132811, 132813, 132814, 132815, 132816, 132817, 132819, 141399, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.816667 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39654] = { ["id"] = 39654, ["name"] = "Odyn and the Valarjar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 41052, 42814, 42815 }, ["description"] = "Fear not, mortal, you are not dead. I was directed to collect you before your demise by Odyn himself. I will take you to Odyn now, follow me.", ["objectivesText"] = "Follow Danica to see Odyn .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39656] = { ["id"] = 39656, ["name"] = "Wolf Pack Attack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39386, 39670 }, ["description"] = "It's time to attack the pack! I've preloaded the hand cannon. All you have to do is point and shoot. The critters should survive the blast and hit the ground running. The howlers will be distracted by the critters, allowing you to focus on killing the packleaders. Happy hunting!", ["objectivesText"] = "Shoot the Critter Hand Cannon near wolf packs so that they scatter, allowing the packleaders to be singled out. Progress: The critter hand cannon is loaded and ready for use! Just aim for one of the packs nearby. The packleaders should be easy to kill once the howlers are distracted.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128651, 131933, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39661] = { ["id"] = 39661, ["name"] = "Lifespring Cavern", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38907, 38911, 39272, 39277, 39316, 39487, 39488, 39489, 39490, 39491, 39496, 39614, 39661 }, ["series"] = { 39277, 39487, 39488, 39489, 39498, 42104 }, ["description"] = "The drogbar have taken over my cavern. It is where we Rivermane practice our water magic and get much of the purest healing water in Highmountain . Meet me there and we will cleanse that sacred place of these dark-dwellers.", ["objectivesText"] = "Meet Jale Rivermane at Lifespring Cavern.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95956, ["x"] = 0.412, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96520, ["x"] = 0.384, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 144, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 144, ["name"] = "Rivermane Tribe", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39663] = { ["id"] = 39663, ["name"] = "On Felbat Wings", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38728, 38765, 38766, 38813, 38819, 39262, 39495, 39515, 39516 }, ["description"] = "It is time. We have dealt the Legion's forces a crippling blow from which they will never recover. Quickly, let us mount up and take the fight to Tyranna's command center.", ["objectivesText"] = "Grab a felbat from Illidari Whitemoon and fly up to the Fel Hammer.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 21, ["flags"] = 0 } } },
[39667] = { ["id"] = 39667, ["name"] = "Where's Lyndras: Leyflame Larceny", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605 }, ["description"] = "The guards here must have seen Lyndras come through. The trail of ley dust isn't exactly hard to miss either. Perhaps one of the guards knows what became of Lyndras.", ["objectivesText"] = "Ask the Violet Hold guards about Lyndras.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 22, ["flags"] = 0 } } },
[39670] = { ["id"] = 39670, ["name"] = "Critter Scatter Shot", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["series"] = { 39386, 39656 }, ["description"] = "The howlers in these hills travel in packs. Three against one isn't a fight I want to pick. Luckily those wolves are no match for my engineering skills! I just put the finishing touches on the prototype of a device that will help scatter the pack. All I need now is some ammo... Snatch me some rabbits from the meadow south of here, and I'll let you be the first to try out the hand cannon.", ["objectivesText"] = "Catch rabbits in Sunfrost Glade. Progress: Have you snatched the rabbits yet?", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 128655, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96513, ["x"] = 0.575333, ["y"] = 0.565333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.565333 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39681] = { ["id"] = 39681, ["name"] = "The Properties of Leystone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38499 }, ["description"] = "I've never seen anything like this \"leystone\" ore. It's light, like mithril, but it carries much more of a magical energy... more even than saronite or elementium. Let's try making something with it. How about a nice pair of gauntlets?", ["objectivesText"] = "Observe Alard as he attempts to work with the leystone ore.", ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39682] = { ["id"] = 39682, ["name"] = "Grand Theft Felbat", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 38723, 40253 }, ["description"] = "You heard what Maiev said. We need to get out of here. There is an elevator shaft at the far end of these caverns. Let us make our way there.", ["objectivesText"] = "Ride a felbat to the upper vault.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128945, 132243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 24, ["flags"] = 0 } } },
[39683] = { ["id"] = 39683, ["name"] = "Forged in Fire", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, <name>.", ["objectivesText"] = "Kill Immolanth and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 25, ["flags"] = 0 } } },
[39684] = { ["id"] = 39684, ["name"] = "Beam Me Up", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "To the east is an intricate prison chamber designed to contain the beholder, Glazer . It began malfunctioning shortly after the breach. You will need to rotate the mirrors in the room to focus an energy beam onto the creature. Otherwise, we cannot break through Glazer 's impenetrable shield. Hurry. Altruis went ahead to assist the others, but we are losing the fight.", ["objectivesText"] = "Break Glazer 's shield.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 132243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 26, ["flags"] = 0 } } },
[39685] = { ["id"] = 39685, ["name"] = "Frozen in Time", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The Wardens kept all kinds of dangerous monsters locked up within this Vault. Now that Gul'dan's forces have breached the walls, it's proving rather... inconvenient. Many of our forces are occupied with containing a fearsome magma destroyer in the southern chamber. With us freshly awoken from stasis, we don't have the means to take it down. However, we might be able to reactivate the room's containment field. Go join up with Kayn. Do whatever it takes to seal that chamber!", ["objectivesText"] = "Activate the Countermeasures in the Vault of Ice.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 127853, 128949, 132243, 133315, 226193, 226194, 232877, 247820, 247821 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 27, ["flags"] = 0 } } },
