[39689] = { ["id"] = 39689, ["name"] = "Illidari, We Are Leaving", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39694, 40253, 40254, 40255, 40373, 95215 }, ["description"] = "The Legion has begun its invasion of our world. Across Kalimdor and the Eastern Kingdoms, brave defenders are answering the call to arms. However, they will ultimately fail without your aid. You Illidari were uniquely trained as weapons against the Legion. I only ask that you come with me. Further instructions await you on the other side.", ["objectivesText"] = "Speak to Archmage Khadgar .", ["rewardXP"] = 145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 30, ["flags"] = 0 } } },
