[39691] = { ["id"] = 39691, ["name"] = "The Call of War", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Today, sorrow grips Stormwind, bastion of the Light. King Varian Wrynn has fallen in battle, leaving the crown to his son Anduin. The leaders of the Alliance have gathered to pay their respects. No doubt they will have need of your unique skills. You will find the king upon the throne of Stormwind Keep, attended by one of your fellow Illidari. I am needed in Dalaran. Good luck, $p.", ["objectivesText"] = "Speak to Jace Darkweaver in Stormwind Keep.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 97296, ["x"] = 0.725, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
