[39741] = { ["id"] = 39741, ["name"] = "Into Our Ranks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42634 }, ["description"] = "I feel that we should quickly welcome Akama into our ranks. It's important that the others see him treated as one of us, rather than as an outsider. Kor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies. It is time to officially raise them up as champions.", ["objectivesText"] = "Recruit Akama and Kor'vas Bloodthorn as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 8, ["flags"] = 0 } } },
