[39746] = { ["id"] = 39746, ["name"] = "A Ring Unbroken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 207, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 41335 }, ["description"] = "Our defeat at the Broken Shore was decisive. The Burning Legion has a foothold on Azeroth, and the best of our armies are retreating in tatters. The elders of the Earthen Ring have called an emergency council near the heart of our world - the Maelstrom. <name>, your triumphs throughout Azeroth and Draenor are the stuff of legend. We need you more than ever. Join me at the Maelstrom. Stormcaller Mylra will be flying there shortly - find her at Krasus' Landing here in Dalaran.", ["objectivesText"] = "Aid the shaman of the Earthen Ring at the Maelstrom. Stormcaller Mylra will fly you there from Krasus' Landing in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1572, ["db2PoiUiMapID"] = 725, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39756] = { ["id"] = 39756, ["name"] = "A Sound Plan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 42811, 42812 }, ["description"] = "The Legion still believes us crippled from the Broken Shore. They think we are unable to fight back. Let's prove them wrong. We've been hard at work mapping out the Broken Isles, learning everything we can about each region for our imminent assault. Once you've had a chance to peruse the map, you should leave for Dalaran at once and charge into the maw of the beast. We will end this madness for good. Light help us all.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39771] = { ["id"] = 39771, ["name"] = "The Voice of Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 726, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "The White Tiger has prepared a series of challenges for everyone who wants to possess the weapons of the storm. Now you know of their power - these are the very artifacts that Ra-den himself wielded during the age of the Titans. Come! I have led arena teams to victory across three continents. With me in your corner, you cannot lose!", ["objectivesText"] = "Travel to the Temple of the White Tiger and prove yourself worthy to wield the weapons of storm! Progress: We have trained our whole lives for this, <name>. We cannot fail.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39776] = { ["id"] = 39776, ["name"] = "Battle Worms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Snowmane Village behind us was caught completely off guard by the scale of this attack. I will hold the drogbar line here so the civilians have time to prepare their evacuation. The drogbar are using worms to burrow their way to the surface and deploy their troops. I am giving you command of our forces. Use them to slay these worms and cut off enemy reinforcements.", ["objectivesText"] = "Slay Naxa , Arxas , and Xist . Progress: Worms. Why did it have to be worms? I hate worms.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39777] = { ["id"] = 39777, ["name"] = "Buy Us Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["description"] = "We need time to evacuate Snowmane Village. Can you take the fight to these Mightstone drogbar and cull their numbers? I will direct my healers to get everyone that is unable to fight to safety.", ["objectivesText"] = "Slay 10 Mightstone drogbar. Progress: We need all the time you can buy us.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 37271, 37393, 37425, 38212, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97344, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97344, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39780] = { ["id"] = 39780, ["name"] = "The Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39860, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Mayla already chased the Underking into his cave. That is something we tell our children never to do. Reckless child, but hey, who wants to live forever? Let us join her in battle.", ["objectivesText"] = "Assault Dargrul the Underking.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121673, 121674, 121675, 121676, 130269, 130270, 130271, 130272, 237812, 245461, 246937 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39781] = { ["id"] = 39781, ["name"] = "Neltharion's Lair: Death to the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 42454 }, ["description"] = "I will direct my people to clear a path through this rubble and assault Dargrul's forces directly. It will be a ruse. Navarrogg proposed a plan that I believe has merit. He knows of a side entrance that might lead directly to Dargrul. Muster what allies of yours you can and strike at them through this side passage. Recover the Hammer of Khaz'goroth before that villain brings the mountain down on top of us. We will provide the distraction you need to get a shot.", ["objectivesText"] = "Recover the Hammer of Khaz'goroth . Progress: The war continues.", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 128765, 141400, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1458, ["db2PoiUiMapID"] = 731, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39786] = { ["id"] = 39786, ["name"] = "A Stone Cold Gamble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "The second target is a basilisk called Stonefang that lives off the bank of the nearby river. I put a bigger wager on him, so if you can take him out I'll make sure you get a cut. I'll need his jaw to verify the kill. Hurry, before those tauren get him first!", ["objectivesText"] = "Collect Stonefang's Jaw from Stonefang in Stonescar Gorge. Progress: Did you take him out?", ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138023, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39787] = { ["id"] = 39787, ["name"] = "Rigging the Wager", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "Care to help settle a bet, chum? Those tauren are Skyhorn, and they fancy themselves big-time hunters. I bet them a pretty penny that they wouldn't be able to take out some of the biggest beasts in Stormheim . If you take em out before they do, I'll split the wager. Deal? The first is a big eagle nesting in the foothills. They call him Spitefeather. You can bait him with some meat, but he's up pretty high, so you'll need a grapple gun to get there. I think there's one of them layin around here...", ["objectivesText"] = "Lure down and defeat Spitefeather to collect Spitefeather's Beak in the Stormtorn Foothills. Progress: You got my trophy yet?", ["rewardXP"] = 1415, ["rewardItems"] = { 127834, 132203, 138022, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39788] = { ["id"] = 39788, ["name"] = "The Runewood's Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39791, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "The Bonespeakers...they are corrupt... hungry for power. Cut them from my woods...", ["objectivesText"] = "Kill 8 Bonespeaker Runeaxes and 8 Bonespeaker Carvers in the Runewood. Progress: Has the corruption been removed?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39789] = { ["id"] = 39789, ["name"] = "Eating Into Our Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["series"] = { 39793 }, ["description"] = "Greetings traveler! You are welcome to rest at our camp, but if you plan on sticking around a while, I have a proposition for you. As you can see, the land here has been very good to us, providing a great natural bounty. Lately, however, the worg have become problematic, and are thinning the herds to unacceptable levels. I can't take care of them all, so I will offer a bounty for every worg slain in the mesa. Return to me when you have culled their pack a bit.", ["objectivesText"] = "Kill 10 Duskpelt worg in Amberfall Mesa.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138111, 138123, 138125, 138127, 138128, 138129, 138130, 138131, 138133, 138135, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97258, ["x"] = 0.514, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39791] = { ["id"] = 39791, ["name"] = "Lay Them to Rest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39796, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "I would ask a favor, outsider. As you step through the graves of ancient heroes, you will no doubt come across spirits of the restless dead, agitated by the Bonespeakers misdeeds. They must be returned to the earth where they are buried, so that they may be judged as well. Take this bough - it carries with it the essence of the Runewood. Channel its power into a weakened spirit, and it will return to rest.", ["objectivesText"] = "Use the Branch of the Runewood to send 8 weakened Restless Ancestors back to the earth.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 3456, 128772, 137663, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93446, ["x"] = 0.681, ["y"] = 0.485 }, { ["mapID"] = 634, ["npcID"] = 97270, ["x"] = 0.698, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39792] = { ["id"] = 39792, ["name"] = "A Stack of Racks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "So while we're waiting here, maybe you could fetch us up some grub. Them tauren were runnin low on meats, so I'm sure they'd be thankful to have more. I hear that musken ribs are the specialty here. The wild musken here are too lean for any good meat, but across the river there are some nice fat ones. Maybe you should check those out! Don't worry, I'm pretty sure there aren't any dragons over there...", ["objectivesText"] = "Collect 8 Meaty Racks of Musken Ribs from Stout Highland Runehorns in Jotunnwood. Progress: Aint nothin like some good old meaty musken ribs, eh pal?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 122577, 131811, 132203, 138020, 138111, 138123, 138125, 138126, 138127, 138129, 138131, 138133, 138134, 138135, 139773, 140216, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39793] = { ["id"] = 39793, ["name"] = "Only the Finest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["series"] = { 39789 }, ["description"] = "Say, you're a pretty good hunter, eh? Maybe you could help these tauren out by stocking them with some rare furs. I'm sure they'd appreciate it when they got back! I hear that Stormheim goat hair can be woven into all kinds of things. The rarest are from the silver-tail goats. I think I saw some in that mountain over there. Why don't you go and fetch some? I'm sure them tauren would pay you handsomely!", ["objectivesText"] = "Collect 18 Patches of Fine Goat Hair from Silvertail Mountain Goats in Nastrondir. Progress: Make sure to get the good stuff!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138021, 138111, 138123, 138124, 138125, 138127, 138129, 138131, 138132, 138133, 138135, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107675, ["x"] = 0.514, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39796] = { ["id"] = 39796, ["name"] = "To Haustvald", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39803, 39804, 40568, 44922, 44940 }, ["description"] = "Your next steps are clear, your feet know the way. Follow them to Haustvald and meet your fate! It is the tree you seek, the heart of the mystic Runewood. He will offer guidance, and probably leaves.", ["objectivesText"] = "Meet with Vydhar in the Runewood.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 2, ["flags"] = 1 } } },
[39799] = { ["id"] = 39799, ["name"] = "Our Next Move", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39832, 40714 }, ["description"] = "Have you seen the fog that surrounds us? The chill winds of Acherus have provided us with a perfect concealment from the prying eyes of the Legion! Under cover of this fog we've been able to send out scouting teams who've put together a fairly comprehensive map of the Broken Isles. Choose where we shall begin our assault. You, of course, shall have the honor of spearheading our efforts, but the rest of the Ebon Blade will follow your lead.", ["objectivesText"] = "Select your order's first assault point.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39801] = { ["id"] = 39801, ["name"] = "The Splintered Fleet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 39698 }, ["description"] = "Preparations have been made, and we are ready to set sail. We must strike out at once. Do not dally, or you will be left behind.", ["objectivesText"] = "Complete Sylvanas' mission to bring the fleet to Stormheim .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 139916, 139925, 139948, 139956, 139974, 139987, 140012, 140018, 237812, 246812, 246937, 253251 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 96686, ["x"] = 0.614, ["y"] = 0.093 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 91473, ["x"] = 0.36, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.093 }, ["mapCandidates"] = { ["npc"] = { 1, 634 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39803] = { ["id"] = 39803, ["name"] = "The Trials Continue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39804, 40568, 44922, 44940 }, ["description"] = "< Havi 's voice continues in your head as the raven stares on> If valor you seek, then to the bones you must speak! But first you must prepare!", ["objectivesText"] = "Meet with Havi in Valdisdall.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97074, ["x"] = 0.48, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39804] = { ["id"] = 39804, ["name"] = "Speaking of Bones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39788, 39791, 39796, 39803, 39804 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 40568, 44922, 44940 }, ["description"] = "The Trial of Valor will be your next test, and test you it will! But only a fool fights on an empty stomach. Are you a fool, outsider? No? Then lend these old bones a hand and butcher the moose for our meal. I will spin you a tale of rocks, trees and spirits.", ["objectivesText"] = "Help Havi butcher the moose and learn about your next trial.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 134, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 134, ["name"] = "The Trial of Valor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39816] = { ["id"] = 39816, ["name"] = "Champion: Thassarian", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself. <Mograine turns and nods to a nearby guard.> He should be here momentarily.", ["objectivesText"] = "Welcome your new knight.", ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39818] = { ["id"] = 39818, ["name"] = "Champion: Nazgrim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "Deathlord, I've found our wayward knight. He wishes to return to the Ebon Blade, in particular he wishes to speak with you himself. <Mograine turns and nods to a nearby guard.> He should be here momentarily.", ["objectivesText"] = "Welcome your new knight.", ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39832] = { ["id"] = 39832, ["name"] = "Plans and Preparations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39832, 40714 }, ["description"] = "Your weapon is stronger than ever, but it will need many more souls in order to reach its true potential. Siouxsie has been collecting reports from the scouts, she will direct you to our enemies and their screaming souls will empower your weapon further.", ["objectivesText"] = "Speak to Siouxsie the Banshee .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39837] = { ["id"] = 39837, ["name"] = "An Unworthy Task", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39848, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "This place is Helheim , the realm of the unworthy dead. Here, the spirits of the dishonorable spend eternity in an endless futile battle, always seeking glory but never able to attain it. We should not be here. We must find a way out. I will scout ahead - you should try and release some of these captive spirits here. Perhaps one may have some answers for us.", ["objectivesText"] = "Search among the caged vrykul in Helheim for one who can help your escape.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39847] = { ["id"] = 39847, ["name"] = "Sign This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39931 }, ["description"] = "Ah, a fellow scribe! You don't look too dim, so how 'bout you and I work together in an effort to discover what we can about the Broken Isles? (That's the big mass of islands we're floating over.) However! I never agree to a partnership without getting all the requisite legalities out of the way. Sign this for me and we're in business.", ["objectivesText"] = "Sign Professor Pallin 's contract. Progress: Did you remember to cross your t's and dot your lower case j's?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129043, 129047, 129211, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39848] = { ["id"] = 39848, ["name"] = "A Desperate Bargain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39849, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "It looks like your friend didn't make it. A pity, but we must move on. You'll want to plead our case to Helya. She is the ruler here. I would accompany you, but I'm afraid I wouldn't help your case. Meet me when you are finished. I will see if I can find the whereabouts of my shieldmaidens.", ["objectivesText"] = "Confront Helya and ask to be freed from Helheim . Progress: <The air hangs silent as you approach.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39849] = { ["id"] = 39849, ["name"] = "To Light the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39850, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "Helya must think her challenge unwinnable. We will show her different. I am unsure what she did, but Helya has weakened you somehow. I have seen similar effects on my shieldmaidens, and now they are trapped by Helya's minions. I may know a way, however. The Kvaldir ships carry special lanterns bound to this place to navigate through the fog. It is said that the light of these lanterns can release bonds of the spirit. There is a kvaldir ship nearby. See if you can find one there.", ["objectivesText"] = "Collect a Helheim Waylight from Bloodbeard in Helheim . Progress: Were you able to secure the lantern?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128854, 129239, 129339, 211279, 237812, 247234, 254878 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39850] = { ["id"] = 39850, ["name"] = "Sundered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39851, 39852, 39853, 39855, 39857 }, ["description"] = "I imagine the power of your weapon will be what allows us to defeat Geir, but right now you are too weak for the confrontation. We must reclaim the missing pieces of your spirit. Helya must have scattered them throughout her realm to keep them from you. If you can find them, shine the lantern and they should be set free. Be careful, though. It is unlikely that Helya left your spirit fragments unguarded.", ["objectivesText"] = "Find and release the Fragment of Will, Fragment of Might, and Fragment of Valor in Helheim . Progress: Have you recovered your power?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 22829, 22832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39851] = { ["id"] = 39851, ["name"] = "Allies in Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39852, 39853, 39855, 39857 }, ["description"] = "Our power alone may not be enough to fight the behemoth, Geir. Fortunately, Faljar was kind enough to send our allies into Helheim with us. Earlier, I had discovered several of them being tortured by the elemental forces of Helheim . You may think the dead can't drown, but with Helya's power, this is not the case. I could not release them then, but now that you possess the waylight, you may be able to. Seek them out and free them from an eternity of suffering!", ["objectivesText"] = "Release 8 Drowning Valkyra in Helheim . Progress: Once unbound, my Valkyra will throttle these wretched minions.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39853] = { ["id"] = 39853, ["name"] = "Victory is Eternal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39855, 39857 }, ["description"] = "There is no more cause for hesitation. Now is the time to strike. We will defeat this foul behemoth and meet Helya's bargain. The path out of Helheim awaits, outsider. Prepare yourself.", ["objectivesText"] = "Defeat Geir in the Eternal Battlefield in Helheim . Progress: Together, we can defeat this foe!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39855] = { ["id"] = 39855, ["name"] = "Paid in Lifeblood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39857 }, ["description"] = "We have fulfilled Helya's bargain. Now, we see if she will keep to her word. When you are ready, we should proceed to the throne. If you have any other business here, I would suggest finishing it now. I will follow your lead, outsider.", ["objectivesText"] = "Confront Helya and leave Helheim .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129188, 132824, 132825, 132826, 132827, 132828, 132829, 132830, 132831, 132832, 132834, 141401, 237812, 246937 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39857] = { ["id"] = 39857, ["name"] = "The Eternal Nemesis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39852, 39853, 39855 }, ["description"] = "<Helya's voice echoes in the sky above the altar> You say that you do not belong here among the unworthy, outsider, but your spirit fragments so easily. How am I to know you speak the truth? I cannot, so you must show me. Bring yourself to the eternal battlefield and face my champion. If you manage to defeat him, then I may grant you a pardon.", ["objectivesText"] = "Return to Ashildir and inform her of Helya's challenge.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39859] = { ["id"] = 39859, ["name"] = "Note-Eating Goats", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 40170, 40216, 40217 }, ["description"] = "I've followed Hemet on all his expeditions from Stranglethorn to Nagrand to... Nagrand again, taking notes on his grand adventures and turning them into timeless literary tales. But my heart is really in the hunt. I want nothing more than to put down the pen, and pick up a rifle! Hemet promised to teach me how to hunt once I finish his latest novel, but the goats around here ate my first draft! I have no hope of becoming a hunter if my manuscript isn't recovered.", ["objectivesText"] = "Recover Addie's manuscript from Sated Hillstriders within Pinerock Basin. Progress: I've been waitin' all day for Addie to finish her first draft. How hard can it be to write a few words about the greatest hunter who's ever lived?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128864, 130320, 160452, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94434, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39860] = { ["id"] = 39860, ["name"] = "Rite of Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 653, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 40219, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "Oakin Ironbull vouches for you. He's capable, for a Rivermane. You also brought with you proof of your own strength, albeit rather inconclusive proof. Before we allow you to move freely within our territory, you must complete the Rite of Blood, which you have already begun. If you succeed--and I doubt you will--talk to me. Enter the depths of the cave. Defeat whatever foe appears and return to me.", ["objectivesText"] = "Complete the Rite of Blood. Progress: Are you afraid of the dark?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121668, 121669, 121670, 121671, 121726, 121728, 121730, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 653, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39861] = { ["id"] = 39861, ["name"] = "Tying Up Loose Ends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 39861 }, ["series"] = { 39731, 40122 }, ["description"] = "Malfurion Stormrage managed to make landfall in Val'sharah and has already taken care of things there. It seems our fortune is finally turning around! He's waiting for you as we speak in Lorlathil. Life is so magical when everything goes according to plan.", ["objectivesText"] = "Speak to Aludane Whitecloud at Krasus' Landing to secure a flight to Val'sharah . Speak to Malfurion Stormrage after you arrive in Lorlathil. Progress: Highlord <name>! You couldn't have arrived at a better time.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91462, ["x"] = 0.546, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[39862] = { ["id"] = 39862, ["name"] = "The Siegebrul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["description"] = "Worms do not like battle or the surface. They only go where their master tells them. So, when in war, kill the master. Siegebrul Olgrul is the master of worms for the Mightstone drogbar who attack us from the north. Slay him.", ["objectivesText"] = "Slay Siegebrul Olgrul . Progress: Siegbrul Olgrul torments all who serve him. There are evil drogbar, and then there is this foul monster.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97301, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97301, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39864] = { ["id"] = 39864, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 39864 }, ["series"] = { 38307, 44701 }, ["description"] = "Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He should be waiting for you in the Violet Citadel. It sounded urgent.", ["objectivesText"] = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003, 237812, 246812, 246814, 248247 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.088 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 7 },
[39867] = { ["id"] = 39867, ["name"] = "I'm Not Lion!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "I've hunted many exotic beasts in my day, but I've never seen a lion like the one I encountered while scouting the basin. The beast's amber eyes locked on mine, luring me closer. I was helpless to this predator's enchanting gaze. It was only when the lion pounced did the stupor break. I've told Hemet of this magical beast, but he laughs. I'm not lying, <name>! The lion exists. If you find the beast, bring me a trophy of your kill, and I'll reward you handsomely.", ["objectivesText"] = "Collect a hunting trophy from the lion that Ellias claims to have seen in Pinerock Basin. Progress: I'll have the last laugh when Hemet sees proof that this magical lion exists!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 57386, 57387, 57388, 128933, 131875, 133810, 211279, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 95438, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 95438, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39873] = { ["id"] = 39873, ["name"] = "I Have a Bad Feeling About This", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["description"] = "You have no reason to trust me. My cousins led by Dargrul have gone mad with power. But I ask you to investigate something. I have a feeling something terrible is about to befall Highmountain , and that Torok and his Bloodtotem are going to be responsible. If you don't believe me, look for yourself at the northern side of Cliff's Edge.", ["objectivesText"] = "Investigate Navarrogg 's suspicions.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97667, ["x"] = 0.39, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39874] = { ["id"] = 39874, ["name"] = "Some Enchanted Evening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39875, 39876, 39877 }, ["description"] = "Welcome! It's nice to see familiar faces returning to Dalaran. You might remember Ildine, Vanessa, and me from Northrend. Archmage Starsinger is in charge of the shop, but he's away on Kirin Tor business at the moment. He's a fine fellow... mostly. Your arrival is fortunate. We've run into a problem that we'd love to solve before the archmage returns. Interested in lending a hand?", ["objectivesText"] = "Speak to Ildine Sorrowspear inside the enchanting shop in Dalaran.", ["rewardXP"] = 1415, ["rewardItems"] = { 6217, 38682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39875] = { ["id"] = 39875, ["name"] = "The Last Few", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39876, 39877 }, ["description"] = "As you can see, <name>, we're hard at work producing enchants for the battle against the Legion. Since you're here, we could really use your help wrapping up one of our orders. If you could, acquire some vellums and start enchanting them with Versatility. Here, I'll teach you the formula.", ["objectivesText"] = "Create 2 Enchant Ring - Word of Versatility vellums for Ildine. You can acquire vellums from a scribe, or from the Auction House. Progress: Almost done enchanting those vellums?", ["rewardXP"] = 1415, ["rewardItems"] = { 38682, 124440, 128540 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39876] = { ["id"] = 39876, ["name"] = "Helping the Hunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39875, 39877 }, ["description"] = "Now, while I continue to fill the rest of our orders, I'd really appreciate it if you would deliver these vellums to Jace Darkweaver down in Azsuna. He and the other demon hunters have been fighting back the Legion for quite some time and could use this as quickly as possible. Thanks, <name>!", ["objectivesText"] = "Deliver the crate of vellums to Jace Darkweaver in Azsuna. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 137186 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39877] = { ["id"] = 39877, ["name"] = "In the Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39874, 39875, 39876 }, ["description"] = "We could use your help down here, <name>. Some of our hunters would benefit greatly from having those vellums applied to their rings right now. Here take a few. I'll give the rest to one of my other soldiers to hand out. My hunters probably won't stop to let you apply the enchants, so you'll just have to do your enchanting even if they're in the midst of battle.", ["objectivesText"] = "Use the enchanting vellums on 6 Demon Hunters at the Illidari Stand. Progress: There's no time to waste. We need to get these enchantments out to as many of my hunters as possible.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 123919, 124124, 130176, 130181, 130183, 132331, 132332, 132333, 137120, 137838, 137840, 137865 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39878] = { ["id"] = 39878, ["name"] = "Thunder Struck", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 40048 }, ["description"] = "I've made contact with a potential source of new enchantments down in Highmountain. The tauren of Thunder Totem command the spirits to imbue items with great power. Seek out an enchanter named Twaintail and see if he will share his knowledge with us. Taurens are known for their sharing... right?", ["objectivesText"] = "Speak to Guron Twaintail in Thunder Totem.", ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39879] = { ["id"] = 39879, ["name"] = "Strong Like the Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39880, 39882, 39883, 39884, 39889 }, ["description"] = "There are many types of spirits in this world, <name>. Some benevolent, some troubled. They all resonate with different reagents which we use to enchant our armor. One such reagent are the crystals of the ambershards. They are a violent creature born of the earth and have recently been disturbed by the drogbar. However, disturbed or not, the crystals they bear are of great use to my people for enchantments. Bring me some and I'll show you what I mean.", ["objectivesText"] = "Defeat Enraged Ambershards and collect 8 of their Ambershard Crystals. Bring them back to Guron in Thunder Totem. Progress: Crystals aren't the only thing the spirits respond to. There are others, but that is another tale for another time.", ["rewardXP"] = 1415, ["rewardItems"] = { 137193 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39880] = { ["id"] = 39880, ["name"] = "Waste Not", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39882, 39883, 39884, 39889 }, ["description"] = "While fighting the ambershards for their crystals, you may come across enchanted armor from our fallen braves. The ambershards care not for such things, but our tribe does not believe in letting anything go to waste. I'd like you to retrieve our braves' armor and disenchant them into the components from which they were imbued. Bring me back the reagents so my tribe may use them to enchant new armor.", ["objectivesText"] = "Go to the Crystal Fissure and search for discarded armor. Disenchant the armor and bring back 15 Thunder Dust to Guron. Progress: To waste what we are given, is to laugh at the spirits who gave it to us to begin with.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 83726, 83727, 83728, 83729, 83730, 116394, 137195, 137196, 142054, 166846, 211279, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39881] = { ["id"] = 39881, ["name"] = "Fey Enchantments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "The new dusts and crystals we've found in these lands are fascinating, as I'm sure you've already surmised. I'm positive we can expand their usefulness to more of our armor. I'd like you to go back out into the field and talk to a dryad in Val'sharah. Apparently she may be able to clue us into some enchantments for shoulder pieces. Her name is Nalamya . You'll find her near the Temple of Elune.", ["objectivesText"] = "Seek out Nalamya near the Temple of Elune in Val'sharah.", ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39889] = { ["id"] = 39889, ["name"] = "Led Astray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39883, 39884 }, ["description"] = "The night elves are no fools, but the elves of Black Rook follow their commanders with blind loyalty. I've no doubt that the blame for their apathy rests heavily upon their commanders. I know of two of their leaders, who as we speak continue to command their troops to do nothing against the blight encroaching upon my home. Go to Black Rook Hold and slay Trelan Shieldbreaker and Starlys Strongbow . Let them be an example for those who can help, but wish to remain cowardly.", ["objectivesText"] = "Go to Black Rook Hold in Val'sharah and slay Trelan Shieldbreaker and Starlys Strongbow .", ["rewardGold"] = 30900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 13, ["flags"] = 0 } } },
[39891] = { ["id"] = 39891, ["name"] = "Cursed, But Convenient", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39907, 39916, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "I need you to return to Azsuna at once, <name>. I've only just heard of an enchantress within the Crumbled Palace who knows of many rare enchantments. Go to her and see what you can learn at once.", ["objectivesText"] = "Find Enchantress Ilanya at the Crumbled Palace in Azsuna.", ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39903] = { ["id"] = 39903, ["name"] = "An Enchanting Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39904, 40265 }, ["description"] = "The more I learn about the Broken Isles, the more convinced I am that it is a land of wonders! Ildine and I were just discussing rumors of a dwelling in Stormheim that was once the home to a vrykul enchantress called Tigrid. It is said the site is perfectly preserved, and her enchantments were so potent that they persist to this day! Investigating the home might uncover valuable knowledge, <name>.", ["objectivesText"] = "Investigate Tigrid's home in Stormheim.", ["rewardXP"] = 1415, ["rewardItems"] = { 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 14, ["flags"] = 0 } } },
[39905] = { ["id"] = 39905, ["name"] = "Ringing True", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "While your presence here would continue to be of value to us, your master in Dalaran has called for you. I'd like to thank you again for all you've done for us. My hunters have been reminded that they're not alone in this war.", ["objectivesText"] = "Return to Nalthanis in Dalaran.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39906] = { ["id"] = 39906, ["name"] = "Prepping For Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39914 }, ["description"] = "To earn my mark, <class>, you must first prove yourself in battle to me. There is a naga I wish to kill, but I am not strong enough to slay him. Before we go into battle together, I need your help as an enchanter to become stronger. I'm sure by now you have a bevy of enchantments in your repertoire. Make some for me so that I may become strong enough again to make a difference in this world.", ["objectivesText"] = "Craft an Enchant Cloak - Word of Strength vellum, an Enchant Ring - Word of Critical Strike vellum and an Enchant Ring - Word of Mastery vellum for Alynblaze . Progress: Once I have the power I need, we shall test both our strengths.", ["rewardXP"] = 1415, ["rewardItems"] = { 38682, 124440, 124441, 128537, 128539, 128545 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 23, ["flags"] = 0 } } },
[39907] = { ["id"] = 39907, ["name"] = "Elven Enchantments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39916, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "You have earned the marks of my most trusted companions. You have also returned my love to me. I am fortunate to have met you, <name>. Now return to your master and let him know of what you have learned.", ["objectivesText"] = "Return to Nalthanis in Dalaran.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 25, ["flags"] = 0 } } },
[39910] = { ["id"] = 39910, ["name"] = "The Druid's Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "In order to grant you my mark, <class>, I must first be made strong enough to come to your aid should you need it. Within the ruins of Nar'thalas, my idols sit dormant. As I've said, I'm not strong enough to get them myself. But you are strong, I can sense it. Strong enough to take on those honor-less naga who plague my home. Find my idols and return them to me. Do this and I will grant you my mark.", ["objectivesText"] = "Find Merrus' Idol of the Paw , Idol of the Claw and Idol of the Moon and return them to him at the Crumbled Palace. Progress: Have you found them? Are they still intact?", ["rewardXP"] = 1415, ["rewardItems"] = { 137290, 137291, 137292 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98381, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98381, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 22, ["flags"] = 0 } } },
[39914] = { ["id"] = 39914, ["name"] = "Sentinel's Final Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39906 }, ["description"] = "Now that I'm stronger, it's time to test your mettle, and mine. As I mentioned earlier, there is a powerful naga I wish to kill. His name is Fathom-Commander Eksis . He was responsible for slaying many of my kin before he retreated into hiding, commanding his troops from the shadows. I've finally discovered his whereabouts in a cave just east of here. Let us bring vengeance upon him for my lost brothers and sisters.", ["objectivesText"] = "Slay Fathom-Commander Eksis . Return to Alynblaze at the Crumbled Palace when you are through. Progress: He will rue the day he ever set foot upon my homeland.", ["rewardXP"] = 1415, ["rewardItems"] = { 139494, 141912 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98159, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 24, ["flags"] = 0 } } },
[39918] = { ["id"] = 39918, ["name"] = "The Absent Priestess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39920, 39921, 40130, 40169 }, ["description"] = "After my betrayal, I never thought I could bear to look upon my love again. But thanks to you, <name>, I can at last return. Go and speak to Enchantress Ilanya . I will let her know that you are worthy of my mark.", ["objectivesText"] = "Return to Enchantress Ilanya at the Crumbled Palace in Azsuna.", ["rewardXP"] = 1415, ["rewardItems"] = { 69777 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98698, ["x"] = 0.399333, ["y"] = 0.362667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.399333, ["y"] = 0.362667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 21, ["flags"] = 0 } } },
[39920] = { ["id"] = 39920, ["name"] = "On Azure Wings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39921, 40130, 40169 }, ["description"] = "I have some exciting news of my own to report, <name>. Ildine and I had an excursion to Azsuna and made contact with the blue dragons at the Azurewing Repose. One of the dragons, Kharmeera , is an enchanter who expressed interest in working with you to perfect some of our enchantments. I understand you were just down there working with the elves, but if you wouldn't mind returning, Kharmeera would enjoy working with you too.", ["objectivesText"] = "Speak to the dragon Kharmeera at Azurewing Repose in Azsuna.", ["rewardXP"] = 6140, ["rewardItems"] = { 69777 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 26, ["flags"] = 0 } } },
[39923] = { ["id"] = 39923, ["name"] = "Down to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["description"] = "The ring enchantments you know now are good, but I know of better ones that exist. That is to say, I know of stronger enchantments that would be suitable for rings. According to legend, there are four constructs whose cores were imbued with magical enchantments. These constructs now patrol the streets of Suramar City. If you were to gather some friends and defeat these constructs, you could take their cores for us to study.", ["objectivesText"] = "Retrieve the Power Cores from Oldus, Or'ell, Olmoore, and Oll'ison. Bring them back to Kharmeera when you have all four. Progress: Remember to bring some friends with you, those constructs are incredibly powerful.", ["rewardXP"] = 6140, ["rewardItems"] = { 124442, 136622, 136623, 136624, 136625 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 28, ["flags"] = 0 } } },
[39931] = { ["id"] = 39931, ["name"] = "Smashing Herbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39847 }, ["description"] = "Now that the formalities are out of the way, let's have you do something actually useful. On the islands below, there's a plethora of new and exotic herbs that we've yet to experiment with. I'd like you to get some of those herbs and create some new pigments from them. Once you have enough, come back to me and I'll see what you've come up with.", ["objectivesText"] = "Obtain 20 Roseate Pigments and 2 Sallow Pigments . Pigments are obtained by milling herbs. Progress: Well? Do you have the pigments, or are you just wasting my time?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124103, 124124, 128304, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 137738, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39932] = { ["id"] = 39932, ["name"] = "Fish Ink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39933 }, ["description"] = "You know, herbs aren't the only ways to obtain ink. Other materials can be inkified. Slightly related! I've been tinkering with the idea of creating my own type of Darkmoon card. Surely if those troggish carnival people can do it, then so can I. To do so, we'll need some special reagents. Go down to Azsuna and collect some oils for me, then mill them into a suitable ink.", ["objectivesText"] = "Obtain 5 Mak'rana Oil, 5 Hatecoil Naga Oil, and 5 Salteye Oil , then combine them into a Piscine Pigment . Progress: My pigment?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129058, 129059, 129060, 129211, 136811, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39933] = { ["id"] = 39933, ["name"] = "The Card Shark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39932 }, ["description"] = "We have the pigment, but we still require one more ingredient. Visitors at the Legerdemain Lounge will often play card games, and occasionally their cards are discarded. Go see if you can find some loose cards that players may have gotten rid of between matches.", ["objectivesText"] = "Collect 10 Hearthstone Cards at the Legerdemain Lounge. Progress: The cards are just for reference, mostly...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129092, 129211, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39934] = { ["id"] = 39934, ["name"] = "Our New Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39935 }, ["description"] = "Have you seen those demon hunters yet? I'm not entirely sold on their allegiance to our cause, but while we have them, we may as well exploit them. Everybody needs glyphs, you know. Go see what you can discover about them. Azsuna is as good a place as any to start. Perhaps my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", ["objectivesText"] = "Go to Azsuna and find Allari the Souleater .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436, 174066 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39935] = { ["id"] = 39935, ["name"] = "The Price of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39934 }, ["description"] = "You wish to learn what it is to be a demon hunter? That may take some time. The first thing you can do is fight alongside us. Battle the demons with us and observe how we use their strength against them. Return to me when you are finished.", ["objectivesText"] = "Slay 15 demons at Illidari Strand. Progress: Have you seen enough?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39940] = { ["id"] = 39940, ["name"] = "Runes of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "Look closely, scribe, and you may learn. As the demons spread out over a region, the more clever ones will inscribe runes upon the ground. The fel taint pervades this entire hillside, but the corruption is darkest around these runes, disallowing anything pure to grow ever again. Study these runes.", ["objectivesText"] = "Study 8 Fel Power Runes .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39943] = { ["id"] = 39943, ["name"] = "The Burdens of Hunting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 40058, 40059, 40060, 40063 }, ["description"] = "There is nothing more I have to teach you, scribe. The Illidari stand behind you in the battle against the Legion.", ["objectivesText"] = "Report back to Professor Pallin .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 }, { ["mapID"] = 630, ["npcID"] = 98026, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39944] = { ["id"] = 39944, ["name"] = "Mysterious Messages", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "The woman at the archaeology shop just dropped off some tablets to be deciphered. Any fool can see they're written in ancient vrykul, but I lent my codex to one of my students, so I'm unable to decipher them here. His name is Nicholo Swiftfuse , and he is in Stormheim. Let him know that if he fails to decipher them, his apprenticeship shall be terminated. That is all.", ["objectivesText"] = "Deliver the tablets to Nicholo Swiftfuse in Stormheim.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 20, ["flags"] = 0 } } },
[39947] = { ["id"] = 39947, ["name"] = "Not So Complex?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39946, 39951, 40052 }, ["description"] = "Alright, I believe I've finished adding the missing entries into the codex. And we have the machete... err, knife. All that's left is to make our own tablet and verify my other suspicion about these tablets: I believe that they're not just simple texts, but a sort of magical device.", ["objectivesText"] = "Assist Nicholo with the creation of a rune tablet.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129164, 129169, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 23, ["flags"] = 0 } } },
[39948] = { ["id"] = 39948, ["name"] = "The Ink Flows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39949, 39950 }, ["description"] = "<name>, I need you to make a quick delivery for me. Yes, I've learned by now that such trivial tasks are beneath your skills... but I'm rather busy right now and we both know my time is much more important than yours. Deliver these contracts to Raethan , the Guard Captain in Dalaran's Underbelly.", ["objectivesText"] = "Deliver the contracts to Raethan in the Underbelly.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 25, ["flags"] = 0 } } },
[39950] = { ["id"] = 39950, ["name"] = "An Odd Trinket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39948, 39949 }, ["description"] = "Wait, <name>, before you leave... did you not notice this? < Raethan peels a small piece of paper from the bottom of the jewel.> This wasn't reported stolen. It appears to be a card of some kind. Must be a scribe thing. Perhaps it may be of some use to you.", ["objectivesText"] = "Give the Rotting Tarot Card to Professor Pallin . Progress: What's that you have there?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034, 129177 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 27, ["flags"] = 0 } }, ["startItems"] = { 129177 } },
[39955] = { ["id"] = 39955, ["name"] = "The Plot Thickens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 87, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39954, 39956 }, ["description"] = "Very well, I won't deny it. The Steamy Romance Novel is mine. I only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s! In fact... you might benefit from a penmanship lesson. The author of these books is one B. Spearshaker. I believe he can be found in the library in Ironforge. Stop reading, student. You are dismissed. And give me my book back!", ["objectivesText"] = "Go to Ironforge and look for B. Spearshaker.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.765667, ["y"] = 0.091 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 29, ["flags"] = 0 } } },
[39956] = { ["id"] = 39956, ["name"] = "The Legacy Passed On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1537, ["mapID"] = 87, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39954, 39955 }, ["description"] = "I've lost my passion, scribe. I just can't get into the voice o' the characters anymore. Take a look at that unfinished book over there on the table. I can't seem to finish it. Maybe ye'll have an easier time with it.", ["objectivesText"] = "Complete the Unfinished Steamy Romance Novel. Progress: Dang-blasted writer's block!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 108649, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 97762, ["x"] = 0.765667, ["y"] = 0.091 } }, ["coords"] = { ["mapID"] = 87, ["source"] = "quest_giver", ["x"] = 0.765667, ["y"] = 0.091 }, ["mapCandidates"] = { ["npc"] = { 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 31, ["flags"] = 0 } } },
[39957] = { ["id"] = 39957, ["name"] = "Demon Ink", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39953 }, ["description"] = "These sigils would make for a fantastic new tarot card. Quite powerful, in fact. We simply require an ink sturdy enough to inscribe them. Fortunately, I have students like you that excel at fetching hard-to-get items. For this project, I require ink mixed from demonic blood. The blood of the demons at Felsoul Hold will serve as a suitable base. You will also need Blood of Sargeras, of course.", ["objectivesText"] = "Collect 25 Vials of Felsoul Blood and 1 Blood of Sargeras, then mix them into Felsoul Ink . Progress: If you're unsure where to get demon blood, go to Suramar and look around. You're bound to trip on a demon sooner or later.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128705, 128709, 128710, 128711, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129204, 129211, 137187, 137790, 137791, 139417, 139436, 141022 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 41, ["flags"] = 0 } } },
[39958] = { ["id"] = 39958, ["name"] = "Skin Deep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40183 }, ["description"] = "Welcome, <name>. It's an honor to be working with someone of your caliber. In order for us to begin our work together, we'll first need to collect some materials. The Broken Isles are home to many strange, exotic creatures which no doubt have interesting hides to experiment with. We'll need scales to make mail armor with as well. Go and collect some materials for us so we may begin working.", ["objectivesText"] = "Acquire 20 Stonehide Leather and 5 Stormscales . If you are not a skinner, you may acquire them from the auction house or other players. Progress: I trust you gave the creatures a merciful death?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 124115, 139498, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39961] = { ["id"] = 39961, ["name"] = "An Embarrassing Revelation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "This doesn't appear to be an inscription textbook at all... it's more of a steamy romance novel . The pages are just FILLED with tawdry tales of carnality. Could it have something to do with inscription? Either way, Professor Pallin should be confronted.", ["objectivesText"] = "Bring the Steamy Romance Novel to Professor Pallin .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 28, ["flags"] = 0 } } },
[39983] = { ["id"] = 39983, ["name"] = "Huln's War - The Arrival", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7838, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Huln Highmountain is the origin of our strength as a tribe. He bested the Legion when last they threatened our survival and unified many disparate tribes. Live his story, and you will know why his name imbues courage in the cowardly and sows fear in the fearless.", ["objectivesText"] = "Defeat 25 Legion.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39985] = { ["id"] = 39985, ["name"] = "Khadgar's Discovery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39986, 39987, 40008, 40009, 40123, 44555 }, ["description"] = "Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.", ["objectivesText"] = "Speak with Archmage Khadgar in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140234, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 0, ["flags"] = 1 } } },
[39986] = { ["id"] = 39986, ["name"] = "Magic Message", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39987, 40008, 40009, 40123, 44555 }, ["description"] = "For the last 10,000 years, the elven city of Suramar has been sealed in an arcane barrier, much like Dalaran once was. That barrier has come down. Since then, waves of magical energy have been emanating from the city like ripples in a pond. It was in these waves that I sensed a pattern. A spell, encrypted among the chaos. I have recreated the spell here. It's not dangerous, but beyond that... I have no idea what it does!", ["objectivesText"] = "Examine the Arcane Anomaly in Dalaran. Progress: Go ahead and take a look.", ["rewardGold"] = 50550, ["rewardXP"] = 1535, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39987] = { ["id"] = 39987, ["name"] = "Trail of Echoes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 40008, 40009, 40123, 44555 }, ["description"] = "The Nightborne could prove powerful allies against the Legion. We must aid this Thalyssra if we can. We should be able to find her by tracking her magical echoes, the same way I found her distress call. I can teleport you near the location where she recorded that message. From there, you must search for ripples in the very fabric of the arcane itself. My wand should do the trick. Follow the sparks it creates--they should lead you to places where Thalyssra used her magic.", ["objectivesText"] = "Use Khadgar's Wand to find Arcane Echoes and track down First Arcanist Thalyssra . Progress: Who are you?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 131931, 136600, 136970, 140234, 141667, 142054, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39988] = { ["id"] = 39988, ["name"] = "Huln's War - Stormrage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7838, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39990, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "< Eche'ro nuzzles your hand and turns around. It looks back, beckoning you to the south.>", ["objectivesText"] = "Meet Malfurion.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39990] = { ["id"] = 39990, ["name"] = "Huln's War - Reinforcements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7838, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39991, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. I would speak with you on this later. It is a rare gift indeed. But now, I ask for your help, Huln Highmountain . I must finish my incantations to allow dryads from beyond the veil to enter this place and lend us their aid.", ["objectivesText"] = "Defend Malfurion. Progress: This shouldn't take long. Please do not allow them to interrupt my spell.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39992] = { ["id"] = 39992, ["name"] = "Huln's War - The Nathrezim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7838, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "I am fully occupied here organizing my troops and planning for the battle to come. While I would like to slay the Dreadlord Tichondrius myself, I will allow that honor to be yours, Huln Highmountain .", ["objectivesText"] = "Defeat Tichondrius .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 130282, 130309, 237812, 246937, 257397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40000] = { ["id"] = 40000, ["name"] = "A True Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39386, 39656, 39670, 40000 }, ["description"] = "I don't know why Hemet hunts with Razik. His contraptions are unreliable at best! A true hunter doesn't need gadgets to hunt. They rely on instinct, skill, and agility. So tell me, <name>, do you have the skills of a true hunter? Better yet, prove it. Take down some of the Bonebeak Hawks that circle the nearby meadow.", ["objectivesText"] = "Prove you're a worthy hunter by hunting Bonebeak Hawks in Sunfrost Glade. Progress: You can't be huntin' hawks if you're here chattin' at me.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97974, ["x"] = 0.575333, ["y"] = 0.564667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97974, ["x"] = 0.575333, ["y"] = 0.564667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.564667 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5919, ["name"] = "Icepine Point", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40001] = { ["id"] = 40001, ["name"] = "Knocking on Valor's Door", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40002, 40003, 40078 }, ["description"] = "The Halls of Valor is your destiny to claim, but it is already in the claiming. The God-King befouls its steps with demons and wickedness. Your dragon allies have come to Halls' defense, but they need your aid. The vrykul have taken the leader of the storm dragons, the one you call Vethir . Free your dragon friend, champion, and wash the Felskorn from the Gates of Valor!", ["objectivesText"] = "Find Vethir in the Felskorn Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40002] = { ["id"] = 40002, ["name"] = "A Familiar Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40001, 40003, 40078 }, ["description"] = "We had come to defend the Halls of Valor... I was taken from the sky... I cannot break free of my bindings. Find the jailer who made this cell... Set me free, friend...", ["objectivesText"] = "Collect the Jailer's Shard from Dravax and free Vethir from his prison. Progress: The jailer has... the key...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129106, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40003] = { ["id"] = 40003, ["name"] = "Stem the Tide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40001, 40002, 40078 }, ["description"] = "Skovald has profaned the Gates of Valor with his demonic allies. Among his forces his twisted mystics have conjured portals to ferry his fel allies from their blighted worlds. If we wish to stem this tide, these portals must be destroyed. I will gather my allies. Take this horn and signal when you have found a portal, and we will strike from the skies!", ["objectivesText"] = "Use the Stormforged Horn to destroy the three Felbound Portals in Gates of Valor. Progress: The portals must be closed if we wish to stop Skovald's forces!", ["rewardGold"] = 221280, ["rewardXP"] = 1415, ["rewardItems"] = { 129161, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40004] = { ["id"] = 40004, ["name"] = "Break the Spine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["description"] = "To lead his tainted forces, the God-King has enlisted demons of great power to act as his lieutenants. If we wish to end his assault, we will need to take their leaders. These demons are too powerful for most mortals to face, but with the power of Stormheim at your disposal, they will prove no match for you. Take them down, and shatter the spine of Skovald's offensive!", ["objectivesText"] = "Defeat Garzareth , Karuas , Muorg and Ravathes in Gates of Valor. Progress: Are the leaders slain?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97979, ["x"] = 0.658, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40005] = { ["id"] = 40005, ["name"] = "Stormheim's Salvation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40072 }, ["description"] = "It would seem that the portals we destroyed down here were not the only ones. Demons still pour in from the top of the Gates of Valor's edifice, summoned by the God-King himself! I cannot face Skovald alone. Come, champion, let us take the battle to him and end this threat! For Stormheim !", ["objectivesText"] = "Defeat God-King Skovald in the Gates of Valor.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 237812, 246937 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97986, ["x"] = 0.718, ["y"] = 0.7056 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97988, ["x"] = 0.702, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.7056 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40008] = { ["id"] = 40008, ["name"] = "The Only Way Out is Through", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40009, 40123, 44555 }, ["description"] = "I have much to tell you, but it is not safe to speak here. I cannot hold this barrier forever. <Thalyssra lifts a delicate flask to her lips. Her eyes shimmer as she takes a sip.> If we push through, we may find shelter up ahead.", ["objectivesText"] = "Escort Thalyssra to safety. Progress: There is no turning back.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40010] = { ["id"] = 40010, ["name"] = "Tapping the Leylines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["series"] = { 41028 }, ["description"] = "The arcways were built to tap into the magical leylines beneath Suramar . As we learned to subsist on the Nightwell, the old facilities fell out of use. This chamber is clearly receiving power from elsewhere. There is only a trickle now, but if you can direct more leyline energy here it will help to sustain us. The closest source is to the north, near Anora Hollow.", ["objectivesText"] = "Explore Anora Hollow and find the Ley Station there.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40011] = { ["id"] = 40011, ["name"] = "Oculeth's Workshop", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We need to make contact with Chief Telemancer Oculeth , the man who developed Suramar 's teleportation network. Oculeth had a workshop in old Suramar , from the age before the Sundering. He may be taking refuge there. <Thalyssra presses a small coin into your palm.> If you find him, show him this. Hopefully you see him before he sees you...", ["objectivesText"] = "Give the First Arcanist's Token to Chief Telemancer Oculeth . Progress: If we are to put up any resistance against the combined forces of the Legion and the Grand Magistrix, we must secure a means of traversing the region quickly.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 10506, 69777, 129039, 132883, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40012] = { ["id"] = 40012, ["name"] = "An Old Ally", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40326, 41702, 41704, 41760 }, ["description"] = "I was on my way to Ambervale in hopes of finding an old colleague. Arcanist Kel'danath was fascinated by the withered. He studied them for years hoping to calm their feral nature or even cure them. When one of his subjects escaped and ran amok in the royal gardens, Kel'danath was ordered to cease his research and kill all withered in his possession. He refused, and was exiled. If Kel'danath lives, he is near withered. And withered are drawn to old settlements like Ambervale.", ["objectivesText"] = "Find Arcanist Kel'danath's hideout in Ambervale.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40043] = { ["id"] = 40043, ["name"] = "The Hunter of Heroes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 40043 }, ["description"] = "Helya has made a mockery of my order by creating her own \"helarjar\", powerful undead tasked with hunting down heroic warriors and taking their souls before my val'kyr can claim them. Among them is her personal champion, Vigfus Bladewind, who wields stolen blades I forged myself long ago. He has returned to Tideskorn Harbor with a full cargo of stolen souls to take to Helheim. Go there, kill him and his helarjar, and make the swords yours.", ["objectivesText"] = "Deal with Vigfus Bladewind's warband and claim his blades. Progress: Ah, you have returned...", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910, 137663, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 215, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 215, ["name"] = "Hunter of Heroes", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40045] = { ["id"] = 40045, ["name"] = "Nature vs. Nurture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "I appreciate murloc-kind far too much to tell you to go kill all the adults. What we should be doing is setting up the next generation to be more peaceful; Murky is the best representative for this. Bring him to talk to the murloc tadpoles. He'll get them on our side.", ["objectivesText"] = "Talk to 10 Swamprock Tadpoles . Progress: Getting the support of the tadpoles is very important for our mission.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40047] = { ["id"] = 40047, ["name"] = "I'll Huff, I'll Puff...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "Murky is my favorite little fella. However, in order to lead a change in the murloc population here, he needs some awesome abilities. There are a lot of pufferfish around in the water, and I think that they could be a good resource for him. Kill a few and collect their eggs for Murky.", ["objectivesText"] = "Collect 5 Pufferfish Eggs . Progress: Pufferfish have this impressive ability of... exploding. They could be a powerful tool for Murky.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129183, 211279, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40048] = { ["id"] = 40048, ["name"] = "Strings of the Puppet Masters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39878 }, ["description"] = "I understand you were just here to deliver the vellums, but we could use your skills as a <class>. Our forces can only hold back the demon invasion, disallowing us to send anyone further into the enemy's camp. The stronger of their forces stay in the back, commanding from a distance. They carry enchanted runes to keep control over the frontline demons. I would very much like to study one of these runes. Please retrieve one for me, so we may learn from it and use it against the Legion.", ["objectivesText"] = "Acquire a Rune of Dominance from the demons at Legion Camp: Chaos. Progress: Have you found any runes yet?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 137185 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90317, ["x"] = 0.432, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40049] = { ["id"] = 40049, ["name"] = "Slime Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "Murky's a growing boy, he needs to eat! What better than slimeweed for a young murloc? There's plenty of it around in the water amongst the murlocs; swim through it and feed Murky!", ["objectivesText"] = "Feed Murky 6 Bunches of Slimeweed by swimming through them.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 67414, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40051] = { ["id"] = 40051, ["name"] = "Fel Secrets", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38725, 40222 }, ["description"] = "The demons made a grave error inscribing their secrets into this book. The fel energy emanating from it is potent. But there's only enough to enact one of the rituals. After that, the book will be consumed. It's up to you to choose which secrets we want to use against the Burning Legion.", ["objectivesText"] = "Read the Tome of Fel Secrets to choose between the Havoc and Vengeance specializations. Progress: Have you made up your mind?", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40052] = { ["id"] = 40052, ["name"] = "Ancient Vrykul Mastered", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39946, 39947, 39951 }, ["description"] = "Here are those tablets back, along with their deciphered writing. You can take this codex back to Pallin, too. I'll start getting my things ready for when he calls me back to Dalaran. <Nicholo sighs.> Learn from my example, <name>. If I were you, I'd break free from Pallin's \"requests\" as soon as you can.", ["objectivesText"] = "Return the tablets and codex to Professor Pallin .", ["rewardItems"] = { 128980, 129032, 129034 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 24, ["flags"] = 0 } } },
[40056] = { ["id"] = 40056, ["name"] = "Our New Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 40057 }, ["description"] = "Student! Your fellow demon hunters in Azsuna have sent for you. I can certainly appreciate your time being spent fending off the Legion, but it doesn't excuse you from your studies. While you're down there, I'd like you to come up with some new glyphs for your abilities. Surely my genius has worn off on you and you'll be able to create your own recipes based on what you learn.", ["objectivesText"] = "Report to Allari the Souleater in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 174066 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 13, ["flags"] = 0 } } },
[40057] = { ["id"] = 40057, ["name"] = "The Price of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 40056 }, ["description"] = "I see, you wish to augment your powers through script. I believe we can kill two birds with one stone then. I need help here reducing the demon threat. Perhaps some more engagement with our enemy will inspire you.", ["objectivesText"] = "Slay 15 demons to help lessen the invasion.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 14, ["flags"] = 0 } } },
[40058] = { ["id"] = 40058, ["name"] = "Defense Symbology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 39943, 40059, 40060, 40063 }, ["description"] = "As you know, <name>, we demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. Up to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. He could use your assistance with his ritual.", ["objectivesText"] = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40059] = { ["id"] = 40059, ["name"] = "Opposites Repel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 39943, 40058, 40060, 40063 }, ["description"] = "The ruins nearby have had an eruption of ley energies. Twisted night elves deemed \"Nightfallen\" are scavenging the area as we speak. Collect ley dust for me from the nightfallen in the ruins up ahead. The dust is infused with arcane energy that I'll need to complete my ritual.", ["objectivesText"] = "Collect ley dust from the nightfallen in Zarkhenar. Progress: Even though they are opposites, one can not exist without the other.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034, 129105 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 16, ["flags"] = 0 } } },
[40060] = { ["id"] = 40060, ["name"] = "Containing the Demon Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 39943, 40058, 40059, 40063 }, ["description"] = "Now that we have all the essential pieces, let's begin the ritual. I'll instruct you on how to help me throughout it. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", ["objectivesText"] = "Assist Baric in completing the ritual.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98026, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40061] = { ["id"] = 40061, ["name"] = "To Know Your Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "As we fight the demons, we've also been studying them. Great understanding can come from gathering intel. I have a demon hunter near the Felblaze Ingress now gathering intel on the demons there. Go to her and see what she has learned from the demons invading that region.", ["objectivesText"] = "Find Zaria Shadowheart near the Felblaze Ingress.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 18, ["flags"] = 0 } } },
[40063] = { ["id"] = 40063, ["name"] = "Control is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39941, 39943, 40058, 40059, 40060 }, ["description"] = "I trust you remember why you removed your eyes? Even though we can see more clearly now, the demons have found ways to mask even their fel energies from us. A demon commander walks amongst the troops below, commanding them from the shadows. His cloak is powered by an energetic crystal. Find and destroy that crystal, then kill the commander.", ["objectivesText"] = "Destroy the crystal providing protecting Overseer Felorax , then slay him.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 19, ["flags"] = 0 } } },
[40072] = { ["id"] = 40072, ["name"] = "Halls of Valor: Securing the Aegis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40001, 40002, 40003, 40004, 40005, 40072 }, ["series"] = { 40005 }, ["description"] = "The Felskorn may be broken, but the head of the beast yet lives. The God-King will still vie for the Aegis if left unchecked. You, who have completed trials upon trials, must not let this come to pass. You must claim the Aegis over Skovald's broken bones! The Halls of Valor await!", ["objectivesText"] = "Defeat God-King Skovald in the Halls of Valor and claim the Aegis of Aggramar .", ["rewardGold"] = 808800, ["rewardXP"] = 2830, ["rewardItems"] = { 141402, 237812, 246812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97988, ["x"] = 0.702, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 138, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1477, ["db2PoiUiMapID"] = 705, ["questLines"] = { { ["id"] = 138, ["name"] = "The Champion of Stormheim", ["orderIndex"] = 5, ["flags"] = 1 } } },
[40077] = { ["id"] = 40077, ["name"] = "The Invasion Begins", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["description"] = "Our advance force of demon hunters is here and has engaged the Legion. Make our presence known. Let's send a shiver down every demon spine. Raise our colors with pride, <name>.", ["objectivesText"] = "Slay 15 demons and change the Legion banner to take control of Despair Ridge.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128953, 133317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 13, ["flags"] = 0 } } },
[40078] = { ["id"] = 40078, ["name"] = "A Heavy Burden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38324, 38339, 38347, 39837, 39848, 39849, 39850, 39851, 39853, 39855, 39857, 40078 }, ["series"] = { 40001, 40002, 40003 }, ["description"] = "With Ashildir's judgment, your final trial is complete. But even Valhallas can wait, for now we must eat! Being dead works up quite an appetite. Come now, bring some of that fish to roast over the fire. It is far too heavy for me to carry.", ["objectivesText"] = "Take the fish from Havi 's Fish Barrel and skewer it on the spear above the fire.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 133813, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 135, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 135, ["name"] = "To Helheim and Back", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40102] = { ["id"] = 40102, ["name"] = "Murlocs: The Next Generation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "The time has come! Murky and his followers need a place to hide out and train--away from the mature murlocs--so that they can prepare to take over in the future. There's a nice cave not too far away... only problem is that it's filled with makrura. This would be a good base for the tadpoles. Murky must go show them what for! Mindmeld with Murky in his egg and show him how it's done!", ["objectivesText"] = "Mindmeld with Murky and slay 10 Cavemoss Clackers . Progress: These young murlocs show such promise. They'll do this shore good.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132183, 132184, 133818, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40120] = { ["id"] = 40120, ["name"] = "A Murky Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40120 }, ["description"] = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end. The creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites. This is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.", ["objectivesText"] = "Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim. Progress: Have you done this task?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129725, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98587, ["x"] = 0.782, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98587, ["x"] = 0.782, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[40122] = { ["id"] = 40122, ["name"] = "Cenarius, Keeper of the Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38384, 40122 }, ["series"] = { 39731, 39861 }, ["description"] = "Ahh, Val'sharah . It has been an age since I have set foot in these sacred woods. Too long... Our work here is simple, <class>. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.", ["objectivesText"] = "Speak to Malfurion Stormrage at Lorlathil in Val'sharah . Progress: Cenarius!", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91462, ["x"] = 0.546, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91109, ["x"] = 0.518, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 184, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 184, ["name"] = "Nature's Call", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40123] = { ["id"] = 40123, ["name"] = "The Nightborne Pact", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40009, 44555 }, ["description"] = "<Thalyssra winces and holds her abdomen.> Ngh... I can ignore this wound no longer. Help me patch this up. I will explain everything.", ["objectivesText"] = "Bandage Thalyssra.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40125] = { ["id"] = 40125, ["name"] = "Branch of the Arcan'dor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "You have used the spellstone of Kel'danath to soothe countless withered. Yet it contains merely a shade of the arcan'dor's power, drawn from its slumbering seed. <Thalyssra holds aloft a gleaming white branch.> This fell from the tree. Though it is severed, it is not dead - invisible threads of magic bind all pieces of the arcan'dor together. I have enchanted this branch with a new iteration of Kel'danath's charm spell. With it, you can mend the arcane essence of even more withered. Use it well.", ["objectivesText"] = "Speak with Thalyssra.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40130] = { ["id"] = 40130, ["name"] = "Washed Clean", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 39921, 40169 }, ["description"] = "Mighty though the Legion is, theirs is not the strongest power in Azeroth. There is a place where Enchantress Ilanya and I spent many blissful hours together. The love that infuses such a place is more potent than fel magic, <name>. Go to the Nor'Danil Wellspring. Its waters can purify the fel dust you have collected... and perhaps purify me as well. I will meet you there.", ["objectivesText"] = "Meet the Fallen Priestess at the Nor'Danil Wellspring. Watch as the priestess attempts the purification ritual. Progress: It... it worked! I am myself again at last!", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98698, ["x"] = 0.399333, ["y"] = 0.362667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 20, ["flags"] = 0 } } },
[40167] = { ["id"] = 40167, ["name"] = "The Story of Huln", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40388, 40515, 40520 }, ["description"] = "You work to unite the tribes. That is no small task. It has only been done once before in the history of this mountain. Huln Highmountain last united the tribes thousands of years ago to take on the Legion during the War of the Ancients.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn to learn about Huln Highmountain . Progress: The history of this place extends beyond our limited memory.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40169] = { ["id"] = 40169, ["name"] = "Crossroads Rendezvous", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 39921, 40130 }, ["description"] = "An old apprentice of mine left during the war, shortly before we were all cursed. I've recently heard that she's been seen near the Felblaze Ingress. I would very much like to speak to her once more. Go and find her. Take her journal to her and let her know that I don't blame her for what she did. And if she's willing, please bring her back to me.", ["objectivesText"] = "Search for signs of the priestess near the Felblaze Ingress. Provided item:", ["rewardXP"] = 1415, ["rewardItems"] = { 129740 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107139, ["x"] = 0.468, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 18, ["flags"] = 0 } } },
[40170] = { ["id"] = 40170, ["name"] = "Amateur Hour", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40216, 40217 }, ["description"] = "The hunters' lodge has attracted a lot of amateurs who call themselves hunters. They're scarin' away all the prize game with their antics. While I'm a known expert with my rifle, I've yet to manage the art of negotiation. How about ya do us all a favor and tell those novice hunters to head for the hills?", ["objectivesText"] = "Confront Amateur Hunters within Pinerock Basin. Progress: Have those amateur hunters scattered? Don't be afraid to use your fists if words don't do the job.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40176] = { ["id"] = 40176, ["name"] = "From Head to Toe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "You've been busy, <name>. And you have some new patterns in your repertoire, I see! How about we add another?", ["objectivesText"] = "Craft a pair of Sturdy Stonehide Boots . You will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers. Progress: I'm very excited to see how this turns out.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129964, 130872, 130873, 130874, 130891, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40177] = { ["id"] = 40177, ["name"] = "Leather Lady", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "I'd like you to start working with my apprentices. The first is Diane Cannings , who has focused her expertise on the softer leather armors. She's just not that into mail armor, like the twins are. Go talk to her about this new type of leather.", ["objectivesText"] = "Meet with Diane Cannings .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40178] = { ["id"] = 40178, ["name"] = "Vestment Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "While the vrykul of Northrend wore strong armor, their craftsmen always had the strongest. Go to Stormheim, search for someone who knows about leather armor, and bring their chest piece back to me.", ["objectivesText"] = "Obtain a Hideshaper's Vestment . Progress: How's your search going?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129971, 138111, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40179] = { ["id"] = 40179, ["name"] = "Stormheim Savagery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "There's a land below - Stormheim, they call it - that's inhabited by vrykul. I remember the vrykul from my days in Northrend. What I remember most was how well-crafted their armor was. If the vrykul here are as skilled as the ones in Northrend, then I'm certain we can learn something by studying their armaments.", ["objectivesText"] = "Obtain 7 Vrykul Leather Bindings . Progress: Are the vrykul giving you much trouble?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129972, 138111, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40180] = { ["id"] = 40180, ["name"] = "Mail Men", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The two dwarves behind me are the Glowergold brothers. They're my resident mail armor experts. While Ranid has decided to focus his skills towards lining his pockets, his brother, Thanid, still enjoys the crafting side of the trade. Introduce yourself to Thanid. You may work with him to further our knowledge of turning these stormscales into something extraordinary.", ["objectivesText"] = "Meet with Thanid Glowergold .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40181] = { ["id"] = 40181, ["name"] = "Black Rook Bandit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "I've heard rumors of a grand castle in Val'sharah that's known to house an impressive army. Surely, the armor they wear ain't made of sticks and hay. I'm willing to bet they've fashioned some mail armor at some point fer their troops and it's just sitting there, ripe for the taking. How about ye head over there and see what ye can \"borrow\" from their armory.", ["objectivesText"] = "Obtain 5 pieces of Black Rook Armor . Progress: Make sure ye don't get captured now, lad.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129973, 129974, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40182] = { ["id"] = 40182, ["name"] = "Too Good To Pass Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "All types of Black Rook Hold armor are intriguing, but I'm most interested in their chest pieces. If ye can, try to find someone of importance there and... relieve them of their shirt. If it makes ye feel any better, I've heard they're all cursed, so puttin' them out of their misery is the least ye could do.", ["objectivesText"] = "Obtain a Black Rook Hauberk . Progress: Chest armor is the best armor, I always say!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129973, 129974, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40183] = { ["id"] = 40183, ["name"] = "Over Your Head", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 39958 }, ["description"] = "Alright, <name>, I'd like you to assist me with creating a helm. First we'll need to shave the hides, then tan them, and finally cut them into usable pieces. Follow my lead.", ["objectivesText"] = "Craft a Rough Warhide Mask . You will need to use Namha's Tanning Rack and Namha's Workbench, located in Legendary Leathers. Progress: I'm starting to think we make a pretty good team.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129975, 130868, 130869, 130870, 130872, 130875, 130891, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40184] = { ["id"] = 40184, ["name"] = "Tauren Tanning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Have you heard of the Highmountain tauren tribes? They're not unlike the tauren we know on Kalimdor. I've heard they have a leatherworking master there who might be able to help us come up with some new patterns. Travel to Highmountain and see if they're willing to teach you how they craft their armor.", ["objectivesText"] = "Report to Hrul Sharphoof .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40186] = { ["id"] = 40186, ["name"] = "Drogbar Durability", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "We are currently at war with a race known as the drogbar. We have long maintained peace with the drogbar, but lately, they have no respect for anyone but themselves. Slay them. Prove your worth as an ally of the tauren. Do this, and I will reward you with knowledge.", ["objectivesText"] = "Kill 15 drogbar to prove your worth to Hrul.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40187] = { ["id"] = 40187, ["name"] = "Links in the Chain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Well, <lad/lass>, I'm afraid I'm at me wits' end with these scales. Not quite sure how to fashion the remaining pieces fer a full set. However, I've heard that the elves of Azsuna had some great crafters in their cities. Perhaps one or two of them still exist. Go there and search fer a master. Maybe they can fill in the missing patterns fer us.", ["objectivesText"] = "Find a leatherworking master in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 12, ["flags"] = 0 } } },
[40188] = { ["id"] = 40188, ["name"] = "Best Served Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "My partner and I both fell victim to the fallout of the Sundering. We were betrayed and abandoned by a trusted friend. That \"friend\" has recently appeared in the ruins to the east. His name is Ranaris . Go to and take revenge for us and I will grant you some of my wisdom.", ["objectivesText"] = "Kill Ranaris in the El'dranil Shallows.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128894, 128899, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 13, ["flags"] = 0 } } },
[40189] = { ["id"] = 40189, ["name"] = "Naga Know-How", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The naga of this region wear little armor, but what they do wear is particularly durable. If you wish to make a strong shoulder piece, I would first study the naga's armor and then create a pattern of similar construct. The city nearby is overrun by naga. Slay them and bring me their armor and I will show you what I mean.", ["objectivesText"] = "Obtain 7 Naga Shoulderguards . Progress: They may be vile, but they still know how to craft as well as any master.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129980, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 14, ["flags"] = 0 } } },
[40191] = { ["id"] = 40191, ["name"] = "Stamped Stories", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Stamped onto the leather of the tanning racks behind me are the ancient ways of our tribe's leatherworkers. They tell the stories of masters who, through perseverance - and luck, in some cases - pioneered our way of leatherworking. Read the stories and learn from them. Perhaps you'll find some insight on how to better your own methods.", ["objectivesText"] = "Learn from the stories of each of the tanning racks.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 16, ["flags"] = 0 } } },
[40195] = { ["id"] = 40195, ["name"] = "A Daring Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40327 }, ["description"] = "My brother, Taldranis , was on a ship headed here to Azsuna. The ship was ambushed by the sea giants and my brother was taken captive. I believe he still lives out his days in those horrible caves, slaving away for the giants. Go and free him, please. Take this with you, it may give him enough protection should you run into any trouble. And be careful not to get captured by the giants yourself.", ["objectivesText"] = "Find Taldranis in Oceanus Cove, and deliver the armor to him.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130263, 140517, 140922, 141850, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 20, ["flags"] = 0 } } },
[40196] = { ["id"] = 40196, ["name"] = "Adventuring Anxieties", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40197, 41889 }, ["description"] = "<name>! I was recently talking with Mei, the mount trader, and she asked me if it was possible to make a barding that could prevent adventurers from being dismounted. I'd like you to go and discuss this idea with her further. Return to me when you're finished. Perhaps we can solve this issue together.", ["objectivesText"] = "Speak with Mei Francis about her barding idea.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 22, ["flags"] = 0 } } },
[40197] = { ["id"] = 40197, ["name"] = "The Necessary Materials", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40196, 41889 }, ["description"] = "In order to make this barding, we'll need a lot of leather. And I mean a LOT of leather. I'll solidify our plans on fitting the pieces together. You go gather the leather. Once that's done, we can begin crafting.", ["objectivesText"] = "Gather 100 Stonehide Leather . Progress: This is probably the biggest project I've ever been a part of. It's quite exciting!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124113, 130875, 130894, 130895, 130896, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 23, ["flags"] = 0 } } },
[40200] = { ["id"] = 40200, ["name"] = "Battle Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40327, 40415, 41889 }, ["series"] = { 40201, 40241 }, ["description"] = "Do you like pets, <name>? I love pets. They're so cute! But what I really want is more things with which to play with them. I'm sure Lio over at the Magical Menagerie has some ideas for fun toys. You should go talk to her!", ["objectivesText"] = "Talk to Lio the Lioness at the Magical Menagerie shop. Then return to Namha.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 27, ["flags"] = 0 } } },
[40202] = { ["id"] = 40202, ["name"] = "The Final Lessons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40198 }, ["description"] = "<name>, Hrul has requested your presence. From his message it seems as though he's ready to impart to you all the wisdom he has gained from working with the skins of this land. I envy you, <name>... but I'm also proud to see that you've gained so much respect with him. Go now, and good luck!", ["objectivesText"] = "Go to Hrul Sharphoof in Highmountain.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 30, ["flags"] = 0 } } },
[40205] = { ["id"] = 40205, ["name"] = "Respect for the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40207, 40208, 40209, 40210 }, ["description"] = "We record the mistakes of the past so we can learn to avoid them in the present. However, recording history is not just about preventing missteps, but also to celebrate our successes. Scattered around Highmountain at sacred locations are racks with stamped leather, much like the ones here, with stories to tell. Go to these locations, pay your respect, and learn their lessons.", ["objectivesText"] = "Go to the four tanning racks around Highmountain and hear their stories.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 131811, 140336, 141605, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 33, ["flags"] = 0 } } },
[40206] = { ["id"] = 40206, ["name"] = "A Debt Paid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40199 }, ["description"] = "Now, I've never heard of a ghost sending a letter before, but I'll be damned if'n I didn't just receive one now. Celea has sent fer ye, <lad/lass>. I'd best be on me way if I were ye. Might be bad luck to keep a spirit waiting.", ["objectivesText"] = "Go to Celea in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850, 263437, 263438 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 34, ["flags"] = 0 } } },
[40210] = { ["id"] = 40210, ["name"] = "Time Well Spent", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40208, 40209 }, ["description"] = "Unfortunately, <name>, you have learned all that I have to teach. I am pleased we were each able to achieve our goals in this partnership. Go now and share what you've learned with your allies in Dalaran. I'm sure they'd be eager to share in your training.", ["objectivesText"] = "Tell Namha of your time with the night elves in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 38, ["flags"] = 0 } } },
[40211] = { ["id"] = 40211, ["name"] = "Demon Flesh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Something we haven't really explored yet, <name>, are the creatures of Suramar. Specifically, the demons. Now I certainly don't praise what they are, but you can't ignore the fact that some of their creatures have especially tough hides. We could take a lesson from the demon hunters and use those hides to our advantage against the demons. I'll be damned though if I know the first thing about working with demon hide. Perhaps there's someone in Suramar who can help...", ["objectivesText"] = "Search for a master leatherworker in Suramar.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 109076, 140327, 141850 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 40, ["flags"] = 0 } } },
[40212] = { ["id"] = 40212, ["name"] = "Wrong End of the Knife", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40213, 40214 }, ["description"] = "There he is! The man that isn't there! He's... he's... Wait... no, I'm sorry. My thoughts, they're just all over place lately. Ever since my exile, things have been a bit fuzzier than normal. If you wish to learn from me before I completely lose my mind, then do me a favor, and kill those traitors who sided with the demons and exiled me.", ["objectivesText"] = "Kill the traitor leatherworkers, Feorias , Tallian , and Syana .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 41, ["flags"] = 0 } } },
[40214] = { ["id"] = 40214, ["name"] = "Fel Tanning", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40212, 40213 }, ["description"] = "Listen, you. I'm not sure when the crazy side of me will come out again, so let's make our time together short. You want to learn how to make armor to rival the demons? Follow my instructions and you'll have an excellent grasp on the procedures.", ["objectivesText"] = "Craft a pair of bracers for Stalriss using the tanning rack. Progress: You're really here, right? <Stalriss reaches out and pinches you>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 124438, 128891, 128907, 130130, 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 43, ["flags"] = 0 } } },
[40216] = { ["id"] = 40216, ["name"] = "A Hunter at Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40170, 40217 }, ["description"] = "Addie's one heck of a writer, but I've never seen her hold a rifle. She's keen on learning how to hunt, but who's ever heard of a gnome hunter? You seem to have a knack dealin' with amateurs, so maybe you'd be willin' to let the gnome tag along on a hunt? She could learn a thing or two by shadowing someone with your skill. Ya best start off with some small game. We don't want the lass to get discouraged.", ["objectivesText"] = "Help Addie learn to hunt by killing wildlife in Pinerock Basin. Progress: Keep an eye on the gnome while you're huntin'. She's never held a rifle before.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40217] = { ["id"] = 40217, ["name"] = "An Offering of Ammo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["series"] = { 39417, 39859, 40170, 40216 }, ["description"] = "The mountains have seen many new travelers pass through their valleys, some without an understanding of our traditions. Our leaders have turned their focus to more pressing matters, but Losro and I cannot ignore the recent arrival of hunters in the nearby basin. They hunt with guns and gadgets, forgoing the experience of hunting with a bow and arrow. While I know that some will remain stuck in their ways, perhaps an offering of arrows will encourage these outsiders to hunt the way we always have.", ["objectivesText"] = "Deliver the Quiver of Arrows to Hemet Nesingwary at Nesingwary's Retreat. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127769, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 0, ["flags"] = 1 } } },
[40218] = { ["id"] = 40218, ["name"] = "Debt Repaid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 39389, 41759, 41767 }, ["description"] = "I have a few urgent matters to take care of, but soon after I will make my way to Dreadscar Rift and aid you with your summoning. You should warn Ritssyn to keep his distance. I'll be there to repay my debt to you, not to speak to the hypocrite who chose the council over his friends.", ["objectivesText"] = "Speak to Ritssyn Flamescowl .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 6265, 22244, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40219] = { ["id"] = 40219, ["name"] = "In Defiance of Deathwing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 657, ["storyline"] = { 38916, 39575, 39577, 39578, 39579, 39580, 40219 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40229, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "It was in this place, ages ago, that Huln Highmountain challenged the great Deathwing. Today we shall re-live moments of that day through the eyes of our ancestors. For this next part of the spirit journey, we must seek out the three braziers set down many ages ago so that those who would follow in the footsteps of Huln might witness his deeds.", ["objectivesText"] = "Witness 3 Visions. Progress: You are learning parts of our history few outsiders have ever known.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 148, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 657, ["questLines"] = { { ["id"] = 148, ["name"] = "Secrets of Highmountain", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40220] = { ["id"] = 40220, ["name"] = "Thorny Dancing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38862, 40220, 40221 }, ["description"] = "The Thistleleaf sprites have gone completely mad. I suspect they are being manipulated by some very mischievous Thorndancers. Please, friend of the forest, seek out these seductive troublemakers and bring peace to the shallows.", ["objectivesText"] = "Defeat 3 Thistleleaf Thorndancers in the Lunarwing Shallows. Progress: Have you dealt with those Thorndancers yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5912, ["name"] = "Lunarwing Shallows", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40221] = { ["id"] = 40221, ["name"] = "Spread Your Lunarwings and Fly", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38862, 40220, 40221 }, ["description"] = "These poor faerie dragons are being tortured! What's worse, when the thistleleaf become bored they ensnare their victims to continue their torment later. This behavior is simply unacceptable. Please free any trapped Lunarwings you can find.", ["objectivesText"] = "Save 8 Trapped Lunarwings in the Lunarwing Shallows.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121577, 121578, 121579, 121580, 121589, 121590, 121591, 121592, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93600, ["x"] = 0.538, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5912, ["name"] = "Lunarwing Shallows", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40224] = { ["id"] = 40224, ["name"] = "The Hammer in the Deep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["description"] = "< Thrall listens intently.> You found it! The Doomhammer fell to the Crumbling Depths... But the Legion remains a step ahead of us. If we hurry, we can follow the demon Geth'xun and retrieve the hammer before any more of this realm is corrupted. Therazane will open a portal directly there. Let's go!", ["objectivesText"] = "Use Therazane's Portal to travel to the Crumbling Depths. Accompany Stormcaller Mylra and Thrall to recover the Doomhammer. Progress: What of the Doomhammer?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40225] = { ["id"] = 40225, ["name"] = "A Ring Reforged", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 207, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 41510 }, ["description"] = "Speak with Nobundo, and take your place around the circle, <name>. The Earthen Ring will rise again, with you as its leader! Within these stones stands the legendary Heart of Azeroth, which we can use as a base of operations. Perhaps the power of your artifact can unseal the hidden chambers...", ["objectivesText"] = "Speak with Nobundo and take your place as the head of the Earthen Ring. Progress: The Alliance and Horde are in chaos. If we are to save Azeroth, we <class> must bind together!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.500667, ["y"] = 0.393333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40227] = { ["id"] = 40227, ["name"] = "Bad Intentions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "Suramar is lost. Our leaders struck a dark bargain, accepting the Legion as our allies. We were meant to be heroes, guardians - the people resting here. We are not like them any more. I cannot live with them. But cut off from the Nightwell, we wither and devolve into a mindless existence. An existence without release or dignity, as you can see even here... I rejected both of these options and found myself here. I will find a third way.", ["objectivesText"] = "Speak with Thaedris Feathersong in Tel'anor. Progress: Why do you seek to dissuade me?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140252, 140326, 141673, 141945, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40228] = { ["id"] = 40228, ["name"] = "Scout It Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39123, 39124, 39178, 39392, 39859, 39867, 40170, 40216, 40217, 40228 }, ["description"] = "You've proven that a gnome can shoot a rifle, and that's no easy feat, but a true test of Addie's skill will be to see if she can track down an elusive beast. Rumor has it that a ravenous roc circles the basin, cursed by harpy magic, but no one's seen the beast up close. Take this flare, and shoot it into the sky once you've spotted the roc. When we see the signal, the huntin' party will rush in and help bring down that magnificent bird!", ["objectivesText"] = "Kill Irewing after sending up a flare, signaling his location. Progress: Don't just stand there, head out into the basin and find that bird!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 53429, 53432, 80768, 80769, 80770, 80771, 80772, 121653, 121654, 121655, 121672, 130074, 130276, 130277, 130278, 130279, 131365, 143488, 169482, 169483, 169485, 188011, 188017, 188025, 188033, 209917, 209918, 210235, 210236, 211279, 228439, 228440, 228441, 228442, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5918, ["name"] = "Nesingwary's Retreat", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40229] = { ["id"] = 40229, ["name"] = "Step into the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 659, ["storyline"] = { 38912, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39588, 39860, 39873, 40229 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40243, 40312, 40594, 42088, 42512 }, ["description"] = "With the threat to my people quelled, I believe it is time to introduce you to my kin. Meet me at Stonedark Grotto, and you will see where we live.", ["objectivesText"] = "Speak with Navarrogg at Stonedark Grotto.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 145, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 659, ["questLines"] = { { ["id"] = 145, ["name"] = "The Bloodtotem Tribe", ["orderIndex"] = 12, ["flags"] = 0 } } },
[40230] = { ["id"] = 40230, ["name"] = "Oh, the Clawdacity!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "The leader of the Cavemoss makrura, Clawdayshus , has been ordering raids into the Cavemoss village to steal the young for snacks. This isn't going to do at all. In order to prove their power, Murky and the tadpoles must destroy him as well! This is a job for murlocs. Mindmeld with Murky in his egg and show him how it's done!", ["objectivesText"] = "Mindmeld with Murky and defeat Clawdayshus . Progress: Clawdayshus is ruthless. Murky must stop him.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132110, 132111, 132112, 132113, 132114, 132115, 132116, 132117, 143660, 237812, 258221 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40236] = { ["id"] = 40236, ["name"] = "The Dawning Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 40636 }, ["description"] = "It was a miracle that you were able to survive, <name>. It is with great sorrow that I have to say that Grand Master Hight was not so lucky. His spirit now rests with the ancestors. Now we must look to a new leader for our order, our broken temple. I have spoken with the other masters and we are all of one mind on this. We all agree that new leader should be you, <name>. You have shown strength, wisdom, courage, and kindness beyond measure. Walk with us to the temple and we will announce our decision.", ["objectivesText"] = "Accompany Fearsome Jang and await the masters' announcement.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40238] = { ["id"] = 40238, ["name"] = "A Grim Equation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 40129, 47508 }, ["description"] = "They were waiting for us when we crashed. It was all we could do to establish our small outpost. Even now they drain the souls of our fallen to fuel their attacks. Destroy their soul coffers . Free our comrades and let them join the Light. When you have finished, find Y'mera in the field. She has been sorely missed, but she will not have fallen. Of this I am certain.", ["objectivesText"] = "Destroy the three Soul Coffers on the Shattered Fields.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121521, ["x"] = 0.4, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 130076 } },
[40244] = { ["id"] = 40244, ["name"] = "That Guy in the Costume", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40045, 40047, 40049, 40102, 40230, 40244 }, ["description"] = "Aye, when we were out huntin' on the coast, we ran into this ridiculous lad in in a costume. He says he's tryin ta blend in with the murlocs... but I'm pretty sure he's just not right in the head. One of ours stayed behind to keep an eye on him when we headed back to camp... mind checkin' it out? Ye can ask Tamara over there for a ride.", ["objectivesText"] = "Speak to Tamara and fly to Shipwreck Cove.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5920, ["name"] = "Murky Waters", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40247] = { ["id"] = 40247, ["name"] = "Asking a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria Felsoul was one of our best... before she answered the Legion's foul call. She now wields the Aldrachi Warblades - the soul-rending armaments of the ancient race's greatest champion, who fell only to Sargeras himself. We sent a party to track Caria down, but we have not heard from them in some time. Jace has nearly repaired a Legion communicator so we can make contact - we need only a power source. Could you ask Khadgar for assistance? Our friends in this world are few.", ["objectivesText"] = "Ask Khadgar for a source to power the Legion communicator.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40249] = { ["id"] = 40249, ["name"] = "Vengeance Will Be Ours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "We aren't going to get our forces anywhere near the Broken Shore without getting knocked out of the sky. I think it best if you handle this matter yourself - there are none among us more capable on the field of battle. Save Allari and her men if you can, but the Aldrachi Warblades will do far more for this war than warm bodies.", ["objectivesText"] = "Take the Aldrachi Warblades from Caria Felsoul.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40253] = { ["id"] = 40253, ["name"] = "Stop Gul'dan!", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 677, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["series"] = { 38723, 39682 }, ["description"] = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens. Gul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse. Even in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", ["objectivesText"] = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 677, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40254] = { ["id"] = 40254, ["name"] = "Forged in Fire", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 678, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "The fearsome demon, Immolanth, led a Legion army that conquered and eventually ruled a distant nexus world. Somehow, the Wardens imprisoned him, then kept him locked up in the chamber to our left. He is contained, but not for long. The demon's power is a valuable prize to any demon hunter who can defeat him. Whoever can do so will gain power beyond imagining. I believe that person could be you, <name>.", ["objectivesText"] = "Kill Immolanth and take his power. Progress: Do you have Immolanth's power, <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 678, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40255] = { ["id"] = 40255, ["name"] = "Between Us and Freedom", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39694, 40253, 40254, 40255, 40373, 95215 }, ["description"] = "The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.", ["objectivesText"] = "Kill Bastillax and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40256] = { ["id"] = 40256, ["name"] = "Between Us and Freedom", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39690, 39694, 40253, 40254, 40256, 40373 }, ["description"] = "The last of our survivors have fought their way into the final chamber ahead. Only one obstacle stands between us and the vault's exit - the leader of this demon invasion, Bastillax. Kill him, take his power, and claim our freedom.", ["objectivesText"] = "Kill Bastillax and take his power.", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 201989 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40267] = { ["id"] = 40267, ["name"] = "An Unexpected Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 25, ["storyline"] = { 11997, 40267, 40270 }, ["series"] = { 40270 }, ["description"] = "Ah, Felo'melorn. I am familiar with this weapon. For ages the Council of Tirisfal attempted to recover the blade. Its control over the primal forces of fire would be devastating in the wrong hands. As luck would have it, an associate of mine, Archmage Modera has recently uncovered some information on this artifact. This crystal contains a message from her. I suggest you start your search there. The portal over there will bring you back to the city.", ["objectivesText"] = "Discover Archmage Modera 's message by using the Glowing Resonate Crystal .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 130131, 237812 }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 99398, ["x"] = 0.286, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 244, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 25, ["questLines"] = { { ["id"] = 244, ["name"] = "Felo'melorn", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40270] = { ["id"] = 40270, ["name"] = "The Path of Atonement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 267, ["mapID"] = 25, ["storyline"] = { 11997, 40267, 40270 }, ["series"] = { 40267 }, ["description"] = "Felo'melorn, the runeblade of the kings of Quel'Thalas. It was said to harness the very essence of flame and after being reforged by Kael'thas could even stand against the legendary Frostmourne. We thought that the blade was lost with Kael'thas's death but an associate of mine has a lead on where it may be located. We need every advantage we can get and with Felo'melorn in your hand the Legion surely will tremble! Ah, our company is here.", ["objectivesText"] = "Speak to Archmage Modera 's associate at the Dalaran Crater within Hillsbrad Foothills", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 237812 }, ["starts"] = { { ["mapID"] = 25, ["npcID"] = 99398, ["x"] = 0.286, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 99415, ["x"] = 0.286, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.286, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 267 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 244, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 25, ["questLines"] = { { ["id"] = 244, ["name"] = "Felo'melorn", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40297] = { ["id"] = 40297, ["name"] = "Lyana Darksorrow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "<A captive demon hunter floats in stasis in front of you; her soul slowly draining into the harvester crystal.> <In order to release her from stasis, you will need to destroy the soul harvester.>", ["objectivesText"] = "Destroy the Soul Harvester.", ["rewardXP"] = 770, ["rewardItems"] = { 140239, 141938, 141939, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98801, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40300] = { ["id"] = 40300, ["name"] = "Tools of the Trade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I used to visit here before the barrier was raised. While the ruling council and the Grand Magistrix argued and politicked I watched the caretakers perform their rituals and venerate the dead. I would honor the spirits here one last time. I am headed to the tombs. If some of the sacred oils, burial shrouds, or incense survived the ages then bring them to me.", ["objectivesText"] = "Tools of the Trade is a quest added in Legion. If you are interested in the 8.1.5 profession questlines instead, please visit our Tools of the Trade Crafting Overview . Retrieve burial objects for Thaedris. Progress: Did you find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132253, 132255, 134092, 140252, 140326, 141673, 141945, 142054, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192019, 192020, 192021, 192030, 192032, 192037, 193477, 197923, 197924, 197926, 197931, 197932, 197937, 197938, 197944, 197947, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40307] = { ["id"] = 40307, ["name"] = "Glaive Circumstances", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "I came here on a mission to slay the demon eredar, Azoran. During my infiltration, I was shot down from my felbat and captured. I'm not going to mince words, <name>. Azoran plans to use the Burning Legion command ship to destroy Dalaran. To stop him, I will need my warglaives that were lost during my fall from the sky. I would retrieve them myself, but I'm still weakened from my imprisonment. Search for the warglaives on the northern side of the crater, where I was shot down.", ["objectivesText"] = "Retrieve Lyana Darksorrow 's glaives. Progress: Do you have my glaives, <race>?", ["rewardGold"] = 63800, ["rewardXP"] = 6140, ["rewardItems"] = { 130210, 130211, 140239, 141938, 141939, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40308] = { ["id"] = 40308, ["name"] = "Fragments of Memory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40308 }, ["description"] = "<The beautiful elven burial urn is shattered carelessly on the ground. It was clearly handled roughly, but not scratched by the talons of the harpies.> <You find a trail of shards leading towards a cave. Those responsible are certainly within. Thaedris would be interested in the relics and their safe return.>", ["objectivesText"] = "Retrieve 15 Tel'anor Mementos . Progress: What do you have there?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130212, 140252, 140326, 141673, 141945, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 }, { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 }, { ["mapID"] = 680, ["npcID"] = 100096, ["x"] = 0.374667, ["y"] = 0.475333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40315] = { ["id"] = 40315, ["name"] = "End of the Line", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I cannot call Suramar my home any more, and I refuse to become a withered abomination. There is no place for me anymore, don't you understand? We only need one last ingredient to complete the elixir. You will help me, won't you?", ["objectivesText"] = "Speak with Thaedris at the upper landing of Tel'anor. Progress: Please let me fulfill my wishes, <name>.", ["rewardGold"] = 210675, ["rewardXP"] = 4605, ["rewardItems"] = { 38129, 38151, 38152, 38153, 38217, 140252, 140326, 141673, 141945, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40320] = { ["id"] = 40320, ["name"] = "Band of Blood Brothers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You are the one that Toryl was bellowing about? Perhaps you can help me. When I set out to search for Throndyr, I was not alone. Three vrykul loyal to Throndyr also accompanied me. As you can plainly see, I now stand alone. Find my kin, <name>. I cannot bear to think that they also share Throndyr's fate.", ["objectivesText"] = "Locate Katarine, Fjolrik, and Stokalfr in Muddledeep Cavern. Progress: I must know what has befallen my kin.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40321] = { ["id"] = 40321, ["name"] = "Feathersong's Redemption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "I must confess I was not entirely honest with you, <name>. I meant to drink the potion and join my wife. And even she was taken from her rest... I cannot fail her again. I must live and do what I can to stop this coming storm to be worthy of joining her. Come, young one. Let us take care of the harpy matriarch and restore Tel'anor to its former glory. We cannot let this poison go to waste, eh?", ["objectivesText"] = "Slay the Cliffclutch Matriarch . Progress: It will take time, but Tel'anor will flourish again. I swear it on my life.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 130260, 140252, 140326, 141673, 141945, 237812, 245701, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100779, ["x"] = 0.45, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40324] = { ["id"] = 40324, ["name"] = "Arcane Communion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40325, 42224, 42225 }, ["description"] = "All of Kel'danath's experiments to connect with the withered failed, and some even made them more dangerous. Until he found Theryn . His arcane essence - the very soul of the shal'dorei - had been touched by something special. But what? By weaving my arcane essence together with Theryn 's, I can create an empathic bond. This communion will bare his soul to us all - or what's left of it. We need only to feed him mana, and lots of it, in order to begin.", ["objectivesText"] = "Feed Theryn 300 Ancient Mana. Progress: Feed Theryn as much as he will take.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 140255, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40325] = { ["id"] = 40325, ["name"] = "Scenes from a Memory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40324, 42224, 42225 }, ["description"] = "Theryn is at the mercy of his own mind. Whatever we find in there, it may be difficult to control. I will need your help to sort through the visions, so be ready for anything. With any luck, we will discover what makes Theryn special. And... whether there is anything left of who he used to be.", ["objectivesText"] = "Help Thalyssra complete the arcane communion with Theryn.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40326] = { ["id"] = 40326, ["name"] = "Scattered Memories", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 41702, 41704, 41760 }, ["description"] = "<As your fingers trace the elegant symbols on the page, a voice dictates the words in your mind. It seems the nightborne have elevated even simple note-taking to a sorcerous art. Arcanist Kel'danath was definitely working in this area. There must be more of his notes scattered around.>", ["objectivesText"] = "Inspect 6 pages of Kel'danath's Notes.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40328] = { ["id"] = 40328, ["name"] = "A Fate Worse Than Dying", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "When the Burning Legion takes a prisoner, it is not an act of mercy. While death is the destruction of the mortal body... if you are captured by the Legion, they will seek to destroy your soul. The Burning Legion uses sacrificial souls to power their demonic machinations of war. The soul engine is where the harvested souls are collected and stored. Though countless have already perished in the soul engine, you may yet save those still alive inside. Hurry and release them before it is too late!", ["objectivesText"] = "Open 8 Soul Engine Cages. Progress: Have the soul engine cages been opened?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140239, 141938, 141939, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40332] = { ["id"] = 40332, ["name"] = "Beach Bonfire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "Do not let... my body lie in... the mud. Set my flesh... aflame.", ["objectivesText"] = "Collect 6 Driftwood in Azuregale Bay and build a funeral pyre for Jarl Throndyr . Progress: Throndyr deserved a more honorable death.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132371, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99559, ["x"] = 0.69, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40336] = { ["id"] = 40336, ["name"] = "Turning the Tidemistress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "The Tidemistress has fallen back to the elven ruins and is licking her wounds. Her guard is undoubtedly protecting her. To best her, you will have to break her defenses. Construct a ballista using the parts that you salvaged and end her once and for all.", ["objectivesText"] = "Construct a Makeshift Ballista and kill Tidemistress Sashj'tar in the Sashj'tar Ruins. Progress: We finally have the advantage against the Sashj'tar. Now is the time to kill the Tidemistress.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133819, 140244, 140245, 140254, 141674, 141675, 141946, 237812, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40341] = { ["id"] = 40341, ["name"] = "Throne of the Tides: Azshara's Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["series"] = { 43645 }, ["description"] = "Wavespeaker Adelee tracked Sharas'dal to the Throne of Tides within the Abyssal Maw, then disappeared. <name>, if we go after her, we are almost certainly walking into a trap. But the elements are with us, my friend. The naga will not expect a shaman of your caliber! Swim to the Throne of Tides to the Northwest, within the Abyssal Depths. I will join you once you are inside. Let's find our missing shaman and get that artifact!", ["objectivesText"] = "Travel to the Throne of Tides and acquire Sharas'dal. Progress: What news from the deeps, <class>?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 6948, 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205, 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40348] = { ["id"] = 40348, ["name"] = "Something in the Water", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "There is something fouling these waters, <class>. We will need to purify the waters in order to restore balance to the elemental forces below this ruin. The magic here has warped the elementals and they are beyond restoration. Release their corrupted forms so that they may be reborn pure.", ["objectivesText"] = "Slay 12 Mana-corrupted Waterspawn . Progress: Is it done?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 140243, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40370] = { ["id"] = 40370, ["name"] = "Purge the Unclean", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "Do you feel it in the air, <race>? The stage is set for us to make things right. While you were busy I was able to track down the elder elemental that rules these waters. Its name is the Azurefall Guardian and it resides within the channels below Tel'anor. Take the ritual focus, it should help you during the battle.", ["objectivesText"] = "Defeat the corruption in the Azurefall Guardian. Progress: Did you find the source of the corruption?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 131760, 140243, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40373] = { ["id"] = 40373, ["name"] = "A New Direction", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7814, ["mapID"] = 679, ["storyline"] = { 38672, 38689, 38690, 38723, 39682, 39683, 39684, 39685, 39686, 39687, 39688, 39689, 39690, 39694, 40253, 40254, 40255, 40256, 40373, 95215 }, ["description"] = "<name>, as leader of the Illidari in Lord Illidan's absence, you must choose your second-in-command. Kayn or Altruis. You can only choose one. The chosen shall become your personal champion, and their ideology will color our decisions for the Illidari going forward. No matter who is chosen, our mission remains unchanged. If you need a reminder of our past, gaze into the Pool of Judgment. Remember the sacrifices that forged us into demon hunters. Speak to me when you are ready to choose.", ["objectivesText"] = "Choose between Kayn and Altruis. Progress: Have you made a choice?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 132243, 138970, 141650 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7814 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1468, ["db2PoiUiMapID"] = 679, ["questLines"] = { { ["id"] = 150, ["name"] = "Vault of the Wardens", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40378] = { ["id"] = 40378, ["name"] = "Enter the Illidari: Ashtongue", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["description"] = "Lord Illidan has placed you in charge. Now, we just need the rest of our Illidari attack force. There are three Burning Legion gateways ahead. Activate them and our Illidari will pour through from the Black Temple. Like most Legion constructs, the gateways are powered by souls. I think we have provided enough to activate this first one, don't you? Let us bring in our Ashtongue forces.", ["objectivesText"] = "Summon in your Ashtongue forces by activating the Legion Gateway. Progress: <name>, I remind you that we need our Ashtongue forces to be brought through the gateway back on Despair Ridge.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 14, ["flags"] = 0 } } },
[40379] = { ["id"] = 40379, ["name"] = "Enter the Illidari: Coilskar", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38759, 39049, 39050 }, ["description"] = "The next gateway's down on the Molten Shore. Our Coilskar forces are waiting at the Black Temple on the other side. Personally, I wouldn't have chosen to bring our naga allies. But, their leader did swear fealty to Lord Illidan. I suppose we'll see. We'll have to find a way to power the gateway's activator. Like this last gateway, it runs on souls. <Allari the Souleater grins as Sevis says this.>", ["objectivesText"] = "Feed a soul into the Legion Gateway Activator and then use it to summon in your Coilskar forces.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40384] = { ["id"] = 40384, ["name"] = "Needs of the Hunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "The eagle appears to have a message for you: To: <name> The time has come to strike back at the Legion. Meet me at Hunter's Reach in Dalaran as soon as you can. - Emmarel Shadewarden", ["objectivesText"] = "Speak with Emmarel Shadewarden in Dalaran.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 0, ["flags"] = 1 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 0, ["flags"] = 1 } } },
[40385] = { ["id"] = 40385, ["name"] = "The Spear in the Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "Many years ago, a corrupted nightsaber hunted my people. Our chieftain, Dorro Highmountain, took Talonclaw and pursued the beast, but never returned. I have heard tales of a fearsome nightsaber that now stalks the mists of Stormheim. My brother and I believe this to be our ancient foe. The weapon must be there too! If we kill the beast and reclaim the spear, it will be of great use against the Legion.", ["objectivesText"] = "Hunt down Highmountain's Bane.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 140548, 140773, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 110821, ["x"] = 0.599, ["y"] = 0.81 }, { ["mapID"] = 650, ["npcID"] = 110986, ["x"] = 0.608, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 650, 739 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40388] = { ["id"] = 40388, ["name"] = "Huln's War - Shadowsong", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7838, ["mapID"] = 697, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40515, 40520 }, ["description"] = "Someone with whom I believe you are familiar commands in the battlefield below. Jarod Shadowsong speaks highly of you, and has requested that you join him in battle. He has plans to put an end to this fight.", ["objectivesText"] = "Meet with Jarod Shadowsong in the battlefield.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7838 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1515, ["db2PoiUiMapID"] = 697, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40391] = { ["id"] = 40391, ["name"] = "Take Me To Your Leader", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "I am glad you are here, <name>. This... Khadgar, the archmage who found my message, has called a meeting. He wishes to meet us at the entrance to the city as soon as possible. Will you accompany me? I have the strangest feeling that he will not be alone.", ["objectivesText"] = "Meet with Khadgar in Suramar .", ["rewardGold"] = 210675, ["rewardXP"] = 4605, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40392] = { ["id"] = 40392, ["name"] = "Call of the Marksman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 739, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 41540 }, ["description"] = "Time is of the essence! If Alleria and Thas'dorah are in Legion hands, it is only a matter of time until both are forfeit. If you are ready, head to the Broken Shore to meet with Ranger-General Windrunner. She has lent her personal hippogryph to fly you down to the surface.", ["objectivesText"] = "Take the hippogryph from Krasus' Landing down to the Broken Shore and meet with Vereesa Windrunner .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103415, ["x"] = 0.473818, ["y"] = 0.453455 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.473818, ["y"] = 0.453455 }, ["mapCandidates"] = { ["npc"] = { 646, 739 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40400] = { ["id"] = 40400, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40400, 40419, 41540 }, ["series"] = { 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "You have long been a trusted hero of the Alliance, <name>. And like the rest of us, you have endured many hardships to reach this point. Now, I must ask even more of you. Will you hear me out?", ["objectivesText"] = "Speak to Vereesa Windrunner . Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40402] = { ["id"] = 40402, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "As you well know, I have opposed the Horde at many turns. The orcs have taken... so much from me. From my family. Yet I have witnessed your deeds firsthand, <name>. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point. Now, I must ask your help. Will you hear me out?", ["objectivesText"] = "Listen to Vereesa Windrunner 's tale. Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40403] = { ["id"] = 40403, ["name"] = "Clandestine Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40402, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "It is no small matter for me to seek the aid of a blood elf. Your leaders have turned their backs on the sacrifices made by my family and so many others. Yet I have witnessed your deeds firsthand, <name>. I have seen you fight for Azeroth time and again. And like the rest of us, you have endured many trials and hardships to reach this point. Now, I must ask your help. Will you hear me out?", ["objectivesText"] = "Listen to Vereesa Windrunner . Progress: Now you must decide whether you will stand with me.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40408] = { ["id"] = 40408, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38710 }, ["description"] = "Our gathering has identified several weapons of immense power. In the right hands, these holy artifacts give us a fighting chance against the Legion. We cannot pursue all of them at once. We risk too much if we spread ourselves that thin. We must agree on where our efforts are best focused. That is why I asked you here, <name>. As one of our greatest champions, you must be our voice of reason and decide our next move.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40412] = { ["id"] = 40412, ["name"] = "Azoran Must Die", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You won't have much time before the Legion is aware of your presence on the ship. When the alarm is raised, countless Burning Legion forces will attempt to board the ship through this portal. I will not let them succeed. I will guard this portal from enemy reinforcements until you return. It is up to you to slay Azoran and lay waste to his ship. We don't have much time... you must attack swiftly and without mercy.", ["objectivesText"] = "Defeat Azoran in Felsoul Hold. Progress: Has Azoran been slain?", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 140239, 141938, 141939, 237812, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100053, ["x"] = 0.31, ["y"] = 0.848 }, { ["mapID"] = 680, ["npcID"] = 100823, ["x"] = 0.31, ["y"] = 0.85 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100878, ["x"] = 0.312667, ["y"] = 0.841333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40415] = { ["id"] = 40415, ["name"] = "Well Spent Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Your respect for our ways has earned you all the knowledge we have to teach. Go now, <name>, and spread our ways to those who fight against the legion. Perhaps it will help to turn the tide in this war for our world.", ["objectivesText"] = "Tell Namha of your time with the tauren in Highmountain.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 39, ["flags"] = 0 } } },
[40419] = { ["id"] = 40419, ["name"] = "Rescue Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 40400, 40402, 40403, 40952, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "The demon has told us how to open a portal to the world where he says Alleria is being held. You and I can go through and see if there is any truth to his claims. In case it's a trap, Magus Solgaze has given me a portal stone to get us back to Dalaran. This demonic magic is anathema to the mage, so we must move quickly. I'm ready when you are, <name>.", ["objectivesText"] = "Travel through the portal and rescue Alleria Windrunner.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 141446, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 100190, ["x"] = 0.323, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.323, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40495] = { ["id"] = 40495, ["name"] = "Ulthalesh, the Deadwind Harvester", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 47, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "The book says the Dark Riders were last seen in a place called Manor Mistmantle. If friend can find these riders, then <he/she> can get Ulthalesh! Calydus will wait here and await your return. Find Ulthalesh, friend!", ["objectivesText"] = "Start your search for the Deadwind Harvester at Manor Mistmantle in Duskwood. Progress: And just why should I help you, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 173527, 237812 }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40515] = { ["id"] = 40515, ["name"] = "A Walk With the Spirits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40520 }, ["description"] = "The spiritwalker you saved from Riverbend has been insufferable since his arrival. He is insisting on showing you the ways of our people so that you better understand what is to come. He is a strange one, even by spiritwalker standards. Even so, only a fool would discard his insight. Please, go to speak with him when you get a moment.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 0, ["flags"] = 1 } } },
[40517] = { ["id"] = 40517, ["name"] = "The Fallen Lion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40519, 42740, 42782, 43806 }, ["description"] = "I haven't left the deck of this ship since we got back. The fleet must be made ready for war. Don't know where we will be needed, but when the call comes, we'll be ready. Truth be told... I welcome the distraction. The others are paying their respects to Varian, but I... I cannot bring myself to face that casket. To face his son. Varian gave me a letter he wrote to Anduin. Please, take it to him on my behalf.", ["objectivesText"] = "Deliver King Varian's letter to King Anduin. Progress: Welcome, <name>. I am pleased you survived the battle. You have something for me?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 132251, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100395, ["x"] = 0.202, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100429, ["x"] = 0.856, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40518] = { ["id"] = 40518, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Your warship awaits at the end of the dock, <name>. May your weapon bring you many kills today. The Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", ["objectivesText"] = "Take Captain Russo 's ship to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 113547, ["x"] = 0.555, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40519] = { ["id"] = 40519, ["name"] = "Legion: The Legion Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 42740, 42782, 43806 }, ["description"] = "Heroes of the Alliance, I write to you in Azeroth's darkest hour. From the maw of hell, the burning armies of the Legion have returned. Our fleets depart for the Broken Isles at once. As a grand lance, we will pierce the Legion's lines and drive them back to the nether that spawned them. Your ship awaits in the Stormwind Harbor, make haste.", ["objectivesText"] = "Check in with Recruiter Lee at Stormwind Harbor. Provided item:", ["rewardItems"] = { 132120, 139389, 139391, 140192, 143785, 237812 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 1, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40520] = { ["id"] = 40520, ["name"] = "To See the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["series"] = { 39983, 39988, 39990, 39991, 39992, 40112, 40167, 40388, 40515 }, ["description"] = "I would like for you to experience firsthand what Huln Highmountain was able to accomplish in a single battle during the War of the Ancients. To do so, I will need very specific ingredients. They are not too difficult to obtain--you can find all of them near Thunder Totem.", ["objectivesText"] = "Collect a Bottle of Airspark , Mu'sha's Tears , and Darkshard Crystal . Progress: Earth, air, and water are all magics we have come to know well in our mountain.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132246, 132247, 132248, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 146, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 146, ["name"] = "Huln's War", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40522] = { ["id"] = 40522, ["name"] = "Fate of the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is a wonder any of our troops survived that bloodbath on the Broken Shore. If not for Lady Sylvanas... High Overlord Saurfang has been asking for you at Grommash Hold. He will not say why... but he was insistent that I send you to him.", ["objectivesText"] = "Go to Grommash Hold and learn the fate of the Horde. Progress: Dark days are upon us.", ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100866, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.105 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40523] = { ["id"] = 40523, ["name"] = "Facet-nating Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40529, 40530, 40531 }, ["description"] = "Excuse me, <sir/madam>. Are you sure you're in the correct shop? We only deal in the finest of jewels here. Ahh, I see... you're a fellow lapidary. Then perhaps we can work together. Introduce yourself to my associates, so they're aware of who you are and what you may have to offer.", ["objectivesText"] = "Introduce yourself to Timothy Jones and Sminx Glasseye. Progress: Get yourself acquainted and we'll discuss business.", ["rewardItems"] = { 132467, 139497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40524] = { ["id"] = 40524, ["name"] = "A Familiar Ring to It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "<name>! Let's talk bling. I'm looking for a ring. See, the elves down in Azsuna were some fine master jewelcrafters back in the day... or so they say. The books all talk about a ring called the \"Band of Farondis\". Can't hurt to ask around for it. Let's head to Azsuna. Bet I'll get there sooner!", ["objectivesText"] = "Find the Shrine of Aldiir near the Crumbling Palace in Azsuna and read about its legend. Progress: Have you tracked down the ring?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132467 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40525] = { ["id"] = 40525, ["name"] = "Getting the Band Back Together", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "I like our dynamic, <name>. You're the muscle with all the hustle! And I'm the brains who entertains! I think this next task is all on you. Try to find that ring, or whatever the murlocs left of it.", ["objectivesText"] = "Find the three pieces of the Band of Farondis and bring them back to Timothy Jones . Progress: How goes the hunt for the ring?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132368, 132467, 132875, 132876 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40529] = { ["id"] = 40529, ["name"] = "Truly Outrageous", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40530, 40531 }, ["description"] = "Ore prospecting is our primary method of gem acquisition. And while prospecting... you're bound to find small, unusable gem chips . Many gem shops simply discard the small gem chips they find, but we here at Cartier & Co. let nothing go to waste.", ["objectivesText"] = "Gather 5 Gem Chips for Tiffany Cartier . Gem Chips can be acquired through Prospecting raw ore or purchased off the auction house. Progress: Try not to get any blood on them while you're out \"adventuring\".", ["rewardItems"] = { 123918, 123919, 129100, 132467, 139497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40530] = { ["id"] = 40530, ["name"] = "An Eye for Detail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40529, 40531 }, ["description"] = "<name>, if there's one thing I despise, it's slander. A rumor is spreading that one of my recent commissions is a fake. We need to quell these rumors as quickly as possible. I need you to visit the customers I recently worked for and examine their gems. If your claim of being a jewelcrafter is true, then you will be able to spot a fake gem from a mile away. Here's the list of my patrons. Return immediately if you find any truth to these rumors.", ["objectivesText"] = "Visit the patrons of the jewelcrafting shop in Dalaran and report back to Tiffany. Progress: I will not let these falsehoods ruin the good name of Tiffany & Co.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 132467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40531] = { ["id"] = 40531, ["name"] = "Swift Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40523, 40529, 40530 }, ["description"] = "I swear, when I find him... <Tiffany catches your eye and regains her composure.> <name>, I need you to track down my FORMER associate, Harold Winston. I doubt he's gotten far, given our location. When you find him, I would like you to recover the stolen property and return it to me. Use any means necessary. And don't worry about Ms. Moore's jewels, I'll redeliver a fresh supply to her personally.", ["objectivesText"] = "Find Harold Winston in Dalaran's Underbelly. Progress: Did you find him? Were you able to recover the jewels?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132259, 132467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40536] = { ["id"] = 40536, ["name"] = "Bruls Before Jewels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40535 }, ["description"] = "So, you wish to learn what Jabrul knows about jewels? Well, Jabrul needs your help. Before we leave this place, Jabrul still needs harpy necklaces. Keep those harpies off of Jabrul while he takes their necklaces and Jabrul will reward you with his knowledge.", ["objectivesText"] = "Protect Jabrul while he finds harpy necklaces and escort him back to the nearby night elf camp.", ["rewardItems"] = { 132467, 132468, 132469 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.693333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 14, ["flags"] = 0 } } },
[40537] = { ["id"] = 40537, ["name"] = "Drawing Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 40537, 49694, 49876 }, ["series"] = { 49694 }, ["description"] = "Hey, <name>! I have something exciting to tell you about, but you must keep a secret. Just between us scribes. <Zooey gives you a wink and pulls out a large tome.> This is the Bloodbound Ledger. Inscribing your name in it allows you to learn how to craft \"blood contracts\" which can hurt a little bit, but are absolutely worth it! I currently know one of them and I get so excited when I use it 'cause it... well, you'll see. So whaddya say? Interested?", ["objectivesText"] = "Sign the Bloodbound Ledger.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 901, ["name"] = "8.1.5 Inscription - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40540] = { ["id"] = 40540, ["name"] = "Come at Me, Brul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40541 }, ["description"] = "<name>, I received a... well, what can only be constituted as a \"letter\", carved into a piece of flat rock. That jewelcrafting master you found in Val'sharah has sent for you. He said he's in Stormheim currently. When you see him, would you be so kind as to inform him that we don't wish to receive any more of his requests for your presence. They just make a mess.", ["objectivesText"] = "Find Jabrul in Stormheim.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 132467 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40541] = { ["id"] = 40541, ["name"] = "The Charge Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40540 }, ["description"] = "Before Jabrul shares his designs with you, he needs you to help him with a special project. Jabrul has a jewel that can trap storm energy. The more lightning it traps, the brighter it shines. Jabrul thinks the storm drakes' power would be better spent in his jewel than terrorizing the skies of Stormheim. Don't you?", ["objectivesText"] = "Use the Conducting Jewel on the corpses of 10 Squallhunter storm drakes.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 132467, 132760, 137663 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 18, ["flags"] = 0 } } },
[40545] = { ["id"] = 40545, ["name"] = "Aww Scrap!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40854 }, ["description"] = "It's a catastrophe! No, even worse, a conspiracy! I heard the Legion was back again, and I thought to myself, \"Hobart, now's your time to shine.\" I made us enough guns to blow those demons back to the beginning of time! But then we get here, and what happens? Everyone just happens to \"find\" all these ancient artifacts to fight the demons with! Long story short, I have too many guns and need to get rid of 'em.", ["objectivesText"] = "Take the Crate of Guns down to Filgo Scrapbottom in the Underbelly. Provided item:", ["rewardItems"] = { 133578, 133671, 133672, 133673, 133674, 133750, 137691, 137692, 137725, 139495, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40556] = { ["id"] = 40556, ["name"] = "Jabrul Needs You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40547 }, ["description"] = "Hello <name>, Jabrul needs your help with something. Could you please come to Azsuna and find Jabrul ? Thank you, Jabrul", ["objectivesText"] = "Find Jabrul in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 132467 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100521, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 24, ["flags"] = 0 } } },
[40567] = { ["id"] = 40567, ["name"] = "Darkheart Thicket: Enter the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "We could not save Ysera, but we did prevent her from destroying the temple. Now I can finally turn my attention to my husband. I do not know what fate he suffers now. I only know that if we stand any chance of saving him, you must go now. Follow Xavius into the Nightmare and find Malfurion. Please, save my husband if you can.", ["objectivesText"] = "Enter Darkheart Thicket and Slay the Shade of Xavius . Progress: Is he alive? Will my husband return to me?", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 141548, 141549, 141550, 141551, 237812, 246812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104921, ["x"] = 0.536, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104921, ["x"] = 0.536, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 10, ["flags"] = 1 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 10, ["flags"] = 1 } } },
[40568] = { ["id"] = 40568, ["name"] = "Fury of the Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38624, 39652, 40568 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 44922, 44940 }, ["description"] = "The Felskorn who ravage my brood were once Drekirjar - a tribe with whom we shared an ancient pact. Now, under the influence of the God-King, they forsake their oaths and strike at the forebears of their coveted drakes. They should answer for this slight. Awaken your fury, <class>, and take the battle to them!", ["objectivesText"] = "Kill 10 Felskorn vrykul in Thorim's Peak. Progress: Are we rid of the Felskorn threat?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 190454, 197921, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 91249, ["x"] = 0.446, ["y"] = 0.775 }, { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 96465, ["x"] = 0.422667, ["y"] = 0.816667 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.775 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 132, ["questLineOrder"] = 5 }, { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 133, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 638, ["questLines"] = { { ["id"] = 132, ["name"] = "The Trial of Will", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 133, ["name"] = "The Trial of Will", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40569] = { ["id"] = 40569, ["name"] = "The Legend of the Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "Nothing! There is next to nothing in our records about this weapon! I've checked and re-checked, and can find barely a shred of a tale. This can only mean that the story comes from a land outside Pandaria. Li Li Stormstout is young, but she is the most traveled on the entire isle except for you. If anyone might know of this weapon, it is she.", ["objectivesText"] = "Speak with Li Li Stormstout . Progress: What's up?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40570] = { ["id"] = 40570, ["name"] = "Into The Heavens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "This stone is saturated with elemental power, possibly the remnant of the magic used against Irmaat! If you went outside and held the stone aloft, it should unleash the stone's essence as a mighty whirlwind. So potent a windstorm could carry you and your companion all the way to Skywall! If the hand blades of Irmaat, the Fists of the Heavens, are as powerful as the old tales say, they would certainly be found there.", ["objectivesText"] = "Obtain the Fists of the Heavens.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 132745, 133948, 237812 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40573] = { ["id"] = 40573, ["name"] = "The Nightmare Lord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38382, 39383, 39384, 40573 }, ["series"] = { 38148, 38322, 38323, 38377 }, ["description"] = "You arrived just in time, friend. Kagraxxis was moments away from sacrificing me to his master... I was certain I would perish. I am grateful, but we are not out of danger yet... Xavius has returned. The Nightmare Lord is here in Val'sharah , personally orchestrating the corruption of this land. My captor revealed as much to me before I was to be sacrificed. We must find Thaon Moonclaw and inform him before it is too late!", ["objectivesText"] = "Inform Thaon Moonclaw of the return of Xavius.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121643, 129992, 130000, 130008, 130019, 237812, 245698, 246937 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 91650, ["x"] = 0.65, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100573, ["x"] = 0.622, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 185, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 185, ["name"] = "Archdruid of the Vale", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40578] = { ["id"] = 40578, ["name"] = "Paying Respects", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "All I see is despair. Look, <race>. The grounds are overwhelmed with these wraiths, spirits of those interred here. Something has made them angry and they are lashing out. I can feel their pain. I will go look for remaining relics, and there is a tomb I must see. It is too late for these unfortunate souls. Please defeat any you find and return them to the rest they deserve.", ["objectivesText"] = "Slay 8 Disturbed Apparitions or Disturbed Spectres .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140252, 140326, 141673, 141945, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40579] = { ["id"] = 40579, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 40579 }, ["description"] = "As the greatest warrior in these halls, you require a great weapon to do both your will and mine. I have looked down on Azeroth and found artifacts worthy of your hands. I leave it to you to choose which artifact you wish to seek out and wield against the Legion. We will recover the others in time.", ["objectivesText"] = "Select an artifact weapon to pursue. Progress: Choose wisely, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40585] = { ["id"] = 40585, ["name"] = "Thus Begins the War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "The Legion thinks you are dead. It will be quite the surprise when you punish them for that assumption! This allows us to see all across the Broken Isles and assign warriors to various tasks. Once you've taken a look, you should choose your first area of operation. I've already picked out the best spots!", ["objectivesText"] = "Select your order's first assault point.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40588] = { ["id"] = 40588, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Very well. I suppose an introduction is in order. I am Revil Kost , priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them. The Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before. Come with me to Ariden's camp. I will explain on the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40593] = { ["id"] = 40593, ["name"] = "Demons Among Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 39691, 40518, 40522, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "The king is wise to focus on the Legion's threat, <name>. Even now, the demons move against us. The Illidari will aid the cause of the Alliance. We believe they have set their sights on key locations around Azeroth. In fact, they could already be in your midst! I sense they are close...", ["objectivesText"] = "Protect Stormwind Keep from the Legion. Progress: I never suspected they had infiltrated my own throne room! Praise the Light you were here!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 138773, 138774, 138775, 138776, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100675, ["x"] = 0.854667, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.854667, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40594] = { ["id"] = 40594, ["name"] = "Justice Rains from Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 42088, 42512 }, ["description"] = "Kill now, grieve later! Here, champion, take flight with one of my war eagles . Use the powers bestowed upon you by our united tribes and help us rain destruction down on these drogbar. Let us clog that new doorway to their lair with the bodies of their own!", ["objectivesText"] = "Bomb the forces of the Understone Breach Progress: The drogbar sure do love those rocks.", ["rewardGold"] = 295000, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40603] = { ["id"] = 40603, ["name"] = "Seeking the Valkyra", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We simply cannot risk another catastrophe like that; we have to protect the Heart against fel energy before we continue our work. The mighty Ashildir has proven willing to aid those who she deems worthy, and her master just may be able to help us protect the Heart. You should seek her out at the Vault of Eyir in Stormheim. I'll meet you there.", ["objectivesText"] = "Seek out Ashildir at the Vault of Eyir in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 23, ["flags"] = 0 } } },
[40605] = { ["id"] = 40605, ["name"] = "Keep Your Friends Close", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "The Legion is bold indeed to strike at the Horde's stronghold! You aided our defense, but now I have a more important task for you. It seems the demon hunters will play a crucial part in this war... but I still don't trust them. You will be my envoy to the Illidari. Learn what they know. Study their techniques. If they betray us, we'll use their own knowledge against them. Their camp lies atop the plateau in the city. Go. Nathanos and I will clean up this mess.", ["objectivesText"] = "Speak to Elthyn Da'rai at the Illidari camp atop the plateau in Orgrimmar .", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40606] = { ["id"] = 40606, ["name"] = "To Point the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Though the journal devolves into dark ramblings written in hurried scribbles, one entry stands out: \"Ulthalesh. The name rings in my head. I can hear it calling, but where? \"The spirits... the very land here is tied to it. It is no wonder we would so often get lost in this place. The forces pull my compass point in every direction... \"Perhaps if it had a stronger pull, the compass could show the way...\"", ["objectivesText"] = "Find the compass mentioned in the journal in Ariden's Camp. Progress: Is that the one?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 132377, 237812 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40607] = { ["id"] = 40607, ["name"] = "Demons Among Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Look around. What do you see? <Allari glares at something over your shoulder.> The Legion has already infiltrated the Horde... even now, they are among you. We must protect your Warchief. When you are ready to see what lies beneath the veil, say the word.", ["objectivesText"] = "Learn what Allari the Souleater sees. Progress: The Illidari were right! Destroy the demons, <name>!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 138773, 138774, 138775, 138776, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40608] = { ["id"] = 40608, ["name"] = "The Mark", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Your blade is powerful, but it has not yet met its full potential. The all-powerful Odyn in the Halls of Valor can bestow upon you his strength. In order to seek this blessing, you must bring him a worthy tribute. I know where you may obtain such a gift, but in order to retrieve it you must first receive the mark of the Valkyra. Prove yourself worthy of our mark, champion, then you may enter the Vault of Eyir- the goddess will guide you from there.", ["objectivesText"] = "Prove your worth to the Valarjar , then receive the Mark of the Valkyra from Eyir. Progress: Greetings, champion. How go your trials?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 9630, 9631, 9632, 9633, 25502, 25503, 25504, 30226, 30252, 65466, 128826, 131425, 131426, 131427, 131428, 132471, 139020, 139631, 139706, 139780, 140198, 140199, 140410, 142054, 146127, 158968, 158969, 158970, 158971, 159075, 160009, 160010, 160011, 160012, 160021, 160022, 160023, 160024, 198608, 205251, 235913, 237812, 239484, 260427 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 24, ["flags"] = 0 } } },
[40611] = { ["id"] = 40611, ["name"] = "The Fate of Deadwind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "The journal mentions a \"stronger pull\" for the compass. If the spirits of this place are indeed tied to it, they may serve as the pull we need. I've come upon several locations in the pass where restless spirits tend to appear. Perhaps if you show the spirits there the compass, they may be able to help point it in the right direction. You seek these locations out. I'll continue on to Karazhan and see if I can find anything leading to the Dark Riders.", ["objectivesText"] = "Attune Ariden's Compass at the sites of restless spirits around Deadwind Pass.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40613] = { ["id"] = 40613, ["name"] = "Maw of Souls: Retrieving the Svalnguard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Svalnguard was once Odyn's shield; it is said that it hid the Halls of Valor from the endless darkness below his realm. Helya, who was cast from the shining halls long ago, stole The Svalnguard and keeps it on her accursed ship, the Naglfar. You must board the Naglfar, defeat Helya, and retrieve The Svalnguard - it will make a worthy tribute for Odyn.", ["objectivesText"] = "Retrieve the Svalnguard and defeat Helya in the Maw of Souls on Mythic difficulty. Progress: Have you wrested the Svalnguard from Helya's clutches?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132440, 132471, 139631, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 25, ["flags"] = 0 } } },
[40614] = { ["id"] = 40614, ["name"] = "A Feast Fit for Odyn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "It is customary in the Halls of Valor to feast after battle is finished. Presenting a truly glorious feast to Odyn from beasts worthy of his throne will show him your determination to earn his blessing. Acquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and the finest cut of steak from Leytusk in Azsuna. They will make a feast worthy of the great battle to come.", ["objectivesText"] = "Acquire flank meat from Thunderhoof in Stormheim, Spinesever's spine in Highmountain, and a steak from Leytusk in Azsuna. Progress: The beasts you hunt have taken the lives of many.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132462, 132463, 132464, 132471, 139631, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 26, ["flags"] = 0 } } },
[40615] = { ["id"] = 40615, ["name"] = "Halls of Valor: Odyn's Blessing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "You are ready, <class>. Travel to Odyn's shining halls and offer the feast on the altar just inside. Mighty Odyn will then set his gaze upon you - you must pass the ancient trials of the Valarjar under his watch. Only then will you receive Odyn's blessing.", ["objectivesText"] = "Obtain Odyn's blessing in the Halls of Valor on Mythic difficulty. Progress: Few have sought Odyn's blessing and returned triumphant.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140306, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 28, ["flags"] = 0 } } },
[40618] = { ["id"] = 40618, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "Three weapons... three worthy paths. Acquiring one such artifact will be the first step in battling the Legion. The weapon will grow in power as you wield it, so you must choose the one which will be the focus of your efforts, <name>. After a time, you will be able to pursue the other weapons. But you must decide which to seek first.", ["objectivesText"] = "Select your first artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40623] = { ["id"] = 40623, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40632] = { ["id"] = 40632, ["name"] = "Take Me To Your Leader", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["description"] = "I am glad you are here, <name>. This... Khadgar, the archmage who found my message, has called a meeting. He wishes to meet us by the entrance to the city as soon as possible. Will you accompany me? I have the strangest feeling that he will not be alone.", ["objectivesText"] = "Meet with Khadgar in Suramar .", ["rewardGold"] = 210675, ["rewardXP"] = 4605, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40633] = { ["id"] = 40633, ["name"] = "Off To Adventure!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "Oh I'd love to go see if that story is true! But Pops is too busy stuffing his gut and being a grouch to let me go do any real exploring. He even told me that I can't leave the village unless I have a guardian! Is Pops for real? I can protect myself just fine! Say, would you be my guardian? Please, get me away from this boredom and you will totally be my hero!", ["objectivesText"] = "Meet with Li Li in Ramkahen. Progress: Do you see this place? This is so neat!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 237812 }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 100571, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40634] = { ["id"] = 40634, ["name"] = "Thunder on the Sands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 40569, 40570, 40633, 40634 }, ["description"] = "I know the tale of Irmaat well. It is said that his home was the ancient city of Ahmtul, long buried under the desert sands. Recently a strange storm has appeared over the ruins. What's more, I am told that an elemental called Nader has attacked my people in nearby lands. These events must be related. Find this Nader and put an end to him. Make sure to search his body for clues as to what is behind this.", ["objectivesText"] = "Defeat Nader and search his body for clues. Progress: Have you found anything, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 132560, 133948, 237812 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47684, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 195, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 249, ["questLines"] = { { ["id"] = 195, ["name"] = "The Fists of the Heavens", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40636] = { ["id"] = 40636, ["name"] = "Prepare To Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 40236 }, ["description"] = "The Burning Legion took us by surprise at the Peak of Serenity. We will not allow them to do so again! We have trained hard, but we need weapons capable of destroying this great evil if we are to have any chance of success. Our scrolls speak of several weapons that should prove suitable, but we are unable to decide which one to pursue first. The choice, Grand Master, is yours.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 128940, 133948, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40643] = { ["id"] = 40643, ["name"] = "A Summons From Moonglade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40644, 40645, 40646, 41106 }, ["description"] = "<name>, Your presence is requested at Moonglade at once. We are preparing for a ritual of great importance and will require your assistance. I will meet you there, so please come with haste.", ["objectivesText"] = "Meet Hamuul Runetotem at the Moonglade. Provided item:", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 140192, 173716, 237812 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40644] = { ["id"] = 40644, ["name"] = "The Dreamway", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40645, 40646, 41106 }, ["description"] = "The preparations for the ritual are now complete. Come with me, <name>, I will guide you to the ceremony.", ["objectivesText"] = "Assist with the ritual. Progress: Are you ready to begin the ritual?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 103875, ["x"] = 0.668, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40645] = { ["id"] = 40645, ["name"] = "To The Dreamgrove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40646, 41106 }, ["description"] = "The portal to the Dreamway is open and it is here where our paths must part. The Moonglade remains vulnerable to the attacks of the Burning Legion and I must ensure it is well defended. I'm entrusting you with the mission to Val'sharah, <name>. Archdruid Greathoof is the leader of the druids there. He is wise in the old ways and will provide us invaluable assistance. The Dream can be dangerous so I will send Keeper Remulos to guide you. Meet with him upon the other side.", ["objectivesText"] = "Go through the portal to the Dreamgrove.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 103875, ["x"] = 0.668, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40646] = { ["id"] = 40646, ["name"] = "Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40645, 41106 }, ["description"] = "I agree with Keeper Remulos. To confront and defeat the Legion, we will need weapons of legendary power. Among the history of our kind, there have been four weapons of renown. Tell me, which weapon would you pursue first?", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 128306, 128821, 128822, 128858, 128859, 128860, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40647] = { ["id"] = 40647, ["name"] = "When Dreams Become Nightmares", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Now that we have Ursol's blessing, we can safely pass the magical wards and reach the claws' resting place! Now, we must pass into the Dream. Lay down before the Shrine of Ursol and drink of the moonwater you brought earlier and your spirit will drift off into the dream. Be careful, the Dream can be a dangerous place.", ["objectivesText"] = "Enter the Emerald Dream and obtain the Claws of Ursoc. Progress: Have you retrieved the Claws of Ursoc?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 136414, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40649] = { ["id"] = 40649, ["name"] = "Meet with Mylune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "It would seem we are fortuitous that you seek G'Hanir this day, <name> - the dryad Mylune arrived not long ago from the sacred shrine where the staff has been guarded for many centuries. Few are privy to its hidden location within the roots of Shaladrassil, but you have certainly earned that right. Speak to Mylune when you are ready to depart - I saw her last just east of here up the hill.", ["objectivesText"] = "Find Mylune .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40650] = { ["id"] = 40650, ["name"] = "Champion: Zen'tabra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40652] = { ["id"] = 40652, ["name"] = "Word on the Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40653, 41332 }, ["description"] = "It is time that we turn our attention to matters in the Broken Isles. Skylord Omnuron has gathered information on events from all over the Isles. If we are presented with any opportunity to strike against the Legion he will know of it. Go and see if he has anything available.", ["objectivesText"] = "Speak to Skylord Omnuron .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40653] = { ["id"] = 40653, ["name"] = "Making Trails", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40652, 41332 }, ["description"] = "The Burning Legion threatens the life of Azeroth, but the nightmare threatens its very soul. We must remove both threats if our world is to survive. This map will allow us to track the developments all across the Broken Isles and respond to threats as they arise. Our forces are limited for now, so we should focus our efforts where they will be the most effective. Once you've taken a look, you should choose where we shall begin.", ["objectivesText"] = "Select your order's first operational area.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40654] = { ["id"] = 40654, ["name"] = "Druids of the Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["description"] = "A new ally has joined our ranks. His name is Yaris Darkclaw , a skilled trainer among the Druids of the Claw. Go speak to him now.", ["objectivesText"] = "Speak to Yaris Darkclaw .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40668] = { ["id"] = 40668, ["name"] = "Eye of Azshara: The Heart of Zin-Azshari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The naga in the Eye of Azshara summon terrible storms that ravage the coastline of Azsuna - storms far beyond the abilities of even their best sirens. It can only be the Heart of Zin-Azshari . Prior to the Sundering, Azshara's chosen used the Heart to greatly magnify their power - it is said to have been key in their dominance of the Well of Eternity. If you can journey to their domain and retrieve it, <name>, we will put its power to far better use than those foul creatures.", ["objectivesText"] = "Retrieve the Heart of Zin-Azshari and defeat the Wrath of Azshara in the Eye of Azshara on Mythic difficulty. Progress: Have you retrieved the Heart?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132738, 139631, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40672] = { ["id"] = 40672, ["name"] = "Neltharion's Lair: Presentation is Key", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Odyn will demand a feast worthy of the ancient trials you must complete; a feast's merit begins not at the great beasts piled upon it, but at the dish used to serve it. Deep beneath Highmountain lies the former lair of Neltharion - you may know the infernal drake better as Deathwing. You will find remnants of the adamantium plating used to hold his molten skin together in the deepest recesses of his lair. They will form a fine dish for the feast.", ["objectivesText"] = "Retrieve 4 Adamantium Casing Scraps and defeat Dargrul the Underking in Neltharion's Lair on Mythic difficulty. Progress: Dare not serve Odyn a feast upon an improper dish. Such action will only earn his ire.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132744, 139631, 139773, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100738, ["x"] = 0.626, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 27, ["flags"] = 0 } } },
[40673] = { ["id"] = 40673, ["name"] = "Lost Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We are indeed familiar with the Nightborne's magic, but we were never allowed access to the Heart. It was a right reserved only for the Queen's favored. However, we can still learn how to properly tap its magic. Thousands of years ago, a Nightborne scholar studied the Heart and documented his findings in great detail. He was executed and the scroll of his writings banned, but the Nightfallen secreted it away in their escape. If you obtain the scroll, we can help you.", ["objectivesText"] = "Obtain the Scroll of Elun'dris from First Arcanist Thalyssra. Progress: The Nightfallen have become... distrustful... since the Nightborne's betrayal. You will have to earn their respect before they will let you near the scroll.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40675] = { ["id"] = 40675, ["name"] = "The Arcway: Rite of the Captain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Only a captain of the Guard may receive the power of our order - our ancient laws forbid otherwise. You must complete the rite of the captain. Traditionally, aspirants patrol the Arcway for three weeks without rest, the vast labyrinth putting their skills as a Guard to the test. Our laws must still be honored, but I believe there another way you may prove yourself. Elisandre's advisor, Vandros, has recently descended into the Arcway's depths. Kill him, and take his Eon Winder .", ["objectivesText"] = "Take Advisor Vandros' Eon Winder from The Arcway on Mythic difficulty. Progress: Have you completed the rites as asked?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139787, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 19, ["flags"] = 0 } } },
[40678] = { ["id"] = 40678, ["name"] = "Twisted Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "It is time we put our work to the test by infusing the most potent source of power I know of - fel magic. Rarely, the Legion's minions will carry fragments of the greater portal stones used to usher in their eredar masters. If you gather enough to form a complete stone, you can use it in Faronaar to call forth the eredar lord Vizuul the Twisted at the Altar of End Times. The bindings Vizuul wears to augment his power should push the Heart to its very limit.", ["objectivesText"] = "Use a Greater Portal Stone to summon Vizuul the Twisted at the Altar of End Times in Faronaar and collect his runebindings. Progress: Do you have the bindings?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 132749, 132750, 132751, 137604, 137623, 139631, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 21, ["flags"] = 0 } } },
[40684] = { ["id"] = 40684, ["name"] = "The Tome of Blighted Implements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 628, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 40685, 40716, 40729 }, ["description"] = "The book you carry is the key to your friends' salvation, and to your absolute power! It holds within information about many relics too dangerous to the Legion to leave unchecked. Read, friend. And decide which of these artifacts you will use to strike Jagganoth down!", ["objectivesText"] = "Speak with Calydus to choose which artifact you will pursue. Progress: Have you made your choice?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 128941, 128942, 128943, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 274, ["name"] = "The Tome of Blighted Implements", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 2, ["flags"] = 0 } } },
