[40705] = { ["id"] = 40705, ["name"] = "Priestly Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 40706 }, ["description"] = "<Master/Mistress> <name>, I come at the behest of one who seeks to organize a stronger resistance to the Legion threat. If you would meet him at Faol's Rest in Tirisfal Glades, he will guarantee both your safety and an opportunity to play a pivotal role in the conflict.", ["objectivesText"] = "Attend the secret meeting at Faol's Rest in Tirisfal Glades.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173373, 237812 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40706] = { ["id"] = 40706, ["name"] = "A Legend You Can Hold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 40705 }, ["description"] = "To face the trials ahead, you require a weapon that can enhance your considerable abilities. I have learned of a few possibilities that you might consider. You must decide which weapon to pursue first. I have the utmost confidence in your decision.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40710] = { ["id"] = 40710, ["name"] = "Blade in Twilight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 18, ["storyline"] = { 40710, 53761, 53762, 53763, 54058, 54114, 54118, 54126, 84371, 84779, 84782, 84784, 84789, 85871 }, ["description"] = "I have been working with Moira Thaurissan to infiltrate the Twilight's Hammer cult. We've learned of an ancient and powerful Old God relic, a blade used at various points in history to wreak havoc. Moira's double agent informs us a new leader is rising, and plans to cement his ascension using this weapon in an unholy ritual. You must find him, stop the ritual, and seize the artifact. We will meet in Dalaran afterwards.", ["objectivesText"] = "Stop the ritual and acquire Xal'atath, Blade of the Black Empire. Progress: Not too difficult a task, I hope!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173523, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 }, { ["mapID"] = 18, ["npcID"] = 231472, ["x"] = 0.128, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18, 84 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 219, ["questLineOrder"] = 8 }, { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 219, ["name"] = "Blade in Twilight", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40712] = { ["id"] = 40712, ["name"] = "The Power Possessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 627, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40731, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "I was wrong about you, warlock. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge. Nevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Ulthalesh, I can think of no safer place than in your care. May it serve you well against the Legion, warlock.", ["objectivesText"] = "Return to Calydus in The Underbelly in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 140192, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40714] = { ["id"] = 40714, ["name"] = "The Call To War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39799, 39832, 40714 }, ["series"] = { 40715 }, ["description"] = "<A chilling thought brushes your mind.> Hear me, <name>. The Legion has returned. They hope to control us, to bend us to their will. Fools - they only walk back within reach of our blades. Your brethren within Dalaran have begun to gather at Krasus' Landing. Go, meet with Duke Lankral and all will be explained.", ["objectivesText"] = "Meet with Duke Lankral at Krasus' Landing.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 170, ["name"] = "The Ebon Blade", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40715] = { ["id"] = 40715, ["name"] = "A Pact of Necessity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 40714 }, ["description"] = "We have an unexpected ally in this war, <name>, and we're going to need every advantage we can get to defeat the Burning Legion. The Ebon Blade will serve as the Lich King's arm as long as the Scourge is confined to Northrend. In return for our assistance, our ally has offered to assist in obtaining powerful weapons for the strongest of our knights. Weapons powerful enough to end the Legion once and for all! You are one of our best, <name>. I want you to decide which weapon you would like to seek out.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128292, 128293, 128402, 128403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40716] = { ["id"] = 40716, ["name"] = "The Sixth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 40684, 40685, 40729 }, ["description"] = "Greetings, warlock. I speak on behalf of the Council of the Black Harvest. With the Legion invasion upon us, it is painfully clear that our only hope is to grow stronger. The council plans to tap into the Twisting Nether and call forth more powerful demon allies. The ritual is ready, but we are short one number. No doubt you have heard of the fate that befell Kanrethad Ebonlocke. You will be his replacement. Do you accept?", ["objectivesText"] = "Meet with Ritssyn Flamescowl in the Circle of Wills beneath Dalaran.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140192, 140517, 140922, 142057, 142058, 142059, 142063, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40727] = { ["id"] = 40727, ["name"] = "All Along the Waterways", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I've noticed some wandering eyes, lately. I am more than happy to continue delivering the goods to Vanthir , but it is getting increasingly dangerous to do so. The Duskwatch that walk the bazaar are by far the most observant. Find and slay the Orbitists so that I may deliver the goods safely. I will follow behind with the shipment.", ["objectivesText"] = "Slay 3 Duskwatch Orbitists . Progress: What of Deline ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40729] = { ["id"] = 40729, ["name"] = "The New Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40684, 40685, 40716 }, ["description"] = "It is time to begin the ritual, warlock. Be prepared, for the summoning we perform today will be more challenging than any you have known or seen before. Are you ready?", ["objectivesText"] = "Complete the summoning ritual with the Council of the Black Harvest in the Circle of Wills in Dalaran.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 132512, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40731] = { ["id"] = 40731, ["name"] = "The Heart of the Dreadscar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40823, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Friend has the artifact! Now Jagganoth does not stand a chance! Quickly, you must go back to Dreadscar Rift! You may still be able to save your friends from Jagganoth's vengeance. If you take the heart of the overlord , his army will be yours to command!", ["objectivesText"] = "Defeat Jagganoth and take his heart to the Seat of the Overlord in Dreadscar Rift.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 132880, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40740] = { ["id"] = 40740, ["name"] = "The Dead and the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 40740 }, ["description"] = "<A powerful mind again touches your thoughts.> Gorelix the Fleshripper is a monstrous demon. The butcher of a thousand worlds, he has exterminated countless races with his axe, the Maw of the Damned . A group of Ebon Blade was dispatched to slay him but they have gone missing. You will succeed where they failed. You will not be alone in this, I've sent Baron Sliver ahead to assist you. Go, obtain the Maw of the Damned and ensure that Gorelix is no more.", ["objectivesText"] = "Travel to Dalaran and fly upon Zeomus to Darkstone Isle. While there, travel through the Demon Portal, find Baron Sliver, and obtain the Maw of the Damned . Progress: It is time to begin, <name>.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 169, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 169, ["name"] = "The Maw of the Damned", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40745] = { ["id"] = 40745, ["name"] = "Shift Change", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "This is as good a chance as we are going to get to rescue Verene's daughter. Here is how this is going to work. You are going to wait here for the guard to pass by on their way to their guard shift. Look for something to hide in. < Silgryn marks a spot on your map.> You will know the guard by their bright red armor. Follow closely, but not so closely that you are seen. It may be necessary to kill the guard when you reach your destination. The child's name is Korine . Good luck.", ["objectivesText"] = "Hide in the basket and wait for the guard to appear. Follow the guard to their destination. Progress: W-who are you?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138147, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107997, ["x"] = 0.482, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40746] = { ["id"] = 40746, ["name"] = "One of the People", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "It is time for you to enter the city proper, <name>. I am sending you to my loyal friend Vanthir . I do hope you remember him- I can guarantee that he remembers you. I will not be able to accompany you, but I must stress that the disguise I have granted you is not impervious. Tread carefully, and avoid those who stare too long. Farewell for now.", ["objectivesText"] = "Meet with Vanthir in Suramar City.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40747] = { ["id"] = 40747, ["name"] = "The Delicate Art of Telemancy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "I hadn't the time to gather my instruments before fleeing the palace. I came here to salvage some equipment. This old workshop is actually several rooms connected by teleporter pads. Elisande's goons are already scouring the place looking for me, but from here I can alter the teleporter network and keep them moving in circles. You go in. I'll monitor your position and ensure the teleporters work normally for you. Find these two parts and bring them back!", ["objectivesText"] = "Collect the Weathered Telemancy Beacon and Cracked Warpsleeve from Oculeth's Workshop. Progress: Salvaging the equipment here is necessary if I am to develop a teleporter network for Thalyssra.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 132893, 132894, 139786, 139890, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.477333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40748] = { ["id"] = 40748, ["name"] = "Network Security", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We must lock down the facility. Otherwise my esteemed colleagues from the palace could uncover my secrets, which puts any teleporters I build for you and Thalyssra at risk. <The inactive attunement device near Oculeth hums to life.> This will take us to my secret test chamber beneath the mountain. From there we can begin the lockdown sequence and make our escape!", ["objectivesText"] = "Complete the lockdown sequence in Oculeth's Test Chamber.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 138783, 139786, 139890, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101499, ["x"] = 0.494, ["y"] = 0.477333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102142, ["x"] = 0.344, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.477333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40760] = { ["id"] = 40760, ["name"] = "Emissary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "As if things weren't unsettled enough, guests have arrived... the Illidari. These demon hunters have been imprisoned since their master's fall at the Black Temple. For the Wardens to release them can only mean the peril is dire indeed. Their delegation's leader, Allari \"the Souleater,\" claims Orgimmar faces a hidden threat. I gave them leave to establish a camp within the city... for now. You will speak with her at once. Find out whether this threat is credible.", ["objectivesText"] = "Speak with Allari the Souleater .", ["rewardGold"] = 70225, ["rewardXP"] = 2125, ["rewardItems"] = { 37213, 37396, 37423, 37487, 197639, 197640, 197641, 226194, 234731, 237812, 247820, 250117 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100866, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40761] = { ["id"] = 40761, ["name"] = "Whispers from Oronaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Ethereals, the Void, a Dark Naaru... I feel they are all connected. I explored the ruins below while you and Velen were seeking the Crown. There are survivors, <name>. Broken wander the cluster of buildings to our west- I cannot understand much of what they say but I suspect that their minds are not their own. If the Void is to blame, we will need to start our investigation there. I will conduct my own search in the meantime.", ["objectivesText"] = "Investigate the Ruins of Oronaar .", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40783] = { ["id"] = 40783, ["name"] = "The Scythe of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40784, 40785, 40834, 40835 }, ["description"] = "I have received word that Tyrande herself has authorized the release of a great artifact, the Scythe of Elune, to aid our cause. Valorn Stillbough has agreed to give up the weapon, which he has kept as part of an investigation into the cursed worgen of Duskwood. I believe that you, champion, will be our best hope at wielding its power without succumbing to the animal rage that ebbs within. You must go to Duskwood, and take up the scythe against our foes!", ["objectivesText"] = "Meet with Valorn Stillbough in the Twilight Grove in Duskwood. Progress: The champion arrives. I hope you are prepared for this burden.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 101656, ["x"] = 0.488, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40784] = { ["id"] = 40784, ["name"] = "Its Rightful Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40785, 40834, 40835 }, ["description"] = "Though it goes against my better judgment, it is Tyrande's wish that the Scythe of Elune be brandished once more against the new Legion threat. It is a small comfort to see it wielded by a keeper of the balance, such as yourself. Know that the last time the scythe was wielded, it resulted in great calamity. You must be vigilant to contain the bestial wrath that ebbs within. With those words in your heart, take the scythe and bring its fury against our foes. May the light of Elune protect you.", ["objectivesText"] = "Take the Scythe of Elune from Valorn. Progress: The scythe is yours, <class>.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 128306, 128822, 128858, 128859, 175451, 175452, 175453, 175454, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 101656, ["x"] = 0.488, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 101651, ["x"] = 0.488, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40785] = { ["id"] = 40785, ["name"] = "A Foe of the Dark", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40834, 40835 }, ["description"] = "I cannot believe the Dark Riders found us here. Long have they hunted the scythe to sate their lust for the artifacts of Azeroth. We thought we would be protected within the grove... And now, Valorn is gone... You must become the hunter, <name>. Seek the Dark Riders and recover the scythe. We last encountered them near Manor Mistmantle in Duskwood. Start your search there. And <name>... bring justice to Valorn. The rider must pay.", ["objectivesText"] = "Start your search for the Scythe of Elune at Manor Mistmantle in Duskwood.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 101651, ["x"] = 0.488, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40793] = { ["id"] = 40793, ["name"] = "A Matter of Planning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Your weapon is stronger than ever, now is the perfect time to put it to use and take our fight to the Legion. Master Hsu has set up a command table by the training grounds, and has collected reports from our friends and allies around all of Azeroth. When you are ready, Grandmaster, he should have an update prepared for you.", ["objectivesText"] = "Speak to Master Hsu .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40794] = { ["id"] = 40794, ["name"] = "Fate of the Queen's Reprisal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 37654, 37657, 37659, 40794, 42220 }, ["description"] = "<This is the kind of intelligence that should be shared. Perhaps someone at the Greyfang Enclave on Dalaran will know what to do with it.>", ["objectivesText"] = "Take the Captain's Log to Lieutenant Surtees at the Greyfang Enclave on Dalaran. Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 121482, 121488, 122570, 138855, 138856, 138857, 138858, 138859, 138860, 138861, 138862, 141403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 5, ["flags"] = 0 } }, ["startItems"] = { 133328 } },
[40795] = { ["id"] = 40795, ["name"] = "The Fight Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "The Burning Legion has left a trail of ruin all across the face of Azeroth. We must strike at their bases within the Broken Isles if we are to have any hope of ending this war. I've put together a map of the isles and a list of tasks that we will need to have done there. Once you've had a chance to peruse the map, you should choose where we will begin our assault.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40814] = { ["id"] = 40814, ["name"] = "The Power to Survive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "We have long relied on Lord Illidan to vanquish the Legion's strongest warriors - many have expressed concern over our efforts without him. Thankfully, their concerns may not matter much longer. We know of two pairs of blades rumored to be more powerful than even Lord Illidan's that are not yet out of reach. If we act quickly we should be able to hunt down one without forsaking our watch over the Legion's movements. I must defer judgment on which is most worthy of our time to you, <name>.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40815] = { ["id"] = 40815, ["name"] = "From Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?", ["objectivesText"] = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 101927, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90255, ["x"] = 0.412, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40816] = { ["id"] = 40816, ["name"] = "The Power to Survive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Illidan and I may have disagreed, but he was unarguably powerful. He was pivotal in vanquishing some of the Legion's most powerful soldiers. However, that may not matter much longer. There are two pairs of blades rumored to be more powerful than even Illidan's that may still be within reach. Regrettably, our numbers are too few to hunt both while maintaining our vigil over the Legion. I fear our window of opportunity is waning quickly. As the ranking Illidari, that decision falls to you.", ["objectivesText"] = "Select an artifact weapon to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127829, 127830, 128831, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40819] = { ["id"] = 40819, ["name"] = "Making Arrangements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "Do you recall Varedis, <name>? He was once our lead trainer, but fell with the Black Temple years ago. ...or so we thought. Kor'vas spotted the traitor alongside the Legion... wielding glaives imbued with power unlike anything she'd ever seen. The Kirin Tor have an eredar lord locked away in the Violet Hold that will know where Varedis' stronghold lies. The prison warden has agreed to consider granting us access to the fiend. Time to do some convincing.", ["objectivesText"] = "Meet Kayn Sunfury outside the Violet Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40823] = { ["id"] = 40823, ["name"] = "Rebuilding the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 41155, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "It seems that friend has caught the attention of Mephistroth. This is very bad news, as the dreadlord will surely wish to seek revenge for losing his general. Friend will need more than the Dreadscar to stand against him, you will need powerful warlocks such as those who were captured. Calydus thinks the orc still lies in the pit where you were chained. Friend must revive him, and rebuild the council!", ["objectivesText"] = "Resurrect Ritssyn Flamescowl in Dreadscar Rift. Progress: I will not rest until the council has been rebuilt.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40824] = { ["id"] = 40824, ["name"] = "The Path of the Dreadscar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40729, 40731, 40823, 40824 }, ["description"] = "It would seem that where the council has failed, you have found untold success. These Dreadscar should prove powerful allies, but they may not be enough. For now, we must look to rebuild. I will send agents out to locate the whereabouts of the captured council members, as well as any other warlocks who may be able to aid the cause. Meet me at the scrying pool, and we will plan our action from there.", ["objectivesText"] = "Use the Dreadscar Battle Plans to choose your first zone.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40830] = { ["id"] = 40830, ["name"] = "Close Enough", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "<Oculeth's eyes have dulled. His voice trembles.> Are we... are we close? So hungry...", ["objectivesText"] = "Carry Chief Telemancer Oculeth to Thalyssra in Shal'Aran. Progress: Where is Oculeth?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102142, ["x"] = 0.344, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40832] = { ["id"] = 40832, ["name"] = "Call of The Uncrowned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40839 }, ["description"] = "My masters gave me strict instructions to deliver this letter to you as quickly as possible. Its contents are for you and you alone. Good luck.", ["objectivesText"] = "Read the Sealed Letter and follow the instructions within.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128479, 128870, 128872, 133558, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40834] = { ["id"] = 40834, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40785, 40835 }, ["description"] = "In my previous confrontation with your foe, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they once were. Come, we must go to Ariden's Camp in Deadwind Pass. I can explain its significance along the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40835] = { ["id"] = 40835, ["name"] = "Disturbing the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40783, 40784, 40785, 40834 }, ["description"] = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.", ["objectivesText"] = "Search around Ariden's Camp for clues leading to the Dark Riders.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40837] = { ["id"] = 40837, ["name"] = "The Deadwind Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40838, 40900 }, ["description"] = "The Nightbane! If they are in Deadwind Pass, then they may be seeking the scythe as well. Let's split up and try to track them down. We'll see where their trail leads...", ["objectivesText"] = "Follow the tracks of the Nightbane worgen.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40838] = { ["id"] = 40838, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40837, 40900 }, ["description"] = "This sewer grate leads to the catacombs underneath Karazhan. I've never paid it much attention, but it seems to be where the Nightbane are being drawn to. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders and claim the Scythe of Elune. Progress: It is done.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40839] = { ["id"] = 40839, ["name"] = "The Final Shadow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40832 }, ["description"] = "You walk in the halls of the Uncrowned. We are the slayers of kings, the downfall of empires, the unseen blades that write the true history of this world. Seated before you are the Shadows, the council which aims the blades of the Uncrowned wherever our will demands. We have brought you here today with an offer. Take your seat as the final Shadow and help us lead the Uncrowned. What do you say?", ["objectivesText"] = "Take your seat in the Council of Shadows. Progress: It's up to you, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128479, 128870, 128872, 136786, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40840] = { ["id"] = 40840, ["name"] = "A Worthy Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["description"] = "For quite some time, we've been looking for someone who can operate outside these halls. <name>, you are the answer to that search. You will be the blade in the dark that vanquishes our foes. In order to do so, you require weapons capable of striking down the Legion's best. Greymane, Tethys, and Valeera each have devised plans to obtain weapons worthy of the tasks to come. I suggest you hear each out before proceeding.", ["objectivesText"] = "Select a weapon to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128476, 128479, 128870, 128872, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40847] = { ["id"] = 40847, ["name"] = "A Friendly Accord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 210, ["storyline"] = { 40847 }, ["description"] = "I'd like to offer ya an accord. The Dread Admiral Eliza wields a pair of cursed blades that have made her the scourge of the south seas. She also stole one of me best ships - the Horizon's Edge - and has it anchored off the shore of Azsuna as we speak. If you help me take back me ship, then her cursed blades are yours. Now, assuming that sounds agreeable, meet me aboard the Crimson Veil. We have her docked right in Booty Bay - not a cheap arrangement.", ["objectivesText"] = "Meet Fleet Admiral Tethys aboard the Crimson Veil in Booty Bay.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 173528, 237812 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 102120, ["x"] = 0.406, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 162, ["questLineOrder"] = 7 } }, ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 162, ["name"] = "The Dreadblades", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40849] = { ["id"] = 40849, ["name"] = "The Dreadblades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 40849 }, ["description"] = "I can promise ya a safe journey to Eliza's position, but once we're there... well, we both know there be no guarantees. The plan is simple. We'll take the Crimson Veil as close as we can get her without being seen and disembark from there. Once we're ashore, we'll board the Horizon's Edge, bribe her mutinous crew to hand it over, and hunt down Eliza and her legendary blades wherever she may be. Just say the word when yer ready.", ["objectivesText"] = "Capture the Horizon's Edge and obtain the Dreadblades .", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 102120, ["x"] = 0.406, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 162, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 162, ["name"] = "The Dreadblades", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40854] = { ["id"] = 40854, ["name"] = "Endless Possibilities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40545 }, ["description"] = "Say, since you're down here, I have something that you might be interested in. <Filgo points over to a husk lying in the junk behind him.> I found that thingy down in Azsuna, just lying on the beach. I'm sure with a little tinkering, an engineer like you could probably get it up and running in no time. Might even be useful against the Legion. Kind of like fighting fel with fel, heh!", ["objectivesText"] = "Bring the Fel Reaver Husk back to Didi the Wrench in Dalaran. Progress: Is there something you need fixed?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133752, 137691, 137692, 137725, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40855] = { ["id"] = 40855, ["name"] = "Our Man in Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "Yikes! OK. This thing is missing a LOT of parts. Why don't you go hunt down some new gears or whatever while I do what I can to its existing frame? A colleague of ours, down in Azsuna, may be able to help out here. His name's Flintlocke. Fetching parts should keep him out of trouble. Just don't let him BUILD anything.", ["objectivesText"] = "Find Fargo Flintlocke in Azsuna near the Felblaze Ingress.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40856] = { ["id"] = 40856, ["name"] = "It'll Cost You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40858, 40863, 40864 }, ["description"] = "If yeh need demon parts, oh aye, this place is right teeming with them fel buggers. Yer bound ta find what'yer lookin' fer probably near them portals they've got jus' sou'east of 'ere.", ["objectivesText"] = "Collect a Fel Reaver Arm and a Fel Reaver Leg from within the Felblaze Ingress. Progress: Found what'cha need yet?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133753, 133754, 137691, 137692, 137725, 141849, 211279, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40858] = { ["id"] = 40858, ["name"] = "The Missing Pieces", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40863, 40864 }, ["description"] = "Yeh seem ta 'ave everything yeh need. Head back to Didi now wit' yer supplies and giv'er a slap on tha back from me!", ["objectivesText"] = "Head back to Didi the Wrench in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 49040, 123918, 132514, 133671, 133672, 133673, 133674, 136633, 136637, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40859] = { ["id"] = 40859, ["name"] = "The Latest Fashion: Headguns!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "So Grapplehammer's got hisself a whole lotta extra guns, right? Glorious! An'it got me ta thinkin', \"What if we put 'em on our heads?\" Hear me out! See, yer hands are already busy with yer current weapons, but what's yer head doin'? It's just sittin' there LOOKIN' at stuff. That's me plan. Weaponize yer head! You, me lucky <lad/lass>, can test it out. Strap this on. Now, go blast some fel-tainted critters down below. Blammo!", ["objectivesText"] = "Kill 10 Fel Critters using Flintlocke's Headgun Prototype .", ["rewardItems"] = { 133671, 133672, 133673, 133674, 133761, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102195, ["x"] = 0.652, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40860] = { ["id"] = 40860, ["name"] = "Resupplying the Line", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, I need you to make a delivery for me. Flintlocke's sent word from Val'sharah stating that they're out of bullets. I sent him down there with enough ammo to cut the planet in half, but Flintlocke goes through ammunition the way you or I go through... air. Go help him out!", ["objectivesText"] = "Deliver the Crate of Ammunition to Fargo Flintlocke in Val'sharah. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133772, 137691, 137692, 137725, 141849 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40862] = { ["id"] = 40862, ["name"] = "All Charged Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "If yer gonna wander inta these woods, ye'll be wantin' somethin' with some punch. These plants are a might grabby. I've got me special explosive charges here that should send those fertilizer mutations back to the dirt. Take 'em with yeh and give them viney beasties a what-fer!", ["objectivesText"] = "Use Flintlocke's Gunpowder Charges to kill 15 Shimmering Oleanders.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 97919, 132510, 133671, 133672, 133673, 133674, 133775, 137691, 137692, 137725, 141849, 239607 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40864] = { ["id"] = 40864, ["name"] = "Modular Modifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40858, 40863 }, ["description"] = "Now that we got this baby running, let's give it some cool abilities. When I was fixing Reaves up, I installed a module port onto his motherboard. This will allow us to upload anything we want. I'll teach you one of my module designs and you install it on Reaves.", ["objectivesText"] = "Create a Reaves Module: Snack Distribution Mode. Then summon Reaves and install it into him. Progress: I have a lot of other ideas for things we can do, but I only wrote down a couple to start.", ["rewardItems"] = { 112059, 123919, 124109, 124112, 124119, 124121, 132500, 132501, 132502, 132503, 132504, 132505, 132506, 132507, 132509, 132510, 132511, 132513, 132514, 132515, 132516, 132517, 132518, 132519, 132523, 132524, 132525, 132526, 132528, 132529, 132530, 132531, 132982, 133578, 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40865] = { ["id"] = 40865, ["name"] = "It's Not Rocket Science", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, I need you to help me track down Flintlocke again. I sent him to Stormheim to gather some materials for an invention of mine and he hasn't been back for days. I'm not worried about Flintlocke, but I DO fear for Stormheim. See if you can find him!", ["objectivesText"] = "Find Fargo Flintlocke in Stormheim.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40868] = { ["id"] = 40868, ["name"] = "Wibbly-Wobbly, Timey-Wimey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40866, 40867 }, ["description"] = "I gotta finish up 'ere, so why don'tcha take those trinkets back to Hobart fer me. 'Sides, I'ma thinkin' he likes ya more than me.", ["objectivesText"] = "Deliver the Murloc Trinkets to Hobart Grapplehammer in Dalaran.", ["rewardItems"] = { 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 14, ["flags"] = 0 } } },
[40869] = { ["id"] = 40869, ["name"] = "Fire and Forget", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "They say, \"When life gives you lemons, make lemonade.\" Well, life gave me a butt-load of guns. So I've been figuring out ways to turn these guns into useful tools. My latest modification is a gun that shoots bandages! Imagine it, you're on the battlefield, you see your ally go down, you pull out your bandage gun, shoot him with it and bam, he's back in the fight! I just need you to test it first and make sure it's safe.", ["objectivesText"] = "Test out the Prototype Pump-Action Bandage Gun on Wounded Kirin Tor Guardians in Dalaran. Use the gun to calibrate it when needed.", ["rewardItems"] = { 132511, 133671, 133672, 133673, 133674, 133928, 137691, 137692, 137725, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40871] = { ["id"] = 40871, ["name"] = "Locke and Load", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40872 }, ["description"] = "Flintlocke's been looking for you, <name>. I think he needs your help again. I sent him out to test out a couple of new inventions of mine back down in Azsuna. Look for him on the shoreline west of Oceanus Cove!", ["objectivesText"] = "Find Fargo Flintlocke in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 64559, 64560, 64561, 64562, 64563, 64564, 64565, 64566, 64567, 64568, 133671, 133672, 133673, 133674, 137691, 137692, 137725, 141849 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40872] = { ["id"] = 40872, ["name"] = "Going Out With a Bang", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40871 }, ["description"] = "While I was, eh, testin' out this new flight pack fer Hobart, it sorta exploded an' sent me flyin' back over 'ere. You can see all the pieces out there in tha water. Now, I've got these boots 'ere that Hobart gave me to test out too, but they're not quite me size. I figure we could kill two birds with one stone and 'ave ye test 'em out while pickin' up the broken bits of the pack. Mind tha sharks while yer out there.", ["objectivesText"] = "Use the Gunshoes to skim across the water while picking up 15 pieces of Gunpack Debris .", ["rewardItems"] = { 132516, 133941 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 18, ["flags"] = 0 } } },
[40874] = { ["id"] = 40874, ["name"] = "I'd Do It Myself, But...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40875, 40876 }, ["description"] = "If yer headed over ta tha sea giant caves, do me a favor give those slimy naga a right bludgerin'. They done run oft with me rogue friend an' I figure some revenge is in order. I'd do it meself but ol' Hobart would give me wut-fer if I abandoned his stuff.", ["objectivesText"] = "Kill 10 Hatecoil Slavemasters in the Oceanus Cove.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 20, ["flags"] = 0 } } },
[40876] = { ["id"] = 40876, ["name"] = "Locke, Stock and Barrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40874, 40875 }, ["description"] = "Well that jes' about wraps up me work 'ere. I'll start packin up an'ead back ta Dalaran. If yeh wouldn't mind, could yeh tell Hobart 'ow things went down 'ere? Maybe leave out tha bits with tha explodin', tha drownin', an' tha gettin captured an' what not. Yer a proper friend, <name>!", ["objectivesText"] = "Return to Hobart in Dalaran and inform him of Flintlocke's work.", ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 22, ["flags"] = 0 } } },
[40879] = { ["id"] = 40879, ["name"] = "It's On With Automatons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 25, ["flags"] = 0 } } },
[40880] = { ["id"] = 40880, ["name"] = "Short Circuit", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 71, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40881 }, ["description"] = "While I've got you here, I was wondering if you could track something down for me. I'm sure you're familiar with a Blingtron, yes? Well, I started askin' around, and it seems no one really knows where the design for it came from. One rumor does pop up more than others, though: Area 52. Interested in a field trip?", ["objectivesText"] = "Find the inventor of Blingtron.", ["rewardItems"] = { 30542, 48933, 127840, 132518, 133975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 26, ["flags"] = 0 } } },
[40881] = { ["id"] = 40881, ["name"] = "Oil Rags to Riches", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40880 }, ["description"] = "Didi will be very interested in reading the journal you found as well as examining the circuit design. You should return to her as soon as you can.", ["objectivesText"] = "Return to Didi the Wrench in Dalaran and show her the items you've found.", ["rewardItems"] = { 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 27, ["flags"] = 0 } } },
[40883] = { ["id"] = 40883, ["name"] = "Fate of the Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "<Thalrenus looks you over.> You are not one of them. The Nightborne came to our gates hours after the shield over Suramar fell. We thought them friends, despite our long separation. We were wrong. They poured into our stronghold and began the slaughter. We were unprepared. Though we fought, we were beaten. The keep is lost. Our leaders have perished and their corpses lay in the streets. Find them, give them their final rites. While you search, look for survivors. Help them if you can.", ["objectivesText"] = "Find the corpses of Nyellus Starweaver , Galar'thus Rivertree , and Kailea Windfeather and perform funereal rites for them. Progress: Are you here to fight the Nightborne?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101766, ["x"] = 0.289, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40890] = { ["id"] = 40890, ["name"] = "The Tears of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 629, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "The Tear of Elune floats effortlessly, glistening in an ethereal pillar of moonlight.", ["objectivesText"] = "Use the central teleporter in Dalaran and then place the Tears of Elune in the Portrait Room.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129985, 129993, 130001, 130012, 139043, 237812, 245739 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40900] = { ["id"] = 40900, ["name"] = "The Burden Borne", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40783, 40784, 40785, 40834, 40835, 40837, 40838, 40900 }, ["series"] = { 40837, 40838 }, ["description"] = "Your assistance against the Dark Riders has proven a great service to the Light. Though our beliefs may separate us, I know that we share one goal. You have allowed me to fill my purpose in returning these artifacts to their rightful owners, and for this I am thankful. As for the Scythe of Elune, I can think of no safer place than in your care. May it serve you well against the Legion, <name>.", ["objectivesText"] = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 210, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 210, ["name"] = "The Scythe of Elune", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40907] = { ["id"] = 40907, ["name"] = "Removing Obstacles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "<class>! Interested in earning some coin? The jarl of Jandvik is missing and two headstrong whelps are vying to take over leadership. I should be the next jarl, not them! I want you to enter Jandvik and defeat Calder and Eynar in mortal combat. I would not normally put my trust in an outsider, but this situation requires the aid of someone like you. Jandvik would condemn me if I were caught with their blood on my hands. Meet me in the center of Jandvik when the deed is done.", ["objectivesText"] = "Kill Calder and Eynar in Jandvik. Progress: Do not underestimate Calder and Eynar .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102309, ["x"] = 0.654, ["y"] = 0.511 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.654, ["y"] = 0.511 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40908] = { ["id"] = 40908, ["name"] = "Jarl Come Back Now", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You seem to follow my commands well, <name>. Perhaps I can use you again. Jarl Throndyr , the leader of Jandvik, has been missing for some time now. I assume that he has fallen in battle to the invading Sashj'tar naga, but I must know for certain. Find out what has become of him. Do this task for me and I can assure you that my vrykul will not harm you.", ["objectivesText"] = "Locate Jarl Throndyr in Azuregale Bay.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99559, ["x"] = 0.69, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40927] = { ["id"] = 40927, ["name"] = "Jandvik's Last Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["series"] = { 41426 }, ["description"] = "Commander Malt'his was conferring with a sea giant? Without your help, this village will surely fall to the combined forces of the Sashj'tar and the sea giants. < Toryl stands there quietly for a moment.> Meet me in an underground cave out in Azuregale Bay. I want to show you something that may turn the tide in this battle.", ["objectivesText"] = "Meet with Toryl in the Sashj'tar Grotto.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99948, ["x"] = 0.705, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102390, ["x"] = 0.76, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40930] = { ["id"] = 40930, ["name"] = "Apocalypse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40931, 40932 }, ["description"] = "<The Lich King's chill voice fills your mind once again> There is an ancient blade, lost in the echoes of time, that has the power to bring my vengeance upon the Legion. It is known as Apocalypse. I've sensed the blade in the possession of the Dark Riders of Deadwind Pass. Their magic conceals them from my sight but they cannot hide from the scourge! They were last seen by my agents near a place called Manor Mistmantle. Go there, <name>. Defeat the Dark Riders, and claim the blade!", ["objectivesText"] = "Start your search for Apocalypse at Manor Mistmantle in Duskwood. Progress: And just why should I help you, <class>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 24107, 24108, 24109, 65685, 65705, 65723, 124124, 128292, 128293, 128402, 128403, 131257, 131702, 136922, 139506, 139673, 139676, 139680, 140517, 140923, 153048, 173527, 237812 }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40931] = { ["id"] = 40931, ["name"] = "Following the Curse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40930, 40932 }, ["description"] = "Very well. I suppose an introduction is in order. I am Revil Kost , priest of the Light and a seeker of lost artifacts. I've dealt with the Dark Riders before, and have returned to rid this place of them. The Riders are elusive, but I may have a clue to their whereabouts. In our previous confrontation, I was able to see a glimpse into their past. Granted blessed vision by the Cloak of Purity, I saw the Dark Riders for who they were before. Come with me to Ariden's camp. I will explain on the way.", ["objectivesText"] = "Escort Revil Kost from Manor Mistmantle in Duskwood to Ariden's Camp in Deadwind Pass.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 100323, ["x"] = 0.774, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 42, 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40932] = { ["id"] = 40932, ["name"] = "Disturbing the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40930, 40931 }, ["description"] = "This place is where the merchant, Ariden, set up camp while he was trying to ply his dubious wares to the sorcerer Medivh. It has remained strangely untouched for all this time, which leads me to believe it may still have a connection to its former owner. Help me search the camp. Let's see if we can find something to lead us to the Dark Riders.", ["objectivesText"] = "Search around Ariden's Camp for clues leading to the Dark Riders.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40933] = { ["id"] = 40933, ["name"] = "A Grisly Task", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40934, 40935 }, ["description"] = "Wet soil? Shallow graves? I think the journal is referring to the gravesites off of the lake near Karazhan. Nobody knows who is buried there, but they may be the key to finding the Dark Riders. You can... speak to the dead, yes?", ["objectivesText"] = "Raise the dead buried in the Sodden Graves in Deadwind Pass until you find one who can point you to the Dark Riders location.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128293, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100729, ["x"] = 0.516667, ["y"] = 0.384667 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.384667 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40934] = { ["id"] = 40934, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40933, 40935 }, ["description"] = "The catacombs? I've never heard of such a place. Unless, he means... There's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse. Progress: Didyou find what you seek, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40935] = { ["id"] = 40935, ["name"] = "The Call of Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 648, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40933, 40934 }, ["description"] = "I was wrong about you, death knight. Your assistance against the Dark Riders has proven a great service to the Light. Perhaps I should not be so quick to judge. Nevertheless, you have allowed me to fill my purpose in returning these artifacts to their rightful owners. As for Apocalypse, I can think of no safer place than in your care. May it serve you well against the Legion, death knight.", ["objectivesText"] = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128293, 128402, 128403, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40938] = { ["id"] = 40938, ["name"] = "The Light and the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "Alonsus Faol has been a valuable ally, and his instincts about you have proven true. I believe you are uniquely suited to assist in a matter that will bring a great force of good into this world. I must take you somewhere far from Azeroth to finish a task my people began long ago. Will you aid us?", ["objectivesText"] = "Aid Velen with his mysterious task. Progress: We have important work to do, <name>.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40949] = { ["id"] = 40949, ["name"] = "Not Their Last Stand", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I've been watching you- you are not with them. <Ivanel coughs quietly.> I am not long for this world, but there is one thing I would have you do while you are here. The hippogryphs here still fight bitterly to defend their home and their companions in the Moon Guard. They have not accepted that the Guard is no more. Please... send them away. Let them know there is nothing left for them to fight for here.", ["objectivesText"] = "Dissuade 5 Lingering Moonfall Hippogryphs Progress: What is it?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106095, ["x"] = 0.296, ["y"] = 0.185 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106182, ["x"] = 0.333, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.296, ["y"] = 0.185 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40950] = { ["id"] = 40950, ["name"] = "Honoring Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40996 }, ["description"] = "All has gone as planned. Your new blades are a testament to that. We will demand a great deal of you in the weeks and months to come, as we must. But we would be remiss if we failed to take a moment to celebrate a job well done. What do you say?", ["objectivesText"] = "Celebrate the successful acquistion of your artifact with your fellow Shadows. Progress: It's kill or be killed.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128479, 128870, 128872, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40952] = { ["id"] = 40952, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40953, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "Now that you wield Thas'dorah, it's time to learn more about the night elf who set you on this journey I suggest returning to the Hunter's Reach shop where you met my courier. Whoever this Emmarel Shadewarden is, it seems she has some part to play in the war against the Legion.", ["objectivesText"] = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden .", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 237812, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40953] = { ["id"] = 40953, ["name"] = "On Eagle's Wings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40954, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "Since ancient times, my order has stood vigil on these Broken Isles, watching for the Legion's return. Only a handful of us remain... but that changes today. The artifact you hold is more than a weapon. It is a symbol that will unite hunters of all kingdoms and creeds. I'm sure you have questions. Meet me at the Trueshot Lodge in Highmountain and see with your own eyes what awaits us. Snowfeather and I will make our own way there.", ["objectivesText"] = "Meet Emmarel Shadewarden at Trueshot Lodge in Highmountain.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102578, ["x"] = 0.3976, ["y"] = 0.257 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.3976, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40954] = { ["id"] = 40954, ["name"] = "The Unseen Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40955, 40958, 40959, 41008, 41009 }, ["description"] = "For a thousand years, the Unseen Path has watched and waited. We remained few in number, quietly acting behind the scenes when Azeroth needed us. Only a select few even knew our group existed. But the time for lingering in the shadows is over. Before we begin our work, you should hear more about the Unseen Path.", ["objectivesText"] = "Hear Emmarel's tale.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 21401, 21402, 21403, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102578, ["x"] = 0.3976, ["y"] = 0.257 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.3976, ["y"] = 0.257 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40955] = { ["id"] = 40955, ["name"] = "Oath of Service", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40958, 40959, 41008, 41009 }, ["description"] = "Assembled before you are many of our world's greatest archers, rangers, beast masters, and trappers, ready to fight the Legion as one. It is time to take your first step in becoming a true leader of hunters. We gather at the fire pit and take our oaths of service before the statue of Ohn'ahra. Touch the statue and kneel before it while I recite the oath, and the Unseen Path will be reborn!", ["objectivesText"] = "Kneel before the eagle statue and pledge your service to the Unseen Path. Progress: Ohn'ahra has blessed our order!", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.43725, ["y"] = 0.25275 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40956] = { ["id"] = 40956, ["name"] = "Survey Says...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "It is time to establish the first secure connection in our teleportation network. Take this beacon to the Ruins of Elune'eth above us and survey the area to find a suitable location. Once your survey is complete, place the beacon and I will anchor a connection to it from here.", ["objectivesText"] = "Use the Telemancy Beacon to survey the Ruins of Elune'eth.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 133897, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 5, ["flags"] = 0 } } },
