[40958] = { ["id"] = 40958, ["name"] = "Tactical Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40959, 41008, 41009 }, ["description"] = "Now that your artifact is ready, it's time to plan your first strike against the Legion. Speak to Tactician Tinderfell , our expert on such matters.", ["objectivesText"] = "Speak to Tactician Tinderfell in the Trueshot Lodge .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102574, ["x"] = 0.43725, ["y"] = 0.25275 }, { ["mapID"] = 739, ["npcID"] = 102940, ["x"] = 0.476333, ["y"] = 0.530333 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.43725, ["y"] = 0.25275 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40959] = { ["id"] = 40959, ["name"] = "The Campaign Begins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 41008, 41009 }, ["description"] = "The Legion believes we are still reeling from our loss on the Broken Shore. Let's prove them wrong. Our scouts have mapped out the Broken Isles, learning everything we can about each region for our imminent assault. Choose where to strike first, and you will lead the Unseen Path's efforts personally.", ["objectivesText"] = "Choose an initial assault point on the Command Map", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40960] = { ["id"] = 40960, ["name"] = "Luminous Pearl", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40960 }, ["series"] = { 40961 }, ["description"] = "Balanced upon your fishing hook, you find a pearl unlike any other you've seen before. It shines with a cold, steady light, and its size and weight fluctuate in your hand. This is clearly a magical item, and should be brought to a magical person.", ["objectivesText"] = "Bring the Luminous Pearl to Archmage Khadgar in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124111, 124112, 133755, 133887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 133887 } },
[40961] = { ["id"] = 40961, ["name"] = "The Dalaran Fountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40961 }, ["series"] = { 40960 }, ["description"] = "You fished this up, did you? I'm... not quite sure what you want ME to do about that. Here. <Khadgar pats you on the head.> \"Good job.\" With regard to the pearl... it does seem to be magical, but I couldn't tell you much more than that. Perhaps it might look nice in the Dalaran fountain?", ["objectivesText"] = "Bring the Luminous Pearl to the fountain in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 7909, 21228, 43512, 133939 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[40963] = { ["id"] = 40963, ["name"] = "Take Them in Claw", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "We should have seen this coming. My sister is dead, my friends are wounded and we will likely die here. I want revenge. <Lyrea hands you a vial full of growing green liquid.> We cannot beat them, but we can turn the Stronghold against them. Wild hippogryphs are attracted to the scent in this bottle. Wild hippogryphs are also notoriously violent when the object of their attraction is not a hippogryph. Use it to clear a path deeper into the stronghold.", ["objectivesText"] = "Attract 3 Wild Moonfall Hippogryphs to deal with the Nightborne at Moonfall Roost. Progress: I thought I was alone here. Are you here to continue the fight?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139882, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40964] = { ["id"] = 40964, ["name"] = "The Rift Between", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I was with Lothrius when the Nightborne poured into the stronghold. He and his constructs managed to get the majority of us out of the Athenaeum, but he was cornered before he could make good on his own escape. I know he still lives- I feel it in my gut!- but I cannot go back for him myself. My injuries are too severe. Beakbuck will take you to where we last saw Lothrius. Simply let him know when you are ready to leave. Go quickly, and good luck!", ["objectivesText"] = "Locate Lothrius Mooncaller in the Athenaeum.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 689, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40965] = { ["id"] = 40965, ["name"] = "Lay Waste, Lay Mines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "They ransacked my library, <name>. If they want our knowledge, we will give it to them. This piece of rune work will allow you to cast an ensnaring spell on the ground. When the Nightborne cross the threshold they will see the true might of the Moon Guard. Teach them well!", ["objectivesText"] = "Slay 50 Nightborne With the Trap Rune . Progress: How fares the education?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133882, 138781, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40968] = { ["id"] = 40968, ["name"] = "Recovering Stolen Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40968 }, ["series"] = { 41108, 41109, 41110 }, ["description"] = "My injuries will not kill me, but I cannot fight. I have my own idea of how to deal with the remaining Nightborne. They destroyed our defense matrix as soon as they arrived. Surely one of them carries the spell focus necessary to reactivate it. Find it, then go to a hippogryph. They linger throughout the Stronghold. These loyal beasts will take you to the skies and take care of the rest.", ["objectivesText"] = "Acquire a Volatile Spell Focus .", ["rewardItems"] = { 133882, 133956, 133957, 140241, 140242, 140329, 141671, 141943, 142054 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102425, ["x"] = 0.314, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40969] = { ["id"] = 40969, ["name"] = "Starweaver's Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I will take these tomes to Thalrenus. There is one thing that weighs heavily on my mind, and I would like for you to attend to it in my stead. My wife and life partner, Syrana Starweaver , resides in the Starweaver's Sanctum across the bridge. It fell shortly after the Nightborne entered the Stronghold. If she still lives she will need to know of our efforts. Her power is sorely needed. Give her my best- I will be along shortly.", ["objectivesText"] = "Locate Syrana Starweaver", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 8, ["flags"] = 0 } } },
[40971] = { ["id"] = 40971, ["name"] = "Overwhelming Distraction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "Do you see the Nightborne outside this room? They hold us here, like mice in a cage. It is more convenient for them that we are pinned down while they search the Sanctum for my father's relics. My companions and I can escape to higher ground with some help. Take this crystal. While standing on a mana focusing rune, use it to overcharge a Conjurer. Their summons will turn on them and create an opening. Use it well, and we will meet you atop the stronghold when the way is clear.", ["objectivesText"] = "Overcharge 3 Imperial Conjurers using the Inert Crystal . You must be standing on a Mana Focuser to use the crystal.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133999, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.309 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40972] = { ["id"] = 40972, ["name"] = "Last Stand of the Moon Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "This is all that remains of the Moon Guard. Take a good look. We are but a shadow of our former selves, and we have the Nightborne to thank for our demise. For now there is nothing more we can do. If we want to live, we must leave immediately. Retribution can wait.", ["objectivesText"] = "Leave Moon Guard Stronghold with Thalrenus, Lothrius, and Syrana.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054, 237812, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101766, ["x"] = 0.289, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.289, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 11, ["flags"] = 0 } } },
[40976] = { ["id"] = 40976, ["name"] = "Audience with the Warchief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Tensions are running high, demon hunter. Warchief Vol'jin was gravely wounded in a disastrous assault on the Broken Shore. I suggest you offer your skills in service of the Horde before your presence is... misinterpreted. High Overlord Saurfang commands the city's defenses. Though wary of the Illidari, I believe he will give you a chance to prove your worth. Speak to him and request passage into Grommash Hold.", ["objectivesText"] = "Speak to High Overlord Saurfang.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 97296, ["x"] = 0.725, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1, 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40982] = { ["id"] = 40982, ["name"] = "Second Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Sylvanas becoming Warchief may be problematic. In life she was a proud ranger, known to many in our ranks. But since the Scourge took her, some of her own allies do not trust the Banshee Queen. The Legion will strike at the first hint of dissension. Even now, I sense something amiss, <name>. I fear that not all is as it seems. Quickly, use your Spectral Sight. We must know if there are foes among us!", ["objectivesText"] = "Use your Spectral Sight. Progress: Time is precious.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40983] = { ["id"] = 40983, ["name"] = "Demons Among Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is just as we suspected, <name>! The demons thought they could take us by surprise. Quickly, to arms! Protect the Banshee Queen!", ["objectivesText"] = "Protect the Warchief. Progress: This is what we were born for.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 100873, ["x"] = 0.458, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40986] = { ["id"] = 40986, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40987 }, ["description"] = "The catacombs? I've never heard of such a place. Unless, he means... There's a sewer grate along the edge of the river leading to a catacombs underneath Karazhan. I've never paid it much attention, but it could lead to the catacombs that the spirit spoke of. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Apocalypse. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40987] = { ["id"] = 40987, ["name"] = "The Call of Vengeance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 648, ["storyline"] = { 40930, 40931, 40932, 40933, 40934, 40935, 40986, 40987 }, ["series"] = { 40986 }, ["description"] = "Our goals have been met, death knight, and it is time we part ways. I think I will be glad to see the last of you. Go on, return to your dark masters. We are done here.", ["objectivesText"] = "Take the Death Gate to the Frozen Throne, and receive the Mark of the Lich King .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 209, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 209, ["name"] = "Apocalypse", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40996] = { ["id"] = 40996, ["name"] = "Delegation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 40950 }, ["description"] = "If I might impart some advice to aid you on the trials and tribulations ahead: do not hesitate to use the many resources of the Uncrowned to aid your efforts. There is a communal board in the tavern beyond this chamber where we organize the efforts of our underlings. Seek out Nikki by the board - she can show you the ropes.", ["objectivesText"] = "Speak to Nikki the Gossip .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40997] = { ["id"] = 40997, ["name"] = "Lethal Efficiency", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["description"] = "Word is you're headin' down to the Broken Isles. That true? Soon as news got out about the place, we combed through every book, tome, and paper we could get our hands on. We put together quite the report! You should take a look. While you're here, this board is where the magic of the Uncrowned happens. You can put a bounty on a king's head, offer a reward for felsilk cloth... just jot down your latest whim and your agents will take care of it.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41001] = { ["id"] = 41001, ["name"] = "Shatter the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41001, 41499 }, ["description"] = "The Sashj'tar forces may have dwindled, but the Tidemistress has surrounded herself with her fiercest naga. This is the time to strike a final crushing blow against the Sashj'tar. If we can defeat them now, we may finally break the back of this menace and save Jandvik.", ["objectivesText"] = "Kill 12 Sashj'tar naga in the Sashj'tar Ruins. Progress: We must defeat the Sashj'tar once and for all.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5813, ["name"] = "Brandolf", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41002] = { ["id"] = 41002, ["name"] = "A Weapon of the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40976, 40982, 40983, 41002, 44092 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It would seem I underestimated your initial value. We will have need of your kind in the coming war. I plan to hunt these demons to the ends of Azeroth, and your kind will be the arrow I shall loose upon them. Tell your Illidari within Orgrimmar to make ready to serve the Horde. But make no mistake, your kind once served the Betrayer. Betray me, and there is no world you can run to that will save you from my vengeance.", ["objectivesText"] = "Report to Elthyn Da'rai at the Illidari camp in Orgrimmar .", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 101035, ["x"] = 0.456, ["y"] = 0.158 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 261, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41003] = { ["id"] = 41003, ["name"] = "The Emperor's Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41003 }, ["description"] = "Ah, Sheilun , the legendary staff wielded by our last emperor. If the Legion were to acquire this weapon, they could unleash untold horrors across the whole of the continent. They must be stopped! If you want to get to the Terrace as fast as possible, you should hitch a ride directly to the mainland. Tak-Tak , a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", ["objectivesText"] = "Retrieve Sheilun , Staff of the Mists, from the Terrace of Eternal Spring. See Tak-Tak to fly directly to the Terrace. Progress: The Terrace of Eternal Spring is a very sacred place for mainland Pandaren. I hope you were able to preserve it from corruption. Enough of Pandaria was destroyed when Garrosh Hellscream turned it into a battlefield.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 129079, 133948, 140551, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 246, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 246, ["name"] = "Staff of the Mists", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41008] = { ["id"] = 41008, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41009 }, ["description"] = "I sense the threads of fate entwined about you. Your destiny is tied to that of the ancient night elf who started you on this journey. I can send you back to the city in the sky. From there, you must begin the task of gathering allies against the ravenous darkness. Fight well, <name>. May Talonclaw serve you well.", ["objectivesText"] = "Return to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden.", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 237812, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41009] = { ["id"] = 41009, ["name"] = "Hunter to Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 40400, 40402, 40403, 40419, 40952, 40953, 40954, 40955, 40958, 40959, 41008 }, ["description"] = "Now that Titanstrike is yours, ye should learn more about the night elf who set us on this journey. She might well be back at the Hunter's Reach shop where you met her. Whoever this Emmarel Shadewarden is, I'd bet me beard she has some part to play in the war against the Legion! Thanks again fer the fun, <name>. If ye ever have need of me, just call!", ["objectivesText"] = "Go to the Hunter's Reach shop in Dalaran and speak to Emmarel Shadewarden .", ["rewardGold"] = 315000, ["rewardXP"] = 175, ["rewardItems"] = { 17687, 38741, 39040, 39066, 39108, 39330, 39373, 39428, 39448, 61124, 61125, 61126, 61127, 116394, 121802, 131202, 139902, 139932, 139962, 140002, 155383, 159038, 159039, 159040, 159041, 184373, 184374, 237812, 246492, 260472, 260473, 260474, 260476, 260477, 260478, 260479, 260481, 260482, 260483 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41010] = { ["id"] = 41010, ["name"] = "Fish Frenzy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 41010 }, ["description"] = "<name>! <pant, pant> You've got to see it! The fish, they're... they're everywhere! Off the coast of Val'sharah, something's whipping them up into a frenzy. I've never seen better fishing in my life! I've got a boat down below. Grab your pole and I'll take you there!", ["objectivesText"] = "Follow Nat Pagle to the Gloaming Reef, then dispatch all of the fish in the area.", ["rewardXP"] = 1415, ["rewardItems"] = { 133723, 133755, 133887, 138777, 227669 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[41019] = { ["id"] = 41019, ["name"] = "Actions on Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "Let me show you the Command Map. Thanks to some draenei construction and naaru magic we now have a window into the Broken Isles! You can devise strategy, send your agents on missions, and choose our first area to operate in. Take a look and let me know where we are going!", ["objectivesText"] = "Use the Command Map to select your order's first operational area.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41028] = { ["id"] = 41028, ["name"] = "Power Grid", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["series"] = { 40010 }, ["description"] = "This station has fallen into disrepair. The circuit is broken, and to mend it we must recharge the seals in the central chamber. Both a high potency current and low potency current are needed for each seal. Direct the currents to point at the same seal, then engage the seal. Me? I shall supervise. You are the help, after all.", ["objectivesText"] = "Charge the Moon Seal, Star Seal, Beast Seal and Elven Seal in Ley Station: Tel'Anor.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141934, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.4348 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41032] = { ["id"] = 41032, ["name"] = "Stop the Spell Seekers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "The Nightborne are here in force. As if that were not worrying enough, they now bring reinforcements. I have seen them opening large portals to Suramar . Through these portals they have called in their constructs. They are immune to much of my magic and so represent something of a stumbling block to rejoining the others. Find the portals and close as many as you can. That should buy us some time.", ["objectivesText"] = "Close 3 Spell Seeker Portals . Progress: I can still sense them, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133882, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41033] = { ["id"] = 41033, ["name"] = "Return to Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The gateway is fully functional, <name>. Ooh, I am positively tingling with excitement! Do let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time. You will be joining us aboard, won't you?", ["objectivesText"] = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41035] = { ["id"] = 41035, ["name"] = "Felstorm's Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41036, 41085 }, ["description"] = "You may not know me, but I need your help, <name>. Meet me in the Violet Gate and I'll explain everything. Make haste. I fear we have little time.", ["objectivesText"] = "Meet Meryl Felstorm in the Violet Gate in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41036] = { ["id"] = 41036, ["name"] = "The Dreadlord's Prize", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41035, 41085 }, ["description"] = "Kathra'natir escaped my grasp, but I know what his next step will be. He seeks an ancient relic called the Forge of the Guardian, used for centuries by the Council of Tirisfal to infuse their power into the Guardian. The forge was hidden away, its location known only to the Council themselves. Now the dreadlord has this knowledge. We must go to the Violet Hold. I only hope we are not too late.", ["objectivesText"] = "Defeat Kathra'natir in Violet Hold. Progress: We must hurry!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41037] = { ["id"] = 41037, ["name"] = "Unbridled Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord. Thankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", ["objectivesText"] = "Activate the Fel Hammer and rally your Illidari forces. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41038] = { ["id"] = 41038, ["name"] = "The Mead Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 634, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 41039 }, ["description"] = "The Storm Brew is created by a legendary vrykul brewmaster named Melba. Here is the location of her meadery along the northern Stormheim coast. If we can convince her to share her secret recipe with us, we will gain a significant advantage over the enemy. Grandmaster, how are your skills of persuasion?", ["objectivesText"] = "Speak to Aegira in Stormheim. Progress: What do you seek?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102843, ["x"] = 0.626, ["y"] = 0.2095 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.2095 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41039] = { ["id"] = 41039, ["name"] = "Stolen Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 41038 }, ["description"] = "Morjirn, the head brewer of the Tideskorn clan, has the Storm Brew recipe . I have never been strong enough to assault his fortress alone, but together with you, I think we can claim retribution for my fallen master. I would like nothing better than to pry the recipe from Morjirn's cold, dead fingers. While we are there, we will sample his Storm Brew. I'd like to see if his brewing skills are even near my master's.", ["objectivesText"] = "Taste the Sour Storm Brew, Weak Storm Brew, Blazing Storm Brew, and kill Morjirn for the Storm Brew Recipe . Progress: Do you have the recipe?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133995, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102843, ["x"] = 0.626, ["y"] = 0.2095 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.2095 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41040] = { ["id"] = 41040, ["name"] = "Halls of Valor: The Brewmaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 704, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41059, 41087 }, ["description"] = "I've made a new breakthrough with Melba 's Storm Brew recipe. We need the use of a special cauldron, one owned by Odyn himself. This cauldron is located in none other than the Halls of Valor. There is only one way to enter this exalted place, and that is through the storm god's favor. You must find a way to enter the hall of warriors. You may require allies for this endeavor, <name>.", ["objectivesText"] = "Speak to Melba in the Halls of Valor.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7672 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1477, ["db2PoiUiMapID"] = 704, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41052] = { ["id"] = 41052, ["name"] = "A Desperate Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611 }, ["series"] = { 38904, 39654, 42814, 42815 }, ["description"] = "<name>, Saurfang has not been the same since our loss at the Broken Shore. Though he led well and slew many, he has taken our defeat hard. I fear he is determined to return to the Broken Shore. Will you speak to him?", ["objectivesText"] = "Meet with High Overlord Saurfang at Krasus' Landing. Progress: Will you help?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41054] = { ["id"] = 41054, ["name"] = "Love Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "Malfurion, my love... In vision I saw him, enraged and then distressed, and now lost beyond my mind's reach. <race>, I know we have little reason to trust one another, but I will not turn away your help. If you value the sanctity of this world, you will come with me.", ["objectivesText"] = "Speak with Tyrande Whisperwind at Starsong Refuge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102938, ["x"] = 0.674, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41056] = { ["id"] = 41056, ["name"] = "Love Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "Malfurion, my love... In vision I saw him, enraged and then distressed, and now lost beyond my mind's reach. He is strong, but the horrors that have befallen this land are all-consuming. I must find him, and you must help me! Gather your wits, <race>, and follow me.", ["objectivesText"] = "Speak to Tyrande Whisperwind at Starsong Refuge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102938, ["x"] = 0.674, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41059] = { ["id"] = 41059, ["name"] = "Halls of Valor: Odyn's Cauldron", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7672, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41040, 41087 }, ["description"] = "Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge. With you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn's Cauldron , which can be found in the great hall just ahead. You have my blessing to borrow it. Good luck in your journey ahead, <name>.", ["objectivesText"] = "Collect Odyn's Cauldron from the Halls of Valor, then pass Odyn 's trial. Progress: Did you pass the trials?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134005, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7672 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41060] = { ["id"] = 41060, ["name"] = "Unbridled Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord. Thankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", ["objectivesText"] = "Activate the Fel Hammer and rally your Illidari forces. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41062] = { ["id"] = 41062, ["name"] = "Spoils of Victory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest. Battlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.", ["objectivesText"] = "Have Battlelord Gaardoun show you what your forces obtained.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41066] = { ["id"] = 41066, ["name"] = "The Hunter's Gaze", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<name>, before you lies your nether crucible - more powerful than any we've crafted before. The souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth. What we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.", ["objectivesText"] = "Use the Empowered Nether Crucible to gaze upon the Burning Legion's forces in Azeroth. Progress: The Legion threat is more dire than we thought.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41067] = { ["id"] = 41067, ["name"] = "Time is of the Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "As you can see, there is little time to spare - the Legion's armies already encroach on our world. Kayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", ["objectivesText"] = "Speak to Kayn Sunfury .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 13, ["flags"] = 0 } } },
[41069] = { ["id"] = 41069, ["name"] = "Direct Our Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease. Until then, we must do what we can on the ground to alleviate their foothold before it grows further. This citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault. I think you would agree that none would be better suited to lead our charge than you.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 15, ["flags"] = 0 } } },
[41070] = { ["id"] = 41070, ["name"] = "Spoils of Victory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "In conquering this citadel we obtained something that I think would be of great use to you. Gaardoun's men have it well-guarded just below - I suggest you have him show you.", ["objectivesText"] = "Have Battlelord Gaardoun show you what your forces obtained.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41085] = { ["id"] = 41085, ["name"] = "A Mage's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41035, 41036 }, ["description"] = "It is decided, then. The foundation of the Tirisgarde's strength lies in the ancient artifacts wielded by its champions. Your first task will be to retrieve one such artifact. The master appendix of this library lists every artifact known to the Council of Tirisfal. There should be a few choices in there worth looking into. I will leave it to you to choose which to pursue.", ["objectivesText"] = "Use the Appendix of Azerothian Artifacts to choose an artifact to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41086] = { ["id"] = 41086, ["name"] = "A Peaceful World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "Word has reached us that the Legion is advancing on the Broken Isles. They beset us from all sides, and if we do not stand strong, they will spill over into the rest of Azeroth. <name>, we need your help more than ever. Lend your strength to those defending at the front. We cannot fail here.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41087] = { ["id"] = 41087, ["name"] = "Storm Brew", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["series"] = { 32442, 41040, 41059 }, ["description"] = "Grandmaster, the Legion is attacking the Wandering Isle! We sent defenders up to the Ridge of Laughing Winds, but they can't hold for long. Our only chance is to finish making the Storm Brew. Chen and Aegira have already gone up to the Chamber of Whispers, but they are under heavy attack as well. Speak to Tak Tak and take a kite up to join them at once!", ["objectivesText"] = "Take Tak-Tak's kite to the Ridge of Laughing Winds, help Chen Stormstout & Aegira make the Storm Brew, and defeat the Burning Legion's forces.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139731, 142060, 142061, 142062, 142064, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41096] = { ["id"] = 41096, ["name"] = "Time is of the Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "As you can see, there is little time to spare - the Legion's armies already encroach on our world. Altruis has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", ["objectivesText"] = "Speak to Altruis the Sufferer .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 14, ["flags"] = 0 } } },
[41099] = { ["id"] = 41099, ["name"] = "Direct Our Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The Tomb of Sargeras is the Legion's primary entrance into our world - it must be destroyed. No easy task, but until we have the means to do so we must do what we can to stop their invasion. The Legion used this citadel to spearhead invasions on other worlds - we can use its navigation systems to plan our own assault against them. You, of course, must take the honor of first breaking ground on their territory, but we will soon follow.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 16, ["flags"] = 0 } } },
[41105] = { ["id"] = 41105, ["name"] = "The Sword of Kings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 41105 }, ["description"] = "The first king of the humans, Thoradin, performed many acts of heroism and valor. While on a personal quest near the end of his reign, he stumbled upon the tomb of my brother Tyr... and the grave-prison of the monstrosity he died fighting. Thoradin unintentionally awoke the beast and gave his life to keep it from escaping. It is Thoradin's sword, Strom'kar, that has kept the monster at bay. Retrieve it and finish what Tyr and Thoradin started. Kill Zakajz the Corrupted.", ["objectivesText"] = "Find Strom'kar, the Warbreaker and deal with Zakajz. Progress: Ah, you have returned...", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 216, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 216, ["name"] = "The Sword of Kings", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41106] = { ["id"] = 41106, ["name"] = "Call of the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40643, 40644, 40645, 40646 }, ["description"] = "Beating the Legion requires us to strike quickly and unexpectedly. We have discovered a Dreamway by which we can travel through the Emerald Dream itself. Though only a short walk through the Dream, it will allow us to cross vast distances on Azeroth and even access the ancient home of all druids, Val'sharah. Malfurion is preparing the ritual to open the Dreamway. I need you to summon Zen'tabra and Naralex to his side. Only by combining our efforts can we hope to succeed.", ["objectivesText"] = "Locate Zen'tabra and Naralex , and direct them to the ritual site. Progress: This ritual must succeed, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 101064, ["x"] = 0.562, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41108] = { ["id"] = 41108, ["name"] = "Rain Death Upon Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41108 }, ["series"] = { 40968, 41109, 41110 }, ["description"] = "Aboard the hippogryph you now possess a unique opportunity. It is time for the Nightborne to regret letting you live.", ["objectivesText"] = "Slay 50 Nightborne.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140241, 140242, 140329, 141671, 141943, 142054 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41109] = { ["id"] = 41109, ["name"] = "Waiting for Revenge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 41109 }, ["series"] = { 40968, 41108, 41110 }, ["description"] = "The Volatile Spell Focus hums with energy as you hold it. Handle with care! Only with this item in your possession will the Hippogryphs allow themselves to be mounted.", ["objectivesText"] = "Mount a Hippogryph.", ["rewardItems"] = { 133956, 140241, 140242, 140329, 141671, 141943, 142054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41112] = { ["id"] = 41112, ["name"] = "The Great Akazamzarak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41113 }, ["description"] = "There is a goblin who is a master of portals and teleportation by the name of Akazamzarak. His talents have gone mostly unnoticed, however, since he mostly uses them for chicanery. He is, what you would call, a street performer. Fortunately for us, he is performing in the streets of Dalaran, grifting coins from the unenlightened masses. Take this bag of gold. See if you can convince him to change vocations.", ["objectivesText"] = "Place the Sizeable Pouch of Gold in Akazamzarak's tip bucket .", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 127857, 128820, 128862, 134060, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41113] = { ["id"] = 41113, ["name"] = "The Only Way to Travel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41112 }, ["description"] = "Portals? Teleportation? You bet I can help you out with that! I mean, how do you think I pull the rabbit out of... ...um, you didn't hear that. Anyway, I can help you move your mages around, if the price is right. Heck I can even teach those combat mages a thing or two. Ever been on the receiving end of an exploding bunny? It ain't pretty! For starters, let me whip up a portal to take us to this hall you're talking about.", ["objectivesText"] = "Return to Meryl Felstorm in the Hall of the Guardian .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 116395, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41114] = { ["id"] = 41114, ["name"] = "The Champion's Return", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["description"] = "I can sense the power of the artifact you hold. It will do well against the Legion as it is, but we have the ability to unlock its power even further. You must return to the Hall of the Guardian. You can use the incantation I taught you before to pass through the runes.", ["objectivesText"] = "Teleport to the Hall of the Guardian and return to Meryl Felstorm .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128862, 134058, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41115] = { ["id"] = 41115, ["name"] = "Champion: Chen Stormstout", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 23, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 23, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41119] = { ["id"] = 41119, ["name"] = "The Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "You must lead this hunt, <name> - a small force will join you to ensure Varedis meets his end. You must try to make it into Varedis' hold undetected; the less time you spend in Legion territory the better. Meet at Krasus' Landing when you are prepared to leave.", ["objectivesText"] = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41120] = { ["id"] = 41120, ["name"] = "Making Arrangements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "Do you remember Varedis? He was once our lead trainer at the Black Temple, but fell early in the siege. ...or so we thought. Kor'vas spotted the traitor amongst the Legion wielding glaives imbued with power unlike anything she'd ever seen. The Kirin Tor have an eredar lord interred in the Violet Hold that will know where Varedis' base of operations is. The hold's warden has agreed to consider granting us access to him. <Altruis smirks.> Time to play the friendly diplomat.", ["objectivesText"] = "Meet Altruis the Sufferer outside the Violet Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41121] = { ["id"] = 41121, ["name"] = "By Any Means", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7777, ["mapID"] = 723, ["storyline"] = { 39051, 39247, 40819, 41119, 41120, 41121 }, ["description"] = "We need to find out Varedis' location from the eredar inside this prison - the kind warden and his men here are all that stand in our way. We'll take them on together if need be - whatever it takes.", ["objectivesText"] = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis. Progress: Well done.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 53265, 53267, 53292, 62178, 62179, 62180, 127830, 128832, 131398, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7777 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 159, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1494, ["db2PoiUiMapID"] = 723, ["questLines"] = { { ["id"] = 159, ["name"] = "The Twinblades of the Deceiver", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41124] = { ["id"] = 41124, ["name"] = "The Tirisgarde Reborn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41141 }, ["description"] = "The Tirisgarde is reformed. It is time we begin our mission in earnest. The order will need leaders, and though I may be an experienced mage, I am no strategist. You have proven yourself capable, in both your past exploits and present. Will you take on this challenge, <name>?", ["objectivesText"] = "Receive your new title from Meryl Felstorm .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41138] = { ["id"] = 41138, ["name"] = "Feeding Shal'Aran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40010, 41028, 41138 }, ["description"] = "With leyline energy feeding in from Anora, this chamber can begin to awaken. It will be a slow process, and we must take care to mask this activity from our enemies, a process which itself requires enormous effort and focus. Furthermore, there is the conundrum of actually consuming the mana in this form. A stream too weak is not enough to provide sustenance - too powerful and it would vaporize us. There is much work to be done yet. For now, let us examine the feed.", ["objectivesText"] = "Examine the Leyline Feed in Shal'Aran with Arcanist Valtrois .", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102600, ["x"] = 0.39, ["y"] = 0.4348 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.4348 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 155, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 155, ["name"] = "Feeding Shal'Aran", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41141] = { ["id"] = 41141, ["name"] = "A Conjuror's Duty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 41124 }, ["description"] = "I don't know about you but I'm ready to get this show on the road. This place is nice and all, but it's a bit stuffy. I'll see what I can do to get some more mages in this group of yours. You go ahead and check the map over there. It'll help you plan your first moves.", ["objectivesText"] = "Use the Scouting Map to choose your first zone.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41149] = { ["id"] = 41149, ["name"] = "A Re-Warding Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["description"] = "<This small device of elegant nightborne design crackles gently with arcane power. Kel'danath's notes mention wards that keep the withered at bay. It seems he found some form of spellcasting that does not tempt their ravenous appetite for magic. These may prove useful in your search for the missing arcanist.>", ["objectivesText"] = "Activate 4 Arcane Wards in Ambervale.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 136269, 140349, 141668, 142054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41155] = { ["id"] = 41155, ["name"] = "The Dark Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41156, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us. To think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", ["objectivesText"] = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh. Progress: Did you find what you seek, <class>?", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 100812, ["x"] = 0.482, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41156] = { ["id"] = 41156, ["name"] = "The Power Possessed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10638, ["mapID"] = 627, ["storyline"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 41155, 41156 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 42125, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Our goals have been met, warlock, and it is time we part ways. I think I will be glad to see the last of you. Go on, return to your dark masters. We are done here.", ["objectivesText"] = "Return to Calydus in The Underbelly in Dalaran.", ["rewardGold"] = 33100, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 208, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 208, ["name"] = "Ulthalesh, the Deadwind Harvester", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41197] = { ["id"] = 41197, ["name"] = "You've Got to Be Kitten Me Right Meow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "While you were dealing with the stray Owlkitten, I took a look around. It seems these curious creatures have a habit of escaping their parents' watchful eyes - some are trapped across the road by a wandering Ettin. He appears to have been... ahem... eating them. We can earn Yowlon's blessing by bringing his children home.", ["objectivesText"] = "\"Herd\" 7 Lost Feathermane Kittens back home. Progress: Have you managed to rescue any?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 137179, 139791, 140240, 140251, 141941, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41215] = { ["id"] = 41215, ["name"] = "They Become The Hunted", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["description"] = "The trapper you slew was but one of many. The Nightborne are subjugating the local creatures, creating a sort of pleasurable exhibit. I think we can strike them in two places at once. Descend upon these trappers, <race>. Let us teach them a lesson in respecting their prey.", ["objectivesText"] = "Slay 6 Nightborne Trappers . Progress: With the number of trappers thinned, their ability to scout into Suramar will be sorely hampered.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106897, ["x"] = 0.456667, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106897, ["x"] = 0.456667, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.456667, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41216] = { ["id"] = 41216, ["name"] = "Survival of the Fittest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["description"] = "The collar you took from the trapper is simple, but effective. Affixing the collar to a target will make them complacent and obedient to their Nightborne masters. Lilryia was able to reverse the spell using the traps you found. The magics in the collar can now be used to cancel out the other collars. How about giving the Nightborne a reminder that nature always finds a way?", ["objectivesText"] = "Free 12 exhibits from the Menagerie.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 134119, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110987, ["x"] = 0.506, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41220] = { ["id"] = 41220, ["name"] = "Down to Azsuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["series"] = { 39718 }, ["description"] = "<name>, we must find a way to reseal the Tomb of Sargeras. I have uncovered information concerning an ancient relic, which might be the key to stopping the Legion. Our search begins on the ancient elven island of Azsuna . Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin. The Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin. Ready to take wing?", ["objectivesText"] = "Speak with Archmage Khadgar to fly down to Azsuna . Progress: It would seem that we have arrived at the crucial moment.", ["rewardXP"] = 1415, ["rewardItems"] = { 22589, 109076, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93326, ["x"] = 0.435, ["y"] = 0.434 }, { ["mapID"] = 630, ["npcID"] = 93337, ["x"] = 0.45, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41221] = { ["id"] = 41221, ["name"] = "Return to Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "The gateway is fully functional, <name>. Ooh, I am positively tingling with excitement! Do let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time. You will be joining us aboard, won't you?", ["objectivesText"] = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41230] = { ["id"] = 41230, ["name"] = "Trapping Evolved", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 40617 }, ["description"] = "The Nightborne are using magic for everything, even trapping. Nighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. Bring me their traps so that I may study their make.", ["objectivesText"] = "Collect 4 Arcane Traps for Lilryia. Progress: Do you have the snares, <race>?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 134128, 139791, 140240, 140251, 141670, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41231] = { ["id"] = 41231, ["name"] = "Apex Predator", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 43582 }, ["description"] = "I have good news and bad news, <race>. The bad news is that they somehow managed to capture and train a Devilsaur. The good news is that it doesn't seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.", ["objectivesText"] = "Find and slay the Nightborne keeping Su'esh obedient. Progress: Did you find the alpha?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41255] = { ["id"] = 41255, ["name"] = "Sowing The Seed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "Your weapon is ancient and powerful but it holds the potential to be so much more. Take this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root. With its power both it and your weapon will be far more than they are alone.", ["objectivesText"] = "Plant the Seed of Ages in the Soft Soil within The Dreamgrove.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 134550, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41332] = { ["id"] = 41332, ["name"] = "Ascending The Circle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 40652, 40653 }, ["description"] = "Now, you are more powerful than ever! Truly, you are a druid without equal, <name>. I sense that Malfurion has arrived. He will certainly want to know of your accomplishments, but first, please walk with me a moment.", ["objectivesText"] = "Accompany Archdruid Greathoof and then speak with Malfurion Stormrage . Progress: Yes?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41335] = { ["id"] = 41335, ["name"] = "The Elements Call...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 207, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 39746 }, ["description"] = "Nobundo is right. Conventional tactics will not work against the Legion - the Broken Shore taught us that. We must scour the world for weapons to use against the Legion! The Doomhammer is missing and must be recovered. Rehgar and Erunak have some other ideas, as well. Whatever our course, we must act immediately. Speak with me to go over your options, but the final decision is yours!", ["objectivesText"] = "Speak with Thrall and choose the Artifact you wish to pursue. Progress: Have you made your decision yet?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128819, 128911, 128935, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1572, ["db2PoiUiMapID"] = 725, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41368] = { ["id"] = 41368, ["name"] = "Lost Mail", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 41368 }, ["description"] = "TO: MADAM GOYA , DALARAN UNDERBELLY URGENT! TIME-SENSITIVE! DELIVER IMMEDIATELY!", ["objectivesText"] = "Deliver the Lost Mail to Madam Goya in Dalaran Underbelly. Progress: What's this? You are not my usual courier...", ["rewardGold"] = 170800, ["rewardXP"] = 710, ["rewardItems"] = { 7912, 45693, 92738, 134859, 135463, 135479, 147869, 147870, 156721, 156833 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 134859 } },
[41395] = { ["id"] = 41395, ["name"] = "Due Reward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 41395 }, ["description"] = "You have served me well these past few minutes we've spent together - minutes I shall not soon forget. I believe a reward befitting your unwavering loyalty is in order. You will have the distinct honor of placing Twinkles' favorite toy by his grave in honor of his memory. Please, please - save your thanks for Twinkles; it is not every day that we may honor a horse made of STARS.", ["objectivesText"] = "Place Twinkles' favorite toy by his grave at the Sludge Fields in Hillsbrad Foothills.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 7912, 45693, 122340, 134859, 135463, 156721, 156833 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "standard" },
[41397] = { ["id"] = 41397, ["name"] = "A Huge Package", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 41397 }, ["description"] = "Due to the incredible volume of complaints in recent months we have been barred from delivering s... s... < The Postmaster holds back tears, pain visible in his eyes.> Solid stone. We're positively swimming in it - if we can't deliver it then pretty soon we will be overwh- < The Postmaster 's eyes light up suddenly.> That's it! There is an old Consortium portal not far from here that we could deposit it in with none the wiser! Can you help, <name>? The stone is extraordinarily heavy.", ["objectivesText"] = "Deliver 1,362 pieces of solid stone to the Ethereal Portal in Dalaran .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 7912, 45693, 109076, 134859, 135463, 139773, 140336, 147869, 156721, 156833 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[41409] = { ["id"] = 41409, ["name"] = "Timing Is Everything", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41409, 41410 }, ["description"] = "Can you feel it, <name>? The waters churn with approaching Sashj'tar. You must strike now... Leave me... Find a way to bombard the naga... with the kegs... Protect... Jandvik...", ["objectivesText"] = "Ride an Azuregale Paddlefoot and kill 50 Sashj'tar naga using the Sealed Powder Kegs in Azuregale Bay.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5821, ["name"] = "Protecting Jandvik", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41415] = { ["id"] = 41415, ["name"] = "The Hunter's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40384, 40618, 41415 }, ["description"] = "I realize we have never met, but you will learn of my order soon enough. For now, pleasantries must wait. The Legion has returned to Azeroth stronger than ever, and we need new weapons to fight them. I have met three individuals here in Dalaran who have leads on ancient artifacts which could prove vital in the battle to come. Acquiring these weapons demands the skills of a master hunter. Speak to each of them and decide whom you will aid first.", ["objectivesText"] = "Investigate leads on three artifact weapons. Progress: Have you chosen a lead to pursue first?", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 271, ["name"] = "Path of the Hunter", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41422] = { ["id"] = 41422, ["name"] = "Necessary Preparations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "G'Hanir is... is... < Mylune wipes her eyes, sniffling.> Corrupted! The Nightmare has risen from the depths of the dream. It all happened so fast... I was able to secret the staff here through the dream before it fell fully. It rests for now... but I fear we don't have much time. You must prepare to retrieve G'Hanir from the Dream. Draw water from the sacred moonwell on the northern edge of the grove and obtain an ancient's blessing. Quickly - every moment is precious!", ["objectivesText"] = "Fill a cup with moonwell water and obtain Leafbeard the Storied's blessing. Progress: Are you ready?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 135501, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41425] = { ["id"] = 41425, ["name"] = "Sunken Foes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41425 }, ["description"] = "The Tidemistress... is filling her ranks with hulking naga... and sea giants. Jandvik cannot withstand... their combined might. Slaughter them... before they reach its shores...", ["objectivesText"] = "Kill 6 Sashj'tar Overseers and 6 Trenchwalker Scavengers in Azuregale Bay. Progress: The Sashj'tar attacks are relentless.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104630, ["x"] = 0.758, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41426] = { ["id"] = 41426, ["name"] = "Against Their Will", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["series"] = { 40927 }, ["description"] = "When the naga brought me down here, I saw many of my vrykul mining the sea floor. They had... squids... attached to their faces. Whatever those things are, they must be controlling my kin and forcing them to work for the naga. I do not know what will happen if you remove the squids, but I would rather my vrykul die than be slaves to the naga. See me in Jandvik when the deed is done.", ["objectivesText"] = "Remove Writhing Willbreakers from 6 Possessed Vrykul in Azuregale Bay.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102390, ["x"] = 0.76, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41436] = { ["id"] = 41436, ["name"] = "In Deep Slumber", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "This bed will be yours for the deep slumber that will usher you into the Dream. Once you are comfortable, drink of the moonwater you brought. I will guide you from there. Quickly, now - with every passing moment G'Hanir slips further into darkness.", ["objectivesText"] = "Enter the Emerald Dream and retrieve G'Hanir. Progress: Were you able to retrieve G'Hanir?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 135506, 135582, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41449] = { ["id"] = 41449, ["name"] = "Join the Dreamer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "I'm afraid I can't really help you actually enter the Emerald Dream - we dryads merely shift our bodies between the planes. That's ok, though - Naralex has offered to help! Go to the very bottom of the Tel'Andu Barrow Den. Naralex is already there setting things up for you.", ["objectivesText"] = "Find Naralex deep within the Tel'Andu Barrow Den.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41452] = { ["id"] = 41452, ["name"] = "Feline Frantic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Greetings, stranger. <Mayruna bows to you.> We arrived from Val'Sharah a short time ago with hopes of settling here. Our journey was not easy and we are weary. These owlcats have made a mess of our camp, as you can surely see. Would you be so kind as to assist us with cleaning up? Then perhaps you can help us establish a new moonwell!", ["objectivesText"] = "Organize the camp. Progress: Is everything in its proper place?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41453] = { ["id"] = 41453, ["name"] = "Homeward Bounding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "The first step to establishing a moonwell is to gain the blessings of the local wildlife. It is their good will that enables us to peacefully coexist, and a moonwell thrives on such energies. Combined with Elune's light, a moonwell can purify its surroundings for years. To begin, we must find creatures willing to give their blessing. We can start with these owl-cat creatures. They ran while you cleaned, but I saw one lingering just before the bridge. See if you can find where it lives!", ["objectivesText"] = "Chase the Lost Feathermane Kitten across the bridge and return it to its family. Progress: Did you bring the little one back with you?", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41462] = { ["id"] = 41462, ["name"] = "Trouble Has Huge Feet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "The Ettin's hide bears many shallow scratch marks and bite scars. It seems he had been terrorizing the local Owlcats for quite some time. Mardranel Forestheart would be interested in this.", ["objectivesText"] = "Take the Grotesque Ettin Leather to Mardranel Forestheart .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 137179, 139791, 140240, 140251, 141941, 142054, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103570, ["x"] = 0.228, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 3, ["flags"] = 1 } } },
[41463] = { ["id"] = 41463, ["name"] = "Missing Along the Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41463 }, ["description"] = "As we retreated from Val'Sharah, our company was briefly separated by a conflict with some satyrs at the border. One of our own did not make it here- Mythandros' brother, Kalendros. I would like you to try and find him if you could. Search the woods just before the bridge back into Val'Sharah.", ["objectivesText"] = "Locate Kalendros Irongrove .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41464] = { ["id"] = 41464, ["name"] = "Not Here, Not Now, Not Ever", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41464 }, ["description"] = "I cannot, will not, accept what is happening here. My body resists me, but I will stop this. <He looks at you.> You will stop this. Here is a root of the corrupted World Tree Shaladrassil. It has somehow found its way out of the ground to this untouched place and already the Darkfiend satyrs are hard at work corrupting Suramar . Stop them. Kill the satyrs, take their horns, drive their points through the totems. Only then can we have any hope of reversing this.", ["objectivesText"] = "Use Satyr Horns to destroy 3 Darkfiend Totems. Progress: Have you stalled their efforts, <race>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137189, 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41467] = { ["id"] = 41467, ["name"] = "The Only Choice We Can Make", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41467 }, ["description"] = "Take this torch, <name>. We cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations. Incinerate the root. Only then can we rest easy in Suramar .", ["objectivesText"] = "Incinerate the Shaladrassil Root.", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 135534, 139791, 140240, 140251, 141941, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 106696, ["x"] = 0.194667, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.194667, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680 },
[41468] = { ["id"] = 41468, ["name"] = "Mistress of the Claw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["series"] = { 41782 }, ["description"] = "The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian's death his claws were hidden away, safe from any who would use their power for evil. Lea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea. She and her Druids of the Claw reside in the Tel'Andu Barrow Den just to the north.", ["objectivesText"] = "Find Lea Stonepaw .", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 101259, ["x"] = 0.392, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41469] = { ["id"] = 41469, ["name"] = "Return to Irongrove Retreat", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "We have three blessings from the creatures we share this land with. Combined with a blessing from Elune, the moonwell will watch over this land for years to come. Meet Mythandros at the retreat. I am sure he would like to include you in the ritual.", ["objectivesText"] = "Seek Mythandros at Irongrove Retreat.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41473] = { ["id"] = 41473, ["name"] = "Redhoof the Ancient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east. I believe Mythandros may have found the next creature that may offer us its blessing. There is a secluded glade along the river's bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.", ["objectivesText"] = "Locate Mythandros and Redhoof the Ancient.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41474] = { ["id"] = 41474, ["name"] = "Fertilizing the Future", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Like most herbivores, our antlered friends will eat anything green enough to chew. However I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food. I will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.", ["objectivesText"] = "Plant 5 Lush Grass Seeds in piles of Rich Soil . Progress: How goes the planting?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 124640, 135558, 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41475] = { ["id"] = 41475, ["name"] = "Prongs and Fangs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "Now, <name>, do not mistake me- I am a druid. I understand that nature has a balance. Predators must feed, and others will be hunted. I also understand that tampering with such balance has consequences. That is why I have taken upon myself to walk this land and perform some... ah... calculations. Slay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.", ["objectivesText"] = "Slay 8 Suramar Snarlers and Gloomfang . Progress: Are you being gentle with your pruning?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41478] = { ["id"] = 41478, ["name"] = "The Final Blessing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. Now that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.", ["objectivesText"] = "Speak to Solendra Featherdown .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41479] = { ["id"] = 41479, ["name"] = "Natural Adversaries", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers. To earn their blessing, I believe we should clear the way for their return. Slay the basilisks that have taken more than their fair share of the land, <race>.", ["objectivesText"] = "Slay 8 Manascale Basilisks .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41480] = { ["id"] = 41480, ["name"] = "Managazer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave. We will use this to our advantage. Seek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.", ["objectivesText"] = "Slay Managazer , the Basilisk Lord. Progress: Managazer must perish, <race>.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139791, 140240, 140251, 141941, 141942, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41485] = { ["id"] = 41485, ["name"] = "Moonwhisper Rescue", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "As a druid I understand that predation happens. Creatures that eat meat must acquire meat. But this... <Solendra gestures angrily toward a nearby petrified nightsaber .> This is just sad. Free them, <race>. Take my blessing and free them from this needless torment.", ["objectivesText"] = "Free 5 Petrified Nightsabers using Solendra's Gift. Progress: Have you freed them, <race>?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 136605, 139791, 140240, 140251, 141941, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41494] = { ["id"] = 41494, ["name"] = "Eminent Grow-main", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 }, ["description"] = "You have done very well, <race>. All that is left is to combine their blessings into the ritual bundle and imbue the Moonwell. Once that is done, Mayruna will add a little water from a purified Moonwell and this land will be protected so long as we inhabit it. This is a momentous occasion, my friend. You bear witness to a sacred rite not often performed in the company of strangers. I will let you do the honors- simply place the ritual bundle into the sacred waters and we will do the rest.", ["objectivesText"] = "Imbue the inert waters with the ritual bundle , then witness the well's creation. Progress: You witness history, <race>.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 136680, 139791, 140240, 140251, 141941, 237812, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103569, ["x"] = 0.272, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103568, ["x"] = 0.258, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 343, ["name"] = "Eminent Grow-main", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41499] = { ["id"] = 41499, ["name"] = "Squid Out of Water", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41001, 41499 }, ["description"] = "Toryl told me about those squid creatures that are controlling my brothers. I have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came. I do not want any more of my kin to suffer the fate of being controlled by the naga. Find out where those squids come from and stop them.", ["objectivesText"] = "Destroy 5 Willbreaker Incubators in the Sashj'tar Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102845, ["x"] = 0.706, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5813, ["name"] = "Brandolf", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41510] = { ["id"] = 41510, ["name"] = "Azeroth Needs You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 40225 }, ["description"] = "We shaman under your command will aid your efforts against the Legion. You may direct our actions from here. Seek out Advisor Sevel just to the south and locate the scouting map from which you can direct your followers. We will also indicate on the scouting map various hot-spots around the Broken Isles that require your attention. Azeroth needs you, Farseer! Visit the scouting map and choose our first point of attack.", ["objectivesText"] = "Select your first assault point on the Broken Isles.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 128819, 128911, 128935, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41540] = { ["id"] = 41540, ["name"] = "Rendezvous with the Courier", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40392, 40400, 40402, 40403, 40419, 41540 }, ["series"] = { 40392 }, ["description"] = "Thas'dorah is a mighty bow indeed! The weapon was carved from a limb of Thas'alah, the mother tree of Eversong, and infused with the magic of the Sunwell. I fought alongside its first wielder, Talanas Windrunner, during an Amani troll incursion. Ah, but such tales can wait for another time. Courier Larkspear was making preparations to depart. You can meet him at Krasus' Landing.", ["objectivesText"] = "Speak to Courier Larkspur at Krasus' Landing.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 173, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 173, ["name"] = "Legacy of the Windrunners", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41541] = { ["id"] = 41541, ["name"] = "A Beastly Expedition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["series"] = { 41574 }, ["description"] = "I know the power of Titanstrike well. The Unseen Path battled the vrykul warlord Volund as he campaigned to conquer the Broken Isles. We sought to wrest the rifle from him, but he took it to his grave. If Volund's tomb can at last be opened, the artifact would be a great boon to our cause. I believe Grif Wildheart is making preparations to depart. You can meet him at Krasus' Landing.", ["objectivesText"] = "Speak to Grif Wildheart at Krasus' Landing in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41542] = { ["id"] = 41542, ["name"] = "Preparation for the Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 39427, 40385, 41542 }, ["description"] = "Talonclaw is a mighty spear indeed! I first set eyes upon it when the Highmountain tauren led the members of my order up to Talon Peak to found the Trueshot Lodge. But such tales must wait for another time. Apata has been in Dalaran gathering supplies for her expedition. I imagine she's ready to depart by now. Seek her out at Krasus' Landing. I know she will be eager to begin.", ["objectivesText"] = "Speak to Apata Highmountain at Krasus' Landing in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 220, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 220, ["name"] = "Talonclaw", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41574] = { ["id"] = 41574, ["name"] = "Stolen Thunder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 745, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["series"] = { 41541 }, ["description"] = "Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield's Rest. It's a dank, sloppy mess adrift in a sea of gloom. Sounds lovely, eh? I've been workin' with a vrykul guide named Prustaga. She'll help us break the wards keepin' the tomb sealed. I know what you're thinkin'... vrykul are trouble. But she hasn't taken a swing at me just yet. Huey'll take us down to the shore. Prustaga's probably found the tomb by now!", ["objectivesText"] = "Accompany Grif Wildheart to Shield's Rest Island and track down Titanstrike. Progress: It's a good thing you found my observation relay! It's been missing for at least a thousand years.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41575] = { ["id"] = 41575, ["name"] = "Felsoul Teleporter Online!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 41575 }, ["description"] = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", ["objectivesText"] = "Infuse the Beacon with Ancient Mana . Progress: <The beacon is cold and dark.>", ["rewardXP"] = 4605, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41606] = { ["id"] = 41606, ["name"] = "Finding Brytag", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40364, 41606, 41618 }, ["series"] = { 40364 }, ["description"] = "< Kell barely manages to speak.> That naga witch... has given many of my kin... to the sea giants. Brytag was... the last one I saw alive. Find him quickly.", ["objectivesText"] = "Locate Brytag in Azuregale Bay.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104630, ["x"] = 0.758, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5814, ["name"] = "Brytag", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41607] = { ["id"] = 41607, ["name"] = "Taking a Promenade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["description"] = "We must learn much about our long-lost kin if we are to fight them. We dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in. They have not returned in some time, and we must suspect the worst. Find them and we shall see what we are up against.", ["objectivesText"] = "Locate the scouts in the Promenade.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114883, ["x"] = 0.405, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114883, ["x"] = 0.405, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41618] = { ["id"] = 41618, ["name"] = "The Seawarden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40364, 41606, 41618 }, ["description"] = "The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle. I despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands. If you cross his path before I get out of here, make him regret ever making a deal with the naga!", ["objectivesText"] = "Kill Seawarden Largush in Azuregale Bay. Progress: Have you slain the Seawarden?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5814, ["name"] = "Brytag", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41625] = { ["id"] = 41625, ["name"] = "The Light's Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 18, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "Light's Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause. Retrieving it won't be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", ["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41626] = { ["id"] = 41626, ["name"] = "A New Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 115, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "If you seek the Nexus, I would warn not to rush headlong. There are strange happenings in Coldarra, and it would be best to gather some information before proceeding. During my last visit to the Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was very closely tied to Malygos' plans during the Nexus Wars, whatever is present there may explain the current state of the Nexus. I cannot accompany you, but this crystal can be used to communicate with me. Good luck.", ["objectivesText"] = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41627] = { ["id"] = 41627, ["name"] = "A Forgotten Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "The device still hums with power. It must have been abandoned not long ago. The nearby switch appears to activate it.", ["objectivesText"] = "Activate the Ethereal Communication Device at the Azure Dragonshrine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41628] = { ["id"] = 41628, ["name"] = "Eyes of the Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41631, 41632 }, ["description"] = "You should travel at once to Coldarra in Borean Tundra, <name>. There, I would recommend you scout out a few key locations and report back to me. I know the area well, and should be able to tell you how to proceed. Make haste!", ["objectivesText"] = "Scout out the key locations in Coldarra.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930, 173430, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41629] = { ["id"] = 41629, ["name"] = "Harnessing the Holy Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41631, 41632 }, ["description"] = "The energy from Light's Wrath lashes out from within the weakened Nexus Vault. We may be able to use this raw, chaotic energy to our advantage. If we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", ["objectivesText"] = "Empower yourself with Unstable Holy Energy by defeating Wraths of the Light or siphoning from Breaches of Holy Energy around the foundation of the Nexus.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41630] = { ["id"] = 41630, ["name"] = "Unleashing Judgment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 114, ["storyline"] = { 41625, 41626, 41627, 41629, 41630, 41631, 41632 }, ["description"] = "You have the power you need to destroy the Surge Needles. At the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Light's Wrath into these points of focused void, and the reaction should cause an overload, destroying the Surge Needle above. You must act quickly. The Ethereum likely won't sit idly by as you lay waste to their machinations.", ["objectivesText"] = "Use your built up Unstable Holy Energy to destroy the Surge Needles in Coldarra.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41631] = { ["id"] = 41631, ["name"] = "The Nexus Vault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3, 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8094, ["mapID"] = 627, ["storyline"] = { 41628, 41629, 41630, 41631 }, ["description"] = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. We have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Light's Wrath, I would ask that you also free my brother from their grip. With the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, <name>.", ["objectivesText"] = "Defeat Nexus-Prince Bilaal and claim Light's Wrath.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128825, 128827, 128868, 136410, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8094 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41632] = { ["id"] = 41632, ["name"] = "A Gift of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 }, ["description"] = "You have done a great thing for the blue dragons today, <name>, as well as for my own peace of mind. Now, armed with Light's Wrath, I only ask that you fulfill your original goal, and take the fight to the Legion. I believe Alonsus Faol awaits your return. Safe travels, friend.", ["objectivesText"] = "Speak with Alonsus Faol .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 136410, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 239, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 239, ["name"] = "Light's Wrath", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41689] = { ["id"] = 41689, ["name"] = "Cleansing the Mother Tree", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "We must save the Mother Tree at all costs. I believe I know a way. The world tree Nordrassil, atop Mount Hyjal, was born from an acorn of G'Hanir. We can use the sacred waters surrounding its roots to purify the corruption. If we take the Dreamway to Mount Hyjal's summit we should have enough time to complete the cleansing ritual before G'Hanir falls completely to the darkness.", ["objectivesText"] = "Use the Dreamway to travel to Mount Hyjal, then cleanse G'Hanir in the sacred waters beneath Nordrassil.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41690] = { ["id"] = 41690, ["name"] = "Reconvene", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40649, 41422, 41436, 41449, 41689, 41690 }, ["description"] = "You found Lyessa in the Dream, didn't you, Shan'do <name>? I heard you mutter her name in your slumber. Thank Elune she is well. You must seek her out - I can sense her presence even now at the Circle of Spirits above. If ever there were one who could help us cleanse G'Hanir, it is Lyessa.", ["objectivesText"] = "Meet with Lyessa Bloomwatcher at the Circle of Spirits.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104349, ["x"] = 0.395, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.183 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 164, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 164, ["name"] = "G'Hanir, the Mother Tree", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41704] = { ["id"] = 41704, ["name"] = "Subject 16", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 40326, 41702, 41760 }, ["description"] = "<It seems Theryn is still under the arcanist's spell. In the absence of Kel'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>", ["objectivesText"] = "Deliver Theryn to Thalyssra.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 38716, 39020, 39049, 39081, 129979, 136269, 136600, 136970, 140349, 141605, 141668, 142054, 237812, 259009, 259011, 259012 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104618, ["x"] = 0.26, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41707] = { ["id"] = 41707, ["name"] = "Wormtalon Wreckage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38671, 41707 }, ["description"] = "As if Shaladrassil's encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. Kill them, <race>. They deserve nothing less for feeding on our misery.", ["objectivesText"] = "Slay 15 Wormtalon Harpies in Shadowfen.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95117, ["x"] = 0.694, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95117, ["x"] = 0.694, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5764, ["name"] = "Shadowfen Sorrows", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41708] = { ["id"] = 41708, ["name"] = "Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind! These refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption... I will beg of Elune a vision to give me direction. With her light, I may find my husband yet.", ["objectivesText"] = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 106175, 107307, 107312, 107317, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41709] = { ["id"] = 41709, ["name"] = "Breaking Down the Big Guns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "You did well against that sea witch, but not well enough. Her power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect... < Toryl grins wryly.> Something of their own design... Salvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.", ["objectivesText"] = "Collect 50 Harpoon Parts from Sashj'tar Harpooners in Azuregale Bay. Progress: The Tidemistress is a dangerous foe. We must be just as cunning to defeat her.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133926, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102390, ["x"] = 0.76, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102410, ["x"] = 0.706, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41724] = { ["id"] = 41724, ["name"] = "Heart of the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole. <Tyrande's expression hardens into a scowl.> Elune herself cannot protect Xavius if he is not.", ["objectivesText"] = "Track Malfurion's path through the Nightmare.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41728] = { ["id"] = 41728, ["name"] = "The Defense of Tian Monastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41729, 41730, 41731, 41732, 41733 }, ["description"] = "Chen's recent report indicates that Tian Monastery is under attack! <name>, they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.", ["objectivesText"] = "Travel to the Jade Forest on Pandaria, then speak to Taran Zhu at Tian Monastery. Speak to Tak-Tak west of the Temple of Five Dawns to fly there.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41729] = { ["id"] = 41729, ["name"] = "Slowing the Spread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41730, 41731, 41732, 41733 }, ["description"] = "Reinforcements. Just what we needed! Grandmaster, the monastery is under attack. The Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy. Destroy those machines, and we can slow their efforts.", ["objectivesText"] = "Destroy 3 Fel Spreaders .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104745, ["x"] = 0.382, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41730] = { ["id"] = 41730, ["name"] = "Desperate Strike", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41731, 41732, 41733 }, ["description"] = "Good, your timing couldn't have been better, <name>. These foul Legion creatures have invaded our sanctuary. They have no place here on our world. Kill every demon you see, <brother/sister>.", ["objectivesText"] = "Kill 20 demon attackers. Progress: This is an invasion like none I have ever seen before.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41731] = { ["id"] = 41731, ["name"] = "Storm, Earth, and Fire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41730, 41732, 41733 }, ["description"] = "Tian Monastery is in bad shape. Felspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery's ale barrels, tainting the brew. Use your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels. Sigh... hundreds of years of the finest ale... ruined. I don't wish to hear any more of it. Just get it done.", ["objectivesText"] = "Destroy 5 Fel Spikes, put out 5 Fel Fires , and destroy 5 Tainted Ale barrels. Progress: Is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104784, ["x"] = 0.410667, ["y"] = 0.247333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.410667, ["y"] = 0.247333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41732] = { ["id"] = 41732, ["name"] = "The Hand of Keletress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41730, 41731, 41733 }, ["description"] = "The demons' leader is up ahead, taking prisoners it is said! This dire storm, we will weather... if we fight her together!", ["objectivesText"] = "Kill Skola Greatsword .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104850, ["x"] = 0.431333, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.431333, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41733] = { ["id"] = 41733, ["name"] = "Rebuilding the Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 41728, 41729, 41730, 41731, 41732 }, ["description"] = "On behalf of all the students and teachers here at Tian Monastery, thank you, Grandmaster <name>. You have a difficult task ahead of you to rebuild our order, but we stand with you. Let us head back to the Wandering Isle.", ["objectivesText"] = "Speak to Iron-Body Ponshu at the Wandering Isle.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 140928, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 6, ["flags"] = 0 } } },
