[41759] = { ["id"] = 41759, ["name"] = "An Unlikely Ally", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 630, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 39389, 40218, 41767 }, ["description"] = "Channeling the demonic gateway will require the assistance of someone with intimate knowledge of the Burning Legion. I know of such a warlock, though I imagine her blood still boils upon hearing my name. It might be best if you are the one to request her help.", ["objectivesText"] = "Speak to Kira Iresoul in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41760] = { ["id"] = 41760, ["name"] = "Kel'danath's Legacy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40012, 40326, 41149, 41702, 41704, 41760 }, ["series"] = { 40012, 40326, 41702, 41704 }, ["description"] = "Kel'danath discovered something incredible - the power to subdue and even control the withered. I will pick up where my old friend left off. We shall see to it that he did not die in vain. Perhaps in the end we can even find peace for the wretches who have been left to a fate worse than death. I will need more subjects. Take Kel'danath's spellstone and use it to subdue more withered.", ["objectivesText"] = "Use the Spellstone of Kel'danath to charm 5 withered and send them to Shal'Aran. Progress: We will need more subjects if we are to continue Kel'danath's research.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136269, 136600, 136970, 140349, 141668, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 153, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 153, ["name"] = "Kel'danath's Legacy", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41762] = { ["id"] = 41762, ["name"] = "Sympathizers Among the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 41834, 41989 }, ["description"] = "Elisande's decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her. We have allies in the city - we just don't know how many. I need you to make contact with a spell-fencer by the name of Silgryn . He is loyal to our cause, and has been lying in wait since our failed coup. He patrols the western edge of the city. Address him by name and tell him our cause is not lost!", ["objectivesText"] = "Speak with Silgryn in the Suramar Outskirts.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136600, 136970, 137010, 141947, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 105071, ["x"] = 0.41, ["y"] = 0.7355 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41763] = { ["id"] = 41763, ["name"] = "Close Enough to Touch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "He is near, <race>, I can feel it. We must search Shala'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever. I was unsure of your worth when first we met. I know now that you will not fail me. I am... grateful.", ["objectivesText"] = "Search for Malfurion within Shala'nir.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132305, 132306, 132308, 132309, 132310, 132311, 132312, 132314, 132316, 132317, 132319, 132320, 132321, 132322, 132323, 132325, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104799, ["x"] = 0.578, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.427333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41764] = { ["id"] = 41764, ["name"] = "Walking in Their Footsteps", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41799, 41800, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past. The wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them. Igrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Igrul the Scalebane. Progress: As a spiritwalker, I am able to see the memories of the dead.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41767] = { ["id"] = 41767, ["name"] = "A Daring Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 748, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["series"] = { 39142, 39179, 39389, 40218, 41759 }, ["description"] = "The plan is a simple one, but it will require great effort on your part. Kira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.", ["objectivesText"] = "Enter the demon world and rescue the missing council members. Progress: Kira and I can sustain the gateway, but you will need to enter the demon world alone.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41768] = { ["id"] = 41768, ["name"] = "Soul Beacon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41769, 41780, 41781, 41784 }, ["description"] = "I have bound Shinfel's soul to her staff, allowing it to serve as an anchor in this world. When we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.", ["objectivesText"] = "Perform a ritual of summoning to retrieve the missing council member. Progress: The council cannot be rebuilt without Shinfel.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41769] = { ["id"] = 41769, ["name"] = "Mad Ernie the Alchemist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41780, 41781, 41784 }, ["description"] = "If we have any hope of curing this curse, we need to know what kind of magic we're dealing with. I know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands. His knowledge may be the first step to breaking this curse.", ["objectivesText"] = "Find Mad Ernie the Alchemist in Val'sharah. Progress: Have you come to lend a hand? We all must do our part.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41770] = { ["id"] = 41770, ["name"] = "The Skies Above", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41771, 42184 }, ["description"] = "There has been no Windlord to lead the air elementals since the death of Al'Akir. The realm of Skywall has been thrown into turmoil. The throne of Al'Akir is Thunderaan's by right, but what remains of the prince's essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever. Take the damaged Thunderfury to Vortex Pinnacle and speak with Celestos. Celestos was a loyal servant of Al'Akir and he will share our desire to see Thunderaan reborn.", ["objectivesText"] = "Speak with Celestos in The Vortex Pinnacle.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139000, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41771] = { ["id"] = 41771, ["name"] = "Recharging the Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41770, 42184 }, ["description"] = "You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan. Thunderfury can be restored, but it will require a rare essence known as the Heart of Skywall . Vortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly. Vortos must be defeated, and the Heart of Skywall must be combined with the blade. Only then can Thunderaan return and claim the Throne of Four Winds.", ["objectivesText"] = "Obtain the Heart of Skywall . Progress: Have you retrieved the Heart of Skywall ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 135589, 137209, 137374, 139000, 139037, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41772] = { ["id"] = 41772, ["name"] = "Ascendant of Flames", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 738, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41900, 42208 }, ["description"] = "As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less. If we help him defeat his rival and ascend to Firelord, he may unite with us in return. The champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally. If anyone can succeed at this impossible task, I have faith that it is you, Farseer. May the elements be with you.", ["objectivesText"] = "Speak with Rehgar Earthfury in the Firelands.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 143489, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1605, ["db2PoiUiMapID"] = 738, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41773] = { ["id"] = 41773, ["name"] = "The Firelord's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 738, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41774, 41888, 41934 }, ["description"] = "Greetings, mortal. I am Scaldius, emissary of Lord Smolderon . I have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon . Pyroth and his minions defy my master's rule and so an example must be made of them. You will slay Pyroth and his champions! Nothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.", ["objectivesText"] = "Defeat the forces of Pyroth. Progress: I will devour the heart of Pyroth with great pleasure!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 136535, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1605, ["db2PoiUiMapID"] = 738, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41775] = { ["id"] = 41775, ["name"] = "The Great Stonemother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41901, 42068, 42200 }, ["description"] = "In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth. However, the Stonemother currently has her hands full battling a Twilight's Hammer resurgence in Deepholm. If we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion. Journey to Therazane 's Throne in the heart of Deepholm. Aid her in defeating the Twilight's Hammer and convince her to join the defense of Azeroth!", ["objectivesText"] = "Speak with Therazane in Deepholm. Progress: What would you have with the Stonemother, <class>?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41776] = { ["id"] = 41776, ["name"] = "Return of the Windlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 737, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "With Thunderfury recharged, Prince Thunderaan can now return to the physical realm. In a moment, I will release my master's spirit from the blessed blade. When the ritual is complete, Skywall will once again have its Windlord.", ["objectivesText"] = "Summon Prince Thunderaan .", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1602, ["db2PoiUiMapID"] = 737, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41777] = { ["id"] = 41777, ["name"] = "Destroying the Cult", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41897, 41898, 41899, 42065 }, ["description"] = "We are all that stands between the Twilight's Hammer and their conquest of Deepholm. Azeroth cannot hope to fight the full strength of the Twilight's Hammer and the Burning Legion at the same time. It is up to us to put an end to their cult before they are able to fully rebuild. Accompany me into their stronghold and we shall cut through their ranks together!", ["objectivesText"] = "Slay 15 Twilight's Hammer cultists at The Twilight Throne. Progress: How many have you slain? I've lost count.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41780] = { ["id"] = 41780, ["name"] = "Doom and Gloom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41781, 41784 }, ["description"] = "Doom curses are serious business, so much so that many warlocks didn't deal in them for some time. The magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it. I can craft an elixir that will slow its progression, but you'll need to collect an assortment of ingredients first.", ["objectivesText"] = "Recover the ingredients Ernest needs to create an Elixir of Suspension. Progress: Have you found those ingredients yet? Time really isn't on your side, you know.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128330, 128758, 128759, 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41781] = { ["id"] = 41781, ["name"] = "Herding Goats", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41780, 41784 }, ["description"] = "In case you haven't noticed, things are a bit hectic around here. Marl's doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck! Round them up for me and I'll do my best to figure out how to handle the curse you're dealing with.", ["objectivesText"] = "Catch Greyhorn Goats, then return them to their pen. Progress: Have you found my goats yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41782] = { ["id"] = 41782, ["name"] = "To The Hills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["series"] = { 41468 }, ["description"] = "It is said that a fragment of Ursoc's spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord's fury. <Lea looks intently at you for a moment.> But you are no novice, I can see that clearly. Very well, draw water from the moonwell on the northern edge of the grove then come find me. I'll await your arrival within the broken stump of Vordrassil in Northrend.", ["objectivesText"] = "Fill a Vial of Moonwell Water and locate Lea Stonepaw within Grizzly Hills. Progress: Did you get the moonwell water? It is essential for our task!", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 49927, 128306, 128822, 128858, 128859, 135563, 197388, 197998, 198015, 198023, 198030, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 101259, ["x"] = 0.392, ["y"] = 0.186 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.186 }, ["mapCandidates"] = { ["npc"] = { 116, 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41784] = { ["id"] = 41784, ["name"] = "Borrowed Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["series"] = { 41768, 41769, 41780, 41781 }, ["description"] = "Don't let the aroma deceive you, this concoction is mostly safe for consumption. Whoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright? Keep in mind, this will only weaken the curse, not cure it.", ["objectivesText"] = "Give the Elixir of Suspension to Shinfel Blightsworn. Progress: Shinfel's curse will kill her soon if we don't find a way to slow its progression.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 136357, 139506, 139765, 139767, 139770, 140517, 140922, 224272, 224273, 224274, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104824, ["x"] = 0.392, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41785] = { ["id"] = 41785, ["name"] = "Finding Fizzlebang", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41787, 41788, 41793, 41795, 41796, 42102 }, ["description"] = "I have reason to believe that Wilfred Fizzlebang's sister has made her way to Stormheim. If she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.", ["objectivesText"] = "Find Lulubelle Fizzlebang in Stormheim.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41787] = { ["id"] = 41787, ["name"] = "Someone Else's Mess", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41788, 41793, 41795, 41796, 42102 }, ["description"] = "A confession alone won't be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. Someone needs to clean up the mess that warlock made. I'd do it myself, but I can't be placed at the scene of the crime. You could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!", ["objectivesText"] = "Banish demons that have been irresponsibly summoned in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 141865, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41788] = { ["id"] = 41788, ["name"] = "Coercing a Confession", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41793, 41795, 41796, 42102 }, ["description"] = "My location has to be kept secret, at least until I have proof of my innocence. Thanks to the legacy of my family name, any time some miserable warlock summons demons they can't control, I get the blame. The scene of my latest \"crime\" is a nearby cave, where unruly imps and other nasty demons are roaming free. Find the lousy warlock who's responsible, and get him to write a confession.", ["objectivesText"] = "Find the warlock that has been irresponsibly summoning demons and obtain a written confession of his wrongdoings.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 136363, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41790] = { ["id"] = 41790, ["name"] = "The First Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "The Legion... <the glow of Ursol 's eyes begin to shine intensely> Yes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear! You must prove to me that the spirit of the bear resides within you as well.", ["objectivesText"] = "Complete the first of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41791] = { ["id"] = 41791, ["name"] = "The Second Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage. Your next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!", ["objectivesText"] = "Complete the second of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41792] = { ["id"] = 41792, ["name"] = "The Third Trial of Ursol", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "You've proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most? This final trial will reveal all.", ["objectivesText"] = "Complete the third of Ursol 's trials. Progress: <The ancient stares at you expectantly.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 104385, ["x"] = 0.506, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 116, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41793] = { ["id"] = 41793, ["name"] = "Lulubelle on Loan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41795, 41796, 42102 }, ["description"] = "What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That's just asking for trouble. Luckily, I'm up for the challenge. I'll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.", ["objectivesText"] = "Speak to Ritssyn Flamescowl .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 104855, ["x"] = 0.392, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41795] = { ["id"] = 41795, ["name"] = "Summoning the Sisters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41793, 41796, 42102 }, ["description"] = "It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order. Once the sisters have been summoned, use the Bloodstone to enslave them. I'll let the others know it's time to begin.", ["objectivesText"] = "Travel through the Demonic Gateway to reach the summoning platform and use the Bloodstone to subdue the eredar sisters once the summoning is complete.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41796] = { ["id"] = 41796, ["name"] = "Selecting a Sixth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41793, 41795, 42102 }, ["description"] = "With the demon sisters under your control, you have managed to weaken Mephistroth's army and gain powerful allies for the council. Our work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains. If we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains. As First of the Black Harvest, the choice is yours.", ["objectivesText"] = "Choose who will become the final member of the council. Progress: The choice may not be easy, but it is yours to make.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 142057, 142058, 142059, 142063, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41797] = { ["id"] = 41797, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 42601, 42602, 42603, 42608 }, ["description"] = "As her name suggests, Imp Mother Dyala is adept at summoning imps. While the council controls Dreadscar Rift, her services will be ours to use as we see fit. Speak to her if you wish to train a pack of imps.", ["objectivesText"] = "Speak to Imp Mother Dyala and train a Pack of Imps. Progress: How did the training go?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41798] = { ["id"] = 41798, ["name"] = "Recruiting More Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire. Speak to him now.", ["objectivesText"] = "Speak to Recruiter Jared .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41799] = { ["id"] = 41799, ["name"] = "Minions of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41800, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us. Ebonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness. Use the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Oenia Skyhorn. Progress: The spirits speak of the Darkness. A great danger rises, <name>.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41800] = { ["id"] = 41800, ["name"] = "Servants of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41884, 48185, 48190, 48434, 48435 }, ["description"] = "The heroes of Highmountain's past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years. We must not fail their memory. Huln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn. Enter the echo of Huln's spirit, and let his courage lead you to the location of this ward.", ["objectivesText"] = "Use the Water of Vision to walk in the memories of Huln Highmountain.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41803] = { ["id"] = 41803, ["name"] = "Asking a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria Felsoul was a bright student... and a Legion traitor. In her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi's greatest champion - they say he only finally fell to Sargeras himself. We sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source. Perhaps you could see if Khadgar has anything we could use? I'm afraid our allies are few.", ["objectivesText"] = "Ask Khadgar for a source to power the Legion communicator.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41804] = { ["id"] = 41804, ["name"] = "Ask and You Shall Receive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "A Legion communicator? Hmmmm. <Khadgar pauses to think for a moment.> You know what, I think I have something in my lockbox upstairs that is just the ticket.", ["objectivesText"] = "Obtain the Crystallized Soul from Archmage Khadgar . Progress: I'm always happy to help a friend.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 127830, 128832, 136385, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41806] = { ["id"] = 41806, ["name"] = "Return to Jace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "That crystallized soul should power your communicator long enough to reach your allies. I must urge you to be cautious, <name>. If that device is of Legion origin, then you never know who among its creators might overhear your message. I'm sure your allies eagerly await your return.", ["objectivesText"] = "Return to Jace Darkweaver .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41807] = { ["id"] = 41807, ["name"] = "Establishing a Connection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "<Jace glances at the crystallized soul.> Yes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces. If Caria is out there, we will find her, and we will make her suffer for her transgressions.", ["objectivesText"] = "Activate the Legion Communicator and receive Allari the Souleater's report. Progress: This may be our only chance at revenge against Caria. Every moment is precious.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41815] = { ["id"] = 41815, ["name"] = "Curse of the Necrodark", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41839, 41840, 41841, 41882, 48403 }, ["description"] = "It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys. They will not take our sacred mountain, <name>. Not while I draw breath. With the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all. Come. Let us take back the summit from the forces that would corrupt it.", ["objectivesText"] = "Journey to Highmountain Summit.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 130423, ["x"] = 0.564, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41834] = { ["id"] = 41834, ["name"] = "The Masks We Wear", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 41762, 41989 }, ["description"] = "Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent. We must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion. Ly'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers. Let us invite ourselves in.", ["objectivesText"] = "Speak with 8 Masqued Revelers while in costume, then speak with Ly'leth Lunastre . Progress: Pleased to make your acquaintance.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136600, 136970, 137010, 141947, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 105071, ["x"] = 0.41, ["y"] = 0.7355 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.7355 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41841] = { ["id"] = 41841, ["name"] = "The Final Ward", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41840, 41882, 48403 }, ["description"] = "The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way. The shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest. Do not hesitate. The fate of Highmountain itself hangs in the balance.", ["objectivesText"] = "Restore the Summit Ward. Progress: This is the hardest challenge I have ever had to face.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.922667 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41849] = { ["id"] = 41849, ["name"] = "The Iron Fist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41850, 41852 }, ["description"] = "It's time to send a rescue operation to the Gates of Valor, <name>. I will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim. Grandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.", ["objectivesText"] = "Speak to Angus Ironfist at Tideskorn Warcamp in Stormheim.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 105045, ["x"] = 0.629, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41850] = { ["id"] = 41850, ["name"] = "The Master of Swords", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41849, 41852 }, ["description"] = "I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line! First things first, my friend Sylara is being held captive in the camp just across the road. We need ta free her - she'll be a valuable ally. We've got ta move move move!", ["objectivesText"] = "Collect Dravax's Key from Dravax, then free Sylara Steelsong . Progress: Something need punching?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136406, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 105045, ["x"] = 0.629, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41851] = { ["id"] = 41851, ["name"] = "Quelling the Tide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "<Sylara looks at you with determined eyes.> Our friends are in danger. We will save them. Kill any Legion in the way.", ["objectivesText"] = "Kill 16 Legion defenders at the Gate of Valor. Progress: <Sylara nods at you.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41852] = { ["id"] = 41852, ["name"] = "No Monk Left Behind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["series"] = { 41849, 41850 }, ["description"] = "Most of the prisoners are being held in the main camp at the Gates of Valor. Our people have been beaten and tortured, and worse still awaits for them if we don't save them. Find the cages within the main camp and free as many monks as you can find. I'll be right beside you, knocking heads and taking names!", ["objectivesText"] = "Free 6 Tortured Prisoners. Progress: Did we free them all?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139506, 139738, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41853] = { ["id"] = 41853, ["name"] = "Zero to Hiro", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "I have a favor to ask of you, <name>. My good friend Hiro is still somewhere inside the main camp. Only problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I've ever seen. If we walk in there, we'll just get slaughtered. But I've seen these vrykul chugging some kind of special brew called Storm Brew . It's some kind of combat tonic that makes them bigger and stronger. Let's steal some of that drink, then storm in to save Hiro !", ["objectivesText"] = "Steal a Storm Brew , then save Hiro .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41854] = { ["id"] = 41854, ["name"] = "Brick By Brick", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "Da monks be free, and we put a thorn in dat eredar lady's side. I'm back wit my friends, and lookin' forward to sleepin' in a bed tonight. Let's go back ta da Wanderin' Isle. I've never been so excited ta see a turtle in my life.", ["objectivesText"] = "Return to Iron-Body Ponshu on the Wandering Isle.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139506, 139738, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41863] = { ["id"] = 41863, ["name"] = "Vengeance Will Be Ours", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 40247, 40249, 41803, 41804, 41806, 41807, 41863 }, ["description"] = "Caria lies in the very heart of Legion territory - they'll see our forces immediately if we try to launch an all-out attack. Failure is not an option. However, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army. Remember, <name> - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.", ["objectivesText"] = "Take the Aldrachi Warblades from Caria Felsoul.", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 160, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 160, ["name"] = "The Aldrachi Warblades", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41877] = { ["id"] = 41877, ["name"] = "Lady Lunastre", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city. Have your disguise ready just in case, <name>.", ["objectivesText"] = "Seek out Ly'leth at the Grand Promenade. Progress: Hm?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41878] = { ["id"] = 41878, ["name"] = "The Gondolier", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I need your help. The wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered. I am dedicated to preventing this for as long as possible. There is a woman by the name of Deline who owns and operates a small delivery service out of her gondola. Find her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.", ["objectivesText"] = "Make contact with the Gondolier. Progress: Unless you want a ride, you should keep moving.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41882] = { ["id"] = 41882, ["name"] = "Whispers of the Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41840, 41841, 48403 }, ["description"] = "Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into. Our people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own. Wake them from their stupor. Free them from the whispers any way you can.", ["objectivesText"] = "Free 6 Highmountain Protectors .", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 119036 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97662, ["x"] = 0.484, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[41884] = { ["id"] = 41884, ["name"] = "Dark Tales", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 48185, 48190, 48434, 48435 }, ["description"] = "Spiritwalker Ebonhorn is stable... for now. He once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own. Incapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack. To find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there. Meet me in Riverbend, <name>. It is there our search begins.", ["objectivesText"] = "Meet Spiritwalker Graysky in Riverbend.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41888] = { ["id"] = 41888, ["name"] = "Allegiance of Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41773, 41774, 41934 }, ["description"] = "My rivals lay dead and there are none within the Firelands who dare oppose my rule! As promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies! Go now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!", ["objectivesText"] = "Speak with Farseer Nobundo in The Heart of Azeroth. Progress: What news do you bring from the Firelands?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139698, 142059, 142060, 142061, 142062, 142064, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41890] = { ["id"] = 41890, ["name"] = "Dark Side of the Moon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind! These refugees tell of an ancient Moonwell hidden in the ruins ahead. If it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet. Meet me at the Moonwell at once, <class>.", ["objectivesText"] = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 106175, 107307, 107312, 107317, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6805, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41893] = { ["id"] = 41893, ["name"] = "Given to Corruption", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "A final favor for an old friend, perhaps? My age-old companion, Varethos , has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour. As with all who suffer this fate, there is no restoring him. Please, <name>, bring him peace.", ["objectivesText"] = "Slay Keeper Varethos . Progress: Is it done, then?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 92783, ["x"] = 0.662, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 5, ["flags"] = 0 } } },
[41897] = { ["id"] = 41897, ["name"] = "The Master's Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41898, 41899, 42065 }, ["description"] = "The purpose of the Twilight's Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant. Defeating the Twilight's Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created. Let us start by searching the encampment for clues as to their true purpose here.", ["objectivesText"] = "Collect the excerpts from The Master's Journal. Progress: What vile scheme have the Twilight's Hammer plotted against the world this time?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 136791, 136792, 136793, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41898] = { ["id"] = 41898, ["name"] = "Unleashing the Elements", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41899, 42065 }, ["description"] = "According to The Master's journal, the Twilight's Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals. The journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing. It appears that our journey here is going to take us deeper into the depths of darkness...", ["objectivesText"] = "Release the Servants of Therazane from Twilight Depths. Progress: Dark rituals such as these must not be allowed to continue.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41899] = { ["id"] = 41899, ["name"] = "Held Captive!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41898, 42065 }, ["description"] = "There are prisoners here, Farseer <name>, that are enslaved by the Twilight's Hammer. The cultists work them to death in the depths of the mine. I cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight's Hammer prisoners we find, so that they may return to their homes and families. The Twilight's Hammer will pay for their crimes!", ["objectivesText"] = "Rescue 10 Twilight Slaves from the Twilight Depths. Progress: Have the slaves been rescued?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41900] = { ["id"] = 41900, ["name"] = "A Promise of Earth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41772, 42208 }, ["description"] = "Deepholm thanks you, shaman. The Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts. For your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth. I have no love for the mortal races, but this world is not the Burning Legion's to destroy. Tell your Earthen Ring that Therazane the Stonemother stands with them!", ["objectivesText"] = "Speak with Advisor Sevel in the Heart of Azeroth.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139506, 139705, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 14, ["flags"] = 0 } } },
[41901] = { ["id"] = 41901, ["name"] = "Oath of the Windlord", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8093, ["mapID"] = 726, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41775, 42068, 42200 }, ["description"] = "You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable. I know that the Earthen Ring seeks to save Azeroth from the Burning Legion. I will pledge my sword, and the armies of Skywall to the aid of Azeroth. When the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.", ["objectivesText"] = "Speak with Advisor Sevel .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8093 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41905] = { ["id"] = 41905, ["name"] = "Report from Tian Monastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["series"] = { 42191 }, ["description"] = "We have heard from all our temples on Pandaria, except for one. We dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual. Grandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Investigate Tian Monastery.\" Progress: What have you discovered?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41907] = { ["id"] = 41907, ["name"] = "Appropriations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "I have come to lend my help to the Order of the Broken Temple. My job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses. Lao Shu is in charge of our supply inventory. Go and speak with him now in the inn.", ["objectivesText"] = "Speak to Lao Shu in The Laughing Crane inn.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41909] = { ["id"] = 41909, ["name"] = "Tracking the Tideskorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off. They've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail. I suggest that we send our champions immediately to assist with the tracking effort.", ["objectivesText"] = "Use the Scouting Map and complete the \"Tracking the Tideskorn\" missions. Progress: Did we gather enough information about the Legion forces at the Gates of Valor?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41910] = { ["id"] = 41910, ["name"] = "Freya's Spring", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "First, we need water from Freya's Spring. Once a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool. Some say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew. I suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.", ["objectivesText"] = "Use the Scouting Map and complete five \"Freya's Spring\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41911] = { ["id"] = 41911, ["name"] = "Amaranthine Hops", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 709, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "The hops for our brew must be a very specific, and they will also be hard to acquire. Amaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid. There is one such supplier from whom I receive this item, but she may ask for something in exchange.", ["objectivesText"] = "Speak to Fleuris Asterleaf in Val'sharah and trade 20 Stonehide Leather for 1 bag of Amaranthine Hops . Progress: Did you find Fleuris?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 139033, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41916] = { ["id"] = 41916, ["name"] = "A Better Future", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "We must move quickly, <name>. I must save as many of my people as I can before the attack begins. Word has gotten out in the city that there is a safe haven with us and some no longer fear exile. Venture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.", ["objectivesText"] = "Rescue 8 Shal'dorei Insurgents in the Grand Promenade. Progress: Each shal'dorei rescued is both a potential enemy vanquished and a new hope for our people.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 208067, 208937, 211366, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.408667, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41918] = { ["id"] = 41918, ["name"] = "The Dreamer Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 40647, 41468, 41782, 41783, 41790, 41791, 41792, 41918 }, ["description"] = "Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone. I can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth! Our paths will cross again, <name>. Be sure of it.", ["objectivesText"] = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 104535, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 167, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["db2QuestSortName"] = "Battle Pets", ["questLines"] = { { ["id"] = 167, ["name"] = "The Claws of Ursoc", ["orderIndex"] = 7, ["flags"] = 0 } } },
[41919] = { ["id"] = 41919, ["name"] = "The Shadows Reveal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive. <Valeera scrawls a few lines on a piece of paper, then hands it to you.> But not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes. Go to each contact and tell them \"The shadows reveal.\" See what they know.", ["objectivesText"] = "Speak to your contacts in Dalaran to acquire intel on Akaari Shadowgore's whereabouts. Progress: Hmm?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136602, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41920] = { ["id"] = 41920, ["name"] = "A Matter of Finesse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "A rune of portals ?! Who does Val'zuun think he is? <Valeera takes a deep breath.> It's worth the price, but those runes aren't exactly easy to come by. Unless... Archmage Celindra , the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were... <Valeera smirks.> But who said anything about asking?", ["objectivesText"] = "Borrow a Rune of Portals from Archmage Celindra . Progress: They say the Fangs of the Devourer have no equal. If that's true, they're worth any price.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 17032, 127837, 128476, 128479, 128870, 128872, 136603, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41921] = { ["id"] = 41921, ["name"] = "Closing In", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area. Come prepared for a fight. Akaari won't go down easily.", ["objectivesText"] = "Confront Akaari Shadowgore in the Legerdemain Lounge. Progress: I can't believe it...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 66933, 66934, 66935, 127837, 128476, 128479, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 195196, 195197, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41922] = { ["id"] = 41922, ["name"] = "Traitor!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "That lying demon SCUM! I should have known. Let's show Val'zuun what happens to people who dare cross the Uncrowned.", ["objectivesText"] = "Join Valeera Sanguinar in the Underbelly Descent.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 22980, 22982, 22984, 22995, 44358, 44359, 44360, 44361, 59171, 59172, 59173, 63912, 63913, 63914, 63915, 63916, 113232, 113233, 113234, 113235, 127837, 128476, 128479, 128870, 128872, 131466, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 155462, 155471, 155479, 155487, 156941, 158599, 158600, 158601, 158602, 180900, 180913, 180914, 180915, 182251, 182260, 182269, 182278, 237812, 248065, 248069, 250355, 251330, 251548 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41924] = { ["id"] = 41924, ["name"] = "Fangs of the Devourer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 740, ["storyline"] = { 41919, 41920, 41921, 41922, 41924 }, ["description"] = "If you spare me I can use the rune of portals you provided to open a gateway to Akaari's citadel in the Twisting Nether. Of course, killing the Legion's master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no? < Val'zuun smiles.> I will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.", ["objectivesText"] = "Obtain the Fangs of the Devourer from Akaari Shadowgore. Progress: Any luck?", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 136802, 139506, 139739, 139742, 139746, 140517, 140931, 152789, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 163, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1607, ["db2PoiUiMapID"] = 740, ["questLines"] = { { ["id"] = 163, ["name"] = "The Fangs of the Devourer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41934] = { ["id"] = 41934, ["name"] = "The Brand of Damnation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8125, ["mapID"] = 738, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41773, 41774, 41888 }, ["description"] = "I require a symbol of my dominion as Firelord. A weapon that will strike fear into the hearts of all who dare to oppose my rule! Deep within the den of the Cinderweb, there is an ancient spear born from within the heart of the Firelands. Emberscar is a living weapon whose wicked power is beyond mortal comprehension. Prove your strength and claim Emberscar in my name! If you survive, perhaps I will aid the feeble races of humanity against the Burning Legion.", ["objectivesText"] = "Retrieve Emberscar, Brand of Damnation . Progress: The Brand of Damnation will be mine!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 136604, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1605, ["db2PoiUiMapID"] = 738, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 11, ["flags"] = 0 } } },
[41945] = { ["id"] = 41945, ["name"] = "Tianji of the Ox", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked. I suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Tianji Needs Help\". Progress: How is the mission proceeding?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41946] = { ["id"] = 41946, ["name"] = "Building Our Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox. She is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils. Speak to her now and train an initiate of the ox.", ["objectivesText"] = "Speak to Recruiter Tianji and train an Ox Initiate. Progress: How did the training go?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 10, ["flags"] = 0 } } },
[41957] = { ["id"] = 41957, ["name"] = "The Vindicator's Plea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I've obtained a request from Vindicator Boros in Dalaran asking for our help. He has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost! You are strong with the Light, perhaps you can succeed where they can't? If you need it, Brother Larry can provide you with a flight to Dalaran.", ["objectivesText"] = "Meet with Vindicator Boros in front of First to Your Aid in Dalaran.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 101314, ["x"] = 0.79, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41966] = { ["id"] = 41966, ["name"] = "House Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there. I was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei. There is something about those wounds that resists everything we've done to treat them. Please, <class>, as a brother in the Light I ask you to do all that you can to help him to recover.", ["objectivesText"] = "Treat the wounds of Defender Barrem .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 173379, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41967] = { ["id"] = 41967, ["name"] = "Out of the Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us. The portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora ... she tripped and I watched them drag her back. Rescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.", ["objectivesText"] = "Travel to Darkstone Isle near the Broken Shore and search for Alora .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 25549, 26010, 26024, 26036, 38734, 39033, 39060, 39098, 42846, 42861, 42870, 42881, 42895, 44018, 44039, 44041, 44042, 44043, 62849, 62850, 62851, 64594, 64604, 64613, 64620, 64625, 64629, 64632, 64634, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648, 65813, 65814, 84060, 84061, 84062, 84063, 84064, 98133, 113169, 113170, 113171, 113172, 113173, 113174, 113175, 113176, 119036, 128825, 128827, 128868, 131271, 131640, 139506, 139757, 139759, 140517, 140930, 151493, 157013, 169905, 171354, 171355, 174288, 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184165, 184378, 184381, 184382, 184383, 184384, 184519, 211279, 237812, 237890, 237893, 245345, 246951, 257143, 263282, 263461, 265106, 265631 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 105684, ["x"] = 0.34, ["y"] = 0.338 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41993] = { ["id"] = 41993, ["name"] = "Salvation From On High", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure! All my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!", ["objectivesText"] = "Something unexpected has interrupted your discussion, deal with it!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 105684, ["x"] = 0.34, ["y"] = 0.338 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 106011, ["x"] = 0.330667, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42000] = { ["id"] = 42000, ["name"] = "Seeker of Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["series"] = { 42002 }, ["description"] = "You may be familiar with Orik Trueheart . He has devoted his time after the Northrend campaign to learning more about Tyr. Orik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out. Please speak to him immediately.", ["objectivesText"] = "Speak with Orik Trueheart in Dalaran. Progress: I'm glad yer in. We've quite the journey ahead.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42001] = { ["id"] = 42001, ["name"] = "Aluneth, Greatstaff of the Magna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 627, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42003, 42006, 42007, 42008, 42009, 42010, 42011 }, ["description"] = "Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic. When Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken. The dragon Kalec may be our best chance. He now resides on the Council of Six.", ["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127857, 128820, 128862, 136694, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42002] = { ["id"] = 42002, ["name"] = "To Northrend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 117, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["series"] = { 42000 }, ["description"] = "Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord. Tahu can help locate the grave, and with a short ritual we should have our answers! Meet us at Shield Hill in the Howling Fjord and we'll move on to the next step.", ["objectivesText"] = "Meet Orik Trueheart on Shield Hill in Howling Fjord.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 89125, 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 105724, ["x"] = 0.568, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 117, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42005] = { ["id"] = 42005, ["name"] = "The End of the Saga", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["description"] = "Ye should read the saga yerself, it's right here. We're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak. You should speak with Tahu so we can get started.", ["objectivesText"] = "Get the end of the story from the spirit of the saga hero.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 136710, 139506, 139690, 139693, 139697, 140192, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 105724, ["x"] = 0.568, ["y"] = 0.786 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.786 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42006] = { ["id"] = 42006, ["name"] = "A New Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 115, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42007, 42008, 42009, 42010, 42011 }, ["description"] = "If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding. During my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus. Here, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.", ["objectivesText"] = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus. Progress: The communication device is inactive.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 128868, 136410, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42007] = { ["id"] = 42007, ["name"] = "A Forgotten Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42008, 42009, 42010, 42011 }, ["description"] = "The device still hums with power. It must have been abandoned not long ago. The nearby switch appears to activate it.", ["objectivesText"] = "Activate the Ethereal Communication Device at the Azure Dragonshrine.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42008] = { ["id"] = 42008, ["name"] = "Eyes of the Dragon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 114, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42009, 42010, 42011 }, ["description"] = "You should travel at once to Coldarra in Borean Tundra, <name>. There, I would recommend you scout out a few key locations and report back to me. I know the area well, and should be able to tell you how to proceed. Make haste!", ["objectivesText"] = "Scout out the key locations in Coldarra.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 136410, 173430, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192030, 192034, 192037, 193477, 197935, 197953, 197956, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42009] = { ["id"] = 42009, ["name"] = "Harnessing the Arcane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 114, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42008, 42010, 42011 }, ["description"] = "The energy from Aluneth lashes out from within the weakened Nexus Vault. We may be able to use this raw, chaotic energy to our advantage. If we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", ["objectivesText"] = "Empower yourself with Unstable Arcane Energy by defeating Arcane Aberrants or siphoning from Breaches of Arcane Energy around the foundation of the Nexus.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 136410 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42011] = { ["id"] = 42011, ["name"] = "The Nexus Vault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42001, 42006, 42007, 42008, 42009, 42010, 42011 }, ["series"] = { 42001, 42003, 42006, 42007, 42008, 42009, 42010 }, ["description"] = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. We have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip. With the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, <name>.", ["objectivesText"] = "Defeat Nexus-Prince Bilaal and claim Aluneth, Greatstaff of the Magna.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 113509, 118006, 127834, 127857, 128820, 128862, 136410, 141446, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 166, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 166, ["name"] = "Aluneth, Greatstaff of the Magna", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42017] = { ["id"] = 42017, ["name"] = "Shrine of the Truthguard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42000, 42002, 42005, 42017 }, ["description"] = "We'll be flying straight to the island. My friend said that the warrior who came here before us never entered the shrine itself, since they were after one of the tombs. If a vrykul hero couldn't enter the shrine, I bet it's still protected by Tyr's power. I'm thinkin' we have a good shot at this. My pal Cato will meet us there. We might be needin' the talents of a good healer!", ["objectivesText"] = "Go to Shield's Rest in Stormheim and claim the Truthguard.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 221, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 221, ["name"] = "Truthguard", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42031] = { ["id"] = 42031, ["name"] = "Dire Growth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42032, 42033 }, ["description"] = "Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.", ["objectivesText"] = "Meet with Naralex, plant the Lasher Seed, and analyze its effects. Progress: I have never seen anything like this...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42032] = { ["id"] = 42032, ["name"] = "Sampling the Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42031, 42033 }, ["description"] = "There is still so much that we don't know about the Nightmare. Before we can fight it, we must understand how it spreads. Let us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.", ["objectivesText"] = "Complete the mission, \"Sampling the Nightmare.\"", ["rewardGold"] = 232300, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42033] = { ["id"] = 42033, ["name"] = "Malorne's Refuge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42031, 42032 }, ["description"] = "I see... it is as we have always feared. The Emerald Nightmare has found our world. We must call upon the ancient god, Malorne. Travel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself. I already sent Broll Bearmantle ahead to give word of your arrival.", ["objectivesText"] = "Speak to Broll Bearmantle at Malorne's Refuge in Val'sharah.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 105903, ["x"] = 0.57, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42034] = { ["id"] = 42034, ["name"] = "Grip of Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42035 }, ["description"] = "Most of the druids were able to escape, but the shrine is still swarming with enemies. The shrine's leader, Sylendra Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.", ["objectivesText"] = "Kill 5 Darkfiend Raiders , rescue Sylendra Gladesong , and examine the Altar of Malorne.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 105903, ["x"] = 0.57, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 105948, ["x"] = 0.569333, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42035] = { ["id"] = 42035, ["name"] = "Tracking the Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["series"] = { 42034 }, ["description"] = "The Idol may be stolen, but there is still hope. While I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh. With our heightened senses, we may still be able to pick up their trail. We must follow their signs through the forest and recover the Idol!", ["objectivesText"] = "Use your Cat Form to follow the satyr's tracks.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 105948, ["x"] = 0.569333, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 106883, ["x"] = 0.598, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.569333, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42036] = { ["id"] = 42036, ["name"] = "Idol of the Wilds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40654, 42031, 42032, 42033, 42034, 42035, 42036, 42038, 42039 }, ["description"] = "We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere. Surely one of these satyrs will know where it was taken. Get the information out of these satyrs, even if it's the last thing they do.", ["objectivesText"] = "Attack 6 Darkfiend Satyr and extract information about the Idol of the Wilds . Progress: Did you recover the Idol of the Wilds ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 97919, 136804, 137663, 140517, 140925, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 106883, ["x"] = 0.598, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5883, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5883, ["name"] = "The Eternal Dream I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42037] = { ["id"] = 42037, ["name"] = "Gathering the Dreamweavers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids. Send your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.", ["objectivesText"] = "Retrieve druids by completing \"Gathering the Dreamweavers\" missions.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 0, ["flags"] = 0 } } },
