[42065] = { ["id"] = 42065, ["name"] = "The Twilight Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41777, 41897, 41898, 41899 }, ["description"] = "There is only one more thing that remains, Farseer <name>. We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all. Without their so-called master, the remaining cultists will be forced to retreat from Deepholm. Only when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.", ["objectivesText"] = "Defeat the Mistress of Twilight .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42068] = { ["id"] = 42068, ["name"] = "The Return of Twilight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41775, 41901, 42200 }, ["description"] = "The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly. I cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it. Go. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!", ["objectivesText"] = "Speak with Muln Earthfury in Deepholm.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 105995, ["x"] = 0.614667, ["y"] = 0.512667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42074] = { ["id"] = 42074, ["name"] = "Return of the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 41957, 41966, 41967, 41993, 42074 }, ["description"] = "Excellent! There is a gateway further down this pathway and like most Legion constructs it is powered by souls. I think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from. Let's go see where the path takes us, shall we?", ["objectivesText"] = "Accompany Jace Darkweaver through the portal and obtain T'uure, Beacon of the Naaru.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 106011, ["x"] = 0.330667, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.330667, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 243, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 243, ["name"] = "T'uure", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42079] = { ["id"] = 42079, ["name"] = "Masquerade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 42147 }, ["description"] = "Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra's return. You must walk among the nightborne. You must earn the trust of our friends and foes alike. You must become someone else. <Ly'leth hands you a shimmering party mask.> Put this on Anarys.", ["objectivesText"] = "Use the Mask of Mirror Image on Anarys Lunastre . Progress: Not to worry, it will not hurt him.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 129979, 136600, 136970, 141947, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42081] = { ["id"] = 42081, ["name"] = "In With the New", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["description"] = "Well, here's your new conduit. Try not to break this one, I really don't feel like making another. Oh, and tell your boss, Deucus, that he owes me big time for this.", ["objectivesText"] = "Bring the newly forged High-Capacity Decoction Conduit to Deucus in Dalaran.", ["rewardGold"] = 561800, ["rewardXP"] = 6140, ["rewardItems"] = { 37074, 37354, 37440, 37519, 37529, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127915, 128209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 32, ["flags"] = 0 } } },
[42088] = { ["id"] = 42088, ["name"] = "Evacuate Snowmane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42512 }, ["description"] = "They just keep coming! And now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village. Go, help the evacuation. We will hold the line here and try to buy you some time.", ["objectivesText"] = "Evacuate Red Skymane , Tarvim Daywalker , and Old Nefu . Progress: I knew we should have secured this town better.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 4, ["flags"] = 0 } } },
