[42097] = { ["id"] = 42097, ["name"] = "Searching the Archives", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 39142, 39179, 39389, 40218, 41759, 41767, 42097 }, ["description"] = "The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. It's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. The search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.", ["objectivesText"] = "Interact with the Dreadscar Battle Plans and complete the mission \"Searching the Archives\". Progress: Have the archives been searched yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5873, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5873, ["name"] = "Rebuilding the Council I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42098] = { ["id"] = 42098, ["name"] = "Black Rook Hold: An Unclaimed Soul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul . The soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift. Shinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. Dwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.", ["objectivesText"] = "Collect an Unclaimed Soul from The Amalgam of Souls in the Black Rook Hold dungeon. Progress: Have you recovered the soul yet?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128941, 128942, 128943, 138988, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42100] = { ["id"] = 42100, ["name"] = "Empowering the Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41752, 41753, 41768, 41769, 41780, 41781, 41784, 41798, 42098, 42100 }, ["description"] = "Creating the anchor will require more power than our soul shards will be able to provide. Dreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.", ["objectivesText"] = "Collect Empowered Soul Shards by completing class hall missions. Progress: With enough soul shards, we should have the power to create the anchor.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 136834, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5874, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5874, ["name"] = "Rebuilding the Council II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42102] = { ["id"] = 42102, ["name"] = "One Who's Worthy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["series"] = { 41785, 41787, 41788, 41793, 41795, 41796 }, ["description"] = "If we wish to successfully summon the sisters, we'll need the help of a warlock who is skilled in summoning greater demons. We cannot afford to lose another council member due to inexperience. The Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. Hopefully among them we can find one worthy of this council.", ["objectivesText"] = "Interact with the Scouting Map and complete the missions, \"One Who's Worthy\".", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 180847, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181708, 181842, 182126, 182338, 182460, 182480, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 184147, 184150, 184587, 184777, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42103] = { ["id"] = 42103, ["name"] = "Let it Feed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it. The stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.", ["objectivesText"] = "Kill demons throughout the Broken Isles and collect their blood. Progress: We will need to feed the Bloodstone before it will be strong enough to control the eredar sisters.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 128941, 128942, 128943, 138991, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42104] = { ["id"] = 42104, ["name"] = "The Underking Comes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38909, 39025, 39026, 39027, 39043, 39498, 42104 }, ["series"] = { 39277, 39487, 39488, 39489, 39498, 39661 }, ["description"] = "Here, I'm too slow to get these laggards to safety. Take my horn and sound the evacuation. We need to get the people out of here before the drogbar arrive. The warbraves can take it from there. For now just send them over to Spiritwalker Ebonhorn . That fool can watch over them until it is safe.", ["objectivesText"] = "Evacuate Riverbend. Progress: Well, this is an unexpected pleasure.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 69777, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97662, ["x"] = 0.484, ["y"] = 0.804 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93805, ["x"] = 0.386, ["y"] = 0.687 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.804 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 89, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 89, ["name"] = "Riverbend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42107] = { ["id"] = 42107, ["name"] = "On the Trail of the Great Worm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "We need the Gjallarhorn to compel the armies of Odyn's children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!", ["objectivesText"] = "Complete the mission \"On the Trail of the Great Worm.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42110] = { ["id"] = 42110, ["name"] = "To the Summit!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 650, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "Your armies have tracked the beast to the highest peak in Highmountain. It has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!", ["objectivesText"] = "Go to Highmountain Summit.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42114] = { ["id"] = 42114, ["name"] = "The Ritual of Tides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 42188 }, ["description"] = "Long ago, the first Farseer of the Earthen Ring was given a vision of the elements. In the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements. <name>, I believe that you are the Farseer of this prophecy, called to lead before you were ever born. The time has come to fulfill your destiny! When you are ready, we will perform the Ritual of Tides and call upon Neptulon , the first of the four great Elemental Lords.", ["objectivesText"] = "Perform the Ritual of Tides in the Maelstrom. Progress: The time has come to fulfill your destiny, Farseer <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42120] = { ["id"] = 42120, ["name"] = "The Silver Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42120, 42231, 42377 }, ["series"] = { 42377 }, ["description"] = "Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer. Tyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us. Take the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.", ["objectivesText"] = "Go to Tyr's Fall in Tirisfal Glades and recover the Silver Hand . Progress: At last it is done.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 173523, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 222, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 222, ["name"] = "The Silver Hand", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42125] = { ["id"] = 42125, ["name"] = "Dark Whispers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 42125, 42168 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42128, 42168, 42939, 42952, 43181 }, ["description"] = "Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in! There is a portal that my kind use to haul in treasures, with it you can get in and find the skull!", ["objectivesText"] = "Use Calydus 's portal to enter into Felsoul Hold and recover the Skull of the Man'ari.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 245, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 245, ["name"] = "Skull of the Man'ari", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42126] = { ["id"] = 42126, ["name"] = "Archmage Omniara", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42127, 42175, 42663, 42687, 42696, 42703 }, ["description"] = "Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked. Send Archmage Kalecgos to help her. He will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Omniara Needs Help\" Progress: How is the mission proceeding?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42127] = { ["id"] = 42127, ["name"] = "Building Our Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42126, 42175, 42663, 42687, 42696, 42703 }, ["description"] = "Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order. She is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us. Speak to her now, and recruit her elementals.", ["objectivesText"] = "Speak to Archmage Omniara and recruit some of her Water Elementals Progress: How did the training go?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42128] = { ["id"] = 42128, ["name"] = "Ritual Reagents", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42128 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42168, 42939, 42952, 43181 }, ["description"] = "The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord! There is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead! We will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst. Oh, and blood! I sense a beast whose blood should be perfect.", ["objectivesText"] = "Search within Dalaran for Grave Dust , a Can of Overheated Oil , an Aged Snowplum Brandy , and a Stag Blood Sample . Progress: Did you obtain everything, friend?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 136983, 136985, 136986, 136987, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 245, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 245, ["name"] = "Skull of the Man'ari", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42129] = { ["id"] = 42129, ["name"] = "The Pendant of Starlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To finish my work here, I will need a magical item called the Pendant of Starlight . For centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it! This pendant stores a great amount of arcane power... power I can use to heal the grove. Get it back, and I will be very grateful!", ["objectivesText"] = "Retrieve the Pendant of Starlight from Abyssal Queen Sha'rathra, who patrols along the coast of Val'sharah. Progress: Was there much killing?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 15885, 139374, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 17, ["flags"] = 1 } } },
[42131] = { ["id"] = 42131, ["name"] = "Unexpected Visitors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "Brace yourself, <name>. I am detecting a strange magic forming in the chamber. Something is projecting itself in.", ["objectivesText"] = "Listen to your unexpected visitors. Progress: Caria and Varedis Felsoul are like a bad copper piece that keeps coming back.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 140924, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42132] = { ["id"] = 42132, ["name"] = "Last, But Not Least", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42809, 42920, 43186 }, ["description"] = "I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions. The two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.", ["objectivesText"] = "Recruit Allari the Souleater and Jace Darkweaver as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42133] = { ["id"] = 42133, ["name"] = "Same Day Delivery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42657, 42658, 42659 }, ["description"] = "I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons. While I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.", ["objectivesText"] = "Return to Emmarel Shadewarden at Trueshot Lodge. Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138303, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42134] = { ["id"] = 42134, ["name"] = "Recruiting More Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["description"] = "Our champions acquired the talents of Recruiter Sampson , an extraordinary tracker. He has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed. Speak to him now.", ["objectivesText"] = "Speak to Recruiter Sampson .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 106446, ["x"] = 0.574, ["y"] = 0.3296 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 2, ["flags"] = 0 } } },
