[42139] = { ["id"] = 42139, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42140, 43007, 43013, 43014, 43015 }, ["description"] = "The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible. We have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done. Might I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.", ["objectivesText"] = "Recruit Garona Halforcen and Vanessa VanCleef as your first champions.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42140] = { ["id"] = 42140, ["name"] = "A More Wretched Hive of Scum and Villainy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 43007, 43013, 43014, 43015 }, ["description"] = "Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types? I know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade. Yeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City. So, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"A More Wretched Hive of Scum and Villainy\". Progress: So, what'd Lonika say?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42141] = { ["id"] = 42141, ["name"] = "Summoner Morn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles. The first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked. I suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Morn Needs Help\". Progress: How is the mission proceeding?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42142] = { ["id"] = 42142, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "Our champions acquired the talents of Summoner Morn, a powerful shaman. He is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause. Speak to him now and train a Lesser Elemental .", ["objectivesText"] = "Speak to Summoner Morn and summon a Lesser Elemental . Progress: How did the training go?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42149] = { ["id"] = 42149, ["name"] = "Some Knowledge Shouldn't Be Shared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["description"] = "I noticed that quite a few of the Empyrean Society's books are inscribed with fel magic. That's blasphemous. We must confiscate as many as we can.", ["objectivesText"] = "Collect 5 Empyrean Fel Tomes . Progress: I hope we've found all of the books.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 127857, 128820, 128862, 136981, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42158] = { ["id"] = 42158, ["name"] = "The Creator's Workshop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8161, ["mapID"] = 745, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["description"] = "My remote observation relay captured an astonishing amount of data from that tomb. If we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it. Since you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!", ["objectivesText"] = "Assist Mimiron . Progress: Remember, anything is science if you write it down!", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8161 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42166] = { ["id"] = 42166, ["name"] = "What Is Going On Here?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42418, 42433, 42434, 42435 }, ["description"] = "We don't know much about the Empyrean Society's activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. Let's meet up at the rotunda on the hill.", ["objectivesText"] = "Question 5 Empyrean Society members and investigate their grounds. Progress: What do you think they are up to?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106530, ["x"] = 0.648667, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648667, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42168] = { ["id"] = 42168, ["name"] = "Looking into the Darkness", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9, 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42125, 42168 }, ["series"] = { 40495, 40588, 40604, 40606, 40611, 40623, 40712, 40731, 40823, 41155, 41156, 42125, 42128, 42939, 42952, 43181 }, ["description"] = "Friend now is ready to perform the ritual! Remember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.", ["objectivesText"] = "Perform the ritual to commune with the Skull of the Man'ari and convince it to tell you its location. Progress: The ritual circle is ready, friend.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 245, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 245, ["name"] = "Skull of the Man'ari", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42171] = { ["id"] = 42171, ["name"] = "Final Exit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42222, 42416, 42423, 42424, 42451, 42508, 42521 }, ["description"] = "We've certainly reduced the Empyrean Society's numbers. I don't think they'll be luring any more members to their cause for a while. There's only one place we haven't investigated, and I suspect that rune we found is attuned to the door. Let's see what's inside the building.", ["objectivesText"] = "Use the Rune of Opening to unlock the Empyrean Society building door. Progress: I thought I'd snoop around a bit before I met you at the rotunda. Unfortunately my invisibility spell wore off at an inopportune time. I'm glad you found me! What is this you have found, <name>?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 127857, 128820, 128862, 137210, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 106530, ["x"] = 0.648667, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648667, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42175] = { ["id"] = 42175, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 735, ["storyline"] = { 41035, 41036, 41085, 41112, 41113, 41114, 41124, 41141, 42126, 42127, 42175, 42662, 42663, 42685, 42687, 42696, 42703 }, ["series"] = { 42126, 42127, 42663, 42687, 42696, 42703 }, ["description"] = "The Tirisgarde has need of your help now that you have grown in strength, <name>. Meet me in the Hall of the Guardian when you are done with your adventures.", ["objectivesText"] = "Meet Meryl Felstorm in the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5867, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5867, ["name"] = "The Tirisgarde Reborn", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42184] = { ["id"] = 42184, ["name"] = "Mission: Elemental Diplomacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["series"] = { 41770, 41771 }, ["description"] = "The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains. For the next step of our campaign, I have organized a diplomatic mission to Skywall. The goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al'Akir the Windlord, and to identify any elementals who would aid our cause. The mission is currently waiting your assignment.", ["objectivesText"] = "Successfully complete the \"Elemental Diplomacy\" mission.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42185] = { ["id"] = 42185, ["name"] = "Never Hunt Alone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8161, ["mapID"] = 627, ["storyline"] = { 41541, 41574, 42158, 42185 }, ["description"] = "Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark. If my deductions are correct, she'll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves! Hopefully Thorim isn't off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.", ["objectivesText"] = "Seek out Thorim at the Temple of Storms and recover Titanstrike.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 128808, 128826, 128861, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8161 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 165, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 165, ["name"] = "Titanstrike", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42186] = { ["id"] = 42186, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 42187 }, ["description"] = "Iron-Body Ponshu has requested your presence. Our campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.", ["objectivesText"] = "Speak to Iron-Body Ponshu at the Wandering Isle.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42187] = { ["id"] = 42187, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 42186 }, ["description"] = "We are still recovering from the attack at the Peak of Serenity. To help us rebuild the order, we should enlist the greatest champions of our class to fight by our side. I know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu .", ["objectivesText"] = "Enlist Chen Stormstout and Li Li Stormstout, then speak to Master Hsu .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42188] = { ["id"] = 42188, ["name"] = "Nobundo Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["series"] = { 42114 }, ["description"] = "Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer. A great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I'll take care of things here. Nobundo is waiting for you now. May the elements be with you, Farseer.", ["objectivesText"] = "Speak with Nobundo in the Heart of Azeroth.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42191] = { ["id"] = 42191, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["series"] = { 41905 }, ["description"] = "Thanks to you, the Order of the Broken Temple is gradually re-assembling. However, there is much more work to do. As our leader, you can determine the trajectory of our order's future. Speak to Number Nine Jia. She will show you the ropes.", ["objectivesText"] = "Speak to Number Nine Jia.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 12, ["flags"] = 1 } } },
[42193] = { ["id"] = 42193, ["name"] = "The Gjallarhorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["series"] = { 43750 }, ["description"] = "You have proven yourself most thoroughly time and again, <name>. There can be no doubt that you are the one to lead Odyn's armies into the final battle. You must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us. King Svergan Stormcloak was the last known living guardian of the horn. Seek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.", ["objectivesText"] = "Find Svergan Stormcloak .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42194] = { ["id"] = 42194, ["name"] = "Stolen Honor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "Safeguarding the Gjallarhorn was my duty, <race>. I will do what is right, but first I must ask for your aid. My family was disavowed by the mystics of our time and this grave was ransacked. I cannot find peace while my family heirlooms are in the hands of the servants of the false God-King. Return them to me and I will aid you in finding the Gjallarhorn!", ["objectivesText"] = "Svergan Stormcloak wants you to obtain the Crown of the Forgotten King , the Stormcloak Signet and the Drakerider's Medallion in the Runewood. Progress: Do you bring back my family's heirlooms, <race>?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 137182, 137183, 137184, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 2, ["flags"] = 0 } } },
