[42200] = { ["id"] = 42200, ["name"] = "Mission: Investigating Deepholm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["series"] = { 41775, 41901, 42068 }, ["description"] = "In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us. Therazane has been absent from our negotiations with the elements thus far. There have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid. I have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.", ["objectivesText"] = "Successfully complete the \"Investigating Deepholm\" mission.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42202] = { ["id"] = 42202, ["name"] = "Revenge, Served Cold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared. Help me avenge my people and I will aid you in your quest to find Jorhuttam.", ["objectivesText"] = "Slay Dogrub the Cruel, Urgrul Skullcleaver and 8 Frostcrag Drogbar in Highmountain Summit. Progress: You return.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42204] = { ["id"] = 42204, ["name"] = "Jorhuttam", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "You upheld your end of your promise. I will do the same. Take these drogbar drums. Then bang on them to call upon Jorhuttam to feast. Find the Great Worm's feeding mound and use the drums to lure her out.", ["objectivesText"] = "Use the Frostcrag Drums near Jorhuttam's Feeding Mound and slay Jorhuttam to obtain the Gjallarhorn . Progress: The Gjallerhorn, <name>. Is it finally in your possession?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 138205, 139501, 140517, 140933, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 106271, ["x"] = 0.538, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42206] = { ["id"] = 42206, ["name"] = "The Next Level Has Arrived", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["description"] = "The Empyrean Society is certainly much more dangerous than they appear. It's unimaginable that any mage would study fel magic -- that's for warlocks and the Legion! Since our friend, Ravandwyr, appears to be delayed, it looks like we'll have to deal with this ourselves. We should remove this sect so they can't corrupt anyone else.", ["objectivesText"] = "Kill 10 Empyrean Society members. Progress: Do you think we've reduced their numbers enough?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 137190, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42208] = { ["id"] = 42208, ["name"] = "Return to the Firelands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["series"] = { 41772, 41900 }, ["description"] = "The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer. Ragnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression. I have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there. If the mission is successful, we may find the information we need to bring the Firelands into our fold.", ["objectivesText"] = "Complete the \"Return to the Firelands\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42210] = { ["id"] = 42210, ["name"] = "Scrolls of Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 12103, 40236, 40636, 40704, 40793, 40795, 41115, 41945, 41946, 42186, 42187, 42191, 42210 }, ["description"] = "Our troops are ready! It's time to test them out in the field, and I have the perfect assignment. Number Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many of her important scrolls were left behind during the attack on the Peak of Serenity. Send our champions to retrieve these documents at once!", ["objectivesText"] = "Complete the mission, \"Scrolls of Knowledge.\" Progress: How did it go?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5877, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5877, ["name"] = "The Broken Temple", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42213] = { ["id"] = 42213, ["name"] = "Eye of Azshara: The Tidestone of Golganneth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8040, ["mapID"] = 627, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37470, 38286 }, ["description"] = "<Now that you have defeated Queen Azshara's Wrath and have the Tidestone in hand, it is time to place it in the Portrait Room of the Chamber of the Guardian in lower Dalaran .>", ["objectivesText"] = "Use the central teleporter in Dalaran and then place the Tidestone of Golganneth in the Portrait Room of the Chamber of the Guardian.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 137206, 140622, 140623, 140624, 140625, 237812, 246812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8040 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 19, ["flags"] = 1 } } },
[42214] = { ["id"] = 42214, ["name"] = "Knocked for a Loop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "While you're focused on murlocs... Many murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use. Collect some of their jewelry and bring it back to me. The wetter, the better!", ["objectivesText"] = "Collect 10 Salteye Bangles . Progress: I could see how jewelry on a murloc might make it seem more attractive...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 132370, 132467 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100538, ["x"] = 0.466, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42220] = { ["id"] = 42220, ["name"] = "Shipwrecked Sailors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37654, 37657, 37659, 40794, 42220 }, ["description"] = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.> <It looks like the sailors are being poisoned and worse. Best to put them out of their misery.>", ["objectivesText"] = "Put 10 Queen's Reprisal Sailors out of their misery.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 3, ["flags"] = 1 } } },
[42222] = { ["id"] = 42222, ["name"] = "Empyrean Society Report", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42171, 42416, 42423, 42424, 42451, 42508, 42521 }, ["description"] = "I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... Regardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.", ["objectivesText"] = "Return to the Hall of the Guardian.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 140927, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106530, ["x"] = 0.648667, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648667, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42223] = { ["id"] = 42223, ["name"] = "Scouting the Crimson Thicket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["description"] = "If you are heading east, there is something I would ask of you. While we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long. I would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.", ["objectivesText"] = "Find Lilryia Dawnwind in Dawncleft.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 139791, 140240, 140251, 141941, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103571, ["x"] = 0.283, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.283, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42224] = { ["id"] = 42224, ["name"] = "Cloaked in Moonshade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 40324, 40325, 42225 }, ["description"] = "I do not know what Theryn found, but I know where he found it. Moonshade Sanctum, to the west. Beyond the Temple of Fal'adora. Whatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. I know this as surely as if I had been there myself.", ["objectivesText"] = "Explore Moonshade Sanctum.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 2, ["flags"] = 0 } } },
