[42228] = { ["id"] = 42228, ["name"] = "The Hidden City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 42226, 42227, 42230 }, ["description"] = "Orathiss has underestimated the seed. It is sapping her power - slowing her down. We must catch her and get the seed to safety!", ["objectivesText"] = "Follow Orathiss through Falanaar Tunnels and slay her.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 6, ["flags"] = 0 } } },
