[42230] = { ["id"] = 42230, ["name"] = "The Valewalker's Burden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40324, 40325, 42224, 42225, 42226, 42227, 42228, 42230 }, ["series"] = { 42226, 42227, 42228 }, ["description"] = "The seed is awakening. Without power it will quickly wither and die. We must carry the seed out of here and plant it somewhere safe. I am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. Please take the seed.", ["objectivesText"] = "Activate the Fal'adora Beacon in Temple of Fal'adora.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140328, 141950, 237812, 246812, 246815, 246937, 249783, 254267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 158, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 158, ["name"] = "An Ancient Gift", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42231] = { ["id"] = 42231, ["name"] = "The Mysterious Paladin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 23, ["storyline"] = { 42120, 42231, 42377 }, ["description"] = "It appears we have been afforded a unique opportunity. A small order of paladins has come forward claiming to know the location of Tyr's tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled. I'd like you to speak with Travard , their leader, to find out more about this artifact.", ["objectivesText"] = "Speak with Travard in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 222, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 222, ["name"] = "The Silver Hand", ["orderIndex"] = 0, ["flags"] = 0 } } },
