[42244] = { ["id"] = 42244, ["name"] = "Fate of the Queen's Reprisal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 627, ["storyline"] = { 37654, 37657, 37659, 42244, 42268 }, ["description"] = "<This is the kind of intelligence that should be shared. Perhaps someone at the Windrunner's Sanctuary on Dalaran will know what to do with it.>", ["objectivesText"] = "Take the Captain's Log to Advisor Stillwater at the Windrunner's Sanctuary on Dalaran. Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 121488, 122570, 138859, 138860, 138861, 138862, 141403, 237812, 246937 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42268] = { ["id"] = 42268, ["name"] = "Shipwrecked Sailors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 630, ["storyline"] = { 37654, 37657, 37659, 42244, 42268 }, ["description"] = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.> <The sailors are being treated very poorly. It looks like a rescue operation is in order.>", ["objectivesText"] = "Rescue 10 Queen's Reprisal Sailors.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5756, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5756, ["name"] = "Mak'rana and the Fate of the Queen's Reprisal", ["orderIndex"] = 2, ["flags"] = 1 } } },
[42271] = { ["id"] = 42271, ["name"] = "Their Dying Breaths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 37991 }, ["description"] = "I have precious little time. As we speak, my troops are defending against an onslaught of withered elves. These four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear. Some cracked ley crystals should bring them back to their senses.", ["objectivesText"] = "Obtain 4 Cracked Ley Crystals , then use them to resuscitate the Mana-Drained Whelplings . Progress: Oh no...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121423, 121424, 121425, 121426, 121481, 122292, 122306, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90543, ["x"] = 0.488, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89975, ["x"] = 0.478, ["y"] = 0.266 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42365] = { ["id"] = 42365, ["name"] = "Focusing the Energies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln. This rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", ["objectivesText"] = "Collect 3 Blood of Sargeras . Progress: Were you able to find the Blood of Sargeras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42367] = { ["id"] = 42367, ["name"] = "Arkethrax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["description"] = "Within the Ingress is a demon who must die. Arkethrax is a creature of cunning evil. If left unchecked he will be able to use the Ingress as a staging point for targeted assaults that will decimate our forces. I, for one, have no intention of underestimating this opponent and shall join you on the battlefield when you are ready to fight him.", ["objectivesText"] = "Slay Arkethrax .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 121480, 129171, 141404, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42368] = { ["id"] = 42368, ["name"] = "Quantity Over Quality", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["description"] = "The demons of Felblaze Ingress are amassing at an exponential rate. We must cull these invaders before they have enough demons to flank our forces at Illidari Stand. Will you join us in battle?", ["objectivesText"] = "Slay demons in the Felblaze Ingress.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107245, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42369] = { ["id"] = 42369, ["name"] = "They're Doing it Wrong", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42372, 42375 }, ["description"] = "These demon portals are terrible and sloppy. No skill or finesse in it. This physically hurts me and I haven't felt real pain in decades. I \"fixed\" some of the Legion's precious Portal Stabilizer crystals. I want you to take them and \"modify\" their main portal in the Ingress and watch the \"hilarity\" ensue.", ["objectivesText"] = "Place 4 Sabotaged Portal Crystals. Progress: Did you see the look on those demons' faces? Priceless!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42370] = { ["id"] = 42370, ["name"] = "Wanding 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["series"] = { 37467, 37468, 37486, 37497, 37518, 37736 }, ["description"] = "We'll start with some wand work. You have your wand with you? Good. I've set up a number of targets around the hall. Use your wand to hit as many as you can. And no point-blank shots! That's cheating.", ["objectivesText"] = "Practice using your wand on 10 Wand Targets . Progress: You'll never learn if you never practice.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42371] = { ["id"] = 42371, ["name"] = "Study Hall: Combat Research", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37256, 37257, 37467, 37468, 37469, 37470, 37486, 37497, 37518, 37530, 37678, 37690, 37729, 37730, 37733, 37736, 38286, 42213, 42370, 42371 }, ["description"] = "What's this? A new, confused student, desperately trying to win the favor of the headmistress, wandering the halls without anything to do? Perfect! I need help with my research. I'm writing a paper on combat. Grab me some books from the shelf over there.", ["objectivesText"] = "Obtain the books that Sythorne requests, then help him defeat the challenges within. Progress: I agree. Research can be grueling work.", ["rewardGold"] = 63800, ["rewardXP"] = 1415, ["rewardItems"] = { 116456, 122674, 137422, 137423, 137426, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5749, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5749, ["name"] = "Azsuna versus Azshara", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42372] = { ["id"] = 42372, ["name"] = "Felblaze Ingress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42369, 42375 }, ["description"] = "It is my mission to cover the rear guard of Illidari Stand. I have employed this warlock... thing, to assist me. However, the two of us are insufficient for a task that needs doing. To the east is a mass of demons at Felblaze Ingress. These creatures have begun to open portals to summon in countless reinforcements. Meet us at Felblaze Ingress and together we can crush this fel insurgency.", ["objectivesText"] = "Meet Tehd Shoemaker at Felblaze Ingress.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 106915, ["x"] = 0.504, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42375] = { ["id"] = 42375, ["name"] = "Eye See You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42367, 42368, 42369, 42372, 42375 }, ["series"] = { 42369, 42372 }, ["description"] = "There is being blind, and then there is being stupid. This eyeless wonder next to me wants to barrel into Felblaze Ingress without preparation. Bah! I say we scout it first. Here, I will provide you with an extra eye I picked up from a place better left unmentioned. Enter Felblaze Ingress, investigate the area, and try not to get poked in the eye.", ["objectivesText"] = "Use Tehd's Eye of Kilrogg to investigate Felblaze Ingress. Progress: Don't ask where I got the eye. Worst case is I tell you and then it gets all awkward between us.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 133753, 137191, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 237812, 244913 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107244, ["x"] = 0.638, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5761, ["name"] = "Felblaze Ingress", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42383] = { ["id"] = 42383, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "The Earthen Ring is built upon the strength and dedication of its members. If we are to help defend this world against the Burning Legion, we will need to grow our order, and recruit skilled champions to our side. Begin by speaking to Stormcaller Mylra and Duke Hydraxis. Perhaps they would be willing to fight for us.", ["objectivesText"] = "Recruit Stormcaller Mylra and Duke Hydraxis.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42384] = { ["id"] = 42384, ["name"] = "Scouting Reports", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42523, 42524, 42525, 42526 }, ["description"] = "In the recent past, our order has spent a lot of time watching and waiting. With you at the helm, we'll be able to focus on our original calling. Take a look around us, <name>. Azeroth needs us now more than ever. The same enemy that led to our formation is threatening us once again. You should send someone to gather reports from our scouts. From there, we'll be able to focus our efforts where they are needed most.", ["objectivesText"] = "Interact with the Scouting Map and complete \"Scouting Reports\".", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42385] = { ["id"] = 42385, ["name"] = "Lending a Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42386 }, ["description"] = "Our scouts reported seeing a village in Val'sharah being attacked by undead hounds. This is the perfect opportunity for the Unseen Path to make good on our promise to help those in need. You should head out to Bradensbrook and see what you can do to help.", ["objectivesText"] = "Find Hudson Crawford in Val'sharah.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107372, ["x"] = 0.416, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42386] = { ["id"] = 42386, ["name"] = "Rising Troubles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42385 }, ["description"] = "Our village is swarming with beasts risen from the dead! The abominations never rest! They attack night and day. We're doing our best to keep them at bay, but it's getting to be more than the townsfolk can handle. They're tired and losing their will to fight. Anything you can do to lessen the burden would be greatly appreciated.", ["objectivesText"] = "Kill Risen Hounds in and around Bradensbrook. Progress: We'll keep fighting as long as the hounds keep coming. Bradensbrook will not be lost to those beasts!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107372, ["x"] = 0.416, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107372, ["x"] = 0.416, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42387] = { ["id"] = 42387, ["name"] = "Assassin Entrapment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["description"] = "Black Rook invaders are still targeting our farms and homes, even though there's not much left to pillage. We had hoped that once they cleared us out that the attacks would stop, but it seems those mindless ghouls will follow any orders given by their commander. We'd take him out ourselves, but he's a sneaky fella. The only way we're going to catch him, is if someone lays a trap. I can provide the supplies if you're willing to help.", ["objectivesText"] = "Set a trap at Carlisle Cottage to catch and kill Captain Tevaris .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137551, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107372, ["x"] = 0.416, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107372, ["x"] = 0.416, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42388] = { ["id"] = 42388, ["name"] = "Urgent Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42389, 42391 }, ["description"] = "The eagle appears to have a message for you: To: <name> Our scouts have returned with reports from all over Azeroth. It seems that things are much worse than they initially seemed. Return to Trueshot Lodge as soon as you can. - Emmarel Shadewarden", ["objectivesText"] = "Speak to Emmarel Shadewarden at Trueshot Lodge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 113325, ["x"] = 0.415, ["y"] = 0.599 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.599 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42389] = { ["id"] = 42389, ["name"] = "Calling Hilaire Home", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42388, 42391 }, ["description"] = "With so many in need of our help, it may be time to call in some of our scouts in the field. One such scout is a huntress by the name of Hilaire. Although she abandoned her clan long ago to join our order, she still feels a need to watch over them. Her dedication to protect those who would shun her is admirable, but we need her here. Seek Hilaire out in Stormheim, and let her know it's time to come home.", ["objectivesText"] = "Find Beastmaster Hilaire in Stormheim. Progress: Have you found Hilaire yet? She's a dedicated huntress, one who's more than willing to protect those who cannot protect themselves.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107316, ["x"] = 0.346, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 634, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42390] = { ["id"] = 42390, ["name"] = "Recruiting Rexxar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42392, 43335 }, ["description"] = "To do the most good, we need the best hunters at our side. Having you leading the order is a great start, but we'll need others who share your skill and expertise if we plan on making an impact. Rexxar has a reputation of being one of the greatest hunters of his time, yet he's never been eager to aid the Unseen Path. He has a camp just north of here, where he and Misha live off the land. Maybe you can convince him to join our ranks.", ["objectivesText"] = "Find Rexxar in Highmountain.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 650, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42391] = { ["id"] = 42391, ["name"] = "Bite of the Beast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42388, 42389 }, ["description"] = "I will not leave my post without Cora . A group of mages have her caged up like a beast, threatening to put her down. They claim she's responsible for the death of one of their own, but I refuse to believe that. Cora is a loyal and obedient companion; she would never attack without my command. I tracked the demon that was truly responsible to this location, but it put up quite a fight before getting away. My injuries prevented me from giving chase, but I am sure that beast has left a bloody trail.", ["objectivesText"] = "Find the beast responsible for the attacks and bring its head to the mages holding Cora captive. Progress: I will not go anywhere until Cora is at my side.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137572, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107316, ["x"] = 0.346, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107316, ["x"] = 0.346, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42392] = { ["id"] = 42392, ["name"] = "Survive the Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42390, 43335 }, ["description"] = "Now it's time to put your skills to the test. Your order seems to be a lot of watching and waiting without a lot of action. Prove me wrong. Show me that I might have something in common with the Unseen Path. If you survive a night in the wild, then I will consider joining your order.", ["objectivesText"] = "Survive a night within Cliff's Edge according to Rexxar 's rules. Progress: You need to eat to survive in the wild. Boar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however. There are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often determine which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat. The best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124640, 137612, 137613, 137618, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42393] = { ["id"] = 42393, ["name"] = "Homecoming", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42394 }, ["description"] = "Cora has calmed enough to make the journey back to Trueshot Lodge. You can let Emmarel know that we are on our way home.", ["objectivesText"] = "Return to Emmarel Shadewarden at Trueshot Lodge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 38675, 237812, 251103, 251104, 251108, 251115, 251118, 260312 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107316, ["x"] = 0.346, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 634, 739 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42394] = { ["id"] = 42394, ["name"] = "Unseen Protection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42393 }, ["description"] = "We will not let the city of Dalaran fall. If the Legion is planning an attack, the Unseen Path will be there to stop it. Our scouts' most recent reports list a few other areas that sound like they could really use our help, whether they realize it or not. As soon as you're able, send your hunters to take care of the threats.", ["objectivesText"] = "Use the Scouting Map to send your champions and troops on \"Unseen Protection\" missions.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42395] = { ["id"] = 42395, ["name"] = "Signaling Trouble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["description"] = "Long ago, we gave select leaders special flares that were only to be used in times of great need. Upon seeing the flare, the leader of the Unseen Path is supposed to head to the southern watchtower to meet with whomever lit it. I don't know who we'll face once we reach the tower, but we must move quickly.", ["objectivesText"] = "Meet Emmarel at the top of the southern watch tower.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 140517, 140926, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 680, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42397] = { ["id"] = 42397, ["name"] = "Baron and the Huntsman", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42398 }, ["description"] = "We've received word from Khadgar that he's lost contact with the mages he sent to investigate the Legion's camps. He's requested our assistance in tracking them down. If we have any hope of locating those mages, we'll need to find ourselves a reliable hound capable of following a scent. There is only one such hound that I know of, and he's long since retired. It's worth it to check in with his master, Hunstman Blake, and see if old Baron still has it in him.", ["objectivesText"] = "Find Huntsman Blake in Stormheim.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107981, ["x"] = 0.802, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 634, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42398] = { ["id"] = 42398, ["name"] = "Awakening the Senses", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42397 }, ["description"] = "I'm afraid old Baron here is past his prime. His nose can't catch a scent the way it used to. Others told me to put him down, but I can't bear the thought of losing my loyal friend. Baron was always at his best when working, though. Maybe if you let him wander through these fields and dig up some old bones, it'll be enough to awaken his senses.", ["objectivesText"] = "Help Baron awaken his senses by digging up Ancient Bones within the area. Progress: How's old Baron holding up?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138299, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107981, ["x"] = 0.802, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107981, ["x"] = 0.802, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.802, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42399] = { ["id"] = 42399, ["name"] = "Ready to Work", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42400, 42401, 42404, 42406, 42689, 42691 }, ["description"] = "If Baron's ready to work, I am too. We'll make our way to the hunter's lodge as soon as I pack up camp and get this dog fed. I'm sure with all that digging, he'll have a hearty appetite.", ["objectivesText"] = "Return to Emmarel Shadewarden in Trueshot Lodge.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107981, ["x"] = 0.802, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.802, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 634, 739 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42400] = { ["id"] = 42400, ["name"] = "Missing Mages", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42401, 42404, 42406, 42689, 42691 }, ["description"] = "The Archmage has already made his way to Suramar, where the missing mages were last seen. Baron ran off, too. It seems that hound is eager to work again. Meet them both near the road that leads into the city. With any luck, Baron will be about to pick up on their magical scent and find the missing mages before it's too late.", ["objectivesText"] = "Meet Archmage Khadgar in Suramar.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 680, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42401] = { ["id"] = 42401, ["name"] = "The Scent of Magic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42400, 42404, 42406, 42689, 42691 }, ["description"] = "This is the last known location of the missing Kirin Tor. There isn't much evidence, other than a torn piece of cloth, which looks to be from one of our tabards. The scrap may be small, but it should be heavy with the essence of magic. We can only hope that Baron can catch the scent and track down the mages.", ["objectivesText"] = "Follow Baron as he tracks the scent of the mages.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108089, ["x"] = 0.33, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42402] = { ["id"] = 42402, ["name"] = "Requesting Reinforcements", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42405, 42407 }, ["description"] = "Many powerful factions have pledged their loyalty to the Unseen Path. It's time that we call on them to help us defeat Hakkar and his demon hounds. Send your champions into the field to track down these leaders and let them know we require their help.", ["objectivesText"] = "Interact with the Scouting Map and complete the mission \"Requesting Reinforcements\".", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42403] = { ["id"] = 42403, ["name"] = "Highmountain Hunters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["description"] = "I've just received word from our scouts that they've identified some potential recruits. It seems as though the famed Hemet Nesingwary has set up camp not too far from our lodge. While he isn't traditionally the type of hunter we'd invite into our ranks, his experience hunting large game could come in handy. Head on over to his retreat and see if he's willing to aid our cause.", ["objectivesText"] = "Find Hemet Nesingwary in Highmountain.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94409, ["x"] = 0.4, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 650, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 1, ["flags"] = 1 } } },
[42404] = { ["id"] = 42404, ["name"] = "Assisting the Archmage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42400, 42401, 42406, 42689, 42691 }, ["description"] = "Hakkar maintains an army of felhounds that feed off of magic. As long as he remains within Azeroth, no mage will be safe. He and his hounds are immune to most spells, so I must ask for assistance in killing them. You have proven yourself more than capable, but are you willing to help take down this demon?", ["objectivesText"] = "Return to Emmarel Shadewarden at Trueshot Lodge.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108089, ["x"] = 0.33, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 680, 739 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42405] = { ["id"] = 42405, ["name"] = "Informing Our Allies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42402, 42407 }, ["description"] = "Leaders from some of the greatest military factions are here, ready and willing to help. They're currently waiting to speak with you directly, hoping to provide insight on how they can help. With any luck, we can pull our resources and find a way to take Hakkar down.", ["objectivesText"] = "Speak to Archmage Khadgar , Halduron Brightwing , Vereesa Windrunner , and Shandris Feathermoon . Progress: We cannot hope to defeat Hakkar without the help of our allies.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42406] = { ["id"] = 42406, ["name"] = "To Tame the Beast", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42399, 42400, 42401, 42404, 42689, 42691 }, ["description"] = "Deep in the heart of Faronaar are dens that are overrun with felhounds. If Hakkar is breeding those beasts, that is the place he would do it. The bait I've crafted is potent. Once you apply it, you'll draw the attention of nearby hounds, so only use it when you're close to the dens. Once the demon has taken the bait, get it into a weakened state to make trapping easier. Good luck, <name>. I hope you return in one piece.", ["objectivesText"] = "Use the Leyworm Bait while in Felbeast Dens to lure and trap a felhound fledgling . Progress: Be careful not to kill the felhound when trapping it. I need the subject alive to perform my tests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137663, 138253, 138763, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 105816, ["x"] = 0.608, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 18, ["flags"] = 0 } } },
[42407] = { ["id"] = 42407, ["name"] = "The Nature of the Beast", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["series"] = { 42402, 42405 }, ["description"] = "By nature, this demon is immune to magic, but it has also been bred to be resistant to physical attacks. It's covered in scales unlike anything I've ever seen; layered and thick. I doubt that most metals will be able to pierce the demon's armor-like hide. Unless your entire army has weapons like yours, I suggest fighting those beasts with something that will exploit their weakness.", ["objectivesText"] = "Return to Emmarel Shadewarden at Trueshot Lodge.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139506, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 108375, ["x"] = 0.608, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 19, ["flags"] = 0 } } },
[42408] = { ["id"] = 42408, ["name"] = "Required Reagents", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons. She provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", ["objectivesText"] = "Collect the required crafting reagents. Progress: The enchanting process cannot be completed without the proper reagents.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 109693, 124440, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 3, ["flags"] = 0 } } },
