[42416] = { ["id"] = 42416, ["name"] = "The Council is in Session", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 627, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42423, 42424, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth's involvement with the Empyrean Society is troubling. However, as he has proven his loyalty to the Kirin Tor many times, we must give him the benefit of the doubt for now. Still, I am obligated to share our concerns with the rest of the Council. You had best travel to Dalaran and meet with them in the Violet Citadel. I will remain here to care for our old friend.", ["objectivesText"] = "Speak to the Council of Six in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 118191, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42418] = { ["id"] = 42418, ["name"] = "An Unexpected Visitor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42166, 42433, 42434, 42435 }, ["description"] = "Archmage Vargoth's long-time apprentice, Ravandwyr , has arrived here in the Hall of the Guardian with an urgent message from his mentor. He will be waiting for you upstairs. You had best find him quickly, <name>!", ["objectivesText"] = "Meet up with Ravandwyr .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 140517, 140924, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42423] = { ["id"] = 42423, ["name"] = "Archmage Vargoth's Retreat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42424, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth has been absent for a while. You may have a look around his living quarters here in the citadel tower, <name>. Kalec will escort you there. I will hold out hope that our esteemed colleague is merely up to his usual eccentricities.", ["objectivesText"] = "Investigate Archmage Vargoth's quarters. Progress: What have you discovered, <name>?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 43824, 127857, 128820, 128862, 137571, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42424] = { ["id"] = 42424, ["name"] = "Following In His Footsteps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42451, 42508, 42521 }, ["description"] = "Archmage Vargoth seems to be mixed up in something dangerous, not that that's unusual for an archmage of his caliber and experience! The Arcway Vaults may be where he's headed, but we should investigate all leads in order to get a better idea of what he's up to.", ["objectivesText"] = "Ask your champions to investigate Archmage Vargoth's travels. Progress: Have your champions discovered anything of note about Archmage Vargoth?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42428] = { ["id"] = 42428, ["name"] = "The Shrine of Ashamane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42439 }, ["description"] = "The mighty Ancient, Ashamane, fell in battle against the Burning Legion ten thousand years ago. To honor her sacrifice, a group of devoted druids called the Ashen forged Ashamane's fangs into powerful daggers. Take my signet and present it to their leader, Delandros Shimmermoon . He will know that you have my blessing. Our flight master, Danise Stargazer , can see you to the shrine.", ["objectivesText"] = "Speak to Danise Stargazer and travel to Ashamane's Fall in search of Delandros Shimmermoon .", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42430] = { ["id"] = 42430, ["name"] = "The Fangs of Ashamane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42440 }, ["description"] = "I have to admit, Verstok was right. The shrine was too easy of a target for the Burning Legion to attack. Still, he's gone and the Fangs are with him. We're going to have to track him down for you to recover the Fangs. I should come with you but I have to stay with my people should we be attacked again. Here, my companion Ebonfang has a sense of smell like no other. He will be able to guide you to wherever Verstok is hiding. Also take this shell, through it we can communicate. May Elune guide you.", ["objectivesText"] = "Mount upon Ebonfang and search for the Fangs of Ashamane. Progress: How goes your search?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128306, 128822, 128858, 128859, 138136, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42432] = { ["id"] = 42432, ["name"] = "The Emerald Nightmare: The Emerald Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "The Lord of Nightmare, Xavius , is still out there. Cenarius is still in grave danger, deep within the Rift of Aln. Summon your greatest allies, <name>. If we are to stare into the face of the Nightmare, we had best be ready. Once you are ready, enter the Emerald Nightmare and defeat all the horrors you find there.", ["objectivesText"] = "Enter the Emerald Nightmare raid on any difficulty and defeat Lord Xavius . Progress: Never has the Nightmare spilled into our world. It is our duty to find the root of this evil, and destroy it.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139484, 237812, 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "raid", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 9, ["flags"] = 1 } } },
[42433] = { ["id"] = 42433, ["name"] = "Ancient Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42166, 42418, 42434, 42435 }, ["description"] = "Since the Broken Isles is the epicenter of ancient night elven learning, there must be countless magical artifacts secreted away in forgotten vaults and reliquaries. We must secure them so they do not fall into the wrong hands! Perhaps you should send a champion in search of them.", ["objectivesText"] = "Interact with your Scouting Map and complete the mission, \"Ancient Magic.\" Progress: What have you discovered?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42434] = { ["id"] = 42434, ["name"] = "A Covert Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 630, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["series"] = { 42166, 42418, 42433, 42435 }, ["description"] = "Your champion discovered some sort of powerful magic emanating from the secretive Empyrean Society enclave in Azsuna. Archmage Vargoth asked me to request Meryl's aid in investigating it, but as you can see, Meryl is clearly too ill to travel at the moment. Would you be willing to go in his place? You will need to prove yourself in order to gain entrance. We should be able to find something sufficient in the Hatecoil Warcamp in Azsuna.", ["objectivesText"] = "Meet Ravandwyr in Azsuna.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107532, ["x"] = 0.648, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42436] = { ["id"] = 42436, ["name"] = "Aiding Our Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42134, 42394, 42397, 42398, 42399, 42400, 42401, 42403, 42404, 42406, 42407, 42412, 42413, 42414, 42436, 42689, 42691, 42928, 42929, 42930 }, ["description"] = "Our Skyhorn allies could use some assistance. Their ongoing war with the invading harpies has left them low on supplies. Anything we can give them will surely help with their efforts to rid those witches from their village.", ["objectivesText"] = "Deliver supplies to Meliah Grayfeather .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124109, 124119, 133940, 140215, 140224, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5849, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5849, ["name"] = "Watchers in the Wild II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42438] = { ["id"] = 42438, ["name"] = "Seeds of Renewal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["description"] = "The Fangs of Ashamane are in danger, <name>. For ten thousand years a powerful magic ward has protected them from any would-be thieves, but the ward has weakened over time and is in danger of failing. My three most trusted Ashen have the Tel'andu seeds we need to perform the ritual of renewal, but the woods are now crawling with demons and I fear they have fallen. No matter what, we cannot allow the Legion to obtain the Fangs! Go and find the Tel'andu seeds , we must hurry before the ward can be broken!", ["objectivesText"] = "Delandros Shimmermoon wants you to search the forests of Mistvale and obtain three Tel'andu Seeds . Progress: Have the Tel'andu seeds ?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 140772, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42439] = { ["id"] = 42439, ["name"] = "Aid for the Ashen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42428 }, ["description"] = "Turn your eyes above and you will see the cause of our misfortune. Ever since that ship appeared the attacks have been relentless. Many of the Ashen have been captured and even now I can hear their screams of torture. Please, go out there and rescue as many of my followers as you can. They do not deserve the fate that awaits them if left in the Legion's grip.", ["objectivesText"] = "Defeat 4 Eredar Soul Lashers and free their captives.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42440] = { ["id"] = 42440, ["name"] = "The Shrine in Peril", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42428, 42430, 42438, 42439, 42440 }, ["series"] = { 42430 }, ["description"] = "You've helped us greatly, champion. Now, it is time that you tell me what brings you here. <You mention to Delandros that Archdruid Greathoof sent you to seek the Fangs of Ashamane.> Hrm... if you had told me this at the outset, I would have told you to take a walk. The Fangs are our greatest treasure, but you've done a great deed for the Ashen today and I am an elf of my word. Very well, let's clear out the rest of these demons and you shall have your weapons.", ["objectivesText"] = "Assist Delandros by removing the last of the attackers. Progress: Did you check on that disturbance?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128306, 128822, 128858, 128859, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 107392, ["x"] = 0.728, ["y"] = 0.4155 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.4155 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 193, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 193, ["name"] = "The Fangs of Ashamane", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42444] = { ["id"] = 42444, ["name"] = "Plight of the Blackfeather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "<The ravenbear frantically gestures and points down the path. It seems he wants you to follow him.>", ["objectivesText"] = "Follow the frightened ravenbear to the Blackfeather chieftain.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107499, ["x"] = 0.502, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42445] = { ["id"] = 42445, ["name"] = "Nithogg's Tribute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "It looks like the ravenbears have started gathering materials for some sort of tribute, but the storm drakes are keeping them from finishing what they started. From the looks of it, they're gathering fully intact stag horns and long tail feathers from the greatstags and eagles nearby. It shouldn't take too long to gather the rest of what they need.", ["objectivesText"] = "Collect 8 Intact Greatstag Antlers and 16 Pristine Eagle Tailfeathers in the Stormtorn Foothills. Progress: Ca-caw?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137610, 137611, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42446] = { ["id"] = 42446, ["name"] = "Singed Feathers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "Ca-caw! Caw caw! <The chieftain flaps his wings and points outside where the storm dragons attack the ravenbears of his tribe. It's plain to see that he's seeking your help to save his flock.>", ["objectivesText"] = "Kill 8 Rampaging Squallhunters in the Stormtorn Foothills.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42447] = { ["id"] = 42447, ["name"] = "Dances With Ravenbears", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42444, 42445, 42446, 42447 }, ["description"] = "<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.> Caw! Caw ca-caw! <It looks like he wants you to follow.>", ["objectivesText"] = "Help the Blackfeather ravenbears perform their tribute ritual.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129246, 129247, 129248, 129249, 129361, 129363, 129364, 129365, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 107498, ["x"] = 0.512, ["y"] = 0.317333 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.317333 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5926, ["name"] = "The Blackfeather Ravenbears", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42449] = { ["id"] = 42449, ["name"] = "Return of the Four Horsemen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 1, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 43539 }, ["description"] = "The voice of the Lich King has spoken, Deathlord, and the Knights of the Ebon Blade will obey your command. The Four Horsemen were no ordinary death knights, they were born of pure, unholy power gifted from the Lich King to Kel'thuzad. This unholy power to raise the dead has now been passed to you, Deathlord. I am sure you will wield it with great conviction. The Four Horsemen will be powerful allies against the Burning Legion... and Nazgrim is a worthy choice as the firstborn.", ["objectivesText"] = "Speak with Thassarian in Durotar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 107554, ["x"] = 0.472, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42451] = { ["id"] = 42451, ["name"] = "Kalec's Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42508, 42521 }, ["description"] = "Your champion was unable to penetrate very far inside the Arcway Vaults due to the heavy legion presence around it. Hopefully you will have better luck following Archmage Vargoth inside. Kalecgos will be waiting for you on the ridge overlooking Felsoul Hold.", ["objectivesText"] = "Meet Kalecgos on the ridge near the Arcway Vaults.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 109076, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107465, ["x"] = 0.312, ["y"] = 0.8236 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.8236 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42452] = { ["id"] = 42452, ["name"] = "Finding Ebonchill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["description"] = "Ebonchill bears a lineage of powerful wielders dating back to its maker, Alodi. He passed it on to his favorite apprentice and so on until... the archmage Arrexis, I believe. Arrexis disappeared sometime around the First War. I know nothing of his fate, but the answer may well be somewhere in this library. Start by looking around here. Whatever you find should lead us to Ebonchill.", ["objectivesText"] = "Investigate the forgotten stacks in the Hall of the Guardian for clues to Ebonchill's last known master, Arrexis. Progress: Have we found what we need yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42454] = { ["id"] = 42454, ["name"] = "The Hammer of Khaz'goroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7546, ["mapID"] = 629, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 39781 }, ["description"] = "<Now that you have defeated Dargrul the Underking and have the Hammer of Khaz'goroth in hand, it is time to place it in Aegwynn's Gallery in the lower chambers of Dalaran .>", ["objectivesText"] = "Use the central teleporter in Dalaran and then place the Hammer of Khaz'goroth in Aegwynn's Gallery.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 137649, 141007, 141008, 141009, 141010, 237812, 246812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7546 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42455] = { ["id"] = 42455, ["name"] = "Alodi's Gems", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["description"] = "Arrexis had a cadre of apprentices and subordinates to help him with the ritual, something you are currently lacking. In older times, when magic was less understood and spells required vast amounts of mana to cast, we stored mana in gems for use in complex spells. Lucky for us, I still have a few powerful Mana Gems in my vault, along with some other useful items. You merely need to go to the Bank of Dalaran and gain access.", ["objectivesText"] = "Gain access to Alodi 's personal bank vault in Dalaran and retrieve the Mana Gems. Progress: You found everything in my vault? I hope the defenses weren't a bother.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 141317, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42476] = { ["id"] = 42476, ["name"] = "The Deadwind Site", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42477, 42479 }, ["description"] = "Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there. You will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.", ["objectivesText"] = "Find and retrieve information on the ritual from Arrexis's campsite near Karazhan. Progress: I trust you were successful?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 141327, 141328, 141329, 173698, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42477] = { ["id"] = 42477, ["name"] = "Daio the Decrepit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42476, 42479 }, ["description"] = "That text lists someone named Daio as being instrumental to the demonic ritual. They can't possibly mean Daio the Decrepit! I never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation. He most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.", ["objectivesText"] = "Fly to the Tainted Scar in the Blasted Lands and get information from Daio the Decrepit. Progress: Well, what did Daio have to say?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 140192, 141330, 173699, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42479] = { ["id"] = 42479, ["name"] = "The Mage Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42452, 42455, 42476, 42477, 42479 }, ["series"] = { 42476, 42477 }, ["description"] = "And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly. I've heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won't want us to complete. The chances of us dying horribly are exceptionally high.", ["objectivesText"] = "Recreate Arrexis' ritual in Faronaar and defeat Balaadur. Progress: Do you have it?", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 127857, 128820, 128862, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 223, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 223, ["name"] = "Ebonchill", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42483] = { ["id"] = 42483, ["name"] = "Put It All on Red", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "All right, I've got one last beasty to send you after. He's a bit far out, but trust me, it'll be worth it. This one I put a huge wager on! Along the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable. But you're gonna prove them wrong, aren't ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.", ["objectivesText"] = "Collect Steelscale's Fin from Steelscale in Citrine Bay. Progress: Hmm...", ["rewardXP"] = 1415, ["rewardItems"] = { 132203, 138024, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107674, ["x"] = 0.512, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42484] = { ["id"] = 42484, ["name"] = "The Firstborn Rises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "General Nazgrim was one of the finest warriors our world has known, and his loyalty was unsurpassed... even for an orc. He deserves the peace of death, but this world cries out to be saved. The time for rest is over... Come, Deathlord... let us welcome Nazgrim into the arms of the damned.", ["objectivesText"] = "Raise Nazgrim as a Death Knight. Progress: General Nazgrim will make a fine <class>.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 107554, ["x"] = 0.472, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42486] = { ["id"] = 42486, ["name"] = "Little One Lost", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I'm ready to go home now, but there are still scary men outside... Will you stay with me? Make sure they don't take me away? I don't want to go back in the cage...", ["objectivesText"] = "Escort Korine back to her mother Verene at the Waning Crescent.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 130209, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107712, ["x"] = 0.431, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.411, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42487] = { ["id"] = 42487, ["name"] = "Friends On the Outside", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "You have done well for us here, but it is time for you to return to Thalyssra. There is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way. Oh, and before you go: < Vanthir hands you a wrapped bottle of Arcwine.> Take this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child. We are grateful beyond measure. Farewell for now.", ["objectivesText"] = "Activate the teleporter pad and bring Vanthir 's gift to Thalyssra. Progress: A gift? For me?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138389, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42488] = { ["id"] = 42488, ["name"] = "Thalyssra's Abode", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "While you were busy in the city I reached a roadblock in my withered research. I feel I am close to overcoming this barrier, but I'm afraid I cannot do so without some more advanced tools. I hid among my possessions an item called an Arcane Amplifier . It does precisely what its name entails. It is more than likely that the Magistrix ordered my estate dismantled. If the Amplifier remains, it will be in fragments. Recover the whole, if you can.", ["objectivesText"] = "Search Thalyssra's estate and collect 3 Amplifier Fragments . Combine them into an Arcane Amplifier . Progress: Did you find it?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138391, 138392, 140255, 141677, 141951, 141952, 142054, 237812, 246815, 246937, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42490] = { ["id"] = 42490, ["name"] = "The Arcway: Opening the Arcway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42490 }, ["description"] = "Deep beneath Suramar is a defunct set of tunnels known as the Arcway. They were abandoned when a disaster disrupted the mana collectors operating there. I know not what awaits you down there, but I do know one thing. We are not the only ones interested in this place. Make enough noise and one of the advisors with whom I served under Elisande is sure to appear. His name is Vandros. Slay him, if you can. His death will be our victory, as we deprive Elisande of one more weapon in her arsenal.", ["objectivesText"] = "Slay Advisor Vandros in the Arcway. Progress: Is it done?", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon" },
[42493] = { ["id"] = 42493, ["name"] = "Impending Dooooooom!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 683, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42520, 42707, 42734, 42940 }, ["description"] = "Millhouse attracts trouble, so he's sure to find Archmage Vargoth if he's still here. Oh and if you do find the Nightborne Soulstone, best get it first!", ["objectivesText"] = "Investigate the Nightborne Vault. Progress: What did you discover?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 683, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42494] = { ["id"] = 42494, ["name"] = "More Than Just A Food Vendor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["description"] = "Your champions made a good dent in thinning out the enemy's numbers. They also discovered a number of starving prisoners who could use our help. Your Conjured Mana Pudding or Fritters will be useful in getting them up on their feet. You should also dispatch as many of the remaining legion invaders back to the twisting nether as you can!", ["objectivesText"] = "Eradicate 15 demons and give your conjured food to 10 starving prisoners. Progress: Have you been able to help the prisoners?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 80610, 127857, 128820, 128862, 138115, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42501] = { ["id"] = 42501, ["name"] = "Finishing the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["series"] = { 42502, 42503, 42539, 42568 }, ["description"] = "Garona set out to assassinate the leaders of a Legion cult some time ago. We haven't heard from her since. To make matters worse, she took the Kingslayers with her. She knows they bring out the worst in her! Your best bet to find Garona is by continuing her work. Our intel points to a warlock by the name of Caden Shadowgaze inducting new recruits at the Altar of Storms in Blasted Lands. See if he has anything useful in his pockets. Once he's dead, I mean.", ["objectivesText"] = "Assassinate Cade Shadowgaze at the Altar of Storms in Blasted Lands and search his body for information.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 137676, 139506, 139739, 139742, 139746, 140517, 140931, 173531 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42502] = { ["id"] = 42502, ["name"] = "No Sanctuary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["series"] = { 42501, 42503, 42539, 42568 }, ["description"] = "We have one other lead that may prove useful. Goes by Felcaller Whitley , another of the cult's elite. He's eluded our agents at every turn. Our latest reconnaissance report puts him somewhere in the village of Raven Hill in Duskwood. He's sure to have information vital to your search. You know what to do.", ["objectivesText"] = "Assassinate Felcaller Whitley at Raven Hill in Duskwood and search his body for information.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 137678, 139506, 139734, 139739, 139742, 139746, 140517, 140931, 173530, 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187466, 194549, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42503] = { ["id"] = 42503, ["name"] = "Codebreaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 626, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42539, 42568 }, ["description"] = "<The coded message you obtained is protected by powerful magic, rendering it indecipherable by conventional means.> <If you use the cipher you took from Felcaller Whitley you might be able to crack the code, leading you ever closer to both the cult's base of operations and Garona.>", ["objectivesText"] = "Use the Fel Cipher to decrypt the Coded Message and learn where you can find the cultists next.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128479, 128870, 128872, 136786, 138102, 139506, 139739, 139742, 139746, 140517, 140931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42504] = { ["id"] = 42504, ["name"] = "The Unseen Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568 }, ["description"] = "We can't let Stormwind fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own. The two of us need to handle this while there's still time. The entire city is on edge from murmurs of the cult's activities. They're as likely to turn on you as they are the cultists if you aren't careful. The other Shadows spoke highly of your skills. Are you in?", ["objectivesText"] = "Help Garona take out the Veiled Hand cultists in Stormwind.", ["rewardGold"] = 202200, ["rewardXP"] = 2125, ["rewardItems"] = { 128479, 128870, 128872, 139178, 237812 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42508] = { ["id"] = 42508, ["name"] = "Not A Toothless Dragon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42451, 42521 }, ["description"] = "The Arcway Vaults have been buried and untouched for thousands of years. We have the legion to thank for it being accessible once again, though I would give much for it to remain hidden. I think we are not far behind Archmage Vargoth's heels and he may yet be inside the vaults. We should make haste if we hope to intercept him.", ["objectivesText"] = "Ride with Kalecgos to the Arcway Vaults.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107465, ["x"] = 0.312, ["y"] = 0.8236 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.8236 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42510] = { ["id"] = 42510, ["name"] = "Immortal Soul", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 37447, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "Illidan's immortal demon soul is lost somewhere in the vastness of the Twisting Nether. Contacting him risks much, the Nether is full of creatures of unimaginable power and appetites. But, it must be done if we are to move forward. The ritual can be performed using the nether crucible. Make the blood offering , <name>.", ["objectivesText"] = "Make the Blood Offering to complete the ritual and contact the soul of Illidan Stormrage. Progress: All that is left is to make the blood offering . Then, we will see what the future holds for the Illidari.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 137690, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42512] = { ["id"] = 42512, ["name"] = "Highmountain Stands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38915, 39776, 39777, 39780, 39781, 39862, 40594, 42088, 42454, 42512 }, ["series"] = { 38909, 38912, 38915, 38916, 39025, 39026, 39027, 39043, 39372, 39373, 39374, 39381, 39391, 39425, 39426, 39455, 39456, 39575, 39577, 39578, 39579, 39580, 39588, 39776, 39780, 39860, 40219, 40229, 40243, 40312, 40594, 42088 }, ["description"] = "That will have to do. Dargrul has come and we need every able body on the front line. Go, I will be right behind you.", ["objectivesText"] = "Defeat Dargrul.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93846, ["x"] = 0.528667, ["y"] = 0.666 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97407, ["x"] = 0.532, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.528667, ["y"] = 0.666 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 278, ["title"] = "Highmountain", ["questLineID"] = 143, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 143, ["name"] = "Snowblind Mesa", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42516] = { ["id"] = 42516, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 42583 }, ["description"] = "Archdruid Rensar Greathoof has requested your presence. Our campaign to defend the Broken Isles is getting under way, and we need you at the helm.", ["objectivesText"] = "Speak to Archdruid Rensar Greathoof at the Dreamgrove.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 9, ["flags"] = 1 } } },
[42519] = { ["id"] = 42519, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["description"] = "As leader of our order, other hunters will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary in the name of the Unseen Path. I know of two within our ranks who are impressed with what they've seen from you so far, and want to help any way they can. Seek them out, and let them ease the burden of leadership.", ["objectivesText"] = "Recruit Emmarel Shadewarden and Loren Stormhoof.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 102940, ["x"] = 0.476333, ["y"] = 0.530333 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.476333, ["y"] = 0.530333 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42520] = { ["id"] = 42520, ["name"] = "A Terrible Loss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 735, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42493, 42707, 42734, 42940 }, ["description"] = "I would say I am surprised by this terrible turn of events, but nothing surprises me of late. It is dark times when even the most upstanding of us can fall... We had best inform Archmage Khadgar of Vargoth's betrayal.", ["objectivesText"] = "Return to the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139506, 139754, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42521] = { ["id"] = 42521, ["name"] = "The Enemy of My Enemy...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42171, 42222, 42416, 42423, 42424, 42451, 42508 }, ["description"] = "Millhouse Manastorm has been quite vociferous about his intention to acquire the Nightborne Soulstone. If you find him, you may as well make use of him. However, he is unpredictable at best and you should always watch your back around him, <name>. Use my crystal to contact me once you have located him.", ["objectivesText"] = "Find Millhouse Manastorm. Progress: Were you able to locate Millhouse?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 38134, 38135, 38176, 38177, 38178, 38732, 38759, 39030, 39058, 39096, 44987, 45724, 46114, 52879, 52884, 52887, 52902, 52931, 52948, 60260, 65290, 65309, 65328, 65341, 119139, 127857, 128820, 128862, 131828, 131840, 137659, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 158666, 159123, 159147, 159148, 159149, 159150, 160083, 160084, 160085, 160086, 160093, 160094, 160095, 160096, 182077, 198611, 204454, 204459, 204620, 204624, 204625, 204626, 204627, 204628, 204629, 204630, 211279, 237812, 249699, 253178 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111553, ["x"] = 0.342, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 683, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42522] = { ["id"] = 42522, ["name"] = "Leader of the Illidari", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 37447, 42510, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087, 44161 }, ["description"] = "Illidan has officially placed you in charge, <name>. The Illidari are now yours. Meet me upstairs. We will let everyone know together.", ["objectivesText"] = "Head upstairs and take your place as the new leader of the Illidari.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42523] = { ["id"] = 42523, ["name"] = "Making Contact", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42524, 42525, 42526 }, ["description"] = "Now that we have recruited champions for our order, we can use the Scouting Map to complete vital assignments across the Broken Isles. Over the years our scouts have kept a close eye on hunters that might one day be added to our ranks. One such hunter, Lenara, was on her way to Trueshot Lodge when she was attacked. I suggest that we send Loren Stormhoof on a mission to rescue her. He may be uniquely suited to this task.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Lenara Needs Help.\" Progress: How is the mission proceeding?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42524] = { ["id"] = 42524, ["name"] = "Recruiting The Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42525, 42526 }, ["description"] = "Our champions acquired the talents of Recruiter Lenara, an extraordinary archer. She can hit the smallest of targets at extended ranges. Her arrows never miss. Speak to her now and train a squad of archers .", ["objectivesText"] = "Speak to Recruiter Lenara and train a troop of archers. Progress: How did the training go?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42525] = { ["id"] = 42525, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42524, 42526 }, ["description"] = "It's time to send our newly trained archers out into the field. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Troops in the Field.\" Progress: How did it go?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 16, ["flags"] = 0 } } },
[42526] = { ["id"] = 42526, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40384, 40618, 40952, 40953, 40954, 40955, 40957, 40958, 40959, 41008, 41009, 41415, 42409, 42519, 42523, 42524, 42525, 42526 }, ["series"] = { 42384, 42523, 42524, 42525 }, ["description"] = "We are very fortunate to have come across Survivalist Bahn. He spent his younger years living off the land in Pandaria, relying on the native flora and fauna to survive. His firsthand experience with building from limited resources could really help shape Trueshot Lodge into something great. Speak to him now and see what he can do for us.", ["objectivesText"] = "Speak to Survivalist Bahn in Trueshot Lodge. Progress: Have you spoken with Survivalist Bahn yet?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5847, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5847, ["name"] = "The Unseen Path", ["orderIndex"] = 17, ["flags"] = 0 } } },
[42533] = { ["id"] = 42533, ["name"] = "The Ruined Kingdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["series"] = { 42534 }, ["description"] = "So the Lich King has revealed the second of the Four Horsemen... it appears that not even kings may rest as the world burns around them. So be it, Deathlord. I will send Nazgrim and Thassarian to meet you at the fallen kingdom of Stromgarde. Prince Galen Trollbane holds the key to the tomb of his father, a famous sword known as Trol'kalar. In order to raise the king as the second of the Four Horsemen, we will need to gain entrance to the tomb. Do what you must to persuade Galen assist us...", ["objectivesText"] = "Speak with Prince Galen Trollbane in Stromgarde.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42534] = { ["id"] = 42534, ["name"] = "Our Oldest Enemies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["series"] = { 42533 }, ["description"] = "I will grant the Ebon Blade access to my father's tomb. First though, I must ask a favor. I have taken up the sword and banner of my father. I have reclaimed Stromgarde with its former citizens as my guard. Yet, one task remains. Witherbark invaders have blockaded themselves in the former mage district of the city. My men have suffered heavy losses at their vile hands. Cut them down to the last! Bring me their heads and I shall give you what you seek. You have my word as the King of Stromgarde.", ["objectivesText"] = "Collect 15 Witherbark Troll heads. Progress: Do you have the heads of my enemies? I want to look upon each and every face...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 138142, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42535] = { ["id"] = 42535, ["name"] = "Death... and Decay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "My family has fought the Witherbark trolls for generations... their presence in Arathi has always been a curse upon the land. I want to drive them out of Stromgarde for good! Destroy their supplies and we shall give them no incentive to return. Blight their supplies... or whatever it is you death knights do to defile things. I care not. Just make sure that it is done!", ["objectivesText"] = "Blight 10 Witherbark Supplies .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 107806, ["x"] = 0.194, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.194, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42536] = { ["id"] = 42536, ["name"] = "Regicide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Galen Trollbane is a fool if he thinks that he can betray the Ebon Blade. I have had enough of his games. The fallen prince wastes our time playing the king of a ruined throne, while heroes sacrifice their lives to save this world. If Galen Trollbane will not open the tomb of his father, then we must take the sword and do it ourselves. If he chooses to resist, so be it.", ["objectivesText"] = "Obtain Trol'kalar from Prince Galen Trollbane. Progress: We need the sword Trol'kalar to open this tomb. Have you found it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128292, 128402, 128403, 138148, 139506, 139673, 139676, 139680, 140517, 140923, 237812, 237936, 237937, 237938, 237939 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2088, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42537] = { ["id"] = 42537, ["name"] = "The King Rises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "King Thoras was one of the greatest warriors this world has known. His people loved him and his enemies feared him. He only ever spoke truth, often saying the words others were afraid to speak. King Thoras lived a life of war and he certainly deserves the peace of death. But this is not a man who would sleep peacefully while the world around him burns. The time has come, Deathlord, to welcome the last true King of Stromgarde into the arms of the dead and damned.", ["objectivesText"] = "Raise King Thoras Trollbane as a Death Knight. Progress: King Trollbane was a great man. He will be a powerful ally against the threat of the Burning Legion.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 108042, ["x"] = 0.2088, ["y"] = 0.646 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2088, ["y"] = 0.646 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42539] = { ["id"] = 42539, ["name"] = "Cloak and Dagger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 626, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42503, 42568 }, ["description"] = "<The cultists seem to have a base of operations in Darkshire. At least Althea Ebonlocke is a member, but it is likely that the entire Night Watch has been compromised.> <The best course of action for now is to retrieve the dark implements for their ritual and make an attempt on Althea's life. Garona will have to wait.>", ["objectivesText"] = "Retrieve the Skull of the Innocent , the Blood of the Innocent , and make an attempt on Althea Ebonlocke's life in Darkshire.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 2000, 127837, 128476, 128479, 128870, 128872, 136786, 138102, 138112, 138113, 139506, 139739, 139742, 139746, 140517, 140931, 173527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42567] = { ["id"] = 42567, ["name"] = "Cursed to Wither", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 42756 }, ["description"] = "So Cedonu said he saw nightfallen going into Leyhollow? I don't like the sound of that. Grandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.", ["objectivesText"] = "Find the nightfallen that entered Leyhollow.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 90738, ["x"] = 0.499, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 91131, ["x"] = 0.482, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 17, ["flags"] = 0 } } },
[42568] = { ["id"] = 42568, ["name"] = "Preparation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42501, 42502, 42503, 42504, 42539, 42568, 42627 }, ["series"] = { 42501, 42502, 42503, 42539 }, ["description"] = "<With Althea's escape there is only one place to go: Stormwind.> <If Garona is keeping a similar pace on the cult's trail, she's bound to be making preparations to enter the city herself.> <Finding her is paramount before moving into the city.>", ["objectivesText"] = "Find Garona Halforcen outside Stormwind. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128479, 128870, 128872, 173532, 211946, 237812 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42583] = { ["id"] = 42583, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["series"] = { 42516 }, ["description"] = "The Legion's defeat cannot be accomplished alone. To win this war, we must work together, just as we did in ancient times. To begin, we must recruit more druids to our aid. Speak to the troll Zen'tabra and the night elf Naralex. Both of them are accomplished druids. They will gladly defend the Dreamgrove.", ["objectivesText"] = "Recruit Zen'tabra and Naralex.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42584] = { ["id"] = 42584, ["name"] = "Sister Lilith", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we've received word that she may be in trouble. Send Zen'tabra to her aid.", ["objectivesText"] = "Use the Scouting Map and complete the mission \"Sister Lilith\". Progress: Do not delay. Sister Lilith is in trouble.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42585] = { ["id"] = 42585, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "In our champions' travels, they made contact with Sister Lilith, a fearless leader among the Laughing Sisters. She is revered among the dryads as a seasoned warrior and a demanding teacher. She will serve as an excellent recruiter. Speak to her now, and recruit some Treants.", ["objectivesText"] = "Speak to Sister Lilith and recruit some Treants. Progress: Additional troops will be very useful for the missions ahead.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42586] = { ["id"] = 42586, ["name"] = "A Glade Defense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "We have a new mission that needs our attention, Archdruid. Deep in the forests of Val'sharah, a small druidic outpost known as Shal'doren Grove is under attack by satyrs. Send our champions to deal with this threat at once, <name>. We cannot allow these satyr incursions to grow unchecked!", ["objectivesText"] = "Use the Scouting Map and complete the mission,\"A Glade Defense.\" Progress: The satyrs are growing bolder with every day.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42588] = { ["id"] = 42588, ["name"] = "Branching Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 40643, 40644, 40645, 40646, 40650, 40652, 40653, 41106, 41255, 41332, 42096, 42516, 42583, 42584, 42585, 42586, 42588 }, ["description"] = "Leafbeard is known as the Storied for good reason. It is said that he remembers tales from before the Sundering. After examining the inscribed leaf that our champions recovered, he may be able to provide new knowledge and improvements for the grove. Go take it to him now.", ["objectivesText"] = "Speak to Leafbeard the Storied at the Dreamgrove in Val'sharah. Progress: It is said that Leafbeard never forgets anything.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5882, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5882, ["name"] = "The Dreamgrove", ["orderIndex"] = 16, ["flags"] = 0 } } },
[42593] = { ["id"] = 42593, ["name"] = "The Arcane Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 627, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42594, 42801 }, ["description"] = "Getting into the Black Temple is going to be tricky. Following the break-in by the Council of the Black Harvest, Akama had his Sha'tari priests erect a holy barrier. It prevents my teleportation. However, I might know a way to bypass those protections and take us directly to the Temple Summit. Long ago, I had a... liaison with a certain high elf wizard named Lan'dalock. He later joined the Kirin Tor. If you were to ask him very nicely, and drop my name, I am certain that he would help.", ["objectivesText"] = "Locate Archmage Lan'dalock at the Violet Citadel in Dalaran.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42594] = { ["id"] = 42594, ["name"] = "Move Like No Other", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42593, 42801 }, ["description"] = "Sorry about the holographic projection... I literally need to be in two places at once these days. A holy barrier that protects against fel magic, you say? I have just the thing to bypass it and enable Malevolence's teleport. <The high elf rummages around in his pack, a shocked look quickly coming over his face.> Sneaky! Look there... that imp just made off with it!", ["objectivesText"] = "Chase down the Sneaky Imp and recover the Grimoire of Arcane Ways . Progress: Did Archmage Lan'dalock prove useful, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138139, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42597] = { ["id"] = 42597, ["name"] = "Odyn's Summons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "Odyn would like to speak to you at once, my liege. He is convinced that as you have grown in power you are ready to take direct command of his armies and would like to begin preparations.", ["objectivesText"] = "Speak to Odyn in Skyhold.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42598] = { ["id"] = 42598, ["name"] = "Champions of Skyhold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "You will soon command one of the greatest armies in existence, but before my own Valarjar follow your every command you must prove your ability to lead. Speak to the two vrykul champions who ascended into these halls with you and tell them it is time for you to assume your duties as Odyn 's chosen.", ["objectivesText"] = "Recruit Ragnvald Drakeborn and Finna Bjornsdottir.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42601] = { ["id"] = 42601, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42602, 42603, 42608 }, ["description"] = "We are very fortunate to have come across Archivist Melinda. She is somewhat of an anomaly, as not many from her race choose our path. What makes her even more unique is her meticulous study of our craft. Her knowledge will be unsurpassed. Speak to her now and seek her council. With her help, we can surely strengthen the council.", ["objectivesText"] = "Speak to Archivist Melinda in Dreadscar Rift. Progress: Archivist Melinda's skills will allow us to make certain upgrades to Dreadscar Rift.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42602] = { ["id"] = 42602, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42601, 42603, 42608 }, ["description"] = "It's time to send our newly trained imps out into the field. Look at the Dreadscar Battle Plans and send your champions and troops on a routine scouting mission.", ["objectivesText"] = "Use the Dreadscar Battle Plans and complete the mission, \"Troops in Training\". Progress: How did it go?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42603] = { ["id"] = 42603, ["name"] = "Information at Any Cost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42601, 42602, 42608 }, ["description"] = "Now that you've found other warlocks that are willing to aid your cause, we can use the Dreadscar Battle Plans to complete vital assignments across the Broken Isles. If we wish to rebuild the council, we must start by locating its missing members. Let us send Ritssyn and Calydus to interrogate the Burning Legion's minions. They might have information that will help us locate the missing council members.", ["objectivesText"] = "Use the Dreadscar Battle Plans and complete the mission \"Information at Any Cost\". Progress: How is the mission proceeding?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 10, ["flags"] = 0 } } },
