[42607] = { ["id"] = 42607, ["name"] = "Captain Stahlstrom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "The souls that make it to these halls are brave, yes. That's why they're here after all. Valor alone does not make for an effective army, however. You will need someone who can train those who would be valarjar to fight with discipline. Have your champions send word to Captain Stahlstrom. Unruly vrykul berserkers may not fear death, but they might fear Hjalmar Stahlstrom enough to make them follow your orders.", ["objectivesText"] = "Use the Eye of Odyn and complete the mission, \"Captain Stahlstrom.\" Progress: Is it done, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42608] = { ["id"] = 42608, ["name"] = "Rise, Champions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["series"] = { 41797, 42601, 42602, 42603 }, ["description"] = "Friend is in a powerful, but lonely position. First of a council whose members are missing. Friend does not have to be alone though. Others will be drawn to friend's power, willing to follow if friend leads. Find those who want to help, and accept their pledge of loyalty.", ["objectivesText"] = "Recruit Calydus and Ritssyn Flamescowl.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42609] = { ["id"] = 42609, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "Captain Stahlstrom has arrived. It would be advisable to speak to him and see that the valarjar are armed and ready for battle. We'll need more than your two champions if we're to win a full-fledged war against the Legion.", ["objectivesText"] = "Speak to Captain Hjalmar Stahlstrom and train Valarjar Aspirants . Progress: What can I do for you, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42610] = { ["id"] = 42610, ["name"] = "Troops in the Field", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "Our enemies' transgressions have gone unchecked for long enough. Now that we have troops to back your champions, you would do well to send them to deal with them. One of our own has been taken prisoner by Odyn's sworn nemesis, Helya. If your forces manage to bring back Einar the Runecaster alive he can aid us in using powerful runes to advance the power of your armies.", ["objectivesText"] = "Use the Eye of Odyn and complete the mission, \"Troops in the Field.\" Progress: I greet you.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42611] = { ["id"] = 42611, ["name"] = "Einar the Runecaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 38904, 39214, 39654, 40585, 41052, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["description"] = "Being a leader is not just about sending your troops to combat. You will also make decisions about how we train and improve our armies. Speak to Einar the Runecaster and let him know how you would like development to progress.", ["objectivesText"] = "Speak to Einar the Runecaster. Progress: Yes, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 15, ["flags"] = 0 } } },
