[42627] = { ["id"] = 42627, ["name"] = "The Unseen Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 1, 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 42503, 42539, 42568, 42627 }, ["description"] = "Stormwind is too important to fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own. The two of us will have to handle this while there's still time. Use extreme caution. The entire city is on edge from murmurs of the cult's activities, and we're already kill on sight. The other Shadows spoke highly of your skills. Are you in?", ["objectivesText"] = "Help Garona take out the Veiled Hand cultists in Stormwind.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128479, 128870, 128872, 139178, 237812 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 107979, ["x"] = 0.368, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 183, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 183, ["name"] = "The Kingslayers", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42634] = { ["id"] = 42634, ["name"] = "Confrontation at the Black Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 39741 }, ["description"] = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers. I will need but a moment to summon a gateway. Stand back, please.", ["objectivesText"] = "Use the Gateway to the Black Temple and confront Akama .", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42635] = { ["id"] = 42635, ["name"] = "The Mystery of Dreyrgrot", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42639, 42641 }, ["description"] = "Well met, good chap! I was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they've unleashed some ancient evil. I would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps. I spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.", ["objectivesText"] = "Gather 4 Ancient Dreyrgrot tablets from the pirate ships outside of Dreyrgrot. Progress: How goes the hunt for knowledge?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 138149, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42639] = { ["id"] = 42639, ["name"] = "A Stone of Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42635, 42641 }, ["description"] = "Unfortunately, we may have another problem. That mist seeping out of the ruins has affected the looting pirates. It's driven them quite mad. Only one of them seems to be unaffected - a captainly fellow with a very fine hat. He wears a large ruby amulet, which I believe protects him from the mist. You'll need it if you are to enter the tomb. He may not give it up willingly.", ["objectivesText"] = "Collect Broketooth's Ruby Amulet from Captain Broketooth on the ships near Dreyrgrot. Progress: We will need the amulet's protection to proceed.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 138150, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42640] = { ["id"] = 42640, ["name"] = "The Value of Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["description"] = "This crate is filled with relics from the nearby ruins. The pirates have discarded them, likely thinking they're of little value. The Explorers' League would probably appreciate if you retrieved these relics for them to study.", ["objectivesText"] = "Gather 7 Crates of Ancient Relics from the waters outside Dreyrgrot. Progress: What's this?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 138151, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42641] = { ["id"] = 42641, ["name"] = "What the Bonespeakers Buried", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["series"] = { 42635, 42639 }, ["description"] = "Most Fascinating! It would appear that we're dealing with our very own vrykul vampyr! All we have encountered have been of blood elven descent, but it has long been theorized that the vrykul have suffered the curse as well. It's too bad he's awake - I would dearly like a subject to study. Oh well, guess there's nothing for it. Take this stake and put it through the old chap's heart. I'm pretty sure that should do the trick.", ["objectivesText"] = "Use the Sharp Wooden Stake to kill Blood-Thane Lucard in Dreyrgrot.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129329, 129357, 129358, 129359, 129360, 138190, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42645] = { ["id"] = 42645, ["name"] = "Spilling Bad Blood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42635, 42639, 42640, 42641, 42645 }, ["description"] = "Ending the evil of the Blood Prince will be a boon to this land, but we can't just allow these crazed corsairs to run amok. I'm afraid there is no choice but to put them to the sword. Carry out this noble deed, my good fellow, and we will celebrate with a nice warm lager.", ["objectivesText"] = "Kill 8 Blood-Crazed Swashbucklers in Dreyrgrot.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108072, ["x"] = 0.748, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5925, ["name"] = "The Mystery of Dreyrgrot", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42650] = { ["id"] = 42650, ["name"] = "Break the Bonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "The Bonespeaker mystics used these heirlooms to tie my soul to this world. Under their curse, my soul could not enter the Halls of Valor. Find the soul pyre in Haustvald and throw my belongings into the flames. The fire that bound my soul through their foul magic will be the same fire that undoes this bond!", ["objectivesText"] = "Throw Svergan's Belongings into the Soul Pyre and complete the Ritual of Unbinding. Progress: Is it done yet, CONCUSSED?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 138204, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42651] = { ["id"] = 42651, ["name"] = "Svergan's Promise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "I thank you for doing this for me. I swore an oath to protect the Gjallarhorn with my life, and so I did. You must tell Hymdall that his Gjallarhorn was devoured by the great worm, Jorhuttam! It devoured an entire army of my men who were swallowed whole trying to fend off the beast. Find Jorhuttam and you will find the horn!", ["objectivesText"] = "Return to Hymdall in Skyhold.", ["rewardGold"] = 70225, ["rewardXP"] = 355, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 106720, ["x"] = 0.673, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.673, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42653] = { ["id"] = 42653, ["name"] = "Champion: Akama", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42654] = { ["id"] = 42654, ["name"] = "Darkheart Thicket: Nightmare Oak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "Blacksmith Kyriel is no stranger to the Farstriders. He has forged countless arrows for us in the past, using his knowledge of unique materials to help build better, stronger ammo. He's efficient and gifted, making the most of scarce materials. Using a single branch from a corrupted ancient, he can craft thousands of arrows.", ["objectivesText"] = "Collect Nightmare Oak from Oakheart within the dungeon, Darkheart Thicket. Progress: Have you recovered the oak yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 138270, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42655] = { ["id"] = 42655, ["name"] = "Ore Under the Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "If we want to bring the fight to Hakkar, my rangers are going to need arrows and ammo that are capable of piercing the thick, magic-resistant hides of his hounds. There's a versatile smith in Dalaran who does incredible work with both bows and blades alike. He uses azure ore in his creations, which can only be found below sea level. Due to its proximity to leystone, the ore is often overlooked, but in an expert smith's hands, it can be smelted into something nearly indestructible.", ["objectivesText"] = "Mine Azure Ore from deposits found in the water off the coast of Suramar. Progress: Have you mined the ore yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44050, 109076, 131811, 138273, 141605, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42656] = { ["id"] = 42656, ["name"] = "Azure Weaponry", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "Take the materials to Blacksmith Kyriel in Dalaran, and he'll use them to craft whatever weapons he can. As I mentioned before, he's skilled and efficient, so you shouldn't have to wait long. When his work is complete, speak to Shandris Feathermoon about getting the weapons enchanted.", ["objectivesText"] = "Find Blacksmith Kyriel in Dalaran. Progress: We will need special weapons if we wish to take down Hakkar and his hounds.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 138274, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108456, ["x"] = 0.45475, ["y"] = 0.22525 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.45475, ["y"] = 0.22525 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42657] = { ["id"] = 42657, ["name"] = "Meeting in Moonclaw Vale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42658, 42659 }, ["description"] = "Lyana Stardust still lingers in a vale that has been overrun by demons. Despite its current start of upheaval, she refuses to abandon her home. The strength and stubbornness she exhibits in the face of an enemy are also traits that shine through in her enchantments. We want our weapons to be as strong and stubborn as she is. Meet her in Moonclaw Vale, and see if she can work her magic with the weapons that Kyriel has crafted for us.", ["objectivesText"] = "Find Lyana Stardust in Val'sharah.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 641, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42658] = { ["id"] = 42658, ["name"] = "Delicate Enchantments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42657, 42659 }, ["description"] = "As I'm sure you've noticed, demons have taken over the vale. Their arrival has forced many of my fellow druids to flee their homes, but I refuse to go down without a fight. Despite all this, I'm happy to provide enchantments for your weapons, but you should know that it is a delicate process that takes time and concentration, something I have little of lately. If you're willing to shelter me from attackers, I will certainly do my best to enchant your weapons.", ["objectivesText"] = "Protect Lyana Stardust while she enchants the azure weaponry. Progress: Enchanting your weapons will require a great deal of power and concentration.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108492, ["x"] = 0.6, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42659] = { ["id"] = 42659, ["name"] = "In Defense of Dalaran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["series"] = { 42133, 42657, 42658 }, ["description"] = "We have everything we need to set the trap for Hakkar. Archmage Khadgar will summon a portal to the Violet Hold. Once inside, he will begin to channel his essence into the arcane vessel at your command. Our allies will be armed with the weapons you brought them, ready to fight when Hakkar takes the bait.", ["objectivesText"] = "Enter the Violet Hold through Khadgar's portal, and defeat Hakkar the Houndmaster .", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139707, 142056, 142057, 142061, 142062, 142064, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42660] = { ["id"] = 42660, ["name"] = "Vault of the Wardens: Matters of the Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "I have made considerable progress with the Bloodstone, thanks in part to your extensive testing. The stone feeds on blood to grow in power, but its ability to control a demon comes from consuming a corrupted heart; the more powerful, the better. Within the Vault of the Wardens you'll find someone with such a heart.", ["objectivesText"] = "Collect a Felsworn Heart from Cordana within The Vault of the Wardens dungeon. Progress: The Bloodstone will grow in power after consuming Cordana's heart.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128941, 128942, 128943, 138989, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 4, ["flags"] = 0 } } },
