[42707] = { ["id"] = 42707, ["name"] = "Eye of Azshara: A Magical Affliction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42734, 42940 }, ["description"] = "Archmage Vargoth's betrayal is an unimaginable loss to our cause, <name>. We will have to deal with him, but first Meryl's condition has become dire. Unfortunately it is not an illness at all, but a magical attack of fel origin. It may be his old nemesis Kathra'natir is behind it. We need to buy him time. The Eye of Azshara contains a vast store of arcane energy from Queen Azshara herself. If we could obtain a vial of water from the Wrath of Azshara's body, that will sustain him for a while.", ["objectivesText"] = "Fill a vial with arcane water from the Wrath of Azshara. Progress: Have you obtained a vial of arcane water yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127857, 128820, 128862, 138271, 138272, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42708] = { ["id"] = 42708, ["name"] = "A Personal Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "If you have a moment, Deathlord... there is a personal matter I would like to speak with you about. Some time ago, a brother of the Ebon Blade was imprisoned beneath the ruins of Lordaeron by the Dark Lady. Sylvanas has refused all attempts to negotiate his release. Now, our world faces destruction and the time for diplomacy has passed. Koltira Deathweaver cannot fight the Burning Legion in chains. So we will break them.", ["objectivesText"] = "Rescue Koltira Deathweaver from Undercity. Progress: The time has come to release Koltira Deathweaver from captivity.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42719] = { ["id"] = 42719, ["name"] = "Eye of Azshara: Cleansing the Dreamway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Brightwing has lots of friends. I like friends! But you know who isn't Brightwing 's friend? Scary monsters from the nightmare! They hurt Brightwing 's allies, and they made the grove all yucky! This place needs to be cleansed, but I'm all out of magic. Can you bring Brightwing some purified water to help? You'll have to go far, far away... to the Eye of Azshara where the naga live.", ["objectivesText"] = "Collect 25 Rarefied Water from the naga in the Eye of Azshara, and defeat the Wrath of Azshara . Progress: Poor, poor flowers...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138993, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 15, ["flags"] = 1 } } },
[42722] = { ["id"] = 42722, ["name"] = "Friends in Cages", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "< Korine stomps her foot and refuses to move.> They put my friends in cages! Make the bad men stop hurting them! They take them out the garden and they never come back! < Korine gestures stubbornly toward the door.> I am not going home until they do!", ["objectivesText"] = "Release 3 Nightborne Citizens from their captivity. Progress: Did you let them out?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138301, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108063, ["x"] = 0.411, ["y"] = 0.593 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.411, ["y"] = 0.593 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42730] = { ["id"] = 42730, ["name"] = "Noggenfogger's Reasonable Request", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible. Marin's asking for a hefty amount of Aethril . He said something about you recently holding a blade to his throat and that he's simply returning the favor. Of course, if you would rather, I can eliminate him.", ["objectivesText"] = "Collect 20 Aethril . Progress: Heya, <name>, you have those reagents I requested? You scratch my back, and well... I'll pay someone to scratch yours.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 127837, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42731] = { ["id"] = 42731, ["name"] = "Working With the Wardens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42131, 42669, 42735, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "As much as we might not like it, we need the aid of the Wardens if we're to locate the Sargerite Keystone. They took it from you when we were all imprisoned in the vault. With Maiev missing, their current leader is Sira Moonwarden. On your behalf, I have agreed that we will assist them in tracking down some of the more powerful creatures that escaped from the Vault of the Wardens. In return, she will direct us to where we need to go to get the Keystone.", ["objectivesText"] = "Use the Scouting Map and complete the \"Working With the Wardens\" missions. Progress: Is Sira happy with our progress? Not that I care, but we do need her help.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 16, ["flags"] = 0 } } },
[42733] = { ["id"] = 42733, ["name"] = "A Very Special Kind of Fuel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42754, 42810 }, ["description"] = "All Legion constructs, including the Fel Hammer, are powered by souls. If we are going to take the command center to Niskara, we are going to need some very powerful souls, indeed! You are a very creative person, <name>. I am certain that you will find a way to get what we need from the right sorts of creatures.", ["objectivesText"] = "Collect 15 Sovereign Souls from bosses in Legion dungeons. Progress: <name>, do you have what Allari asked you to harvest for fuel?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 138482, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42734] = { ["id"] = 42734, ["name"] = "Into the Oculus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42707, 42940 }, ["description"] = "I fear Kathra'natir is behind the attack on Meryl. We have little time to act. I suspect Archmage Vargoth's involvement is no coincidence. While it greatly pains me to destroy an archmage of his caliber and worse, someone I once called friend, we cannot permit his betrayal to stand unpunished. It is time to follow him into the Oculus.", ["objectivesText"] = "Talk to Archmage Khadgar when you are ready to travel to the Oculus.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 97919, 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 142056, 142059, 142060, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42735] = { ["id"] = 42735, ["name"] = "Malace in Vrykul Land", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42736, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "I did some recon in Stormheim. What I discovered is that the Tideskorn are a tribe of vrykul who have been cut-off from the sea by their kvaldir brethren. Many of the Tideskorn have pledged their services to the Legion and become Felskorn. Malace Shade was last seen heading toward the Felskorn Warcamp. It is likely that she was captured. I have arranged a flight to Stormheim for you. When you are ready, you can use the gateway to travel to Dalaran and speak with Aludane Whitecloud at Krasus' Landing.", ["objectivesText"] = "Grab a flight from Aludane Whitecloud and find Malace Shade in Stormheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42736] = { ["id"] = 42736, ["name"] = "Rune Ruination", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42749, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "A cage wasn't enough to hold me, so the vrykul ensorcelled these runestones to trap me in here. Each is powered by a different Felskorn rune. Unfortunately, they gave the runes to different guardians, who have all scattered to different places around Stormheim. So, if Sira said that you could have your precious keystone back, you're first going to have to get me out of here. Then, we'll see.", ["objectivesText"] = "Deactivate the three runestones to set Malace free.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138111, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42737] = { ["id"] = 42737, ["name"] = "Rune Ruination: Runeskeld Rollo", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["description"] = "<Collect the rune from Runeskeld Rollo to deactivate this runestone.>", ["objectivesText"] = "Collect Rollo's Rune . Progress: <The runestone thrums with fel-corrupted power. Disable it with its corresponding rune.>", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127830, 128832, 130082, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42738] = { ["id"] = 42738, ["name"] = "Rune Ruination: Runelord Ragnar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["description"] = "<Collect the rune from Runelord Ragnar to deactivate this runestone. If you do not already have one, obtain a grapple launcher in order to scale the walls of Hrydshal.>", ["objectivesText"] = "Collect Ragnar's Rune . Progress: <The runestone is keeping Malace Shade imprisoned. Use Ragnar's rune to shut it down.>", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127284, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42739] = { ["id"] = 42739, ["name"] = "Rune Ruination: Runesage Floki", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["description"] = "<This runestone is entrapping Malace Shade. It can only be destroyed by using Runesage Floki's rune upon it.>", ["objectivesText"] = "Collect Floki's Rune . Progress: <Who knows how long the Felskorn vrykul will leave Malace Shade alive? Best to deal with the runestone sooner rather than later.>", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127830, 128832, 130083, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42740] = { ["id"] = 42740, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 40519, 42782, 43806 }, ["description"] = "This is your vessel, <name>. She's a fine ship; been through many a campaign. Speak with the ship's captain when you're ready to depart. Good luck out there. We've received few reports about what's happening at the Broken Shore, but I'd wager King Varian has matters well in hand.", ["objectivesText"] = "Take the third fleet ship to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 }, { ["mapID"] = 84, ["npcID"] = 108916, ["x"] = 0.19, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100395, ["x"] = 0.202, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42747] = { ["id"] = 42747, ["name"] = "Where the Wildkin Are", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42748, 42750, 42751, 42786 }, ["description"] = "Owlbeasts are often charged with protecting places of importance to Elune. But if her influence over them wanes or is cut off, the creatures can become dangerous. These wildkin, unfortunately, must be dealt with. The recent disturbances in Val'sharah have driven these creatures to madness. Once an individual is lost, there is only one way to address the problem. I cannot bring myself to kill one of Elune's creations, but I know what must be done.", ["objectivesText"] = "Slay 10 Owlbeasts and 8 Undulating Boneslimes within Lostlight Grotto.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42748] = { ["id"] = 42748, ["name"] = "Emerald Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42747, 42750, 42751, 42786 }, ["description"] = "The owlbeasts here are disconnected from Elune. A contingent of dryads went into their territory to find out what went wrong, but none of them have returned. I fear the worst, and I believe they are in need of rescue. While I try to learn if the owlkin can be saved, I would appreciate your help in freeing any Sisters you find in the grotto.", ["objectivesText"] = "Rescue 6 Sisters of the Moon in Lostlight Grotto.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42749] = { ["id"] = 42749, ["name"] = "Strange Bedfellows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42752, 42753, 42775, 42776, 42787 }, ["description"] = "The reason why I came out here was to capture or kill a fel lord named, Lochaber . I am no longer in a capturing mood. I'll grab my weapon and then head up to the bridge in front of the Gates of Valor. That place is a scary mess full of Felskorn vrykul and demons. How do you think I got caught? So, I'd rather not go back in there. But, I think I know a way to get the demon to come out to us.", ["objectivesText"] = "Meet Malace Shade on the bridge at the Gates of Valor and then slay Lochaber .", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 108576, ["x"] = 0.648, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42750] = { ["id"] = 42750, ["name"] = "Dreamcatcher", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42747, 42748, 42751, 42786 }, ["description"] = "I cannot hold on for much longer... I brought a dreamcatcher with me. I was to use it to steal the magic from owlbeast totems. It is the only way to break the barrier where they hold Keeper Remulos. Please help where I have failed.", ["objectivesText"] = "Charge the dreamcatcher using owlbeast totems in Lostlight Grotto. Progress: Leirana ? Oh no...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 87399, 109585, 138433, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108358, ["x"] = 0.595, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42751] = { ["id"] = 42751, ["name"] = "Moon Reaver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42751 }, ["series"] = { 42747, 42748, 42750, 42786 }, ["description"] = "We must not delay! If Keeper Remulos is in danger, he must be protected. With the dreamcatcher, we should be able to enter the lair of the owlbeast Boneflux . It must be defeated so Keeper Remulos can break free!", ["objectivesText"] = "Defeat Boneflux and rescue Keeper Remulos in The Undergorge.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812, 245258 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108887, ["x"] = 0.594, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[42752] = { ["id"] = 42752, ["name"] = "Vault of the Wardens: Vault Break-In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42753, 42775, 42776, 42787 }, ["description"] = "<All that is left now is to travel to the Isle of the Watchers off of southwest Azsuna. There, you will need to break back in to the Vault of the Wardens and descend down into its lowest recesses where once you were imprisoned.> <Within the so-called Vault of the Betrayer, where the Wardens once held Illidan's corpse, the Sargerite Keystone awaits.>", ["objectivesText"] = "Retrieve the Sargerite Keystone . Progress: Were you successful, <name>? Have you recovered the Sargerite Keystone ?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138397, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42753] = { ["id"] = 42753, ["name"] = "Vault of the Wardens: Vault Break-In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42775, 42776, 42787 }, ["description"] = "The Wardens made good on the deal. All that's left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you'll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned. Within the so-called Vault of the Betrayer, where the Wardens once held the Master's corpse, you'll find Sargerite Keystone . Good luck, <name>.", ["objectivesText"] = "Retrieve the Sargerite Keystone . Progress: Were you successful, <name>? Have you recovered the Sargerite Keystone ?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 138397, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42754] = { ["id"] = 42754, ["name"] = "Jump-Capable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42733, 42810 }, ["description"] = "While it is true that the Fel Hammer is powered, sadly, its jump engines are non-functional. If we are going to invade a demon world, we're going to have to make the command center jump-capable. We need some replacement parts. Luckily for us, the Legion brought a couple of command centers and soul engines along with them to the Broken Isles. You will find them at Faronaar in Azsuna, and at Felsoul Hold in Suramar.", ["objectivesText"] = "Collect a Fel Engine Injector , a Soul Configuration Matrix , a Fel Engine Ignition , and a Vile Spirit Converter . Progress: It's vile the way this thing operates. The whole thing is powered by souls... you do NOT want to know what happens to them.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 138111, 138483, 138484, 138485, 139404, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42756] = { ["id"] = 42756, ["name"] = "Hunger's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 37853, 37855, 37856, 37857, 37858, 37859, 37860, 37861, 37862, 37957, 37959, 37960, 37991, 38014, 38015, 38443, 42271, 42567, 42756 }, ["series"] = { 42567 }, ["description"] = "I am weak. The hunger is devastating, my friend. I understand now why your dragon rests in these pools. <cough, cough> I came to warn you but... it looks like I was too late. I hear him outside now. Ael'Yith ... is... here...", ["objectivesText"] = "Kill Ael'Yith and his construct.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 133006, 133007, 133008, 133009, 133010, 133011, 133012, 133013, 133014, 133016, 133040, 133041, 133042, 133043, 133044, 133045, 133046, 133047, 133048, 133050, 141405, 237812, 246812, 246937 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 91131, ["x"] = 0.482, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5748, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5748, ["name"] = "Defending Azurewing Repose", ["orderIndex"] = 18, ["flags"] = 0 } } },
[42762] = { ["id"] = 42762, ["name"] = "The Wanderer's Companion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42765, 42766, 42767, 42768, 42868, 42957 }, ["description"] = "Fu Zan... a wise choice. If the legends are true, its powers will be essential to our cause. We believe that the staff possessed by the Monkey King could be fabled Fu Zan, yet no one has seen him with the weapon for over a year. the Monkey King was last spotted at Tian Monastery. Be prepared for anything! He is known for being... less than forthcoming with his answers. Tak-Tak , a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", ["objectivesText"] = "Speak to Tak-Tak to fly to Tian Monastery and meet with the Monkey King .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 237812 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42765] = { ["id"] = 42765, ["name"] = "The Trial at the Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42766, 42767, 42768, 42868, 42957 }, ["description"] = "My staff was strong and mighty without peer, but since I not its master, in time it would soon disappear. The staff was a gift from the Jade Serpent, Yu'lon, but for only a single task. With my work finished, to her again it has passed. Yu'lon be the staff's keeper, holding it for those who are blessed. To her we now go now, to announce your request.", ["objectivesText"] = "Accompany the Monkey King to the Temple of the Jade Serpent and obtain Fu Zan, the Wanderer's Companion.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128937, 128938, 133948, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42766] = { ["id"] = 42766, ["name"] = "The Riddle of the Barrel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42767, 42768, 42868, 42957 }, ["description"] = "My weapon is great when in a fight, It's even handy when you sit for a bite. My favorite flask I've tied on it, hanging from a cord, The brews within are some of the best that I've ever scored. If you truly seek my weapon then bring me something nice to put into my belly, A powerful brew is what I want, something strong and smelly.", ["objectivesText"] = "Search for the objects the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138624, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42767] = { ["id"] = 42767, ["name"] = "The Riddle of the Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42768, 42868, 42957 }, ["description"] = "My weapon is strong but not for attacking, Protecting the weak is what it's enacting. In the valley are people who till the land from dawn to night, The fruits of their labor, you must show me tonight. Sacks of grain are what I require, Not just any will do, only those kissed by a fire. Bring me what I seek.", ["objectivesText"] = "Search for the objects the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138623, 173704, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42768] = { ["id"] = 42768, ["name"] = "The Riddle of Purity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42868, 42957 }, ["description"] = "Do you seek my weapon? Then you better answer my question. \"I seek something curvy and bendy but with no spine, It rushes and rushes leaving chaos behind. Sometimes it brings life, sometimes it brings death: A little is good, but a lot steals your breath. It's as common as dirt, but this part's obscure: This stuff comes from a pool that's known to be pure.\" Bring me what I seek.", ["objectivesText"] = "Search for the object the Monkey King has described in his riddle. Progress: Ah, it returns. Has the wikkit brought what I'm looking for?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 138477, 173703, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 108700, ["x"] = 0.416, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42770] = { ["id"] = 42770, ["name"] = "Seeking Guidance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "Highlord Tirion may be gone, but the Ashbringer is still out there somewhere. Its power would devastate the Legion. We must find it! I wish it were as simple as returning to where Tirion fell. It could be anywhere on that infernal landscape by now. I believe an old friend can help us find the blade. I ask that you place your faith in me and journey to Uther's tomb in the Plaguelands. We will seek answers there.", ["objectivesText"] = "Meet Lord Maxwell Tyrosus at Uther's Tomb in Western Plaguelands.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 173537, 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 22, 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42771] = { ["id"] = 42771, ["name"] = "Keeping the Peace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "The lost souls roaming the cemetery grounds have been drawn to the realm of the living in the wake of the Light's disturbance. In truth, they merely seek comfort... as we all do in these dark times since Highlord Tirion's passing. However, their unrest threatens the very sanctity of the tomb we have sworn to protect. If we are to restore peace here, then they must be exorcised.", ["objectivesText"] = "Exorcise 9 spirits. Progress: Your aid is greatly appreciated.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108778, ["x"] = 0.514, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108778, ["x"] = 0.514, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42772] = { ["id"] = 42772, ["name"] = "Sacred Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "We must ensure that those buried here are never again disturbed. Their spirits' very presence only further perturbs the Light. This cannot continue. I must maintain this barrier to ensure none of the wayward souls enter the Lightbringer's resting place. If you can purify the graves themselves, this madness can finally cease.", ["objectivesText"] = "Purify the graveyards in Sorrow Hill. Progress: Have the graveyards been purified?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 128867, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108777, ["x"] = 0.514, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108777, ["x"] = 0.514, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42773] = { ["id"] = 42773, ["name"] = "The Light Reveals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "We seek aid not from a living friend, but one who passed long ago. Uther the Lightbringer was more attuned to the subtleties of the Light than any paladin I've ever known. If we reach out to him, he may be able to help us find the Ashbringer. The ceremony has been prepared. Approach the tomb when you are ready.", ["objectivesText"] = "Commune with Uther the Lightbringer. Progress: We must do whatever it takes.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 120978, 128823, 128866, 128867, 132204, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.5165, ["y"] = 0.8075 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42774] = { ["id"] = 42774, ["name"] = "Hope Prevails", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 38376, 42770, 42771, 42772, 42773, 42774 }, ["description"] = "Tirion... still alive! We have to save him. Light's Hope Chapel is not far from here. We must rally our forces and leave at once for the Broken Shore.", ["objectivesText"] = "Meet Lord Maxwell Tyrosus at Light's Hope Chapel. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 128867, 173538, 237812 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 108776, ["x"] = 0.5165, ["y"] = 0.8075 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 90369, ["x"] = 0.742, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.5165, ["y"] = 0.8075 }, ["mapCandidates"] = { ["npc"] = { 22, 23 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 87, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 23, ["questLines"] = { { ["id"] = 87, ["name"] = "The Ashbringer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42775] = { ["id"] = 42775, ["name"] = "The Crux of the Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42776, 42787 }, ["description"] = "We have Akama. Cordana Felsong has been eliminated. And, we have the Sargerite Keystone. Everything is falling into place. The honor is all yours, <name>.", ["objectivesText"] = "Place the Sargerite Keystone above the Scouting Map. Progress: No demon world is beyond our reach now.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42776] = { ["id"] = 42776, ["name"] = "Two Worthies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42787 }, ["description"] = "As our forces grow, and our reach extends ever outward, you have need of more trusted companions to handle the most important of missions. The time has come for you to elevate two worthies into the ranks of your champions. It's my opinion that you should consider recruiting Belath and Malevolence. They have both proven themselves indispensable.", ["objectivesText"] = "Recruit Belath Dawnblade and Matron Mother Malevolence as your champions.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 10, ["flags"] = 0 } } },
