[42782] = { ["id"] = 42782, ["name"] = "To Be Prepared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 40517, 40519, 42740, 43806 }, ["description"] = "Allies from across Azeroth have come to Stormwind to support our efforts against the Burning Legion. Before you ship out, you should pay them a visit. Every bit of preparation helps!", ["objectivesText"] = "Visit Alliance forces in Stormwind Harbor. Progress: The Light protects those who protect themselves!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 59679, 59680, 59681, 59682, 59683, 59684, 65872, 65884, 65886, 138385, 138450, 139718, 141294, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107934, ["x"] = 0.368, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 108916, ["x"] = 0.19, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42786] = { ["id"] = 42786, ["name"] = "Grotesque Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42747, 42748, 42750, 42786 }, ["series"] = { 42747, 42748, 42750, 42751 }, ["description"] = "These grotesque remains are an amalgamation of jelly-like ooze and what appear to be dryad bones. Guviena Bladesong would be interested in seeing these.", ["objectivesText"] = "Speak to Guviena Bladesong at the Whispering Bluffs. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 138441, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 108304, ["x"] = 0.602, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5911, ["name"] = "Lostlight Grotto", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42787] = { ["id"] = 42787, ["name"] = "Deal With It Personally", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["series"] = { 42131, 42669, 42731, 42735, 42736, 42749, 42752, 42753, 42775, 42776 }, ["description"] = "The way I see it, the Wardens owe us for all of those years we were imprisoned. Unfortunately, their new leader, Sira Moonwarden doesn't agree with my assessment. Even though your champions have already dealt with several of their escaped bounties, she wants more. In fact, as a sign of good faith, she's asking that you deal with it personally. You'll have to extinguish the flames of the kobold candles to summon forth the Devouring Darkness . The other two should be more straightforward.", ["objectivesText"] = "Kill the Devouring Darkness in Highmountain, Hertha Grimdottir in Suramar, and Theryssia in Val'sharah. Progress: How go your efforts to convince the Wardens to tell us where the Sargerite Keystone is located? If she doesn't tell us soon, I think we should consider other options where Sira Moonwarden is concerned.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121737, 124125, 127830, 128832, 130136, 131780, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42792] = { ["id"] = 42792, ["name"] = "Make Your Mark", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "While you were out, I asked around. You are looking for Overseer Durant . Turns out he lives near the Shimmershade Garden. I can help you confront him, but you will need help. There are three individuals with the necessary skills, and they serve our cause. Tell Cyrille that the owl hoots at dusk. Inform Lorin that the saber prowls the plaza. Mention to Sylessa that the cruel caskmaster has breathed his last. They will know what to do. Speak to Vanthir when the deed is done.", ["objectivesText"] = "Recruit Sylessa , Cyrille , and Lorin and slay Overseer Durant .", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42800] = { ["id"] = 42800, ["name"] = "Champion: Valeera Sanguinar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42801] = { ["id"] = 42801, ["name"] = "Back in Black", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42593, 42594 }, ["description"] = "Before you head into the Black Temple, we need more information. The last thing we want is for you to teleport into a trap. We must discern their force structure, patrol schedule, new defenses, and what Akama eats for breakfast. <Belath grins.> I suggest you send our broken warriors to handle this. They can blend in with the rest of Akama's Ashtongue forces inside the temple. We'll get what we need to know from the ones that make it back. A champion handler or two can scout outside the temple.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Back in Black\". Progress: Any word from your troops that we sent to infiltrate the Black Temple?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42802] = { ["id"] = 42802, ["name"] = "Securing Mardum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42808 }, ["description"] = "There has been increased demonic activity below on Mardum. There are still demons leftover down there from when we first invaded. To eliminate any threat to the Fel Hammer, it's time that they were destroyed.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Securing Mardum\".", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140378, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42808] = { ["id"] = 42808, ["name"] = "Green Adepts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42802 }, ["description"] = "As much as I would love us to finesse our way to victory, the cold, hard reality is that we need more powerful forces. We are already straining Gaardoun's ability to recruit more broken. But now that we have Ariana Fireheart , she can train new demon hunters for us.", ["objectivesText"] = "Speak with your Illidari recruiter, Ariana Fireheart .", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42809] = { ["id"] = 42809, ["name"] = "The Invasion of Niskara", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42132, 42920, 43186 }, ["description"] = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready. Caria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara. It's time to begin the invasion and finish this once and for all.", ["objectivesText"] = "Activate the Fel Hammer's control console and complete the scenario, \"The Invasion of Niskara\". Progress: Finally, our plan of taking the fight directly to the demons is coming to fruition. You are making it all happen, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42810] = { ["id"] = 42810, ["name"] = "A Final Offer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42733, 42754 }, ["description"] = "What was that? Sounds like something's outside. Something big... You'd better get up there, <name>!", ["objectivesText"] = "Investigate whatever is happening outside of the Fel Hammer. Progress: What happened?", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 124125, 127830, 128832, 137623, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42811] = { ["id"] = 42811, ["name"] = "We Meet at Light's Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7796, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 39756, 42812 }, ["description"] = "We must put Highlord Tirion to rest. There is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel. Paladins the world over will join us for the ceremony. I know Tirion would want you there most of all.", ["objectivesText"] = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 140192, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7796 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42812] = { ["id"] = 42812, ["name"] = "We Meet at Light's Hope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 38376, 38566, 38576, 38933, 39756, 42811 }, ["description"] = "Before we march on the Broken Isles, <name>, we must put Highlord Tirion to rest. There is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel here. Paladins the world have gathered below for the ceremony. They await your arrival to begin the ceremony.", ["objectivesText"] = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 108956, ["x"] = 0.752, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42814] = { ["id"] = 42814, ["name"] = "An Important Mission", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39214, 39654, 40585, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 39654, 41052, 42815 }, ["description"] = "Champion! I bear an urgent message from Danath Trollbane . He requests that you join him at Krasus' Landing. He has an urgent mission that requires your expertise!", ["objectivesText"] = "Speak with Danath Trollbane at Krasus' Landing in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42815] = { ["id"] = 42815, ["name"] = "Return to the Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 695, ["storyline"] = { 39214, 39654, 40585, 42597, 42598, 42605, 42606, 42607, 42609, 42610, 42611, 42814, 42815 }, ["series"] = { 38904, 39654, 41052, 42814 }, ["description"] = "If I'm to assist in this war, I need firsthand information. I will fly to the Broken Shore and see the battlefield for myself. Your record as a proven commander is unquestioned, and you were there. I could use your insight. Will you accompany me to the Broken Shore? I don't anticipate engaging the enemy, but that close to the Fel Storm, one can never be sure.", ["objectivesText"] = "Take Danath's spare mount to the Broken Shore and provide assistance.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 128288, 128289, 128908, 128910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 213, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 213, ["name"] = "Becoming Valarjar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42818] = { ["id"] = 42818, ["name"] = "The Scarlet Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 804, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "The High Inquisitor of the Scarlet Crusade?! You will not find High Inquisitor Whitemane listed in the annals of history alongside the names of fallen heroes. Still... despite her madness and zealotry she held a bond to the Light unmatched by even the greatest paladins. There are few scarlet crusaders left on this world, but Scarlet Monastery is far from abandoned. The monastery now houses the most zealous and crazed crusaders the order has left. Success will require a full blown assault.", ["objectivesText"] = "Speak with Thassarian in Scarlet Monastery.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139538, 139673, 139676, 139680, 140517, 140763, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 804, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42821] = { ["id"] = 42821, ["name"] = "Raising an Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8285, ["mapID"] = 804, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "We underestimated the number of scarlet crusaders still residing in the monastery. The battle for control of the cathedral is taking too long. It's time to take a more resourceful approach to the battle... Raise the fallen crusaders as ghouls and send them back into the battle against their brothers and sisters. The Scarlet Crusade will not be able to hold back the tide of undeath for long.", ["objectivesText"] = "Raise 12 Festering Ghouls from the corpses of Scarlet Crusaders. Progress: Have you completed your mission?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8285 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 804, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42823] = { ["id"] = 42823, ["name"] = "The Scarlet Commander", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8285, ["mapID"] = 805, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "There is only one more obstacle standing between us and the tomb of Sally Whitemane. High Commander Goodchilde guards the path to the tomb. Although he is a zealot and a murderer, he is still a hardened knight who has dedicated his life to the eradication of our kind. He should not be underestimated... Slay him and our work here will be nearly done.", ["objectivesText"] = "Slay High Commander Goodchilde . Progress: Has High Commander Goodchilde been slain?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8285 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1618, ["db2PoiUiMapID"] = 805, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42824] = { ["id"] = 42824, ["name"] = "The Zealot Rises", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "Sometimes the line between hero and villain is nothing more than perception. As High Inquisitor, Sally Whitemane saw herself as a champion of humanity in the war against the scourge. Yet under her leadership the Scarlet Crusade slew the living along with the undead. Death can bring a silent peace to the soul, but not for Sally Whitemane. Her death is one of regret and unrest. We will offer her the chance to atone for her crimes. The price will be high, but I have little doubt she will pay it.", ["objectivesText"] = "Raise Sally Whitemane as a Death Knight.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42828] = { ["id"] = 42828, ["name"] = "Moths to a Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "No doubt you have noticed our guests. I have watched them for a time and seen how they are attracted to the tree. I do not know if they are harmful to our sapling, but we cannot take that chance. Collect a handful of the insects and bring them to me. I will examine them and determine if they are to be left alone.", ["objectivesText"] = "Collect 4 Underglow Locusts . Progress: Have you acquired a sufficient sampling?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42829] = { ["id"] = 42829, ["name"] = "Make an Entrance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I need you to infiltrate the Twilight Vineyards and bring back something to deal with these insects. To do that, you will need a way to bypass the guards that keep the orchards secure. Ly'leth will be able to help us there. I will arrange to have her meet you near the entrance. Go quickly!", ["objectivesText"] = "Meet with Ly'leth Lunastre outside the Twilight Vineyards. Progress: Can I help you?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139790, 140255, 140410, 141605, 141678, 141953, 141954, 180731, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42832] = { ["id"] = 42832, ["name"] = "The Fruit of Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "It is my job to maintain appearances here. < Margaux smiles apologetically.> You will have to endure a little showmanship while I walk with you through the vineyard. It is the only way to avoid suspicion. I will try to help you as I can, but only when it is safe to do so. Come with me- our first stop is the tasting pavilion. There you can sample some of our work.", ["objectivesText"] = "Taste the Honeyed Infusion, Supple Nectar, and Unctuous Draught. Progress: Enjoying yourself?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140187, 140188, 140189, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42833] = { ["id"] = 42833, ["name"] = "How It's Made: Arcwine", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Margaux speaks in a hushed tone.> While we walk through the Vineyard, we may find time to exchange information. Try not to look alarmed at what you see, hm? < Margaux flashes a vacant, forced smile.> Shall we press on?", ["objectivesText"] = "Follow Margaux through the Vineyard. Exchange information where possible.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42834] = { ["id"] = 42834, ["name"] = "Intense Concentration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "This is a rare treat, I hope you know. Not just anyone is allowed to stand on this hallowed ground. < Sylverin adjusts his cuffs in a dignified fashion.> To participate in the demonstration, simply take up an energy vessel and wade into the pool beside us. Catch the delicate dewdrops of Nightwell energy in the bowl as they fall- this is the only way one can safely manage its essence. Once your vessel is full, proceed to our demonstration cask and gently pour the amalgamation into it. Enjoy!", ["objectivesText"] = "Catch 15 drops of Nightwell Essence using an Energy Vessel . Progress: Having trouble?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42835] = { ["id"] = 42835, ["name"] = "The Old Fashioned Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "While you experienced the raw majesty that is Nightwell Infusion, Margaux was busy preparing another demonstration for you. Head across the bridge and to the left, then again across a bridge and to your right. You will find her on the juicing veranda. Enjoy the remainder of your tour! < Sylverin offers an intensely fake smile.>", ["objectivesText"] = "Participate in a juicing demonstration. Progress: Having fun?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42836] = { ["id"] = 42836, ["name"] = "Silkwing Sabotage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Moths. Who ever heard of something so... barbaric! They are eating our crop and the mana wyrms do nothing to deter them. You. You seem capable. Deter these creatures so we can complete our harvest on schedule. Ahem. Please.", ["objectivesText"] = "Slay 8 Tattered Silkwings . Progress: Are you sure you took care of this situation?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 }, { ["mapID"] = 680, ["npcID"] = 112653, ["x"] = 0.612, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 6, ["flags"] = 0 } } },
[42837] = { ["id"] = 42837, ["name"] = "Balance to Spare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Our tour is just about over. I will let you loose to 'walk the orchard', as is proper at this stage. While you are there, you will notice a large number of mana wyrms floating about. I am certain the vineyard would not miss a handful of them. Good luck with your insect problem, friend. < Margaux smiles warmly at you.>", ["objectivesText"] = "Collect 8 Shadescale Flyeaters.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108872, ["x"] = 0.572, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42838] = { ["id"] = 42838, ["name"] = "Reversal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Sylverin regards you uneasily.> I was meant to meet you and Margaux here so I could escort you from the Vineyard. My mistress Margaux is never late. I fear that something terrible may have happened. Please find her and make sure she is well.", ["objectivesText"] = "Locate Margaux . Progress: How did your trip to the Vineyard go?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42839] = { ["id"] = 42839, ["name"] = "Seek the Unsavory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "This is just... unspeakable. Margaux risked everything to get these mana wyrms to us. I cannot let it end this way. I need you to find someone who can make this right. Someone who will do whatever it takes to see Overseer Durant slain. Speak with Vanthir . I am certain he will know exactly who we need.", ["objectivesText"] = "Speak to Vanthir .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 10, ["flags"] = 0 } } },
[42840] = { ["id"] = 42840, ["name"] = "If Words Don't Work...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "Unless you have something worth risking my life for, I will not budge. Vanthir must have told you that my services do not come cheap. Let's say... enough mana to sustain me for a month. < Arluin looks smug, as if you could never agree to this request.>", ["objectivesText"] = "Bribe Arluin with 800 Ancient Mana. Progress: My price will not change. Do we have a deal?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141652, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42841] = { ["id"] = 42841, ["name"] = "A Big Score", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I'm not rich in anything but information, but maybe that can be of use to someone with your skills. You helped me, now you can help yourself. The Magistrix receives a daily shipment of arcwine, which travels to the palace with a heavy escort. I can share the location, provided you leave me a cut of the goods. One of my men has infiltrated the group and will hold up the delivery long enough for you to strike.", ["objectivesText"] = "Attack the Magistrix's arcwine shipment and bring Arluin his cut of the stolen goods. Progress: Where's my cut?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42844] = { ["id"] = 42844, ["name"] = "Growing Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["description"] = "Lord Maxwell Tyrosus has requested your presence back at the Sanctum of Light. Our campaign to defend the Broken Isles is getting under way, and we need you at the helm.", ["objectivesText"] = "Speak to Maxwell Tyrosus at the Sanctum of Light.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 9, ["flags"] = 1 } } },
[42846] = { ["id"] = 42846, ["name"] = "The Blood Matriarch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42847, 42848, 42849, 42850 }, ["description"] = "I am but the first of many; you must find the holiest of paladins to champion our order. There is one other I believe deserves such an honor - Lady Liadrin, Matriarch of the Blood Knights. Go speak to her now.", ["objectivesText"] = "Enlist Lady Liadrin as a champion of the Order of the Silver Hand.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 11, ["flags"] = 0 } } },
[42847] = { ["id"] = 42847, ["name"] = "Dark Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42848, 42849, 42850 }, ["description"] = "Greetings, Highlord. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles. The first task is critical - the storms above the Tomb of Sargeras are intensifying. We should send our champions to keep an eye on that region, and scour the area for possible survivors.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Dark Storms.\" Progress: How is the mission proceeding?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 31857, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 13, ["flags"] = 0 } } },
[42848] = { ["id"] = 42848, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42849, 42850 }, ["description"] = "Commander Ansela is a grizzled war veteran and seasoned teacher. Many of our most valiant knights once trained under her. Go speak to her now, and recruit a squad of Squires .", ["objectivesText"] = "Speak to Commander Ansela and recruit a squad of Squires . Progress: Additional troops will be very useful for the missions ahead.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 14, ["flags"] = 0 } } },
[42849] = { ["id"] = 42849, ["name"] = "Wrath and Justice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42848, 42850 }, ["description"] = "A new mission requires our attention, Highlord <name>. Hearthglen has come under attack by a small demon army. No doubt, they are testing our strength... and our patience. Strength we have in bounds, but my tolerance wears thin. I suggest we send our champions and troops to deal with this threat.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Wrath and Justice.\" Progress: We will show the enemy who they are dealing with.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 15, ["flags"] = 0 } } },
[42850] = { ["id"] = 42850, ["name"] = "Tech It Up a Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 38566, 38576, 38710, 38933, 39696, 39756, 40408, 42811, 42812, 42844, 42846, 42847, 42848, 42849, 42850, 42881 }, ["series"] = { 42846, 42847, 42848, 42849 }, ["description"] = "Alamande Graythorn is well known among scholars of the Light. He has long since retired from battle, but his mind is sharp as ever. I wouldn't be surprised if he could take a bout or two in a duel, either. Speak to him and see if he has any knowledge to share regarding the improvement of our order hall.", ["objectivesText"] = "Speak to Alamande Graythorn and choose a class hall upgrade. Progress: Did you learn anything?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 86, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 86, ["name"] = "The Silver Hand", ["orderIndex"] = 16, ["flags"] = 0 } } },
