[42857] = { ["id"] = 42857, ["name"] = "Moist Around the Hedges", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42857, 42865, 42883, 42884 }, ["description"] = "These fruit appear to be food to grell. Old Grizzleback might appreciate it if they were removed from the village.", ["objectivesText"] = "Collect 5 Moist Grizzlecombs in Grizzleweald. Progress: You have found a fruit that might be of interest to me?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 138788, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5913, ["name"] = "Grizzleweald", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42865] = { ["id"] = 42865, ["name"] = "Grell to Pay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42857, 42865, 42883, 42884 }, ["description"] = "The ringleader of the grell must be sent to his final rest. You will know him by the white of his skin and the bite of his tongue.", ["objectivesText"] = "Defeat Enderkind in Grizzleweald. Progress: I miss the days when grell kept to themselves and played tricks on the night elves.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109631, ["x"] = 0.666, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5913, ["name"] = "Grizzleweald", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42866] = { ["id"] = 42866, ["name"] = "A Sign From The Sky", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 627, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 44257 }, ["description"] = "Greetings, Highlord. I have important news to share with you. During my expedition to the Broken Shore, I saw with my own eyes an extraordinarily luminescent object emerge from the Felstorm. It fell down towards the coast of Suramar, cutting a swath through the tempest itself! From it I felt an incredible surge of power, before it vanished beyond the horizon. We need to bring news of this immediately to Archmage Khadgar .", ["objectivesText"] = "Speak to Archmage Khadgar in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42867] = { ["id"] = 42867, ["name"] = "Meeting of the Silver Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42919 }, ["description"] = "The Light's Heart will be safe within our order's walls, but it bears dark tidings. We should gather the leaders of our order for a council. Go and speak to Lady Liadrin , Vindicator Boros , Justicar Julia Celeste , Arator the Redeemer, and Aponi Brightmane . We should seek their wisdom for the days ahead.", ["objectivesText"] = "Speak to Lady Liadrin , Vindicator Boros , Justicar Julia Celeste , Arator the Redeemer, and Aponi Brightmane . Progress: Have you gathered the council?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140763, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42868] = { ["id"] = 42868, ["name"] = "The Monkey King's Challenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42768, 42957 }, ["description"] = "You can roll, you can hit, even shoot flaming spit... But can your training you heed? Tasty brew's what I need! The goodies you've gathered are what you must mix, The instructions to follow will come from my lips. Just pass this final brewing lesson, And I will point you to my weapon.", ["objectivesText"] = "Help the Monkey King to complete his brew. Progress: Ah! This brew is grand! It's fit for a King!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128937, 128938, 133948, 138477, 138623, 138624, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42869] = { ["id"] = 42869, ["name"] = "Eternal Vigil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "<Kor'vas glances at your glaives, her eyes widening.> I'm excited to see what those can do in person! Maybe we can spar a bit before heading out on the next hunt? While you were gone we built a camp just off of this landing to help us watch over the Legion's movements. We should head there right away - Jace needed your help with something. It sounded big!", ["objectivesText"] = "Glide to Illidari Redoubt off of Krasus' Landing.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42872] = { ["id"] = 42872, ["name"] = "Securing the Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42869, 42872, 44379, 44383 }, ["description"] = "I was able to make contact with our forces on Mardum - they secured the Fel Hammer after our departure all those years ago and have held it ever since! Malevolence has utilized the ship's warp systems to transport the bulk of our forces aboard, but doing so greatly taxes what little power remains. I believe there to be a better way. Your glaives carry a piece of the power of Kil'jaeden - you should be able to use them to open a permanent gateway to the Fel Hammer.", ["objectivesText"] = "Use your glaives to rip open a gateway to the Fel Hammer in Mardum. Progress: Soon our forces will flow freely between the here and the Fel Hammer.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 127830, 128832, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 161, ["name"] = "The Illidari", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 5, ["flags"] = 0 } } },
