[42918] = { ["id"] = 42918, ["name"] = "Demonic Runes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "Hodir valiantly went through that demonic portal. He should've earned an honorable death, but instead was taken prisoner by Legion scum. We always imagined the battles of the end days to take place here in Azeroth, but we shall bring the fight to the enemy if it means sparing one of our own that terrible fate. Hymdall thinks that with the right power source, he can reactivate and redirect the Legion's own gateways. Gather demonic runestones from the Legion and let the final conflict begin!", ["objectivesText"] = "Obtain 30 Demonic Runes from demons in the Broken Isles. Progress: You bring the demonic runestones , <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 138817, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42919] = { ["id"] = 42919, ["name"] = "The Scion's Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42867 }, ["description"] = "The leaders of the Silver Hand have gathered. Listen to their counsel.", ["objectivesText"] = "Listen to the leaders of the council. Progress: Our next steps will be very important.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140356, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42920] = { ["id"] = 42920, ["name"] = "The Invasion of Niskara", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 42132, 42733, 42754, 42809, 42810, 42920, 43184, 43185, 43186 }, ["series"] = { 42132, 42809, 43186 }, ["description"] = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready. Caria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara. It's time to begin the invasion and finish this once and for all.", ["objectivesText"] = "Activate the Fel Hammer's control console and complete the scenario, \"The Invasion of Niskara\". Progress: Finally, Illidan's plan of taking the fight directly to the demons is coming to fruition. You are making it all happen, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5890, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5890, ["name"] = "Destiny of the Illidari III", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42921] = { ["id"] = 42921, ["name"] = "Confrontation at the Black Temple", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 37447, 39741, 42131, 42510, 42522, 42593, 42594, 42634, 42653, 42664, 42665, 42673, 42731, 42801, 42802, 42808, 42921 }, ["series"] = { 42665 }, ["description"] = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers. I will need but a moment to summon a gateway. Stand back, please.", ["objectivesText"] = "Use the Gateway to the Black Temple and confront Akama .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 124125, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5888, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5888, ["name"] = "Destiny of the Illidari I", ["orderIndex"] = 6, ["flags"] = 0 } } },
