[42931] = { ["id"] = 42931, ["name"] = "Where the Hammer Falls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42932, 42933, 42935, 42937 }, ["description"] = "You saved us all, shaman! Thank you! Thrall wants to dive right into the Maelstrom and retrieve the Doomhammer, but I worry - he was badly wounded in that last fight, and that demon Geth'xun may still be alive down there. We should go with him. Hop on Stormbeak when you're ready and we'll track down that artifact!", ["objectivesText"] = "Use Stormbeak to fly into the Maelstrom with Thrall and Mylra.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96539, ["x"] = 0.500667, ["y"] = 0.393333 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.500667, ["y"] = 0.393333 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42932] = { ["id"] = 42932, ["name"] = "What the Stonemother Knows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42933, 42935, 42937 }, ["description"] = "We must split up. I am still badly wounded from my encounter with Geth'xun, and I don't want to appear weak before the Stonemother. This task falls to you. Travel to Therazane 's Throne and speak to Therazane herself. Find out if she has seen the Doomhammer. Help her if she asks. She is dangerous and mercurial, but this is her realm, and without her aid we will find nothing.", ["objectivesText"] = "Travel to Therazane 's Throne and speak with Therazane the Stonemother.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 96527, ["x"] = 0.533333, ["y"] = 0.258667 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.533333, ["y"] = 0.258667 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42933] = { ["id"] = 42933, ["name"] = "The Troggs that Fel to Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42935, 42937 }, ["description"] = "\"Demons\" you say? A \"Burning Legion?\" Hrmph! Nothing burns here but for my ire, shaman, and if these monsters think to corrupt my domain, they will be crushed beneath my dainty beautiful feet! I have not seen this hammer of yours, but the stone troggs witnessed everything that fell from the sky. Moreover, they've been running amok in the Pale Roost ever since the green fire landed near their home. Be a dear and lay waste to the Felrock Troggs west of here. Perhaps you can get one of them to talk.", ["objectivesText"] = "Slay 25 Felrock Troggs in the Pale Roost. Progress: Well? Have you given them a solid thrashing?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42935] = { ["id"] = 42935, ["name"] = "Stone Drake Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42933, 42937 }, ["description"] = "When that demon of yours fell into my realm he must have done something to the troggs. They were never a threat to my beloved stone drakes before. Now they're loose all over the Pale Roost, subduing drakes on the ground. Put a stop to this insult at once, and free those drakes! They may be of use to us later.", ["objectivesText"] = "Rescue 6 Stone Drakes in the Pale Roost by defeating the troggs that torment them. Progress: What of my precious little drakes, hm?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42936] = { ["id"] = 42936, ["name"] = "Clutch Play", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["description"] = "I confess the stone drake broodmother and I have had a rocky relationship in the past. She supported Deathwing during the Cataclysm, you know. But Aeosera has been put back in her place and it is my responsibility to protect her. The problem is that she refuses to abandon her eggs, even in the midst of a trogg attack. You're a shaman! Use your natural magnetism to reassemble fallen Opalescent Guardians in the Pale Roost. Escort them to Aeosera so they can carry her eggs to safety of my bosom.", ["objectivesText"] = "Escort 5 Opalescent Guardians to Aeosera. Progress: Step to it, <class>! Reassemble those guardians and take them to Aeosera!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42937] = { ["id"] = 42937, ["name"] = "Needlerock Beatdown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 }, ["series"] = { 42931, 42932, 42933, 42935 }, ["description"] = "The troggs saw where your hammer fell, and I expect those cowards told the Legion where to find it. Hmph! The leader of the stone troggs since the Cataclysm has been \"Borlock,\" a thick-headed little dirt-grubber who's about to get what's coming to him. Find him at Needlerock Spire and beat the information out of him. Take Aeosera with you. Her and her brood have their own score to settle with those belligerent little beasts.", ["objectivesText"] = "Fly with Aeosera to Needlerock Spire and defeat Borlock of the Deeps . Progress: Oh I so love to see Aeosera in action.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 265, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 265, ["name"] = "Call of the Doomhammer", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42940] = { ["id"] = 42940, ["name"] = "When There's a Will, There's a Way", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["series"] = { 42493, 42520, 42707, 42734 }, ["description"] = "The Oculus appears to have fallen to the Burning Legion and is heavily shielded. We will need to figure out a way to get you inside. I suspect your champions can help us out quite a bit.", ["objectivesText"] = "Ask your champions to find a way into the Oculus.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42954] = { ["id"] = 42954, ["name"] = "A Small Favor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42955, 42956, 42959 }, ["description"] = "Meryl's illness is troubling. I have seen something similar before, but I cannot think of its name... Talk to my friend. I call her Ari . She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.", ["objectivesText"] = "Talk to Ari .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42955] = { ["id"] = 42955, ["name"] = "The Proper Way of Things", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42956, 42959 }, ["description"] = "Archmage Khadgar is my friend. That he trusts you means much. I know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.", ["objectivesText"] = "Siphon 50 phials of nightwell energy from the nightborne in Suramar City. Progress: Have you found enough nightwell energy yet?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 137299, 138853, 138965, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42956] = { ["id"] = 42956, ["name"] = "Ari's Package", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42955, 42959 }, ["description"] = "Look! It was right here under our noses. \"Arcanists Guide to Rare Diseases.\" Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough. Here. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth's wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.", ["objectivesText"] = "Bring Ari 's package to Archmage Khadgar . Provided item:", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 138866, 141880, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42957] = { ["id"] = 42957, ["name"] = "Journey to the East", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 42762, 42765, 42766, 42767, 42768, 42868, 42957 }, ["series"] = { 42762, 42765, 42766, 42767, 42768, 42868 }, ["description"] = "My riddles you've solved but your job is not complete. Come, meet me at the Jade Serpent Temple for the answers you seek.", ["objectivesText"] = "Meet with the Monkey King at the Temple of the Jade Serpent within the Jade Forest. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 128937, 128938, 133948, 173706, 237812 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 109187, ["x"] = 0.554, ["y"] = 0.582 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 194, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 194, ["name"] = "Fu Zan, The Wanderer's Companion", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42959] = { ["id"] = 42959, ["name"] = "Three Is a Lucky Number", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42416, 42423, 42424, 42451, 42493, 42494, 42508, 42520, 42521, 42702, 42704, 42954, 42955, 42956, 42959 }, ["series"] = { 42954, 42955, 42956 }, ["description"] = "Ari is much more than she appears, you know. She was once one of the most powerful archmagi on Azeroth and a member of the Council of Tirisfal. Unfortunately her mind was badly damaged and she has not left the Hall of the Guardian since. She must like you very much to have given you a gift. If you bring her something special in return, I suspect she will surprise you. She prefers things in threes.", ["objectivesText"] = "Bring Ari 3 special gifts. These gifts can be found on powerful enemies in dungeons. Progress: Have you found anything special for Ari yet?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 138968, 138969, 138971, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5869, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5869, ["name"] = "Rise of the Tirisgarde II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42966] = { ["id"] = 42966, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Holy Allies.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[42967] = { ["id"] = 42967, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads. To defeat them, we will need to stay vigilant on all fronts. Let us send our champions to deal with the Legion incursions as they come.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Legion Defense.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[42968] = { ["id"] = 42968, ["name"] = "The Highlord's Command", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["description"] = "You are right, Highlord. Our military efforts cannot succeed without solid logistics. That means we need a steady supply of weapons, food, medicine, and other provisions. Let us send our champions to establish a supply line.", ["objectivesText"] = "Complete the mission, \"The Highlord's Command: Procuring Supplies.\"", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 9, ["flags"] = 0 } } },
[42974] = { ["id"] = 42974, ["name"] = "The Fate of Hodir", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "It is time, <name>. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir. The Legion will regret they set foot on Azeroth!", ["objectivesText"] = "Join your forces at Felblaze Ingress and Complete the Fate of Hodir scenario. Progress: You've returned, <name>. What news do you bring?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139681, 142057, 142059, 142061, 142063, 142064, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42977] = { ["id"] = 42977, ["name"] = "Servant of the Windseeker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 81, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "The elemental lords must be united, but there has been no Windlord to lead the air elementals since the death of Al'Akir. Once, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince's rebirth. There is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.", ["objectivesText"] = "Speak with Highlord Demitrian in Silithus.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 14347, ["x"] = 0.295, ["y"] = 0.1055 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.1055 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42983] = { ["id"] = 42983, ["name"] = "Mistral Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "To restore the Maelstrom Pillar, we will need to infuse it with the essence of air. A large quantity of Mistral Essence will be required to do this. Mistral Essence can be found on many of the elementals in Vortex Pinnacle. If you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.", ["objectivesText"] = "Collect 100 Mistral Essences from wind elementals in Vortex Pinnacle. Travel to the Vortex Pinnacle through the portal in the Heart of Azeroth. Progress: Were you able to collect the necessary amount?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138994, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42984] = { ["id"] = 42984, ["name"] = "Eye of Azshara: The Scepter of Storms", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar. Air, no matter how capricious, cannot resist a good storm. In the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms . Retrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.", ["objectivesText"] = "Collect the Scepter of Storms from Lady Hatecoil in the Eye of Azshara dungeon. Progress: I hope it was easy to convince Lady Hatecoil to part with her scepter.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138995, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42986] = { ["id"] = 42986, ["name"] = "Enemies of Air", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly. In his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos. We will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.", ["objectivesText"] = "Complete 4 \"Thunderaan's Enemies\" missions. Progress: How are the missions going?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42988] = { ["id"] = 42988, ["name"] = "Worldmender", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before. However, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles. When we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.", ["objectivesText"] = "Complete 10 World Quests. Progress: How does the situation look?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[42989] = { ["id"] = 42989, ["name"] = "Ma'haat the Indomitable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg. The Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later. First, we must find that egg! The Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!", ["objectivesText"] = "Speak to Ma'haat the Indomitable in Deepholm to acquire a Fossilized Egg. He will require Blood of Sargeras in trade.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42990] = { ["id"] = 42990, ["name"] = "Neltharion's Lair: The Earthen Amulet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "That you were even able to acquire the Egg of Gaiath is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope. For the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg. There is an item that just may have the ability to do this - a relic known as the Earthen Amulet , rumored to have been created by Loken himself. It was lost many ages ago, and has fallen into the hands of Dargrul the Underking.", ["objectivesText"] = "Retrieve the Earthen Amulet from Dargrul the Underking in Neltharion's Lair. Progress: Neltharion collected many valuable relics. The Earthen Amulet was one of them.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 138999, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 4, ["flags"] = 0 } } },
[42995] = { ["id"] = 42995, ["name"] = "A Taste For Blood", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["objectivesText"] = "Progress: Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep... Such a barter will cost you... greatly. Bring me 5 Blood of Sargeras , and I will give you the egg.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[42996] = { ["id"] = 42996, ["name"] = "The Maelstrom Pillar: Air", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41742, 41743, 41775, 41777, 41897, 41898, 41899, 41900, 42065, 42068, 42200, 42983, 42984, 42986, 42996 }, ["description"] = "Elementalist Janai was looking for you earlier, Farseer. It appears that her study of the Maelstrom Pillar has been most enlightening. If you have a moment, you should go and meet with her to discuss her progress.", ["objectivesText"] = "Speak to Elementalist Janai at the Heart of Azeroth.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5864, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5864, ["name"] = "The Elemental Lords II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[42997] = { ["id"] = 42997, ["name"] = "The Maelstrom Pillar: Earth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "Elementalist Janai has been hard at work restoring the Maelstrom Pillar. As of late, she has been focusing her research on the element of earth. You should speak with her when you have a chance. I have heard that she is close to a breakthrough.", ["objectivesText"] = "Speak to Elementalist Janai at the Heart of Azeroth.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43002] = { ["id"] = 43002, ["name"] = "Blessed Blade of the Windseeker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "So the Earthen Ring wishes to resurrect my master? < Highlord Demitrian laughs maniacally.> I knew this day would come! At last, humanity understands the power of the Windseeker! When Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury. To resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master's sword traveled to the Broken Isles to fight demons.", ["objectivesText"] = "Locate the lost blade of the Windseeker. Progress: Have you found the key to resurrecting Thunderaan?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 19019, 124124, 128819, 128911, 128935, 137209, 137225, 137374, 139000, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 14347, ["x"] = 0.295, ["y"] = 0.1055 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.1055 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43003] = { ["id"] = 43003, ["name"] = "Return to Janai", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 41744, 41745, 41746, 41747, 41772, 41773, 41888, 41934, 42208, 42988, 42989, 42990, 42995, 42997, 43003, 91621 }, ["description"] = "< Ma'haat the Indomitable speaks to you with a low, rumbling voice.> Here... is the Egg of Gaiath . It is yours now. Go... in peace.", ["objectivesText"] = "Return to Elementalist Janai at the Heart of Azeroth. Provided item:", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138997, 237812 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42470, ["x"] = 0.587, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.587, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5865, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5865, ["name"] = "The Elemental Lords III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43007] = { ["id"] = 43007, ["name"] = "Return to the Chamber of Shadows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43013, 43014, 43015 }, ["description"] = "Lord Jorach Ravenholdt sent me out to find you, <name>. He wants your counsel on some matter of importance. He requests your presence back at the Chamber of Shadows.", ["objectivesText"] = "Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43013] = { ["id"] = 43013, ["name"] = "The School of Roguery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43014, 43015 }, ["description"] = "Great! Sounds like she's already settled in. That's good, cuz we already need some fresh meat for the grinder. You should mosey over an' see if she's got any thieves just lying around takin' up space.", ["objectivesText"] = "Speak with Lonika Stillblade and train a Gang of Bandits . Progress: How's the new 'school' comin' along?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 11, ["flags"] = 0 } } },
[43014] = { ["id"] = 43014, ["name"] = "The Big Bad Wolfe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43013, 43015 }, ["description"] = "You've heard of Winstone Wolfe , right? Of course you have. Who hasn't? So, while you were off gabbin' with the headmistress, Lord Ravenholdt graced me with his presence. In the flesh. I didn't think he ever came out of that chamber. Anywhoodles, he more than suggested, in that way of his, that we send Garona, Vanessa, and our new merry gang of bandits off to have a little chat with The Wolf at Ravenholdt Manor. Just make sure they're nice and civil, or that's the last we'll see of them.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"The Big Bad Wolfe\". Progress: How'd the trip out to Ravenholdt Manor go?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139002, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43015] = { ["id"] = 43015, ["name"] = "What Winstone Suggests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 40832, 40839, 40840, 40950, 40996, 40997, 42139, 42140, 43007, 43013, 43014, 43015, 43261, 43262 }, ["series"] = { 42139, 42140, 43007, 43013, 43014 }, ["description"] = "If anyone can improve the way things run around here, it's Winstone Wolfe. I tell ya, the man is a miracle-worker! Now that he's workin' for us, shall we pick his brain an' see what he suggests?", ["objectivesText"] = "Speak to Winstone Wolfe. Progress: I see that you were able to convince Mr. Wolfe to join us. Of course, that rather sizeable sum of gold we deposited into his bank account didn't hurt either.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5852, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5852, ["name"] = "The Uncrowned", ["orderIndex"] = 13, ["flags"] = 0 } } },
[43054] = { ["id"] = 43054, ["name"] = "An Ample Stockpile", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "I have gone through our stockpile several times and no matter how I try to cut corners, we come up short. A lack of food and medicine will halt our war efforts... that is simply the reality. We desperately need food or bandages. If you know how to acquire any such items, you can bring them to me.", ["objectivesText"] = "Turn in 100 Spiced Rib Roasts, Highmountain Salmon, or Silkweave Bandages for Lao Shu 's stockpile. The Cooking and First Aid professions may be useful for this task.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124109, 124119, 124437, 133564, 133589, 133815, 133940, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43058] = { ["id"] = 43058, ["name"] = "Spiced Rib Roast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["objectivesText"] = "Progress: Spiced Rib Roast is a light meal that can be made by those skilled in cooking. If you are not learned in this profession, you may be able to acquire the services of a cook elsewhere.", ["rewardItems"] = { 133564 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 5, ["flags"] = 1 } } },
[43060] = { ["id"] = 43060, ["name"] = "Highmountain Salmon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 709, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["objectivesText"] = "Progress: This delicious fish can be found in the pools of Highmountain. Taking up fishing can be a productive and rewarding profession. Or, I hear there are plenty of fishers who are open to trading.", ["rewardItems"] = { 124109, 124124 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 4, ["flags"] = 1 } } },
