[43062] = { ["id"] = 43062, ["name"] = "Further Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 371, ["storyline"] = { 41736, 41737, 41738, 41849, 41850, 41851, 41852, 41853, 41854, 41907, 41909, 43054, 43058, 43060, 43061, 43062 }, ["description"] = "You may be the Grandmaster, but mastery must be maintained through discipline. To achieve perfect harmony, you must continue your training. I would like to see your form in practice, <name>. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.", ["objectivesText"] = "Use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike abilities 10 times each. Progress: To achieve mastery, we must hone ourselves tirelessly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 237812 }, ["starts"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 104744, ["x"] = 0.454, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5879, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5879, ["name"] = "Journey of the Grandmaster II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43090] = { ["id"] = 43090, ["name"] = "Ulduar's Oath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42616, 42618, 43090, 43586, 43604 }, ["description"] = "I was once leader of all of the titanforged keepers of Azeroth. We were charged by the Titans themselves to protect the world. Once I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers. Not even my own son, Thorim, is bound to heed my commands. The Gjallarhorn comes from a time before our falling out, however. A time of an ancient oath of honor. Let us invoke that oath -- I am certain Thorim will answer the call.", ["objectivesText"] = "Ask Hymdall to sound the Gjallarhorn and request Thorim's assistance. Progress: What news do you bring from Ulduar?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139506, 139688, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5806, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5806, ["name"] = "Chronicles of Skyhold II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43100] = { ["id"] = 43100, ["name"] = "Finding the Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 22, ["storyline"] = { 43100, 43153, 43254 }, ["series"] = { 43153, 43215 }, ["description"] = "Very powerful, but difficult to acquire. Scepter is in the hands of Gul'dan. We must find out his plans, get close. Calydus know Gul'dan planning major operation. He has sent out a call to arms to all Shadow Council to help with big ritual. One such group at Caer Darrow, talking to the necromancers there. You should go, find out about plan.", ["objectivesText"] = "Go to Caer Darrow in Western Plaguelands and find out about the Shadow Council ritual. Progress: This gets complicated, but Calydus have idea!", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128941, 128942, 128943, 139035, 139506, 139765, 139767, 139770, 140517, 140922, 173526, 237812 }, ["ends"] = { { ["mapID"] = 22, ["npcID"] = 109698, ["x"] = 0.692, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 22, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43151] = { ["id"] = 43151, ["name"] = "Making A Trade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 32442, 41038, 41039, 41040, 41059, 41086, 41087, 41739, 41910, 41911, 43151 }, ["description"] = "Yes I do have Amaranthine Hops , but they took me quite some time to gather. I cannot part with them easily. However, I'd be willing to trade them for Stonehide Leather . If you come upon any, bring it to me and we can make a trade.", ["objectivesText"] = "Obtain 20 Stonehide Leather . Progress: Do you have leather to trade?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 124113, 139033 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 109738, ["x"] = 0.562, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 109738, ["x"] = 0.562, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5880, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5880, ["name"] = "Journey of the Grandmaster III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43153] = { ["id"] = 43153, ["name"] = "An Eye for a Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 28, ["mapID"] = 22, ["storyline"] = { 43100, 43153, 43254 }, ["series"] = { 43100, 43215 }, ["description"] = "Sounds simple? Make nice with Shadow Council friend must... for now. Help with ritual enough to gain trust, then turn tables! Council made portal device to Tol Barad here. Go, help Shadow Council find Eye of Dalaran, earn spot in big ritual! Then steal Scepter! Calydus will try to keep eye on friend when possible.", ["objectivesText"] = "Take the portal to Tol Barad and help find the Eye of Dalaran.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["starts"] = { { ["mapID"] = 22, ["npcID"] = 109698, ["x"] = 0.692, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 22, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 22 }, ["zone"] = { 28 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43182] = { ["id"] = 43182, ["name"] = "The Missing Vessel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 680, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "So long as Hakkar roams free, no mage will be safe. Millificent Manastorm created a vessel that siphons the essence of a mage, binding their magic to the object. It was created to be a weapon, but we can use it as bait. If I channel my essence into the vessel, it will become an object of pure magic. Upon capture, Millificent shattered the vessel, allowing it to fall into the hands of our enemies. Find the pieces and return them to me. Together we can set a trap Hakkar won't be able to resist!", ["objectivesText"] = "Interact with the Scouting Map and complete \"The Missing Vessel\" missions to collect Shattered Vessel Fragments. Progress: Have you found the missing pieces yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139041, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107966, ["x"] = 0.38, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 2, ["flags"] = 0 } } },
