[43249] = { ["id"] = 43249, ["name"] = "The Raven's Eye", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42684, 43250, 43253, 43468 }, ["description"] = "It is imperative that we decipher the SI:7 letter. We must uncover the secrets that it holds before it is too late. But, our best code breakers have yet to make a dent in the cypher. However, we now know that the myth is in fact reality. The Raven's Eye truly exists. Shall we tell the others?", ["objectivesText"] = "Listen to Valeera's tale of the Raven's Eye. Progress: Are you interested, or not?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43250] = { ["id"] = 43250, ["name"] = "Off to Court", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42684, 43249, 43253, 43468 }, ["description"] = "The Ravencourt of Black Rook Hold is where we begin our search. It is the ancestral home of Lord Kur'talos Ravencrest, night elven hero of the War of the Ancients. Some of my own ancient ancestors are interred in its cemetery. Meet me there and make sure that you are not followed. SI:7 is very good at what they do. We have to be better.", ["objectivesText"] = "Meet up with Valeera Sanguinar at Ravencourt in Val'sharah.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43251] = { ["id"] = 43251, ["name"] = "In Search of the Eye", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42678, 42680, 43252 }, ["description"] = "The Raven's Eye should be somewhere within the courtyard. This is where Ravencrest's lieutenants used to plan their strategies in life. Hell, it looks like they still might be doing so in death. It has to be around here somewhere. Your skill at lock picking should prove invaluable.", ["objectivesText"] = "Pick the locks of the Ancient Chests to find the Raven's Eye. Progress: Have you found the Raven's Eye yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139290, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43252] = { ["id"] = 43252, ["name"] = "Eternal Unrest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42678, 42680, 43251 }, ["description"] = "My ancient ancestors are buried here in the cemetery to the west. Because of whatever is causing the dead to rise, their souls are now at unrest. All blood elves are descended from high elves, who in turn came from these lands before they were sundered. I cannot bring myself to do it. Will you put my ancestors to rest?", ["objectivesText"] = "Put Cesta Stargazer , Mandrel Nightsbane , and T'rel Moonblade to rest.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 110164, ["x"] = 0.404, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43253] = { ["id"] = 43253, ["name"] = "Maw of Souls: Ancient Vrykul Legends", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42678, 42680, 42800, 43249, 43250, 43251, 43252, 43253 }, ["series"] = { 42684, 43249, 43250, 43468 }, ["description"] = "Our diversionary tactics in Stormheim uncovered intel on something I thought only a myth. There is a legend about a magical jewel the vrykul created long before the time of man. The jewel was said to be able to... <Valeera stops herself from continuing while looking around and eyeing you wryly.> I do not want to talk about it just yet. Not until we have proof. Unfortunately, the only way we are going to get that proof is in the Maw of Souls on the Naglfar... the ship of the dead.", ["objectivesText"] = "Gather a group and take an etching of the Raven's Eye Tablet on the ship of the dead, The Naglfar, in the Maw of Souls. Progress: Did you find proof?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139302, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5854, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5854, ["name"] = "Saga of the Shadowblade II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43254] = { ["id"] = 43254, ["name"] = "Ritual Ruination", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 43100, 43153, 43254 }, ["description"] = "Time for main event, friend! Gul'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan. Take this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out! Calydus will help when he can! Good luck, friend!", ["objectivesText"] = "Take the Fel Bat to the Tomb of Sargeras and steal the Scepter of Sargeras.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 224, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4788 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 224, ["name"] = "Scepter of Sargeras", ["orderIndex"] = 2, ["flags"] = 0 } } },
