[43273] = { ["id"] = 43273, ["name"] = "Spread the Word", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 43270, 43275 }, ["description"] = "In the center of the dais is a map of the Broken Isles. From it, you can direct our allies to carry out vital assignments across the world. The first task is critical to the growth of our order - identifying skilled priests whom we can trust to train our order's troops. This is a task we can easily entrust to one of our new champions.", ["objectivesText"] = "Use the Command Map and complete the mission, \"Spread the Word\". Progress: How is the mission proceeding?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 63667, 63668, 63669, 63670, 63671, 63672, 63673, 63674, 63675, 63676, 63677, 63678, 237812, 239440 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43275] = { ["id"] = 43275, ["name"] = "Recruiting the Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 43270, 43273 }, ["description"] = "Our recruiting efforts have paid off. Grand Anchorite Gesslar has pledged his service to our order. He has an eye for greatness, and can easily spot a recruit with potential. He takes those selected under his wing, and shapes them into worthy allies. Speak to him now and train a troop of acolytes.", ["objectivesText"] = "Speak to Grand Anchorite Gesslar and train a troop of acolytes. Progress: How did the training go?", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 9, ["flags"] = 0 } } },
