[43277] = { ["id"] = 43277, ["name"] = "Tech It Up A Notch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["series"] = { 43276 }, ["description"] = "We are very fortunate to have come across Archon Torias. His knowledge will be invaluable as we improve our defenders and fortify Netherlight Temple.", ["objectivesText"] = "Speak to Archon Torias in Netherlight Temple. Progress: Have you had a chance to speak with Archon Torias yet?", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 11, ["flags"] = 0 } } },
