[43309] = { ["id"] = 43309, ["name"] = "The Perfect Opportunity", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "I have heard whispers from Suramar City. Recent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested. This is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause! I know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray. Seek her out at the Waning Crescent and ensure her victory.", ["objectivesText"] = "Meet Ly'leth Lunastre at the Waning Crescent. Progress: Thalyssra asks much of me.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43310] = { ["id"] = 43310, ["name"] = "Either With Us", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Thalyssra asks much of me, but our cause is worth the risks. The title of advisor would grant us enormous influence. Information. Access. I could change this rebellion. I could save so many lives. I will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant. Lady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. Earn her trust and the rest will follow.", ["objectivesText"] = "Speak to Lady Aurore .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 211279, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43311] = { ["id"] = 43311, ["name"] = "Or Against Us", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "If Ly'leth is to achieve the role of advisor to the Grand Magistrix we will need to open a path for her. It is true she will have some supporters but they alone cannot grant her the title. There are other houses that Ly'leth must contend with. Fear and coercion are their tools. None dare stand against them openly, and we cannot win them over with favors and oaths. Seek out Arluin . I trust he will have some ideas of how to proceed.", ["objectivesText"] = "Speak to Arluin . Progress: Yes, I know why you are here. Yes, I can get the jobe done. No, it will not be free.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29333, 29334, 29335, 29336, 52593, 52617, 52640, 52644, 52673, 62210, 62211, 62212, 62213, 131283, 131655, 139786, 140255, 140409, 140421, 140422, 141680, 141955, 142054, 211279, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43312] = { ["id"] = 43312, ["name"] = "Thinly Veiled Threats", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "How could I let this happen? < Aurore wrings her hands.> Yesterday Coryn Stelleris approached me about the appointment. He sought my support, but I did not offer it. He said my son's life would continue as normal... if I gave him my vote. This morning my son was gone. I can only think of the terrible things he may be suffering. You know what this family is capable of! You want my support, but I can do nothing while my son is in danger. Nothing. Please... save him!", ["objectivesText"] = "Rescue Ailen Astravar . Progress: Did you find my son?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43313] = { ["id"] = 43313, ["name"] = "Rumor Has It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Coryn Stelleris and Ruven Duskmere were close friends, but one always overshadowed the other. Now the Stelleris family stands to gain from lord Ruven's death. Handsomely. House Duskmere will soon learn of their loss. I want you to be the one to redirect their anger and grief. A handful of well placed rumors should do the trick. I won't be lingering in this part of the city for long, and Ly'leth will want to know of your efforts. Return to her when you are finished.", ["objectivesText"] = "Plant rumors among members of House Duskmere.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 123956, 130899, 131746, 137178, 137401, 140255, 140409, 140421, 140422, 141605, 141680, 141955, 179384, 200738, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43315] = { ["id"] = 43315, ["name"] = "Death Becomes Him", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "There are two houses that pose a threat to Ly'leth's rise, but we concern ourselves with only one of them now. House Duskmere commands respect through fear and that fear is not unfounded. Few can boast of magical talent equal to that of Ruven Duskmere. Without this charming specimen, however, their house is nothing. I know you may find my methods distasteful. Know that there were demons in Suramar long before the Legion. This one has lived long enough.", ["objectivesText"] = "Slay Ruven Duskmere. Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 17125, 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43317] = { ["id"] = 43317, ["name"] = "In the Bag", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Already the city is abuzz with outrage. I will not lie to you- it pleases me greatly that one such as Coryn is made a fool. The other houses have sent their endorsements. It is done, and nothing remains but a formal ceremony to grant me the title of advisor. Meet me there. You deserve to share in this success.", ["objectivesText"] = "Witness Ly'leth Lunastre 's ascension to advisor. Progress: I am prepared. It is nearly time.", ["rewardGold"] = 24100, ["rewardXP"] = 770, ["rewardItems"] = { 5083, 57540, 140255, 140409, 140421, 140422, 141680, 141955, 181176, 181177, 181180, 181182, 181189, 181197, 181198, 181204, 181217, 181218, 181224, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 185854, 185942, 186201, 204195, 237354, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43318] = { ["id"] = 43318, ["name"] = "Ly'leth's Champion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "Tal'ashar is an honor duel. If I lose, then I must forfeit my title to Coryn Stelleris. <Ly'leth smiles gently.> That is why you are going to fight for me. I will grant you a more powerful disguise for this task, and together we will put Coryn in his place. Speak to me when you are ready to battle on my behalf.", ["objectivesText"] = "Speak with Ly'leth to begin the encounter. Progress: I know you will defend my honor, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812, 246937, 247911 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43319] = { ["id"] = 43319, ["name"] = "The Way of the Tiger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 41728, 41729, 41730, 41731, 41732, 41733, 41734, 41735, 41905, 43319 }, ["description"] = "Among the allies who joined us from Tian Monastery is Gin Lai , a monk famed for his experience in the ways of the tiger. With his help, we will be able to train Tiger Initiates, who strike swiftly and precisely on the field of battle. Go speak with him now and request his services.", ["objectivesText"] = "Speak to Recruiter Gin Lai .", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5878, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5878, ["name"] = "Journey of the Grandmaster I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43334] = { ["id"] = 43334, ["name"] = "The Coming Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 379, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "You saved us all, my friend! Truly you embody all the elements stand for. If the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power. They were placed in the care of the White Tiger, who will give them only to one who is worthy. Come <name>! Travel with me to Pandaria and we will prove your worth!", ["objectivesText"] = "Travel to Pandaria and speak to the White Tiger at his temple.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 60968, ["x"] = 0.687, ["y"] = 0.47075 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.47075 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43335] = { ["id"] = 43335, ["name"] = "Survival Skills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 }, ["series"] = { 42390, 42392 }, ["description"] = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct. Show me you have the basic survival skills to live off the land.", ["objectivesText"] = "Show your survival skill by building a campfire from chopped wood , and cooking a steak over an open flame. Progress: You need to eat to survive in the wild. Boar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however. There are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often tell which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat. The best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124119, 137609, 137612, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 107425, ["x"] = 0.366, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5848, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5848, ["name"] = "Watchers in the Wild I", ["orderIndex"] = 10, ["flags"] = 0 } } },
[43338] = { ["id"] = 43338, ["name"] = "The Codex of Ra", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 39771, 43334, 43338 }, ["description"] = "The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as \"Ra-den\" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone , The Edict of Fire , and the Edict of the Storm . These pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.", ["objectivesText"] = "Enter the Guo Lai Halls in the Vale of Eternal Blossoms and collect the Edict of Stone , the Edict of Fire , and the Edict of the Storm . Cleanse the area by slaying mogu spirits. Progress: I've been asking around. The pandaren locals are terrified of this place. It's been haunted since the end of Hellscream's Pandaren Campaign. Did you find an offering for the White Tiger?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139432, 139433, 139434, 139506, 139698, 139701, 139705, 139879, 140517, 140929, 140932, 187028, 232877, 233014, 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 60968, ["x"] = 0.687, ["y"] = 0.47075 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.47075 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 266, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 395, ["questLines"] = { { ["id"] = 266, ["name"] = "The Voice of Thunder", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43341] = { ["id"] = 43341, ["name"] = "Uniting the Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43341, 45727 }, ["description"] = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", ["objectivesText"] = "Earn at least Friendly reputation with the factions of the Broken Isles. Progress: Any luck uniting the factions?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 139390, 141605, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 275, ["name"] = "7.0 World Quests", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43352] = { ["id"] = 43352, ["name"] = "Asset Security", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "With the demons and guards so agitated, I'm running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now. Head to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge. I will make sure there is something in it for you when you are done.", ["objectivesText"] = "Defend Arluin 's stash from the city guards. Progress: Did you deter them yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.724 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 14, ["flags"] = 0 } } },
[43359] = { ["id"] = 43359, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["storyline"] = { 43359 }, ["description"] = "Grand Master, you have saved our order from the brink of destruction. Your deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential. Please, stand before the Forge of the Roaring Mountain and raise your weapon high.", ["objectivesText"] = "Approach the indicated location before the Forge of the Roaring Mountain and raise your weapon. Progress: We honor you, Grandmaster.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard" },
[43360] = { ["id"] = 43360, ["name"] = "The Shardmaidens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 684, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "Long have I walked this land and I have seen many forms of corruption. The creatures that wander this hall are twisted by the magics unleashed by the failed arcan'dor. These dryads have lost their way, and cannot be saved. You must destroy them. End their suffering.", ["objectivesText"] = "Slay 6 Shardmaidens in the Shattered Locus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140255, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43365] = { ["id"] = 43365, ["name"] = "The Cycle Continues", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Yay! The grove is regenerating nicely. Our flower friends thank you for helping them. We were able to save most of the grove, but sadly, many living souls were lost as well. Brightwing is so sad! But you can help! Take this bag of Dream Seeds . Plant them onto fresh corpses, and in time, new flowers will grow! Death is beautiful, and from death comes rebirth. This is the cycle that must continue!", ["objectivesText"] = "Plant 100 Dream Seeds on corpses.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 46874, 139380, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 16, ["flags"] = 1 } } },
[43368] = { ["id"] = 43368, ["name"] = "Champion: Brightwing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 715, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1540, ["db2PoiUiMapID"] = 715, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 18, ["flags"] = 1 } } },
[43371] = { ["id"] = 43371, ["name"] = "Relieving the Front Lines", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Many within our order have been on the front lines of battle for too long, aiding those who are attempting to thwart the Legion's invasion. It is time we send in some relief, allowing our allies some much needed rest.", ["objectivesText"] = "Interact with the Command Map and complete the mission, \"Relieving the Front Lines\".", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43372] = { ["id"] = 43372, ["name"] = "Whispers in the Void", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Our priests are resting and recuperating, but one not as well as the others. Gilner Greymoss lingers within the Sanctuary of the Void, laughing to himself. He refuses to leave, but his presence is making the other priests uneasy. Perhaps you should speak to him and see what is wrong?", ["objectivesText"] = "Speak to Gilner Greymoss in the Sanctuary of the Void. Progress: Some wounds are too deep to heal.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43373] = { ["id"] = 43373, ["name"] = "The Best and Brightest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "If we wish to see the truth in Gilner's ramblings, I will need to induce a vision. It is not the sort of thing that is typically forced, but we have within our ranks the best and brightest alchemists who can craft an extract that will grant me the sight I need. Seek them out in Azsuna where they are currently aiding those on the front lines.", ["objectivesText"] = "Find Zabra Hexx in Azsuna.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43374] = { ["id"] = 43374, ["name"] = "Murloc Mind Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Yalia and I were deliverin' antidotes to da front lines a Faronaar when we were attacked by a herd a murlocs. We dropped our supplies and made a run for it, but Yalia never made it out a da camp. Obviously I didn't fair much better, ma bones still ache from bein' turned to stone. It's possible Yalia's still alive and bein' held captive. Please, ya have to find her!", ["objectivesText"] = "Rescue Yalia Sagewhisper from the murlocs within El'dranil Shallows.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 112487, ["x"] = 0.585, ["y"] = 0.371 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43375] = { ["id"] = 43375, ["name"] = "An Ample Supply", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Durin' our attempt to flee da murlocs, Yalia and I dropped da supplies we planned to deliver to da demon hunters in Faronaar. Inside each a those crates were vials a salve dat took us countless days and resources to craft. If we don' get those supplies back, I fear our allies on da front lines will suffer.", ["objectivesText"] = "Recover Felbat Toxin Salve from supply crates scattered around El'dranil Shallows. Progress: Do ya have our supplies?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128825, 128827, 128868, 139458, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110686, ["x"] = 0.546667, ["y"] = 0.394667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.394667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43376] = { ["id"] = 43376, ["name"] = "Problem Salver", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "Forcing a vision isn't easy by any means. Finding the ingredients for the elixir alone will take a considerable amount of time, time we don't have. Too many are suffering on the front lines as we speak, in need of the salve we were meant to deliver. I suppose if we all work together, we can make this work. Zabra and I will find the items needed for Velen's elixir, if you take the salve to Faronaar and cure the demon hunters . Does that sound fair?", ["objectivesText"] = "Use the salve on diseased demon hunters at Faronaar Front in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 139463, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 112487, ["x"] = 0.585, ["y"] = 0.371 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110687, ["x"] = 0.493333, ["y"] = 0.387333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.371 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43377] = { ["id"] = 43377, ["name"] = "Halls of Valor: The Light Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "We cannot ignore the Prophet's vision, <name>. To do so would mean that everything we know and hold dear will be lost to the Legion. We must focus on what we know, and that is that the Light must walk among us. Within the Halls of Valor you will find an ascending val'kyr by the name of Hyrja. Recover a spark of her Light and release it within our temple.", ["objectivesText"] = "Recover a Spark of Light from Hyrja within the Halls of Valor dungeon.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 139485, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43378] = { ["id"] = 43378, ["name"] = "Eye of Azshara: Looking Through the Lens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 630, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "We have what we need to create Velen's elixir, but in order for others to be able to witness his vision, we'll need to find something that can be used to project images from the mind. A lens from the nearby naga should work well, but I don't think they're going to be too eager to give it up.", ["objectivesText"] = "Recover the Lens of the Tide from Lady Hatecoil within the Eye of Azshara dungeon. Progress: Gazing through the lens of a powerful naga will allow you to witness my vision.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 128825, 128827, 128868, 139464, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110687, ["x"] = 0.493333, ["y"] = 0.387333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.387333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7834 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43379] = { ["id"] = 43379, ["name"] = "Velen's Vision", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 42137, 42138, 43371, 43372, 43373, 43374, 43375, 43376, 43378, 43379 }, ["description"] = "I have everything I need to bring forth a vision, but the question remains: are you ready to witness it? Even the smallest glimpse into the future can weigh heavy on your soul. Once I ingest the elixir, the vision will come quickly. Gazing into the Lens of the Tides will allow you to see what I see. Let me know when you are ready to begin.", ["objectivesText"] = "Use the Lens of the Tides to witness Prophet Velen 's vision. Progress: Even the smallest glimpse into the future can leave a heavy weight on your mind.", ["rewardGold"] = 606600, ["rewardXP"] = 2125, ["rewardItems"] = { 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5858, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5858, ["name"] = "Fulfilling the Prophecy I", ["orderIndex"] = 9, ["flags"] = 0 } } },
