[43382] = { ["id"] = 43382, ["name"] = "Champion: Natalie Seline", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 14, ["flags"] = 0 } } },
[43383] = { ["id"] = 43383, ["name"] = "Awakening the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "This spark will only know its full potential once it's been filled with pure Light, gleaned from the holiest places in our world. Nurture this spark, and it may grow to walk among you.", ["objectivesText"] = "Collect Pure Holy Light by completing Class Hall missions. Progress: <Saa'ra's soothing voice fills your mind.> Nurture the spark with holy Light if you wish it to awaken and walk among you.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 139368, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43384] = { ["id"] = 43384, ["name"] = "Demonic Runes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "I cannot stand by idly and allow the Legion to destroy our home. I've been studying their language for some time, deciphering any runes I can get my hands on, but my supply is severely limited. If I had more runes to study, it's possible that I may discover something that will help us in locating Balnazzar.", ["objectivesText"] = "Collect Demonic Runestones from demons throughout the Broken Isles. Progress: Were you able to recover the runestones?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 128825, 128827, 128868, 138817, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43385] = { ["id"] = 43385, ["name"] = "Infiltrating Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "With the Light at our side, we should focus our efforts on figuring out who among our enemies could be a potential ally. Any of your champions should be capable of infiltrating enemy ranks, giving us a better understanding of how to approach this. Even so, it is a delicate task. Proceed with caution.", ["objectivesText"] = "Interact with the Command Map and complete the mission, \"Infiltrating Our Enemies\".", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43386] = { ["id"] = 43386, ["name"] = "Onslaught Envoy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "A few defectors have been discovered among the Scarlet Onslaught in Northrend. I know it's difficult to think that any within their ranks could be useful to our cause, but we must make an attempt. The prophecy says an old enemy will become an ally, so it's worth it to investigate and see if these defectors can be brought to the Light.", ["objectivesText"] = "Find a new ally among old enemies in New Hearthglen.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43387] = { ["id"] = 43387, ["name"] = "Scarlet Redemption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The Light shines upon me, <name>! For the first time in my life, I feel it! I was without hope, ready to die for the things I had done in the name of the Scarlet Crusade, but then you appeared! You are my chance at redemption. Please, let me prove to you that I am worthy of a second chance. Let me slay those I used to be loyal to!", ["objectivesText"] = "Help Mariella the Heretic redeem herself by killing members of the Scarlet Onslaught in New Hearthglen. Progress: I will prove myself worthy of being redeemed.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43388] = { ["id"] = 43388, ["name"] = "Apostate Liberation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "There are others like me, you know. Others that have removed the veil that the Scarlet Crusade has kept over our eyes for so long. They've been placed in cages, treated like animals, simply because their beliefs no longer line up with what the Onslaught deems is right and holy. They wish to redeem themselves. We should try to free them, if you think their lives are worth saving.", ["objectivesText"] = "Rescue Onslaught Apostates within New Hearthglen. Progress: All we want is a chance to redeem ourselves.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 110683, ["x"] = 0.714, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43389] = { ["id"] = 43389, ["name"] = "Unexpected Guests", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "You helped me escape my fate by freeing me from the gallows, but allowing me to fight the Scarlet Onslaught by your side has truly freed my heart and mind from the guilt I have felt for so long. I want to be a part of something greater than myself, a noble cause that won't distort the meaning of the Light. Let me travel to your temple and beg forgiveness of the Prophet. I may not be a welcome guest, but it's a journey I must make to complete my redemption.", ["objectivesText"] = "Return to Alonsus Faol in Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[43390] = { ["id"] = 43390, ["name"] = "Forgotten Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The Light walks among us, as does one of our enemies. You have done well to bring the prophecy to life, but it is not yet complete. The shadows must rise, and to do so, the Cult of Forgotten Shadows must be restored. You will find the few remaining followers at the cemetery in Duskwood. They linger there near the grave of their fallen leader.", ["objectivesText"] = "Head to Duskwood and meet with a member of the Cult of Forgotten Shadows.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 11, ["flags"] = 0 } } },
[43391] = { ["id"] = 43391, ["name"] = "Secrets of the Void", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "Our leader was murdered for her beliefs, or so most would believe. Natalie Seline knew her fate, and took steps to protect herself from an inevitable death. The night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself. She penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place. Without her journal, we will never be able to recover her spirit.", ["objectivesText"] = "Recover Natalie's Journal from Twilight Lord Urgrok. Progress: We watch over Natalie's body, forever hopeful that her spirit will return.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 139772, 140517, 140930, 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43392] = { ["id"] = 43392, ["name"] = "Into the Void", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "This is without a doubt Natalie's writing. The entry was scrawled in haste, but the message is clear: The spell within this journal will lead us to Natalie's spirit, but it needs to be incanted at a shadow altar within the catacombs. Odessa and I have a duty to watch over Natalie's body, but with your considerable power, you should be able to perform the spell with ease.", ["objectivesText"] = "Read Natalie's Journal at the catacomb's shadow altar to enter the void and recover her spirit.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 111041, ["x"] = 0.242, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[43393] = { ["id"] = 43393, ["name"] = "Rising Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 47, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "News of my return will spread fast among those who share my beliefs. Soon Azeroth will see the rise of Shadows, but I imagine this is not news to you. Whatever your plan may be, I hope it continues to see the Cult of Forgotten Shadows as allies.", ["objectivesText"] = "Return to Alonsus Faol at Netherlight Temple.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 110684, ["x"] = 0.242, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 15, ["flags"] = 0 } } },
[43394] = { ["id"] = 43394, ["name"] = "Crossing Legion Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 748, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "I've received word from the Highlord that a group of paladins and priests were captured after a battle broke out at Felblaze Ingress. Your priestess, Delas Moonfang, was among those captured. They've been taken through the demon portal and into the Legion stronghold of Niskara. We will need the assistance of the Conclave if we have any hope of recovering them.", ["objectivesText"] = "Use the demon portal at Felblaze Ingress to enter Niskara and find Aponi Brightmane . Progress: I've never been so happy to see you, <class>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 16, ["flags"] = 0 } } },
[43395] = { ["id"] = 43395, ["name"] = "Allies of the Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies. We cannot leave them, <name>.", ["objectivesText"] = "Looking for Paladin quest? See Allies of the Light . Save Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 17, ["flags"] = 0 } } },
[43396] = { ["id"] = 43396, ["name"] = "The Mind of the Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly. Let us find whatever information we can about their plans.", ["objectivesText"] = "Find the Legion Intelligence, Star Map, and Image of Velen, then slay Brood Queen Aramis .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 18, ["flags"] = 0 } } },
[43397] = { ["id"] = 43397, ["name"] = "United As One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 24, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "You and Delas have had dealings with the paladins before, maybe it's possible they will grant you an audience with their war council. Head to the Sanctum of Light and ask the paladins to help us defend Netherlight Temple from Balnazzar's attack.", ["objectivesText"] = "Make your way to the Sanctum of Light to speak with Lady Liadrin , and hear the council of war. Progress: Now is not the time for interruptions, <name>. The council needs to determine its course of action.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 128825, 128827, 128868, 136928, 139506, 139697, 139757, 139759, 140517, 140930, 150745, 150746, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 19, ["flags"] = 0 } } },
[43398] = { ["id"] = 43398, ["name"] = "Champion: Alonsus Faol", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43399] = { ["id"] = 43399, ["name"] = "Fortifying the Temple", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "We've all worked so hard turning this temple into something all priests can be proud of, it would be a shame to see it fall to the Burning Legion. We must strengthen our defenses in preparation for the attack. With the right resources, we can make the temple a nearly impenetrable fortress.", ["objectivesText"] = "Complete 10 World Quests. Progress: We will need to gather many resources in order to properly fortify the temple.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124105, 124111, 124120, 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43400] = { ["id"] = 43400, ["name"] = "Lumenstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "To prepare for the battle, we will need the best armor and weapons we can get. Lumenstone is an enchanted material that can withstand great amounts of fel magic. It is found in rare quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting. We should send our champions to target enemies around the Broken Isles - there should be plenty of Lumenstone to be found in their stockpiles.", ["objectivesText"] = "Collect 50 Lumenstone by sending champions on \" Lumenstone \" missions. Progress: Have you acquired any lumenstone ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140191, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43401] = { ["id"] = 43401, ["name"] = "A Light in the Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "The Burning Legion has begun their attack! I will remain here and prepare the temple's defenses. You must meet our allies in Dalaran and let them know that the battle has begun! Make haste, <name>. I do not know how long we will be able to keep Balnazzar at bay.", ["objectivesText"] = "United with the paladins, defend Netherlight Temple and slay Lord Balnazzar . Progress: The paladins have always been our allies and friends. Now, we stand united against a common cause.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 128825, 128827, 128868, 139448, 139450, 139506, 139757, 139759, 140517, 140930, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43402] = { ["id"] = 43402, ["name"] = "High Priest of Netherlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "You have fulfilled the prophecy, but more than that, you have united the priests of Azeroth. We should take a moment to recognize all that you have accomplished.", ["objectivesText"] = "Listen as you are honored by the Conclave of priests. Progress: We rejoice in your triumph!", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139759, 142055, 142057, 142062, 142063, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43403] = { ["id"] = 43403, ["name"] = "Defending the Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42049, 42050, 42051, 42053, 42054, 42055, 42056, 42365, 42432, 43403, 91614 }, ["description"] = "As druids, our charge is to defend nature... and in turn, our home, Azeroth. Conflict breaks out all across the Broken Isles. The Burning Legion pushes forward, and numerous allies call out for our aid. We must focus our efforts on defense, before we can mount an offense against the Nightmare. Help our allies across the Broken Isles, then return to me when the situation is under control.", ["objectivesText"] = "Complete 10 World Quests. Progress: Conflict rages across the Broken Isles.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5885, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5885, ["name"] = "The Eternal Dream III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43407] = { ["id"] = 43407, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["storyline"] = { 43407 }, ["description"] = "I'm pleased to report that the improvements to the Soul Forge are complete! When you are ready, we shall use it to unlock the true potential of your weapon!", ["objectivesText"] = "Approach the indicated location before the Soul Forge and raise your weapon. Progress: Suffer well, Deathlord.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[43409] = { ["id"] = 43409, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["storyline"] = { 43409 }, ["description"] = "<class>t, in our short time together you have done much to aid the Circle. We are inspired by your determination and have developed a new technique that will bind the power of your weapon with the Emerald Dream itself! Everything is prepared. When you are ready we shall begin.", ["objectivesText"] = "Approach the indicated location before the Seed of Ages and raise your weapon. Progress: We honor you, Archdruid.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard" },
[43412] = { ["id"] = 43412, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["storyline"] = { 43412 }, ["series"] = { 44214 }, ["description"] = "I'm pleased to report that the improvements to the Forge are complete! When you are ready, we shall use it to unlock the true potential of your weapon!", ["objectivesText"] = "Approach the indicated location before the Cursed Forge of the Nathrezim and raise your weapon. Progress: We honor you, Slayer.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 124125, 127829, 127830, 128832, 138111, 139506, 139715, 139718, 139722, 140378, 140517, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard" },
[43414] = { ["id"] = 43414, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["storyline"] = { 43414 }, ["description"] = "<class>t, our research into the Felblood Altar has proven useful. We've developed a ritual that should unleash the full powers of your artifact weapon! Say the word, and we shall begin the ritual at once!", ["objectivesText"] = "Approach the indicated location before the Felblood Altar and raise your weapon. Progress: We honor you, Netherlord.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 128941, 128942, 128943, 139506, 139765, 139767, 139770, 140517, 140922, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard" },
[43415] = { ["id"] = 43415, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 43415 }, ["description"] = "<class>t, in our short time together you have done much for our order. Through your words and deeds we've been inspired to redouble our efforts and I'm proud to report that we've discovered a new technique that may be of use to you. If you have a moment, <class>t, I would be pleased to show you the fruit of our research.", ["objectivesText"] = "Approach the indicated location before the Forge of the Guardian and raise your weapon. Progress: We honor you, Archmage.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard" },
[43418] = { ["id"] = 43418, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["storyline"] = { 43418 }, ["description"] = "Farseer, since you have joined us you have done much to aid the Earthen Ring. Your efforts have not gone unnoticed. The spirits have watched all that you have done and are pleased. They also have shown me a technique that will unleash the true power of your weapon! The ritual is ready. When you are prepared we can begin.", ["objectivesText"] = "Approach the indicated location before the Ancient Elemental Altar and raise your weapon. Progress: We honor you, Farseer.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard" },
[43420] = { ["id"] = 43420, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["storyline"] = { 43420 }, ["description"] = "<class>t, in our short time together you have done much to aid the Conclave. Now, with the work upon the Altar of Light and Shadow complete, it is time that we aid you. We have discovered a method to awaken the full power of your weapon! Please, step before the altar and raise your weapon high.", ["objectivesText"] = "Approach the indicated location before the Altar of Light and Shadow and raise your weapon. Progress: All hail the, High <class>!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard" },
[43422] = { ["id"] = 43422, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43422 }, ["series"] = { 44215 }, ["description"] = "I'm pleased to say that the improvements to the crucible are complete! When you are prepared, we shall use it to unlock the true potential of your weapons!", ["objectivesText"] = "Approach the indicated location before the Crucible of the Uncrowned and raise your weapon. Progress: Well done, Shadowblade.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43423] = { ["id"] = 43423, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 43423 }, ["description"] = "I'm pleased to say that the improvements to the Altar of the Eternal Hunt are complete! When you are ready, we shall use it to unlock the full potential of your weapon!", ["objectivesText"] = "Approach the indicated location before the Altar of the Eternal Hunt and raise your weapon. Progress: Well done, Huntmaster.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110505, ["x"] = 0.4768, ["y"] = 0.4944 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 110505, ["x"] = 0.4768, ["y"] = 0.4944 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4768, ["y"] = 0.4944 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[43424] = { ["id"] = 43424, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43424 }, ["description"] = "<class>t, you've brought together the Silver Hand like no <class>t has done before. You've shown us that with determination and faith in the holy light we can overcome any challenge. Following in your example our workmen have toiled hard to improve the Altar of Ancient Kings, allowing it to unlock the true potential of your weapon. Their work is now complete! Step forward when you are ready and we shall begin.", ["objectivesText"] = "Approach the indicated location before the Altar of Ancient Kings and raise your weapon. Progress: Well done, Highlord.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard" },
[43425] = { ["id"] = 43425, ["name"] = "A Hero's Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "I've been watching you, <name>. Time and again you've led the Valarjar to war with your weapon held high! Time and again the halls of Valhalas have thundered with the cheers of your victory! Now that the enhancements to the forge have been completed, it is time that your weapon's true potential be unleashed! Meet with me at the forge, hero.", ["objectivesText"] = "Meet with Odyn at his forge and raise your weapon at the indicated location. Progress: I honor you, Battlelord.", ["rewardGold"] = 101100, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43441] = { ["id"] = 43441, ["name"] = "A Second Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 43441, 44310 }, ["description"] = "We have strong leads on other ancient weapons that you might choose to pursue, if having one renowned, powerful piece of history in your hands is somehow insufficient. I'll lay out the options for you. Let me know how you'd like to proceed.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5835, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5835, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43462] = { ["id"] = 43462, ["name"] = "Mother Ozram", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 42851, 42852, 42866, 42867, 42885, 42886, 42887, 42888, 42890, 42919, 42966, 42967, 42968, 43462, 44004, 44153, 44257 }, ["series"] = { 42886, 42887, 42888, 42890 }, ["description"] = "The fiendish imps in this region are an incessant pain on our allies defending the camps below. They are the spawn of a wicked imp-mother named Mother Ozram , who has been seen on a hill to the south. Destroy her, and we will end her brood as well.", ["objectivesText"] = "Kill Mother Ozram . Progress: Do not be deceived by the imp-mothers. They are devious and strong.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 109384, ["x"] = 0.306, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 13, ["flags"] = 0 } } },
[43468] = { ["id"] = 43468, ["name"] = "Blood for the Wolfe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 42684, 43249, 43250, 43253 }, ["description"] = "We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask. I am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some. We should show him the same professional courtesy.", ["objectivesText"] = "Collect 50 Fel Blood . Progress: The clock is ticking, <name>. Do you have the blood?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 137677, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43469] = { ["id"] = 43469, ["name"] = "Where In the World is Mathias?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43470, 43479, 43485 }, ["description"] = "Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord. Or rather, a very clever dreadlord has taken his place while he is being held captive somewhere. It is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.", ["objectivesText"] = "Use the Scouting Map and complete the \"Where In the World is Mathias Shaw?\" missions.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43470] = { ["id"] = 43470, ["name"] = "Pruning the Garden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43479, 43485 }, ["description"] = "In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole. On the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn't you agree, <name>?", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43479] = { ["id"] = 43479, ["name"] = "The World is Not Enough", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43470, 43485 }, ["description"] = "Now that we have pruned the garden, it is time to dig up the rotting tree stump in the middle. Put another way, we need to make sure to keep the forces of chaos from overwhelming the Broken Isles. Certainly others are helping in this endeavor. However, I am sure the target you select to eliminate will be the wisest from the standpoint of the Uncrowned.", ["objectivesText"] = "Complete any 1 \"Rare Elite\" World Quest designated by a diamond surrounded by a gold dragon on the area maps. Progress: And have you dug up that tree stump yet, <name>?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43485] = { ["id"] = 43485, ["name"] = "A Burning Distraction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 43469, 43470, 43479 }, ["description"] = "We're going to need a distraction if we are to rescue Mathias Shaw from where he's being held captive in Felsoul Hold. A big one. Explosives placed in a few key locations should do nicely. Noggenfogger is playing nice and has donated some bombs to the cause. He might be trying to smooth over relations due to his earlier extortion. I can have someone go ahead and mark the best locations. You want to do the honors?", ["objectivesText"] = "Place the Noggenfogger Boom Bombs on your way through Felsoul Hold and then trigger the Detonator to set them off. Progress: As soon as you set all of the explosives and push the button, we will proceed.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110714, ["x"] = 0.298, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43486] = { ["id"] = 43486, ["name"] = "Cracking the Codex", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43487, 49812 }, ["description"] = "I have been studying the Codex of Command that you recovered from Faronaar. It is important to Balnazzar, but WHY? What does it say? I'm sure we could gain valuable knowledge if we could just crack this code. I have a friend who might be able to help us: a priestess named Delas Moonfang . She has been studying Eredun, the language of the demons. Take the sigil to her in Dalaran. Tell her I sent you.", ["objectivesText"] = "Speak to Delas Moonfang in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43487] = { ["id"] = 43487, ["name"] = "Assault on Violet Hold: The Fel Lexicon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43486, 49812 }, ["description"] = "I have been studying the language of the demons, but it has been difficult to get my hands on written material. I have heard rumor of a book called the Fel Lexicon , written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much! I heard that this book might be in the hands of a powerful prisoner inside the Violet Hold. Bring me this book, and my work here will go much faster.", ["objectivesText"] = "Collect a Fel Lexicon from a powerful prisoner inside Violet Hold. Progress: I am fairly adept in twelve different languages, and I hope to add more to the list.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 120978, 128823, 128866, 139445, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43488] = { ["id"] = 43488, ["name"] = "Blood of Our Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "I have seen demonic artifacts before, <name>. Legion sigils will only reveal themselves in the presence of demon blood. I sense that time is of the essence. Bring me a large quantity of demon blood, so that I may translate the book as soon as you retrieve it.", ["objectivesText"] = "Send your champions on \"Blood of Our Enemy\" missions against the Burning Legion and collect 5 Flasks of Demon Blood . Progress: The last time, I tried to use a living demon. It ended rather poorly... for the demon.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 139465, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43489] = { ["id"] = 43489, ["name"] = "To Felblaze Ingress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 630, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43493 }, ["description"] = "I have sobering news, Highlord. We have had no word from Chieftain Aponi Brightmane, young Arator, or priestess Delas Moonfang since they departed for Felblaze Ingress. We need to know what happened to them. We fear the worst.", ["objectivesText"] = "Find Aponi Brightmane at Felblaze Ingress in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43490] = { ["id"] = 43490, ["name"] = "Aponi's Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 748, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "<The book is missing several pages. Nearby, you can see signs of a struggle.> <If you can seek the missing pages on the nearby demons, perhaps you could learn what fate befell your allies.>", ["objectivesText"] = "Find 8 pages of Aponi's journal, then use them to track her down. Progress: I've never been so happy to see you, Highlord.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139540, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1604, ["db2PoiUiMapID"] = 748, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43491] = { ["id"] = 43491, ["name"] = "Allies of the Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies. We cannot leave them, <name>.", ["objectivesText"] = "Looking for Priest quest? See Allies of the Light . Save 5 Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43492] = { ["id"] = 43492, ["name"] = "Champion: Aponi Brightmane", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 11, ["flags"] = 0 } } },
[43493] = { ["id"] = 43493, ["name"] = "Black Rook Hold: Lord Ravencrest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43489 }, ["description"] = "Highlord, news has reached us of a Legion presence at Black Rook Hold. It is rumored that the night elf commander, Kur'talos Ravencrest, amasses an enormous army behind the fortress walls. Take a group of your most powerful allies, Highlord, and investigate these stories. Lord Ravencrest was a formidable general during Azshara's reign, and if the reports are true, then we must know more.", ["objectivesText"] = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold. Progress: It is vital that we stay on top of the Legion's movements. At any moment, they could attack.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43494] = { ["id"] = 43494, ["name"] = "Silver Hand Knights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43494 }, ["description"] = "Good news, Highlord! We have recruited a paladin trainer named Commander Born . He is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services. Go speak to him, and train a squad of Silver Hand Knights.", ["objectivesText"] = "Speak to Commander Born .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard" },
[43496] = { ["id"] = 43496, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 739, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "My apologies for the unannounced intrusion, <name>. Do you have a moment? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely! The very thought demands we find out for sure. You are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", ["objectivesText"] = "Meet Archmage Kalec at Azurewing Repose in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 124124, 132471, 139631, 139671, 139672, 139706, 139780, 140196, 140197, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110768, ["x"] = 0.484286, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.484286, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 8022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43501] = { ["id"] = 43501, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 739, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "My apologies for the unannounced intrusion, <name>. Do you have a moment? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely! The very thought demands we find out for sure. The ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", ["objectivesText"] = "Complete the \"Defending Azurewing Repose\" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110768, ["x"] = 0.484286, ["y"] = 0.494 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.484286, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 630, 739 }, ["zone"] = { 8022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43502] = { ["id"] = 43502, ["name"] = "A Change of Seasons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43562, 43563 }, ["description"] = "It is time. The arcan'dor is preparing to mature. With a final burst of growth, this gift will be fully realized. We must make ready the leyline feed.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43503] = { ["id"] = 43503, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Do you have a moment, Conjurer? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away deep within. Perhaps even a new form entirely! The very thought demands we find out for sure. You are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", ["objectivesText"] = "Meet Archmage Kalec at Azurewing Repose in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43505] = { ["id"] = 43505, ["name"] = "The Power Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Do you have a moment, Conjurer? The power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely! The very thought demands we find out for sure. The ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", ["objectivesText"] = "Complete the \"Defending Azurewing Repose\" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43506] = { ["id"] = 43506, ["name"] = "Black Rook Hold: Greater Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "The raw power of the runestones will allow Hymdall to temporarily open a tear into demonic worlds, but it's not enough. The Legion hides its presence in far away worlds with dark magic. Bring a greater runestone so that Hymdall can hone in on our enemies across the cosmos.", ["objectivesText"] = "Defeat Lord Kur'talos Ravencrest and retrieve a Greater Demonic Runestone from Dantalionax in the Black Rook Hold Dungeon. Progress: Do you bring the runestone we require, <name>?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 139453, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43508] = { ["id"] = 43508, ["name"] = "The Captive Spymaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 }, ["series"] = { 37448, 37494, 37666 }, ["description"] = "We must move swiftly while the distraction is working. Mathias Shaw is being held in the lower levels of the Halls of the Eclipse directly to the south. Quickly, <name>, we must go!", ["objectivesText"] = "Follow Taoshi into the Halls of the Eclipse to where Mathias Shaw is being held captive.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110714, ["x"] = 0.298, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110793, ["x"] = 0.27, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5855, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5855, ["name"] = "Saga of the Shadowblade III", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43514] = { ["id"] = 43514, ["name"] = "A Vainglorious Past", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Heart's magic is attuned to Azshara's elite through powerful warding spells. If we tried to tap into its power now we would be met only with our own demise. However, there may be a way we can bypass the wards. Prince Farondis and his court were once a part of Azshara's empire, and still hold on to keepsakes of their sordid past. Among these is sure to be a Vainglorious Draught , said to further bind the queen's followers to her will. See if you can convince the court to part with a bottle.", ["objectivesText"] = "Obtain a Vainglorious Draught from Veridis Fallon. Progress: It may take some effort to convince Farondis' people to part with the draught; some among them still cling desperately to their past lives.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43517] = { ["id"] = 43517, ["name"] = "Darkheart Thicket: Fallen Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Once we have the proper implements we can use the Heart to infuse great power into your artifact. We need only a source. Deep within the Darkheart Thicket lies the ancient Oakheart, once a great and mighty protector of Shaladrassil. He has regrettably fallen to the nightmare like so many of his kin. As the darkness within him has taken root, an essence of the corruption has manifested. I ask that you recover the essence so that we may draw from its power, and put noble Oakheart to rest.", ["objectivesText"] = "Recover a Corrupted Essence from Oakheart and defeat the Shade of Xavius in Darkheart Thicket on Mythic difficulty. Progress: You have the essence?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139633, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43518] = { ["id"] = 43518, ["name"] = "Tempering Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "I do not doubt Senegos' plan, but I do have some concerns about the Heart's volatility, especially when combined with nightmare energy. Despite its name, Blood of Sargeras is often used as a tempering agent by master craftsmen. I believe it would work for our ritual as well. You should keep an eye out for it during your travels - we'll need a substantial amount to ensure that everything goes smoothly.", ["objectivesText"] = "Obtain 5 Blood of Sargeras . Progress: It can be difficult to extract properly, but I do not wish to leave anything to chance.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 132471, 139631 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43519] = { ["id"] = 43519, ["name"] = "Lucid Strength", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We have everything we need, <name>. Once you are ready, raise your artifact and channel its energy upon the Heart of Zin-Azshari to safely absorb the power stored within the nightmare essence. I will use the blood you provided to make sure the ritual stays safely contained.", ["objectivesText"] = "Absorb the power from the Corrupted Essence using the Heart of Zin-Azshari. Progress: This is but the first step in unlocking the true potential hidden away deep within your artifact, but it is an exciting milestone nonetheless.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140304, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43520] = { ["id"] = 43520, ["name"] = "The Emerald Nightmare: In Nightmares", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "We must do what we can to ensure that the Nightmare never again festers within the Emerald Dream. The aberration known as Il'gynoth lies at the heart of the corruption - a living, writhing manifestation of the horrors you will encounter at every turn of your journey. I ask that you ensure its destruction, along with the Nightmare Lord himself... Xavius. Once the deeds have been done, bring a small piece of each to me. We can study them to figure out just how the Nightmare grew so quickly.", ["objectivesText"] = "Obtain a Deathglare Iris and the Horn of the Nightmare Lord from the Emerald Nightmare on Normal difficulty or higher. Progress: Is the deed done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139671, 139672, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 10, ["flags"] = 0 } } },
[43521] = { ["id"] = 43521, ["name"] = "The Emerald Nightmare: Essence of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Now that we have a better understanding on the Heart's capabilities, it is time we tap into its true potential. In the Emerald Nightmare you will find creatures that should not be; monsters that defy all that the Dream stands for. All that the green flight itself stands for. Each of these fiends carry within them corrupted essence , as Oakheart did, but far more potent. Gather all that you can, and we will turn their corruption against them.", ["objectivesText"] = "Collect 10 Corrupted Essence from the Emerald Nightmare on Normal difficulty or higher. Progress: The task before you is not simple, but I have faith in your abilities.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139771, 139780, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 11, ["flags"] = 0 } } },
[43522] = { ["id"] = 43522, ["name"] = "Essential Consumption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "As before, <name>, once you are ready raise your artifact and channel its energy upon the Heart of Zin-Azshari and we will unleash the power of the essence you gathered. Do not worry - we still have enough of the blood you gathered to ensure the ritual remains stable.", ["objectivesText"] = "Absorb the combined power of the Corrupted Essences using the Heart of Zin-Azshari. Progress: After all you have done for my flight, this is but a small favor in return.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 140305, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43523] = { ["id"] = 43523, ["name"] = "Repaid Debt", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Moon Guard fought against the Legion many years ago, during the War of the Ancients. Their intimate knowledge of our enemies would be invaluable to our cause. They have remained in Shal'Aran since you saved Thalrenus and his kin. Shall we pay them a visit and see what they can do?", ["objectivesText"] = "Meet Archmage Kalec inside Shal'Aran in Suramar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 16, ["flags"] = 0 } } },
[43524] = { ["id"] = 43524, ["name"] = "Court of Stars: Literary Perfection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Out of all the books, why that one?! Oh, Mother Moon, I am but a trusting fool. I apologize, you have no idea what I'm going on about. I lent my first edition copy of \" Wards, Sigils, and the Nightborne Way \" to a dear friend - well, former friend, I should say - just before the betrayal. As fate would have it, there is an incantation in that book that I will need for my part of the ritual. Please retrieve it if you can, but be careful - it is quite valuable!", ["objectivesText"] = "Find Lothrius' first edition copy of \" Wards, Sigils, and the Nightborne Way \" in the Court of Stars on Mythic difficulty. Progress: Did you find it? Oh, please tell me you found it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139782, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 18, ["flags"] = 0 } } },
[43525] = { ["id"] = 43525, ["name"] = "Vault of the Wardens: Borrowing Without Asking", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The elusive Wardens run an immense secret prison facility deep underneath the mountains of Azsuna housing all manner of terrible creatures. Perhaps... 'used to run' is more accurate. This presents us with a unique opportunity. The wardens used powerful containment crystals to encase each prisoner in their cell. If any of them still remain intact, we could use one to safely contain the Heart's power. They certainly won't be needing them.", ["objectivesText"] = "Recover a Containment Crystal from the Vault of the Wardens on Mythic difficulty. Progress: Any luck?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139788, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 20, ["flags"] = 0 } } },
[43526] = { ["id"] = 43526, ["name"] = "A True Test", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Vizuul's runebindings are more potent than I had anticipated. Not a bad thing - more power is certainly welcome - but there's certainly more potential for catastrophe if the spell matrix somehow becomes unstable. We should be able to safely contain the fel energy within the containment field using the eon winder you recovered... but keep an eye open just in case.", ["objectivesText"] = "Absorb the power from the Twisted Runebindings using the Heart of Zin-Azshari. Progress: I'm sure we'll be able to keep everything stable.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101080, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 22, ["flags"] = 0 } } },
[43527] = { ["id"] = 43527, ["name"] = "Saving the Guard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Moon Guard were once among the most powerful sorcerers on Azeroth. Most assumed their ranks demolished after the War of the Ancients, but it seems they have managed to survive in their ancient stronghold in Suramar! I believe they could be valuable allies in our quest if they still oppose the Legion. <name>, if you can save what remains of the Guard, I will work to convince the Council of Six to lend us additional aid.", ["objectivesText"] = "Complete the \"Moon Guard Stronghold\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 14, ["flags"] = 0 } } },
[43528] = { ["id"] = 43528, ["name"] = "Planning the Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself. We just need a way inside. I am working fervently with the rest of the Council of Six to secure an entrance. Once we have, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills.", ["objectivesText"] = "Await the opening of the Nighthold, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 111814, ["x"] = 0.625, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 30, ["flags"] = 0 } } },
[43530] = { ["id"] = 43530, ["name"] = "The Nighthold: Delusions of Grandeur", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Grand Magistrix Elisande and her cohorts have lost their minds - they truly believe that allying themselves with the Legion will end in anything but their own demise! They are too far gone to save, I'm afraid, but they still have powerful items that we can use to help us infuse the Heart of Zin-Azshari with their power. In your assault on the Nighthold, ensure you recover the mad construct Trilliax's power core, as well as the spellbook of the Grand Magistrix herself. Good luck.", ["objectivesText"] = "Collect the core of Trilliax and Grand Magistrix Elisande's Millennia Tome in the Nighthold on Normal difficulty or higher. Progress: I ask more of you than I wish, but there is no other way.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140196, 140197, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101083, ["x"] = 0.378, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 31, ["flags"] = 0 } } },
[43531] = { ["id"] = 43531, ["name"] = "The Nighthold: Into the Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Our work is very nearly complete. Now that the Heart can safely absorb power from fel magic, we need the strongest sources of it that we can get our hands on. Gul'dan has called the nightborne's elite back to the Nighthold to aid him. The storm of fel energy above the palace has seeped into the very fabric of their being, even making its way into the crystallized pieces of the Nightwell that many carry with them. Those shards are exactly what we need, <name>. Save as many as you can in your assault.", ["objectivesText"] = "Collect 8 Nightshards from the Nighthold on Normal difficulty or higher. Progress: How many Nightshards were you able to retrieve?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 137575, 139631, 139706, 139780, 140198, 140199, 140200, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 32, ["flags"] = 0 } } },
[43532] = { ["id"] = 43532, ["name"] = "The Nighthold: Darkness Calls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Before we perform the ritual there is one last thing I must ask of you, <name>. You must finally bring Gul'dan to justice. No more of his lies, his deceits, or his trickery. None of it can save him now. Take one of his conjured eyes when you're done. Using his power for good will be a fitting end.", ["objectivesText"] = "Bring one of Gul'dan's eyes to Archmage Kalec on Normal difficulty or higher. Progress: Is the deed done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 32483, 132471, 139631, 139706, 139780, 140198, 140199, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 33, ["flags"] = 0 } } },
[43533] = { ["id"] = 43533, ["name"] = "Balance of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "At long last, it is time to reap the fruits of your labors. Lothrius tells of a place deep in the former Moonguard Stronghold used to infuse new Guards with immense power. It will be the perfect place to tap into and augment the power of the Nightshards you gathered. Gather your effects and meet me there when you are ready, and we will use the Heart to finally reveal the great power within your artifact.", ["objectivesText"] = "Absorb the combined power of the Nightshards and the Eye of Gul'dan using the Heart of Zin-Azshari at the Lunar Crucible. Progress: This is a truly momentous occasion.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132471, 139631, 139706, 139780, 140198, 140199, 140307, 141652, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 34, ["flags"] = 0 } } },
[43534] = { ["id"] = 43534, ["name"] = "Blood of Sargeras", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras . We will need a plentiful quantity. Bring me whatever you can muster.", ["objectivesText"] = "Collect 3 Blood of Sargeras . Progress: Have you acquired any Blood of Sargeras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43535] = { ["id"] = 43535, ["name"] = "Translation: Danger!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "<Delas smears fel blood across the lexicon's pages. Alien sigils blaze forth above the paper. She scribbles them down furiously.> My goodness... these are detailed records of the Legion invasion force at Felblaze Ingress. They are planning to open a portal directly to their demon world of Niskara! This is quite serious - we need to alert your allies at once. If you are going back to Light's Hope Chapel, could I accompany you? I would like to offer my services.", ["objectivesText"] = "Speak to Aponi Brightmane at the Sanctum of Light. Progress: Did you bring back the translation?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43539] = { ["id"] = 43539, ["name"] = "Salanar the Horseman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["series"] = { 42449 }, ["description"] = "The Four Horsemen will need perfect steeds. This is no simple task. For the next step of our campaign, I have organized a mission to the Realm of Shadows. The goal of the mission is to find Salanar the Horseman, leader of the Dark Riders, and summon him to Acherus. The mission is currently waiting your assignment.", ["objectivesText"] = "Complete the \"Salanar the Horsemen\" mission.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 14, ["flags"] = 0 } } },
[43540] = { ["id"] = 43540, ["name"] = "The Mind of the Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8105, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly. Let us find whatever information we can about their plans.", ["objectivesText"] = "Find the Legion Intelligence, the Star Map, the Image of Velen, then slay Brood Queen Aramis .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[43541] = { ["id"] = 43541, ["name"] = "United As One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "I am glad you returned safely, Highlord. Delas Moonfang has also arrived with representatives of the Conclave. The priests have come to discuss Netherlight Temple, their seat of power, hidden deep within the Twisting Nether. As you have both discovered, the Legion has been searching for them for quite some time, and now... they have found them. The Silver Hand has agreed to hear their words. Would you join them now, Highlord?", ["objectivesText"] = "Speak to Delas Moonfang and hear the council of war. Progress: Delas has come on behalf of the Conclave.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139506, 139697, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 10, ["flags"] = 0 } } },
[43562] = { ["id"] = 43562, ["name"] = "Giving It All We've Got", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43502, 43563 }, ["description"] = "The arcan'dor is drawing incredible amounts of energy. Even with the leyline feed at full capacity, we may not have the power. Let us first ensure that all potential leyline conduits connecting to Shal'Aran are active. Then I can attempt to amplify the output and hopefully satisfy this insufferable plant.", ["objectivesText"] = "Activate all of the leyline feeds in Suramar , then speak with Valtrois. Progress: We must activate all of the leyline feeds in Suramar before attempting the spell.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 140328, 141652, 141655, 141682, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43564] = { ["id"] = 43564, ["name"] = "Flow Control", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "If all goes as planned, the manastorm will cause the leyline to flare up, sending a great surge of energy through the arcway. In order for the surge to reach Shal'Aran, we must seal off any outlets along the way. If we miss even one, the mission fails - and hundreds of people will be vaporized by the energy blow off. Thalyssra had better be sure about this tree.", ["objectivesText"] = "Seal off the Arcway Outlets in Lunastre Lane, The Parade Grounds, and the Midnight Court.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140255, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43565] = { ["id"] = 43565, ["name"] = "Bring Home the Beacon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "The conduit we need is in the Arcway, and security in the Arcway has doubled since your last visit. Our only reasonable option is to teleport your strike team directly in. This is a long-range teleport to a non-anchored destination. In other words, it will be hard. Take this beacon and survey the commons in Suramar City, then return the beacon to me so I can analyze the results. This will help me teleport you as close as possible to the conduit!", ["objectivesText"] = "Use the Advanced Telemancy Beacon to survey Evermoon Commons, Evermoon Bazaar, and Siren's Vigil in Suramar City. Progress: Imagine firing an arrow at the sky in hopes of hitting an acorn at the far end of the forest. This teleport will be a little harder, but I think I can do it.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 131811, 140255, 140257, 141605, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3664, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[43567] = { ["id"] = 43567, ["name"] = "All In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43568 }, ["description"] = "It is time to put our plan into action. Oculeth will send you, Arluin and myself into the Arcway, where we shall trigger a manastorm in the Nightflow Conduit. Valtrois will stay here and prepare Shal'Aran for a massive jolt of arcane power - hopefully enough to satisfy the arcan'dor. $p... We have a saying... \"To lead is to stand alone.\" It means only those who bear the weight of leadership can truly appreciate it. Thank you for standing beside me. In truth, I do not feel alone.", ["objectivesText"] = "Complete the \"All In\" scenario. Chief Telemancer Oculeth can begin the scenario.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141684, 237812, 246812, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43569] = { ["id"] = 43569, ["name"] = "Arluin's Request", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["description"] = "I never thought I would need to read this... < Vanthir hefts a scroll in his hand.> Arluin made... plans... in the event he fell. It is not much, but I would like to honor his last request. < Vanthir hands you the scroll.> Go to the location marked on this map. Take this Arcan'dor Fruit and give it to a woman named Arluelle", ["objectivesText"] = "Locate Arluelle and give her a piece of the Arcan'dor Fruit. Progress: Where is Arluin?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140255, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110698, ["x"] = 0.482, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[43571] = { ["id"] = 43571, ["name"] = "Neltharion's Lair: Braid of the Underking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Greetings, Deathlord. Years have passed since we first met, but for me it has been mere days. The unholy bond between Horseman and steed must not be taken lightly. Power begets power, Deathlord. Never forget this fact! I can forge an inseparable bond between rider and steed, but components of great power are required. The first item I require is the Braid of the Underking , a dark shamanic adornment passed down for generations. Currently, it is possessed by Dargrul the Underking.", ["objectivesText"] = "Retrieve the Braid of the Underking from Neltharion's Lair. Progress: Have you acquired the Braid of the Underking ?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139537, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 10, ["flags"] = 0 } } },
[43572] = { ["id"] = 43572, ["name"] = "Darkheart Thicket: The Nightmare Lash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "The dark steeds of the apocalypse are indomitable creatures of anguish and cruelty. They can never be tamed... only subjugated. The next component of power we require is one born of hatred, fashioned within the Emerald Nightmare. It is known as the Nightmare Lash . The Nightmare Lash has the power to suffocate all hope... all light... from within a living soul. The Shade of Xavius himself carries the lash. Defeat him and bring the lash to me! I will use it to dominate the steeds of the damned!", ["objectivesText"] = "Retrieve the Nightmare Lash from Darkheart Thicket. Progress: Do you have the Nightmare Lash ?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139538, 139673, 139676, 139680, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43573] = { ["id"] = 43573, ["name"] = "Advancing the War Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "The quest for the Four Horsemen is of the utmost importance, however we must turn our attention to the warfront. Our continued success on the field of battle has shaken the Burning Legion and as a result, they have increased the frequency and intensity of their assaults. We must meet the increased aggression with continued resistance! Only then will we be able to turn our attention back to the Four Horsemen.", ["objectivesText"] = "Complete 10 World Quests. Progress: How goes the war effort?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43574] = { ["id"] = 43574, ["name"] = "Maw of Souls: Maul of the Dead", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "All of the necessary components have been gathered together. Soon, the unholy steeds of the damned will trample the armies of the Burning Legion. However, our work is not quite done. One item yet remains beyond our grasp... Lurking within the depths of Helheim, the fallen queen Helya rules over the dead. In her possession is a maul, infused with the souls of countless fallen warriors. Bring to me the Maul of the Dead and with it, I will forge barding so impenetrable... no demon shall break it!", ["objectivesText"] = "Retrieve the Maul of the Dead from Helheim. Progress: Have you brought me the Maul of the Dead ?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140162, 140517, 140923, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43576] = { ["id"] = 43576, ["name"] = "Regroup at the Refuge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38684, 38687, 38743, 40567, 40890, 41056, 41708, 41724, 41893, 43576, 43702 }, ["description"] = "I cannot think clearly in this place. Even though the moonwell is still pure, the corrupting influence of the Nightmare remains. Come, we will return to the refuge and gather our wits. Then we will continue the hunt for my husband.", ["objectivesText"] = "Return to Starsong Refuge.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104885, ["x"] = 0.668, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 103022, ["x"] = 0.6805, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43577] = { ["id"] = 43577, ["name"] = "Capturing the Gateway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "The time has come to make our move against the Legion. The Legion has multiple portals across the Broken Isles. Should your armies succeed in securing one while it's still active, Hymdall can use the runestones you gathered to direct it to whatever hellish world Hodir is trapped in.", ["objectivesText"] = "Complete the missions: Investigate Felsoul Hold, Preparing Our Arrival and Capturing the Gateway.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43581] = { ["id"] = 43581, ["name"] = "The Wisdom of Patience", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The horrors you braved in the thicket are only the beginning. Within the Emerald Nightmare you will face the very heart of the corruption that threatens the stability of all life on Azeroth. But not just yet. We have not yet managed to permeate the magic protecting Xavius' sinister realm. Once we have, however, you should return here; there is still much to be done.", ["objectivesText"] = "Await the opening of the Emerald Nightmare, then report back to Senegos in Azsuna.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132471, 139631 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 100482, ["x"] = 0.48, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 9, ["flags"] = 0 } } },
[43582] = { ["id"] = 43582, ["name"] = "Shalassic Park", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 41231 }, ["description"] = "We have a Devilsaur. I think she sees you as the pack leader now. She should obey your commands. She looks hungry. Why don't you let her off the leash a little bit?", ["objectivesText"] = "Ride Su'esh and defeat 50 adversaries.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140026, 140034, 141679, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111019, ["x"] = 0.48, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 110987, ["x"] = 0.506, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43585] = { ["id"] = 43585, ["name"] = "Preparing For War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["description"] = "We would do well to bolster our own forces before calling upon our allies to join us in the final conflict against the Legion. There still remains much to do in the Broken Isles and victories there will give us the momentum we need to crush the enemy.", ["objectivesText"] = "Complete \"Aiding the Valkyra,\" \"Lost at Sea\" and \"Enslaved by Sea Giants\" missions. Progress: Any news, <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 9, ["flags"] = 0 } } },
[43586] = { ["id"] = 43586, ["name"] = "Maw of Souls: Message to Helya", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42616, 42618, 43090, 43586, 43604 }, ["description"] = "We cannot fight on two fronts and succeed. If we're to give ourselves the room we need to fight off the Legion we need to deliver a decisive victory against Helya. Not her armies, not her lieutenants, but the mother of the underworld herself. Go to the Maw of Souls and defeat Helya, <name>.", ["objectivesText"] = "Defeat Helya inside the Maw of Souls dungeon. Progress: Is it done?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5806, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5806, ["name"] = "Chronicles of Skyhold II", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43594] = { ["id"] = 43594, ["name"] = "Leyline Feed: Halls of the Eclipse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43594 }, ["description"] = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", ["objectivesText"] = "Infuse the leyline feed with Ancient Mana . Progress: <The leyline feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[43604] = { ["id"] = 43604, ["name"] = "Maw of Souls: Ymiron's Broken Blade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42616, 42618, 43090, 43586, 43604 }, ["description"] = "You hold King Ymiron's blade and realize what a fierce combatant he would make, were he to fight on your side. Perhaps Odyn could be persuaded to force the vrykul King's spirit to fight alongside your army.", ["objectivesText"] = "Return to Skyhold and convince Odyn to raise King Ymiron.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139619, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5806, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5806, ["name"] = "Chronicles of Skyhold II", ["orderIndex"] = 2, ["flags"] = 1 } } },
[43644] = { ["id"] = 43644, ["name"] = "To the Deeps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8046, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["description"] = "I assure you the legends are true: Sharas'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing. Wavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj'ir, but we haven't heard from her since. <name>! Come with me to the ocean depths. Let's track down our missing shaman and get that artifact!", ["objectivesText"] = "Travel to the Ruins of Vashj'ir with Erunak. Progress: I can transport us to the depths. Step into the bubble here... It's mostly safe.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 54465, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 128819, 128911, 128935, 131432, 131433, 169354, 218343, 225245, 226146, 227792, 237812 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 8046 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 205, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43645] = { ["id"] = 43645, ["name"] = "Wavespeaker's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 5144, ["mapID"] = 205, ["storyline"] = { 40341, 43644, 43645 }, ["series"] = { 40341 }, ["description"] = "The shaman we seek is Wavespeaker Adelee. Her research brought her down to these ancient ruins, where she reported naga armies amassing prior to the Legion invasion. The last I had heard, she had located Sharas'dal, the Scepter of Tides - and then she went silent. <name>, Search for clues to her whereabouts among the lower level of the ruins. Beware the naga patrols!", ["objectivesText"] = "Locate three clues to the whereabouts of Wavespeaker Adelee within the Ruins of Vashj'ir. Progress: How goes the search?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 54465, 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 }, ["starts"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 205, ["npcID"] = 96530, ["x"] = 0.435, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 205, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 5144 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 267, ["questLineOrder"] = 8 } }, ["db2PoiUiMapID"] = 205, ["questLines"] = { { ["id"] = 267, ["name"] = "Azshara's Power", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43686] = { ["id"] = 43686, ["name"] = "The Fourth Horseman", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 43686, 44248 }, ["description"] = "The Lich King demands too much! Tirion Fordring deserves more than a life of anguish and undeath! Know this, Deathlord... I will obey your will, but there will be no redemption for what we are about to do. The Silver Hand will never hand Tirion to us. The path to the Fourth Horseman will be soaked in righteous blood! Blood that will stain our hands forever. Your will be done, Deathlord. I will begin the preparations to invade Light's Hope. If this is what it takes to save our world, so be it!", ["objectivesText"] = "Obtain the Fourth Horseman .", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 97919, 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 142057, 142059, 142060, 142061, 142063, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5895, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5895, ["name"] = "The Four Horsemen III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43697] = { ["id"] = 43697, ["name"] = "Warriors of Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["series"] = { 43700 }, ["description"] = "We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.", ["objectivesText"] = "Listen as you are honored by the Order of the Silver Hand. Progress: We rejoice in our triumph!", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 139690, 142055, 142056, 142059, 142061, 142062, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43698] = { ["id"] = 43698, ["name"] = "Lumenstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "To prepare for the battle ahead, we will need armor and weapons. We have learned of lumenstone , a rare metal that can negate magic... even fel magic. It is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting. We should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", ["objectivesText"] = "Collect 50 Lumenstone by sending champions on \" Lumenstone \" missions. Progress: Have you acquired any lumenstone ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139634, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43699] = { ["id"] = 43699, ["name"] = "Defenders of the World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["description"] = "Requests are pouring in from across the Broken Isles for our aid, Highlord. I know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help. We cannot turn our backs on those who need our aid.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43700] = { ["id"] = 43700, ["name"] = "A Light in the Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43534, 43697, 43698, 43699, 43700, 43701, 43785, 91619 }, ["series"] = { 43697 }, ["description"] = "Highlord, thank goodness you've arrived! The invasion of Netherlight Temple has begun. Our forces are already waiting on the other side of the portal. Join them, and we will close the trap around Lord Balnazzar .", ["objectivesText"] = "Go to Netherlight Temple using the priest's portal in Dalaran, then defend Netherlight Temple and slay Lord Balnazzar . Progress: The priests have always been our allies and friends. Now, we stand united against a common cause.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44018, 44039, 44041, 44042, 44043, 120978, 128823, 128866, 139506, 139690, 139693, 139697, 140517, 140929, 237812, 257143, 265106, 265631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5827, ["questLineOrder"] = 3 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5827, ["name"] = "Path of the Light III", ["orderIndex"] = 4, ["flags"] = 0 } } },
