[43702] = { ["id"] = 43702, ["name"] = "Softening the Target", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38675, 38684, 38743, 40567, 40890, 41054, 41749, 41763, 41890, 43576, 43702 }, ["description"] = "The Archdruid's end draws near. His memory will live on in the hearts of all who knew him. Elothir's desperate efforts revealed that Malfurion is being held in Shala'nir, amidst the roots of Shaladrassil. My love. So near, yet so far.... Shala'nir is infested with Nightmare creatures. To rush in would be suicide. I subdued one of Xavius' creatures. Use it against him, <name> and clear us a path.", ["objectivesText"] = "Slay 50 Nightmare Creatures in Shala'nir riding the Subdued Nightwing . Progress: Have you managed to thin their numbers?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 104728, ["x"] = 0.642, ["y"] = 0.427333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.642, ["y"] = 0.427333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 189, ["questLineOrder"] = 6 }, { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 190, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 189, ["name"] = "All Nightmare Long", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 190, ["name"] = "All Nightmare Long", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43705] = { ["id"] = 43705, ["name"] = "Nobundo's Last Stand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8277, ["mapID"] = 775, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "The Exodar shook from the force of the Legion's arrival. Before we could react, demons were running rampant through the halls, slaughtering everything in their path. If it were not for the Prophet, we would have all perished in the initial assault. I was charged with evacuating the Crystal Hall, which is when my Broken and I were separated from the main force. We fell back into the collapsed hall to make our last stand. With your aid, we may survive this invasion.", ["objectivesText"] = "Defend Farseer Nobundo from the Legion Assault. Progress: The Legion must fall!", ["rewardGold"] = 663840, ["rewardXP"] = 1415, ["rewardItems"] = { 140602, 140603, 140604, 140605, 140606, 140607, 140608, 140609, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8277 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1624, ["db2PoiUiMapID"] = 775, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 5, ["flags"] = 1 } } },
