[43750] = { ["id"] = 43750, ["name"] = "The Call of Battle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42107, 42110, 42193, 42194, 42202, 42204, 42614, 42650, 42651, 43585, 43750 }, ["series"] = { 42193 }, ["description"] = "Once, the mighty titanforged keepers of Ulduar and Odyn acted as one. Ever since Odyn broke off to create the valarjar, not even Odyn's own son Thorim is bound to follow his father's advice. There is one hope to unite the forces of Skyhold and Ulduar however. The Gjallarhorn was a gift given to Hymdall before Odyn's departure. The keepers of Ulduar are oathbound to answer the call of the Gjallarhorn were it to be sounded as it would signal that the end times are upon us!", ["objectivesText"] = "Speak to Hymdall .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 137642, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 238, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 238, ["name"] = "Chronicles of Skyhold I", ["orderIndex"] = 0, ["flags"] = 0 } } },
