[43797] = { ["id"] = 43797, ["name"] = "Aiding the Conclave", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "The priests of the Conclave are formidable allies. With our combined strength, we may just have a chance to slay the dreadlord, forever. Let Alonsus Faol know that we will be by your side and ready to fight when you need us.", ["objectivesText"] = "Return to Alonsus Faol within Netherlight Temple.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 139506, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 20, ["flags"] = 0 } } },
