[43810] = { ["id"] = 43810, ["name"] = "Down to Business", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "First things first, <name>: we must set up our camp. We do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike. They are drawing up their battle lines within the city, but could attack us while we are setting up our defenses. Venture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.", ["objectivesText"] = "Enter the Grand Promenade and slay 15 defenders.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143740, 143741, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 4, ["flags"] = 0 } } },
