[43812] = { ["id"] = 43812, ["name"] = "Down to Business", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["description"] = "Time to get to business, <name>. We cannot afford to tarry. While we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes. They are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.", ["objectivesText"] = "Enter the Grand Promenade and slay 15 defenders.", ["rewardGold"] = 280900, ["rewardXP"] = 4605, ["rewardItems"] = { 143740, 143741, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.452667, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 5, ["flags"] = 0 } } },
