[43829] = { ["id"] = 43829, ["name"] = "Spy vs. Spy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43958, 44041 }, ["description"] = "SI:7 is the espionage and intel branch of the Alliance. They are based out of Stormwind City and headed up by Master Mathias Shaw. As of late, they have been acting, shall we say, peculiar. I would like for you to send some of our people out to assess the situation. It might be nothing, but I am not fond of situations that I do not fully understand. If we are going to win this war against the Burning Legion, the last thing we need is for something wholly unexpected to occur.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Spy vs. Spy\".", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 23372, 23373, 23390, 23391, 23392, 23393, 24441, 25553, 57498, 57499, 57500, 63793, 63794, 63796, 63797, 133695, 190454, 191984, 191988, 191990, 191991, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192005, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192037, 198490, 198529, 198532, 198695, 205423, 209837, 211279, 237812, 246427 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43832] = { ["id"] = 43832, ["name"] = "Elixirs of Aid", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43398, 43399, 43400, 43401, 43402, 43832, 43923, 43924, 43925 }, ["description"] = "We can never be too prepared for battle. The Legion will strike at any moment, and we must be ready to deal with a multitude of injuries and afflictions. Zabra and Yalia have provided me a list of their most potent potions and battle elixirs than can do everything from restore health to blind the enemy. We have an exhaustive list of ingredients that we'll need in order to craft a respectable supply.", ["objectivesText"] = "Collect elixir crafting ingredients for Alonsus Faol .", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124105, 124111, 124120, 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5860, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5860, ["name"] = "Fulfilling the Prophecy III", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43841] = { ["id"] = 43841, ["name"] = "Convincin' Old Yancey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43852 }, ["description"] = "Avast ye! Th' time be long overdue that we get some more pirate blood into our ranks. <Crackers gives a sudden squawk in agreement.> And I know just th' man t' do it. I'm talkin' about good old Yancey Grillsen, o' course. He's an old salt down Stranglethorn way. Send some o' your land lovin' scallywags off t' round him up.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Convincin' Old Yancey\".", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[43851] = { ["id"] = 43851, ["name"] = "Recruiting More Troops", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43377, 43380, 43381, 43382, 43383, 43384, 43385, 43386, 43387, 43388, 43389, 43390, 43391, 43392, 43393, 43394, 43395, 43396, 43397, 43797, 43851 }, ["description"] = "Word of your leadership has spread rather fast. Priests of all sorts have traveled to the temple to lend their aid. We're lucky enough to have caught the eye of Vicar Eliza . She's quite the leader in her own right, commanding countless devotees that do her bidding without question. Speak to her now.", ["objectivesText"] = "Speak to Vicar Eliza .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5859, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5859, ["name"] = "Fulfilling the Prophecy II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[43852] = { ["id"] = 43852, ["name"] = "Fancy Lads and Buccaneers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43841 }, ["description"] = "Aye, it warms me heart t' know that Yancey's now part o' th' crew. <Tethys feeds Crackers some cackle fruit from the table.> Why don't you be a good <lad/lass> and see if he can sponge us up some bilge rats.", ["objectivesText"] = "Speak with your Pirate recruiter, Yancey Grillsen . Progress: Are you lookin' t' be shark bait? Where be our new crew of pirates? <Crackers squawks in agreement.>", ["rewardGold"] = 110640, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 9, ["flags"] = 0 } } },
[43899] = { ["id"] = 43899, ["name"] = "Steeds of the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen. Salanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items. Use the mission table to assign your chosen champions to the task.", ["objectivesText"] = "Complete 5 \"Fallen Steeds\" missions. Progress: Have you completed the necessary missions for Salanar the Horseman?", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 9, ["flags"] = 0 } } },
