[43926] = { ["id"] = 43926, ["name"] = "Legion: The Legion Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 44120, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Warriors of da Horde! Break out ya axes and sharpen ya spears. Da Burning Legion has returned ta our world! We be shipping outta Bladefist Bay right away. With da full fury of da Horde, we gonna smash der line so hard dat Sargeras is gonna feel it in da Nether! Get to da ships. We got demons ta slay!", ["objectivesText"] = "Check in with Holgar Stormaxe at the Dranosh'ar Blockade. Provided item:", ["rewardItems"] = { 132119, 140192, 143785, 237812 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 4311, ["x"] = 0.46, ["y"] = 0.134 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.134 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 2, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43928] = { ["id"] = 43928, ["name"] = "Aggregates of Anguish", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "Our preparations for conjuring the Steeds of the Damned are nearly complete. Salanar the Horseman has given us a list of the remaining components. The ritual of conjuring requires five unholy essences known as the Aggregates of Anguish. I have taken it upon myself to organize the necessary missions to obtain these components. Use the mission table to assign your chosen champions to the task.", ["objectivesText"] = "Complete 5 \"Unholy Attainment\" missions.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43933] = { ["id"] = 43933, ["name"] = "Champion: Delas Moonfang", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[43934] = { ["id"] = 43934, ["name"] = "A New Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["description"] = "Highlord <name>, if I could have a moment of your time? Long have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more. When I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me. I wish to become a paladin of the Silver Hand. Will you allow me to join you?", ["objectivesText"] = "Speak to Delas Moonfang . Progress: What do you think?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 181743, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 12, ["flags"] = 0 } } },
[43935] = { ["id"] = 43935, ["name"] = "A Second Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 43935, 44407 }, ["description"] = "Perhaps it's time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested. Let me show you what your options are and you can choose one.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5833, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5833, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43943] = { ["id"] = 43943, ["name"] = "Withered Army Training", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 680, ["storyline"] = { 43943 }, ["objectivesText"] = "Bring 400 Ancient Mana to Thalyssra", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 93730, 124124, 127834, 127847, 127848, 127849, 127850, 136269, 136914, 137564, 137573, 139010, 139011, 139017, 139018, 139019, 139027, 139028, 139546, 139563, 139565, 139786, 139804, 139890, 140218, 140226, 140260, 140326, 140327, 140328, 140329, 140447, 140448, 140449, 140450, 140451, 140495, 140778, 140780, 140786, 141296, 141297, 141298, 141299, 141300, 141301, 141306, 141313, 141314, 141593, 141639, 141652, 141870, 143764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bring 400 Ancient Mana to Thalyssra", ["amount"] = 1, ["type"] = 0, ["objectID"] = 111948, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[43945] = { ["id"] = 43945, ["name"] = "Expanding Your Horizons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 43945, 44006 }, ["series"] = { 44406 }, ["description"] = "You are a fast study, <class>t <name>. The elements speak through you - it is rare to have such a connection to the world. A true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another? Speak with me and let us discuss your options.", ["objectivesText"] = "Speak with Aggra to choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5834, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5834, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43949] = { ["id"] = 43949, ["name"] = "More Weapons of Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 43949, 44417 }, ["description"] = "It is wise to carry more than one weapon to war. Sometimes one will be better suited than another. You should choose another weapon of legend to carry with you, especially against foes so deadly. What say you?", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5825, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5825, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43958] = { ["id"] = 43958, ["name"] = "A Body of Evidence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43829, 44041 }, ["description"] = "There is an urgent matter that requires your attention, <name>. The body of a woman with a knife in her back has turned up in the sewers. Normally, such a matter would be less than newsworthy... but this isn't your average cutthroat. It's an SI:7 operative! I've got some of our goons guarding the body, but you had better get over there before the word spreads. If SI:7 finds out about this... it will be bad for business.", ["objectivesText"] = "Investigate the body of the SI:7 operative for clues. Progress: Did you identify the body? Was it an SI:7 operative?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140278, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43962] = { ["id"] = 43962, ["name"] = "Blades of Destiny", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 43962, 44401 }, ["description"] = "I'm glad that weapon you've been carrying around has proven useful. Our ally, the Lich King, has offered to provide you with a lead on another weapon should the one you already have somehow be lacking. Consider the options carefully and let me know which you would like to seek out.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 22130, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5840, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5840, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43969] = { ["id"] = 43969, ["name"] = "Hired Help", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "I was fond of Margaux. News of her death weighs heavily on many of us. < Vanthir shakes his head sadly.> If we are to carry on, we need to send a strong message. We need those like Durant to know that we are watching, and we will hold them accountable. I know someone who could help us. His name is Arluin . To call him a reluctant ally would be generously overstating it. He is cautious, and will not risk himself without compensation. You can find him in the alleys north of the Evermoon Bazaar.", ["objectivesText"] = "Locate Arluin and persuade him to help you. Progress: Best not to lurk if you aren't doing business.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107253, ["x"] = 0.512, ["y"] = 0.724 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 11, ["flags"] = 0 } } },
[43973] = { ["id"] = 43973, ["name"] = "Two Paths, Two Weapons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 43973, 44424 }, ["description"] = "We've searched through our scrolls and have found new leads on a couple of powerful weapons. They may prove beneficial in our efforts. Here, let me show you what I've found. If any of these interest you then simply let me know.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5837, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5837, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43975] = { ["id"] = 43975, ["name"] = "Recruiting Shieldmaidens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["storyline"] = { 43975 }, ["description"] = "The powerful val'kyr Savyn Valorborn has arrived to aid us in bolstering our numbers. She ushers some of the most valorous vrykul shieldmaidens into the Halls of Valor. Speak to her and recruit powerful troops to add to our roster.", ["objectivesText"] = "Speak to Savyn Valorborn .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard" },
[43980] = { ["id"] = 43980, ["name"] = "Another Weapon of Old", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 43980, 44431, 44443 }, ["description"] = "You have done well but our foes are powerful and cunning. It would be wise to be prepared for whatever they may unleash upon us. You would be wise to consider obtaining another of the weapons of old to aid in our conflict. Let me know how you'd like to proceed.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5838, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5838, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43984] = { ["id"] = 43984, ["name"] = "The Tome Opens Again", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 43984, 44089 }, ["description"] = "You've been doing well, friend, but you would be unstoppable if you had another weapon at your side. Here, let me show you what options remain in the book. If either of these interest you then simply let me know.", ["objectivesText"] = "Choose a second artifact to pursue. Progress: Thoughts, friend?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5836, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 274, ["name"] = "The Tome of Blighted Implements", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5836, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[43991] = { ["id"] = 43991, ["name"] = "The Protectors", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity. To find these essences, we must consult the protectors of the forest. Go to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.", ["objectivesText"] = "Use your druidic powers to commune with protectors at the Feral Stone, the Guardian Stone, the Restoration Stone, and the Balance Stone.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44004] = { ["id"] = 44004, ["name"] = "Bringer of the Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44153 }, ["description"] = "Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear. We must hurry, <name>. We must uncover the object's sacred purpose. The prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen. I will open a portal for you now. Take my beacon and use it when you are ready to return.", ["objectivesText"] = "Discover the purpose of the Mysterious Lightbound Object. Progress: Have you discovered anything about the object?", ["rewardGold"] = 808800, ["rewardXP"] = 1415, ["rewardItems"] = { 140319, 140533, 140574, 140610, 140611, 140612, 140613, 140614, 140615, 140616, 140617, 140763, 237812, 251480 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44006] = { ["id"] = 44006, ["name"] = "Your Fullest Potential", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 43945, 44006 }, ["description"] = "I see that you walk many paths, as a true shaman should. Two mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle. Speak with me, and together we will unlock your fullest potential.", ["objectivesText"] = "Speak with Aggra to choose a third artifact to pursue. Progress: Where are the spirits guiding you, Farseer?", ["rewardGold"] = 20220, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5834, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5834, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44009] = { ["id"] = 44009, ["name"] = "A Falling Star", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "<class>t <name>, thank you for coming. I have a matter of some urgency that requires your unique talents. The Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having \"cut a swath\" through the Felstorm itself. Will you investigate? There is a gryphon awaiting your arrival at Krasus' Landing.", ["objectivesText"] = "Find the Mysterious Lightbound Object . Progress: Show me what you've found.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 110560, 140192, 140319, 140533, 140574, 140763, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44034] = { ["id"] = 44034, ["name"] = "Another Worthy Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 44034, 44375 }, ["description"] = "We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work. I would be happy to go over the remaining options with you so that you may make an informed decision.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5832, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5832, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44040] = { ["id"] = 44040, ["name"] = "Vote of Confidence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "I will endeavor to protect my son until the votes are cast. Coryn Stelleris is a predator even among the nobility. It does not surprise me that he should stoop to such depths to ensure his own success. Tell Ly'leth that she has my support. Unequivocally. You may also choose to tell her that Coryn Stelleris will hurt her, if she gives him a chance. Be careful.", ["objectivesText"] = "Return to Ly'leth at the Waning Crescent.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 110679, ["x"] = 0.575, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107632, ["x"] = 0.46, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44041] = { ["id"] = 44041, ["name"] = "The Bloody Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["series"] = { 43829, 43958 }, ["description"] = "We need to find out who is behind the assassination of Amber Kearnen. It won't be long before SI:7 realizes that their agent is MIA and comes sniffing around The Hall of Shadows. Here, take these stylish spy glasses and set them to scan for traces of hemoglobin. I've taken the liberty of calibrating them specifically for Amber Kearnen's blood. Follow the blood trail back to the culprits, but make sure to stay out of sight! Report back to us when you've got the information we need.", ["objectivesText"] = "Discover the truth behind the hit on the SI:7 agent. Progress: Were you able to find out who's behind the assassination attempt?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140395, 140517, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44043] = { ["id"] = 44043, ["name"] = "Continuing the Legend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 40953, 40954, 40955, 40957, 40958, 40959, 44043, 44366 }, ["description"] = "There are still two paths you may walk - two powerful weapons you might yet obtain to aid you in the fight against the Legion. I will help you recall your remaining options, of course.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107317, ["x"] = 0.435333, ["y"] = 0.26 }, { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.435333, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5831, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 174, ["name"] = "The Unseen Path", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5831, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44051] = { ["id"] = 44051, ["name"] = "Wasted Potential", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44051 }, ["description"] = "You have done well for us here, but it is time for you to return to Thalyssra. There is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way. Oh, and before you go: <Vanthir hands you a wrapped bottle of Arcwine.> Take this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child. We are grateful beyond measure. Farewell for now.", ["objectivesText"] = "Activate the teleporter pad and bring Vanthir's gift to Thalyssra.", ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111900, ["x"] = 0.442, ["y"] = 0.703333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.703333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44052] = { ["id"] = 44052, ["name"] = "And They Will Tremble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "There will be consequences for what has transpired this day. For now, you should return to Thalyssra. Tell her that we have avenged Margaux and that the Dusk Lily has announced itself to all of Suramar . There will be many more deaths before this is over, rest assured, but this is a death that will teach others like Durant to tread more carefully in the future.", ["objectivesText"] = "Return to Thalyssra", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 139790, 140255, 140410, 141678, 141953, 141954, 237812, 246815, 246937, 247914, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 16, ["flags"] = 0 } } },
[44053] = { ["id"] = 44053, ["name"] = "Friends With Benefits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 }, ["description"] = "The Lunastre Attendant , silent as ever, offers you a wax-sealed scroll. It reads: \"Dearest <name>, I asked my attendant to catch you, should things go in my favor. The role of Advisor will keep me away from the estate for some time and I settled on a gift for Thalyssra. I have sent a detachment of attendants to Shal'Aran with some comfort items. Treat them well- they need someone to wait on and I could think of none better! Give the others my thanks, and my love, Advisor Ly'leth Lunastre\"", ["objectivesText"] = "Return to Thalyssra.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 111903, ["x"] = 0.383429, ["y"] = 0.519714 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.383429, ["y"] = 0.519714 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 202, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 202, ["name"] = "Statecraft", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44063] = { ["id"] = 44063, ["name"] = "Bolstering Your Arsenal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 44063, 44370 }, ["description"] = "Highlord, there are still weapons that you might obtain to help you defeat the Legion. We have kept a close eye on them during your time on the Broken Isles. I would be happy to review them with you if you wish.", ["objectivesText"] = "Choose a second artifact to pursue.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5830, ["questLineOrder"] = 9 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5830, ["name"] = "Weapons of Legend", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44074] = { ["id"] = 44074, ["name"] = "Neltharion's Lair: Essence of Tenacity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Greetings, Archdruid. I hear that you seek the essence of tenacity . There is none more unyielding and unbreakable than a creature of stone. In Neltharion's Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.", ["objectivesText"] = "Collect 1 Essence of Tenacity from Rokmora in Neltharion's Lair, then slay Dar'grul the Underking. Progress: Stand firm, <class>.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 140311, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 2, ["flags"] = 1 } } },
[44075] = { ["id"] = 44075, ["name"] = "Halls of Valor: Essence of Ferocity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "To find the essence of ferocity , you must seek a creature who has slain thousands, and is revered by even the gods. I speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.", ["objectivesText"] = "Collect 1 Essence of Ferocity from Fenryr in the Halls of Valor, then prove your worth to Odyn . Progress: It takes a ferocious beast to take down another ferocious beast.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 139469, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 3, ["flags"] = 1 } } },
[44076] = { ["id"] = 44076, ["name"] = "Darkheart Thicket: Essence of Regrowth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "My child, I can think of only one place to capture the essence of regrowth . Deep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare's corruption, but deep within his heart, he still fights. Gather the essence of this great tree, so that his everliving soul may be used to fuel new life.", ["objectivesText"] = "Collect 1 Essence of Regrowth from Oakheart in Darkheart Thicket, then defeat the Shade of Xavius . Progress: My heart aches for those fallen to the Nightmare.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 140313, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 4, ["flags"] = 1 } } },
[44077] = { ["id"] = 44077, ["name"] = "Eye of Azshara: Essence of Balance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7979, ["mapID"] = 747, ["storyline"] = { 42037, 42040, 42041, 42042, 42043, 42044, 42045, 42046, 42047, 42048, 42129, 42719, 43365, 43368, 43991, 44074, 44075, 44076, 44077 }, ["description"] = "Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist. Slay it. In its aftermath, you may find the essence of balance that you seek.", ["objectivesText"] = "Collect 1 Essence of Balance from the Wrath of Azshara. Progress: We follow Elune's path.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 140312, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7979 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5884, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5884, ["name"] = "The Eternal Dream II", ["orderIndex"] = 5, ["flags"] = 1 } } },
[44082] = { ["id"] = 44082, ["name"] = "Knights of the Ebon Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 42533, 42534, 42535, 42536, 42537, 42708, 43571, 43572, 43899, 44082, 44243, 44244, 44482 }, ["description"] = "Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential. I cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion. The demon armies are nearly endless and we are few. Speak with Korgaz when you are ready to recruit additional death knights.", ["objectivesText"] = "Speak to Korgaz Deadaxe .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5893, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5893, ["name"] = "The Four Horsemen I", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44084] = { ["id"] = 44084, ["name"] = "Vengeance for Margaux", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42792, 42828, 42829, 42832, 42833, 42834, 42835, 42836, 42837, 42838, 42839, 42840, 42841, 43352, 43969, 44052, 44084 }, ["description"] = "< Sylverin sputters, pale-faced with rage.> How could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her! Such injustice cannot stand. We must take vengeance for Margaux.", ["objectivesText"] = "Slay 8 Vineyard Enforcers or Wardens.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 141678, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108870, ["x"] = 0.5275, ["y"] = 0.5205 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.5275, ["y"] = 0.5205 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 201, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 201, ["name"] = "Blood and Wine", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44087] = { ["id"] = 44087, ["name"] = "Return to the Fel Hammer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44161 }, ["description"] = "<name>, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with. He requests your presence back on the Fel Hammer as soon as possible.", ["objectivesText"] = "Speak with Battlelord Gaardoun on the Fel Hammer.", ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 17, ["flags"] = 1 } } },
[44089] = { ["id"] = 44089, ["name"] = "A Greater Arsenal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 40684, 43984, 44089 }, ["description"] = "The tome speaks of one more weapon that friend can use against our foes. Do you wish to seek it?", ["objectivesText"] = "Speak with Calydus to choose to pursue your final artifact. Progress: Have you made your choice?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5836, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 247, ["name"] = "Weapon of Legend", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 274, ["name"] = "The Tome of Blighted Implements", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5836, ["name"] = "Weapons of Legend", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44090] = { ["id"] = 44090, ["name"] = "Pledge of Loyalty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 44090 }, ["description"] = "The eagle appears to have a message for you: To: <name> I hope this message finds you well. Word of Ohn'ahra's omen has traveled fast. There are many who wish to pledge their loyalty to the Unseen Path's new leader. Return to me at Trueshot Lodge, and we can discuss this further. - Altar Keeper Biehn", ["objectivesText"] = "Return to Altar Keeper Biehn in Trueshot Lodge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 102940, ["x"] = 0.476333, ["y"] = 0.530333 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.476333, ["y"] = 0.530333 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[44098] = { ["id"] = 44098, ["name"] = "Recruiting Apprentices", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 42149, 42166, 42171, 42206, 42222, 42418, 42433, 42434, 42435, 42705, 42706, 44098 }, ["description"] = "Grand Conjuror Mimic has arrived to aid us in bolstering our numbers. She seeks out the most promising apprentices and trains them very quickly. Her former students are some of the most powerful conjurors in the land! Speak to her and recruit some of her apprentices to add to our roster.", ["objectivesText"] = "Speak to Grand Conjuror Mimic.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5868, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 5868, ["name"] = "Rise of the Tirisgarde I", ["orderIndex"] = 11, ["flags"] = 0 } } },
[44099] = { ["id"] = 44099, ["name"] = "A Mutual Friend", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 717, ["storyline"] = { 40684, 40716, 41748, 41750, 41797, 42601, 42602, 42603, 42608, 44099 }, ["description"] = "It's good to see you are well. I've been sent by our mutual friend, Calydus . He is eager to speak with you. Please return to Dreadscar Rift at your earliest convenience.", ["objectivesText"] = "Return to Calydus within Dreadscar Rift.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5872, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5872, ["name"] = "Council of the Black Harvest", ["orderIndex"] = 6, ["flags"] = 1 } } },
[44100] = { ["id"] = 44100, ["name"] = "Proper Introductions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 40705, 40706, 40938, 41019, 43270, 43271, 43272, 43273, 43275, 43276, 43277, 44100 }, ["description"] = "I'm glad I found you. I have a message from Alonsus Faol . He says introductions are in order, and requests your presence within Netherlight Temple at your earliest convenience.", ["objectivesText"] = "Return to Alonsus Faol within Netherlight Temple.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5857, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5857, ["name"] = "Light and the Void", ["orderIndex"] = 7, ["flags"] = 1 } } },
[44106] = { ["id"] = 44106, ["name"] = "Archdruid of Lore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38225, 38235, 38381, 44106 }, ["description"] = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore. Seek him out and tell him that he is desperately needed here.", ["objectivesText"] = "Seek out Elothir in Thas'talah.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 94179, ["x"] = 0.544, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 91066, ["x"] = 0.488, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 187, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 187, ["name"] = "Archdruid of Lore", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44116] = { ["id"] = 44116, ["name"] = "Mystery at Citrine Bay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents? Something isn't adding up... We need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization? The encrypted letter she was carrying may hold the clues... but we need more information. The SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we'll see about getting this letter decrypted.", ["objectivesText"] = "Speak with Fleet Admiral Tethys at Citrine Bay in Stormheim.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140931, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44117] = { ["id"] = 44117, ["name"] = "Time Flies When Yer Havin' Rum!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Thar be few pirates ye want to cross swords wit' less than th' Red Blade! They be salty dogs, indeed! That being said... they does have a way wit' rum! I'll level wit' ye, <name>... thar be few rums as jolly as that 'o th' Red Blade. Seein' as ye be headin' off in search 'o clues, ye might as well brin' back a few bottles while ye be at it! Brin' me back as many bottles as ye can find, and I'll reward ye handsomely! Pirates honor, <name>!", ["objectivesText"] = "Collect 10 bottles of Red Blade Rum . Progress: Have ye got th' spiced rum, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140729, 140931, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44120] = { ["id"] = 44120, ["name"] = "Illidari Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44281, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives. I gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I'd like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause. Just... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.", ["objectivesText"] = "Meet with the Illidari representative in the Mage Quarter of Stormwind.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44137] = { ["id"] = 44137, ["name"] = "Into the Fray", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely. Come, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", ["objectivesText"] = "Speak with the lead demon hunter at Illidari Stand.", ["rewardGold"] = 309800, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93337, ["x"] = 0.45, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 }, { ["mapID"] = 630, ["npcID"] = 101927, ["x"] = 0.435, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44140] = { ["id"] = 44140, ["name"] = "From Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 36811, 36920, 37449, 37450, 37653, 37656, 37658, 37660, 38834, 39718, 40815, 41220, 44137, 44140 }, ["description"] = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within. I haven't heard from them in a while. It would be best if you could find and lead them to success. Agreed?", ["objectivesText"] = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89362, ["x"] = 0.435, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 90255, ["x"] = 0.412, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 275, ["title"] = "Azsuna", ["questLineID"] = 5747, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5747, ["name"] = "Behind Legion Lines", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44152] = { ["id"] = 44152, ["name"] = "A Growing Crisis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "The Arcan'dor is failing. This energy was once bound in its boughs and fueled its growth. There was balance, between life and arcane. Now that energy is breaking free. When the heart can no longer hold it, this tree will kill every living thing in this hall. I have seen this happen before and I must find a way to stop it from happening again. We must go to the tree that came before. Its bones can guide us. Meet me at the temple of Fal'adora. We will descend together.", ["objectivesText"] = "Meet Valewalker Farodin at the Temple of Fala'dora. You can travel there using the Portal to Falanaar in Shal'aran.", ["rewardXP"] = 770, ["rewardItems"] = { 140255, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44153] = { ["id"] = 44153, ["name"] = "Light's Charge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44004 }, ["description"] = "\"You did not ask for this burden, but it is what fate has deemed.\" Turalyon's haunting last words still echo in my mind. I worry about the fate of the draenei... about the fate of my friend, Velen; but we must remain vigilant, <name>! For now, Light's Heart remains under your watchful eye. There is one place on Azeroth that I would trust with the safekeeping of the object: your order hall. Take it there, <name>. I will remain in Dalaran and continue looking for answers. There must be another way!", ["objectivesText"] = "Place Light's Heart in your Order Hall. Progress: This is where you must place Light's Heart .", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140319, 140533, 140574, 140763, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44155] = { ["id"] = 44155, ["name"] = "Searching For Clues", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "It be no coincidence that we be in Citrine Bay investigatin' a murder, and we find th' band 'o pirates known as th' Red Blade here as well! Aye, this be no coincidence at all, <name>... but we be needin' proof! Ye go on ahead and look fer clues and I'll find some scallywags to interrogate. Aye <name>, we'll get t' 'th bottom o' this t' be sure! Thar be no doubt!", ["objectivesText"] = "Find proof of SI:7 working with The Red Blade. Progress: Have ye found evidence 'o th' murder from th' pirates 'o th' Red Blade?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140730, 140931, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44156] = { ["id"] = 44156, ["name"] = "Another Arcan'dor Closes...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "I hope you have a better understanding of what is at stake. Come. There is no more for us to do here. Meet me in Shal'aran and we will discuss what steps we may take next.", ["objectivesText"] = "Return to Shal'aran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140255, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44161] = { ["id"] = 44161, ["name"] = "Things Gaardoun Needs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 39047, 39261, 40814, 40816, 41033, 41037, 41060, 41062, 41066, 41067, 41069, 41070, 41096, 41099, 41221, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 42690, 42695, 42697, 42869, 42872, 44087, 44161 }, ["series"] = { 37447, 42510, 42522, 42666, 42670, 42671, 42677, 42679, 42681, 42682, 42683, 44087 }, ["description"] = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that. Time to put your new champions to the test. I'm sure it will be a grueling mission.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Things Gaardoun Needs\". Progress: Did they come back already with whatever it is that Gaardoun needs?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5887, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5887, ["name"] = "The Illidari", ["orderIndex"] = 24, ["flags"] = 0 } } },
[44177] = { ["id"] = 44177, ["name"] = "Dark Secrets and Shady Deals", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "Whatever Amber Kearnen knew, Mathias Shaw didn't want it gettin' out... Aye, this be dirty business indeed, hiring th' Red Blade at such a price... just to hunt down and kill one of their own! Ye best get back to th' Hall 'o Shadows, and let Lord Ravenholdt know what we found here in Citrine Bay. Whatever SI:7 be up to, it be goin' deeper than we first imagined...", ["objectivesText"] = "Speak with Lord Ravenholdt.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 140517, 140931, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 112959, ["x"] = 0.772, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44178] = { ["id"] = 44178, ["name"] = "A Particularly Potent Potion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 }, ["description"] = "I've got a proposition for ya, <name>! Word has it that Trade Prince Gallywix recently acquired a priceless, one-of-a-kind love potion. There's only one goblin who can replicate it and you're looking at him! Get me that potion and I can make us both richer than kings! The pleasure palace is located in Azshara and it has been on high alert since the war started. Gallywix isn't letting anybody in except his personal staff, but I know a girl on the inside! Find her and she'll get you to the safe!", ["objectivesText"] = "Steal Love Potion #6 from Gallywix's personal safe. Progress: Do you have the goods?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 127837, 128476, 128870, 128872, 136786, 139506, 139739, 139742, 139746, 140517, 140811, 140814, 140931, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5853, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5853, ["name"] = "Saga of the Shadowblade I", ["orderIndex"] = 15, ["flags"] = 0 } } },
