[44184] = { ["id"] = 44184, ["name"] = "In the Blink of an Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44182, 44421, 44500 }, ["description"] = "The Broken Isles is our destination, <name>. The spell that will blink Dalaran to its new location is not a simple one. It will take this Council's full energy and attention. As Jaina is... absent, Kalecgos of the blue dragonflight has offered us his aid. The Legion will make every attempt to stop us, but we will not falter. It is time to begin!", ["objectivesText"] = "Witness the teleportation of Dalaran to the Broken Isles.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 140192, 143785, 223988, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44214] = { ["id"] = 44214, ["name"] = "One More Thing...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["storyline"] = { 44214 }, ["series"] = { 43412 }, ["description"] = "Well done, Slayer. You are truly now the leader of the Illidari. But there's one more thing. Meet me down at the forge.", ["objectivesText"] = "Head down to the chamber of the Cursed Forge of the Nathrezim on the lower level of the Fel Hammer.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard" },
[44215] = { ["id"] = 44215, ["name"] = "One More Thing...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44215 }, ["series"] = { 43422 }, ["description"] = "Firstly, allow me to congratulate you. I know of no one more deserving of the title of Shadowblade. But there's one more thing. Meet me over near the forge.", ["objectivesText"] = "Meet Lord Ravenholdt in the Uncrowned Vault.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
