[44252] = { ["id"] = 44252, ["name"] = "A Sheath For Every Blade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44252 }, ["description"] = "<name>, your cunning and leadership inspires awe in all of us! The Uncrowned are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", ["objectivesText"] = "Accept a gift from the Uncrowned.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139742, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[44257] = { ["id"] = 44257, ["name"] = "A Falling Star", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496 }, ["series"] = { 42866 }, ["description"] = "<Khadgar ponders the information that you brought to him.> You say that it cut a swath through the Felstorm and was emanating power enough that your scout could feel it coursing through their body? Something that powerful could prove to be a potent weapon against the Burning Legion! I will inform the other order leaders of your discovery while you investigate the matter further! A gryphon awaits your command at Krasus' Landing! Light guide you.", ["objectivesText"] = "Find the Mysterious Lightbound Object . Progress: Show me what you've found.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140574, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 236, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 236, ["name"] = "Path of the Light I", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44278] = { ["id"] = 44278, ["name"] = "Illidari Freedom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "< Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.> Within the prison are three of our... <cough>... comrades. We were taken by surprise while scouting the area. I am not long for this world, <name>, but please... you can still save them.", ["objectivesText"] = "Free Sirius Ebonwing , Cassiel Nightthorn , and Asha Ravensong .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95028, ["x"] = 0.39, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44281] = { ["id"] = 44281, ["name"] = "To Be Prepared", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40518, 40522, 40605, 40607, 40760, 43926, 44092, 44281 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44463, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "Our allies have made the journey to Orgrimmar to support our war efforts. Stop and visit with them, <name>. Their assistance will secure our victory today.", ["objectivesText"] = "Visit Horde forces in Dranosh'ar Blockade. Progress: Blood and thunder, friend.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 59679, 59680, 59681, 59682, 59683, 59684, 65872, 65884, 65886, 138450, 139718, 141294, 141295, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 4311, ["x"] = 0.46, ["y"] = 0.134 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 113547, ["x"] = 0.555, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.134 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 260, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44282] = { ["id"] = 44282, ["name"] = "Eye of Azshara: The Frozen Soul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["series"] = { 44247 }, ["description"] = "Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure. I recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost. I have reason to believe that it may be found somewhere within the Eye of Azshara. Retrieve the pendant for me, and it will prove most useful in my studies.", ["objectivesText"] = "Retrieve the Frozen Soul Pendant from the Wrath of Azshara. Progress: Have you retrieved the pendant?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 141302, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 13, ["flags"] = 0 } } },
[44286] = { ["id"] = 44286, ["name"] = "Vault of the Wardens: A Masterpiece of Flesh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7695, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["description"] = "Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh. Actually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans. My first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items. The prisoners in the Vault of the Wardens should make fine donors for the parts I require.", ["objectivesText"] = "Retrieve the Beating Fel-Heart and Demonic Entrails from Vault of the Wardens. Progress: Have you retrieved the parts?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 128292, 128402, 128403, 139506, 139673, 139676, 139680, 140517, 140923, 141307, 141308, 141309, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7695 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 7, ["flags"] = 0 } } },
