[44457] = { ["id"] = 44457, ["name"] = "Brotherly Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38714, 38715, 38717, 38718, 38719, 38721, 38724, 44278, 44457 }, ["description"] = "Maiev will be somewhere in the prison. I found her discarded armor on my way here. I know the two of you have a history. I trust that will not be a problem. Let's split up to search the cells more quickly. We must find her.", ["objectivesText"] = "Find Maiev Shadowsong in Black Rook Prison. Provided item:", ["rewardGold"] = 331700, ["rewardXP"] = 1415, ["rewardItems"] = { 139353, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 277, ["title"] = "Val'sharah", ["questLineID"] = 192, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 192, ["name"] = "Black Rook Hold", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44463] = { ["id"] = 44463, ["name"] = "Demons Among Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44471, 44473, 44543, 44663, 95215 }, ["description"] = "It is just as we suspected, <name>! The demons thought they could take us by surprise. Quickly, to arms! Warn the King!", ["objectivesText"] = "Protect the King. Progress: Now is not a good time.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128959, 129104, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8445, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44464] = { ["id"] = 44464, ["name"] = "Awakenings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Light's Heart is to serve as the vessel for Illidan Stormrage's rebirth: my last act of service to the Light. But Illidan is dead and his soul is lost in the Nether. Before we may attempt to recover his soul, we must prepare the vessel for his return. Across two worlds exist echoes of Illidan's past. You must venture out and find the echoes. Start where all life begins, <name>: birth. Find Illidan's birthplace in Val'sharah. Awaken the memory.", ["objectivesText"] = "Witness the Awakening of Illidan Stormrage in Val'sharah. Progress: When our work is complete, I will be lost to the Great Dark.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 141351, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 10, ["flags"] = 0 } } },
[44465] = { ["id"] = 44465, ["name"] = "Recruiting Earthcallers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 41770, 41771, 41776, 41901, 41981, 42184, 42977, 43002, 44465 }, ["description"] = "Felinda Frye has recently joined us at the Heart of Azeroth. She oversees the recruitment and training of our Earthcallers. I recommend that you speak with her at your soonest convenience, Farseer <name>. The Earthcallers are powerful shaman and will greatly bolster our ranks.", ["objectivesText"] = "Speak to Felinda Frye .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5863, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5863, ["name"] = "The Elemental Lords I", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44466] = { ["id"] = 44466, ["name"] = "An Unclear Path", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44479 }, ["description"] = "Much of Illidan's formative years were spent in Val'sharah, alongside his twin brother, Malfurion. As young night elves, the twins vied for the affection of the young priestess, Tyrande, as they underwent the trials of the demi-god, Cenarius. We must travel to the Dreamgrove now, where Illidan's true path would be forged.", ["objectivesText"] = "Witness Illidan's Resilience at the Dreamgrove in Val'sharah. Progress: You mustn't lose hope.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 11, ["flags"] = 0 } } },
[44471] = { ["id"] = 44471, ["name"] = "Second Sight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44473, 44543, 44663, 95215 }, ["description"] = "Though young King Anduin is a noble soul, he may lack the conviction of his father. The Alliance needs a leader who will do what needs to be done. The Legion will strike at the first hint of weakness. Even now, I sense something amiss, <name>. I fear that not all is as it seems. Quickly, use your Spectral Sight. We must know if there are foes among us!", ["objectivesText"] = "Use your Spectral Sight. Progress: Time is precious.", ["rewardGold"] = 1500, ["rewardXP"] = 1060, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 102585, ["x"] = 0.8445, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8445, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44473] = { ["id"] = 44473, ["name"] = "A Weapon of the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 39691, 40661, 44463, 44471, 44473, 95215 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44543, 44663, 95215 }, ["description"] = "At first I was unsure whether it was wise to allow the Illidari inside the city. But you may have just saved all our lives. You may establish a camp in the Mage Quarter. The Alliance will have need of your skills if we are to face the Legion. Make no mistake though. Should your kind give in to the fel energies you toy with, we will treat you like the demons you are becoming.", ["objectivesText"] = "Meet with the Illidari in the Mage Quarter of Stormwind.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 100973, ["x"] = 0.855, ["y"] = 0.317 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.317 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44480] = { ["id"] = 44480, ["name"] = "In My Father's House", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Most mortals cannot comprehend the truth of the Legion. Those that recognize it, often refuse to accept its meaning. Such knowledge carries a weight that the mortal frame cannot bear. To sacrifice that much of ones self changes the soul. Among your greatest heroes, a rare few understood that type of sacrifice. Let us witness it through Illidan's eyes. We must go to Azshara, on the continent of Kalimdor.", ["objectivesText"] = "Witness Illidan's Sacrifice in Azshara on the continent of Kalimdor. Progress: The vessel is nearly ready to take on the soul.", ["rewardGold"] = 404400, ["rewardXP"] = 1770, ["rewardItems"] = { 237812, 249230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 16, ["flags"] = 0 } } },
[44481] = { ["id"] = 44481, ["name"] = "Destiny Unfulfilled", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus. Yet, in a strange twist of fate, it was not the Burning Legion who came for him in the end. We must travel to Outland to experience Illidan's last memory.", ["objectivesText"] = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland. Progress: When the vessel is prepared, we will seek out his soul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 32757, 121745, 137015, 139909, 139946, 140005, 151016, 237812, 249229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 19, ["flags"] = 0 } } },
[44489] = { ["id"] = 44489, ["name"] = "Lyana Darksorrow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "<Your fellow Illidari, Lyana Darksorrow , floats captive in stasis in front of you; her soul slowly draining into the harvester crystal.> <In order to release her from stasis, you will need to destroy the soul harvester.>", ["objectivesText"] = "Destroy the Soul Harvester.", ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98801, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 0, ["flags"] = 0 } } },
