[44497] = { ["id"] = 44497, ["name"] = "Destiny Unfulfilled", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 747, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["description"] = "Hardly recognizable from the golden eyed child of prophecy, and living as an outcast on the fringes of a shattered world, his motivation remained unchanged. His assaults on the Legion and his attempts to end their march were his only focus. Yet, in a strange twist of fate, it was not the Burning Legion who came for him in the end. We must travel to Outland to experience Illidan's last memory.", ["objectivesText"] = "Witness True Betrayal in Shadowmoon Valley on the fringes of Outland. Progress: When the vessel is prepared, we will seek out his soul.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 32757, 121745, 139909, 139946, 140005, 237812, 249229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 17, ["flags"] = 0 } } },
[44544] = { ["id"] = 44544, ["name"] = "Call of the Earthen Ring", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 39746, 40225, 41335, 41510, 41740, 41741, 42114, 42141, 42142, 42188, 42197, 42198, 42383, 44544 }, ["description"] = "At last, I've found you! I have a message from Advisor Sevel . The Earthen Ring has need of you, Farseer. Please return to the Heart of Azeroth at your soonest convenience. Advisor Sevel is eagerly awaiting your return.", ["objectivesText"] = "Speak with Advisor Sevel .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5862, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5862, ["name"] = "A Ring Unbroken", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44550] = { ["id"] = 44550, ["name"] = "Called to Acherus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 680, ["storyline"] = { 39799, 39816, 39818, 39832, 40714, 40715, 42449, 42484, 43264, 43265, 43266, 43267, 43268, 43539, 44550 }, ["description"] = "Deathlord, your presence has been requested on Acherus. The war against the Burning Legion rages on and the Knights of the Ebon Blade await further orders. Please return to Acherus at your soonest convenience. Siouxsie the Banshee is awaiting your return.", ["objectivesText"] = "Speak with Siouxsie the Banshee at Acherus: The Ebon Hold. You can use Death Gate to return there.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5892, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5892, ["name"] = "The Ebon Blade", ["orderIndex"] = 9, ["flags"] = 1 } } },
[44555] = { ["id"] = 44555, ["name"] = "Khadgar's Discovery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40009, 40123 }, ["description"] = "Champion! Please come to the Violet Citadel immediately. I have made a discovery that I would like to share with you before the Council of Six.", ["objectivesText"] = "Speak with Archmage Khadgar in Dalaran.", ["rewardGold"] = 5865, ["rewardXP"] = 770, ["rewardItems"] = { 121804, 140234, 141667, 142054, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 32, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 1, ["flags"] = 1 } } },
[44561] = { ["id"] = 44561, ["name"] = "Seed of Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44561 }, ["description"] = "Thalyssra was wise to send you in search of the arcan'dor, though she underestimates its power. She will learn - as will the others. But it will take time. And with hunger gnawing at their very souls, the Nightfallen will need your help to survive.", ["objectivesText"] = "Reach Honored with The Nightfallen . Progress: The arcan'dor needs time.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141681, 141685, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44562] = { ["id"] = 44562, ["name"] = "Growing Strong", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44562 }, ["description"] = "Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us. The shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony. But I sense potential among the Nightfallen . Losing everything has humbled them. It has made them stronger. Stay the course, $p. Help the Nightfallen rise up.", ["objectivesText"] = "Reach Revered with The Nightfallen . Progress: Have you felt it? Change is on the wind.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141681, 141685, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44636] = { ["id"] = 44636, ["name"] = "Building an Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44636 }, ["description"] = "We must keep our eyes on the future. There will come a time when we will need an army. We've proven that the withered are not completely beyond redemption. They can be taught, and molded. I want you to be their combat trainer, <name>. Come with me. We can use the nearby ruins as an arena to hone their abilities.", ["objectivesText"] = "Speak with Thalyssra when you are ready to lead the withered in their first combat training mission.", ["rewardItems"] = { 93730, 124124, 127834, 127847, 127848, 127849, 127850, 136269, 136914, 137573, 139010, 139011, 139017, 139018, 139019, 139027, 139028, 139546, 139563, 139565, 139786, 139890, 140218, 140226, 140260, 140326, 140327, 140328, 140329, 140447, 140448, 140449, 140450, 140451, 140495, 140778, 141296, 141593, 141652, 141870 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44663] = { ["id"] = 44663, ["name"] = "In the Blink of an Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 85, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44543, 95215 }, ["description"] = "<The entity speaks with the familiar voice of Archmage Khadgar.> Azeroth needs you, <name>! After scouring Ulduar and Karazhan for answers, we know the key to defeating the Legion: five ancient artifacts called the Pillars of Creation. To find them, Dalaran must be moved to the Broken Isles. As our leader Jaina is... absent, Kalecgos of the blue dragonflight has offered the Kirin Tor his aid. The Legion is assaulting our current position over Deadwind Pass. Hurry!", ["objectivesText"] = "Witness the teleportation of Dalaran to the Broken Isles.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 140192, 143785, 237812 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 95234, ["x"] = 0.525667, ["y"] = 0.569 }, { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.525667, ["y"] = 0.569 }, ["mapCandidates"] = { ["npc"] = { 84, 85 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 619, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44667] = { ["id"] = 44667, ["name"] = "Will of the Valarjar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 42619, 42918, 42974, 43425, 43506, 43577, 44667 }, ["description"] = "As we prepare to launch an attack on the Legion's own world, it is important to not give reprieve to our enemies in this one. As your armies seek to secure enemy gateways, you would do well to return to the Broken Isles and carry on the battle against those who stand against you.", ["objectivesText"] = "Complete 10 World Quests. Progress: You've returned, <name>.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5807, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5807, ["name"] = "Chronicles of Skyhold III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44672] = { ["id"] = 44672, ["name"] = "Ancient Mana", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["description"] = "Without the Nightwell to feed upon, my comrades and I will have to live off the land itself. Ancient mana from the underground leylines can reach the surface in many forms, most commonly as crystals or gems. <Thalyssra picks up a small stone and, whispering words of power, traces a rune upon it with her fingertip.> This stone will glow when ancient mana is nearby. Please gather as much as possible! It will be a precious resource in the weeks to come.", ["objectivesText"] = "Gather from 3 Ancient Mana nodes. Progress: We need all the ancient mana we can get. Make sure you know how to find it!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44680] = { ["id"] = 44680, ["name"] = "Leading by Example", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 42133, 42402, 42405, 42408, 42415, 42654, 42655, 42656, 42657, 42658, 42659, 43182, 44680, 91616 }, ["description"] = "We cannot let our current situation overshadow the Unseen Path's mission to protect the people of Azeroth. There are many in this world who could use our help. As our leader, you can set the example by aiding those in need.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 107973, ["x"] = 0.44, ["y"] = 0.450667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.450667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5850, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5850, ["name"] = "Watchers in the Wild III", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44682] = { ["id"] = 44682, ["name"] = "Unparalleled Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 41751, 41754, 41755, 41756, 41785, 41787, 41788, 41793, 41795, 41796, 42102, 42103, 42660, 44682 }, ["description"] = "Power is all around us, <name>, waiting to be harnessed. You must venture out into the world and claim it for the council! With our First wielding such unparalleled power, our enemies won't stand a chance.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5875, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5875, ["name"] = "Rebuilding the Council III", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44689] = { ["id"] = 44689, ["name"] = "The Might of the Tirisgarde", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 42707, 42734, 42914, 42917, 42940, 44689 }, ["description"] = "The Tirisgarde has received requests from across the Broken Isles for aid in fighting the Burning Legion. While we will continue pursuing Archmage Vargoth, we cannot forget that our primary mission is to repel the demons and protect Azeroth.", ["objectivesText"] = "Complete 10 World Quests. Progress: Azeroth will burn without our help.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5870, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5870, ["name"] = "Rise of the Tirisgarde III", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44690] = { ["id"] = 44690, ["name"] = "A Thirst For Blood", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 42818, 42821, 42823, 42824, 42882, 43573, 43574, 43928, 44245, 44246, 44247, 44282, 44286, 44690, 91615 }, ["objectivesText"] = "Progress: Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best. If my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 124124, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5894, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 5894, ["name"] = "The Four Horsemen II", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44691] = { ["id"] = 44691, ["name"] = "Hungry Work", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40011, 40747, 40748, 40830, 40956, 44691 }, ["description"] = "We must get Chief Telemancer Oculeth back on his feet as soon as possible. Find ancient mana, any way you can, and feed it to him.", ["objectivesText"] = "Use Ancient Mana to feed Chief Telemancer Oculeth .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 129039, 141652, 141933, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98548, ["x"] = 0.3664, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 154, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 154, ["name"] = "The Telemancer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44694] = { ["id"] = 44694, ["name"] = "One Battle at a Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 42669, 42701, 42735, 42736, 42737, 42738, 42739, 42749, 42752, 42753, 42775, 42776, 42777, 42787, 44694 }, ["description"] = "Before I became a demon hunter, I practiced the arcane arts. I still retain some of that knowledge, though the fel makes it all but impossible to use. One thing I can still manage is the occasional glimpse into faraway places. You've seen me use the nether crucible to do this. I'm afraid that things don't look too good. The forces that are arrayed against us are not limited to the Burning Legion. You must act quickly to keep the Broken Isles from being overwhelmed.", ["objectivesText"] = "Complete 10 World Quests.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5889, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 5889, ["name"] = "Destiny of the Illidari II", ["orderIndex"] = 14, ["flags"] = 0 } } },
[44700] = { ["id"] = 44700, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38035, 38206, 39800, 44700 }, ["series"] = { 38035, 38052, 38206, 39735, 39800 }, ["description"] = "It is good we found you, <name>! Sky Admiral Rogers has sent word for you to meet her in Dalaran. It sounded important. She awaits your presence in the Violet Citadel. Make haste!", ["objectivesText"] = "Speak to Sky Admiral Rogers at the Violet Citadel in Dalaran.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003, 237812, 246812, 246814, 248247 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107460, ["x"] = 0.302, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 96644, ["x"] = 0.185538, ["y"] = 0.462154 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 84, 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 131, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 131, ["name"] = "Greymane's Gambit", ["orderIndex"] = 0, ["flags"] = 1 } } },
[44701] = { ["id"] = 44701, ["name"] = "Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38307, 39698, 39801, 44701 }, ["series"] = { 38307, 39864 }, ["description"] = "It is good we found you, <name>! Nathanos Blightcaller , Champion of the Banshee Queen herself, sent for you in Dalaran. He made it sound urgent. He should be waiting for you in the Violet Citadel. Make haste!", ["objectivesText"] = "Speak to Nathanos Blightcaller at the Violet Citadel in Dalaran.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 128861, 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 142003, 237812, 246812, 246814, 248247 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 107460, ["x"] = 0.302, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 96683, ["x"] = 0.612, ["y"] = 0.088 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1, 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 280, ["title"] = "Stormheim", ["questLineID"] = 130, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 130, ["name"] = "Greymane's Gambit", ["orderIndex"] = 0, ["flags"] = 1 } } },
[44719] = { ["id"] = 44719, ["name"] = "Breaching the Sanctum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["series"] = { 45417, 45420 }, ["description"] = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area. Take these telemancy orbs . If you find you need support, use them to summon Withered. We must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", ["objectivesText"] = "Speak with Oculeth to start the assault. Progress: We've done it! Despite the initial failures, we are still in position to enter the Breach and free our comrades.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142118, 142401, 143747, 146669, 237812, 246812, 246813, 246814, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115367, ["x"] = 0.433, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44722] = { ["id"] = 44722, ["name"] = "Disillusioned Defector", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "The atmosphere in the city has improved little, but we may find this to our advantage today. Silgryn asks for you at the Terrace. It seems even Elisande's forces are fleeing before her insanity. A defector has risen from the ranks and seeks to join our cause. See that this individual is well received, <name>. We need all the friends we can get during these dark times.", ["objectivesText"] = "Meet Silgryn at Evermoon Terrace.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44723] = { ["id"] = 44723, ["name"] = "More Like Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Greetings, Outlander. I am Victoire . I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good. The massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself. There are others who feel as I do. They simply need proof that there is another way. The Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.", ["objectivesText"] = "Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters. Progress: Did you find more like me?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142065, 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114956, ["x"] = 0.52, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114956, ["x"] = 0.52, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44724] = { ["id"] = 44724, ["name"] = "Missing Persons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Our new friend brings us some disturbing information. She claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor. Those taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons. I need you to find out where these people went. Infiltrate the harbor and gather any information you can. Start with the Legion filth- their corpses may point us in the right direction.", ["objectivesText"] = "Acquire a Legion Communicator from demons in Astravar Harbor. Progress: Have you learned where the captives have been taken?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142066, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44725] = { ["id"] = 44725, ["name"] = "Hostage Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Our own people, sacrificed to the Legion! We need to intercept a transport if we intend to put an end to this trade. I'm afraid this does mean you will be playing the part of a captive, my friend. Before voicing your concerns, try to have a little faith. We will follow behind in one of Deline's boats and break you out once we know where they are going. Go to the harbor and find a group of captives. Stand among them. Allow yourself to be taken. We will not be far.", ["objectivesText"] = "Go to Astravar Harbor and join a group of captives being taken to Felsoul Hold. Progress: Please try to trust me. We will allow no harm to come to you.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44726] = { ["id"] = 44726, ["name"] = "In the Business of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "We will hold our position here while you find and slay the demon responsible for this camp. Ending Aargoss will not permanently stop this smuggling operation, but it may slow them down long enough for us to find another way to help these people. Go quickly. He is somewhere atop this ridge.", ["objectivesText"] = "Slay Aargoss in Felsoul Advance. Progress: Have you dealt with Aargoss ?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143739, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44727] = { ["id"] = 44727, ["name"] = "Smuggled!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "Please get me out of here! The bars are brittle but I am so weak... The others! There are so many others! Please help us!", ["objectivesText"] = "Release Maribeth and 5 captives in Felsoul Advance.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115002, ["x"] = 0.258, ["y"] = 0.885 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115376, ["x"] = 0.248, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44736] = { ["id"] = 44736, ["name"] = "Gates of the Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 45267, 45282 }, ["description"] = "Our combined armies are arrayed in front of the palace, ready to strike! I cannot believe the time has come. Your allied commanders are already there and we will join you. Make your way to Astravar Harbor and speak with Khadgar. He is coordinating the attack, or at least I think he is. See you there... and thanks for everything.", ["objectivesText"] = "Go to Astravar Harbor and begin the siege of Nighthold with the elves. Progress: Well, that was... unexpected.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44738] = { ["id"] = 44738, ["name"] = "Full Might of the Elves", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44739, 44740, 45266, 45281 }, ["description"] = "Thalyssra managed to get all 3 to agree to the same thing? I am impressed with her skills of negotiation. Alright hero, Liadrin is already marching on Suramar . Join her forces. Tyrande will flank the city defenders and meet you deeper in. The Nightborne will bring up the rear and hold the territory for us. Oculeth and I will move the Kirin Tor forces to Astravar Harbor. With luck, we shall see you on the other side.", ["objectivesText"] = "Lead the elven army to Astravar Harbor. Progress: All this running is exhausting.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140040, 140069, 140071, 140072, 140073, 140074, 140075, 140076, 140077, 140078, 143749, 237812, 246812, 246814 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44739] = { ["id"] = 44739, ["name"] = "Ready for Battle", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44740, 45266, 45281 }, ["description"] = "Thanks to your efforts and a lot of effort on the part of our new army, the Nightfallen are prepared for battle. What is more, we have managed to evacuate nearly all of the civilians between here and Astravar Harbor. I have drafted plans that can lead our combined forces through the city and take the harbor. Can you deliver these plans to Vereesa, Tyrande and Liadrin?", ["objectivesText"] = "Deliver plans to Vereesa Windrunner , Lady Liadrin and Tyrande Whisperwind . Progress: So many different types of elves. Each of us changed in some way by the magic we wield. It is very, enlightening.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 211279, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44740] = { ["id"] = 44740, ["name"] = "Staging Point", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44739, 45266, 45281 }, ["description"] = "That is quite a corridor you and our allies have punched through the city. It will be difficult to hold but it will cut a wedge in Elisande's forces. Oculeth has been busy redirecting a telemancy beacon to this location but wanted to give you the honor of activating it.", ["objectivesText"] = "Activate the Astravar Beacon. Progress: Has the beacon been activated.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812, 246813, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.692667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44742] = { ["id"] = 44742, ["name"] = "Tavernkeeper's Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["series"] = { 45262 }, ["description"] = "I have finished unraveling Ly'leth's message. I want you to come with me to her estate. It is long past time I returned to the city.", ["objectivesText"] = "Follow Thalyssra to the Lunastre Estate and learn of Vanthir's fate. Progress: Dire news like this cannot wait.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115247, ["x"] = 0.432, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44743] = { ["id"] = 44743, ["name"] = "Tyrande's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44827, 44858, 44859, 44860, 44861, 44862 }, ["description"] = "Shal'aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Tyrande has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.", ["objectivesText"] = "Speak with Tyrande Whisperwind in Meredil.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44752] = { ["id"] = 44752, ["name"] = "Essence Triangulation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Vanthir... an example! That certainly explains why Elisande chose to hold him this long. We need to move quickly. I can track him, but I will need to find places where his Arcane Essence is strongest. This will not be an easy feat, not in a city this old, but with any luck there are a few places important enough to him that he left a little bit of himself behind. We should start in the promenade- he often visited it for business.", ["objectivesText"] = "Help Thalyssra collect 3 of Vanthir's Arcane Essences. Progress: Did you find them?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.789 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44753] = { ["id"] = 44753, ["name"] = "On Public Display", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Now that I have identified Vanthir's essence from the multitude of Suramar 's citizens, it may be that I can find his exact location. I believe you'll recall a similar ritual with our friend Theryn. Do not worry- there will be less screaming this time. Hopefully. Come. Let us find our missing tavernkeeper.", ["objectivesText"] = "Help Thalyssra complete the Scrying Ritual. Progress: I need to maintain complete focus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115248, ["x"] = 0.476, ["y"] = 0.789 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115557, ["x"] = 0.522, ["y"] = 0.79 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.789 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44756] = { ["id"] = 44756, ["name"] = "Sign of the Dusk Lily", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "Simply... astounding. I have not felt this clear of mind in so long. I am still weak... I need to rest. But first... < Vanthir gestures to the top of his cage with a trembling hand.> Show them that the Dusk Lily triumphs this day.", ["objectivesText"] = "Place a Dusk Lily Sigil above Vanthir 's Cage.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143487, 237812, 246813, 246815, 247842, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115604, ["x"] = 0.488, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44758] = { ["id"] = 44758, ["name"] = "What's the Cache?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45833, 46322 }, ["description"] = "We're here for a cache of gunpowder. It seems to have been infused with some sort of fel power... it's extremely reactive. One of the leaders of the pirate forces here currently has it. Master Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", ["objectivesText"] = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache . Progress: Did you get the gunpowder?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142116, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44766] = { ["id"] = 44766, ["name"] = "Backup Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45207, 45437, 46335, 46338, 46705 }, ["description"] = "Dalaran may appear to be just a floating city, but it is actually our most powerful magical weapon. It will take time to repair the arcane defenses - time the Legion will use to their great advantage. It is imperative to come up with an interim plan, and quickly! Archmage Kalec is very knowledgeable about this sort of thing. Perhaps you should consult with him?", ["objectivesText"] = "Speak with Archmage Kalec .", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44768] = { ["id"] = 44768, ["name"] = "Nyell's Workshop", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 691, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46339, 46345 }, ["description"] = "From what I've overheard, this is Master Artificer Nyell 's workshop. His skills in construct creation are unparalleled! What a shame that he swore fealty to the Legion. I hate to destroy such a renowned craftsman, but we have no choice. If you are lucky, he might even have a spare shield generator sitting around.", ["objectivesText"] = "Kill Master Artificer Nyell . Progress: Were you successful?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142212, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 691, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44770] = { ["id"] = 44770, ["name"] = "Secrets of the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 691, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46351 }, ["description"] = "This workshop includes an extensive library of rare scrolls written by my people. We all benefit by sharing information, do you not agree? Perhaps if we bring back such a treasure trove the Tirisgarde will be more welcoming towards me and my kind... Please gather whatever you can.", ["objectivesText"] = "Gather 8 Ancient Shal'dorei Scrolls . Progress: Have you found some scrolls?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142211, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 691, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44775] = { ["id"] = 44775, ["name"] = "The Peak of Bones", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44783 }, ["description"] = "While you were gone, we strategized what to do with the harness. We can utilize its power to bind the spirits of deceased drakes to you, raising them under your will as loyal soldiers. I sent Minerva to Thorim's Peak in Stormheim, where she has found a brood of deceased Thorignir. They will be prime targets. Speak to Grimwing for a flight to the mountain, then Minerva will fill you in.", ["objectivesText"] = "Speak to Grimwing for a flight to Thorim's Peak, then meet Minerva.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 115360, ["x"] = 0.512, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44782] = { ["id"] = 44782, ["name"] = "Away From Prying Eyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "Wars are not won solely with armies charging bravely across the battlefield, <class>t. Sometimes, it is the actions of individuals that matter most, fighting battles few ever hear about. That is why - <Khadgar furrows his brow slightly.> We should really discuss this somewhere a tad more private. Let's move up to the Purple Parlor, shall we?", ["objectivesText"] = "Join the Council of Six in the Purple Parlor above the Violet Citadel. Progress: We should discuss this matter further in the Purple Parlor just above us.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44783] = { ["id"] = 44783, ["name"] = "From Bones They Rise", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44775 }, ["description"] = "Alright, the job is to get the broodmother under our control. But hear me out. A few more drakes would be a boon, right? While we're here, why don't we use our awesome power over undeath to raise some of her brood as well? Although the peak has claimed their corpses for the ice, I'm sure the embrace of undeath will be much more welcoming. We must find their frozen corpses and breathe your will into them.", ["objectivesText"] = "Revive 4 Deceased Thorignir in Thorim's Peak. Progress: Have you granted the drakes their unbirth?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44787] = { ["id"] = 44787, ["name"] = "The Bonemother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 647, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 46305 }, ["description"] = "It's time to call the mother, the true reason we came. She is strong, her sheer will and strength allowing her to face this peak in order to watch over the remains of her brood. While the Thorignir is a grand sight, I like my dragons a little more bony. She must die first. Remember the pyre where we met? She is its guardian, as the spirit was at the peak. If we light it, she will come.", ["objectivesText"] = "Light Thorim's Beacon at Thorim's Peak to raise Daumyr . Defeat her and raise her from death.", ["rewardGold"] = 169800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44790] = { ["id"] = 44790, ["name"] = "Trial by Demonfire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44830 }, ["description"] = "We are out of time. I have reports that a pitlord has come to Meredil. I have dispatched a strike force. We cannot let this demon flank our army here, nor can we let him find Shal'Aran. It is time to temper these recruits in a real battle. Join our forces in Meredil, engage the demon, and help us ensure this new army of ours is not lost in its first conflict.", ["objectivesText"] = "Slay Rozzeleth in Meredil.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143533, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 11, ["flags"] = 0 } } },
[44800] = { ["id"] = 44800, ["name"] = "Against Magatha's Will", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45652, 45706, 45724 }, ["description"] = "Well? What are you waiting for? Hand over the Doomstone.", ["objectivesText"] = "Talk to Magatha Grimtotem , then bring the Doomstone to Farseer Nobundo .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["db2QuestSortName"] = "Proving Grounds", ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44814] = { ["id"] = 44814, ["name"] = "Waning Refuge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["description"] = "We have done all we can here. Let us get everyone into the boat and get out while we still can. We have bought time for the others but nothing more.", ["objectivesText"] = "Leave Felsoul Advance on Deline 's Gondola.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115067, ["x"] = 0.248, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114948, ["x"] = 0.507333, ["y"] = 0.807333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44821] = { ["id"] = 44821, ["name"] = "In Dire Need", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44782, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "The ill tidings you bear only increase the concerns the Council has been having. I know you have your hands full with the Tomb of Sargeras. Make no mistake, the battle for the tomb remains our top priority--but we must not think the Legion foolish enough to rely on brute force alone. They are far more cunning than that. Please, hear us out.", ["objectivesText"] = "Hear out the Council of Six in the Purple Parlor.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44822] = { ["id"] = 44822, ["name"] = "Temporal Investigations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["description"] = "I knew the shal'dorei dabbled in time magic, but this is simply incredible... Elisande stopped time on our entire army! Come, let us investigate. Perhaps there is a way to break the spell - or at least discover how it is being maintained.", ["objectivesText"] = "Investigate Elisande's time spell with Khadgar.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115039, ["x"] = 0.525333, ["y"] = 0.692667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.692667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44827] = { ["id"] = 44827, ["name"] = "Citizens' Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44858, 44859, 44860, 44861, 44862 }, ["description"] = "I can barely get these civilians to stand in a straight line. They are untrained, undisciplined, and underarmed. Still, they need to be ready for the real battle. Khadgar suggested we try some field training at the ruins of Black Rook Hold in Val'sharah. The risen forces of Lord Ravencrest apparently remember how to fight. Go, hero, and I will send some trainees to support you.", ["objectivesText"] = "Defeat 20 of Ravencrest's forces at Black Rook Hold in Val'sharah.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44829] = { ["id"] = 44829, ["name"] = "We Need Weapons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "So many of the rebels want to help in the coming battle. Our people have the will, they lack only the means. They need weapons. From what Khadgar has told me, the fortress of Black Rook has plenty of munitions we could use. Travel to the fortress and place these beacons on some weapon caches there. Once placed, I can teleport them back.", ["objectivesText"] = "Recover 3 Weapon Caches at Black Rook Hold in Val'sharah. Progress: How goes the search?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605, 143744, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115342, ["x"] = 0.475333, ["y"] = 0.620667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115342, ["x"] = 0.475333, ["y"] = 0.620667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.620667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44831] = { ["id"] = 44831, ["name"] = "Taking a Promenade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "These people are foreign to us, despite our common heritage. They have changed much in the years they have been cloistered away. We need to learn more about them, what they are capable of. We dispatched one of our scouts to infiltrate the Promenade and assess the defenses. The blood elves did the same, although I doubt their ability to be discreet. Both are long past due for reporting back to us. Find them and make sure they are safe or at least did not die in vain.", ["objectivesText"] = "Locate the scouts in the Promenade.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114963, ["x"] = 0.4525, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114963, ["x"] = 0.4525, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.4525, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44832] = { ["id"] = 44832, ["name"] = "Scouting the Breach", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44833, 45209 }, ["description"] = "If Ly'leth's information is accurate, there is a breach in the Sanctum of Order that could be our only way into the Nighthold. No doubt they have magically sealed it - take Valtrois and protect her while she examines the seal. She is an exceptional talent, and I have total faith in her ability to break whatever enchantment they have cooked up. Valtrois has her own methods of getting into the city and will meet you inside the Sanctum of Order.", ["objectivesText"] = "Aid Valtrois underneath the Sanctum of Order in Suramar City.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115524, ["x"] = 0.433, ["y"] = 0.603 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44833] = { ["id"] = 44833, ["name"] = "The Seal's Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44832, 45209 }, ["description"] = "The Nightwell is so overloaded that they could not spare anything for this seal. Instead, they are borrowing power from the ley lines. I have traced one of their power sources to Kel'balor. We should head there immediately so I can determine how best to disable this barrier. Yes of course I said \"we.\" Surely you do not expect me to go without my bodyguard, do you? I shall meet you there!", ["objectivesText"] = "Investigate the ley line device at Kel'balor in the Crimson Thicket. Progress: Have you and Valtrois learned anything about the barrier?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143745, 237812, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115524, ["x"] = 0.433, ["y"] = 0.603 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.433, ["y"] = 0.603 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44842] = { ["id"] = 44842, ["name"] = "Shield, Meet Spell", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40632, 41607, 41916, 43812, 44834, 44842, 44845, 45263, 45316 }, ["series"] = { 44834 }, ["description"] = "There you have it, one arcane nullifier ! Using their weapon and magical signatures to cloak the spell, it should tear apart the shield as good as any spellbreaker would. Go teach that amateur spellslinger what it means to wage war against the sin'dorei!", ["objectivesText"] = "Use the Arcane Nullifier to defeat Arcshaper Thorendis . Progress: The nullifier should do most of the work for you. Just watch out for his offensive magic!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142260, 143486, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 12, ["flags"] = 0 } } },
[44843] = { ["id"] = 44843, ["name"] = "Crystal Clearing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "This portal is a problem. With it they can summon countless reserves. The crystals nearby seem to be powering the gate. If we destroy those, we can set them back significantly.", ["objectivesText"] = "Destroy 4 Portal Crystals .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44844] = { ["id"] = 44844, ["name"] = "Powering Down the Portal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 41916, 43810, 44831, 44834, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "Destroying the crystals will stop them temporarily, but it will be meaningless if we do not deal with the person controlling the portal itself. I heard their overseer, Ingra, shouting orders for more power so that she could bring the stronger Legion lieutenants through the gate. We must stop her to truly seal the portal for good.", ["objectivesText"] = "Slay Overseer Ingra .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143742, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115521, ["x"] = 0.405333, ["y"] = 0.644667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.644667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 10, ["flags"] = 0 } } },
[44845] = { ["id"] = 44845, ["name"] = "Break An Arm", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "The insurgents you marshaled gave me some bad news, <name>. The arcanists loyal to Elisande have reactivated the Arm of the Magistrix . The most powerful construct ever attempted, it raged out of control and decimated an entire district before it was disabled. Truly they must be desperate to turn it against us. The scouts have spotted it in the Crimson Thicket to the north. We cannot allow it to reach full power if we are to succeed.", ["objectivesText"] = "Defeat the Arm of the Magistrix . Progress: We must destroy the Arm!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143498, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114908, ["x"] = 0.408667, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.408667, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 13, ["flags"] = 0 } } },
[44849] = { ["id"] = 44849, ["name"] = "Recruitment Drive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 45834, 46173 }, ["description"] = "Helya's kvaldir have been raiding Azeroth's coasts for centuries, and many worthy vrykul who were destined to become my Valarjar were stolen. Now that their cursed queen is defeated, the souls held captive in Helheim can finally be freed to join us! Go to Helheim with Aerylia . I assure you she will bring you back safely.", ["objectivesText"] = "Ask Aerylia to escort you to Helheim.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44850] = { ["id"] = 44850, ["name"] = "Arming the Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["description"] = "The recent battles have greatly depleted our supplies, and we will need arms for our new Valarjar. The kvaldir have an abundance of weapons, armor, and other spoils from their raiding stockpiled in stolen crates. Confiscate whatever you can!", ["objectivesText"] = "Search stolen crates for 10 stolen blades and 10 stolen shields. Progress: Did you find any supplies we can use in Helheim <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142285, 142312, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44858] = { ["id"] = 44858, ["name"] = "Trolling Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44859, 44860, 44861, 44862 }, ["description"] = "My army is disciplined, and they will follow my order not to engage the Sin'dorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.", ["objectivesText"] = "Remove insulting items from the elven war camps. Progress: We elves are long lived, but not as long lived as our prejudices it would seem.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44859] = { ["id"] = 44859, ["name"] = "Liadrin's Command", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44860, 44861, 44862 }, ["description"] = "Shal'Aran is bursting at the seams with refugees and rebels. We practically have an army now but not enough weapons or mana to keep everyone armed and un-withered. And in all of this, Lady Liadrin has a battery of requests I simply do not have the time to deal with. Will you go to her? Her growing army is hard to miss in Meredil.", ["objectivesText"] = "Speak with Lady Liadrin in Meredil.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44860] = { ["id"] = 44860, ["name"] = "Trolling Them", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44861, 44862 }, ["description"] = "My army is disciplined, and they will follow my order not to engage the kaldorei in combat unless I give the command. However, it is with some level of shame that I must admit both armies have been attempting to harass the other with pranks, littering our respective camps with insults. Please, $p, we need someone both armies respect to collect these items before fighting breaks out.", ["objectivesText"] = "Remove insulting items from the elven war camps.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.452667, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44861] = { ["id"] = 44861, ["name"] = "Arming the Rebels", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44861, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44860, 44862 }, ["description"] = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals, but could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. I want those Nightfallen ready for battle when the time comes.", ["objectivesText"] = "Speak with Victoire in Meredil.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114838, ["x"] = 0.460667, ["y"] = 0.586 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.460667, ["y"] = 0.586 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44862] = { ["id"] = 44862, ["name"] = "Arming the Rebels", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["mapID"] = 680, ["storyline"] = { 44790, 44827, 44829, 44830, 44859, 44860, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44743, 44827, 44858, 44859, 44860, 44861 }, ["description"] = "The Nightfallen rebellion is growing in number, but they have not fought a real war in ages. Victoire and Silgryn are doing their best to train the new arrivals and could use an experienced hand. Go to them and show them some of the skills in battle you have picked up in your travels. We need those Nightfallen ready for battle when the time comes.", ["objectivesText"] = "Speak with Victoire in Meredil.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114841, ["x"] = 0.452667, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 116256, ["x"] = 0.398, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.452667, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8025 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44869] = { ["id"] = 44869, ["name"] = "Talon Terror", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "I just received word that the Shrine of Aviana is under attack by the Burning Legion! While the Druids of the Talon here are taking their time planning and strategizing their defense, our brothers and sisters are being slaughtered where they stand. I cannot stand idly by while my home shrine is in danger. Please, come with me to save my people.", ["objectivesText"] = "Use the portal in the Dreamway to meet Thisalee at the Shrine of Aviana in Mount Hyjal.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44870] = { ["id"] = 44870, ["name"] = "Mouths to Feed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44873 }, ["description"] = "We have rescued many refugees, as you can see. Unfortunately this has revealed a new problem. The arcan'dor fruit is our salvation, but it does not bear enough fruit right now to cure everyone. We must rely on mana a little longer to tide the refugees over. Valtrois thinks that she may have a solution. Please go speak with her and see what she plans to do.", ["objectivesText"] = "Speak with Arcanist Valtrois in Shal'Aran.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 12, ["flags"] = 0 } } },
[44873] = { ["id"] = 44873, ["name"] = "Oculeth Ex Machina", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44870 }, ["description"] = "I have a plan to feed Shal'Aran. Now that I am no longer starving for mana I have had time to study ley lines in new regions. I detected an eddy of mana in the ley lines of Azsuna. I have plenty of magic at my disposal, but we must visit the ley line in person in order to properly redirect the energy to Shal'Aran. Oculeth has graciously offered to teleport us there, but I could use an assistant. Care to join me?", ["objectivesText"] = "Speak with Oculeth and teleport to Azsuna.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 13, ["flags"] = 0 } } },
[44874] = { ["id"] = 44874, ["name"] = "Unbeleyvable", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44875 }, ["description"] = "Back to the task at hand! Take these ley line taps . We can use the resonant energies to properly redirect the flow, but they must be placed in precise locations. I will show you where. Your friend has agreed to... \"supervise\" us. Let us hope she just stays out of the way while the professionals take care of this.", ["objectivesText"] = "Assist Arcanist Valtrois with placing ley line taps . Progress: This ley line energy will not move itself. We must give it encouragement.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 14, ["flags"] = 0 } } },
[44875] = { ["id"] = 44875, ["name"] = "The Art of Flow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44874 }, ["description"] = "All done, <name>! We have but one more step and Shal'Aran will have all the mana it needs. Now that I have better access to the ley line below I can break the pool so that it will flow through properly. Given the chaotic state of this ley line it will require all of my concentration to redirect the energy. I must warn you that we will attract attention while I am doing this. You will need to protect me while I complete the process. Speak to me when you are ready.", ["objectivesText"] = "Protect Arcanist Valtrois while she completes the ritual. Progress: This ritual will shake the pool of energy loose, allowing it to flow through the ley line unimpeded.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143743, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115693, ["x"] = 0.6, ["y"] = 0.142 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.142 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 15, ["flags"] = 0 } } },
[44876] = { ["id"] = 44876, ["name"] = "A Dance With Dragons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "I must say I am impressed, <name>. You and your friend were able to fix a ley line, and you are not even dragons! You both seem exhausted by this ordeal. Allow me to help you get back home.", ["objectivesText"] = "Speak with Stellagosa to ride back to Shal'Aran.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115701, ["x"] = 0.596, ["y"] = 0.134667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.134667 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 16, ["flags"] = 0 } } },
[44877] = { ["id"] = 44877, ["name"] = "Attack on the Roost", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "Skylord Shadegrove has been leading the defense of the shrine, but I think he's starting to lose hope. Clearly he needs some more firepower behind him! Let's take out these demons and fend off the attack. They'll never see it coming!", ["objectivesText"] = "Kill 15 Legion invaders. Progress: I love the feeling of my knife in a demon's back!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44888] = { ["id"] = 44888, ["name"] = "Aviana's Grace", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "If this was only the distraction, where is the main force? Who else is under attack? We need to figure out who else is in danger! Aviana should know, she's got eyes everywhere. Let's go ask her. We should be able to contact her in the back room.", ["objectivesText"] = "Contact Aviana in the Shrine of Aviana .", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 115749, ["x"] = 0.442, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[44889] = { ["id"] = 44889, ["name"] = "Resource Management", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 45118, 45128, 45634 }, ["description"] = "Now that you possess Helya's Horn, the kvaldir are yours to command. We may as well put them to good use for a change. I've dispatched my Val'kyr, Danica, to the Broken Shore. She has identified a few Legion targets that should be eliminated. Aerylia will send you there when you are ready to leave.", ["objectivesText"] = "Talk to Aerylia to travel to the Path of Suffering on the Broken Shore.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44914] = { ["id"] = 44914, ["name"] = "Arms: The Thieving Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177 }, ["series"] = { 47032 }, ["description"] = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him. Fortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem. I'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to. Specialization: Arms Warrior", ["objectivesText"] = "Travel to Xylem's Tower within Bear's Head in Azshara.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44915] = { ["id"] = 44915, ["name"] = "Professionally Good Looking", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["description"] = "The archmage has recently locked himself away in his tower. If you wish to enter, you'll need help from some of his apprentices. I'm afraid you won't get it dressed like that. Xylem has a thing for... outfits, and his apprentices use them to show rank. If you wish his apprentices to help you, you'll need to appear their superior. Such is their desire to impress the archmage, many of his apprentices will battle each other for the best pieces. I think you know where this is going.", ["objectivesText"] = "Collect the Fanciful Hat , Well-Tailored Robes , and Magnificent Mantle from Raethas Dawnseer , Lobos and Phloem in Azshara. Progress: Feeling stylish?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142365, 142372, 142374, 237812 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44918] = { ["id"] = 44918, ["name"] = "A Message From Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44919, 45268, 45285 }, ["description"] = "<name>! The messages from Ly'leth we traced throughout the Terrace - we could not have known at the time, but somebody was watching. This crystal was delivered by a courier early this morning. <Pointing to the crystal by her side.> I am afraid the message contained within is not for the faint of heart. It has not been shown to anyone else, but you deserve to see it for all you have done for us.", ["objectivesText"] = "Listen to Andaris's Message in Shal'Aran. Progress: We have no time to waste.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44919] = { ["id"] = 44919, ["name"] = "A Challenge From Our Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44918, 45268, 45285 }, ["description"] = "Make no mistake. This message cannot be taken lightly. Any threat made against our people will be dealt with swiftly. We must travel to the estate at once to discover what has become of Ly'leth.", ["objectivesText"] = "Meet Andaris at the Lunastre Estate in Suramar City.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44920] = { ["id"] = 44920, ["name"] = "Order of Incantations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["series"] = { 44924 }, ["description"] = "The barrier shielding the tower can only be opened by activating the imbued gems in the correct order. The order is only known to Xylem and his inner circle of apprentices. No others have yet been able to decipher the code, and mistakes are met with deadly consequences. The aspiring apprentices spend a lot of their time around the tower. Some may have seen or heard something that might point to a solution. Let us hope, for your sake, their information proves valuable.", ["objectivesText"] = "Speak with Xylem's apprentices in Bear's Head to decipher the code to open the barrier to his tower.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44921] = { ["id"] = 44921, ["name"] = "Lone Wolf", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "My eyes and ears fly across Azeroth, bringing me back news of many things. My ally Goldrinn took to the barrows of Moonglade in mourning upon the death of Varian Wrynn. He has been untouched in the dream... until now. Demons have been seen invading the very same barrows, killing many more of our mortal druids in the process. You must go. Save Goldrinn, avenge our people! Take my hatchling Thisalee with you. Her tenacity and bloodlust is welcome in my clutch. You shall have my aid.", ["objectivesText"] = "Meet Thisalee Crow in Moonglade.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 146708, 237812 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115749, ["x"] = 0.442, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 80, 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44924] = { ["id"] = 44924, ["name"] = "The Archmage Accosted", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["series"] = { 44920 }, ["description"] = "With the barrier dispelled, Archmage Xylem is finally within reach! Hopefully he'll be cooperative in returning the Iris...", ["objectivesText"] = "Confront Archmage Xylem.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 116048, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44925] = { ["id"] = 44925, ["name"] = "Closing the Eye", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44925 }, ["description"] = "We have received reports from the apprentices at Xylem's Tower that they've been able to use the remant of Xylem's portal to pinpoint his location. We have orders from the Council of Six to open a portal directly to him, though whatever magic he's channeling on the other end is powerful enough to allow us to only keep it open for a brief window. The apprentice, Joanna asked I give you this message before you proceed. Speak to me when you're ready.", ["objectivesText"] = "Closing the Eye (Archmage Xylem) is a Mage Tower DPS Challenge, available during Legion Timewalking. The following specs can complete this challenge: Havoc Demon Hunters, Frost Death Knights, Arms Warriors, Survival Hunters, and Subtlety Rogues. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our Closing the Eye Mage Tower Strategy guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Speak with War Councilor Victoria to be teleported to Archmage Xylem 's location and defeat him.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 120257, 127848, 127849, 132366, 132376, 132444, 132452, 132458, 132466, 133572, 133576, 133976, 136975, 137014, 137021, 137038, 137052, 137060, 137061, 137064, 137069, 137077, 137087, 137090, 137101, 137107, 137459, 140587, 140796, 140797, 140806, 140808, 141446, 142117, 142406, 142502, 142508, 143728, 144236, 144259, 144279, 144361, 153023 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 117252, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 76, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[44928] = { ["id"] = 44928, ["name"] = "Something's Not Quite Right...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["description"] = "Something is troubling me, champion. Beyond these simple japes, the Kirin Tor has had to break up a few fights between the elves. I am worried something - or someone - might be influencing them. Your disguise was made by the nightborne, yes? It is not unreasonable to assume they can do something similar. Fortunately, Thalyssra has told me much about how the illusion works, and I believe this crystal can remove their disguise. Why don't you check the camps, just to be safe?", ["objectivesText"] = "Remove the disguise of 5 Nightborne Infiltrators. Progress: Were you able to find the instigators?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142375, 143499, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 114909, ["x"] = 0.409, ["y"] = 0.5235 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 5, ["flags"] = 0 } } },
[44955] = { ["id"] = 44955, ["name"] = "Visitor in Shal'Aran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["description"] = "Someone came to Shal'Aran while you were in the City. She asked for you specifically. I did not recognize her face, nor her voice, but she seemed trustworthy and earnest. She is just outside the cavern. Meet with her and determine her purpose for coming here.", ["objectivesText"] = "Meet the stranger outside Shal'Aran. Progress: What have you learned?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143738, 237812, 245558, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44964] = { ["id"] = 44964, ["name"] = "I'll Just Leave This Here", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["description"] = "Valtrois has a plan for the Sanctum's energy barrier. Several key Arcway locations throughout Suramar harness the power necessary for it. These Energy Disruptors she made will remotely break the links simultaneously on activation, causing the barrier to fall. Take these devices and install them at the leylines, then return here for the surprise assault on the Sanctum.", ["objectivesText"] = "Place Energy Disruptors at the energy sources in Teloth'aran, Kel'balor and Elor'shan in Suramar .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143540, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115372, ["x"] = 0.366, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45021] = { ["id"] = 45021, ["name"] = "Answers Unknown", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45024 }, ["description"] = "Have you noticed a change in Jubeka's demeanor? I know she's not the warmest of warlocks, but I fear she's been more withdrawn than usual. I imagine her mind lingers on Kanrethad, the council's one-time leader. Jubeka was steadfast in her commitment to keeping him banished, until the Burning Legion took her as their prisoner. His fate is unknown, and it's clearly troubling our friend. The last thing she said to me, was that she felt his presence in Azsuna. Don't let her travel this path alone.", ["objectivesText"] = "Find Jubeka Shadowbreaker within Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45024] = { ["id"] = 45024, ["name"] = "Cult Culling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45021 }, ["description"] = "The lure of Kanrethad is strong. Even when not in this world, there are those who wish to be near him at any cost, hoping to share in his power. A group of these fanatics are here in Faronaar, working tirelessly to bring Kanrethad back, I've learned as much from my prisoner. We cannot let them succeed, <name>. Find their compound and kill as many of them as you can. I will remain here and see what else I can learn about their intentions.", ["objectivesText"] = "Head into Felfire Cavern and kill members of the Cult of the Green Flame.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 97919, 137663, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45027] = { ["id"] = 45027, ["name"] = "To the Broken Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45026, 45794 }, ["description"] = "It would seem that Kanrethad's twisted followers have begun their ritual on the Broken Shore. We must act quickly. The Burning Legion cannot be allowed to use Kanrethad as their weapon. We have acolytes on standby, ready to perform a ritual of summoning on the Broken Shore when you're ready.", ["objectivesText"] = "Head to the Broken Shore.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292, 237812, 246812, 246814 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45028] = { ["id"] = 45028, ["name"] = "The Fate of Kanrethad", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["description"] = "I can feel his presence, Netherlord! Kanrethad is here! His followers have set up camp in the nearby pass, and are performing the ritual to bring him back as we speak. Quickly, take the fel crystals. Arrange them in a circle around Kanrethad. If placed correctly, the crystals should link together and begin to siphon the fel energy. Now go, before it's too late!", ["objectivesText"] = "Use the Fel Crystals to siphon fel energy from Kanrethad. Progress: We cannot allow the Burning Legion to take control of Kanrethad.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45062] = { ["id"] = 45062, ["name"] = "Resisting Arrest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 45063 }, ["description"] = "Your findings do not disappoint, <name>. Make your way to the soul engine and use our newly acquired weapons to dismantle the power source.", ["objectivesText"] = "Use the withered to dismantle the Power Source inside the Soul Engine at Felsoul Hold. Progress: There is much to be done.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 142400, 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45063] = { ["id"] = 45063, ["name"] = "The Felsoul Experiments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 45062 }, ["description"] = "Andaris's control over the withered poses a real threat. If we are to increase the withered's resistance against these effects, we must do so in an environment built from this very magic. Head for Felsoul Hold at once. When you arrive, I will send withered to aide in your efforts. It is of the utmost importance you do not leave until you are certain the experiments yield the appropriate results.", ["objectivesText"] = "Test the withered's resistance against fel magic at Felsoul Hold. Progress: Making progress I assume?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142399, 143488 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45064] = { ["id"] = 45064, ["name"] = "Felborne No More", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "The Felborne have begun to expand their grasp beyond the city's reach. A camp to the east in the Crimson Thicket is of a particular interest to us. Their outpost leader, Valthis Ama'ran , serves Andaris directly. Now is the time to put our withered training and Oculeth's device to the test. We cannot allow them to advance any further, <name>. Head for the camp and use the orb to sever the head of the beast. The time has come to begin our advance.", ["objectivesText"] = "Slay 8 Felborne and their leader, Valthis Ama'ran , at the Felborne Outpost in Crimson Thicket. Progress: Has the threat been removed?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142491, 143746, 237812, 246813, 246815, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45065] = { ["id"] = 45065, ["name"] = "Survey the City", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "Never a dull moment! Well... perhaps this is not entirely true. I'm afraid I must ask you once more to return to the city to gather information. But this is not just any information - this is information extraction! I require specific coordinates to allow me to focus my teleportations with extreme accuracy. It will, unfortunately, take a bit of time to dig through the information once retrieved, but no matter. We have plenty else to do in the meantime.", ["objectivesText"] = "Use the Advanced Telemancy Beacon to survey the Terrace of Order in Suramar City. Progress: Let's hope this is survey is our last. I grow quite tired watching you run around all day.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142405, 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45066] = { ["id"] = 45066, ["name"] = "Experimental Instability", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "In order to advance our studies I must ask you to recover a few particular items from my long-forgotten chambers. I assure you it is... mostly safe there, aside from a few unstable elements. Make your way to my workshop and locate the teleporter. I'll disable its cloaking device when you arrive.", ["objectivesText"] = "Gather the Telemancy Notes and 4 Discarded Orbs from Oculeth's Test Chamber. Progress: Scavenging going well? Not too dangerous I hope.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143538, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.4575 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45067] = { ["id"] = 45067, ["name"] = "Telemantic Expanse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["description"] = "Understanding fel magic alone may not be enough, <name>. Speak with Oculeth about diversifying our efforts. I hear he's got something... unique planned for us.", ["objectivesText"] = "Speak with Oculeth in Shal'Aran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115710, ["x"] = 0.3675, ["y"] = 0.4575 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45073] = { ["id"] = 45073, ["name"] = "Loot and Plunder!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45576, 45628, 45629, 45833, 45835, 45836, 45848, 46260, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "I'm bein' honest here matey, I've got me own motives fer bein' here. Last time there was a bit of a debacle. Some drinkin', some gamblin', and a bit too much rum if ye catch me meanin'. Some words were said, some fists were thrown and... honestly it was quite a haze. I'm not the most welcome pirate here after that. But they took me stuff! These lyin', dirty ol'... ahem. Could ye just take this torch and... burn their belongin's? I'd be grateful.", ["objectivesText"] = "Burn 8 Blacksail Booty .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 118125, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 118125, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45079] = { ["id"] = 45079, ["name"] = "The Village of Glenbrook", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 44785, 45079, 47289, 47428 }, ["description"] = "<The book is a register of the inhabitants of Glenbrook. All but a few of the names are crossed out.>", ["objectivesText"] = "Discover the fate of the Glenbrook villagers.", ["rewardGold"] = 303800, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 122493, ["x"] = 0.546, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5447, ["name"] = "A Tea Party", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45103] = { ["id"] = 45103, ["name"] = "We Ride!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "The time has come, Deathlord! Our scouts have marked a large amassing of demons not far from here. Lead us to victory, and show these demons the power of undeath!", ["objectivesText"] = "Lead the Four Horsemen in the battle against the Burning Legion.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 31451, 31452, 31453, 31454, 31455, 43873, 43875, 43877, 43896, 43897, 43898, 43899, 43904, 43937, 43939, 43940, 43948, 52919, 52964, 54465, 55962, 55963, 55964, 57518, 147457, 158228, 158238, 158239, 158240, 158241, 175161, 175162, 175163, 175164, 175165, 175166, 175167, 175168, 175169, 175170, 175171, 175172, 175173, 175174, 197607, 199826, 199827, 199828, 199829, 211279, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116128, ["x"] = 0.515333, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45111] = { ["id"] = 45111, ["name"] = "Everyone Loves a Good Fight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45111 }, ["description"] = "The note reads: \"You shouldn't have blabbed about the brawlers, especially to those champions. Now that you have though, I suppose it's ok that they fight here on occasion, but you better prove yourself a true brawler first!\"", ["objectivesText"] = "Compete in 5 Brawls. Progress: Compete in the Brawlers Guild to allow your champions to participate.", ["rewardItems"] = { 93195, 93228, 142319, 142522, 142553, 142554, 143561, 143590, 143899 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 49889, ["x"] = 0.556, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 142522 } },
[45118] = { ["id"] = 45118, ["name"] = "Helya's Horn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44889, 45128, 45634 }, ["description"] = "<name>, we need to bolster our army by any means necessary. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are eternally bound to obey Helya even through her death. If we can call them using her voice, they will follow us instead! We recovered Helya's Horn from her corpse. Empower it so you can call the kvaldir when we have need of them.", ["objectivesText"] = "Kill enemies in Helheim to empower Helya's Horn .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144071, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45123] = { ["id"] = 45123, ["name"] = "Elemental: The Folly of Levia Laurence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327 }, ["description"] = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Elemental Shaman", ["objectivesText"] = "Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45125] = { ["id"] = 45125, ["name"] = "Dabbling in the Demonic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45126 }, ["description"] = "Levia must have used these runes to aid her ritual. Even if she is as powerful as Modera says, she was a novice in demonic magic, so the runes must have helped stabilize the portal. I'll need you to find out what runes need to be activated to recreate her ritual. There are several books on runic magic in this room, which she no doubt studied for her ritual. Once you have activated the runes, I will complete the spell.", ["objectivesText"] = "Activate the correct three runes to help Rittsyn Flamescowl complete the spell to stabilize the portal. Progress: Quit fooling around and help me with this ritual!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45126] = { ["id"] = 45126, ["name"] = "Unlikely Seduction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45125 }, ["description"] = "Mo... Modera sent you? No... you must... leave! Agatha will be back any moment! Save... yourself...", ["objectivesText"] = "Defeat Agatha . Progress: Save... yourself...", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 10, ["flags"] = 0 } } },
[45127] = { ["id"] = 45127, ["name"] = "Fel-Crossed Lovers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["series"] = { 45861 }, ["description"] = "That vile imp mother! If I wasn't so weakened I would dive down that pool and give her a piece of my mind! <Levia takes a deep breath to regain her composure.> It's only a matter of time until Agatha can make use of the power she stole from me. We had best not be here when she does.", ["objectivesText"] = "Return to Archmage Modera in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 11, ["flags"] = 0 } } },
[45128] = { ["id"] = 45128, ["name"] = "A Glorious Reunion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 695, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44889, 45118, 45634 }, ["description"] = "You have done well, Battlelord <name>. Let us return to Skyhold. Odyn will want to hear of your success here.", ["objectivesText"] = "Speak to Aerylia , then report to Odyn .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45143] = { ["id"] = 45143, ["name"] = "Judgment Awaits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["description"] = "Our ongoing offensive within the Broken Shore has drawn the interest of many paladins who wish to fight under your leadership. Some are more worthy than others, but only you can be the judge of that. The new recruits are lingering in the camp just outside the chapel, awaiting your judgment.", ["objectivesText"] = "Use Highlord's Judgment to determine the worth of Silver Hand Recruits. Progress: Not all are worthy of joining the Silver Hand.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45146] = { ["id"] = 45146, ["name"] = "Runic Reading", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45147, 45148 }, ["description"] = "There is something curious about this scroll. It appears to be an empty page to the untrained eye, but I can see a shimmer of runes appear briefly when I hold it up to the light. As with most demonic runes, I will need fel blood to undo the magic that's been used to conceal whatever message is within this scroll.", ["objectivesText"] = "Collect 10 Fel Blood from demons throughout the Broken Isles. Progress: I will need to submerge the scroll in demon blood in order for the runes to reveal themselves.", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 137677, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45147] = { ["id"] = 45147, ["name"] = "Felstone Destruction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45146, 45148 }, ["description"] = "<Delas' mouth drops open as the scroll falls from her hands and onto the floor.> This cannot be... the runes... they detail a pact between the Burning Legion and my ancestors. A dark deal that would grant my ancestors protection from demons in this life, but in return, their spirits would belong to the Legion. This fel pendant is an embodiment of the pact, and cannot be removed once worn. Quickly, <name>. You must use your artifact to destroy that cursed piece of jewelry!", ["objectivesText"] = "Destroy the Felstone Pendant.", ["rewardGold"] = 144600, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45148] = { ["id"] = 45148, ["name"] = "Oath Breaker", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45146, 45147 }, ["description"] = "Many years ago I made a pact with a man I thought not to be unlike myself. His promise of protection seemed too good to be true, but it was a deal I was desperate to make. It wasn't until I had signed in blood that the dreadlord Zorak revealed himself. As long as he lives, my ancestors will remain bound to the Burning Legion, allowing our enemies to amass an army of unwilling soldiers. Head to the Broken Shore and slay Oathbinder Zorak . His death will break the hold he has over my ancestors.", ["objectivesText"] = "Head to the Broken Shore and slay Oathbinder Zorak .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 147469, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45149] = { ["id"] = 45149, ["name"] = "Ending the Crescent Curse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["description"] = "We must do whatever we can to break the curse that befalls my ancestors. The Burning Legion have set up camp within the ruins that house our dead, ready to make good on the dreadful pact that was drafted so long ago. Each of my ancestor's is burdened with a pendant that binds them to their demonic overlords. It cannot be removed, but as you have shown, with enough power it can be destroyed. End the curse that plagues my ancestors and set their spirits free!", ["objectivesText"] = "Free Felbound Spirits in Crescent Ruins by destroying their fel pendants. Progress: You are the only one powerful enough to destroy the fel pendants that bind my ancestor's spirits to the Legion.", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45162] = { ["id"] = 45162, ["name"] = "We Brought the Hammer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45162 }, ["description"] = "Your champions found success in the brawl against the Warhammer Council. Bring this \"token\" to the Brawler's Guild as proof.", ["objectivesText"] = "Go to the Brawler's Guild.", ["rewardItems"] = { 93195, 93228, 142522, 142553, 142554, 143561, 143590, 143899 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 49889, ["x"] = 0.556, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 142553 } },
[45163] = { ["id"] = 45163, ["name"] = "Cleaning Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45163 }, ["description"] = "Your champions return successful. They tell a grand tale of how they really cleaned up against Bill the Janitor.", ["objectivesText"] = "Return the Broken Broom Handle to the Brawler's Guild.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 37275, 37351, 37443, 37478, 81742, 81743, 81744, 81745, 81746, 81747, 81748, 81749, 81750, 93195, 93228, 119001, 142522, 142553, 142554, 143561, 143590, 143899, 155237, 160384, 160387, 160390, 160393, 211279, 237812 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 49889, ["x"] = 0.556, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["startItems"] = { 142554 } },
[45174] = { ["id"] = 45174, ["name"] = "The Hunt for Illidan Stormrage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45175, 45176 }, ["description"] = "Allari the Souleater , an oracle of the Illidari, has been on the hunt for Illidan's soul for quite some time. She now believes that she has discovered its location and requires your assistance in its recovery. Find Allari at Illidari Stand in Azsuna and aid her in any way possible. If Sargeras truly plans to use Illidan's body as a vessel for his own return then returning Illidan's soul to his body is integral in preventing the dark titan from returning to our world!", ["objectivesText"] = "Seek out Allari the Souleater at Illidari Stand in Azsuna.", ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45175] = { ["id"] = 45175, ["name"] = "Soul Prism of the Illidari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45174, 45176 }, ["description"] = "Alas, I will not burden you with the location of the master's soul just yet, <name>. First we must craft a soul prism powerful enough to hold the master's boundless chaotic energies. To do this I require lingering soul fragments from powerful beings found across this world. Bring me enough and I will craft a soul prism capable of holding the soul of the master - at least long enough to transfer into the naaru.", ["objectivesText"] = "Claim 5 Lingering Soul Fragments from the final bosses of Legion dungeons. Higher difficulty dungeons provide a greater chance and quantity of Lingering Soul Fragments.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139900, 139921, 139930, 139933, 139960, 139978, 140000, 140014, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45176] = { ["id"] = 45176, ["name"] = "Trial of Valor: The Once and Future Lord of Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["series"] = { 45174, 45175 }, ["description"] = "While tracking the master's physical body proved challenging, we were able to locate it in the Nighthold of Suramar. Our intelligence reports that Gul'dan is making final preparations to the Nightwell in order to use its power to usher the soul of Sargeras into Illidan's body. The only way to stop that from happening is to put Illidan's own immortal soul back. Take the Soul Prism of the Illidari and venture to Helheim. Defeat Helya and use the prism on Illidan's soul! Return it to Light's Heart .", ["objectivesText"] = "Defeat Helya in the Trials of Valor raid and then use the Soul Prism of the Illidari to claim Illidan's Soul.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 139904, 139928, 139941, 139958, 139964, 139988, 139996, 140021, 143661, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45177] = { ["id"] = 45177, ["name"] = "The Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45174, 45175, 45176, 45177 }, ["description"] = "Illidan's soul rests safely within Light's Heart . Take this vessel and deliver it to Khadgar with the following instructions: When Gul'dan attempts to tear the sky asunder and bring the dark titan into our world, call forth the power of this vessel and release Illidan's soul into his body. Go now, <name>. We do not have much time. The dark ritual will begin soon.", ["objectivesText"] = "Deliver Light's Heart to Khadgar at the Violet Citadel in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 770, ["rewardItems"] = { 140148, 140763, 141324, 141325, 141326, 143757, 237812, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 336, ["name"] = "The Hunt for Illidan Stormrage", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45188] = { ["id"] = 45188, ["name"] = "The Wisdom of the Council", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "I'm sorry, <name>, but I can't make heads nor tails of this. Riddles have never exactly been my strength. We should take this cultist's writings to the archmage. Perhaps he could shed some light on this.", ["objectivesText"] = "Bring the Nethersworn Manifesto to Archmage Karlain in the Violet Citadel in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 143496, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45190] = { ["id"] = 45190, ["name"] = "Where it's Thinnest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "Though I have never heard of this \"Nethersworn\" cult, what this manifesto speaks of can't be good. I do have a theory, however. The writing speaks of \"the place its skin is thinnest.\" I think they might be referring to the place where the veil between Azeroth and the Twisting Nether is weakest - the Tomb of Sargeras. With our forces having established a foothold at the Broken Shore, this would be an opportune time for Raest and his cultist allies to reach the tomb. I would suggest you stop them.", ["objectivesText"] = "Meet Karam Magespear at Felbreach Hollow in the Broken Shore.", ["rewardGold"] = 28090, ["rewardXP"] = 1535, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45192] = { ["id"] = 45192, ["name"] = "Runes of Rending", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "My brother and his cultists are engaged in some kind of ritual at the far end of the cave. I tried to intervene, but my brother has left magical wards to block the way. If you can find a way past them, we may be able to stop him in time!", ["objectivesText"] = "Bypass the wards in Felbreach Hollow and confront Raest Magespear. Progress: We must not hesitate!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139773, 140336, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45193] = { ["id"] = 45193, ["name"] = "One Step Behind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "It looks like Raest is out of our reach, but at least his cultists should prove less of a threat. We should return to the Kirin Tor. They should be able to help us plan our next move.", ["objectivesText"] = "Return to Khadgar in the Violet Citadel in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 10, ["flags"] = 0 } } },
[45207] = { ["id"] = 45207, ["name"] = "The Nightborne Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45437, 46335, 46338, 46705 }, ["description"] = "I would be happy to introduce you to my new apprentice if you do not mind traveling a bit. She is currently in the field keeping an eye on an enclave of Felborne resistance fighters who have sworn loyalty to the Legion. As the first nightborne to join the Tirisgarde, I am sure she is eager to prove her skills!", ["objectivesText"] = "Meet Arcanist Ryanna in the Crimson Thicket.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 121357, ["x"] = 0.558, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45209] = { ["id"] = 45209, ["name"] = "Those Scrying Eyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44832, 44833 }, ["description"] = "Until recently, Ly'leth was sending magical messages to us regularly from within the Nighthold. She took care to hide these messages - only the most vigilant scryers could have detected them. They could not be within the palace... too much interference from the Nightwell... Of course! The Terrace of Enlightenment! The Duskwatch must have set up a listening post there. Check the scrying orbs for traces of Ly'leth's messages. We must learn what she was trying to tell us!", ["objectivesText"] = "Inspect 4 Duskwatch Scrying Orbs in the Terrace of Enlightenment.", ["rewardGold"] = 208560, ["rewardXP"] = 6140, ["rewardItems"] = { 140030, 143536, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115506, ["x"] = 0.548, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45240] = { ["id"] = 45240, ["name"] = "Making Preparations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 647, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "Deathlord, we have uncovered an heirloom of great significance and power. Rimefang's harness has appeared in Icecrown Citadel. We must obtain it, rather than let it fall into the hands of others. I assume you'd like to retrieve the harness personally? We've sent one of our own, Minerva Ravensorrow , ahead to scout. You've met her before, yes? She has impressed us greatly, and we believe she can become quite powerful under your tutelage. I will open a death gate for you. It is best you meet her there.", ["objectivesText"] = "Take the Death Gate near Highlord Darion Mograine , then meet Minerva Ravensorrow .", ["rewardGold"] = 28090, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 647, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45243] = { ["id"] = 45243, ["name"] = "On Daumyr's Wings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "The time is nigh, $p. With these new dragons in our army, we are prepared for our assault on the Broken Shore. A large detachment of demons have appeared near one of our camps, and there are far too many of them for any of our allies to overcome. Who better to defeat these demons than those without fear of death? Those with quite the large secret weapon? Take Daumyr . We will meet you there.", ["objectivesText"] = "Ride Daumyr to the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116128, ["x"] = 0.515333, ["y"] = 0.216 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.515333, ["y"] = 0.216 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45251] = { ["id"] = 45251, ["name"] = "Redundancy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45614 }, ["description"] = "A construct progenitor? What a creative solution to our problem! We probably could channel Kathra'natir's power without releasing him now, but I want to add another layer of protection before we try, just in case. I will not have anyone accusing me of subterfuge! Meet me on the Broken Shore when you are ready.", ["objectivesText"] = "Meet Aethas on the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 11, ["flags"] = 0 } } },
[45260] = { ["id"] = 45260, ["name"] = "One Day at a Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38649, 38692, 38694, 38695, 38720, 42889, 44955, 45260 }, ["series"] = { 38649, 38695, 45271 }, ["description"] = "Thank you for coming, outlander. It is good to see you again. I have a situation in the city that needs your attention, but first... Let us talk of hope. <Thalyssra gestures toward the arcan'dor.> The fruit of the arcan'dor can truly free my people from the Nightwell. However, it only grows so fast. It will take time to distribute this cure. I think it only right that you help me pass out the fruit as it is ready. Please take this, and give it to anyone.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: In time, all of the shal'dorei will be free.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 285, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 285, ["name"] = "Lockdown", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45261] = { ["id"] = 45261, ["name"] = "Continuing the Cure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 }, ["series"] = { 45272 }, ["description"] = "Given the events at the Waning Crescent, the refugees here are more eager than ever to receive the gift of the arcan'dor and be free of the Nightwell forever. Fortunately, the tree has borne more fruit. Again, I ask that you honor us by giving this fruit to anyone here in Shal'Aran. When you are finished, we shall discuss further developments within the city. Silgryn reports that Arluelle has proven a fine student, and the two are making progress in evacuating citizens.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: No matter what crises come up, we must stay the course and free my people from their addiction. We take it one day at a time.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 286, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 286, ["name"] = "Missing Persons", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45262] = { ["id"] = 45262, ["name"] = "A Message From Ly'leth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["series"] = { 44742 }, ["description"] = "The arcan'dor bears fruit once again. Just in time, too - Ly'leth has sent us a message, and it seems she may have a lead on Vanthir. He is long overdue for this gift, assuming we manage to find him. Give a fruit to another citizen here in Shal'Aran while I finish decrypting Ly'leth's message.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143487, 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45263] = { ["id"] = 45263, ["name"] = "Eating Before the Meeting", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["series"] = { 45278 }, ["description"] = "Having Vanthir around has done much to lift the spirits of the people here. I dare say some have begun to relish their newfound freedom, even if they miss their beloved city. I will not rest until I can give it back to them. You and I have an important meeting to attend. Before we go, let us distribute more of the arcan'dor's fruit. I want people to know that although I must leave for now, I have not abandoned them.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45265] = { ["id"] = 45265, ["name"] = "Feeding the Rebellion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 45280 }, ["description"] = "More nightborne flee Suramar every day to join our cause. Our ranks are swelling, and with the aid of great heroes like yourself and the armies of the Horde and Alliance, our chances have never been better. Help me hand out more fruit of the arcan'dor - each one is a life free from slavish dependence on the Nightwell! Afterwards, we shall speak on how best to assist our new allies in their siege.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45266] = { ["id"] = 45266, ["name"] = "A United Front", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44738, 44739, 44740, 45266 }, ["series"] = { 44738, 44739, 44740, 45281 }, ["description"] = "Our rebel fighters have been armed and morale is high - even the Alliance and Horde elves have ceased their squabbling. We are nearly ready to march on the city. Hand out this week's fruit, and then we can begin preparations.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 262100, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 284, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 284, ["name"] = "March on Suramar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45267] = { ["id"] = 45267, ["name"] = "Before the Siege", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44736, 44822, 44832, 44833, 45209, 45267 }, ["series"] = { 44736, 45282 }, ["description"] = "So many years of my life spent studying within the Nighthold... Never had I considered that I would one day have to fight my way back in. Time is short. The battle will be upon us soon. Please, continue our tradition and feed another refugee the fruit of the arcan'dor .", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran.", ["rewardGold"] = 262100, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 279, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 279, ["name"] = "Elisande's Retort", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45268] = { ["id"] = 45268, ["name"] = "The Advisor and the Arcanist", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44918, 44919, 45062, 45063, 45064, 45065, 45066, 45067, 45268 }, ["series"] = { 44918, 44919, 45285 }, ["description"] = "This new First Arcanist appointed by Elisande. This... Andaris. If she is as dangerous as I have heard, then Ly'leth may well be lost. I am sorry, I should not entertain such thoughts. It is just that we have received a troubling message. Help me distribute the latest batch of the arcan'dor fruit, then we will discuss the message.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: Are you ready?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 288, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 288, ["name"] = "As Strong As Our Will", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45269] = { ["id"] = 45269, ["name"] = "A Taste of Freedom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44719, 44964, 45269 }, ["series"] = { 45287 }, ["description"] = "We are as ready as we will ever be. Once we put Valtrois' plan into action, we can attack the Sanctum of Order and put an end to Andaris. She will never expect us to have trained our withered against fel magic, and her hubris will be her downfall. Come, let us feed the people one last time.", ["objectivesText"] = "Feed the Fruit of the Arcan'dor to a Suramar Refugee in Shal'Aran. Progress: Even if our failure means their doom, they deserve a taste of freedom, no matter how fleeting.", ["rewardGold"] = 221280, ["rewardXP"] = 6140, ["rewardItems"] = { 143597, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 292, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 292, ["name"] = "Breaking the Nighthold", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45301] = { ["id"] = 45301, ["name"] = "Taking Charge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 719, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45330 }, ["description"] = "Mardum has been quiet for months. I wonder why the Legion is attacking us now? Could be in retaliation for destroying their battleship on the Broken Shore... We had better head down ourselves and save the day, don't you agree?", ["objectivesText"] = "Talk to Kyra Lightblade and choose to fly down to Mardum.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 719, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
