[45316] = { ["id"] = 45316, ["name"] = "Stabilizing Suramar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["description"] = "Elisande's plan has backfired. She thought to stamp out our rebellion by making an example of the Waning Crescent. Instead, she ignited the flame of the shal'dorei better than I ever could. We must maintain a cohesive campaign against Elisande and the Legion by fighting them in every corner of Suramar . Show the people that there is still hope - that there are still heroes willing to fight for them!", ["objectivesText"] = "Complete 10 world quests in Suramar . Progress: Now is the time for action!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45329] = { ["id"] = 45329, ["name"] = "Operation: Portals", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 719, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["description"] = "This is a serious invasion, but nothing a Slayer like you can't handle. Time to put those weapons to work!", ["objectivesText"] = "Close 3 Legion portals.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 719, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
