[45399] = { ["id"] = 45399, ["name"] = "Severing the Sveldrek", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8529, ["mapID"] = 823, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "So here's the order of things, as far as I've been told. Mortal walks into Icecrown. Mortal is brutally defeated. Mortal gets raised as Scourge. These fools can't expect to trounce in here, do whatever they want, and leave without any consequence. Time to make them truly as mindless as they act.", ["objectivesText"] = "Kill and raise 8 Sveldrek vrykul.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1692, ["db2PoiUiMapID"] = 823, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45404] = { ["id"] = 45404, ["name"] = "Panic at the Brewery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45459, 45574 }, ["description"] = "We were not prepared for a surprise attack. I fear Brewmaster Blanche has been captured, or worse... Please help me, Grandmaster!", ["objectivesText"] = "Help Almai find Brewmaster Blanche and defend Stormstout Brewery.", ["rewardXP"] = 7675, ["rewardItems"] = { 143731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45412] = { ["id"] = 45412, ["name"] = "Protection: Aid of the Illidari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863 }, ["series"] = { 45413, 45414, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city. Kor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks. I do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more. Specialization: Protection Warrior", ["objectivesText"] = "Find Kor'vas Bloodthorn in the streets of Dalaran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45413] = { ["id"] = 45413, ["name"] = "Gathering Information", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45414, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "The Legion has sent one demon after another to try to break into the Kirin Tor vaults in the city, but we don't know what they're after. Looks like they finally made it in. We need to find out what was taken, and quickly, before they get a chance to put whatever it is to use. Probe any survivors for information - I'll use my spectral sight to make sure there aren't still any straggling demons lurking about.", ["objectivesText"] = "Question citizens in the Bank of Dalaran to find out what was stolen. Progress: We can't risk another attack until we get to the bottom of this.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 30383, 30384, 30386, 30397, 237812 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45414] = { ["id"] = 45414, ["name"] = "Confirming Suspicions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45413, 45415, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "That heart is the last remaining piece of Highlord Kruul - once one of the Legion's best warlords. Many years ago Kruul's armies nearly descended upon the Dark Portal to crush the Azerothian assault on Outland. We Illidari intercepted before he could strike. I fear that the Legion aims to use the heart to hasten Kruul's resurrection in the nether. We must find the Prophet Velen at once - only he can tell us for sure.", ["objectivesText"] = "Find Prophet Velen in Dalaran. Progress: This is deeply concerning.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45415] = { ["id"] = 45415, ["name"] = "Between Worlds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["series"] = { 45412, 45413, 45414, 46314, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Kruul boasts damnation, but his power has not yet fully manifested. His minions have taken his heart to hasten his rebirth in the nether. We do not have much time. Go to the place of Kruul's fall at the Stair of Destiny in desolate Outland, where the link to his soul is strongest. There you must pry open the way to his realm. I must prepare for the battle to come. Good luck, champion.", ["objectivesText"] = "Establish a portal to the Twisting Nether at the Stair of Destiny in Outland. Progress: Lord Illidan led us into glorious battle against Kruul long ago. Now you must do the same.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 137677, 237812 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 100, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45416] = { ["id"] = 45416, ["name"] = "The Highlord's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45416 }, ["series"] = { 45905 }, ["description"] = "I have a missive for you from Kor'vas, as well as instructions for getting you there. I can teleport you to them to begin the fight, but you will need some Nethershards to force your way into the Twisting Nether. When you have enough, speak with me and you can begin.", ["objectivesText"] = "The Highlord's Return is the Mage Tower Tank Challenge, available during Legion Timewalking. The following specs can complete this challenge: Blood Death Knight, Vengeance Demon Hunter, Guardian Druid, Brewmaster Monk, Protection Paladin, and Protection Warrior. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our Mage Tower Tank Challenge Guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Defeat Highlord Kruul in the Twisting Nether. Speak with War Councilor Victoria to get there.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 109076, 120257, 127844, 127849, 132367, 132376, 132443, 132444, 132452, 133571, 133576, 133644, 137015, 137016, 137017, 137025, 137056, 137070, 137079, 137089, 137107, 137108, 137312, 137315, 137419, 138949, 139324, 140587, 140789, 140790, 140799, 142117, 142406, 142508, 147278, 151636, 151795, 151976, 152626 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45417] = { ["id"] = 45417, ["name"] = "The Nighthold: Lord of the Shadow Council", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45417 }, ["series"] = { 44719, 45420 }, ["description"] = "As we speak, Gul'dan is using the Nightwell's power to pull Sargeras into our world. Gather your companions and fight your way to the top of The Nighthold . I will prepare Light's Heart and join you when the time is right. Together, we will put an end to Gul'dan once and for all.", ["objectivesText"] = "Defeat Gul'dan in The Nighthold .", ["rewardItems"] = { 142436, 143757, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115367, ["x"] = 0.433, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.433, ["y"] = 0.607 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "raid" },
[45425] = { ["id"] = 45425, ["name"] = "Grovebound", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 46675, 46677 }, ["description"] = "Now THAT was some good stuff right there. Now that we've taken out the commander, the druids and the ancients should be safe for a while. Revenge was an added bonus. We should get back to Rensar and tell him what we accomplished.", ["objectivesText"] = "Return to Rensar Greathoof in the Dreamgrove.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 147461, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 13, ["flags"] = 0 } } },
[45426] = { ["id"] = 45426, ["name"] = "Nature's Advance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45498, 45528, 46674, 46924 }, ["description"] = "<name>, you must return to the Dreamgrove and bring the news of my attack. Tell the other druids that aggressions such as this will continue against us unless we find a way to stop the Legion. I thank you for the aid. I feel the fel energies leaving my veins, though it may take some time.", ["objectivesText"] = "Return to Rensar Greathoof in the Dreamgrove.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 115750, ["x"] = 0.687, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45437] = { ["id"] = 45437, ["name"] = "An Urgent Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 46335, 46338, 46705 }, ["description"] = "Archmage, <name>! We have an important guest. Please meet me in my chamber when you have a moment.", ["objectivesText"] = "Find Meryl's visitor in the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45440] = { ["id"] = 45440, ["name"] = "A Brewing Situation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "Greetings, Grandmaster. I'm an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. In fact, we have already begun production! That calls for a party, don't you think? We brought enough of my prized Celebration Brew for everyone!", ["objectivesText"] = "Direct the Stormstout Brewers to distribute Celebration Brew to the temple balcony, in front of the Laughing Crane, and near the troop training grounds. Progress: Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*", ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45442] = { ["id"] = 45442, ["name"] = "Not Felling Well", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 46320 }, ["description"] = "Let's see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. Yes, I think this will counteract the Legion's poison. It will probably taste terrible, but what medicine doesn't? Hurry, Grandmaster <name>. Our most stricken friends don't have much time left.", ["objectivesText"] = "Use Blanche's Still and then give the Curative Brew to 8 Fel-Poisoned Initiates. Progress: Did our Curative Brew work?", ["rewardXP"] = 6140, ["rewardItems"] = { 146401 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45449] = { ["id"] = 45449, ["name"] = "Alchemist Korlya", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "The zealots within the Garrison of the Fel are led by Alchemist Korlya . It seems likely that's the Felskorn Brewmaster Blanche observed poisoning our brew. Please kill her.", ["objectivesText"] = "Kill Alchemist Korlya .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45459] = { ["id"] = 45459, ["name"] = "Storming the Legion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45404, 45574 }, ["description"] = "I did my best to fight the demons off, but there were too many even for my skill... As I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. If you could acquire some of the poison, I'm sure we can concoct an antidote!", ["objectivesText"] = "Talk to Tak-tak to travel to the Broken Shore.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 2, ["flags"] = 1 } } },
[45482] = { ["id"] = 45482, ["name"] = "Arcane: Fate of the Tideskorn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340 }, ["series"] = { 47033, 47034 }, ["description"] = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Arcane Mage", ["objectivesText"] = "Search Jandvik for the vrykul mentioned in the scrolls.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 144457, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45486] = { ["id"] = 45486, ["name"] = "The Reluctant Queen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline. I don't know who you are, nor do I believe I'm part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you. Meet me in Valdisdall, <class>. From there we can make our way to Skold-Ashil and request an audience with Eyir . Perhaps she can shed some light on this prophecy.", ["objectivesText"] = "Bring Sigryn before Eyir in Skold-Ashil.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 640, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45498] = { ["id"] = 45498, ["name"] = "Let Sleeping Dogs Lie", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45528, 46674, 46924 }, ["description"] = "You see those big eredar guys? That's the barrow that Goldrinn is in! I don't know what the Legion is doing to him in there, but I'm sure we don't want them to succeed. Let's get in there and save Goldrinn !", ["objectivesText"] = "Save Goldrinn from the Stormrage Barrow Dens. Progress: Who knows what the Legion could be doing to Goldrinn !", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45522] = { ["id"] = 45522, ["name"] = "To Silence the Bonespeakers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Sigryn's claim to the throne will be challenged by two rivals - Runeseer Faljar of the Bonespeakers and Jarl Velbrand of the Drekirjar. I would begin in Haustvald with the Runeseer. He was a close ally of Skovald and is a powerful mystic. With the Bonespeakers at his charge, he would prove a staunch opponent if he cannot be made to yield. Go now, and claim your destiny in the name of the Valkyra!", ["objectivesText"] = "Defeat Runeseer Faljar in Haustvald.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 117199, ["x"] = 0.73, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45523] = { ["id"] = 45523, ["name"] = "To Tame the Drekirjar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "The Bonespeaker's words trouble me, outsider. The darkness he speaks of, Skovald's fel curse, could he have passed it onto me somehow? No, it cannot be so. The Runeseer must be mistaken... Come, the next challenger awaits. I will no doubt need your assistance bringing him to heel as well.", ["objectivesText"] = "Defeat Jarl Velbrand in Hrydshal.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 117227, ["x"] = 0.412, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45524] = { ["id"] = 45524, ["name"] = "The Forgotten Heir", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "My brother... lives? The last time I saw him, the assassins were closing in on him. I can't imagine how he defeated them... We should travel to Vrekt. I would look upon my brother with my own eyes.", ["objectivesText"] = "Find Torvald in Vrekt. Progress: Let us go to Vrekt.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 142487, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45525] = { ["id"] = 45525, ["name"] = "Unanswered Questions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "What is done, is done. There are none left to challenge the throne of the Tideskorn. My brother's words still haunt me, though. If Eyir knows who ordered my family killed, I deserve to know it. Come, let us return.", ["objectivesText"] = "Join Sigryn at the Vault of Eyir in Skold-Ashil.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 640, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45526] = { ["id"] = 45526, ["name"] = "The God-Queen's Fury", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45526 }, ["description"] = "<class>t, the Kirin Tor have found a way to get you into the Halls of Valor to pursue the God-King's heir. Archmage Khadgar has asked me to stress upon you the importance of stopping Sigryn , as the prophecies hint that she may still be the key to uniting the Tideskorn against the Legion. It will require an incredible amount of energy to teleport you directly to the Halls, so be sure that you are prepared. It may be some time before we can send you again. Speak to me when you are ready to proceed.", ["objectivesText"] = "The God-Queen's Fury (Sigryn) is a Mage Tower DPS Challenge available during Legion Timewalking. The following specs can complete this challenge: Arcane Mage, Retribution Paladin, Assassination Rogue, Enhancement Shaman, and Demonology Warlock. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our God-Queen's Fury Mage Tower Strategy guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Speak with War Councilor Victoria to be teleported to Sigryn 's location and defeat her.", ["rewardGold"] = 631800, ["rewardXP"] = 7675, ["rewardItems"] = { 25321, 120257, 127849, 132442, 132443, 132444, 132451, 132452, 132466, 133977, 136715, 137020, 137021, 137030, 137048, 137049, 137050, 137069, 137086, 137419, 140790, 140794, 140796, 140801, 140806, 140809, 140846, 142167, 144274, 146666 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 947, ["npcID"] = 116484, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 646, 947 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45528] = { ["id"] = 45528, ["name"] = "The Befouled Barrows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45498, 46674, 46924 }, ["description"] = "You were taking too long, so I took the liberty to scout out the barrows in advance. The Legion has set up portals, pulling more and more demons through them by the second. We need to shut them down so we can save Goldrinn! I'm not sure my usual methods are going to do much to take them down, but I think you can do it! I think some nice vine-work is in order.", ["objectivesText"] = "Close 3 Legion Portals in the Stormrage Barrow Dens. Progress: If we call up some vines to close the portals, then the Legion can't come through.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 80, ["npcID"] = 120032, ["x"] = 0.68, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45532] = { ["id"] = 45532, ["name"] = "Mother's Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "That big ugly thing looks like it's leading the attack here. Let's take her down!", ["objectivesText"] = "Kill Mother Mirenda .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 115802, ["x"] = 0.409, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 198, ["db2QuestSortName"] = "Engine of Innovation", ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45545] = { ["id"] = 45545, ["name"] = "Barrel Toss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "The Legion is defending the Felskorn lair with fel emitters. Fortunately we have Storm Brew to spare, so there should be plenty available with which to destroy them. Take this barrel, throw it at the spreaders, and watch them go BOOM!", ["objectivesText"] = "Use Storm Brew to destroy 5 Fel Brew Spreaders .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146308, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45551] = { ["id"] = 45551, ["name"] = "Devastating Effects", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "The Burning Legion will not rest until they have destroyed everything and everyone. Their presence here has had a devastating effect on our lands, and now it seems our wildlife as well. I have heard numerous reports of sickly animals in the thicket that surrounds the demon-infested city of Suramar. Make your way there and see if the rumors are true.", ["objectivesText"] = "Investigate Suramar.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 108455, ["x"] = 0.466571, ["y"] = 0.345143 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.466571, ["y"] = 0.345143 }, ["mapCandidates"] = { ["npc"] = { 680, 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45553] = { ["id"] = 45553, ["name"] = "The Nighthuntress Beckons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "< D'Bynn becomes alert at the sound of his master's voice. Using his muzzle, he nudges your hand with a sense of urgency, inviting you to hop on his back.>", ["objectivesText"] = "Ride D'Bynn and let him lead you to Nighthuntress Syrene's location.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.551333, ["y"] = 0.452667 }, ["mapCandidates"] = { ["npc"] = { 646, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45555] = { ["id"] = 45555, ["name"] = "Felbound Beasts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "So Reyln is taking orders from Lexera? Why am I not surprised. She seemed far too comfortable with the demons who infested our city. We cannot let her succeed in corrupting Suramar's wildlife. I swore to protect the city of Suramar from all enemies, even those within its walls. If you can deal with her trappers, I will do my best to track Nighthuntress Lexera down.", ["objectivesText"] = "Kill Nightborne Trappers and free Felbound beasts.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45556] = { ["id"] = 45556, ["name"] = "Ready to Strike", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["series"] = { 45557 }, ["description"] = "I followed one of the trappers, who unknowingly led me to the Broken Shore. Lexera was there, surrounded by an army of demons and loyal nightborne. I wasn't able to get close, but from what I could tell, she and her army of trappers are taming the fel-corrupted beasts. It is an abomination of nature, and she must be stopped! Meet me on the Broken Shore and be ready to strike. I will gather additional manaroot. I have a feeling we'll need it.", ["objectivesText"] = "Meet Nighthuntress Syrenne on the Broken Shore.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45557] = { ["id"] = 45557, ["name"] = "Unnatural Consequences", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["series"] = { 45556 }, ["description"] = "Lexera and her trappers have taken over the valley. She is stronger than she looks, <name>, and she fights with the strength of a dreadlord. Do not go in unprepared. I can handle these demons. Go, find Lexera, and make her feel the consequences of her unnatural endeavors.", ["objectivesText"] = "Kill Nighthuntress Lexera . Progress: Lexera and her trappers must be stopped.", ["rewardGold"] = 63800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45560] = { ["id"] = 45560, ["name"] = "Destruction: Rumblings Near Feltotem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842 }, ["series"] = { 45564, 45575, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Destruction Warlock", ["objectivesText"] = "Find Navarrogg at the Misty Coast in Highmountain.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45561] = { ["id"] = 45561, ["name"] = "Seek Me Out", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45561 }, ["description"] = "The letter from Maximillian is written on something which looks to be torn off a ship's sail. Included are directions to the beach in northern Highmountain .", ["objectivesText"] = "Look for Maximillian of Northshire in Highmountain . Progress: Look for Maximillian of Northshire in Highmountain .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 7083, 90313, 90314, 90315, 90316, 90317, 90318, 90319, 90320, 90321, 143900, 152668, 162372, 165785, 166245, 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 185954, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 190742, 190745, 190748, 190751, 211279, 224784, 229354, 237812, 239118, 244865, 248038, 248039, 248040, 248041 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["startItems"] = { 143900 } },
[45562] = { ["id"] = 45562, ["name"] = "Kneel and Be Squired!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45562 }, ["description"] = "You must kneel before me if we are to begin our journey together once more. Kneel, squire, and be squired!", ["objectivesText"] = "Kneel before Maximillian.", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45564] = { ["id"] = 45564, ["name"] = "The Burning Birds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45575, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Feltotem are experimenting on these falcosaurs! They didn't get the results that they wanted and have carelessly left their experiments lying around to further poison the animals. We should collect their leftover totems to prevent further corruption and to find out what they were doing.", ["objectivesText"] = "Collect Fel Infusing totems . Progress: These animals are unable to be infused with fel magic, but I doubt the Feltotem stopped here.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45565] = { ["id"] = 45565, ["name"] = "Further Training", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45565 }, ["description"] = "The journey here was perilous, Squire. It was fraught with danger. Storms, demons, storm demons... I shudder at the memory. Of course, I overcame all such dangers at great loss to my person. This is where I need your assistance. You must venture forth--nay, sally forth--and recover my armor, my weapon, and of course my grand steed. Once you have successfully completed these tasks three, will you be promoted to Squire, First Class!", ["objectivesText"] = "Complete Maximillian's quests and slay \"demons\" to earn the rank of Squire First Class.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45566] = { ["id"] = 45566, ["name"] = "A Knight's Belongings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45566 }, ["description"] = "Amidst the squalls and the crashing waves, my mighty ship swayed and tumbled. Lesser knights would have trembled in terror, frozen stiff. Not me! Nay! Heroically, I stripped my armor off my back and stored it safely in my sack. Why did I strip down to these simple undergarments, you ask? Only an ignorant squire would. I was wary of sinking to the bottom should my ship fall foul of course! Ha ha! Unfortunately, the sacks of armor were thrown overboard by the waves.", ["objectivesText"] = "Fetch Maximillian's armor. Progress: Fetch Maximillians armor.", ["rewardItems"] = { 143777, 143782, 143889, 143890, 143891 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45567] = { ["id"] = 45567, ["name"] = "My Kingdom for a Horse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45567 }, ["description"] = "Oh, woe is me! Soon after making landfall I began exploring, riding my trusty steed Pimento into the heart of a demon infested village to the north. While performing my investigations, I tied Pimento up to go further on foot, only to return and discover a powerful demon had captured her! There he was, riding her like she was his own. Please find her and send her back to me.", ["objectivesText"] = "Return Pimento .", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 118010, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45568] = { ["id"] = 45568, ["name"] = "They Stole Excaliberto!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45568 }, ["description"] = "I was scouting the nearby demon village when I was attacked. They took my artifact! Of course, if I leave here, the shore will be undefended. The nearby demons have it. Go, slay them and bring it back to me!", ["objectivesText"] = "Find Excaliberto and return it to Maximillian. Progress: Find Maximillians \"Artifact\" weapon, Excaliberto", ["rewardItems"] = { 143840 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117226, ["x"] = 0.558, ["y"] = 0.162 }, { ["mapID"] = 650, ["npcID"] = 117760, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45571] = { ["id"] = 45571, ["name"] = "A Bit of Espionage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45576, 45628, 45629, 45833, 45835, 45836, 45848, 46260, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "With the gunpowder in tow, it's time to move on to our next plan. Meet us on the Broken Shore. You can get a flight directly to our next location from Krasus' Landing. We will meet you there, <class>t.", ["objectivesText"] = "Speak to Aludane Whitecloud in Krasus' Landing for a flight to Broken Shore.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 10, ["flags"] = 0 } } },
[45573] = { ["id"] = 45573, ["name"] = "Rise Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["description"] = "Here we are, <class>t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it. There's no time to explain the plan in full right now, but Tess has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", ["objectivesText"] = "Kill 8 demons, then reach the top of the ramp.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 17900, 17905, 19019, 37971, 38014, 38057, 38118, 44998, 45022, 56652, 56653, 56654, 57281, 57282, 57283, 58927, 58928, 58929, 58930, 58931, 59607, 59608, 59609, 59610, 59666, 59667, 59668, 59669, 59670, 59671, 59672, 63237, 63238, 63239, 63240, 65912, 65938, 65962, 65986, 66012, 66021, 66030, 66039, 123975, 131298, 131713, 131714, 139506, 156934, 156936, 207105, 211279, 220128, 220129, 220131, 220132, 237812, 239135, 239136, 246936, 249400, 251329, 251821, 254267, 254579 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117262, ["x"] = 0.725, ["y"] = 0.427 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 11, ["flags"] = 0 } } },
[45574] = { ["id"] = 45574, ["name"] = "Fel Ingredients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45404, 45459 }, ["description"] = "Our scouts have located a Felskorn encampment within the Garrison of the Fel. We will need as many samples of fel poison as we can find if we are to concoct a cure for our stricken monks. Take samples of anything that looks remotely useful!", ["objectivesText"] = "Acquire 5 Vials of Liquid Felflame , 3 Flasks of Fel Blood , and 3 pinches of Demonic Ash . Progress: Did you find any samples we can use?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146310, 146311, 146312, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45575] = { ["id"] = 45575, ["name"] = "Village of the Corruptors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45587, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "The Feltotem continue to create these totems for further \"experiments\". Let us deal with these infusers in the traditional manner. Their deaths will right a great wrong and provide clues as to their ultimate goal.", ["objectivesText"] = "Kill Feltotem Infusers in Feltotem. Progress: These Feltotem need to be dealt with.", ["rewardGold"] = 1230, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45576] = { ["id"] = 45576, ["name"] = "Rise Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "Here we are, <class>t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it. There's no time to explain the plan in full right now, but Lilian has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", ["objectivesText"] = "Kill 8 demons, then reach the top of the ramp.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 17900, 17905, 19019, 37971, 38014, 38057, 38118, 44998, 45022, 56652, 56653, 56654, 57281, 57282, 57283, 58927, 58928, 58929, 58930, 58931, 59607, 59608, 59609, 59610, 59666, 59667, 59668, 59669, 59670, 59671, 59672, 63237, 63238, 63239, 63240, 65912, 65938, 65962, 65986, 66012, 66021, 66030, 66039, 123975, 131298, 131713, 131714, 139506, 156934, 156936, 207105, 211279, 220128, 220129, 220131, 220132, 237812, 239135, 239136, 246936, 249400, 251329, 251821, 254267, 254579 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117263, ["x"] = 0.725, ["y"] = 0.4265 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 12, ["flags"] = 0 } } },
[45586] = { ["id"] = 45586, ["name"] = "Shield Amplification", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 46000, 46290 }, ["description"] = "It will not hurt to reinforce the Nightborne Soulstone 's shield just a bit more, and to do that we must infuse it with energy. Ryanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin'dorei well know, desperate times call for desperate measures. It is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. Do what must be done.", ["objectivesText"] = "Use the Nightborne Soulstone on defeated Felborne within the Weeping Terrace.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143795, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 12, ["flags"] = 0 } } },
[45587] = { ["id"] = 45587, ["name"] = "The Feltotem Menace", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45726, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "If I had known Tugar was alive and behind this I would've alerted you sooner! He is a hateful creature, and an easy recruit to the Legion's cause. If he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let's go!", ["objectivesText"] = "Find and deal with Tugar Bloodtotem.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45614] = { ["id"] = 45614, ["name"] = "Lady Remor'za", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45251 }, ["description"] = "Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. Their leader, Lady Remor'za , and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. However, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!", ["objectivesText"] = "Kill Lady Remor'za .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117331, ["x"] = 0.451, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 13, ["flags"] = 0 } } },
[45615] = { ["id"] = 45615, ["name"] = "Finders Keepers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "Would you look at this place? It's a mess! Everywhere you look there's just pile after pile of arcane dust ! <Akazamzarak smiles broadly.> These poor saps don't realize what that stuff's worth! I tell ya what, if you help me summon up some brooms to collect this powdered gold, I'll split the profits with you 80/20.", ["objectivesText"] = "Sweep up 8 piles of Arcane Dust in the Hall of the Guardian. Progress: Say, how's that dust coming along?", ["rewardGold"] = 151900, ["rewardXP"] = 3070, ["rewardItems"] = { 147838, 178065, 178066, 178067, 178068, 178069, 178070, 178071, 178072, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45628] = { ["id"] = 45628, ["name"] = "This Time, Leave a Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45629, 46260 }, ["description"] = "Are you ready, <class>t? I will walk you through every step of the plan. You'll be perfectly safe! First thing's first: You see that rappel point behind me? That's your way down into the cave. Good luck!", ["objectivesText"] = "Rappel down into the cave, then follow Tess's instructions.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117262, ["x"] = 0.725, ["y"] = 0.427 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.427 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 13, ["flags"] = 0 } } },
[45629] = { ["id"] = 45629, ["name"] = "This Time, Leave a Trail", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["series"] = { 45628, 46260 }, ["description"] = "Here goes nothing, <class>t. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave. What? Don't make that face. I'll give you more instructions once you're in the cave.", ["objectivesText"] = "Rappel down into the cave, then follow Lilian's instructions.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117263, ["x"] = 0.725, ["y"] = 0.4265 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.4265 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 14, ["flags"] = 0 } } },
[45630] = { ["id"] = 45630, ["name"] = "Servant to No One", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "I like workin' with ya, <name>. How's about we keep this gold train a-rollin'? Archmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative? <Akazamzarak hands you a small crystal.> This bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up. Why not take it into town and try her out? See for yourself!", ["objectivesText"] = "Test Akazamzarak's Servants on 5 people in Dalaran. Progress: Good stuff, am I right?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45632] = { ["id"] = 45632, ["name"] = "Missing in Action: Eitrigg", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["series"] = { 45647 }, ["description"] = "Are you familiar with Eitrigg ? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby. Unfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him. Please try to find him!", ["objectivesText"] = "Find Eitrigg .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45633] = { ["id"] = 45633, ["name"] = "Operation Felrage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["description"] = "I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored. The naga warlord, Kaz'jatar, and his skrog toady, Felbeard , are responsible for the Felrage's attacks on our forces. We must teach them that it does not pay to consort with demons!", ["objectivesText"] = "Kill Warlord Kaz'jatar and Felbeard . Progress: Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 12, ["flags"] = 0 } } },
[45634] = { ["id"] = 45634, ["name"] = "Kvaldir on Call", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44889, 45118, 45128 }, ["description"] = "You empowered Helya's Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. Seek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!", ["objectivesText"] = "Blow Helya's Horn and direct the kvaldir to destroy the three Legion portals. Progress: Did the kvaldir answer your call, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45644] = { ["id"] = 45644, ["name"] = "Oh Doloria, My Sweet Doloria", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45644 }, ["description"] = "What ho! We are quite the dashing pair of adventurers, aren't we? Now that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria . Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky! It must be Dalaran . Quickly, squire! Mount up and meet me at Dalaran 's famous inn. Make haste!", ["objectivesText"] = "Seek out Doloria in the Legerdermain Lounge in Dalaran .", ["starts"] = { { ["mapID"] = 650, ["npcID"] = 118009, ["x"] = 0.558, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[45645] = { ["id"] = 45645, ["name"] = "A Fool's Errand", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45645 }, ["description"] = "Oh yea sure, I'm, um, held here against my, you know, will, or something. Look bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth. I've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom. Take your time, don't get hurt. Much.", ["objectivesText"] = "Kill \"Hill Bandits\" to find Doloria 's stolen \"Jewelry\" and buy her \"release\". Progress: Kill \"Hill Bandits\" to find Dolorias stolen \"Jewelry\" and buy her \"release\"", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 65929, 65954, 65978, 65999, 143845 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45647] = { ["id"] = 45647, ["name"] = "Mission: Search and Rescue", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45834, 45873, 46267 }, ["series"] = { 45632 }, ["description"] = "I will make these naga pay for their audacity. They and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor! We must rescue our fallen soldiers before they are sold as slaves, or worse...", ["objectivesText"] = "Rescue 8 squads of Captured Warriors . Progress: Have we found them all?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 10, ["flags"] = 0 } } },
