[45652] = { ["id"] = 45652, ["name"] = "A \"Humble\" Request", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 44800, 45706, 45724 }, ["description"] = "<class>t, we've received a... visitor. She orders entry, but the guards will not let her pass without approval. Please head up to the overlook as soon as you are able.", ["objectivesText"] = "Meet your visitor at Storm's Eye Overlook. Progress: Our \"guest\" is waiting for you. You may want to hurry.", ["rewardGold"] = 22130, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45706] = { ["id"] = 45706, ["name"] = "The Power of Thousands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 44800, 45652, 45724 }, ["description"] = "I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition. The Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.", ["objectivesText"] = "Take Magatha's portal and meet her in Thousand Needles.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45723] = { ["id"] = 45723, ["name"] = "The Crone's Wrath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.", ["objectivesText"] = "Defeat 15 demons on Darkcloud Pinnacle.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds", ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45725] = { ["id"] = 45725, ["name"] = "Breaking Chains", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.", ["objectivesText"] = "Free 8 Captured Grimtotem from Prison Cages.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds", ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45726] = { ["id"] = 45726, ["name"] = "The Tainted Marsh", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45587, 45796, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic! I will rework this fel totem to draw out the fel energies they infused in those spirits. Please, cure what spirits you can, perhaps it will even give them some peace. If you want, I can even send you there!", ["objectivesText"] = "Drain the fel energies from the spirits of the Blind Marshlands. Progress: I'm tired of these monsters abusing everything around them!", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 143778, 143863, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117249, ["x"] = 0.312, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45727] = { ["id"] = 45727, ["name"] = "Uniting the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43341, 45727 }, ["description"] = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", ["objectivesText"] = "Speak to Archmage Khadgar in Dalaran.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 140192, 141605, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 275, ["name"] = "7.0 World Quests", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45763] = { ["id"] = 45763, ["name"] = "Demonic Disruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45767, 45971 }, ["description"] = "While scouting on the Broken Shore, we have stumbled upon something quite unsettling. The Legion is attempting to harness the powers of Azeroth's elements. What is more, they are succeeding. We must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.", ["objectivesText"] = "Speak to Farseer Nobundo to go to the Broken Shore, then meet Therazane at the Garrison of the Fel.", ["rewardGold"] = 16980, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45764] = { ["id"] = 45764, ["name"] = "Restoring Equilibrium", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45385 }, ["description"] = "Kor'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that'ss even possible... It hass also begun listing to one side - rather comically, I might add. For some reason, Kor'vass doesn't find this nearly as entertaining as she should. Anyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss. Say the word and I will direct a squadron of illidari batriderss to accompany you. I'd come too, but...", ["objectivesText"] = "Obtain 3 Stabilizing Crystals . Progress: Have you secured the materialss for repairing the Fel Hammer, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143918, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45765] = { ["id"] = 45765, ["name"] = "Brothers and Sisters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["description"] = "Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.", ["objectivesText"] = "Heal 8 Injured Shaman in Garrison of the Fel. Progress: Rock may chip, but it does not bleed as flesh does.", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45769] = { ["id"] = 45769, ["name"] = "Conflagration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45883, 46258 }, ["description"] = "That fiend! Up on the hill, a demon who calls himself \"The Flameripper\" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his. He is extremely powerful, Farseer. You must take him down, whatever the cost!", ["objectivesText"] = "Kill Barastagax the Flameripper.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 115492, ["x"] = 0.545333, ["y"] = 0.524667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.545333, ["y"] = 0.524667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 11, ["flags"] = 0 } } },
[45770] = { ["id"] = 45770, ["name"] = "Stirring in the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 46069, 46070, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme. When it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use. Then it's just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare's mount, Shadowmane. Travel to the service gate of Stratholme when you're ready.", ["objectivesText"] = "Meetup with Lord Grayson Shadowbreaker in Stratholme. Once inside, locate the remains of Lord Rivendare and his mount and perform the ritual to claim it as your own. Progress: Your mount is within our reach, Highlord. I only pray Stratholme still has an ample supply of holy water.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 44177, 46109, 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768, 151623, 168056, 229348, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45771] = { ["id"] = 45771, ["name"] = "A Time for Everything", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["description"] = "Our order is recovering thanks to your quick actions, Grandmaster. There is just one more monk we need to attend to before it is too late!", ["objectivesText"] = "Give the Curative Brew to Iron-Body Ponshu .", ["rewardXP"] = 7675, ["rewardItems"] = { 146401, 147467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45788] = { ["id"] = 45788, ["name"] = "The Speaker Awaits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45788, 45789 }, ["description"] = "High Priest, we've received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself! What could he want from our order? You'd best head back to Netherlight, we'll hold down the front here.", ["objectivesText"] = "Speak with Betild Deepanvil in Netherlight Temple.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118536, ["x"] = 0.444667, ["y"] = 0.634667 }, { ["mapID"] = 646, ["npcID"] = 118537, ["x"] = 0.444667, ["y"] = 0.635333 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.444667, ["y"] = 0.634667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 789, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 789, ["name"] = "Class Mount: Priest", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45789] = { ["id"] = 45789, ["name"] = "The Sunken Vault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 702, ["storyline"] = { 45788, 45789 }, ["description"] = "'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth. The voice is telling 'im there's a lost Titan vault out there, near the Maelstrom. We dun know what's inside, but he's got tha feelin' it's got somethin' ta do with the Light, and you! Brann's got a vessel waitin' for ye, off the coast of Azsuna. Of course, I'll be accompanying ye as well, for cataloguing purposes. Can't go and let a chance like this go to waste!", ["objectivesText"] = "Take Brann's vessel in Azsuna to the Sunken Vault. Progress: Ta be one o' tha first to step foot in a lost Titan vault, it gives me tha chills!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 789, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 789, ["name"] = "Class Mount: Priest", ["orderIndex"] = 1, ["flags"] = 0 } } },
