[45794] = { ["id"] = 45794, ["name"] = "Informing the Council", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45026, 45027 }, ["description"] = "I'll deal with this prisoner, but you should head back to Dreadscar Rift. Let the others know what we've discovered. We will need their help dealing with Kanrethad on the Broken Shore.", ["objectivesText"] = "Return to Shinfel Blightsworn in Dreadscar Rift.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45796] = { ["id"] = 45796, ["name"] = "Destroying the Nest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["series"] = { 45560, 45564, 45575, 45587, 45726, 47018, 47019, 47020, 47031, 47035 }, ["description"] = "We have to put an end to Tugar's plot. These abominations must be destroyed, as well as their source! I think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place. Go there and stop their fel monster production at its source!", ["objectivesText"] = "Enter the Feltotem Caverns and ruin Tugar's plot. Progress: A tough fight to be sure, have you prevailed?", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 143778, 143863, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45798] = { ["id"] = 45798, ["name"] = "War'zuul the Provoker", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 46266 }, ["description"] = "There'ss some obnoxious demon lord up there who's been yelling for hourss. Would you please shut him up already? I'm getting a terrible headache!", ["objectivesText"] = "Kill War'zuul the Provoker .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45813] = { ["id"] = 45813, ["name"] = "Where Art Thou, My Sweet", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45813 }, ["description"] = "What poor fate! Here we are with the jewelry to buy my beloved's freedom, and she has disappeared! We must inquire of the patrons of this fine establishment. Perhaps they know what befell her.", ["objectivesText"] = "Help to maintain Doloria's \"illusion\" and ask around the Inn to see where Doloria disappeared to.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45833] = { ["id"] = 45833, ["name"] = "The Pirate's Bay", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 44758, 46322 }, ["description"] = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned. We've received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man's Bay in Azsuna.", ["objectivesText"] = "Meet up with Tess Greymane and Tethys at Dead Man's Bay in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45834] = { ["id"] = 45834, ["name"] = "Stolen Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 649, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["series"] = { 44849, 46173 }, ["description"] = "Odyn's worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen. Now, you can restore them to their rightful places. Destroy the soul fonts to release them!", ["objectivesText"] = "Free 15 stolen souls.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1463, ["db2PoiUiMapID"] = 649, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45835] = { ["id"] = 45835, ["name"] = "False Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["description"] = "As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time. Plant the orders in the marked locations. You should see the results rather quickly.", ["objectivesText"] = "Plant the False Orders in the marked locations.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 4, ["flags"] = 0 } } },
[45836] = { ["id"] = 45836, ["name"] = "Jorach's Calling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["description"] = "And with that, the first phase of the plan is complete. It's best we return to Jorach and bring him the news.", ["objectivesText"] = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119821, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[45841] = { ["id"] = 45841, ["name"] = "A Triumphant Report", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["description"] = "You should return to your Kirin Tor. I have no doubt they will want to hear the good news!", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 143778, 143863, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 117361, ["x"] = 0.314, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45842] = { ["id"] = 45842, ["name"] = "A Gift From the Six", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45560, 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018, 47019, 47020 }, ["description"] = "<name>, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war. Such a deed merits more than mere recognition. If you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", ["objectivesText"] = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel. Progress: Are you ready?", ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 10, ["flags"] = 0 } } },
[45843] = { ["id"] = 45843, ["name"] = "Dark Omens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45412, 45413, 45414, 45415, 45843, 45863, 46314, 47022, 47023, 47024, 47025 }, ["description"] = "We won't be able to defeat Kruul alone. Once the portal has stabilized I will send word so we can bring the Highlord to justice. In the meantime, you should inform the Kirin Tor of Vazuun's death - and Kruul's return.", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45844] = { ["id"] = 45844, ["name"] = "Avocation of Antonidas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "Archmage Kalec has requested your presence back in the Hall of the Guardian. He's discovered something he wishes to urgently speak with you about. Please see him at your earliest convenience.", ["objectivesText"] = "Speak with Archmage Kalec in the Hall of the Guardian.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117770, ["x"] = 0.452, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.618 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45845] = { ["id"] = 45845, ["name"] = "Burning Within", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core. However, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire. Perhaps you should speak with Khadgar and find out what became of the disc.", ["objectivesText"] = "Speak with Khadgar about the Tri-Disc of Fire . Follow his instructions after you speak with him. Progress: Was Khadgar able to remember what he did with the piece?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 143836, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 1, ["flags"] = 0 } } },
