[45883] = { ["id"] = 45883, ["name"] = "The Firelord's Offense", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45769, 46258 }, ["description"] = "Smolderon calls from across the battlefield, shaman. Now it is his realm being violated. It seems urgent. I will clean up here.", ["objectivesText"] = "Report to Firelord Smolderon in Cinder Run.", ["rewardGold"] = 20855, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 115492, ["x"] = 0.545333, ["y"] = 0.524667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 10, ["flags"] = 0 } } },
[45890] = { ["id"] = 45890, ["name"] = "Ancestors and Enemies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 641, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45145, 46259 }, ["description"] = "I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I'm beginning to doubt my worthiness. You see, I found my family's sigil among the demonic runes I've been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you'll be able to find what connection lies between my ancestors and my enemies. What's left of their village can be found in Val'sharah.", ["objectivesText"] = "Head to Delas' ancestral home in Val'sharah and recover relics from her past.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45916] = { ["id"] = 45916, ["name"] = "The Acolyte Imperiled", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "Truthfully, the Council knows little of Agatha, but she is more than just your average succubus. She has many allies within the sayaad, and is known to command armies of imps that swarm and overwhelm her foes. To seek her out is folly, but Ritssyn Flamescowl repays his debts. Come, let us examine what manner of fel powers this little mage of yours was stumbling her way through...", ["objectivesText"] = "Help Ritssyn investigate Levia's ritual. Progress: Keep these imps off me!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 7, ["flags"] = 0 } } },
[45917] = { ["id"] = 45917, ["name"] = "Following the Scent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "You will have to continue through the portal without me, <class>. I have assisted you in locating your mage's whereabouts, so I consider my debt to Modera paid. However, I will lend you one of my felhounds to help track this mage down. If she is as powerful as Modera says, then it would be in everyone's best interest that Agatha not be allowed to keep her. Best of luck, <class>, and try to bring Fhambar back in one piece.", ["objectivesText"] = "Follow Fhambar to Levia's location.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 116189, ["x"] = 0.256, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 9, ["flags"] = 0 } } },
[45971] = { ["id"] = 45971, ["name"] = "Infernal Phenomena", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45763, 45767 }, ["description"] = "Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will. How dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life. Sabotage their foolish rituals. Crush them! Show them Azeroth's true power!", ["objectivesText"] = "Interrupt 3 Infernal Rituals. Progress: The earth is my domain, NOT the Legion's!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46000] = { ["id"] = 46000, ["name"] = "Arming Dalaran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45586, 46290 }, ["description"] = "Kathra'natir is powerless to stop us from harnessing his energy within the Nightborne Soulstone. We have been lucky thus far - our allies have kept news of the sabotage from spreading. We should repair Dalaran's weapons array immediately while luck is still on our side. Oh - the weapon platform is a bit inaccessible. I trust you are not afflicted by a fear of heights? I will open a portal.", ["objectivesText"] = "Travel to the Dalaran Spire via Aethas' portal. Progress: Use the Control Crystal to activate the Soulstone!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 14, ["flags"] = 0 } } },
[46020] = { ["id"] = 46020, ["name"] = "Crystal Containment", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["description"] = "Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic. If any should break, the energy inside would find its way back to our friend. I shouldn't need to tell you how devastating it would be if that were to happen. I will gather the crystals and meet you back at Dreadscar Rift.", ["objectivesText"] = "Meet Jubeka Shadowbreaker in Dreadscar Rift.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 147477, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
