[46035] = { ["id"] = 46035, ["name"] = "End of the Risen Threat", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46035 }, ["series"] = { 45906 }, ["description"] = "Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you. I'm prepared to teleport you to his location, but there's a snag. In order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.", ["objectivesText"] = "End of the Risen Threat is the Mage Tower Healer Challenge, available during Legion Timewalking. The following specs can complete this challenge: Holy Priest, Holy Paladin, Restoration Shaman, Restoration Druid, Mistweaver Monk. Completing the challenge awards a recolor of the Tier 20 Mythic set. Our Mage Tower Healer Challenge Guide provides encounter tips, links to detailed spec-specific guides to beat the encounter, and gearing advice. Defeat Lord Erdris Thorn. Speak with War Councilor Victoria to be teleported to Jarod Shadowsong's location.", ["rewardGold"] = 929400, ["rewardXP"] = 9210, ["rewardItems"] = { 127847, 132444, 132450, 132452, 132466, 133571, 137026, 137072, 137086, 137095, 137105, 139322, 140030, 140587, 140803, 142117, 142170, 142406, 143732, 144258, 147007 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117871, ["x"] = 0.455, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
