[46060] = { ["id"] = 46060, ["name"] = "Salvation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help. Take this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.", ["objectivesText"] = "Use the Manaroot Salve on fel-infected animals.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132844, 132845, 132846, 132847, 132848, 132849, 132850, 132851, 132852, 132854, 211279, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46061] = { ["id"] = 46061, ["name"] = "Adopt a Tadpole", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 46061 }, ["description"] = "One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I'm not sure why this tradition persists, as it usually results in heavy damage to buildings and food stores. I usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.", ["objectivesText"] = "Select your favorite Winterfin tadpole and beckon it to follow you.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 144289, 144291 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 25197, ["x"] = 0.435, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 118571, ["x"] = 0.4308, ["y"] = 0.1328 }, { ["mapID"] = 114, ["npcID"] = 118575, ["x"] = 0.428, ["y"] = 0.128 }, { ["mapID"] = 114, ["npcID"] = 118577, ["x"] = 0.4315, ["y"] = 0.1335 }, { ["mapID"] = 114, ["npcID"] = 118578, ["x"] = 0.429667, ["y"] = 0.134333 }, { ["mapID"] = 114, ["npcID"] = 118579, ["x"] = 0.432, ["y"] = 0.128 }, { ["mapID"] = 114, ["npcID"] = 118580, ["x"] = 0.424, ["y"] = 0.132 }, { ["mapID"] = 114, ["npcID"] = 118582, ["x"] = 0.427333, ["y"] = 0.132667 }, { ["mapID"] = 114, ["npcID"] = 118583, ["x"] = 0.427, ["y"] = 0.133 }, { ["mapID"] = 114, ["npcID"] = 118584, ["x"] = 0.4316, ["y"] = 0.1336 }, { ["mapID"] = 114, ["npcID"] = 118586, ["x"] = 0.4324, ["y"] = 0.134 }, { ["mapID"] = 114, ["npcID"] = 118587, ["x"] = 0.4315, ["y"] = 0.134 }, { ["mapID"] = 114, ["npcID"] = 118589, ["x"] = 0.4328, ["y"] = 0.1344 }, { ["mapID"] = 114, ["npcID"] = 118590, ["x"] = 0.428, ["y"] = 0.134 }, { ["mapID"] = 114, ["npcID"] = 118591, ["x"] = 0.426667, ["y"] = 0.132667 }, { ["mapID"] = 114, ["npcID"] = 118592, ["x"] = 