[46069] = { ["id"] = 46069, ["name"] = "Worthy of the Title", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46070, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter. Please seek him out at Light's Hope Chapel in your order hall at your earliest convenience.", ["objectivesText"] = "Speak with Lord Grayson Shadowbreaker in your order hall.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136600, 136970, 143503, 143504, 143505, 144294, 147768, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118376, ["x"] = 0.438, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46070] = { ["id"] = 46070, ["name"] = "Preparations Underway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46071, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "As you may or may not recall, I once helped young paladins obtain their first armored mount. It was a tedious task that involved months of obtaining materials and sending them all over Azeroth. Thankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord. In order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", ["objectivesText"] = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker. Progress: How goes the search for the barding? Find anything suitable yet?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136600, 136970, 143503, 143504, 143505, 144294, 147768, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46071] = { ["id"] = 46071, ["name"] = "The Hammer of Dalaran", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46074, 46081, 46083, 91618, 94847 }, ["description"] = "Should we wish to make this barding worthy of the steed who will bear it, we'll need to upgrade it. Right now it's just good for not getting you kicked off your mount. Speak with Alard Schmied in Dalaran. He's a fine smith and will know how to modify this barding into something more befitting our needs.", ["objectivesText"] = "Speak with Alard Schmied in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46078] = { ["id"] = 46078, ["name"] = "Holy: The Bradensbrook Investigation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200 }, ["series"] = { 46079, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook! Is it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid. Specialization: Holy Priest", ["objectivesText"] = "Go to Bradensbrook in Val'sharah.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46079] = { ["id"] = 46079, ["name"] = "Aid on the Front Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us! We could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!", ["objectivesText"] = "Give aid to the wounded on the east, west, and south defense lines of Bradensbrook. Progress: We can't take anymore losses.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46080] = { ["id"] = 46080, ["name"] = "Quieting the Spirits", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46079, 46082, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "An overwhelming attack on Bradensbrook is imminent. Together I believe we can blunt the spear before it is cast. While we are dealing with the commanders, we should put down as many unquiet spirits as we can. With their leaders down and their numbers culled, that should give us time to find Erdris Thorn.", ["objectivesText"] = "Slay risen elves and spirits near Bradensbrook. Progress: I can see you've brought a lot of \"peace\" in your day, <class>.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46082] = { ["id"] = 46082, ["name"] = "Shadowsong's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46078, 46079, 46080, 47003, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "Well our lines are doing a lot better, thanks to you. A good thing too, because we need the rest! That being said, we noticed a big group of bigger, meaner risen coming from the farmstead. They would've given us a hard time, but that Shadowsong fellow has returned and killed them all. He's holding off reinforcements coming from the hold. I'm guessing he could use a hand. We can hold here until you and Shadowsong sort this out.", ["objectivesText"] = "Find Jarod Shadowsong outside Bradensbrook in Val'sharah.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118947, ["x"] = 0.39, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46089] = { ["id"] = 46089, ["name"] = "Hiding In Plain Sight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 46089, 46103 }, ["description"] = "Greetings, Shadowblade. I hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead. Yes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord. And there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", ["objectivesText"] = "Assassinate the infiltrating homunculi. Progress: Your blade is not yet bloody enough.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 63206, 139590, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 144259, 144296, 160251, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46103] = { ["id"] = 46103, ["name"] = "Dread Infiltrators", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46089, 46103, 46178 }, ["description"] = "Shadowblade, we have received a raven with most troubling news. One of our own, an ally that walked our very Hall of Shadows, is not who they seem. I believe Lilian has already begun dissecting their corpse. You'd best hurry.", ["objectivesText"] = "Speak with Lilian Voss in the Hall of Shadows.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 143490, 143491, 143492, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119259, ["x"] = 0.45, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46106] = { ["id"] = 46106, ["name"] = "Cutting off the Heads", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46107 }, ["description"] = "Erdris Thorn was a key commander of Ravencrest's forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat. We must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.", ["objectivesText"] = "Slay the risen squad leaders in Bradensbrook. Progress: It is difficult to bring peace to old friends.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118947, ["x"] = 0.39, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46107] = { ["id"] = 46107, ["name"] = "Source of the Corruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 46106 }, ["description"] = "There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling! The reinforcements are streaming out of Black Rook Hold from Heroes' Rest. We must make our way there and see if we can stop the source of these new troops.", ["objectivesText"] = "Find the source of the corruption at Heroes' Rest and end it. Progress: We must end this corruption.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 25913, 25914, 25915, 52595, 52621, 52633, 131282, 237812, 245616 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 9, ["flags"] = 0 } } },
