[46145] = { ["id"] = 46145, ["name"] = "Sterile Surroundings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion. Let's leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.", ["objectivesText"] = "Return to Netherlight Temple.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 147471, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46159] = { ["id"] = 46159, ["name"] = "An Urgent Message", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 720, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["description"] = "We received an urgent message from one of Belath's scouts down on Mardum! I think you had better listen to it.", ["objectivesText"] = "Activate the console to receive the message from Mardum. Progress: What do you think?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46173] = { ["id"] = 46173, ["name"] = "Tactical Planning", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["storyline"] = { 46173 }, ["series"] = { 44849, 45834 }, ["description"] = "Battlelord <name>! We should discuss our next moves!", ["objectivesText"] = "Meet with Odyn in Skyhold's Great Mead Hall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard" },
[46177] = { ["id"] = 46177, ["name"] = "A Portal Away", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 44914, 44915, 44920, 44924, 45865, 46177, 47043, 47046, 47047, 47048 }, ["description"] = "Xylem may have escaped, but a trace of his portal remains. Now that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him. Once I find something, I will alert the Kirin Tor. I only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him. Farewell, <name>.", ["objectivesText"] = "Return to Archmage Kalec in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 116048, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46178] = { ["id"] = 46178, ["name"] = "Hiding In Plain Sight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 46103, 46178 }, ["description"] = "Greetings, Shadowblade. I hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead. Yes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord. And there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", ["objectivesText"] = "Assassinate the infiltrating homunculi. Progress: Your blade is not yet bloody enough.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29571, 133636, 143490, 143491, 143492, 144259, 144357, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 792, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 792, ["name"] = "Class Mount: Rogue", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46200] = { ["id"] = 46200, ["name"] = "The Matter Resolved... For Now...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 }, ["series"] = { 45864 }, ["description"] = "You should return to the Kirin Tor. I have no doubt they will want to hear of our success. I will find Lord Erdris, and then I will contact you.", ["objectivesText"] = "Speak with Archmage Modera in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 10, ["flags"] = 0 } } },
[46207] = { ["id"] = 46207, ["name"] = "The Trial of Rage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 46207, 46208 }, ["description"] = "I wish to extend to you a prestigious invitation. Every year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial. Should you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end. Take what time you need to prepare yourself. Come back and speak with me when you're ready to begin.", ["objectivesText"] = "Speak with Odyn to begin the Trial of Rage scenario. Complete the scenario and claim your prize. Progress: I have no doubt that you will be victorious in this trial. I look forward to watching it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 127849, 133569, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 144396, 144397, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 303, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 303, ["name"] = "Class Mount: Warrior", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46208] = { ["id"] = 46208, ["name"] = "A Godly Invitation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46207, 46208 }, ["description"] = "Battlelord $p, Odyn has requested an audience with you back in Skyhold. Please meet with him at your earliest convenience.", ["objectivesText"] = "Speak with Odyn at your order hall in Skyhold.", ["rewardXP"] = 770, ["rewardItems"] = { 142232, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119527, ["x"] = 0.428667, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 303, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 303, ["name"] = "Class Mount: Warrior", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46235] = { ["id"] = 46235, ["name"] = "Secured Surroundings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "With Lexera defeated, her band of trappers will quickly disband. Those that refuse will meet my blade. These shores will be free of those who wish to corrupt Azeroth's wildlife. Our work here is done for now. Let us meet at Deliverance Point. There is more I wish to discuss in secured surroundings.", ["objectivesText"] = "Meet Nighthuntress Syrenne at Deliverance Point.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 147462, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119097, ["x"] = 0.508, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46237] = { ["id"] = 46237, ["name"] = "Bloodbringer's Missive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "Warlock! We have news from Dreadscar Rift. A message arrived by raven from Mor'zul Bloodbringer , with instructions that you meet him in Dreadscar Rift immediately!", ["objectivesText"] = "Speak with Mor'zul Bloodbringer in Dreadscar Rift. Progress: Will you not hear me out, <class>?", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 137663, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117622, ["x"] = 0.438, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46238] = { ["id"] = 46238, ["name"] = "If You Build It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground. I will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. Here's the list of what you'll need.", ["objectivesText"] = "Collect 5 Felslate , 3 Chaotic Spinel and an Unbending Potion . These can be gathered and crafted using profession skills or purchased on the Auction House. Progress: Have you the necessary materials?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 29784, 29785, 29786, 30398, 33226, 63227, 63228, 63229, 123919, 124124, 127845, 130175, 144328, 156937, 157009, 157010, 158611, 158612, 158613, 158614, 160189, 160190, 160191, 160192, 167649, 178061, 183830, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46241] = { ["id"] = 46241, ["name"] = "The Minions of Hel'nurath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 646, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["series"] = { 46242 }, ["description"] = "The dreadlord Hel'nurath gifts his lieutenants with calling stones to call and bind the dreadsteeds of Xoroth to their service. I believe one such stone will help us draw out the Wrathsteed. Some Xorothian cultists have been spotted helping the Legion's efforts on the Broken Shore. It would be safe to assume their leader has one of Hel'nurath's stones. Your succubus should be able to entice the truth out of the cultists. Find one who knows of their leader's whereabouts.", ["objectivesText"] = "Use your Succubus' Seduction to question Xorothian Cultists within the Dark Stockades in the Broken Shore.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46243] = { ["id"] = 46243, ["name"] = "The Wrathsteed of Xoroth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "The time has come and the preparations have been made. When you are ready, we will tear a hole into Xoroth, and force the Arax'ath and the Wrathsteed out of hiding. Follow me to the summoning platform. From there we will initiate the ritual. Prepare yourself, <name>. This will not be an easy undertaking.", ["objectivesText"] = "Complete the ritual on the Summoning Platform in Dreadscar Rift to enslave the Wrathsteed.", ["rewardGold"] = 309800, ["rewardXP"] = 7675, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46244] = { ["id"] = 46244, ["name"] = "Cathedral of Eternal Night: Altar of the Aegis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "Champion, we are ready to assault the Tomb of Sargeras. I studied the writings of Aegwynn, the Guardian who defeated the Dark Titan's avatar. She said that if her wards were compromised, a failsafe could be triggered by placing the Aegis of Aggramar upon an altar in the Cathedral of Eternal Night . You are the hero who acquired the Pillars of Creation, <name>. Gather your allies and enter the Cathedral. Be warned: Mephistroth will use all his power to stop you from placing the Aegis. You must prevail!", ["objectivesText"] = "Defeat Lord Mephistroth and place the Aegis of Aggramar upon the Altar of Eternal Night. Progress: There is little time. Mephistroth must be defeated, and the Cathedral of the Eternal Night secured.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 146925, 146926, 146927, 146928, 146929, 146930, 146931, 146932, 146933, 146934, 237812, 246812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46245] = { ["id"] = 46245, ["name"] = "Begin Construction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "We've got the supplies. Now someone needs to decide what to do with 'em. Hmm. Looks like it's your call, being the <class>t and all! Time to pick a building to focus on.", ["objectivesText"] = "Use the Construction Table to donate Legionfall War Supplies to the construction of the Mage Tower, Nether Disruptor, or Command Center. Progress: Oi! Which building should we work on? I've got deadlines to meet, mate!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 4, ["flags"] = 0 } } },
[46246] = { ["id"] = 46246, ["name"] = "Strike Them Down", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The Felstorm continues to rain demon scum upon these shores. Kil'jaeden believes his army infinite, his resources inexhaustible. We will show him how wrong he is. Cut a swath of retribution through their ranks, <class>t. Strike down demon after demon, until your weapons are bathed in their blood. And when they cry out for mercy, send them screaming back into the Nether.", ["objectivesText"] = "Slay 100 demons on the Broken Shore. Progress: Did they plead for their lives? Did they whimper as they bled away to nothingness?", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 16, ["flags"] = 0 } } },
[46247] = { ["id"] = 46247, ["name"] = "Defending Broken Isles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "In our zeal to reclaim the Broken Shore from the Legion, we cannot allow the rest of this land to fall into the demons' foul grip. Kil'jaeden has dispatched his forces across the Broken Isles, threatening the homelands of the allies you have made. You must answer their call in this hour of need. Turn back these demon assaults with haste, <class>t. The Armies of Legionfall will see that the Broken Shore remains secured.", ["objectivesText"] = "Defeat a Legion Assault in the Broken Isles.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46248] = { ["id"] = 46248, ["name"] = "Self-Fulfilling Prophecy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "In my life, I have witnessed many visions. Some filled me with hope... others, with despair. Victory over Kil'jaeden lies within our grasp. I have foreseen it. But visions only show us where our path might lead. They require effort to become reality. That effort falls upon your shoulders, <name>. You have done much, but more is needed. Fight on the battlefields of the Broken Shore and forge a destiny free from the Legion's grasp!", ["objectivesText"] = "Complete World Quests on the Broken Shore. Progress: How go your efforts on the warfront?", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 147842, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.633 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 11, ["flags"] = 0 } } },
[46249] = { ["id"] = 46249, ["name"] = "Championing Our Cause", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "Important work has been done by your order, <class>t. Your champions have succeeded time and again in undermining the Legion's invasion. As we make preparations for our assault on the Tomb of Sargeras, we need to keep the demons off balance. By pressuring them at every turn, we will expose vulnerabilities that can be exploited to our advantage. Send out your order's champions, <name>. Their missions are vital to the success of our campaign... especially as our confrontation with Kil'jaeden draws closer.", ["objectivesText"] = "Successfully complete a Legionfall mission at your Class Order Hall.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 124124, 146949, 146950, 147500, 147905, 153005 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 15, ["flags"] = 0 } } },
[46250] = { ["id"] = 46250, ["name"] = "Take Out the Head...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The Broken Shore swims with Legion filth, each demon deserving of a swift and merciless end. But some are more insidious than the rest. Powerful combatants rallying others to their perfidious cause. Strike down these demon champions and you will fill the hearts of their kin with fear and doubt. Break the Legion's spirit and we will break its back.", ["objectivesText"] = "Slay Rare Elite Demon Commanders on the Broken Shore. Progress: Are they dead yet?", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 147775, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 14, ["flags"] = 0 } } },
[46251] = { ["id"] = 46251, ["name"] = "Shard Times", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "As you have surely noticed, a slain demon leaves behind Nethershards , solidified residual energy from the Twisting Nether. I require a significant quantity of them for an experiment I'm conducting... $1oa shards, to be precise. Why are you looking at me like that? We've had this conversation before. I did the math. I need exactly $1oa shards. Fewer would be inadequate. More would be absurd. Don't question my methods. Go!", ["objectivesText"] = "Collect 2500 Nethershards on the Broken Shore. Progress: Do you have the shards? I hope you kept an accurate count. If you counted wrong, I simply can't be held responsible for the consequences.", ["rewardXP"] = 7675, ["rewardItems"] = { 69777 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46258] = { ["id"] = 46258, ["name"] = "The Calm After the Storm", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45769, 45883 }, ["description"] = "You have saved the elements from the Legion's control, and for that we thank you. However, it came at a great cost to both your health and your fellow shaman. Many came back to us wounded, dragged along by their fellow shaman. We have seen the havoc the Doomstone can wreak. It does not belong in the hands of any being, mortal or otherwise. While you were asleep, the elemental lords and I discussed its fate. Bring it to Neptulon . He will explain.", ["objectivesText"] = "Bring the Doomstone to Neptulon in the Maelstrom. Progress: We must watch over the Doomstone. Its power is too great.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 147475, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 12, ["flags"] = 0 } } },
[46259] = { ["id"] = 46259, ["name"] = "Darkbinder Dilemma", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45147, 45890, 46259 }, ["series"] = { 45145, 45890 }, ["description"] = "Ah, Delas sent you. I see. It's good she didn't come herself. It would break her heart to see what is happening to our family. A demon is defiling our dead in the ruins nearby. She's using her fel magic on our ancestors, turning them into mindless horrors that do the bidding of the Burning Legion. I can't deal with the harpies and this demon, but maybe you could help? Get rid of the darkbinder that torments our dead, and I will grant you access to whatever's left of the Moonfang family relics.", ["objectivesText"] = "Kill Darkbinder Elissath . Progress: Our dead will never know peace until Darkbinder Elissath is killed.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46260] = { ["id"] = 46260, ["name"] = "Meld Into the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44758, 45073, 45571, 45573, 45628, 45833, 45835, 45836, 45848, 46260 }, ["series"] = { 45628, 45629 }, ["description"] = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", ["objectivesText"] = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 147474, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 16, ["flags"] = 0 } } },
[46266] = { ["id"] = 46266, ["name"] = "Return of the Slayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["series"] = { 45798 }, ["description"] = "If you're anything like me, I'm sure you'd prefer to remain here on solid ground. Unfortunately, it is probably best to return to the Fel Hammer right away so Kor'vass can finish the repairss.", ["objectivesText"] = "Return to Kor'vas aboard the Fel Hammer.", ["rewardXP"] = 7675, ["rewardItems"] = { 147458 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 720, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46267] = { ["id"] = 46267, ["name"] = "Return of the Battlelord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44849, 44850, 44889, 45118, 45128, 45632, 45633, 45634, 45647, 45648, 45649, 45650, 45834, 45873, 45876, 46267 }, ["description"] = "Battlelord <name>, Odyn will want to hear the tale of your glorious victories here! I will assist you in returning to Skyhold when you are ready.", ["objectivesText"] = "Talk to Odyn in Skyhold.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147481, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116858, ["x"] = 0.698, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 286, ["title"] = "Warrior Order Hall", ["questLineID"] = 5808, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 5808, ["name"] = "Chronicles of Skyhold IV", ["orderIndex"] = 13, ["flags"] = 0 } } },
[46268] = { ["id"] = 46268, ["name"] = "A Found Memento", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["description"] = "<The trinket's fine brass exterior is inlaid with intricate filigree, though much of the detail has been battered by rocks and waves. Clearing away the grime and salt encrusting the clasp, you manage to open it. It is a compass--or was, at least. The glass face is shattered, the needle bent, unmoving. Set into the lid is a portrait. The paint is faded and waterlogged, but the subject is unmistakable: the face of a young Anduin Wrynn .>", ["objectivesText"] = "Bring the compass to King Anduin Wrynn in Stormwind Keep. Progress: Well met, <name>. What brings you to Stormwind this day?", ["rewardXP"] = 4605, ["rewardItems"] = { 146408, 147441, 147442, 147444 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 146407 } },
[46272] = { ["id"] = 46272, ["name"] = "Summons to the Keep", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46274, 46275, 46282 }, ["description"] = "Greetings, <name>. Your presence has been requested in the royal court. The crown has urgent need of you! Please return to Stormwind at your earliest convenience. King Greymane is anticipating your swift arrival.", ["objectivesText"] = "Meet with Genn Greymane at Stormwind Keep.", ["rewardGold"] = 210675, ["rewardXP"] = 4605, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120281, ["x"] = 0.415, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 119338, ["x"] = 0.8612, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 84, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46274] = { ["id"] = 46274, ["name"] = "Consoling the King", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46275, 46282 }, ["description"] = "Anduin hasn't been the same since you brought him his father's compass. He has become listless... distracted. We attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word. I ordered the guards to follow him, of course. He went to pray at the cathedral, where he's remained ever since. You brought this melancholy upon him! You must convince the boy to resume his duties. There's a war to be won!", ["objectivesText"] = "Look for King Anduin Wrynn inside Stormwind Cathedral.", ["rewardGold"] = 210675, ["rewardXP"] = 4605, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 119338, ["x"] = 0.8612, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 119357, ["x"] = 0.499, ["y"] = 0.453 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8612, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46275] = { ["id"] = 46275, ["name"] = "A Kingdom's Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46274, 46282 }, ["description"] = "My father was a legend. He oversaw the rebuilding of Stormwind, stood toe-to-toe with dragons, led the Alliance to numerous victories. Then, one day, he was just... gone. I wear his crown, I hold his title. But I've done nothing to earn them... or the faith of my people. I've spent the war sequestered in the keep, surrounded by guards and advisors. I need to walk the streets of Stormwind, to know whether it is hope or fear that beats in the hearts of my people. I welcome your company.", ["objectivesText"] = "Accompany King Anduin on his walk through Stormwind.", ["rewardXP"] = 6140, ["rewardItems"] = { 93168, 147442 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 119357, ["x"] = 0.499, ["y"] = 0.453 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 120268, ["x"] = 0.854, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.453 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46278] = { ["id"] = 46278, ["name"] = "Return to Sender", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 46278 }, ["description"] = "You've arrived just in time! Unlike the mail as of late, I'm afraid. We are severely understaffed, and demand is at an all-time high. We simply can't keep up! I'd love to chat, but I need help catching up before I can rest for even a moment. First thing's first. Several parcels of rejected mail have broken loose again; will you help me round them all up and return them to their senders?", ["objectivesText"] = "Return 9 Rejected Letters.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 134859, 156721, 156833 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[46282] = { ["id"] = 46282, ["name"] = "The King's Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["series"] = { 46272, 46274, 46275 }, ["description"] = "Now that I have seen the Broken Shore and the terror of the Burning Legion first hand, my eyes have been opened to the truth. I speak not of the unfathomable evil of the enemy, but of the bravery and sacrifice that such evil brings about in the hearts of our people. My father once told me that every king must carry the weight of his own crown. Mine has never felt heavier than it does at this very moment... Please take me to the place where my father died, so that I may honor his sacrifice.", ["objectivesText"] = "Accompany King Anduin to the Tomb of Sargeras.", ["rewardXP"] = 6140, ["rewardItems"] = { 147444 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 121237, ["x"] = 0.590333, ["y"] = 0.262333 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120288, ["x"] = 0.604, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.590333, ["y"] = 0.262333 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46286] = { ["id"] = 46286, ["name"] = "Legionfall Supplies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "If we don't build up some respectable fortifications, we'll lose our foothold on the Broken Shore. That ain't gonna happen on my watch, mate! We started construction on three key structures: the Mage Tower, the Nether Disruptor, and the Command Center. Each will play a key role in helping us pound the tar out of the Burning Legion. To make progress, we need Legionfall War Supplies... and I mean lots of 'em! You bring 'em to me, and I'll handle distribution. Got it?", ["objectivesText"] = "Complete World Quests or slay Rare Elites on the Broken Shore to earn Legionfall War Supplies. Progress: Crikey! Did you bring me Legionfall War Supplies?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46290] = { ["id"] = 46290, ["name"] = "Return of the Archmage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 45586, 46000 }, ["description"] = "With Dalaran protected once again, we can all breathe a little easier. It is time for us to return to the Hall of the Guardian. I'm sure Meryl is anxiously awaiting word of our success.", ["objectivesText"] = "Speak to Meryl in the Hall of the Guardian.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 147464, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 15, ["flags"] = 0 } } },
[46297] = { ["id"] = 46297, ["name"] = "Overwhelming Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "We will find no sanctuary on this world. Even now the full might of the Burning Legion rises to defend Argus. The siege camp below overflows with demon filth that stand between us and the weapon trained on the Vindicaar. They must be dealt with before it can fully charge, or Argus will be our grave.", ["objectivesText"] = "Kill 12 demons. Progress: Is the way to the weapon clear?", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 152690, 152691, 152692, 152693, 152694, 152695, 152696, 152697, 152715, 153421, 237812, 246815, 256763 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119535, ["x"] = 0.575, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 123148, ["x"] = 0.542, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46305] = { ["id"] = 46305, ["name"] = "Thorim's Flame", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["series"] = { 44787 }, ["description"] = "Not too long ago, the Drekirjar and the Thorignir respected each other. This only changed when Skovald came into power. An ancient Drekirjar spirit watches over this peak, which seems to be a sacred graveyard of some sort. He is the keeper of the ceremonial flame, which happens to be exactly what we need to call down the broodmother. Why don't we go convince him to let us take the flame? I'm sure he'll be nothing but... amiable.", ["objectivesText"] = "Convince the Drekirjar Shrine-Keeper to let you take Thorim's Flame. Progress: Although the spirit might stand unconvinced that raising the bodies of his deceased allies for our own bidding is necessary, we could always slaughter him to get our way. Seems normal for us.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46314] = { ["id"] = 46314, ["name"] = "Vengeance: Seeking Kor'vas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45413, 45414, 45415, 45843, 45863, 46314 }, ["series"] = { 45412, 45413, 45414, 45415, 47022, 47023, 47024, 47025, 47030 }, ["description"] = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city. One of your Illidari, Kor'vas Bloodthorn , has taken to patrolling the city streets on her own to find the source behind the recent attacks. I do not entirely trust your kind, but I will concede that you have at least proved adept at your namesake. I suggest you find Kor'vas and see what she has uncovered before the Legion strikes once more. Specialization: Vengeance Demon Hunter", ["objectivesText"] = "Find Kor'vas Bloodthorn in the streets of Dalaran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46316] = { ["id"] = 46316, ["name"] = "Champion: Kanrethad Ebonlocke", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46317] = { ["id"] = 46317, ["name"] = "Talon's Call", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The Legion is launching a renewed assault against the Shrine of Aviana in Hyjal! Thisalee Crow is organizing a counter-offensive, she requests your presence in the Dreamgrove at once. We will handle the offensive here. Good luck, Archdruid!", ["objectivesText"] = "Speak with Thisalee Crow in the Dreamgrove.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 140394, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118105, ["x"] = 0.438, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46318] = { ["id"] = 46318, ["name"] = "Defense of Aviana", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The situation is dire. The Legion is attacking the Shrine of Aviana in Hyjal, AGAIN! They must be after something specific, but I'm not sure what. Us Druids of the Talon are skilled scouts and infiltrators, but are lacking in... durability. They won't be able to hold out for long! We must go to help!", ["objectivesText"] = "Assist Thisalee in the defense of the Shrine of Aviana in Hyjal, then return to her in the Dreamgrove. Progress: What are you waiting for?! Get to the Shrine of Aviana in Hyjal!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 140394, 143638, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46320] = { ["id"] = 46320, ["name"] = "Hope For a Cure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45404, 45440, 45442, 45449, 45459, 45545, 45574, 45771, 45790, 46320 }, ["series"] = { 45442 }, ["description"] = "Hopefully you found enough fel poison samples with which to brew a cure. Let's meet back to the Temple of Five Dawns!", ["objectivesText"] = "Return to the Spirit of Brewmaster Blanche in the Temple of Five Dawns.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117305, ["x"] = 0.536, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 5881, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 5881, ["name"] = "Journey of the Grandmaster IV", ["orderIndex"] = 6, ["flags"] = 1 } } },
[46322] = { ["id"] = 46322, ["name"] = "The Pirate's Bay", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["series"] = { 44758, 45833 }, ["description"] = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned. We've received word of a large cave off the main island, where powerful demons meet to plot our downfall. One of our rogues, Lilian Voss , has formulated a plan with Tethys to take care of them, but they require your aid. They are waiting for you at Dead Man's Bay in Azsuna.", ["objectivesText"] = "Meet up with Lilian Voss and Tethys at Dead Man's Bay in Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 143679, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46323] = { ["id"] = 46323, ["name"] = "What's the Cache?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "Our goal is to retrieve a cache of gunpowder which has been infused with some sort of fel power. I don't know how the pirates here acquired it, but it is more dangerous than they know. I assure you that it will be more... effective in our hands. Master Gunner Prix should be toward the back of the cove, near the water. Take what we need from her.", ["objectivesText"] = "Kill Master Gunner Prix and obtain the Fel-Infused Gunpowder Cache . Progress: Did you get it?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142116, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46324] = { ["id"] = 46324, ["name"] = "False Orders", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "We must take some precautions. As soon as you assassinate the gunner, the crew will be looking for you. I had Tethys forge some orders in her handwriting that should buy us some time. Plant the orders in the marked locations. That will take care of the danger.", ["objectivesText"] = "Plant the False Orders in the marked locations.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46326] = { ["id"] = 46326, ["name"] = "Jorach's Calling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "And with that, the first phase of my machination is complete. Let's return to Jorach and tell him it is time to continue.", ["objectivesText"] = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", ["rewardGold"] = 63800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 119822, ["x"] = 0.576, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46327] = { ["id"] = 46327, ["name"] = "Bargaining with Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 629, ["storyline"] = { 45123, 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055, 47056, 47057, 47058, 47059 }, ["description"] = "From the clues you've been able to piece together, it appears that Levia was looking to conduct a ritual in the libraries beneath Dalaran - most likely to summon this \"Agatha\" she has become so infatuated with. I'm afraid this is a little out of my area of expertise, so I'm going to have to call in a favor. I'll send for assistance from the Council of the Black Harvest. One of their warlocks will meet you in the Chamber of the Guardian to assist with your investigation. I hope we're not too late.", ["objectivesText"] = "Meet Ritssyn Flamescowl in the Chamber of the Guardian beneath Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 629, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46333] = { ["id"] = 46333, ["name"] = "Livin' on the Ledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46333, 46334 }, ["description"] = "Slayer $p, Matron Mother Malevolence requests an audience with you back at the Fel Hammer. Please see her at your earliest convenience.", ["objectivesText"] = "Return to the Fel Hammer and speak with Matron Mother Malevolence .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118306, ["x"] = 0.43625, ["y"] = 0.61975 }, { ["mapID"] = 646, ["npcID"] = 118307, ["x"] = 0.4375, ["y"] = 0.622 }, { ["mapID"] = 646, ["npcID"] = 118314, ["x"] = 0.434571, ["y"] = 0.614286 }, { ["mapID"] = 646, ["npcID"] = 118316, ["x"] = 0.436857, ["y"] = 0.618 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.43625, ["y"] = 0.61975 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 787, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 787, ["name"] = "Class Mount: Demon Hunter", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46334] = { ["id"] = 46334, ["name"] = "To Fel and Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 46333, 46334 }, ["description"] = "Mardum has its fair share of secrets, one of which we found not too long after we took control of the Fel Hammer. It's a breeding ground of sorts, festering with fel bats. We've been capturing the pups and trying to train them up for our efforts against the Legion. But the other day, we caught an even greater prize, something worthy of your position, Slayer. Speak with Kyra and she'll provide you a ride to the ledge.", ["objectivesText"] = "Speak with Kyra Lightblade to secure a ride to Felwing Ledge. Then complete the Felwing Ledge scenario.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 147537, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 787, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 787, ["name"] = "Class Mount: Demon Hunter", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46335] = { ["id"] = 46335, ["name"] = "The Vault of the Tirisgarde", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 45437, 46338, 46705 }, ["description"] = "Dalaran's weapons are arcane in origin, but that doesn't mean we can't try something different. Our order's vaults contain a vast store of magical devices... Why don't you take a look around and see if there's anything we can use?", ["objectivesText"] = "Find 5 Ancient Artifacts within the Hall of the Guardian. Progress: Have you found anything promising?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146402, 146403, 146404, 146405, 146409, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46336] = { ["id"] = 46336, ["name"] = "A Golden Ticket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46336, 46337 }, ["description"] = "Huntmaster, we've gotten word from the Lodge that there is a letter wrought from golden light sitting on one of the tables, and it's got your name on it. No one is sure how it got there, and someone's wolf may have tried to open it and gotten a mouth full of singed fur. Seems like it's meant only for you. We'll hold down the fort here while you investigate.", ["objectivesText"] = "Read the Golden Letter in Trueshot Lodge.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 142226, 142228, 147580, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117810, ["x"] = 0.438, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 791, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 791, ["name"] = "Class Mount: Hunter", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46337] = { ["id"] = 46337, ["name"] = "Night of the Wilds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8641, ["mapID"] = 739, ["storyline"] = { 46336, 46337 }, ["description"] = "<The letter is written in a flowing, golden script. You can practically hear Odyn's booming voice speak the words as you read it.> The Night of the Wilds is upon us. Tonight, we will feast in honor of the beasts of legend, and they will rise once more in the Fields of the Eternal Hunt. One among us will set out into the fields to put their spirits to rest once more. My herald awaits you, hunter, if you will join us.", ["objectivesText"] = "Ask the Herald of Odyn to take you to the Fields of the Eternal Hunt.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142226, 142227, 142228, 142231, 142232, 143489, 143493, 143502, 143638, 147580, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8641 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 791, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 791, ["name"] = "Class Mount: Hunter", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46338] = { ["id"] = 46338, ["name"] = "A Creative Solution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 45437, 46335, 46705 }, ["description"] = "The Nightborne Soulstone may be our best hope if we can come up with a way to safely use it without Kathra'natir escaping. If he were to get loose in Dalaran... We should consult with our friend, Ari. She will know what modifications need to be done.", ["objectivesText"] = "Talk to Ari. Progress: Well? What did Ari think?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46339] = { ["id"] = 46339, ["name"] = "Keymaster Orlis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44768, 46345 }, ["description"] = "The Felborne insurgents appear to be guarding a teleporter pad within the glade ahead. I wonder where it leads? It is probably safe to assume that we'll need to kill Keymaster Orlis in order to gain access.", ["objectivesText"] = "Kill Keymaster Orlis and search his body. Progress: Did you find anything?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142241, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 121357, ["x"] = 0.558, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 121358, ["x"] = 0.545, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46340] = { ["id"] = 46340, ["name"] = "The Gates Are Closed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 627, ["storyline"] = { 45482, 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049, 47050, 47051, 47052 }, ["description"] = "Sigryn must be reached before she can confront Odyn, but our path is blocked. Odyn will close the Gates of Valor as soon as he becomes aware of Sigryn's assault. You will have to find another way into the Halls. I have no talent with portals, but your friends at the Kirin Tor seem to be very adept. Go now to them, and find a way through. I thank you for what you've done to help Sigryn this far, <class>. I only hope we can save her from herself.", ["objectivesText"] = "Return to Archmage Khadgar at the Violet Citadel in Dalaran.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 10, ["flags"] = 0 } } },
[46341] = { ["id"] = 46341, ["name"] = "The Tale of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46342, 46343, 46353 }, ["description"] = "Oh, hello, you must be the new Grandmaster. < Master Bu squints at you and sniffs.> You young ones have no patience these days, always running off to fight your great battles. No time for stories, even good ones, eh? Why don't you put your fists down for a moment and allow an old man to tell you a tale. Maybe buy an old man a drink while you are at it?", ["objectivesText"] = "Listen to Master Bu 's story.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46342] = { ["id"] = 46342, ["name"] = "Return to the Broken Peak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46341, 46343, 46353 }, ["description"] = "Of course, this is no mere story. Ban-Lu served as the personal mount of each of the previous Grandmasters, accompanying them through their travels as a faithful and trusted companion. But... he has not revealed himself since you have become Grandmaster. This is troubling. The last time he was seen was at the Peak of Serenity, after the fall of Grandmaster Hight. It is there that we must begin our search for him.", ["objectivesText"] = "Meet Master Bu at the Peak of Serenity.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 7902 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46343] = { ["id"] = 46343, ["name"] = "The Trail of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46341, 46342, 46353 }, ["description"] = "It seems a lifetime ago that Grandmaster Hight was walking these grounds. While Ban-Lu has served every previous Grandmaster, he and Hight were the greatest of friends. For many years they traveled the land, connecting with its people and maintaining our fragile peace. I cannot imagine how deeply Ban-Lu must have been affected by his passing. There must be some clues to his whereabouts around here. Look sharply.", ["objectivesText"] = "Follow the trail of Ban-Lu. Progress: Have you found any more clues, Grandmaster?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46345] = { ["id"] = 46345, ["name"] = "Into the Hornet's Nest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44768, 46339 }, ["description"] = "I hope you are up for an adventure. Shall we see where that teleporter goes?", ["objectivesText"] = "Use the teleporter pad.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 121358, ["x"] = 0.545, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 691, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46346] = { ["id"] = 46346, ["name"] = "The Shadow of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46347, 46348, 46349 }, ["description"] = "That was good of you to assist Smelly Mountaintop, Grandmaster, and we have learned more about the fate of Ban-lu. I won't bother you with escorting me to Shado-Pan Monastery. I can manage on my own. Meet me there and we'll continue our search.", ["objectivesText"] = "Meet Master Bu at the Shado-Pan Monastery.", ["rewardGold"] = 28900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46347] = { ["id"] = 46347, ["name"] = "Clean-up on Aisle Sha", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46348, 46349 }, ["description"] = "I've spoken with the Shado-pan and they are willing to give us information if we can assist them with a task of their own. Speak with Commander Shen-Li . While you're assisting them, I shall continue to meditate.", ["objectivesText"] = "Help Commander Shen-Li with the remaining Sha. Progress: Ooohhmmmm... Ooooohhhhmmmm...", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46348] = { ["id"] = 46348, ["name"] = "The River to Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46347, 46349 }, ["description"] = "We still do not know where Ban-Lu has gone to, but I do know who might. To the southeast lives a jinyu, Waterspeaker Ryuli . Perhaps he has seen Ban-Lu, or can ask him to inquire with the river about where Ban-Lu has been seen recently? All this travel has done a number on my old joints, Grandmaster. I shall rest here a bit longer, and then catch up with you later on.", ["objectivesText"] = "Meet with Waterspeaker Ryuli to the southeast.", ["rewardGold"] = 28900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120722, ["x"] = 0.421, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.421, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46349] = { ["id"] = 46349, ["name"] = "Lilies for Ryuli", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46346, 46347, 46348 }, ["description"] = "I have not seen Ban-Lu, but the waters will surely know where he is. There is a flower that grows in the lakes of the mountain slopes near the Temple of the White Tiger, that only blooms in the presence of someone pure of heart. Bring me six of these Moon Lilies and I shall use them to speak to the river.", ["objectivesText"] = "Collect 6 Moon Lilies for Waterspeaker Ryuli . Progress: How goes the Moon Lily collection, Grandmaster?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 147313, 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46350] = { ["id"] = 46350, ["name"] = "The Trial of Ban-Lu", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["description"] = "Ah, the ripples I feel in the water are strong! The droplet does not fall far from our location. Ban-Lu is quite close. <Ryuli closes his eyes and releases the lilies into the water. They drift slowly to the east.> He waits for you now, at the bottom of the waterfall to the east.", ["objectivesText"] = "Find Ban-Lu at the bottom of the waterfall.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147542, 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120726, ["x"] = 0.742, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46351] = { ["id"] = 46351, ["name"] = "Keep it Secret, Keep it Safe", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44770 }, ["description"] = "The shield generator you found is much more than it appears. I do not think my elders would approve of such advanced technology being shared with outlanders... And yet... We owe you our lives and our freedom. You may use it, with my blessing. Just... please be discreet about its existence, Archmage <name>.", ["objectivesText"] = "Return to Ari in the Hall of the Guardian.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 37383, 37434, 37512, 37559, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 10, ["flags"] = 0 } } },
[46353] = { ["id"] = 46353, ["name"] = "Master Who?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["series"] = { 46341, 46342, 46343 }, ["description"] = "Greetings. I've just received word that Master Bu has returned from a long spirit journey, and is currently resting his feet at Morning Breeze Village outside of the Temple of Five Dawns. It's been quite a long time since anyone has seen or heard from him, but he's asking to speak to you. We will handle the situation here while you are absent, Grandmaster.", ["objectivesText"] = "Meet Master Bu at Morning Breeze Village outside Temple of the Five Dawns.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 25589, 25591, 25592, 29787, 29788, 29789, 29791, 37270, 37353, 37441, 37479, 39323, 39331, 39374, 39375, 39429, 39451, 39461, 39480, 39503, 63216, 63217, 63218, 74035, 83078, 87333, 87334, 87335, 87336, 87337, 87338, 87339, 87340, 87341, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052, 89125, 89548, 89549, 89550, 89551, 89553, 89561, 89562, 89564, 89565, 89567, 89569, 89576, 89577, 89606, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707, 128861, 130222, 132269, 183399, 183856, 211279, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118214, ["x"] = 0.448, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46666] = { ["id"] = 46666, ["name"] = "The Motherlode", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "Pst... Come 'ere! I just got a tip about a cave on this island that is a treasure trove of loot! This could be my biggest score yet. Problem is, I uhh... sprained my ankle. Yeah, I would be right there with you battling those demons to get this treasure, but I shouldn't be putting any weight on this leg of mine. Shucks. How about you go check on this cave and report back to me. I'll mark your map where the cave entrance is. I've been told it's pretty hidden, so you've got to look around.", ["objectivesText"] = "Investigate the cave that Excavator Karla told you about. Progress: You find anything?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 29813, 29814, 29815, 142452, 143559, 146653, 146953, 146955, 146956, 146957, 146958, 147717, 147867, 147869, 147870, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46674] = { ["id"] = 46674, ["name"] = "The Preservation of Nature", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7846, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45498, 45528, 46924 }, ["description"] = "I fear this attack on Goldrinn is only the beginning, <name>. Whoever is ordering these attacks must be found and defeated. Wasn't Thisalee with you? She never returned... brash child. I assume she is already on the Broken Shore, trying to track down this commander. Please, find her. Do not let her take this on alone.", ["objectivesText"] = "Find Thisalee Crow near Deliverance Point on Broken Shore.", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46676] = { ["id"] = 46676, ["name"] = "Nature's Touch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["description"] = "Apparently we're not the only druids that have run into these demons. The Legion took a ton of captives and brought them back to their camp. Our brothers and sisters lay wounded and hurting... You can heal! Let's go save them!", ["objectivesText"] = "Heal 5 Injured Druids in Impsorrow Approach. Progress: We can't let the other druids suffer any longer!", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 11, ["flags"] = 0 } } },
[46677] = { ["id"] = 46677, ["name"] = "Prick of a Thistle", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45425, 46675 }, ["description"] = "Their commander's name is Katith'rax. He's the one who organized these attacks, and now the one who leads them. Luckily, it doesn't seem as though he's far off. Right off the coast is a small island. Seems as though he hides there, barking orders without getting his hands dirty. I, on the other hand, enjoy getting my hands a little dirty. Don't you?", ["objectivesText"] = "Kill Commander Katith'rax on Darkstone Isle. Progress: This guy is going to pay for what he's done!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 12, ["flags"] = 0 } } },
[46705] = { ["id"] = 46705, ["name"] = "Retaliation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44766, 44768, 44770, 45207, 45251, 45437, 45586, 45614, 46000, 46043, 46290, 46335, 46338, 46339, 46345, 46351, 46705 }, ["series"] = { 44766, 45207, 45437, 46335, 46338 }, ["description"] = "Of course I will help you! Although to be honest, I am not certain where a new arcane shield generator can be found these days. So many of our craftspeople have been executed... I will think on it. Would you mind helping me as well? I have been observing a nearby group of Felborne for some time. Their activities have become increasingly brazen of late. I think it's time to teach them how it feels to be violently suppressed.", ["objectivesText"] = "Kill 7 Felborne Insurgents.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 121357, ["x"] = 0.558, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 121358, ["x"] = 0.545, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 5871, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 681, ["questLines"] = { { ["id"] = 5871, ["name"] = "Rise of the Tirisgarde IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46719] = { ["id"] = 46719, ["name"] = "Amal'thazad's Message", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46719, 46720, 46812, 46813 }, ["description"] = "Deathlord, Amal'thazad has requested your presence at Acherus. He has been in contact with the Lich King, and making improvements on the citadel. For his benefit, or yours, I know not.", ["objectivesText"] = "Speak with Amal'thazad in Acherus.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117573, ["x"] = 0.44, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 351, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 351, ["name"] = "Class Mount: Death Knight", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46720] = { ["id"] = 46720, ["name"] = "Frozen Memories", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 648, ["storyline"] = { 46719, 46720, 46812, 46813 }, ["description"] = "Close your eyes, Deathlord. Can't you feel his presence already? <The Lich King's icy presence is inside your mind in an instant.> Stand in the rune circle atop Acherus, Deathlord. I will show you what I have seen. <The presence fades.>", ["objectivesText"] = "Take the portal to the top of Acherus, listen to the Lich King's plan, then witness his vision in Icecrown.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 351, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 351, ["name"] = "Class Mount: Death Knight", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46722] = { ["id"] = 46722, ["name"] = "Nothing Up My Sleeve", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "Now, you may think that a sack of gold would be a good reward for your troubles, but I've got something better in mind for you. I'm gonna teach you my best trick! I know, I know, I'm a very generous goblin. Let me show you how it's done!", ["objectivesText"] = "Use Akazamzarak's Hat to perform a magic trick. Progress: You gonna do the trick or not?", ["rewardGold"] = 16980, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46723] = { ["id"] = 46723, ["name"] = "Down the Rabbit Hole", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 734, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "Alright, bub. I'm gonna need you to go in there and find out what's going wrong. I'd go in myself, but... well, it's complicated. Anyway, we got no time to lose! Just jump in the hat and find out what's goin on. I'll be ready to pull you out once you've got everything handled.", ["objectivesText"] = "Enter Akazamzarak's Hat and find out what's happening to his rabbits. Progress: Don't just stand there, get in the hat and help the poor bunnies!", ["rewardGold"] = 120510, ["rewardXP"] = 3070, ["rewardItems"] = { 147838, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 734, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46724] = { ["id"] = 46724, ["name"] = "Champion: The Great Akazamzarak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 735, ["storyline"] = { 45615, 45630, 46722, 46723, 46724 }, ["description"] = "You know, you're a useful <fella/dame> to have around, <name>. Tell ya what, I think I'll accompany you on your adventures. Seems to be good gold in it, and I think it'll be a good way to scout out some new business opportunities around the Broken Isles. What do you say?", ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 314, ["name"] = "Champion: Akazamzarak", ["orderIndex"] = 4, ["flags"] = 0 } } },
[46725] = { ["id"] = 46725, ["name"] = "Power Outage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45301, 45329, 45330, 45339, 45385, 45391, 45764, 45798, 46159, 46266, 46725 }, ["description"] = "Kor'vass asked for a bunch of other stuff, but it won't hurt her to learn a bit of patience. Don't you agree? She did mentioned that the ship'ss weaponss array is severely damaged and dangerously low on power. Knowing her, I'm sure that'ss an exaggeration. I suppose you may as well take this power core I confiscated. You can replenish it from those disgusting Legion geyserss and energy globess floating around the Tomb.", ["objectivesText"] = "Refill the Fel Hammer's Power Core with fel energy.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 95416, 146797, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117709, ["x"] = 0.52, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 301, ["title"] = "Demon Hunter Order Hall", ["questLineID"] = 5891, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5891, ["name"] = "Destiny of the Illidari IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46730] = { ["id"] = 46730, ["name"] = "Armies of Legionfall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["series"] = { 46734 }, ["description"] = "Thanks to your leadership, the <class> order has grown even mightier than I had dared hope. Alongside champions of the other orders, we now have a fighting force capable of driving the Burning Legion from our world. It's time to end this invasion! Using the Pillars of Creation, we will dissipate the Felstorm and seal the Tomb of Sargeras.", ["objectivesText"] = "Escort Archmage Khadgar at Krasus' Landing in Dalaran.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 146796, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46732] = { ["id"] = 46732, ["name"] = "The Prophet's Gambit", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "I can feel their presence just ahead. It is as faint as the lightest breeze that once rolled across these hills, but it is not of the Legion, of that I am certain. We must see if these broken are potential allies. It is a great risk, but our numbers are too few to ignore the chance.", ["objectivesText"] = "Follow Prophet Velen .", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121345, ["x"] = 0.578, ["y"] = 0.680667 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121345, ["x"] = 0.578, ["y"] = 0.680667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.680667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46734] = { ["id"] = 46734, ["name"] = "Assault on Broken Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["series"] = { 46730 }, ["description"] = "It has been a long and costly war, <name>. It is time we put an end to it. We will drive the Burning Legion from their seat of power and close their gateway into Azeroth. Our first step is to gain a foothold on the Broken Shore. Divided, the Alliance and Horde faced defeat. But united as the Armies of Legionfall, we will claim victory!", ["objectivesText"] = "Complete the Assault on Broken Shore scenario.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812, 246812, 246814 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46765] = { ["id"] = 46765, ["name"] = "The Broken Shore: Investigating the Legion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 47000 }, ["description"] = "While we focus efforts on the Broken Shore, we must be careful to guard against other threats. We have been getting disturbing reports on the Legion starting or supporting indirect threats to Azeroth. While you are on the Broken Shore, please keep an eye out for strange objects or intelligence that could give us a clue as to what and where these threats are. I know it is not a lot to go on, we will do our best from here as well.", ["objectivesText"] = "Discover a hidden Legion threat while on the Broken Shore. Progress: Found something?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142396, 147430, 147860, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46769] = { ["id"] = 46769, ["name"] = "Relieved of Their Valuables", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "Not all demons on this shore stomp around in the open. Some slink about in the shadows, finding more subtle ways to advance the Legion's cause. I have been observing the behavior of smaller demons, these wyrmtongues. They seem to spend considerable time acquiring objects of power. We cannot allow them to use these items against us. The wyrmtongues stash their goods in chests spread around the Broken Shore. I suggest you relieve them of their ill-gotten gain.", ["objectivesText"] = "Find 3 Hidden Wyrmtongue Caches on the Broken Shore. Progress: Have you found the wyrmtongue caches?", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 45072, 147811, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 13, ["flags"] = 0 } } },
[46791] = { ["id"] = 46791, ["name"] = "Carried On the Wind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46791, 46792 }, ["description"] = "Farseer $p, Consular Celestos has requested your presence back at the Maelstrom. Please see him at your earliest convenience.", ["objectivesText"] = "Return to the Maelstrom and speak with Consular Celestos .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117888, ["x"] = 0.446, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 788, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 788, ["name"] = "Class Mount: Shaman", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46792] = { ["id"] = 46792, ["name"] = "Gathering of the Storms", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 46791, 46792 }, ["description"] = "Thunderaan has asked me to send you to the Throne of the Four Winds to assist him with a situation. Speak with me again when you're ready to leave, Farseer.", ["objectivesText"] = "Speak with Consular Celestos to begin the Gathering of the Storms scenario. Complete the scenario and return to Celestos. Progress: I'm sure the Windlord's problem won't be too difficult for you to assist with.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 788, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 788, ["name"] = "Class Mount: Shaman", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46813] = { ["id"] = 46813, ["name"] = "The Lost Glacier", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 871, ["storyline"] = { 46719, 46720, 46812, 46813 }, ["description"] = "<The Lich King's presence is overwhelming.> Do you know why the red dragonflight seeks to prevent us from finding our prize? The bones of a great red dragon teem with the essence of life, even decades after its passing. You will consume this life essence, blight it, and turn it to undeath. And then you will raise a dragon. Fly now into the north. Find this glacier, and your destiny. <The presence fades.>", ["objectivesText"] = "Travel to the Lost Glacier. Progress: Go, now, and find your frozen destiny.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 351, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1738, ["db2PoiUiMapID"] = 871, ["questLines"] = { { ["id"] = 351, ["name"] = "Class Mount: Death Knight", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46815] = { ["id"] = 46815, ["name"] = "Eredath, Jewel of Argus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "The shattered ruin below us is all that remains of Eredath . We called it the Jewel of Argus. It was here that my fellows in the triumvirate guided our people to prosperity. That was a long time ago. <Velen lapses into a moment of silence.> Join me on the surface. We will begin our search for the Crown of the Triumvirate.", ["objectivesText"] = "Descend to Eredath with Velen.", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 29106, 31307, 32649, 108897, 237812 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46816] = { ["id"] = 46816, ["name"] = "Rendezvous", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "There is much to be done before this nightmare can end, but we need to regroup before we draw more attention from the Legion. I managed to retain a signal crystal during the crash used to call transport beacons from the Xenedar. With luck, we should be able to use it to establish a link between here and your forces as well.", ["objectivesText"] = "Use the Signal Crystal to call down a Lightforged Beacon from the Vindicaar. Progress: We must establish a link to your vessel before we can press on.", ["rewardGold"] = 77400, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120529, ["x"] = 0.5775, ["y"] = 0.6745 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120529, ["x"] = 0.5775, ["y"] = 0.6745 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.5775, ["y"] = 0.6745 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46818] = { ["id"] = 46818, ["name"] = "Defenseless and Afraid", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "This is the battle that raged while I awaited the Genedar. So many ran to join me, but Kil'jaeden inspired still more to stand in their way. My people were slaughtered without mercy. To cover our retreat I ordered for this arena's defenses to be activated. It is clear that they were unable. To turn the tide in this battle, to give these spirits rest, we must do what they could not. Find a way to activate the pylons.", ["objectivesText"] = "Collect Stolen Pylon Cores from enemies in Triumvirate's End and use them to activate 3 Ancient Pylons . Progress: I will hold this position. The spirits may be only echoes of their former selves, but they do not know that.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 152408, 153052, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46827] = { ["id"] = 46827, ["name"] = "Meld Into the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45073, 45571, 45576, 45629, 45848, 46322, 46323, 46324, 46326, 46827 }, ["description"] = "We should meet back up with the rest of the council and tell them of what we have achieved this day. At your leisure, return to us. We shall be waiting.", ["objectivesText"] = "Return to the Hall of Shadows, and meet Lord Jorach Ravenholdt .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 147474, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117259, ["x"] = 0.735, ["y"] = 0.434 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.434 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 294, ["title"] = "Rogue Order Hall", ["questLineID"] = 5856, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5856, ["name"] = "Saga of the Shadowblade IV", ["orderIndex"] = 15, ["flags"] = 0 } } },
[46832] = { ["id"] = 46832, ["name"] = "Aalgen Point", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["series"] = { 46845 }, ["description"] = "You wanna hold territory on this chunder puddle of an island, right? Right. That means linkin' up with camps on the outskirts, mate. I know this bloke called Heidirk. Scrappy fella, loves to get into the thick of it. Headed out to the eastern coast with those drakes of his. Have a look for him. Remind him he owes me a pint or two!", ["objectivesText"] = "Speak with Heidirk the Scalekeeper at Aalgen Point.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120183, ["x"] = 0.445, ["y"] = 0.631 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120118, ["x"] = 0.706, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.631 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46839] = { ["id"] = 46839, ["name"] = "From Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "I'm afraid it's only a matter of time before our presence is known. We must begin our preparations at once.", ["objectivesText"] = "Walk with High Exarch Turalyon .", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 84060, 84061, 84062, 84063, 84064, 237812, 257143, 265106, 265631 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120529, ["x"] = 0.5775, ["y"] = 0.6745 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120760, ["x"] = 0.598, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.5775, ["y"] = 0.6745 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 8, ["flags"] = 0 } } },
[46840] = { ["id"] = 46840, ["name"] = "Prisoners No More", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "Hatuun's people have endured arduous times. Their numbers dwindle as those ripped from beyond the walls of their sanctuary become servants to the annihilan lords in the pits just beyond, sentenced to a life of labor, torture and ultimately, death. Seek out these captives, release them from their bonds and show our allies we stand as one against the Burning Legion.", ["objectivesText"] = "Rescue 10 Darkfallen Slaves from the Annihilan Pits.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120760, ["x"] = 0.598, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120953, ["x"] = 0.504, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 10, ["flags"] = 0 } } },
[46841] = { ["id"] = 46841, ["name"] = "Threat Reduction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "In time, Hatuun and his people will set aside their bitterness and become valuable allies. But their trust must be earned. He says their village is beset by a demon called Aggonar and his cruel kin. We need these fiends out of the way before we can seek out Alleria and the others. The chieftain lent us his horn. Use it to call down his people's vengeance upon the demon lieutenants while I carve a path to Aggonar's lair.", ["objectivesText"] = "Slay Kar'aaz , Xeth'tal , and Magraloth in the Annihilan Pits. Progress: Has the threat been dealt with?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 152700, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120760, ["x"] = 0.598, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120953, ["x"] = 0.504, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 9, ["flags"] = 0 } } },
[46842] = { ["id"] = 46842, ["name"] = "A Strike at the Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "These pits have long been a blight upon the lives of our new allies. The demons hunt them down and torture the poor souls for sport. <Turalyon shakes his head with disgust, fixing his gaze upon the beast before him.> It is time to make them pay for their cruelty and restore hope to this Light-forsaken place. We strike on your mark, <name>.", ["objectivesText"] = "Slay Aggonar . Progress: No rest until the deed is done.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120953, ["x"] = 0.504, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120738, ["x"] = 0.511333, ["y"] = 0.531333 }, { ["mapID"] = 830, ["npcID"] = 124995, ["x"] = 0.515, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "group", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 11, ["flags"] = 0 } } },
[46843] = { ["id"] = 46843, ["name"] = "Return to the Vindicaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "That pit lord won't trouble our new allies any longer. <Turalyon's brow furrows.> Until another takes its place, at least. If there's one thing I've learned in our endless war against the Legion, it's to savor victories as you find them. Come, let us take a moment to regroup back at your vessel. Alleria and I have been waiting a long time for a reunion with our son.", ["objectivesText"] = "Return to the Vindicaar.", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120738, ["x"] = 0.511333, ["y"] = 0.531333 }, { ["mapID"] = 830, ["npcID"] = 124995, ["x"] = 0.515, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.511333, ["y"] = 0.531333 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 12, ["flags"] = 0 } } },
[46845] = { ["id"] = 46845, ["name"] = "Vengeance Point", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["series"] = { 46832 }, ["description"] = "On my way here, I ran across a squad of demon hunters headed northwest to Vengeance Point. You can bet the Legion will try to stop them from establishing a forward position. I spoke to an elf named Izal Whitemoon . Not the friendliest sort, but I'm sure she'd be grateful if you lent the Illidari a hand... whether she admits it or not.", ["objectivesText"] = "Defeat the Legion siege on Vengeance Point and report to Izal Whitemoon . Progress: This siege is disabling my bats from their scouting duties.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120118, ["x"] = 0.706, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 111323, ["x"] = 0.496, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46924] = { ["id"] = 46924, ["name"] = "The Wolf's Tale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45426, 45498, 45528, 46674 }, ["description"] = "Goldrinn sure didn't take any time getting out of here, did he? Let's go see if we can find him outside.", ["objectivesText"] = "Find Goldrinn outside of the Stormrage Barrow Dens.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 115750, ["x"] = 0.687, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.687, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 80, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 7, ["flags"] = 0 } } },
[46938] = { ["id"] = 46938, ["name"] = "Alone in the Abyss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["series"] = { 47589 }, ["description"] = "Champion, we will suffer the same fate as the Army of the Light if the Legion fires that infernal weapon upon us. We must descend into the siege camp below and destroy it while we still can!", ["objectivesText"] = "Speak to Grand Artificer Romuul to disembark the Vindicaar.", ["rewardGold"] = 50550, ["rewardXP"] = 1535, ["rewardItems"] = { 152593, 152626, 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119543, ["x"] = 0.608, ["y"] = 0.795 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46941] = { ["id"] = 46941, ["name"] = "The Path Forward", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "<Velen stares beyond the arena for a time.> We must continue on, but I feel Eredath is far from finished with us. We should take advantage of this relative safety while we still can. I will place a signal beacon that will allow the Vindicaar to lock onto our location. Romuul will send us our means of returning to the Vindicaar if there is a need.", ["objectivesText"] = "Call down a Lightforged Beacon. Progress: Much remains to be seen, <name>. Argus has not forgotten us.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 210455, 211313, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47000] = { ["id"] = 47000, ["name"] = "The Council's Call", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44782, 44821, 46765, 47000 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765 }, ["description"] = "I'm sorry that I haven't kept your apprised of the situation. We needed more actionable information before bringing the matter before you. The Council of the Six has been investigating Legion threats outside of the Broken Shore. I believe this scroll to be the final piece of information we need. Meet me in Dalaran at the Violet Citadel. We will need the other members of the Council.", ["objectivesText"] = "Seek out the Council of Six in the Violet Citadel.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116302, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 278, ["name"] = "The Council's Challenge", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47003] = { ["id"] = 47003, ["name"] = "Restoration: The Bradensbrook Investigation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 45864, 46079, 46080, 46082, 46106, 46107, 46200, 47003 }, ["series"] = { 46078, 46079, 46080, 46082, 47004, 47005, 47006, 47027, 47029 }, ["description"] = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook! Is it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid. Specialization: Restoration Shaman", ["objectivesText"] = "Go to Bradensbrook in Val'sharah.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118752, ["x"] = 0.422, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 304, ["name"] = "The Black Rook Threat", ["orderIndex"] = 4, ["flags"] = 0 } } },
