[47018] = { ["id"] = 47018, ["name"] = "Beast Mastery: Rumblings Near Feltotem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47018 }, ["series"] = { 45560, 45564, 45575, 45587, 45726, 45796, 47019, 47020, 47031, 47035 }, ["description"] = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Beast Mastery Hunter", ["objectivesText"] = "Find Navarrogg at the Misty Coast in Highmountain.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47019] = { ["id"] = 47019, ["name"] = "Windwalker: Rumblings Near Feltotem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 45564, 45575, 45587, 45726, 45796, 45841, 45842, 47019 }, ["series"] = { 45560, 45564, 45575, 45587, 45726, 45796, 47018, 47020, 47031, 47035 }, ["description"] = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later. The drogbar chieftain, Navarrogg , is handling this personally and we'd like you to meet him near the Feltotem village. Specialization: Windwalker Monk", ["objectivesText"] = "Find Navarrogg at the Misty Coast in Highmountain.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 117225, ["x"] = 0.356, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 296, ["name"] = "The Fel Worm Menace", ["orderIndex"] = 2, ["flags"] = 0 } } },
