[47022] = { ["id"] = 47022, ["name"] = "Protection: Aid of the Illidari", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 100, ["storyline"] = { 45413, 45414, 45415, 45843, 45863, 47022 }, ["series"] = { 45412, 45413, 45414, 45415, 46314, 47023, 47024, 47025, 47030 }, ["description"] = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city. Kor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks. I do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more. Specialization: Protection Paladin", ["objectivesText"] = "Find Kor'vas Bloodthorn in the streets of Dalaran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 116880, ["x"] = 0.848, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.848, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 293, ["name"] = "The Highlord's Return", ["orderIndex"] = 4, ["flags"] = 0 } } },
