[47046] = { ["id"] = 47046, ["name"] = "Frost: The Thieving Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 76, ["storyline"] = { 44915, 44920, 44924, 45865, 46177, 47046 }, ["description"] = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him. Fortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem. I'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to. Specialization: Frost Death Knight", ["objectivesText"] = "Travel to Xylem's Tower within Bear's Head in Azshara.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 115791, ["x"] = 0.25, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.25, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 313, ["name"] = "Xylem Challenge", ["orderIndex"] = 2, ["flags"] = 0 } } },
