[47049] = { ["id"] = 47049, ["name"] = "Demonology: Fate of the Tideskorn", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049 }, ["description"] = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Demonology Warlock", ["objectivesText"] = "Search Jandvik for the vrykul mentioned in the scrolls.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 144457 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116568, ["x"] = 0.6256, ["y"] = 0.6316 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.6256, ["y"] = 0.6316 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 310, ["name"] = "God-Queen Challenge", ["orderIndex"] = 1, ["flags"] = 0 } } },
