[47055] = { ["id"] = 47055, ["name"] = "Fire: The Folly of Levia Laurence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47055 }, ["description"] = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Fire Mage", ["objectivesText"] = "Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 3, ["flags"] = 0 } } },
