[47059] = { ["id"] = 47059, ["name"] = "Feral: The Folly of Levia Laurence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45125, 45126, 45127, 45861, 45916, 45917, 46327, 47059 }, ["description"] = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands. She was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail. Specialization: Feral Druid", ["objectivesText"] = "Ask around the city for information on Levia Laurence. Progress: Have you found any clues to Levia's disappearance?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 311, ["name"] = "Imp Mother Challenge", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47066] = { ["id"] = 47066, ["name"] = "Consecrating Ground", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "We have everything we need. In the alcove below you will find the shattered remains of the Argunite Matrix . Replacing the Keystone will restore it to full capacity. The pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over. I hope it brings them peace.", ["objectivesText"] = "Repair the Argunite Matrix beneath Triumvirate's End. Progress: Hurry <name>, we cannot let this continue any longer.", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47100] = { ["id"] = 47100, ["name"] = "Arkhaan's Pain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Darkness envelops us... the Light has gone from this place... < Arkhaan mumbles to himself before noticing you are still talking to him.> Arkhaan could not save them. Brothers. Sisters. Whispers twisted them. The Light cannot see them. It turns away from us. Arkhaan failed. < Arkhaan stares off into space.>", ["objectivesText"] = "Slay 12 Broken in Oronaar Collapse. Progress: < Arkhaan mutters incoherently to himself.>", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121518, ["x"] = 0.414667, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121518, ["x"] = 0.414667, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.414667, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47137] = { ["id"] = 47137, ["name"] = "Champions of Legionfall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The battle to reclaim the Broken Shore is straining our resources. We cannot afford to relent, lest the Legion undo all that we have accomplished. The members of your order have given much, but more is needed. Rally your champions and do what you must to bolster their ranks. There may be untapped power in this land that will turn the tide of war in our favor.", ["objectivesText"] = "Return to your class order hall and recruit a new champion.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116576, ["x"] = 0.445, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47180] = { ["id"] = 47180, ["name"] = "The Pulsing Madness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "This broken still retains some of his sanity, though not all of it. I can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind. Perhaps we can use the prayer fragments you found, as they still contain some Light energy. I will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.", ["objectivesText"] = "Dispel 5 Void Manifestations .", ["rewardGold"] = 154900, ["rewardXP"] = 6140, ["rewardItems"] = { 151563, 152712, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47183] = { ["id"] = 47183, ["name"] = "Arkhaan's Plan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Arkhaan remembers. He remembers something that will... yes... will save us. Follow Arkhaan . Isolon calls! We will offer soft words to the Light. The Light will banish the darkness. < Arkhaan eyes Alleria warily.> Arkhaan will watch that one closely.", ["objectivesText"] = "Follow Arkhaan to Isolon.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121518, ["x"] = 0.414667, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.414667, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47184] = { ["id"] = 47184, ["name"] = "Arkhaan's Peril", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Whatever called to him, it cannot have good intentions. We need to go in after him. Before we step through this portal, <name>... ensure you are prepared to fight. The Void's influence is rarely peaceful.", ["objectivesText"] = "Enter the Void Tear and deal with Arkhaan . Progress: We must address this threat.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47203] = { ["id"] = 47203, ["name"] = "Throwing Shade", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me. If he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void... Come, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.", ["objectivesText"] = "Investigate the Umbra Hollows with Alleria and Locus-Walker. Progress: Move quickly, or we may lose him.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 }, { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47217] = { ["id"] = 47217, ["name"] = "Sources of Darkness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "I think I understand what he was trying to show us, <name>. I feel a surge of power building ahead. They must be cultivating the Void, calling it here. We need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary. Locus-Walker and I have unfinished business to attend to.", ["objectivesText"] = "Deactivate 5 Void Harvesters . Progress: Locus-Walker and I have some unfinished business to attend to.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 }, { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47218] = { ["id"] = 47218, ["name"] = "The Shadowguard Incursion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void. I had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance. It cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.", ["objectivesText"] = "Slay 15 Shadowguard Ethereals. Progress: Walking the razor's edge does have risks, <name>.", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121597, ["x"] = 0.339333, ["y"] = 0.492222 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121597, ["x"] = 0.339333, ["y"] = 0.492222 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.339333, ["y"] = 0.492222 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 }, { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47221] = { ["id"] = 47221, ["name"] = "The Hand of Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 47221, 47222, 47223, 47224, 48440, 48506 }, ["series"] = { 47222, 47223, 47224, 47835, 47867, 48506, 48507 }, ["description"] = "$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Stormwind Harbor. A ship awaits you there to grant you and your allies passage to Azuremyst.", ["objectivesText"] = "Meet your escort to the Exodar at Stormwind Harbor.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 132120 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 121754, ["x"] = 0.215, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 3, ["db2PoiMapID"] = 1750, ["db2PoiUiMapID"] = 892, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47222] = { ["id"] = 47222, ["name"] = "Two If By Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 47221, 47222, 47223, 47224, 48440, 48506 }, ["series"] = { 47221, 47223, 47224, 47835, 47867, 48506, 48507 }, ["description"] = "The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger. We will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better. Just say the word when you are ready to depart.", ["objectivesText"] = "Speak to Vereesa Windrunner to set sail for the Exodar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 55015, 58216, 131354, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 121754, ["x"] = 0.215, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1750, ["db2PoiUiMapID"] = 891, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47223] = { ["id"] = 47223, ["name"] = "Light's Exodus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8840, ["mapID"] = 892, ["storyline"] = { 47221, 47222, 47223, 47224, 47835, 47867, 48440, 48506, 48507 }, ["series"] = { 47221, 47222, 47224, 47835, 47867, 48506, 48507 }, ["description"] = "Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path. We should find the Prophet at once so that we do not stall the invasion.", ["objectivesText"] = "Meet Prophet Velen in the Vault of Lights in the Exodar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1750, ["db2PoiUiMapID"] = 892, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47224] = { ["id"] = 47224, ["name"] = "The Vindicaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8840, ["mapID"] = 893, ["storyline"] = { 47221, 47222, 47223, 47224, 47835, 47867, 48440, 48506, 48507 }, ["series"] = { 47221, 47222, 47223, 47835, 47867, 48506, 48507 }, ["description"] = "Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel. Once the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.", ["objectivesText"] = "Board the Vindicaar. Progress: Today marks the beginning of the Legion's downfall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1750, ["db2PoiUiMapID"] = 893, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47238] = { ["id"] = 47238, ["name"] = "The Seat of the Triumvirate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole. That is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there. This is a dire task, one that I would not ask if it were not completely necessary. We will descend together. Come.", ["objectivesText"] = "Seek the Crest of Knowledge. Progress: Such a task I cannot undertake alone. Your help is greatly appreciated, <name>.", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 152241, 152242, 152243, 152244, 152939, 237812, 246812, 246936, 249400, 251821, 254267, 254579 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47287] = { ["id"] = 47287, ["name"] = "The Vindicaar Matrix Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 886, ["storyline"] = { 47104, 47134, 47182, 47287, 47554 }, ["description"] = "Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? But we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. Go to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.", ["objectivesText"] = "Link Light's Judgment into the Vindicaar Matrix Core. Progress: Have you linked Light's Judgment into the Vindicaar Matrix Core?", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 355, ["name"] = "The Legion Jailbreak", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47416] = { ["id"] = 47416, ["name"] = "Shadow of the Triumvirate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "Talgath's words carry more gravity than I think he knew. In an attempt to hurt me one final time, he has given us the answer. The Crest of Knowledge is hidden away in the Seat of the Triumvirate, and it is not unguarded. If my suspicions are correct, we may be facing a greater threat than any of us dared imagine. A dark naaru. Let us return to the Vindicaar. We will plan our next steps there.", ["objectivesText"] = "Return to the Vindicaar.", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 152711, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47431] = { ["id"] = 47431, ["name"] = "Gathering Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["description"] = "Alleria and I long for more time with our son, but we cannot afford to wait any longer, <name>. We must strike now. The Army of the Light is scattered, but not defeated. Any survivors should have stayed near the crash site of the Xenedar. If there is any hope of victory, we must rally them and rescue Xe'ra. With the pit lords dealt with, we should have a safer route to the Xenedar. Meet me in the krokul hovel as soon as you can.", ["objectivesText"] = "Meet Turalyon in the Krokul Hovel.", ["rewardGold"] = 50550, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 122621, ["x"] = 0.384857, ["y"] = 0.574857 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.384857, ["y"] = 0.574857 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47473] = { ["id"] = 47473, ["name"] = "Sizing Up The Opposition", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "Turalyon was no doubt hoping for better news, but I fear I cannot provide it. Attempting to drive into the heart of the Legion now would cost us everything. There must be another way. I do not know what it is, but I trust that we will find it. Best not keep Turalyon waiting. We must move forward.", ["objectivesText"] = "Speak with Turalyon.", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 885, ["npcID"] = 127033, ["x"] = 0.724, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47508] = { ["id"] = 47508, ["name"] = "Fire At Will", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 40129, 40238 }, ["description"] = "Look out there, the wings of the bats fill the sky. We must offer what ranged support we can, but our hands are full here. It looks like the Legion has not yet destroyed all of the artillery batteries. If you can get to one, you should be able to show those flying fiends the Light.", ["objectivesText"] = "Enter a Lightforged Battery and slay 30 Frenzied Plaguewings . Progress: Those bats are always a nuisance to deal with. This method will be more... efficient, I believe.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 152707, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47526] = { ["id"] = 47526, ["name"] = "Bringing the Big Guns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 46213, 47771 }, ["description"] = "Light's Judgment has a security feature to prevent it from falling into enemy hands. We can trigger its recall mechanism, which will teleport it back to a vessel. With the Xenedar out of commission, the gun should recall to your ship instead. You can make good use of its firepower. The process takes time, though, and will likely attract the Legion's attention. Be on your guard.", ["objectivesText"] = "Locate and secure Light's Judgment .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121517, ["x"] = 0.315, ["y"] = 0.637 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.637 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47541] = { ["id"] = 47541, ["name"] = "The Best Prevention", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["description"] = "If you've brought the High Exarch back to us, you are a welcome ally indeed. More is needed of you. You see our soldiers out there, fighting against all odds? Defend them. Slay the enemy. Strong words for a priest, perhaps, but every dead man'ari is one less blade at our throats. Show them that the Light protects its chosen even as it scorches the unfaithful. When you are finished, seek out Y'mera. She will have fewer troops, and more need of your abilities.", ["objectivesText"] = "Slay 20 attackers in the Shattered Fields.", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121520, ["x"] = 0.405, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47589] = { ["id"] = 47589, ["name"] = "Righteous Fury", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["series"] = { 46938 }, ["description"] = "The devastators bombarding our forces prevent us from advancing any further. I can only protect us from their blasts for so long. Champion, you must pierce their lines and remove the barriers protecting the devastators. If you can destroy the anchors that maintain the shields, I can cleanse them from afar.", ["objectivesText"] = "Destroy 3 Legion Devastators. Progress: Unless the anchors are destroyed, the devastators cannot be touched.", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119543, ["x"] = 0.608, ["y"] = 0.795 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 123149, ["x"] = 0.542, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47627] = { ["id"] = 47627, ["name"] = "Vengeance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "The Army of the Light will not have fallen in vain. Our forces will assault the main encampment while we destroy their siege weapon. This will be but the beginning of our vengeance.", ["objectivesText"] = "Destroy the siege weapon at the Crown of Destruction. Progress: Until their weapon is no longer a threat, we are cornered here like vermin.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 25919, 25920, 25921, 41826, 41829, 41844, 41845, 41846, 44408, 44409, 44410, 44411, 44412, 49448, 49449, 49546, 49562, 50387, 50401, 50402, 52253, 56644, 56645, 62869, 62870, 62871, 62879, 62880, 62881, 62882, 66901, 66902, 66903, 84528, 84529, 84530, 84531, 84532, 84533, 84534, 84535, 84536, 117509, 117510, 117511, 117512, 128832, 131295, 131667, 131821, 131822, 141678, 175446, 175459, 175460, 175461, 180901, 180902, 180903, 180904, 197110, 211279, 237812, 252655, 264479, 264480, 264481 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 123148, ["x"] = 0.542, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119535, ["x"] = 0.575, ["y"] = 0.772 }, { ["mapID"] = 830, ["npcID"] = 123148, ["x"] = 0.542, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47641] = { ["id"] = 47641, ["name"] = "Signs of Resistance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "Our forces sustained heavy losses defending the Vindicaar, <name>. We require allies. The Army of the Light was known to take in survivors of the Legion's crusade to bolster their ranks. We must do the same. I sense the presence of the Legion slaves you freed nearby. I suspect that they have carved out a resistance against their masters. I would appreciate your company, $p.", ["objectivesText"] = "Search for signs of resistance.", ["rewardGold"] = 70225, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119543, ["x"] = 0.608, ["y"] = 0.795 }, { ["mapID"] = 830, ["npcID"] = 123149, ["x"] = 0.542, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121345, ["x"] = 0.578, ["y"] = 0.680667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.795 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47652] = { ["id"] = 47652, ["name"] = "The Light Mother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 47653, 47743 }, ["description"] = "We must know for sure whether the Light Mother survived, <name>. Xe'ra was weakened by sending her heart to Azeroth, but she is the prime naaru. She is the Light, and she cannot fade. Let's head into the Xenedar and look for her. Light willing, she will return to guide us once more.", ["objectivesText"] = "Find Xe'ra within the Xenedar. Progress: Light Mother... you must have survived...", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 122621, ["x"] = 0.384857, ["y"] = 0.574857 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 122621, ["x"] = 0.384857, ["y"] = 0.574857 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.384857, ["y"] = 0.574857 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47653] = { ["id"] = 47653, ["name"] = "Light's Return", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 47652, 47743 }, ["description"] = "Xe'ra has been saved! We have won an important victory here. The Light Mother should be back on the Vindicaar. No doubt she will want to speak with you. There is so much to explain... Romuul should be able to teleport us back to the ship now. Let me know when you are ready.", ["objectivesText"] = "Speak with Turalyon to return to the Vindicaar.", ["rewardGold"] = 561800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 122621, ["x"] = 0.384857, ["y"] = 0.574857 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.384857, ["y"] = 0.574857 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47686] = { ["id"] = 47686, ["name"] = "Not-So-Humble Beginnings", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "Now we may begin our search for the Crown of the Triumvirate. We will start with the fragment Archimonde carried: the Sigil of Awakening. To the east and north you will find all that remains of the greatest school of magic on Argus. It was there that Archimonde gained his mastery of the arcane. I can think of no other place he would stow his treasures. It will be guarded, no doubt. We will leverage the expertise of Fareeya's forces here to follow this trail.", ["objectivesText"] = "Meet Archmage Y'mera at the Conservatory of the Arcane.", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47687] = { ["id"] = 47687, ["name"] = "Gatekeeper's Challenge: Mastery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "Archimonde was an individual consumed by the pursuit of power. Only those who could match his lust would fare well under his tutelage. You will fight what remains of Archimonde's greatest pupils. These three once held such power in their own disciplines that the Conservatory remembers them now. Their echoes will try to kill you. Best all three with all your limbs intact and I will recognize your strength.", ["objectivesText"] = "Defeat Grand Vizier Jarasum , Arc-Consul Velara , and High Wakener Aargon .", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 137246, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47689] = { ["id"] = 47689, ["name"] = "Gatekeeper's Challenge: Tenacity", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "My master Archimonde was not known for his willingness to suffer indecision. He preferred to teach by rewarding frustration with more frustration-- punishment with more punishment. Absolute conviction was required to succeed under him. At the opposite end of the Conservatory you will find a large structure. Once inside, your goal is to overcome all the obstacles placed before you. Emerge unscathed and I will be forced to consider your will strong enough to proceed.", ["objectivesText"] = "Overcome the Trial of Tenacity. Progress: Take all the time you need. Failure is an art, I hear.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 152098, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47691] = { ["id"] = 47691, ["name"] = "A Non-Prophet Organization", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "I have complete faith that Velen is nearby. We would know if he had been captured. All the same, we must not delay. The Legion has a vested interest in finding him after all he has done to resist them. I shudder to think what they might do, given the chance. That is why I am going with you. We will find Velen and help him track down the Crest of Knowledge. We must have faith in his mission or all will be lost.", ["objectivesText"] = "Locate Velen.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 237812, 245422 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47743] = { ["id"] = 47743, ["name"] = "The Child of Light and Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 831, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 47652, 47653 }, ["description"] = "It is time, <name>. Xe'ra is returned to us. We have Light's Heart. We have her Chosen One. Come, let us restore her. Let us forge a bright new path against our foes. Speak to me when you are ready to begin.", ["objectivesText"] = "Speak with Turalyon to revive Xe'ra. Progress: Xe'ra...", ["rewardGold"] = 842700, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47754] = { ["id"] = 47754, ["name"] = "Lightly Roasted", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["description"] = "Can you hear me, <name>? Good. Light's Judgment has been installed on the Vindicaar. We should be able to harness its power immediately. We can use it both to clear the rubble blocking the Xenedar as well as destroy our enemies. As with any new piece of technology, we should test it out. Thoroughly. I trust you have plenty of targets down there.", ["objectivesText"] = "Use Light's Judgment to destroy the rubble blocking the entrance to the Xenedar.", ["rewardGold"] = 140450, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124906, ["x"] = 0.316, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 122621, ["x"] = 0.384857, ["y"] = 0.574857 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.316, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47771] = { ["id"] = 47771, ["name"] = "Locating the Longshot", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 46213, 47526 }, ["description"] = "We're going to need a bigger gun if we hope to free Xe'ra. One of the other bunkers crashed closer to the Xenedar. If Baraat was on it, he will have already begun surveying the area. Perhaps he's found the main cannon of the ship. If you head over that way, make sure he hasn't died, will you?", ["objectivesText"] = "Find Baraat the Longshot .", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121517, ["x"] = 0.315, ["y"] = 0.637 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47835] = { ["id"] = 47835, ["name"] = "The Hand of Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 47223, 47224, 47835, 47867, 48440, 48507 }, ["series"] = { 47221, 47222, 47223, 47224, 47867, 48506, 48507 }, ["description"] = "$p, We have won many battles against the Burning Legion, but it is time to end this war once and for all. Final preparations have begun to depart for Argus. Make haste to Bladefist Bay. A ship awaits you there to grant you and your allies passage to Azuremyst.", ["objectivesText"] = "Meet your escort to the Exodar at Bladefist Bay.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 122065, ["x"] = 0.582, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 3, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47853] = { ["id"] = 47853, ["name"] = "Flanking Maneuvers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "I will take command of Fareeya's lieutenants and we will escort Velen to the Crest of Knowledge. His mission must not fail. We face an old foe-- one the Army of the Light has encountered on numerous occasions. Talgath will try to block us in and prevent our retreat. You must not let that happen. Find out how he is bringing in his forces and cut them off. All we need is time to get in and get out. We are counting on you.", ["objectivesText"] = "Close 3 Legion Portals .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47854] = { ["id"] = 47854, ["name"] = "Wrath of the High Exarch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "Where the Legion is concerned, violence is always the answer. <Turalyon hefts his blade with a grim expression.> They are between us and Velen. Nothing will stop them from finding him unless we act. Now is not the time to hold back. Together we will sow chaos among their ranks.", ["objectivesText"] = "Disrupt the Legion forces in Arinor Gardens.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47855] = { ["id"] = 47855, ["name"] = "What Might Have Been", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "<Velen continues to stare at the statue as he speaks.> Thousands of years ago, when I was young, I made a choice. A choice that allowed my world to fall to ruin. A choice that made my people exiles. A choice that forever separated me from my beloved brothers. <Velen shakes his head.> I cannot leave, not yet. Not until I have had a chance to reflect.", ["objectivesText"] = "Witness Velen's memory. Progress: Memory roots me in place, more surely than the heaviest stone.", ["rewardGold"] = 154900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47856] = { ["id"] = 47856, ["name"] = "Across the Universe", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "Talgath . There was a time I called him an ally, a friend. I put my trust in him when it came time to leave Argus. I asked him to call out to the others who would join me. I gave him all that he needed to betray me and slaughter my followers. I do not know what brought this hatred to lurk in his heart, but his machinations repeatedly forced my people to flee world after world. He made it his mission to hunt us across the universe. This must end, <name>. Talgath must die.", ["objectivesText"] = "Defeat Talgath .", ["rewardGold"] = 619600, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47867] = { ["id"] = 47867, ["name"] = "Two If By Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 47223, 47224, 47835, 47867, 48440, 48507 }, ["series"] = { 47221, 47222, 47223, 47224, 47835, 48506, 48507 }, ["description"] = "The draenei have crafted a vessel to take us to Argus safely. They are gathering the invasion force on Azuremyst Isle as we speak. We will join them there by sea. The Legion is no doubt keeping a close eye on the gateway to their world. We must retain the element of surprise. Let me know when you are ready.", ["objectivesText"] = "Speak to Lady Liadrin to set sail for the Exodar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 55015, 58216, 131354, 237812 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 122065, ["x"] = 0.582, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1750, ["db2PoiUiMapID"] = 891, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47882] = { ["id"] = 47882, ["name"] = "Conservation of Magic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "I have an idea. This construct will be of use to us. We simply need to jolt it awake. We once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just. Take this. <Y'mera hands you a brightly glowing crystal.> It will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so. Stabilizing a few should allow us to access the whole network.", ["objectivesText"] = "Stabilize 8 Erratic Power Conduits .", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 151624, 152709, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47883] = { ["id"] = 47883, ["name"] = "The Longest Vigil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "It was a good thing we sought two sources of energy. Even with the conduits active, the construct has not stirred. It has likely been inactive a long while. Perhaps as long as Eredath has floated above Argus. What a long, lonely vigil it must have been. <Y'mera is silent for a moment as she peers at the construct.> Go ahead and jostle it a little. That combined with one last burst of magic ought to do the trick.", ["objectivesText"] = "Wake the Gatekeeper.", ["rewardGold"] = 154900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47889] = { ["id"] = 47889, ["name"] = "The Speaker Calls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "Magni sent for you to meet him in the Krokul Hovel. He has found something that he believes could help us overcome the Legion's infinite armies. We need every advantage we can muster if we are to see this war through. You should seek him out.", ["objectivesText"] = "Meet Magni in the Krokul Hovel.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47890] = { ["id"] = 47890, ["name"] = "Visions of Torment", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "I've been hearin' whispers ever since we got to Argus. They're just like Azeroth's, only... they ain't hers. I'm convinced that Argus has a titan of its own that's reachin' out to us! The broken have a relic stowed away that's darn near holy to 'em. Hatuun says they hear whispers from it... I think it might have some sort o' link to Argus itself! It's just in this chamber. Let's see what we can learn.", ["objectivesText"] = "Activate the Sacred Stone to witness Argus' vision with Magni. Progress: I know, I know, it's a lot to ask, but we need all the help we can get lad!", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47891] = { ["id"] = 47891, ["name"] = "Dire News", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["series"] = { 47892 }, ["description"] = "Azeroth was right in sendin' us here, <name>. We have to stop whatever it is Sargeras is plannin', or we may not have a home left to save when this is all over. Ye should go back to Turalyon and let him know what ye've seen. I'll stay here and see if I can't glean anything else that might help us.", ["objectivesText"] = "Return to Turalyon on the Vindicaar.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47892] = { ["id"] = 47892, ["name"] = "Storming the Citadel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["series"] = { 47891 }, ["description"] = "We have already secured ground near Nath'raxas Hold. It is one of the Legion's chief military fortifications on Argus. Striking it now, and hard, may be our only opportunity to tip the scales in our favor.", ["objectivesText"] = "Travel to Destiny Point.", ["rewardGold"] = 20220, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120763, ["x"] = 0.608, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47967] = { ["id"] = 47967, ["name"] = "An Argus Roper", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "My warriors stand no chance against even the smallest of the Legion's forces without our Cragscalers. If you can capture a few and bring them here, my warriors can better defend our people.", ["objectivesText"] = "Return 3 Wild Cragscalers to Lead Rider Jerek . Progress: We need those talbuk!", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 152095, 152096, 152097, 152575, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47987] = { ["id"] = 47987, ["name"] = "Preventive Measures", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "There is no end to the Legion's depravity. Every battle won, every world conquered, yields more souls to fuel their war machine. They have not yet defiled all of the fallen warriors in the hold, but I fear it is only a matter of time. Please, take this talisman with you into the hold and use it to sanctify any corpses you encounter. They deserve a better fate.", ["objectivesText"] = "Use the Talisman of the Prophet to sanctify 9 fallen Army of the Light warriors.", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 152110, 152706, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124974, ["x"] = 0.61, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124974, ["x"] = 0.61, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47988] = { ["id"] = 47988, ["name"] = "Chaos Theory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "Despite their strength and their numbers, even the Burning Legion requires order to fight. Disrupt that order... and they fall like the rabble they are. The plan is simple. Let chaos reign in their ranks, and the day will be ours.", ["objectivesText"] = "Kill 12 Nath'raxxan Fleshcarvers , Nath'raxxan Doomshots , or Ravenous Soulhunters , and 1 Nathrezim Banelord . Progress: We must do whatever it takes to see this done.", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124972, ["x"] = 0.606, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124972, ["x"] = 0.606, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47989] = { ["id"] = 47989, ["name"] = "Heralds of Apocalypse", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "We've been presented with a rare opportunity. Our scouts have spotted two shivarra priestesses in the western fel pools enhancing the Legion's war effort. The inner circle of Sargeras' chosen never leave the walls of Antorus. If we take them out, we might be able to sow fear among those closest to the Dark Titan.", ["objectivesText"] = "Slay Lady Heretica and Mistress Apostriss .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 153048, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125443, ["x"] = 0.615, ["y"] = 0.467 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125443, ["x"] = 0.615, ["y"] = 0.467 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.467 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47991] = { ["id"] = 47991, ["name"] = "Dark Machinations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "Eredar are adept at manipulating the fel that courses through this world. Those who do not shape it into living weapons build other armaments, like the Spires of Woe. The spires will make it difficult for even a small force to penetrate the main stronghold. We must dismantle enough of them to clear the way before we advance upon it.", ["objectivesText"] = "Dismantle 3 Spires of Woe. Progress: We do not have time for failure.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124972, ["x"] = 0.606, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124972, ["x"] = 0.606, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47992] = { ["id"] = 47992, ["name"] = "Dawn of Justice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["series"] = { 47993 }, ["description"] = "Thanks to your efforts, our enemy is in disarray and their defenses inoperable. We must take the ground at the spire's base and tighten the noose around their commander's neck. You have more than earned the honor to take the warframe into battle. We will follow your lead once the way is clear.", ["objectivesText"] = "Use the Lightforged Warframe to take control of the Court of the Avenger.", ["rewardGold"] = 404400, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120763, ["x"] = 0.608, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 120763, ["x"] = 0.608, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47993] = { ["id"] = 47993, ["name"] = "Lord of the Spire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["series"] = { 47992 }, ["description"] = "Lord Nath'raxas rules over this hold as thanks for his role in delivering Argus to the Legion many years ago. Make no mistake, he is powerful, but he has also grown overconfident in his seat. Take advantage of his hubris and make use of the warframe's firepower while you can. We will storm the courtyard shortly!", ["objectivesText"] = "Defeat Lord Nath'raxas .", ["rewardGold"] = 929400, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 120763, ["x"] = 0.608, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47994] = { ["id"] = 47994, ["name"] = "Forming a Bond", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 886, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47995] = { ["id"] = 47995, ["name"] = "Overt Ops", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "My soldiers are out there, <name>. I need you to find Baraat, Sorvos, and Telaamon. They were in the process of securing this area for Velen when the Legion came down on top of our heads. Inform them that their orders are to regroup with the Prophet at once. The time for subtlety has passed. There is a small army between us and them. Do what you must. Light keep you safe.", ["objectivesText"] = "Locate Baraat the Longshot , Grand Vindicator Sorvos , and Blademaster Telaamon .", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48053] = { ["id"] = 48053, ["name"] = "Weigh Anchor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 84, ["storyline"] = { 48053 }, ["description"] = "<name>, I was hoping to ask you for a small favor. The naval fleet at Stormwind Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Stormwind in the Greyfang Enclave here in Dalaran so it shouldn't be a long trip or anything.", ["objectivesText"] = "Bring the Crate of Felslate to Walcott Sutton at Stormwind Harbor. Progress: Did Alard send you?", ["rewardItems"] = { 151871 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 125210, ["x"] = 0.311, ["y"] = 0.124 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.311, ["y"] = 0.124 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 360, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48066] = { ["id"] = 48066, ["name"] = "A Feast for Our Kin", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["description"] = "Ah, the Highmountain tauren. They have been our allies ever since we felled the Legion. Are you interested in hearing how they joined the Horde? It is quite the tale! It all began with Baine Bloodhoof and Mayla Highmountain. Baine was hosting a great feast in Thunder Bluff to welcome the Highmountain tauren...", ["objectivesText"] = "Meet Baine Bloodhoof at Thunder Bluff in Mulgore.", ["rewardGold"] = 322100, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 125285, ["x"] = 0.38, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 93844, ["x"] = 0.614, ["y"] = 0.519 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 85, 88 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48067] = { ["id"] = 48067, ["name"] = "Shadow Over Thunder Bluff", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 48079, 49756 }, ["description"] = "A dark force has descended upon us. I refuse to believe that the Highmountain are behind it. The cacophony out there is disturbingly familiar. Could it be... No! The minions of the Old Gods are attacking! We must fight for Thunder Bluff, <name>!", ["objectivesText"] = "Slay 4 Dark Tendrils and 12 Shadows of Uul in Thunder Bluff. Progress: For the Old Gods to manifest even these fledgling minions is troubling.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 129914, ["x"] = 0.611, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.611, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48079] = { ["id"] = 48079, ["name"] = "Return to Highmountain", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 750, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 48067, 49756 }, ["description"] = "Spiritwalker Ebonhorn remains in great danger. He and Mayla have returned to Highmountain, but I believe they still need our aid. Let us journey to Thunder Totem and do whatever we can to mend Ebonhorn. Perhaps our deeds will strengthen the bond between our peoples.", ["objectivesText"] = "Meet Mayla Highmountain at Thunder Totem in Highmountain.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48081] = { ["id"] = 48081, ["name"] = "A Floating Ruin", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 883, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "We knew the Legion to be a formidable foe, but recent events demonstrate that we do not possess the necessary strength to continue. We have come too far to fail at this critical moment. I know of a relic on Eredath , my ancient home, that may be our salvation. We must take the Vindicaar beyond the surface of Argus, to the floating ruin suspended above us. Perhaps there we will find the salvation we so desperately need.", ["objectivesText"] = "Travel to Eredath .", ["rewardGold"] = 77400, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48107] = { ["id"] = 48107, ["name"] = "The Sigil of Awakening", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "This relic is too powerful to keep it out in the open. We must return to the Vindicaar at once. The Prophet will know what to do. I did want to thank you, <name>. Without you this would not be possible. Quoram would have ensured I never got near the Sigil. Perhaps some day I will share that story with you.", ["objectivesText"] = "Return to the Vindicaar and secure the Sigil of Awakening. Progress: Did you recover the Sigil of Awakening?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 151476, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48185] = { ["id"] = 48185, ["name"] = "Shadow of the Sepulcher", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 41884, 48190, 48434, 48435 }, ["description"] = "Ebonhorn spoke of another ward safeguarding the lands of the Skyhorn tribe. Somewhere close to the Sepulcher of the Sky, he said. It was there that this \"Darkness\" once manifested. Meet me there, <name>. I will show you how to walk in the memories of a great Skyhorn hero.", ["objectivesText"] = "Meet Spiritwalker Graysky in Sepulcher of the Sky.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125454, ["x"] = 0.385, ["y"] = 0.69 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.69 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48190] = { ["id"] = 48190, ["name"] = "Huln's Mountain", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 41884, 48185, 48434, 48435 }, ["description"] = "We have made progress reactivating the wards, but more must be done. I sense Ebonhorn's struggle. Though he fights with all his strength, he is slipping away. Should this \"Darkness\" emerge into our realm, I fear our friend will be lost. Ebonhorn spoke of another ward somewhere within Snowblind Mesa. Meet me there, so that I might guide you along another journey into the memories of the past.", ["objectivesText"] = "Meet Spiritwalker Graysky at Snowblind Mesa.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125459, ["x"] = 0.57, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48199] = { ["id"] = 48199, ["name"] = "The Burning Heart", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 886, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us. I wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru. This must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack. We need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!", ["objectivesText"] = "Use the Navigation Console to travel to the Antoran Wastes .", ["rewardGold"] = 77400, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48200] = { ["id"] = 48200, ["name"] = "Securing a Foothold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 886, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements. Our first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts. Speak to Romuul when you are ready to head down to the surface.", ["objectivesText"] = "Travel to the Antoran Wastes and place the Lightforged Beacon. Progress: We need that teleportation beacon set up if we are to reinforce our positions.", ["rewardGold"] = 30900, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48201] = { ["id"] = 48201, ["name"] = "Reinforce Light's Purchase", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "Now that we have established a foothold, we need to rendezvous with our soldiers in the field. We have an Army of the Light encampment to the south, near where the Legion is keeping their strongest warriors in some sort of stasis. Alleria went to scout the area. Find her, and see what information she has gathered.", ["objectivesText"] = "Speak with Alleria at Light's Purchase. Progress: The camp lies to the south. When you find the large stasis capsules, look for a passage on the left.", ["rewardGold"] = 77400, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 885, ["npcID"] = 127033, ["x"] = 0.724, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.724, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 885, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48202] = { ["id"] = 48202, ["name"] = "Reinforce the Veiled Den", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "The foothold you established allows us to check in with our field operatives. On our last mission here, we set up a bastion to the northeast. It should be defensible for now, but that could change at any moment. Illidan has gone ahead to assess the situation. I suggest you go there and see if he needs a hand.", ["objectivesText"] = "Speak with Illidan at the Veiled Den. Progress: The camp lies to the northeast. It may appear hidden at first glance, but you can find the Light shining in the darkest places.", ["rewardGold"] = 77400, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 885, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48344] = { ["id"] = 48344, ["name"] = "We Have a Problem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "We have a problem, <name>. The Legion has come to Eredath . When you claimed the Sigil it was as if we announced our presence to all of Argus. The eyes of Antorus are firmly upon us. Just wait. It gets worse. Velen took Captain Fareeya and her forces into the Arinor Gardens area to search for the Crest of Knowledge. To my knowledge, they are all now behind enemy lines. Come with me to the Conservatory. We need to bring Velen and the others back before it is too late.", ["objectivesText"] = "Meet Turalyon at the Conservatory of the Arcane.", ["rewardGold"] = 77400, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48345] = { ["id"] = 48345, ["name"] = "Talgath's Forces", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 }, ["description"] = "I must continue to seek the Crest of Knowledge, my friend. Nothing short of the whole Crown of the Triumvirate can turn the tide in the battle we face. Talgath's forces stand between us and that goal. I will need you to clear a path. We can let nothing stand in our way. Not even Talgath.", ["objectivesText"] = "Slay 12 of Talgath's forces.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 367, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 367, ["name"] = "Across the Universe", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48403] = { ["id"] = 48403, ["name"] = "The Darkness", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41840, 41841, 41882 }, ["description"] = "For thousands of years, the Darkness was held at bay. The wards stood... protecting Highmountain. Now they are gone, and evil is free once more. The Darkness that haunted our dreams... that even the kobolds spoke of only in frightened whispers... has come. Uul'gyneth , herald of the Old Gods, paves the way for his masters. Unless we stand together and defeat him, all is lost. You must hold nothing back, champion. None of us can.", ["objectivesText"] = "Defeat Uul'gyneth the Darkness.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 25549, 26010, 26024, 26036, 38734, 39033, 39060, 39098, 42846, 42861, 42870, 42881, 42895, 44018, 44039, 44041, 44042, 44043, 62849, 62850, 62851, 64594, 64604, 64613, 64620, 64625, 64629, 64632, 64634, 65623, 65631, 65632, 65641, 65644, 65645, 65646, 65647, 65648, 65813, 65814, 84060, 84061, 84062, 84063, 84064, 98133, 113169, 113170, 113171, 113172, 113173, 113174, 113175, 113176, 119036, 131271, 131640, 151493, 157013, 169905, 171354, 171355, 174288, 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184165, 184378, 184381, 184382, 184383, 184384, 184519, 211279, 237812, 237890, 237893, 245345, 246951, 257143, 263282, 263461, 265106, 265631 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 104997, ["x"] = 0.566, ["y"] = 0.926 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.922667 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48433] = { ["id"] = 48433, ["name"] = "Together We Are the Horde!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["description"] = "What began with a simple feast led to a battle against an ancient evil seeking to consume the world. My kind of day! Your deeds have helped secure an alliance between Orgrimmar and Highmountain. These tauren will make a valuable addition to the Horde. The Warchief will be pleased.", ["objectivesText"] = "Speak with Ji Firepaw at the Orgrimmar Embassy to hear the end of this tale.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 63207, 63353, 65274, 110560, 128353, 155662 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 126134, ["x"] = 0.566, ["y"] = 0.926 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 126065, ["x"] = 0.378, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.926 }, ["mapCandidates"] = { ["npc"] = { 85, 650 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48434] = { ["id"] = 48434, ["name"] = "How Fares Ebonhorn?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 41884, 48185, 48190, 48435 }, ["description"] = "Three of the ancient wards are restored. The mountain is not yet secure, but we may have done enough to break Ebonhorn free of the shadows gripping him. Let us return to Thunder Totem and see how he fares. Hopefully Ebonhorn can tell us more about what is happening with the Necrodark and the insidious master they serve.", ["objectivesText"] = "Return to Thunder Totem and check on Ebonhorn.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 125466, ["x"] = 0.532, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 15, ["flags"] = 0 } } },
[48440] = { ["id"] = 48440, ["name"] = "Into the Night", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8840, ["mapID"] = 831, ["storyline"] = { 47221, 47222, 47223, 47224, 47835, 47867, 48440, 48506, 48507 }, ["description"] = "What we do this day, we do for Azeroth. For the countless souls lost to the Legion's foul crusade. Once you are ready we will take the Vindicaar into the very heart of the Legion. Argus awaits.", ["objectivesText"] = "Travel to Argus aboard the Vindicaar.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8840 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48441] = { ["id"] = 48441, ["name"] = "Remnants of Darkfall Ridge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "My riders have talbuk, but my people need supplies. Food. Tools. Weapons. For millennia, we have migrated from one hovel to the next, moving each time the Legion discovered us. Never able to flee with our possessions, we left them behind. You are powerful, your followers are capable, but you do not know Argus. The landscape will dispatch you as mercilessly as the Legion. Recover our supplies from Darkfall Ridge, and I will order my people to guide your forces through the Argus Wastes.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Darkfall Ridge Supplies\".", ["rewardItems"] = { 152095, 152096, 152097, 152430, 152439, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48442] = { ["id"] = 48442, ["name"] = "Nath'raxas Hold: Preparations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "One of two fates await krokul prisoners taken to Nath'raxas Hold. Consume the fel, and become a willing soldier in the infinite army, or be mutated into a disfigured abomination. An ur'zul. While the Army of the Light occupies the Legion's attention, I am presented with an opportunity to save my people. I ask for your aid. Before we begin, your forces must be adequately equipped.", ["objectivesText"] = "Raise 6 Champions to 900 Item Level.", ["rewardItems"] = { 151842, 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48443] = { ["id"] = 48443, ["name"] = "Nath'raxas Hold: Rescue Mission", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "Your forces are adequately equipped for the mission to save my people from Nath'raxas. Order your champions to bolster my assault, and together we will dismantle the Legion's stranglehold over the region.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Nath'raxas Breakout\".", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48445] = { ["id"] = 48445, ["name"] = "The Ruins of Oronaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "Many krokul wander the city below, shrouded in shadow. I will not accept that they are all beyond redemption. Arkhaan was a leader, once. Some among his followers may still reside in the ruins of Oronaar, straddling the thin divide between reason and oblivion. Enlist the aid of your order. Scour the ruins for any that can be saved.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Inches from Madness.\"", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48446] = { ["id"] = 48446, ["name"] = "Relics of the Ancient Eredar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "I failed Arkhaan. I won't fail again. If there is to be any hope of freeing the krokul, the ethereal threat must be removed from Eredath . L'ura has been vanquished, but the void clings heavily near the Shadowguard Incursion. Before we commence, ensure your forces are protected from the shadow. Your champions should seek ancient eredar armaments in the nearby ruins.", ["objectivesText"] = "Raise 6 Champions to 925 Item Level.", ["rewardItems"] = { 151090, 151843, 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48447] = { ["id"] = 48447, ["name"] = "Shadowguard Dispersion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "Lend me the aid of your order once again, that we might end the Shadowguard threat permanently. While you confront the Legion, we will face the void. The attack commences once your forces arrive.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Shadowguard Dispersion\".", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48448] = { ["id"] = 48448, ["name"] = "Hindering the Legion War Machine", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 886, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "<class>t, I could use your help. The Army of the Light is coordinating an attack against the Spirit Crucible, Terminus, and Shaper's Rise to cripple the Legion's ability to wage war outside of the Antoran Wastes . We do not have enough soldiers to defend our footholds and execute this operation. Will you approach the <class>s on our behalf? This gambit could succeed with them fighting by our side. We can paralyze the Legion war machine.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Gambit in the Wastes.\"", ["rewardItems"] = { 152095, 152096, 152097, 152449, 153132, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48453] = { ["id"] = 48453, ["name"] = "Strike Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "As you may have seen, the ritualists in this forest kidnap our people and perform heinous rituals on them. The souls of our fallen now roam as twisted creatures. This sin cannot go unpunished. Kill as many ritualists as you are able, but be sure to strike at the dark demon that leads them.", ["objectivesText"] = "Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 152095, 152096, 152097, 152575, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48455] = { ["id"] = 48455, ["name"] = "Duskcloak Problem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "Here in this forest, species of talbuk and panthara still roam. However, the balance has been disrupted and now the panthara risk hunting the talbuk to extinction. To ensure their survival, we must decrease the number of panthara. Do not let their suffering linger. A swift death is the most merciful.", ["objectivesText"] = "Kill 10 panthara within the Petrified Forest.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152095, 152096, 152097, 152575, 153046, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48460] = { ["id"] = 48460, ["name"] = "The Wranglers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48460 }, ["description"] = "Great evil exists on Argus and our forests house some of the worst of it. My wranglers are at the edge of the forest and are waiting for reinforcements. That would be you. Seek out Lead Rider Jerek , he will tell you more.", ["objectivesText"] = "Speak to Lead Rider Jerek in the Petrified Forest.", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48461] = { ["id"] = 48461, ["name"] = "Where They Least Expect It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 48461, 48513 }, ["description"] = "The Legion's fanatical crusade leaves them spread thin. As they focus their defenses on Argus, we are free to tear into their forces on other worlds. Travel through an Invasion Point on Argus and show the Legion that there is no hiding from death.", ["objectivesText"] = "Enter an Invasion Point and defeat a Legion Commander. Progress: No demon is safe while I draw breath.", ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 369, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 369, ["name"] = "Invasion Rifts", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48483] = { ["id"] = 48483, ["name"] = "A Stranger's Plea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "My people... enslaved... Beaten... within death's grasp... <The cowled figure weakly raises his arm, handing you a small liquid skin.> Help... us...", ["objectivesText"] = "Heal 8 Felbound Drudges .", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 152472, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 126239, ["x"] = 0.588, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 123149, ["x"] = 0.542, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48500] = { ["id"] = 48500, ["name"] = "A Moment of Respite", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 831, ["storyline"] = { 46297, 46732, 46816, 46839, 46840, 46841, 46842, 46843, 46938, 47589, 47627, 47641, 48483, 48500 }, ["description"] = "For all we have seen, we must remember not to dwell on the past, but to look forward and prepare for what is to come. Take this opportunity to familiarize yourself with the Vindicaar.", ["objectivesText"] = "Speak with Artificer Shela'na , Thelbus Wimblenod and High Priestess Ishanah . Progress: Light guide your path.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 345, ["questLineOrder"] = 1 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 345, ["name"] = "Assault on Argus", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48506] = { ["id"] = 48506, ["name"] = "The Hand of Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 84, ["storyline"] = { 47221, 47222, 47223, 47224, 48440, 48506 }, ["series"] = { 47221, 47222, 47223, 47224, 47835, 47867, 48507 }, ["description"] = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there. With the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force. You should make your way to Stormwind Harbor right away. Arrangements have been made for a ship there to take you to Azuremyst.", ["objectivesText"] = "Meet your escort to the Exodar at Stormwind Harbor.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 121754, ["x"] = 0.215, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48507] = { ["id"] = 48507, ["name"] = "The Hand of Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 1, ["storyline"] = { 47223, 47224, 47835, 47867, 48440, 48507 }, ["series"] = { 47221, 47222, 47223, 47224, 47835, 47867, 48506 }, ["description"] = "Ever since the Legion invaded the Exodar, the draenei have been hard at work preparing to return to Argus. At long last they have a vessel that can take us there. With the way to that dreadful world open, we simply could not ask for a better opportunity to strike. Prophet Velen called for you quite specifically to join the assault force. You should make your way to Bladefist Bay right away. Arrangements have been made for a ship there to take you to Azuremyst.", ["objectivesText"] = "Meet your escort to the Exodar at Bladefist Bay. Progress: It seems fate has conspired to bring us together, <name>.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 122065, ["x"] = 0.582, ["y"] = 0.12 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.12 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 346, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 346, ["name"] = "To Argus!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48513] = { ["id"] = 48513, ["name"] = "Invasion Point Offensive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 48461, 48513 }, ["description"] = "The invasion points are key to cutting off Legion reinforcements to Argus. Defeating their armies within the lesser portals will allow us to assault larger invasion points and extinguish the Legion presence within.", ["objectivesText"] = "Complete 3 Invasion Points . Progress: The offensive continues.", ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 369, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 369, ["name"] = "Invasion Rifts", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48542] = { ["id"] = 48542, ["name"] = "Strike Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48542 }, ["description"] = "The scroll details a dark spell which steals the souls from the neighboring Krokul to create a new demon, the Ur'zul. The scroll is signed by Lady Shahrazad .", ["objectivesText"] = "Kill 8 Eredar ritualists and Lady Shahrazad in the Petrified Forest.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 152575, 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 152575 } },
[48544] = { ["id"] = 48544, ["name"] = "Woah, Nelly!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "<name>, you have my thanks. My Wranglers should be able to take it from here. If I can ask one more favor, would you pass a message to Chieftain Hatuun ? Tell him the forest is secure once again. I'm sure he will reward you for all of your effort. I'll loan you one of my fastest Cragscalers for the trip. Make sure to look both ways before crossing that path outside this forest, there's a giant Legion Obliterator that patrols there. Good luck!", ["objectivesText"] = "Return to Chieftain Hatuun in Krokul Hovel.", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 126160, ["x"] = 0.644, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48559] = { ["id"] = 48559, ["name"] = "An Offering of Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 831, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["description"] = "I sense it. The nobility in Xe'ra's heart. Her relentless defiance of the Legion. Let this be her legacy. In building the Vindicaar, we fashioned the Netherlight Crucible to harness the tremendous powers at play on Argus. I believe Xe'ra's essence is one key to that potential. Yet the Light alone is not enough. Without balance, there can be no harmony, no cohesion. Infuse this essence into the crucible, champion. It is the first step in unlocking the strength needed to end the Burning Crusade.", ["objectivesText"] = "Infuse the Essence of Light into the Netherlight Crucible.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 152593, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48560] = { ["id"] = 48560, ["name"] = "An Offering of Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 48560 }, ["description"] = "Can you sense it, <name>? The darkness within this essence is palpable. In the past, I might have shunned such power, even denied its very existence. But what have we learned throughout our long struggle, if not that Light and shadow must coexist? This may prove to be exactly what we need to bring balance to the Netherlight Crucible. To give us the edge we need against the Legion. Infuse this essence into the crucible, champion. Draw one step closer to realizing your weapon's full potential.", ["objectivesText"] = "Infuse the Essence of Shadow into the Netherlight Crucible. Progress: Light and shadow... forces that shape our very existence.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 152594, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard" },
[48600] = { ["id"] = 48600, ["name"] = "Take the Edge Off", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 886, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "The demons streaming out of Antorus equip themselves at Felfire Armory. We need to deny those weapons. Will your <class>s fight alongside the Army of the Light once again? Before the assault, gather materials. My smiths will craft your soldiers more powerful armor. The Legion won't give up Felfire without a fight.", ["objectivesText"] = "Raise 6 Champions to 950 Item Level. Progress: Make your preparations, <name>.", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48601] = { ["id"] = 48601, ["name"] = "Felfire Shattering", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 886, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "A thin series of stone bridges connects the Burning Breach to Felfire Armory over Fiend's Run. The Army of the Light will stem Legion reinforcements while your people deal with the armory itself. Work swiftly.", ["objectivesText"] = "Use the Scouting Map and complete the mission, \"Assault on Felfire Armory.\"", ["rewardItems"] = { 152095, 152096, 152097, 153130, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48634] = { ["id"] = 48634, ["name"] = "Further Supplying Krokuun", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48634 }, ["description"] = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker. What say you, offworlder?", ["objectivesText"] = "Collect 900 Order Hall Resources. Progress: You seek the aid of another ridgestalker?", ["rewardItems"] = { 152095 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48635] = { ["id"] = 48635, ["name"] = "More Void Inoculation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 48635 }, ["description"] = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. We can save more of my kin.", ["objectivesText"] = "Collect 100 Fragments of Condensed Void. Progress: Many of my brethren are deeply touched by shadow. It will take a tremendous effort to free them. Will you help?", ["rewardItems"] = { 152096, 237812 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 127037, ["x"] = 0.438, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard" },
[48636] = { ["id"] = 48636, ["name"] = "Fueling the Antoran Campaign", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48636 }, ["description"] = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", ["objectivesText"] = "Complete 10 Invasion Points. Progress: War is costly work. Have you gathered additional supplies for our efforts here?", ["rewardItems"] = { 152097, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48654] = { ["id"] = 48654, ["name"] = "Beneath Oronaar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 47967, 48441, 48442, 48443, 48445, 48446, 48447, 48448, 48453, 48455, 48544, 48600, 48601, 48654 }, ["description"] = "The krokul we found beneath Oranaar did not wish to leave. Could you speak with him, <name>? Convince him to board the Vindicaar.", ["objectivesText"] = "Speak with the krokul beneath Oranaar.", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 127037, ["x"] = 0.438, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 365, ["name"] = "Petrified Forest", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48910] = { ["id"] = 48910, ["name"] = "Supplying Krokuun", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48910 }, ["description"] = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker. What say you, offworlder?", ["objectivesText"] = "Collect 150 Order Hall Resources. Progress: This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more resources, I could offer you a ridgestalker. I can only part with a Krokul-Ridgestalker for this few resources once per week. Next week, I will offer you this trade again.", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 119388, ["x"] = 0.565, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48911] = { ["id"] = 48911, ["name"] = "Void Inoculation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 48911 }, ["description"] = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. We can save more of my kin.", ["objectivesText"] = "Collect 100 Fragments of Condensed Void. Progress: If you bring the necessary supplies, I can begin the distillation process, <name>. I can only free one of the Void-Touched with this few resources once per week.", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 127037, ["x"] = 0.438, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard" },
[48912] = { ["id"] = 48912, ["name"] = "Supplying the Antoran Campaign", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48912 }, ["description"] = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", ["objectivesText"] = "Complete 10 Invasion Points. Progress: The campaign against the Legion has taxed our existing resources heavily. Bring me supplies and I will place a lightforged under your command. I can only spare a lightforged for this few resources once per week.", ["rewardItems"] = { 152095, 152096, 152097, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48929] = { ["id"] = 48929, ["name"] = "Sizing Up The Opposition", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 }, ["description"] = "No doubt your High Exarch will fret at the news that we lack the resources to assault Antorus. He is not used to believing his vaunted Army of the Light to be inadequate. His pride is no concern of mine. While he plots a new strategy, I will bathe the ground in demon blood. Go. There is much to be done before we can achieve our final victory.", ["objectivesText"] = "Speak with Turalyon.", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 371, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 371, ["name"] = "The Heart of Argus", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48962] = { ["id"] = 48962, ["name"] = "Telogrus Rift", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 48962, 49787 }, ["description"] = "Umbric and his blood elves were cast out of their home for their pursuit of understanding. I know the dangers of the void better than most. We should lend them our aid and ensure they don't do anything too foolhardy. This rift will take us to their current location. I hope we are not too late to help them.", ["objectivesText"] = "Travel to Telogrus Rift and complete the scenario.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 155656, 156486 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 126301, ["x"] = 0.521, ["y"] = 0.135 }, { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 }, { ["mapID"] = 84, ["npcID"] = 234616, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.135 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 532, ["name"] = "Allies of the Alliance: Void Elf", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49266] = { ["id"] = 49266, ["name"] = "Forge of Aeons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 9359, ["mapID"] = 940, ["storyline"] = { 49266, 49698, 50071 }, ["series"] = { 49698 }, ["description"] = "The Lightforged have long stood as a beacon of hope against the Legion. But few truly know what it takes to become the embodiment of Light's wrath. These few champions among the Army of the Light are ready to undergo their final trial. Will you do us the honor of bearing witness?", ["objectivesText"] = "Bear witness to the ritual of the Lightforged. Progress: It fills me with hope that we have found allies such as you.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 155656, 156486 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9359 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1860, ["db2PoiUiMapID"] = 940, ["questLines"] = { { ["id"] = 533, ["name"] = "Allies of the Alliance: Lightforged Draenei", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49354] = { ["id"] = 49354, ["name"] = "Remember the Sunwell", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 49354, 49613, 49614, 49973 }, ["series"] = { 49613, 49614 }, ["description"] = "The Regent Lord intends to show First Arcanist Thalyssra our Sunwell. I do not know if he will allow Alleria Windrunner to attend the meeting, but we are invited to join them.", ["objectivesText"] = "Complete the scenario, \"Remember the Sunwell.\"", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 130133, ["x"] = 0.581, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 130133, ["x"] = 0.581, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.581, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 531, ["name"] = "Allies of the Horde: Nightborne", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49532] = { ["id"] = 49532, ["name"] = "Warchief's Command: Shadowmoon Valley!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["series"] = { 10595, 10596, 10597, 10598, 10599, 10600, 11048 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Blood Guard Gulmok at Shadowmoon Valley in Outland. The Burning Legion is attempting to lay siege to Shadowmoon Village, but our elite Kor'kron force is showing them what it means to fight against the Horde. Crush the Legion. For the Horde!", ["objectivesText"] = "Speak to Blood Guard Gulmok at Shadowmoon Valley in Outland.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 21359, ["x"] = 0.304, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 104, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49533] = { ["id"] = 49533, ["name"] = "Warchief's Command: Howling Fjord!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 11167, 11168, 11170 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Apothecary Lysander in Howling Fjord . The Forsaken have established a stronghold on the eastern shores of Northrend. Now is the time to strike at the Scourge with our military might and a new plague that is being developed by the Royal Apothecary Society. For the Horde!", ["objectivesText"] = "Speak to Apothecary Lysander in Howling Fjord .", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 24126, ["x"] = 0.785, ["y"] = 0.29 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.29 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 117, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49534] = { ["id"] = 49534, ["name"] = "Warchief's Command: Zul'Drak!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12630, 12883, 12884, 12902, 39208, 49552 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Crusader Lord Lantinga in Zul'Drak . The Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army. Assist the Argent Crusade and the Ebon Blade in stopping this threat. For the Horde!", ["objectivesText"] = "Speak with Crusader Lord Lantinga in Zul'Drak .", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 29687, ["x"] = 0.32, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 121, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49535] = { ["id"] = 49535, ["name"] = "Warchief's Command: Sholazar Basin!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 125, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12489, 12521, 39209, 39212, 49553 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Archmage Pentarus in Dalaran over Crystalsong Forest. Hemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin , but has gone missing. We do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King. For the Horde!", ["objectivesText"] = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 125, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49536] = { ["id"] = 49536, ["name"] = "Warchief's Command: Storm Peaks!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 126, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 12853, 49554 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Rin Duoctane in Dalaran over Crystalsong Forest. The goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers. Speak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King. For the Horde!", ["objectivesText"] = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 126, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49537] = { ["id"] = 49537, ["name"] = "Warchief's Command: Icecrown!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 125, ["storyline"] = { 28711, 39203, 39206, 49533, 49534, 49535, 49536, 49537, 60097, 60963 }, ["series"] = { 13419 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Sky-Reaver Klum in Dalaran over Crystalsong Forest. The Warsong Offensive needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself. It is time to make the Lich King pay for his crimes. For the Horde!", ["objectivesText"] = "Speak to Sky-Reaver Klum in Dalaran over Crystalsong Forest.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 125, ["questLines"] = { { ["id"] = 5578, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49550] = { ["id"] = 49550, ["name"] = "Hero's Call: Shadowmoon Valley!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["series"] = { 10562, 10563, 10564, 10572, 10573, 10582, 11044 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Wing Commander Nuainn in Shadowmoon Valley on Outland. The Burning Legion are laying siege to Wildhammer Stronghold, endagering our people and threatening their lives. We need to reinforce the stronghold and stop the Burning Legion's relentless assault! Glory to the Alliance!", ["objectivesText"] = "Speak with Wing Commander Nuainn in Shadowmoon Valley on Outland.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 21357, ["x"] = 0.395, ["y"] = 0.536 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.536 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 104, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 8, ["flags"] = 0 } } },
