[49552] = { ["id"] = 49552, ["name"] = "Hero's Call: Zul'Drak!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12630, 12883, 12884, 12902, 39208, 49534 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Crusader Lord Lantinga in Zul'Drak . The Scourge is massacring the local population in Zul'Drak and converting them over to be part of the Scourge army. Assist the Argent Crusade and the Ebon Blade in stopping this threat. Glory to the Alliance!", ["objectivesText"] = "Speak with Crusader Lord Lantinga in Zul'Drak .", ["rewardGold"] = 10500, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 29687, ["x"] = 0.32, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 121, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49553] = { ["id"] = 49553, ["name"] = "Hero's Call: Sholazar Basin!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 125, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12489, 12521, 39209, 39212, 49535 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Archmage Pentarus in Dalaran over Crystalsong Forest. Hemet Nesingwary, along with his expeditionary force, was sent to explore Sholazar Basin , but has gone missing. We do not know much about the lush landscape of Sholazar, but there might be secrets in the basin that can give us an advantage in our fight against the Lich King. Glory to the Alliance!", ["objectivesText"] = "Speak with Archmage Pentarus in Dalaran over Crystalsong Forest.", ["rewardGold"] = 10500, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 125, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49554] = { ["id"] = 49554, ["name"] = "Hero's Call: Storm Peaks!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 126, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 12853, 49536 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest. The goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers. Speak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King. Glory to the Alliance!", ["objectivesText"] = "Speak with Rin Duoctane in Dalaran over Crystalsong Forest.", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 126, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49555] = { ["id"] = 49555, ["name"] = "Hero's Call: Icecrown!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4395, ["mapID"] = 125, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["series"] = { 13418 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Officer Van Rossem in Dalaran over Crystalsong Forest. The Valiance Expedition needs more adventurers to bolster their assault on assault Icecrown Citadel and Arthas himself. It is time to make the Lich King pay for his crimes. Glory to the Alliance!", ["objectivesText"] = "Speak with Officer Van Rossem in Dalaran over Crystalsong Forest.", ["rewardGold"] = 10500, ["rewardXP"] = 430, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 125, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49613] = { ["id"] = 49613, ["name"] = "Silvermoon City", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 49354, 49613, 49614, 49973 }, ["series"] = { 49354, 49614 }, ["description"] = "The nightborne have been isolated from the world for thousands of years. Now that they have reemerged, it is up to us to guide them along the right path. Regent Lord Theron has extended an invitation to the nightborne to meet with us in Silvermoon. Come, <name>, let us travel to Silvermoon with Thalyssra.", ["objectivesText"] = "Meet with Lady Liadrin in Silvermoon City.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 6948 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 131478, ["x"] = 0.658, ["y"] = 0.642 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 130133, ["x"] = 0.581, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.642 }, ["mapCandidates"] = { ["npc"] = { 110, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 531, ["name"] = "Allies of the Horde: Nightborne", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49614] = { ["id"] = 49614, ["name"] = "The Nightborne", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 110, ["storyline"] = { 49354, 49613, 49614, 49973 }, ["series"] = { 49354, 49613 }, ["description"] = "The Warchief will be pleased with our success. Thalyssra and her nightborne will prove strong allies, I am sure.", ["objectivesText"] = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 156487 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 130133, ["x"] = 0.581, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 126065, ["x"] = 0.378, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.581, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 85, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 531, ["name"] = "Allies of the Horde: Nightborne", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49698] = { ["id"] = 49698, ["name"] = "The Lightforged", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 49266, 49698, 50071 }, ["series"] = { 49266 }, ["description"] = "Do you wish to hear how the Lightforged draenei joined the Alliance? It might be one of my favorite stories. Most likely since it involves seeing our beautiful world from space! It all began when High Exarch Turalyon invited members of the Alliance onto the Vindicaar...", ["objectivesText"] = "Travel to the Vindicaar. Progress: This ritual has never been witnessed by an outsider.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 155656, 156486, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 126319, ["x"] = 0.521, ["y"] = 0.135 }, { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.135 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1860, ["db2PoiUiMapID"] = 940, ["questLines"] = { { ["id"] = 533, ["name"] = "Allies of the Alliance: Lightforged Draenei", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49756] = { ["id"] = 49756, ["name"] = "Dark Forces", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 48067, 48079 }, ["description"] = "The Old Gods have inflicted one of their faceless ones upon Thunder Bluff. The fiend desecrates my people's city! We must fight together to rid this place of such filth. I believe that destroying this herald will drive our enemies from Mulgore. May our weapons strike true, <name>!", ["objectivesText"] = "Defeat Qy'telek , Herald of Uul'gyneth Progress: This herald of the Old Gods must be stopped.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 17, ["flags"] = 0 } } },
[49812] = { ["id"] = 49812, ["name"] = "Delas in Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 627, ["storyline"] = { 43486, 43487, 43488, 43489, 43490, 43491, 43492, 43493, 43535, 43540, 43541, 43933, 43934, 49812 }, ["series"] = { 43486, 43487 }, ["description"] = "Delas Moonfang needs our help. In-turn, she will aid us to decrypt the Codex of Command. I implore you to seek her out as soon as possible. She is known to enjoy the memorial dedicated to the fallen, great leader of the Kirin Tor, Antonidas.", ["objectivesText"] = "Find Delas Moonfang at the Antonidas Memorial in Dalaran.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5826, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 5826, ["name"] = "Path of the Light II", ["orderIndex"] = 3, ["flags"] = 1 } } },
[49973] = { ["id"] = 49973, ["name"] = "Thalyssra's Estate", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49354, 49613, 49614, 49973 }, ["description"] = "Would you like to hear how the nightborne came to join the Horde? We earned their trust when we aided them in liberating Suramar from the tyranny of Grand Magistrix Elisande and the Burning Legion. Lor'themar Theron later asked them to join him in Quel'Thalas. Lady Liadrin made the journey to extend the invitation to First Arcanist Thalyssra...", ["objectivesText"] = "Meet with Lady Liadrin at the Estate of the First Arcanist in Suramar.", ["rewardGold"] = 169800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 126062, ["x"] = 0.38, ["y"] = 0.805 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 131478, ["x"] = 0.658, ["y"] = 0.642 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 85, 680 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 531, ["name"] = "Allies of the Horde: Nightborne", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50046] = { ["id"] = 50046, ["name"] = "It's a Sabotage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "The Horde has wasted no time in shamelessly extracting this mysterious ore from the great wound. Luckily for us, goblin engineering is not nearly as sophisticated as what we create in Gnomeregan! All it takes is a little bit of old fashioned dynamite to completely disable a goblin shredder. What unsophisticated machinery! Take these dynamite bundles and plant them on the inactive shredders around the mining camp. It'll take those greedy goblins weeks to get back up and running again!", ["objectivesText"] = "Plant 10 dynamite bundles .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 29978, 29979, 29980, 39811, 39873, 39875, 39877, 53225, 53253, 53255, 57451, 57452, 57453, 131384, 131454, 140255, 220118, 223440, 223442, 223451, 223467, 237812 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130030, ["x"] = 0.694, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130030, ["x"] = 0.694, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50047] = { ["id"] = 50047, ["name"] = "Free Samples", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "The crown has ordered SI:7 to infiltrate the goblin mining operation and collect any information we can find on this mysterious new substance. My agents have infiltrated the camp, but the clock is ticking and we need to get our hands on some extracted ore samples fast. In other words, I need someone who can take the direct approach. Someone who can handle a fight against overwhelming odds and come out alive. Take the ore samples to Khargus Stonemantle for analysis when you return.", ["objectivesText"] = "Collect 8 Mysterious Ore samples. Progress: What have ye got for me?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 156711 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132192, ["x"] = 0.694, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50049] = { ["id"] = 50049, ["name"] = "The Speaker's Perspective", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "Sargeras has left a scar upon our world, <name>. A scar that will not soon heal... It appears that the scars between the Alliance and Horde have yet to heal as well. Too many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more. I have a request for you before I go. Take this letter to Magni Bronzebeard . He is in Silithus seeking a way to heal the wound. The letter contains information that may prove valuable to him.", ["objectivesText"] = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130032, ["x"] = 0.69, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 22, ["flags"] = 0 } } },
[50052] = { ["id"] = 50052, ["name"] = "No Spies Allowed", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "Hey <name>, I'm glad you're here. I'm in way over my head! Killer bugs, a strange substance... that GIANT sword sticking outta the ground... I don't have a good feelin' about this place! To make matters worse, I've been gettin' reports of Alliance spies snoopin' around the camp! Look kid, the Dark Lady has plans for this mysterious ore and I ain't going to be the one to dissapoint her, know what I mean? Get over to the mining camp and take out those SI:7 spies before they ruin the whole operation!", ["objectivesText"] = "Kill 10 SI:7 Operatives in Silithus.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132045, ["x"] = 0.662, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132045, ["x"] = 0.662, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50053] = { ["id"] = 50053, ["name"] = "Lazy Prospectors!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "I've been around long enough to know you can never trust a goblin with an orc's work. Gallywix and his cartel may be serving the warchief, but we need to keep a close eye on them if we're going to get anything done! I've already noticed many of the workers loafing about and sleeping on the job. The Horde does not tolerate laziness! Get out there and put those lazy prospectors in their place!", ["objectivesText"] = "Motivate 10 Lazy Prospectors .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 10, ["flags"] = 0 } } },
[50055] = { ["id"] = 50055, ["name"] = "The Speaker's Perspective", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "Sargeras has left a scar upon our world, <name>. A scar that will not soon heal... It appears that the scars between the Alliance and Horde have yet to heal as well. Too many lives have already been lost fighting to save Azeroth from destruction. I will not stay and watch this world lose more. I have a request for you before I go. Take this letter to Magni Bronzebeard . He is in Silithus seeking a way to heal the wound. The letter contains information that may prove valuable to him.", ["objectivesText"] = "Deliver Khadgar's letter to Magni Bronzebeard in Silithus. Progress: What do ye have for me, <class>?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130033, ["x"] = 0.664, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 23, ["flags"] = 0 } } },
[50071] = { ["id"] = 50071, ["name"] = "For the Light!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 49266, 49698, 50071 }, ["description"] = "The Lightforged Draenei will be happy to join the Alliance. Our cause is now yours, <name>. Let us return to Stormwind. Captain Fareeya will speak with our people.", ["objectivesText"] = "Return to Stormwind and speak with Aysa Cloudsinger to hear the end of his tale.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 155656, 156486 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 126301, ["x"] = 0.521, ["y"] = 0.135 }, { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.135 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1860, ["db2PoiUiMapID"] = 940, ["questLines"] = { { ["id"] = 533, ["name"] = "Allies of the Alliance: Lightforged Draenei", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50130] = { ["id"] = 50130, ["name"] = "A Friendly Gesture", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 9701, 9702, 9708, 9709, 9716, 9718, 9720, 9724, 9726, 9728, 9729, 9731, 9732, 9739, 9743, 9747, 9769, 9770, 9771, 9772, 9773, 9774, 9780, 9781, 9782, 9783, 9786, 9787, 9788, 9790, 9791, 9801, 9803, 9814, 9816, 9820, 9822, 9823, 9830, 9833, 9834, 9835, 9839, 9841, 9842, 9845, 9846, 9847, 9848, 9894, 9896, 9898, 9899, 9901, 9902, 9903, 9904, 9905, 9919, 10096, 10115, 10118, 50130, 50131 }, ["description"] = "Life in the marsh has not been easy, <name>. We want to live in harmony with those that call it home, but our enemies out here threaten our existence. Work with us. Help the people of Sporeggar thrive.", ["objectivesText"] = "Reach Friendly with Sporeggar .", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17924, ["x"] = 0.196, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17924, ["x"] = 0.196, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.196, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 102, ["questLines"] = { { ["id"] = 463, ["name"] = "Zangarmarsh", ["orderIndex"] = 39, ["flags"] = 0 } } },
[50131] = { ["id"] = 50131, ["name"] = "An Outside Perspective", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 9701, 9702, 9708, 9709, 9716, 9718, 9720, 9724, 9726, 9728, 9729, 9731, 9732, 9739, 9743, 9747, 9769, 9770, 9771, 9772, 9773, 9774, 9780, 9781, 9782, 9783, 9786, 9787, 9788, 9790, 9791, 9801, 9803, 9814, 9816, 9820, 9822, 9823, 9830, 9833, 9834, 9835, 9839, 9841, 9842, 9845, 9846, 9847, 9848, 9894, 9896, 9898, 9899, 9901, 9902, 9903, 9904, 9905, 9919, 10096, 10115, 10118, 50130, 50131 }, ["description"] = "Thank you for everything you have done for my people, but they are still scared of outsiders. Fight the bog lords and rescue the spore sacs in the Spawning Glen. The future of my people is at stake!", ["objectivesText"] = "Reach Neutral with Sporeggar.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17923, ["x"] = 0.1905, ["y"] = 0.633 } }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17923, ["x"] = 0.1905, ["y"] = 0.633 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.1905, ["y"] = 0.633 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 102, ["questLines"] = { { ["id"] = 463, ["name"] = "Zangarmarsh", ["orderIndex"] = 37, ["flags"] = 0 } } },
[50226] = { ["id"] = 50226, ["name"] = "The Source of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "Although the silithid disappeared for a time immediately following the destruction of Silithus, they have recently returned from beneath the ground. These new silithid seem stronger than before! My hypothesis is that the silithid are feeding on some kind of power source beneath the blade of Sargeras. I've been tasked with studying the effects that this mysterious power is having on the silithid hives. Bring me as many intact silithid brains as you can carry and I'll begin the research!", ["objectivesText"] = "Collect 10 Silithid Brains . Progress: Do you have the brains?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 20384, 20402, 66908, 66909, 66910, 156794, 211279, 237812 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132606, ["x"] = 0.694, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132606, ["x"] = 0.694, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 14, ["flags"] = 0 } } },
[50227] = { ["id"] = 50227, ["name"] = "Larvae By The Dozen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "How did the silithid survive the blade of Sargeras? I'm perplexed! I've never encountered a species that can adapt to changes in the environment as quickly as the silithid can. The larvae, or broodlings as they are often called, can evolve into a variety of silithid creature types based on the needs of the hive. Is it the hive mind that signals the evolutionary development of the larvae, or is some environmental factor at play? Science must find the answer!", ["objectivesText"] = "Collect 12 Silithid Broodlings . Progress: Do you have the silithid larvae?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 156795 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132606, ["x"] = 0.694, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132606, ["x"] = 0.694, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 16, ["flags"] = 0 } } },
[50228] = { ["id"] = 50228, ["name"] = "The Twilight Survivor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "Silithus used to be overrun with members of the Twilight's Hammer. The cult was presumed to be exterminated, but it has always survived in the shadows. Their numbers have dwindled, but the cult remains no less fanatical than at their peak. Most of the cultists here were destroyed by Sargeras in the attack, but a few still remain. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus. We cannot let Michiel rally the remaining survivors to action. He must be stopped!", ["objectivesText"] = "Retrieve Michiel Voidstrider's head . Progress: We cannot allow the Twilight's Hammer to regain their foothold in Silithus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 156796 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 18, ["flags"] = 0 } } },
[50230] = { ["id"] = 50230, ["name"] = "The Source of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "The silithid are all riled up and stronger than ever! My guess is that they are feeding off of some kind of power beneath the ground. Probably near the blade of Sargeras! I've been ordered to study the effects that this mysterious power is having on the sillithid. Bring me as many intact silithid brains as you can carry and I'll begin the research!", ["objectivesText"] = "Collect 10 Silithid Brains . Progress: Hey kid! You got the stuff?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 20384, 20402, 66908, 66909, 66910, 156794, 211279, 237812 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132040, ["x"] = 0.668, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132040, ["x"] = 0.668, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 15, ["flags"] = 0 } } },
[50231] = { ["id"] = 50231, ["name"] = "Larvae By The Dozen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "How did the silithid survive the blade of Sargeras?! I've never encountered a species that can adapt to changes in the environment as quickly as the silithid! There's gotta be a way to tame these suckers! Harness their evolutionary biology for our profit! We gotta start training 'em young! Forget about the old crusty adults, we need babies! Steal me as many of the silithid larvae as you can carry, and I'll find a way to train 'em!", ["objectivesText"] = "Collect 12 Silithid Broodlings . Progress: Do you have the silithid larvae?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 156795 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132040, ["x"] = 0.668, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132040, ["x"] = 0.668, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 17, ["flags"] = 0 } } },
[50232] = { ["id"] = 50232, ["name"] = "The Twilight Survivor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "This land was once overrun with members of the Twilight's Hammer. The cult was presumed to be exterminated, but darkness always survives in the shadows. Most of the cultists were destroyed by Sargeras in the attack, but a few yet live. Their leader, Michiel Voidstrider has been emboldened by the destruction of Silithus. We cannot let this fanatic rally the remaining survivors to action! Bring me his head!", ["objectivesText"] = "Retrieve Michiel Voidstrider's head . Progress: We cannot allow the Twilight's Hammer to regain their foothold in Silithus!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 156796 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 19, ["flags"] = 0 } } },
[50247] = { ["id"] = 50247, ["name"] = "The Mail Must Flow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 50247 }, ["description"] = "Due to all of the recent shenanigans, I'm running short on mailementals to sort letters. It's a simple job, really - just toss the letter into the proper portal, where it will be whisked away to the far corners of Azeroth and beyond. I like to make a little game out of it. How many can you sort in one minute?", ["objectivesText"] = "Help the Postmaster sort at least 15 letters within the time limit.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 7912, 45693, 122340, 134859, 135463, 156721, 156833, 156836 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[50358] = { ["id"] = 50358, ["name"] = "Desert Research", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "The dark blade of Sargeras has cast a shadow of destruction over this land. It seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning. If it were up to me, I'd burn those wretched hives once and for all! However, it is not up to me. The Dark Lady wants the surviving silithid dissected and studied. Pixni Rustbomb is conducting the research and is in need of a \"collector.\"", ["objectivesText"] = "Speak with Pixni Rustbomb .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132040, ["x"] = 0.668, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 11, ["flags"] = 0 } } },
[50360] = { ["id"] = 50360, ["name"] = "Khadgar's Request", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "Archmage Khadgar arrived while you were away. It seems that he is here to speak with you, <name>. Hurry and see what it is that he wants. I want him gone as soon as possible. The last thing we need is a human nosing around in Horde business!", ["objectivesText"] = "Speak with Archmage Khadgar .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130033, ["x"] = 0.664, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 21, ["flags"] = 0 } } },
[50364] = { ["id"] = 50364, ["name"] = "The Blood of Azeroth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "Do the leaders of the Alliance and Horde even know what they're fightin' over? This substance that is risin' up from the wound is the lifeblood of Azeroth! We need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die! I trust ye, <name>, and I know that yer voice carries great weight among the Horde. Ye must reason with 'em ta stop this madness! 'Tis the only hope our world has...", ["objectivesText"] = "Deliver Magni Bronzebeard 's message.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 25, ["flags"] = 0 } } },
[50372] = { ["id"] = 50372, ["name"] = "Desert Research", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "The dark blade of Sargeras has cast a shadow of destruction over this land. It seemed that the silithid hives were destroyed in the attack, but I have received reports that the silithid are returning. We need to find out how the silithid avoided destruction and what effect the blade is having on their hives. The crown wants the surviving silithid dissected and studied. Tammy Tinkspinner is conducting the research and is in need of a \"collector.\"", ["objectivesText"] = "Speak with Tammy Tinkspinner .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132606, ["x"] = 0.694, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50373] = { ["id"] = 50373, ["name"] = "A Recent Arrival", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "The situation in Silithus appears to be gaining more attention. Archmage Khadgar just arrived while you were away. It seems that he is here to speak with you, <name>. It appears urgent. I would speak with him as soon as possible.", ["objectivesText"] = "Speak with Archmage Khadgar .", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130032, ["x"] = 0.69, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 20, ["flags"] = 0 } } },
[50374] = { ["id"] = 50374, ["name"] = "The Blood of Azeroth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "Do the leaders of the Alliance and Horde even know what they're fightin' over? This substance that is risin' up from the wound is the lifeblood of Azeroth! We need ta heal the wound, not exploit it fer power! Azeroth is the only home we've got. We cannot allow her ta die! I trust ye, <name>, and I know that yer voice carries great weight among the Alliance. Ye must reason with 'em ta stop this madness! 'Tis the only hope our world has...", ["objectivesText"] = "Deliver Magni Bronzebeard 's message.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 24, ["flags"] = 0 } } },
})
